__d(function(n,o,t,_,c,d,e){c.exports={"1:1":"\u0623\u0628\u062a\u062f\u0626 \u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0642\u0631\u0622\u0646 \u0628\u0627\u0633\u0645 \u0627\u0644\u0644\u0647 \u0645\u0633\u062a\u0639\u064a\u0646\u0627 \u0628\u0647\u060c (\u0627\u0644\u0644\u0647\u0650) \u0639\u0644\u0645 \u0639\u0644\u0649 \u0627\u0644\u0631\u0628 -\u062a\u0628\u0627\u0631\u0643 \u0648\u062a\u0639\u0627\u0644\u0649- \u0627\u0644\u0645\u0639\u0628\u0648\u062f \u0628\u062d\u0642 \u062f\u0648\u0646 \u0633\u0648\u0627\u0647\u060c \u0648\u0647\u0648 \u0623\u062e\u0635 \u0623\u0633\u0645\u0627\u0621 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0644\u0627 \u064a\u0633\u0645\u0649 \u0628\u0647 \u063a\u064a\u0631\u0647 \u0633\u0628\u062d\u0627\u0646\u0647. (\u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0646\u0650) \u0630\u064a \u0627\u0644\u0631\u062d\u0645\u0629 \u0627\u0644\u0639\u0627\u0645\u0629 \u0627\u0644\u0630\u064a \u0648\u0633\u0639\u062a \u0631\u062d\u0645\u062a\u0647 \u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u0644\u0642\u060c (\u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650) \u0628\u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0648\u0647\u0645\u0627 \u0627\u0633\u0645\u0627\u0646 \u0645\u0646 \u0623\u0633\u0645\u0627\u0626\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u064a\u062a\u0636\u0645\u0646\u0627\u0646 \u0625\u062b\u0628\u0627\u062a \u0635\u0641\u0629 \u0627\u0644\u0631\u062d\u0645\u0629 \u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0643\u0645\u0627 \u064a\u0644\u064a\u0642 \u0628\u062c\u0644\u0627\u0644\u0647.","1:2":"\u0627\u0644\u062b\u0646\u0627\u0621 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0628\u0635\u0641\u0627\u062a\u0647 \u0627\u0644\u062a\u064a \u0643\u0644\u0651\u064f\u0647\u0627 \u0623\u0648\u0635\u0627\u0641 \u0643\u0645\u0627\u0644\u060c \u0648\u0628\u0646\u0639\u0645\u0647 \u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0648\u0627\u0644\u0628\u0627\u0637\u0646\u0629\u060c \u0627\u0644\u062f\u064a\u0646\u064a\u0629 \u0648\u0627\u0644\u062f\u0646\u064a\u0648\u064a\u0629\u060c \u0648\u0641\u064a \u0636\u0645\u0646\u0647 \u0623\u064e\u0645\u0652\u0631\u064c \u0644\u0639\u0628\u0627\u062f\u0647 \u0623\u0646 \u064a\u062d\u0645\u062f\u0648\u0647\u060c \u0641\u0647\u0648 \u0627\u0644\u0645\u0633\u062a\u062d\u0642 \u0644\u0647 \u0648\u062d\u062f\u0647\u060c \u0648\u0647\u0648 \u0633\u0628\u062d\u0627\u0646\u0647 \u0627\u0644\u0645\u0646\u0634\u0626 \u0644\u0644\u062e\u0644\u0642\u060c \u0627\u0644\u0642\u0627\u0626\u0645 \u0628\u0623\u0645\u0648\u0631\u0647\u0645\u060c \u0627\u0644\u0645\u0631\u0628\u064a \u0644\u062c\u0645\u064a\u0639 \u062e\u0644\u0642\u0647 \u0628\u0646\u0639\u0645\u0647\u060c \u0648\u0644\u0623\u0648\u0644\u064a\u0627\u0626\u0647 \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0635\u0627\u0644\u062d.","1:3":"(\u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0646\u0650) \u0630\u064a \u0627\u0644\u0631\u062d\u0645\u0629 \u0627\u0644\u0639\u0627\u0645\u0629 \u0627\u0644\u0630\u064a \u0648\u0633\u0639\u062a \u0631\u062d\u0645\u062a\u0647 \u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u0644\u0642\u060c (\u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u0650) \u060c \u0628\u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0648\u0647\u0645\u0627 \u0627\u0633\u0645\u0627\u0646 \u0645\u0646 \u0623\u0633\u0645\u0627\u0621 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649.","1:4":"\u0648\u0647\u0648 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062d\u062f\u0647 \u0645\u0627\u0644\u0643 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u0648\u0647\u0648 \u064a\u0648\u0645 \u0627\u0644\u062c\u0632\u0627\u0621 \u0639\u0644\u0649 \u0627\u0644\u0623\u0639\u0645\u0627\u0644. \u0648\u0641\u064a \u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0645\u0633\u0644\u0645 \u0644\u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0629 \u0641\u064a \u0643\u0644 \u0631\u0643\u0639\u0629 \u0645\u0646 \u0635\u0644\u0648\u0627\u062a\u0647 \u062a\u0630\u0643\u064a\u0631 \u0644\u0647 \u0628\u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0622\u062e\u0631\u060c \u0648\u062d\u062b\u0651\u064c \u0644\u0647 \u0639\u0644\u0649 \u0627\u0644\u0627\u0633\u062a\u0639\u062f\u0627\u062f \u0628\u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0635\u0627\u0644\u062d\u060c \u0648\u0627\u0644\u0643\u0641 \u0639\u0646 \u0627\u0644\u0645\u0639\u0627\u0635\u064a \u0648\u0627\u0644\u0633\u064a\u0626\u0627\u062a.","1:5":"\u0625\u0646\u0627 \u0646\u062e\u0635\u0643 \u0648\u062d\u062f\u0643 \u0628\u0627\u0644\u0639\u0628\u0627\u062f\u0629\u060c \u0648\u0646\u0633\u062a\u0639\u064a\u0646 \u0628\u0643 \u0648\u062d\u062f\u0643 \u0641\u064a \u062c\u0645\u064a\u0639 \u0623\u0645\u0648\u0631\u0646\u0627\u060c \u0641\u0627\u0644\u0623\u0645\u0631 \u0643\u0644\u0647 \u0628\u064a\u062f\u0643\u060c \u0644\u0627 \u064a\u0645\u0644\u0643 \u0645\u0646\u0647 \u0623\u062d\u062f \u0645\u062b\u0642\u0627\u0644 \u0630\u0631\u0629. \u0648\u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0629 \u062f\u0644\u064a\u0644 \u0639\u0644\u0649 \u0623\u0646 \u0627\u0644\u0639\u0628\u062f \u0644\u0627 \u064a\u062c\u0648\u0632 \u0644\u0647 \u0623\u0646 \u064a\u0635\u0631\u0641 \u0634\u064a\u0626\u064b\u0627 \u0645\u0646 \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u0643\u0627\u0644\u062f\u0639\u0627\u0621 \u0648\u0627\u0644\u0627\u0633\u062a\u063a\u0627\u062b\u0629 \u0648\u0627\u0644\u0630\u0628\u062d \u0648\u0627\u0644\u0637\u0648\u0627\u0641 \u0625\u0644\u0627 \u0644\u0644\u0647 \u0648\u062d\u062f\u0647\u060c \u0648\u0641\u064a\u0647\u0627 \u0634\u0641\u0627\u0621 \u0627\u0644\u0642\u0644\u0648\u0628 \u0645\u0646 \u062f\u0627\u0621 \u0627\u0644\u062a\u0639\u0644\u0642 \u0628\u063a\u064a\u0631 \u0627\u0644\u0644\u0647\u060c \u0648\u0645\u0646 \u0623\u0645\u0631\u0627\u0636 \u0627\u0644\u0631\u064a\u0627\u0621 \u0648\u0627\u0644\u0639\u062c\u0628\u060c \u0648\u0627\u0644\u0643\u0628\u0631\u064a\u0627\u0621.","1:6":"\u062f\u064f\u0644\u0651\u064e\u0646\u0627\u060c \u0648\u0623\u0631\u0634\u062f\u0646\u0627\u060c \u0648\u0648\u0641\u0642\u0646\u0627 \u0625\u0644\u0649 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645\u060c \u0648\u062b\u0628\u062a\u0646\u0627 \u0639\u0644\u064a\u0647 \u062d\u062a\u0649 \u0646\u0644\u0642\u0627\u0643\u060c \u0648\u0647\u0648 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0627\u0644\u0630\u064a \u0647\u0648 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0648\u0627\u0636\u062d \u0627\u0644\u0645\u0648\u0635\u0644 \u0625\u0644\u0649 \u0631\u0636\u0648\u0627\u0646 \u0627\u0644\u0644\u0647 \u0648\u0625\u0644\u0649 \u062c\u0646\u062a\u0647\u060c \u0627\u0644\u0630\u064a \u062f\u0644\u0651 \u0639\u0644\u064a\u0647 \u062e\u0627\u062a\u0645 \u0631\u0633\u0644\u0647 \u0648\u0623\u0646\u0628\u064a\u0627\u0626\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0641\u0644\u0627 \u0633\u0628\u064a\u0644 \u0625\u0644\u0649 \u0633\u0639\u0627\u062f\u0629 \u0627\u0644\u0639\u0628\u062f \u0625\u0644\u0627 \u0628\u0627\u0644\u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0639\u0644\u064a\u0647.","1:7":"\u0637\u0631\u064a\u0642 \u0627\u0644\u0630\u064a\u0646 \u0623\u0646\u0639\u0645\u062a \u0639\u0644\u064a\u0647\u0645 \u0645\u0646 \u0627\u0644\u0646\u0628\u064a\u064a\u0646 \u0648\u0627\u0644\u0635\u062f\u0651\u0650\u064a\u0642\u064a\u0646 \u0648\u0627\u0644\u0634\u0647\u062f\u0627\u0621 \u0648\u0627\u0644\u0635\u0627\u0644\u062d\u064a\u0646\u060c \u0641\u0647\u0645 \u0623\u0647\u0644 \u0627\u0644\u0647\u062f\u0627\u064a\u0629 \u0648\u0627\u0644\u0627\u0633\u062a\u0642\u0627\u0645\u0629\u060c \u0648\u0644\u0627 \u062a\u062c\u0639\u0644\u0646\u0627 \u0645\u0645\u0646 \u0633\u0644\u0643 \u0637\u0631\u064a\u0642 \u0627\u0644\u0645\u063a\u0636\u0648\u0628 \u0639\u0644\u064a\u0647\u0645\u060c \u0627\u0644\u0630\u064a\u0646 \u0639\u0631\u0641\u0648\u0627 \u0627\u0644\u062d\u0642 \u0648\u0644\u0645 \u064a\u0639\u0645\u0644\u0648\u0627 \u0628\u0647\u060c \u0648\u0647\u0645 \u0627\u0644\u064a\u0647\u0648\u062f\u060c \u0648\u0645\u0646 \u0643\u0627\u0646 \u0639\u0644\u0649 \u0634\u0627\u0643\u0644\u062a\u0647\u0645\u060c \u0648\u0627\u0644\u0636\u0627\u0644\u064a\u0646\u060c \u0648\u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u0644\u0645 \u064a\u0647\u062a\u062f\u0648\u0627 \u0639\u0646 \u062c\u0647\u0644 \u0645\u0646\u0647\u0645\u060c \u0641\u0636\u0644\u0648\u0627 \u0627\u0644\u0637\u0631\u064a\u0642\u060c \u0648\u0647\u0645 \u0627\u0644\u0646\u0635\u0627\u0631\u0649\u060c \u0648\u0645\u0646 \u0627\u062a\u0628\u0639 \u0633\u0646\u062a\u0647\u0645. \u0648\u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062f\u0639\u0627\u0621 \u0634\u0641\u0627\u0621 \u0644\u0642\u0644\u0628 \u0627\u0644\u0645\u0633\u0644\u0645 \u0645\u0646 \u0645\u0631\u0636 \u0627\u0644\u062c\u062d\u0648\u062f \u0648\u0627\u0644\u062c\u0647\u0644 \u0648\u0627\u0644\u0636\u0644\u0627\u0644\u060c \u0648\u062f\u0644\u0627\u0644\u0629 \u0639\u0644\u0649 \u0623\u0646 \u0623\u0639\u0638\u0645 \u0646\u0639\u0645\u0629 \u0639\u0644\u0649 \u0627\u0644\u0625\u0637\u0644\u0627\u0642 \u0647\u064a \u0646\u0639\u0645\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0641\u0645\u0646 \u0643\u0627\u0646 \u0623\u0639\u0631\u0641 \u0644\u0644\u062d\u0642 \u0648\u0623\u062a\u0628\u0639 \u0644\u0647\u060c \u0643\u0627\u0646 \u0623\u0648\u0644\u0649 \u0628\u0627\u0644\u0635\u0631\u0627\u0637 \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645\u060c \u0648\u0644\u0627 \u0631\u064a\u0628 \u0623\u0646 \u0623\u0635\u062d\u0627\u0628 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0647\u0645 \u0623\u0648\u0644\u0649 \u0627\u0644\u0646\u0627\u0633 \u0628\u0630\u0644\u0643 \u0628\u0639\u062f \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0641\u062f\u0644\u062a \u0627\u0644\u0622\u064a\u0629 \u0639\u0644\u0649 \u0641\u0636\u0644\u0647\u0645\u060c \u0648\u0639\u0638\u064a\u0645 \u0645\u0646\u0632\u0644\u062a\u0647\u0645\u060c \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645.","2:1":"\u0647\u0630\u0647 \u0627\u0644\u062d\u0631\u0648\u0641 \u0648\u063a\u064a\u0631\u0647\u0627 \u0645\u0646 \u0627\u0644\u062d\u0631\u0648\u0641 \u0627\u0644\u0645\u0642\u0637\u0651\u064e\u0639\u0629 \u0641\u064a \u0623\u0648\u0627\u0626\u0644 \u0627\u0644\u0633\u0648\u0631 \u0641\u064a\u0647\u0627 \u0625\u0634\u0627\u0631\u0629 \u0625\u0644\u0649 \u0625\u0639\u062c\u0627\u0632 \u0627\u0644\u0642\u0631\u0622\u0646; \u0641\u0642\u062f \u0648\u0642\u0639 \u0628\u0647 \u062a\u062d\u062f\u064a \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646\u060c \u0641\u0639\u062c\u0632\u0648\u0627 \u0639\u0646 \u0645\u0639\u0627\u0631\u0636\u062a\u0647\u060c \u0648\u0647\u0648 \u0645\u0631\u0643\u0651\u064e\u0628 \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u062d\u0631\u0648\u0641 \u0627\u0644\u062a\u064a \u062a\u062a\u0643\u0648\u0646 \u0645\u0646\u0647\u0627 \u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628. \u0641\u062f\u064e\u0644\u0651\u064e \u0639\u062c\u0632 \u0627\u0644\u0639\u0631\u0628 \u0639\u0646 \u0627\u0644\u0625\u062a\u064a\u0627\u0646 \u0628\u0645\u062b\u0644\u0647 -\u0645\u0639 \u0623\u0646\u0647\u0645 \u0623\u0641\u0635\u062d \u0627\u0644\u0646\u0627\u0633- \u0639\u0644\u0649 \u0623\u0646 \u0627\u0644\u0642\u0631\u0622\u0646 \u0648\u062d\u064a \u0645\u0646 \u0627\u0644\u0644\u0647.","2:2":"\u0630\u0644\u0643 \u0627\u0644\u0642\u0631\u0622\u0646 \u0647\u0648 \u0627\u0644\u0643\u062a\u0627\u0628 \u0627\u0644\u0639\u0638\u064a\u0645 \u0627\u0644\u0630\u064a \u0644\u0627 \u0634\u064e\u0643\u0651\u064e \u0623\u0646\u0647 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647\u060c \u0641\u0644\u0627 \u064a\u0635\u062d \u0623\u0646 \u064a\u0631\u062a\u0627\u0628 \u0641\u064a\u0647 \u0623\u062d\u062f \u0644\u0648\u0636\u0648\u062d\u0647\u060c \u064a\u0646\u062a\u0641\u0639 \u0628\u0647 \u0627\u0644\u0645\u062a\u0642\u0648\u0646 \u0628\u0627\u0644\u0639\u0644\u0645 \u0627\u0644\u0646\u0627\u0641\u0639 \u0648\u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0635\u0627\u0644\u062d \u0648\u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u064a\u062e\u0627\u0641\u0648\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u064a\u062a\u0628\u0639\u0648\u0646 \u0623\u062d\u0643\u0627\u0645\u0647.","2:3":"\u0648\u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u064a\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u0648\u0646 \u0628\u0627\u0644\u063a\u064a\u0628 \u0627\u0644\u0630\u064a \u0644\u0627 \u062a\u062f\u0631\u0643\u0647 \u062d\u0648\u0627\u0633\u0651\u064f\u0647\u0645 \u0648\u0644\u0627 \u0639\u0642\u0648\u0644\u0647\u0645 \u0648\u062d\u062f\u0647\u0627; \u0644\u0623\u0646\u0647 \u0644\u0627 \u064a\u064f\u0639\u0652\u0631\u0641 \u0625\u0644\u0627 \u0628\u0648\u062d\u064a \u0627\u0644\u0644\u0647 \u0625\u0644\u0649 \u0631\u0633\u0644\u0647\u060c \u0645\u062b\u0644 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629\u060c \u0648\u0627\u0644\u062c\u0646\u0629\u060c \u0648\u0627\u0644\u0646\u0627\u0631\u060c \u0648\u063a\u064a\u0631 \u0630\u0644\u0643 \u0645\u0645\u0627 \u0623\u062e\u0628\u0631 \u0627\u0644\u0644\u0647 \u0628\u0647 \u0623\u0648 \u0623\u062e\u0628\u0631 \u0628\u0647 \u0631\u0633\u0648\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c (\u0648\u0627\u0644\u0625\u064a\u0645\u0627\u0646: \u0643\u0644\u0645\u0629 \u062c\u0627\u0645\u0639\u0629 \u0644\u0644\u0625\u0642\u0631\u0627\u0631 \u0628\u0627\u0644\u0644\u0647 \u0648\u0645\u0644\u0627\u0626\u0643\u062a\u0647 \u0648\u0643\u062a\u0628\u0647 \u0648\u0631\u0633\u0644\u0647 \u0648\u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0622\u062e\u0631 \u0648\u0627\u0644\u0642\u062f\u0631 \u062e\u064a\u0631\u0647 \u0648\u0634\u0631\u0647\u060c \u0648\u062a\u0635\u062f\u064a\u0642 \u0627\u0644\u0625\u0642\u0631\u0627\u0631 \u0628\u0627\u0644\u0642\u0648\u0644 \u0648\u0627\u0644\u0639\u0645\u0644 \u0628\u0627\u0644\u0642\u0644\u0628 \u0648\u0627\u0644\u0644\u0633\u0627\u0646 \u0648\u0627\u0644\u062c\u0648\u0627\u0631\u062d) \u0648\u0647\u0645 \u0645\u0639 \u062a\u0635\u062f\u064a\u0642\u0647\u0645 \u0628\u0627\u0644\u063a\u064a\u0628 \u064a\u062d\u0627\u0641\u0638\u0648\u0646 \u0639\u0644\u0649 \u0623\u062f\u0627\u0621 \u0627\u0644\u0635\u0644\u0627\u0629 \u0641\u064a \u0645\u0648\u0627\u0642\u064a\u062a\u0647\u0627 \u0623\u062f\u0627\u0621\u064b \u0635\u062d\u064a\u062d\u064b\u0627 \u0648\u064e\u0641\u0652\u0642 \u0645\u0627 \u0634\u0631\u0639 \u0627\u0644\u0644\u0647 \u0644\u0646\u0628\u064a\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0645\u0645\u0627 \u0623\u0639\u0637\u064a\u0646\u0627\u0647\u0645 \u0645\u0646 \u0627\u0644\u0645\u0627\u0644 \u064a\u062e\u0631\u062c\u0648\u0646 \u0635\u062f\u0642\u0629 \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0627\u0644\u0648\u0627\u062c\u0628\u0629 \u0648\u0627\u0644\u0645\u0633\u062a\u062d\u0628\u0629.","2:4":"\u0648\u0627\u0644\u0630\u064a\u0646 \u064a\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u0648\u0646 \u0628\u0645\u0627 \u0623\u064f\u0646\u0632\u0644 \u0625\u0644\u064a\u0643 \u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644 \u0645\u0646 \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0648\u0628\u0645\u0627 \u0623\u0646\u0632\u0644 \u0625\u0644\u064a\u0643 \u0645\u0646 \u0627\u0644\u062d\u0643\u0645\u0629\u060c \u0648\u0647\u064a \u0627\u0644\u0633\u0646\u0629\u060c \u0648\u0628\u0643\u0644 \u0645\u0627 \u0623\u064f\u0646\u0632\u0644 \u0645\u0650\u0646 \u0642\u0628\u0644\u0643 \u0639\u0644\u0649 \u0627\u0644\u0631\u0633\u0644 \u0645\u0646 \u0643\u062a\u0628\u060c \u0643\u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644 \u0648\u063a\u064a\u0631\u0647\u0645\u0627\u060c \u0648\u064a\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u0648\u0646 \u0628\u062f\u0627\u0631 \u0627\u0644\u062d\u064a\u0627\u0629 \u0628\u0639\u062f \u0627\u0644\u0645\u0648\u062a \u0648\u0645\u0627 \u0641\u064a\u0647\u0627 \u0645\u0646 \u0627\u0644\u062d\u0633\u0627\u0628 \u0648\u0627\u0644\u062c\u0632\u0627\u0621\u060c \u062a\u0635\u062f\u064a\u0642\u0627 \u0628\u0642\u0644\u0648\u0628\u0647\u0645 \u064a\u0638\u0647\u0631 \u0639\u0644\u0649 \u0623\u0644\u0633\u0646\u062a\u0647\u0645 \u0648\u062c\u0648\u0627\u0631\u062d\u0647\u0645 \u0648\u062e\u0635 \u064a\u0648\u0645 \u0627\u0644\u0622\u062e\u0631\u0629 \u0628\u0627\u0644\u0630\u0643\u0631; \u0644\u0623\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0647 \u0645\u0646 \u0623\u0639\u0638\u0645 \u0627\u0644\u0628\u0648\u0627\u0639\u062b \u0639\u0644\u0649 \u0641\u0639\u0644 \u0627\u0644\u0637\u0627\u0639\u0627\u062a\u060c \u0648\u0627\u062c\u062a\u0646\u0627\u0628 \u0627\u0644\u0645\u062d\u0631\u0645\u0627\u062a\u060c \u0648\u0645\u062d\u0627\u0633\u0628\u0629 \u0627\u0644\u0646\u0641\u0633.","2:5":"\u0623\u0635\u062d\u0627\u0628 \u0647\u0630\u0647 \u0627\u0644\u0635\u0641\u0627\u062a \u0639\u0644\u0649 \u0646\u0648\u0631 \u0645\u0646 \u0631\u0628\u0647\u0645 \u0648\u0628\u062a\u0648\u0641\u064a\u0642 \u0645\u0650\u0646 \u062e\u0627\u0644\u0642\u0647\u0645 \u0648\u0647\u0627\u062f\u064a\u0647\u0645\u060c \u0648\u0647\u0645 \u0627\u0644\u0641\u0627\u0626\u0632\u0648\u0646 \u0627\u0644\u0630\u064a\u0646 \u0623\u062f\u0631\u0643\u0648\u0627 \u0645\u0627 \u0637\u0644\u0628\u0648\u0627\u060c \u0648\u0646\u064e\u062c\u064e\u0648\u0627 \u0645\u0646 \u0634\u0631\u0651\u0650 \u0645\u0627 \u0645\u0646\u0647 \u0647\u0631\u0628\u0648\u0627.","2:6":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u062c\u062d\u062f\u0648\u0627 \u0645\u0627 \u0623\u064f\u0646\u0632\u0644 \u0625\u0644\u064a\u0643 \u0645\u0646 \u0631\u0628\u0643 \u0627\u0633\u062a\u0643\u0628\u0627\u0631\u064b\u0627 \u0648\u0637\u063a\u064a\u0627\u0646\u064b\u0627\u060c \u0644\u0646 \u064a\u0642\u0639 \u0645\u0646\u0647\u0645 \u0627\u0644\u0625\u064a\u0645\u0627\u0646\u060c \u0633\u0648\u0627\u0621 \u0623\u062e\u0648\u0651\u064e\u0641\u062a\u0647\u0645 \u0648\u062d\u0630\u0631\u062a\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0645\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647\u060c \u0623\u0645 \u062a\u0631\u0643\u062a \u0630\u0644\u0643\u061b \u0644\u0625\u0635\u0631\u0627\u0631\u0647\u0645 \u0639\u0644\u0649 \u0628\u0627\u0637\u0644\u0647\u0645.","2:7":"\u0637\u0628\u0639 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0642\u0644\u0648\u0628 \u0647\u0624\u0644\u0627\u0621 \u0648\u0639\u0644\u0649 \u0633\u0645\u0639\u0647\u0645\u060c \u0648\u062c\u0639\u0644 \u0639\u0644\u0649 \u0623\u0628\u0635\u0627\u0631\u0647\u0645 \u063a\u0637\u0627\u0621; \u0628\u0633\u0628\u0628 \u0643\u0641\u0631\u0647\u0645 \u0648\u0639\u0646\u0627\u062f\u0647\u0645 \u0645\u0650\u0646 \u0628\u0639\u062f \u0645\u0627 \u062a\u0628\u064a\u0651\u064e\u0646 \u0644\u0647\u0645 \u0627\u0644\u062d\u0642\u060c \u0641\u0644\u0645 \u064a\u0648\u0641\u0642\u0647\u0645 \u0644\u0644\u0647\u062f\u0649\u060c \u0648\u0644\u0647\u0645 \u0639\u0630\u0627\u0628 \u0634\u062f\u064a\u062f \u0641\u064a \u0646\u0627\u0631 \u062c\u0647\u0646\u0645.","2:8":"\u0648\u0645\u0646 \u0627\u0644\u0646\u0627\u0633 \u0641\u0631\u064a\u0642 \u064a\u062a\u0631\u062f\u062f \u0645\u062a\u062d\u064a\u0651\u0650\u0631\u064b\u0627 \u0628\u064a\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0648\u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646\u060c \u0648\u0647\u0645 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u0642\u0648\u0644\u0648\u0646 \u0628\u0623\u0644\u0633\u0646\u062a\u0647\u0645: \u0635\u062f\u0651\u064e\u0642\u0652\u0646\u064e\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0628\u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0622\u062e\u0631\u060c \u0648\u0647\u0645 \u0641\u064a \u0628\u0627\u0637\u0646\u0647\u0645 \u0643\u0627\u0630\u0628\u0648\u0646 \u0644\u0645 \u064a\u0624\u0645\u0646\u0648\u0627.","2:9":"\u064a\u0639\u062a\u0642\u062f\u0648\u0646 \u0628\u062c\u0647\u0644\u0647\u0645 \u0623\u0646\u0647\u0645 \u064a\u062e\u0627\u062f\u0639\u0648\u0646 \u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0628\u0625\u0638\u0647\u0627\u0631\u0647\u0645 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0625\u0636\u0645\u0627\u0631\u0647\u0645 \u0627\u0644\u0643\u0641\u0631\u060c \u0648\u0645\u0627 \u064a\u062e\u062f\u0639\u0648\u0646 \u0625\u0644\u0627 \u0623\u0646\u0641\u0633\u0647\u0645; \u0644\u0623\u0646 \u0639\u0627\u0642\u0628\u0629 \u062e\u062f\u0627\u0639\u0647\u0645 \u062a\u0639\u0648\u062f \u0639\u0644\u064a\u0647\u0645. \u0648\u0645\u0650\u0646 \u0641\u0631\u0637 \u062c\u0647\u0644\u0647\u0645 \u0644\u0627 \u064a\u064f\u062d\u0650\u0633\u0651\u064f\u0648\u0646 \u0628\u0630\u0644\u0643; \u0644\u0641\u0633\u0627\u062f \u0642\u0644\u0648\u0628\u0647\u0645.","2:10":"\u0641\u064a \u0642\u0644\u0648\u0628\u0647\u0645 \u0634\u0643\u0651\u064c \u0648\u0641\u0633\u0627\u062f \u0641\u0627\u0628\u0652\u062a\u064f\u0644\u0648\u0627 \u0628\u0627\u0644\u0645\u0639\u0627\u0635\u064a \u0627\u0644\u0645\u0648\u062c\u0628\u0629 \u0644\u0639\u0642\u0648\u0628\u062a\u0647\u0645\u060c \u0641\u0632\u0627\u062f\u0647\u0645 \u0627\u0644\u0644\u0647 \u0634\u0643\u064b\u0627\u060c \u0648\u0644\u0647\u0645 \u0639\u0642\u0648\u0628\u0629 \u0645\u0648\u062c\u0639\u0629 \u0628\u0633\u0628\u0628 \u0643\u0630\u0628\u0647\u0645 \u0648\u0646\u0641\u0627\u0642\u0647\u0645.","2:11":"\u0648\u0625\u0630\u0627 \u0646\u064f\u0635\u062d\u0648\u0627 \u0644\u064a\u0643\u0641\u0651\u064f\u0648\u0627 \u0639\u0646 \u0627\u0644\u0625\u0641\u0633\u0627\u062f \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0628\u0627\u0644\u0643\u0641\u0631 \u0648\u0627\u0644\u0645\u0639\u0627\u0635\u064a\u060c \u0648\u0625\u0641\u0634\u0627\u0621 \u0623\u0633\u0631\u0627\u0631 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0648\u0645\u0648\u0627\u0644\u0627\u0629 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646\u060c \u0642\u0627\u0644\u0648\u0627 -\u0643\u0630\u0628\u064b\u0627 \u0648\u062c\u062f\u0627\u0644\u0627\u064b- \u0625\u0646\u0645\u0627 \u0646\u062d\u0646 \u0623\u0647\u0644 \u0627\u0644\u0625\u0635\u0644\u0627\u062d.","2:12":"[\u0623\u064a \u0644\u0627 \u064a\u0634\u0639\u0631\u0648\u0646] \u0623\u0646\u0651\u064e \u0647\u0630\u0627 \u0627\u0644\u0630\u064a \u064a\u0641\u0639\u0644\u0648\u0646\u0647 \u0648\u064a\u0632\u0639\u0645\u0648\u0646 \u0623\u0646\u0647 \u0625\u0635\u0644\u0627\u062d \u0647\u0648 \u0639\u064a\u0646 \u0627\u0644\u0641\u0633\u0627\u062f\u060c \u0644\u0643\u0646\u0647\u0645 \u0628\u0633\u0628\u0628 \u062c\u0647\u0644\u0647\u0645 \u0648\u0639\u0646\u0627\u062f\u0647\u0645 \u0644\u0627 \u064a\u064f\u062d\u0650\u0633\u0651\u064f\u0648\u0646.","2:13":"\u0648\u0625\u0630\u0627 \u0642\u064a\u0644 \u0644\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646: \u0622\u0645\u0650\u0646\u064f\u0648\u0627 -\u0645\u062b\u0644 \u0625\u064a\u0645\u0627\u0646 \u0627\u0644\u0635\u062d\u0627\u0628\u0629\u060c \u0648\u0647\u0648 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0642\u0644\u0628 \u0648\u0627\u0644\u0644\u0633\u0627\u0646 \u0648\u0627\u0644\u062c\u0648\u0627\u0631\u062d-\u060c \u062c\u0627\u062f\u064e\u0644\u0648\u0627 \u0648\u0642\u0627\u0644\u0648\u0627: \u0623\u064e\u0646\u064f\u0635\u064e\u062f\u0651\u0650\u0642 \u0645\u062b\u0644 \u062a\u0635\u062f\u064a\u0642 \u0636\u0639\u0627\u0641 \u0627\u0644\u0639\u0642\u0644 \u0648\u0627\u0644\u0631\u0623\u064a\u060c \u0641\u0646\u0643\u0648\u0646 \u0646\u062d\u0646 \u0648\u0647\u0645 \u0641\u064a \u0627\u0644\u0633\u0651\u064e\u0641\u064e\u0647\u0650 \u0633\u0648\u0627\u0621\u061f \u0641\u0631\u062f\u0651\u064e \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645 \u0628\u0623\u0646 \u0627\u0644\u0633\u0651\u064e\u0641\u064e\u0647\u064e \u0645\u0642\u0635\u0648\u0631 \u0639\u0644\u064a\u0647\u0645\u060c \u0648\u0647\u0645 \u0644\u0627 \u064a\u0639\u0644\u0645\u0648\u0646 \u0623\u0646 \u0645\u0627 \u0647\u0645 \u0641\u064a\u0647 \u0647\u0648 \u0627\u0644\u0636\u0644\u0627\u0644 \u0648\u0627\u0644\u062e\u0633\u0631\u0627\u0646.","2:14":"\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0625\u0630\u0627 \u0642\u0627\u0628\u0644\u0648\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0642\u0627\u0644\u0648\u0627: \u0635\u062f\u0651\u064e\u0642\u0646\u0627 \u0628\u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0645\u062b\u0644\u0643\u0645\u060c \u0648\u0625\u0630\u0627 \u0627\u0646\u0635\u0631\u0641\u0648\u0627 \u0648\u0630\u0647\u0628\u0648\u0627 \u0625\u0644\u0649 \u0632\u0639\u0645\u0627\u0626\u0647\u0645 \u0627\u0644\u0643\u0641\u0631\u0629 \u0627\u0644\u0645\u062a\u0645\u0631\u062f\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0623\u0643\u0651\u064e\u062f\u0648\u0627 \u0644\u0647\u0645 \u0623\u0646\u0647\u0645 \u0639\u0644\u0649 \u0645\u0644\u0629 \u0627\u0644\u0643\u0641\u0631 \u0644\u0645 \u064a\u062a\u0631\u0643\u0648\u0647\u0627\u060c \u0648\u0625\u0646\u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u062e\u0650\u0641\u0651\u064f\u0648\u0646 \u0628\u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0648\u064a\u0633\u062e\u0631\u0648\u0646 \u0645\u0646\u0647\u0645.","2:15":"\u0627\u0644\u0644\u0647 \u064a\u0633\u062a\u0647\u0632\u0626 \u0628\u0647\u0645 \u0648\u064a\u064f\u0645\u0647\u0644\u0647\u0645; \u0644\u064a\u0632\u062f\u0627\u062f\u0648\u0627 \u0636\u0644\u0627\u0644\u0627 \u0648\u062d\u064e\u064a\u0652\u0631\u0629 \u0648\u062a\u0631\u062f\u062f\u064b\u0627\u060c \u0648\u064a\u062c\u0627\u0632\u064a\u0647\u0645 \u0639\u0644\u0649 \u0627\u0633\u062a\u0647\u0632\u0627\u0626\u0647\u0645 \u0628\u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646.","2:16":"\u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0628\u0627\u0639\u0648\u0627 \u0623\u0646\u0641\u0633\u0647\u0645 \u0641\u064a \u0635\u0641\u0642\u0629 \u062e\u0627\u0633\u0631\u0629\u060c \u0641\u0623\u062e\u0630\u0648\u0627 \u0627\u0644\u0643\u0641\u0631\u060c \u0648\u062a\u0631\u0643\u0648\u0627 \u0627\u0644\u0625\u064a\u0645\u0627\u0646\u060c \u0641\u0645\u0627 \u0643\u0633\u0628\u0648\u0627 \u0634\u064a\u0626\u064b\u0627\u060c \u0628\u0644 \u062e\u064e\u0633\u0650\u0631\u0648\u0627 \u0627\u0644\u0647\u062f\u0627\u064a\u0629. \u0648\u0647\u0630\u0627 \u0647\u0648 \u0627\u0644\u062e\u0633\u0631\u0627\u0646 \u0627\u0644\u0645\u0628\u064a\u0646.","2:17":"\u062d\u0627\u0644 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 -\u0638\u0627\u0647\u0631\u064b\u0627 \u0644\u0627 \u0628\u0627\u0637\u0646\u064b\u0627- \u0628\u0631\u0633\u0627\u0644\u0629 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u062b\u0645 \u0643\u0641\u0631\u0648\u0627\u060c \u0641\u0635\u0627\u0631\u0648\u0627 \u064a\u062a\u062e\u0628\u0637\u0648\u0646 \u0641\u064a \u0638\u0644\u0645\u0627\u062a\u0650 \u0636\u0644\u0627\u0644\u0647\u0645 \u0648\u0647\u0645 \u0644\u0627 \u064a\u0634\u0639\u0631\u0648\u0646\u060c \u0648\u0644\u0627 \u0623\u0645\u0644 \u0644\u0647\u0645 \u0641\u064a \u0627\u0644\u062e\u0631\u0648\u062c \u0645\u0646\u0647\u0627\u060c \u062a\u064f\u0634\u0652\u0628\u0647 \u062d\u0627\u0644\u064e \u062c\u0645\u0627\u0639\u0629 \u0641\u064a \u0644\u064a\u0644\u0629 \u0645\u0638\u0644\u0645\u0629\u060c \u0648\u0623\u0648\u0642\u062f \u0623\u062d\u062f\u0647\u0645 \u0646\u0627\u0631\u064b\u0627 \u0639\u0638\u064a\u0645\u0629 \u0644\u0644\u062f\u0641\u0621 \u0648\u0627\u0644\u0625\u0636\u0627\u0621\u0629\u060c \u0641\u0644\u0645\u0627 \u0633\u0637\u0639\u062a \u0627\u0644\u0646\u0627\u0631 \u0648\u0623\u0646\u0627\u0631\u062a \u0645\u0627 \u062d\u0648\u0644\u0647\u060c \u0627\u0646\u0637\u0641\u0623\u062a \u0648\u0623\u0639\u062a\u0645\u062a\u060c \u0641\u0635\u0627\u0631 \u0623\u0635\u062d\u0627\u0628\u0647\u0627 \u0641\u064a \u0638\u0644\u0645\u0627\u062a \u0644\u0627 \u064a\u0631\u0648\u0646 \u0634\u064a\u0626\u064b\u0627\u060c \u0648\u0644\u0627 \u064a\u0647\u062a\u062f\u0648\u0646 \u0625\u0644\u0649 \u0637\u0631\u064a\u0642 \u0648\u0644\u0627 \u0645\u062e\u0631\u062c.","2:18":"\u0647\u0645 \u0635\u064f\u0645\u0651\u064c \u0639\u0646 \u0633\u0645\u0627\u0639 \u0627\u0644\u062d\u0642 \u0633\u0645\u0627\u0639 \u062a\u062f\u0628\u0631\u060c \u0628\u064f\u0643\u0652\u0645 \u0639\u0646 \u0627\u0644\u0646\u0637\u0642 \u0628\u0647\u060c \u0639\u064f\u0645\u0652\u064a \u0639\u0646 \u0625\u0628\u0635\u0627\u0631 \u0646\u0648\u0631 \u0627\u0644\u0647\u062f\u0627\u064a\u0629; \u0644\u0630\u0644\u0643 \u0644\u0627 \u064a\u0633\u062a\u0637\u064a\u0639\u0648\u0646 \u0627\u0644\u0631\u062c\u0648\u0639 \u0625\u0644\u0649 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0627\u0644\u0630\u064a \u062a\u0631\u0643\u0648\u0647\u060c \u0648\u0627\u0633\u062a\u0639\u0627\u0636\u0648\u0627 \u0639\u0646\u0647 \u0628\u0627\u0644\u0636\u0644\u0627\u0644.","2:19":"\u0623\u0648 \u062a\u064f\u0634\u0652\u0628\u0647 \u062d\u0627\u0644\u064f \u0641\u0631\u064a\u0642 \u0622\u062e\u0631 \u0645\u0646 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u064a\u0638\u0647\u0631 \u0644\u0647\u0645 \u0627\u0644\u062d\u0642 \u062a\u0627\u0631\u0629\u060c \u0648\u064a\u0634\u0643\u0648\u0646 \u0641\u064a\u0647 \u062a\u0627\u0631\u0629 \u0623\u062e\u0631\u0649\u060c \u062d\u0627\u0644\u064e \u062c\u0645\u0627\u0639\u0629 \u064a\u0645\u0634\u0648\u0646 \u0641\u064a \u0627\u0644\u0639\u0631\u0627\u0621\u060c \u0641\u064a\u0646\u0635\u0628 \u0639\u0644\u064a\u0647\u0645 \u0645\u0637\u0631 \u0634\u062f\u064a\u062f\u060c \u062a\u0635\u0627\u062d\u0628\u0647 \u0638\u0644\u0645\u0627\u062a \u0628\u0639\u0636\u0647\u0627 \u0641\u0648\u0642 \u0628\u0639\u0636\u060c \u0645\u0639 \u0642\u0635\u0641 \u0627\u0644\u0631\u0639\u062f\u060c \u0648\u0644\u0645\u0639\u0627\u0646 \u0627\u0644\u0628\u0631\u0642\u060c \u0648\u0627\u0644\u0635\u0648\u0627\u0639\u0642 \u0627\u0644\u0645\u062d\u0631\u0642\u0629\u060c \u0627\u0644\u062a\u064a \u062a\u062c\u0639\u0644\u0647\u0645 \u0645\u0646 \u0634\u062f\u0629 \u0627\u0644\u0647\u0648\u0644 \u064a\u0636\u0639\u0648\u0646 \u0623\u0635\u0627\u0628\u0639\u0647\u0645 \u0641\u064a \u0622\u0630\u0627\u0646\u0647\u0645; \u062e\u0648\u0641\u064b\u0627 \u0645\u0646 \u0627\u0644\u0647\u0644\u0627\u0643. \u0648\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0645\u062d\u064a\u0637 \u0628\u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0644\u0627 \u064a\u0641\u0648\u062a\u0648\u0646\u0647 \u0648\u0644\u0627 \u064a\u0639\u062c\u0632\u0648\u0646\u0647.","2:20":"\u064a\u0642\u0627\u0631\u0628 \u0627\u0644\u0628\u0631\u0642 -\u0645\u0646 \u0634\u062f\u0629 \u0644\u0645\u0639\u0627\u0646\u0647- \u0623\u0646 \u064a\u0633\u0644\u0628 \u0623\u0628\u0635\u0627\u0631\u0647\u0645\u060c \u0648\u0645\u0639 \u0630\u0644\u0643 \u0641\u0643\u0644\u0651\u064e\u0645\u0627 \u0623\u0636\u0627\u0621 \u0644\u0647\u0645 \u0645\u0634\u064e\u0648\u0652\u0627 \u0641\u064a \u0636\u0648\u0626\u0647\u060c \u0648\u0625\u0630\u0627 \u0630\u0647\u0628 \u0623\u0638\u0644\u0645 \u0627\u0644\u0637\u0631\u064a\u0642 \u0639\u0644\u064a\u0647\u0645 \u0641\u064a\u0642\u0641\u0648\u0646 \u0641\u064a \u0623\u0645\u0627\u0643\u0646\u0647\u0645. \u0648\u0644\u0648\u0644\u0627 \u0625\u0645\u0647\u0627\u0644 \u0627\u0644\u0644\u0647 \u0644\u0647\u0645 \u0644\u0633\u0644\u0628 \u0633\u0645\u0639\u0647\u0645 \u0648\u0623\u0628\u0635\u0627\u0631\u0647\u0645\u060c \u0648\u0647\u0648 \u0642\u0627\u062f\u0631 \u0639\u0644\u0649 \u0630\u0644\u0643 \u0641\u064a \u0643\u0644 \u0648\u0642\u062a\u064d\u060c \u0625\u0646\u0647 \u0639\u0644\u0649 \u0643\u0644 \u0634\u064a\u0621 \u0642\u062f\u064a\u0631.","2:21":"\u0646\u062f\u0627\u0621 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0644\u0644\u0628\u0634\u0631 \u062c\u0645\u064a\u0639\u064b\u0627: \u0623\u0646 \u0627\u0639\u0628\u062f\u0648\u0627 \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a \u0631\u0628\u0651\u064e\u0627\u0643\u0645 \u0628\u0646\u0639\u0645\u0647\u060c \u0648\u062e\u0627\u0641\u0648\u0647 \u0648\u0644\u0627 \u062a\u062e\u0627\u0644\u0641\u0648\u0627 \u062f\u064a\u0646\u0647; \u0641\u0642\u062f \u0623\u0648\u062c\u062f\u0643\u0645 \u0645\u0646 \u0627\u0644\u0639\u062f\u0645\u060c \u0648\u0623\u0648\u062c\u062f \u0627\u0644\u0630\u064a\u0646 \u0645\u0646 \u0642\u0628\u0644\u0643\u0645; \u0644\u062a\u0643\u0648\u0646\u0648\u0627 \u0645\u0646 \u0627\u0644\u0645\u062a\u0642\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645 \u0648\u0631\u0636\u0648\u0627 \u0639\u0646\u0647.","2:22":"\u0631\u0628\u0643\u0645 \u0627\u0644\u0630\u064a \u062c\u0639\u0644 \u0644\u0643\u0645 \u0627\u0644\u0623\u0631\u0636 \u0628\u0633\u0627\u0637\u064b\u0627; \u0644\u062a\u0633\u0647\u0644 \u062d\u064a\u0627\u062a\u0643\u0645 \u0639\u0644\u064a\u0647\u0627\u060c \u0648\u0627\u0644\u0633\u0645\u0627\u0621 \u0645\u062d\u0643\u0645\u0629 \u0627\u0644\u0628\u0646\u0627\u0621\u060c \u0648\u0623\u0646\u0632\u0644 \u0627\u0644\u0645\u0637\u0631 \u0645\u0646 \u0627\u0644\u0633\u062d\u0627\u0628 \u0641\u0623\u062e\u0631\u062c \u0644\u0643\u0645 \u0628\u0647 \u0645\u0646 \u0623\u0644\u0648\u0627\u0646 \u0627\u0644\u062b\u0645\u0631\u0627\u062a \u0648\u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0646\u0628\u0627\u062a \u0631\u0632\u0642\u064b\u0627 \u0644\u0643\u0645\u060c \u0641\u0644\u0627 \u062a\u062c\u0639\u0644\u0648\u0627 \u0644\u0644\u0647 \u0646\u0638\u0631\u0627\u0621 \u0641\u064a \u0627\u0644\u0639\u0628\u0627\u062f\u0629\u060c \u0648\u0623\u0646\u062a\u0645 \u062a\u0639\u0644\u0645\u0648\u0646 \u062a\u0641\u0631\u0651\u064f\u062f\u0647 \u0628\u0627\u0644\u062e\u0644\u0642 \u0648\u0627\u0644\u0631\u0632\u0642\u060c \u0648\u0627\u0633\u062a\u062d\u0642\u0627\u0642\u0650\u0647 \u0627\u0644\u0639\u0628\u0648\u062f\u064a\u0629.","2:23":"\u0648\u0625\u0646 \u0643\u0646\u062a\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0643\u0627\u0641\u0631\u0648\u0646 \u0627\u0644\u0645\u0639\u0627\u0646\u062f\u0648\u0646- \u0641\u064a \u0634\u064e\u0643\u0651\u064d \u0645\u0646 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0630\u064a \u0646\u064e\u0632\u0651\u064e\u0644\u0646\u0627\u0647 \u0639\u0644\u0649 \u0639\u0628\u062f\u0646\u0627 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u062a\u0632\u0639\u0645\u0648\u0646 \u0623\u0646\u0647 \u0644\u064a\u0633 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647\u060c \u0641\u0647\u0627\u062a\u0648\u0627 \u0633\u0648\u0631\u0629 \u062a\u0645\u0627\u062b\u0644 \u0633\u0648\u0631\u0629 \u0645\u0646 \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0648\u0627\u0633\u062a\u0639\u064a\u0646\u0648\u0627 \u0628\u0645\u0646 \u062a\u0642\u062f\u0631\u0648\u0646 \u0639\u0644\u064a\u0647 \u0645\u0650\u0646 \u0623\u0639\u0648\u0627\u0646\u0643\u0645\u060c \u0625\u0646 \u0643\u0646\u062a\u0645 \u0635\u0627\u062f\u0642\u064a\u0646 \u0641\u064a \u062f\u0639\u0648\u0627\u0643\u0645.","2:24":"\u0641\u0625\u0646 \u0639\u062c\u064e\u0632\u062a\u0645 \u0627\u0644\u0622\u0646 -\u0648\u0633\u062a\u0639\u062c\u0632\u0648\u0646 \u0645\u0633\u062a\u0642\u0628\u0644\u0627 \u0644\u0627 \u0645\u062d\u0627\u0644\u0629- \u0641\u0627\u062a\u0642\u0648\u0627 \u0627\u0644\u0646\u0627\u0631 \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0646\u0628\u064a \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649. \u0647\u0630\u0647 \u0627\u0644\u0646\u0627\u0631 \u0627\u0644\u062a\u064a \u062d\u064e\u0637\u064e\u0628\u064f\u0647\u0627 \u0627\u0644\u0646\u0627\u0633 \u0648\u0627\u0644\u062d\u062c\u0627\u0631\u0629\u060c \u0623\u064f\u0639\u0650\u062f\u0651\u064e\u062a\u0652 \u0644\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0644\u0647.","2:25":"\u0648\u0623\u062e\u0628\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0623\u0647\u0644 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0635\u0627\u0644\u062d \u062e\u0628\u0631\u064b\u0627 \u064a\u0645\u0644\u0624\u0647\u0645 \u0633\u0631\u0648\u0631\u064b\u0627\u060c \u0628\u0623\u0646 \u0644\u0647\u0645 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u062d\u062f\u0627\u0626\u0642 \u0639\u062c\u064a\u0628\u0629\u060c \u062a\u062c\u0631\u064a \u0627\u0644\u0623\u0646\u0647\u0627\u0631 \u062a\u062d\u062a \u0642\u0635\u0648\u0631\u0647\u0627 \u0627\u0644\u0639\u0627\u0644\u064a\u0629 \u0648\u0623\u0634\u062c\u0627\u0631\u0647\u0627 \u0627\u0644\u0638\u0644\u064a\u0644\u0629. \u0643\u0644\u0651\u064e\u0645\u0627 \u0631\u0632\u0642\u0647\u0645 \u0627\u0644\u0644\u0647 \u0641\u064a\u0647\u0627 \u0646\u0648\u0639\u064b\u0627 \u0645\u0646 \u0627\u0644\u0641\u0627\u0643\u0647\u0629 \u0627\u0644\u0644\u0630\u064a\u0630\u0629 \u0642\u0627\u0644\u0648\u0627: \u0642\u062f \u0631\u064e\u0632\u064e\u0642\u064e\u0646\u0627 \u0627\u0644\u0644\u0647 \u0647\u0630\u0627 \u0627\u0644\u0646\u0648\u0639 \u0645\u0646 \u0642\u0628\u0644\u060c \u0641\u0625\u0630\u0627 \u0630\u0627\u0642\u0648\u0647 \u0648\u062c\u062f\u0648\u0647 \u0634\u064a\u0626\u064b\u0627 \u062c\u062f\u064a\u062f\u064b\u0627 \u0641\u064a \u0637\u0639\u0645\u0647 \u0648\u0644\u0630\u062a\u0647\u060c \u0648\u0625\u0646 \u062a\u0634\u0627\u0628\u0647 \u0645\u0639 \u0633\u0627\u0628\u0642\u0647 \u0641\u064a \u0627\u0644\u0644\u0648\u0646 \u0648\u0627\u0644\u0645\u0646\u0638\u0631 \u0648\u0627\u0644\u0627\u0633\u0645. \u0648\u0644\u0647\u0645 \u0641\u064a \u0627\u0644\u062c\u0646\u0651\u064e\u0627\u062a \u0632\u0648\u062c\u0627\u062a \u0645\u0637\u0647\u0651\u064e\u0631\u0627\u062a \u0645\u0646 \u0643\u0644 \u0623\u0644\u0648\u0627\u0646 \u0627\u0644\u062f\u0646\u0633 \u0627\u0644\u062d\u0633\u064a\u0651\u0650 \u0643\u0627\u0644\u0628\u0648\u0644 \u0648\u0627\u0644\u062d\u064a\u0636\u060c \u0648\u0627\u0644\u0645\u0639\u0646\u0648\u064a \u0643\u0627\u0644\u0643\u0630\u0628 \u0648\u0633\u0648\u0621 \u0627\u0644\u062e\u064f\u0644\u064f\u0642. \u0648\u0647\u0645 \u0641\u064a \u0627\u0644\u062c\u0646\u0629 \u0648\u0646\u0639\u064a\u0645\u0647\u0627 \u062f\u0627\u0626\u0645\u0648\u0646\u060c \u0644\u0627 \u064a\u0645\u0648\u062a\u0648\u0646 \u0641\u064a\u0647\u0627 \u0648\u0644\u0627 \u064a\u062e\u0631\u062c\u0648\u0646 \u0645\u0646\u0647\u0627.","2:26":"\u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0627 \u064a\u0633\u062a\u062d\u064a\u064a \u0645\u0646 \u0627\u0644\u062d\u0642 \u0623\u0646 \u064a\u0630\u0643\u0631 \u0634\u064a\u0626\u064b\u0627 \u0645\u0627\u060c \u0642\u0644\u0651\u064e \u0623\u0648 \u0643\u062b\u0631\u060c \u0648\u0644\u0648 \u0643\u0627\u0646 \u062a\u0645\u062b\u064a\u0644\u0627 \u0628\u0623\u0635\u063a\u0631 \u0634\u064a\u0621\u060c \u0643\u0627\u0644\u0628\u0639\u0648\u0636\u0629 \u0648\u0627\u0644\u0630\u0628\u0627\u0628 \u0648\u0646\u062d\u0648 \u0630\u0644\u0643\u060c \u0645\u0645\u0627 \u0636\u0631\u0628\u0647 \u0627\u0644\u0644\u0647 \u0645\u062b\u0644\u0627 \u0644\u0650\u0639\u064e\u062c\u0652\u0632 \u0643\u0644 \u0645\u0627 \u064a\u064f\u0639\u0652\u0628\u064e\u062f \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647. \u0641\u0623\u0645\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0641\u064a\u0639\u0644\u0645\u0648\u0646 \u062d\u0643\u0645\u0629 \u0627\u0644\u0644\u0647 \u0641\u064a \u0627\u0644\u062a\u0645\u062b\u064a\u0644 \u0628\u0627\u0644\u0635\u063a\u064a\u0631 \u0648\u0627\u0644\u0643\u0628\u064a\u0631 \u0645\u0646 \u062e\u0644\u0642\u0647\u060c \u0648\u0623\u0645\u0627 \u0627\u0644\u0643\u0641\u0627\u0631 \u0641\u064e\u064a\u064e\u0633\u0652\u062e\u0631\u0648\u0646 \u0648\u064a\u0642\u0648\u0644\u0648\u0646: \u0645\u0627 \u0645\u0631\u0627\u062f \u0627\u0644\u0644\u0647 \u0645\u0650\u0646 \u0636\u064e\u0631\u0652\u0628 \u0627\u0644\u0645\u062b\u0644 \u0628\u0647\u0630\u0647 \u0627\u0644\u062d\u0634\u0631\u0627\u062a \u0627\u0644\u062d\u0642\u064a\u0631\u0629\u061f \u0648\u064a\u062c\u064a\u0628\u0647\u0645 \u0627\u0644\u0644\u0647 \u0628\u0623\u0646 \u0627\u0644\u0645\u0631\u0627\u062f \u0647\u0648 \u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631\u060c \u0648\u062a\u0645\u064a\u064a\u0632 \u0627\u0644\u0645\u0624\u0645\u0646 \u0645\u0646 \u0627\u0644\u0643\u0627\u0641\u0631; \u0644\u0630\u0644\u0643 \u064a\u0635\u0631\u0641 \u0627\u0644\u0644\u0647 \u0628\u0647\u0630\u0627 \u0627\u0644\u0645\u062b\u0644 \u0646\u0627\u0633\u064b\u0627 \u0643\u062b\u064a\u0631\u064a\u0646 \u0639\u0646 \u0627\u0644\u062d\u0642 \u0644\u0633\u062e\u0631\u064a\u062a\u0647\u0645 \u0645\u0646\u0647\u060c \u0648\u064a\u0648\u0641\u0642 \u0628\u0647 \u063a\u064a\u0631\u0647\u0645 \u0625\u0644\u0649 \u0645\u0632\u064a\u062f \u0645\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0627\u0644\u0647\u062f\u0627\u064a\u0629. \u0648\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0627 \u064a\u0638\u0644\u0645 \u0623\u062d\u062f\u064b\u0627; \u0644\u0623\u0646\u0647 \u0644\u0627 \u064a\u064e\u0635\u0652\u0631\u0650\u0641 \u0639\u0646 \u0627\u0644\u062d\u0642 \u0625\u0644\u0627 \u0627\u0644\u062e\u0627\u0631\u062c\u064a\u0646 \u0639\u0646 \u0637\u0627\u0639\u062a\u0647.","2:27":"\u0627\u0644\u0630\u064a\u0646 \u064a\u0646\u0643\u062b\u0648\u0646 \u0639\u0647\u062f \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a \u0623\u062e\u0630\u0647 \u0639\u0644\u064a\u0647\u0645 \u0628\u0627\u0644\u062a\u0648\u062d\u064a\u062f \u0648\u0627\u0644\u0637\u0627\u0639\u0629\u060c \u0648\u0642\u062f \u0623\u0643\u0651\u064e\u062f\u0647 \u0628\u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u0631\u0633\u0644\u060c \u0648\u0625\u0646\u0632\u0627\u0644 \u0627\u0644\u0643\u062a\u0628\u060c \u0648\u064a\u062e\u0627\u0644\u0641\u0648\u0646 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647 \u0643\u0642\u0637\u0639 \u0627\u0644\u0623\u0631\u062d\u0627\u0645 \u0648\u0646\u0634\u0631 \u0627\u0644\u0641\u0633\u0627\u062f \u0641\u064a \u0627\u0644\u0623\u0631\u0636\u060c \u0623\u0648\u0644\u0626\u0643 \u0647\u0645 \u0627\u0644\u062e\u0627\u0633\u0631\u0648\u0646 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629.","2:28":"\u0643\u064a\u0641 \u062a\u0646\u0643\u0631\u0648\u0646 -\u0623\u064a\u0651\u064f\u0647\u0627 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646- \u0648\u062d\u062f\u0627\u0646\u064a\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u062a\u0634\u0631\u0643\u0648\u0646 \u0628\u0647 \u063a\u064a\u0631\u0647 \u0641\u064a \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u0645\u0639 \u0627\u0644\u0628\u0631\u0647\u0627\u0646 \u0627\u0644\u0642\u0627\u0637\u0639 \u0639\u0644\u064a\u0647\u0627 \u0641\u064a \u0623\u0646\u0641\u0633\u0643\u0645\u061f \u0641\u0644\u0642\u062f \u0643\u0646\u062a\u0645 \u0623\u0645\u0648\u0627\u062a\u064b\u0627 \u0641\u0623\u0648\u062c\u062f\u0643\u0645 \u0648\u0646\u0641\u062e \u0641\u064a\u0643\u0645 \u0627\u0644\u062d\u064a\u0627\u0629\u060c \u062b\u0645 \u064a\u0645\u064a\u062a\u0643\u0645 \u0628\u0639\u062f \u0627\u0646\u0642\u0636\u0627\u0621 \u0622\u062c\u0627\u0644\u0643\u0645 \u0627\u0644\u062a\u064a \u062d\u062f\u062f\u0647\u0627 \u0644\u0643\u0645\u060c \u062b\u0645 \u064a\u0639\u064a\u062f\u0643\u0645 \u0623\u062d\u064a\u0627\u0621 \u064a\u0648\u0645 \u0627\u0644\u0628\u0639\u062b\u060c \u062b\u0645 \u0625\u0644\u064a\u0647 \u062a\u0631\u062c\u0639\u0648\u0646 \u0644\u0644\u062d\u0633\u0627\u0628 \u0648\u0627\u0644\u062c\u0632\u0627\u0621.","2:29":"\u0627\u0644\u0644\u0647\u064f \u0648\u062d\u062f\u0647 \u0627\u0644\u0630\u064a \u062e\u064e\u0644\u064e\u0642 \u0644\u0623\u062c\u0644\u0643\u0645 \u0643\u0644 \u0645\u0627 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0645\u0646 \u0627\u0644\u0646\u0651\u0650\u0639\u0645 \u0627\u0644\u062a\u064a \u062a\u0646\u062a\u0641\u0639\u0648\u0646 \u0628\u0647\u0627\u060c \u062b\u0645 \u0642\u0635\u062f \u0625\u0644\u0649 \u062e\u0644\u0642 \u0627\u0644\u0633\u0645\u0648\u0627\u062a\u060c \u0641\u0633\u0648\u0651\u064e\u0627\u0647\u0646\u0651\u064e \u0633\u0628\u0639 \u0633\u0645\u0648\u0627\u062a\u060c \u0648\u0647\u0648 \u0628\u0643\u0644 \u0634\u064a\u0621 \u0639\u0644\u064a\u0645. \u0641\u0639\u0650\u0644\u0652\u0645\u064f\u0647 -\u0633\u0628\u062d\u0627\u0646\u0647- \u0645\u062d\u064a\u0637 \u0628\u062c\u0645\u064a\u0639 \u0645\u0627 \u062e\u0644\u0642.","2:30":"\u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0644\u0646\u0627\u0633 \u062d\u064a\u0646 \u0642\u0627\u0644 \u0631\u0628\u0643 \u0644\u0644\u0645\u0644\u0627\u0626\u0643\u0629: \u0625\u0646\u064a \u062c\u0627\u0639\u0644 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0642\u0648\u0645\u064b\u0627 \u064a\u062e\u0644\u0641 \u0628\u0639\u0636\u0647\u0645 \u0628\u0639\u0636\u064b\u0627 \u0644\u0639\u0645\u0627\u0631\u062a\u0647\u0627. \u0642\u0627\u0644\u062a: \u064a\u0627 \u0631\u0628\u0651\u064e\u0646\u0627 \u0639\u0644\u0651\u0650\u0645\u0652\u0646\u0627 \u0648\u0623\u064e\u0631\u0652\u0634\u0650\u062f\u0652\u0646\u0627 \u0645\u0627 \u0627\u0644\u062d\u0643\u0645\u0629 \u0641\u064a \u062e\u0644\u0642 \u0647\u0624\u0644\u0627\u0621\u060c \u0645\u0639 \u0623\u0646\u0651\u064e \u0645\u0646 \u0634\u0623\u0646\u0647\u0645 \u0627\u0644\u0625\u0641\u0633\u0627\u062f \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0648\u0627\u0631\u0627\u0642\u0629 \u0627\u0644\u062f\u0645\u0627\u0621 \u0638\u0644\u0645\u0627 \u0648\u0639\u062f\u0648\u0627\u0646\u064b\u0627 \u0648\u0646\u062d\u0646 \u0637\u0648\u0639 \u0623\u0645\u0631\u0643\u060c \u0646\u0646\u0632\u0651\u0650\u0647\u0643 \u0627\u0644\u062a\u0646\u0632\u064a\u0647 \u0627\u0644\u0644\u0627\u0626\u0642 \u0628\u062d\u0645\u062f\u0643 \u0648\u062c\u0644\u0627\u0644\u0643\u060c \u0648\u0646\u0645\u062c\u0651\u0650\u062f\u0643 \u0628\u0643\u0644 \u0635\u0641\u0627\u062a \u0627\u0644\u0643\u0645\u0627\u0644 \u0648\u0627\u0644\u062c\u0644\u0627\u0644\u061f \u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u0644\u0647\u0645: \u0625\u0646\u064a \u0623\u0639\u0644\u0645 \u0645\u0627 \u0644\u0627 \u062a\u0639\u0644\u0645\u0648\u0646 \u0645\u0646 \u0627\u0644\u0645\u0635\u0644\u062d\u0629 \u0627\u0644\u0631\u0627\u062c\u062d\u0629 \u0641\u064a \u062e\u0644\u0642\u0647\u0645.","2:31":"\u0648\u0628\u064a\u0627\u0646\u064b\u0627 \u0644\u0641\u0636\u0644 \u0622\u062f\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0639\u0644\u0651\u064e\u0645\u0647 \u0627\u0644\u0644\u0647 \u0623\u0633\u0645\u0627\u0621 \u0627\u0644\u0623\u0634\u064a\u0627\u0621 \u0643\u0644\u0647\u0627\u060c \u062b\u0645 \u0639\u0631\u0636 \u0645\u0633\u0645\u064a\u0627\u062a\u0647\u0627 \u0639\u0644\u0649 \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u0642\u0627\u0626\u0644\u0627 \u0644\u0647\u0645: \u0623\u062e\u0628\u0631\u0648\u0646\u064a \u0628\u0623\u0633\u0645\u0627\u0621 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0648\u062c\u0648\u062f\u0627\u062a\u060c \u0625\u0646 \u0643\u0646\u062a\u0645 \u0635\u0627\u062f\u0642\u064a\u0646 \u0641\u064a \u0623\u0646\u0643\u0645 \u0623\u064e\u0648\u0652\u0644\u0649 \u0628\u0627\u0644\u0627\u0633\u062a\u062e\u0644\u0627\u0641 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0645\u0646\u0647\u0645.","2:32":"\u0642\u0627\u0644\u062a \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629: \u0646\u0646\u0632\u0651\u0650\u0647\u0643 \u064a\u0627 \u0631\u0628\u0651\u064e\u0646\u0627\u060c \u0644\u064a\u0633 \u0644\u0646\u0627 \u0639\u0644\u0645 \u0625\u0644\u0627 \u0645\u0627 \u0639\u0644\u0651\u064e\u0645\u062a\u0646\u0627 \u0625\u064a\u0627\u0647. \u0625\u0646\u0643 \u0623\u0646\u062a \u0648\u062d\u062f\u0643 \u0627\u0644\u0639\u0644\u064a\u0645 \u0628\u0634\u0626\u0648\u0646 \u062e\u0644\u0642\u0643\u060c \u0627\u0644\u062d\u0643\u064a\u0645 \u0641\u064a \u062a\u062f\u0628\u064a\u0631\u0643.","2:33":"\u0642\u0627\u0644 \u0627\u0644\u0644\u0647: \u064a\u0627 \u0622\u062f\u0645 \u0623\u062e\u0628\u0631\u0647\u0645 \u0628\u0623\u0633\u0645\u0627\u0621 \u0647\u0630\u0647 \u0627\u0644\u0623\u0634\u064a\u0627\u0621 \u0627\u0644\u062a\u064a \u0639\u062c\u064e\u0632\u0648\u0627 \u0639\u0646 \u0645\u0639\u0631\u0641\u062a\u0647\u0627. \u0641\u0644\u0645\u0627 \u0623\u062e\u0628\u0631\u0647\u0645 \u0622\u062f\u0645 \u0628\u0647\u0627\u060c \u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u0644\u0644\u0645\u0644\u0627\u0626\u0643\u0629: \u0644\u0642\u062f \u0623\u062e\u0628\u0631\u062a\u0643\u0645 \u0623\u0646\u064a \u0623\u0639\u0644\u0645 \u0645\u0627 \u062e\u0641\u064a \u0639\u0646\u0643\u0645 \u0641\u064a \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0623\u0639\u0644\u0645 \u0645\u0627 \u062a\u0638\u0647\u0631\u0648\u0646\u0647 \u0648\u0645\u0627 \u062a\u062e\u0641\u0648\u0646\u0647.","2:34":"\u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0644\u0646\u0627\u0633 \u062a\u0643\u0631\u064a\u0645 \u0627\u0644\u0644\u0647 \u0644\u0622\u062f\u0645 \u062d\u064a\u0646 \u0642\u0627\u0644 \u0633\u0628\u062d\u0627\u0646\u0647 \u0644\u0644\u0645\u0644\u0627\u0626\u0643\u0629: \u0627\u0633\u062c\u062f\u0648\u0627 \u0644\u0622\u062f\u0645 \u0625\u0643\u0631\u0627\u0645\u064b\u0627 \u0644\u0647 \u0648\u0625\u0638\u0647\u0627\u0631\u064b\u0627 \u0644\u0641\u0636\u0644\u0647\u060c \u0641\u0623\u0637\u0627\u0639\u0648\u0627 \u062c\u0645\u064a\u0639\u064b\u0627 \u0625\u0644\u0627 \u0625\u0628\u0644\u064a\u0633 \u0627\u0645\u062a\u0646\u0639 \u0639\u0646 \u0627\u0644\u0633\u062c\u0648\u062f \u062a\u0643\u0628\u0631\u064b\u0627 \u0648\u062d\u0633\u062f\u064b\u0627\u060c \u0641\u0635\u0627\u0631 \u0645\u0646 \u0627\u0644\u062c\u0627\u062d\u062f\u064a\u0646 \u0628\u0627\u0644\u0644\u0647\u060c \u0627\u0644\u0639\u0627\u0635\u064a\u0646 \u0644\u0623\u0645\u0631\u0647.","2:35":"\u0648\u0642\u0627\u0644 \u0627\u0644\u0644\u0647: \u064a\u0627 \u0622\u062f\u0645 \u0627\u0633\u0643\u0646 \u0623\u0646\u062a \u0648\u0632\u0648\u062c\u0643 \u062d\u0648\u0627\u0621 \u0627\u0644\u062c\u0646\u0629\u060c \u0648\u062a\u0645\u062a\u0639\u0627 \u0628\u062b\u0645\u0627\u0631\u0647\u0627 \u062a\u0645\u062a\u0639\u064b\u0627 \u0647\u0646\u064a\u0626\u064b\u0627 \u0648\u0627\u0633\u0639\u064b\u0627 \u0641\u064a \u0623\u064a \u0645\u0643\u0627\u0646 \u062a\u0634\u0627\u0621\u0627\u0646 \u0641\u064a\u0647\u0627\u060c \u0648\u0644\u0627 \u062a\u0642\u0631\u0628\u0627 \u0647\u0630\u0647 \u0627\u0644\u0634\u062c\u0631\u0629 \u062d\u062a\u0649 \u0644\u0627 \u062a\u0642\u0639\u0627 \u0641\u064a \u0627\u0644\u0645\u0639\u0635\u064a\u0629\u060c \u0641\u062a\u0635\u064a\u0631\u0627 \u0645\u0646 \u0627\u0644\u0645\u062a\u062c\u0627\u0648\u0632\u064a\u0646 \u0623\u0645\u0631 \u0627\u0644\u0644\u0647.","2:36":"\u0641\u0623\u0648\u0642\u0639\u0647\u0645\u0627 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0641\u064a \u0627\u0644\u062e\u0637\u064a\u0626\u0629: \u0628\u0623\u0646\u0652 \u0648\u0633\u0648\u0633 \u0644\u0647\u0645\u0627 \u062d\u062a\u0649 \u0623\u0643\u0644\u0627 \u0645\u0646 \u0627\u0644\u0634\u062c\u0631\u0629\u060c \u0641\u062a\u0633\u0628\u0628 \u0641\u064a \u0625\u062e\u0631\u0627\u062c\u0647\u0645\u0627 \u0645\u0646 \u0627\u0644\u062c\u0646\u0629 \u0648\u0646\u0639\u064a\u0645\u0647\u0627. \u0648\u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u0644\u0647\u0645: \u0627\u0647\u0628\u0637\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u0623\u0631\u0636\u060c \u064a\u0639\u0627\u062f\u064a \u0628\u0639\u0636\u0643\u0645 \u0628\u0639\u0636\u064b\u0627 -\u0623\u064a \u0622\u062f\u0645 \u0648\u062d\u0648\u0627\u0621 \u0648\u0627\u0644\u0634\u064a\u0637\u0627\u0646- \u0648\u0644\u0643\u0645 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0627\u0633\u062a\u0642\u0631\u0627\u0631 \u0648\u0625\u0642\u0627\u0645\u0629\u060c \u0648\u0627\u0646\u062a\u0641\u0627\u0639 \u0628\u0645\u0627 \u0641\u064a\u0647\u0627 \u0625\u0644\u0649 \u0648\u0642\u062a \u0627\u0646\u062a\u0647\u0627\u0621 \u0622\u062c\u0627\u0644\u0643\u0645.","2:37":"\u0641\u062a\u0644\u0642\u0649 \u0622\u062f\u0645\u064f \u0628\u0627\u0644\u0642\u0628\u0648\u0644 \u0643\u0644\u0645\u0627\u062a\u064d\u060c \u0623\u0644\u0647\u0645\u0647 \u0627\u0644\u0644\u0647 \u0625\u064a\u0627\u0647\u0627 \u062a\u0648\u0628\u0629 \u0648\u0627\u0633\u062a\u063a\u0641\u0627\u0631\u064b\u0627\u060c \u0648\u0647\u064a \u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: {\u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0638\u064e\u0644\u064e\u0645\u0652\u0646\u064e\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u062a\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0646\u064e\u0627 \u0648\u064e\u062a\u064e\u0631\u0652\u062d\u064e\u0645\u0652\u0646\u064e\u0627 \u0644\u064e\u0646\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062e\u064e\u0627\u0633\u0650\u0631\u0650\u064a\u0646\u064e} \u0641\u062a\u0627\u0628 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u060c \u0648\u063a\u0641\u0631 \u0644\u0647 \u0630\u0646\u0628\u0647 \u0625\u0646\u0647 \u062a\u0639\u0627\u0644\u0649 \u0647\u0648 \u0627\u0644\u062a\u0648\u0627\u0628 \u0644\u0645\u0646 \u062a\u0627\u0628 \u0645\u0650\u0646 \u0639\u0628\u0627\u062f\u0647\u060c \u0627\u0644\u0631\u062d\u064a\u0645 \u0628\u0647\u0645.","2:38":"\u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u0644\u0647\u0645: \u0627\u0647\u0628\u0637\u0648\u0627 \u0645\u0646 \u0627\u0644\u062c\u0646\u0629 \u062c\u0645\u064a\u0639\u064b\u0627\u060c \u0648\u0633\u064a\u0623\u062a\u064a\u0643\u0645 \u0623\u0646\u062a\u0645 \u0648\u0630\u0631\u064a\u0627\u062a\u0643\u0645 \u0627\u0644\u0645\u062a\u0639\u0627\u0642\u0628\u0629 \u0645\u0627 \u0641\u064a\u0647 \u0647\u062f\u0627\u064a\u062a\u0643\u0645 \u0625\u0644\u0649 \u0627\u0644\u062d\u0642. \u0641\u0645\u0646 \u0639\u0645\u0644 \u0628\u0647\u0627 \u0641\u0644\u0627 \u062e\u0648\u0641 \u0639\u0644\u064a\u0647\u0645 \u0641\u064a\u0645\u0627 \u064a\u0633\u062a\u0642\u0628\u0644\u0648\u0646\u0647 \u0645\u0646 \u0623\u0645\u0631 \u0627\u0644\u0622\u062e\u0631\u0629 \u0648\u0644\u0627 \u0647\u0645 \u064a\u062d\u0632\u0646\u0648\u0646 \u0639\u0644\u0649 \u0645\u0627 \u0641\u0627\u062a\u0647\u0645 \u0645\u0646 \u0623\u0645\u0648\u0631 \u0627\u0644\u062f\u0646\u064a\u0627.","2:39":"\u0648\u0627\u0644\u0630\u064a\u0646 \u062c\u062d\u062f\u0648\u0627 \u0648\u0643\u0630\u0628\u0648\u0627 \u0628\u0622\u064a\u0627\u062a\u0646\u0627 \u0627\u0644\u0645\u062a\u0644\u0648\u0629 \u0648\u062f\u0644\u0627\u0626\u0644 \u062a\u0648\u062d\u064a\u062f\u0646\u0627\u060c \u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0630\u064a\u0646 \u064a\u0644\u0627\u0632\u0645\u0648\u0646 \u0627\u0644\u0646\u0627\u0631\u060c \u0647\u0645 \u0641\u064a\u0647\u0627 \u062e\u0627\u0644\u062f\u0648\u0646\u060c \u0644\u0627 \u064a\u062e\u0631\u062c\u0648\u0646 \u0645\u0646\u0647\u0627.","2:40":"\u064a\u0627 \u0630\u0631\u064a\u0629 \u064a\u0639\u0642\u0648\u0628 \u0627\u0630\u0643\u0631\u0648\u0627 \u0646\u0639\u0645\u064a \u0627\u0644\u0643\u062b\u064a\u0631\u0629 \u0639\u0644\u064a\u0643\u0645\u060c \u0648\u0627\u0634\u0643\u0631\u0648\u0627 \u0644\u064a\u060c \u0648\u0623\u062a\u0645\u0648\u0627 \u0648\u0635\u064a\u062a\u064a \u0644\u0643\u0645: \u0628\u0623\u0646 \u062a\u0624\u0645\u0646\u0648\u0627 \u0628\u0643\u062a\u0628\u064a \u0648\u0631\u0633\u0644\u064a \u062c\u0645\u064a\u0639\u064b\u0627\u060c \u0648\u062a\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0627\u0626\u0639\u064a. \u0641\u0625\u0646 \u0641\u0639\u0644\u062a\u0645 \u0630\u0644\u0643 \u0623\u064f\u062a\u0645\u0645 \u0644\u0643\u0645 \u0645\u0627 \u0648\u0639\u062f\u062a\u0643\u0645 \u0628\u0647 \u0645\u0646 \u0627\u0644\u0631\u062d\u0645\u0629 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0627\u0644\u0646\u062c\u0627\u0629 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629. \u0648\u0625\u064a\u0651\u064e\u0627\u064a\u064e -\u0648\u062d\u062f\u064a- \u0641\u062e\u0627\u0641\u0648\u0646\u064a\u060c \u0648\u0627\u062d\u0630\u0631\u0648\u0627 \u0646\u0642\u0645\u062a\u064a \u0625\u0646 \u0646\u0642\u0636\u062a\u0645 \u0627\u0644\u0639\u0647\u062f\u060c \u0648\u0643\u0641\u0631\u062a\u0645 \u0628\u064a.","2:41":"\u0648\u0622\u0645\u0646\u0648\u0627 -\u064a\u0627 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644- \u0628\u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0630\u064a \u0623\u0646\u0632\u064e\u0644\u0652\u062a\u064f\u0647 \u0639\u0644\u0649 \u0645\u062d\u0645\u062f \u0646\u0628\u064a \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0645\u0648\u0627\u0641\u0642\u064b\u0627 \u0644\u0645\u0627 \u062a\u0639\u0644\u0645\u0648\u0646\u0647 \u0645\u0646 \u0635\u062d\u064a\u062d \u0627\u0644\u062a\u0648\u0631\u0627\u0629\u060c \u0648\u0644\u0627 \u062a\u0643\u0648\u0646\u0648\u0627 \u0623\u0648\u0644 \u0641\u0631\u064a\u0642 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u064a\u0643\u0641\u0631 \u0628\u0647\u060c \u0648\u0644\u0627 \u062a\u0633\u062a\u0628\u062f\u0644\u0648\u0627 \u0628\u0622\u064a\u0627\u062a\u064a \u062b\u0645\u0646\u064b\u0627 \u0642\u0644\u064a\u0644\u0627 \u0645\u0646 \u062d\u0637\u0627\u0645 \u0627\u0644\u062f\u0646\u064a\u0627 \u0627\u0644\u0632\u0627\u0626\u0644\u060c \u0648\u0625\u064a\u0627\u064a \u0648\u062d\u062f\u064a \u0641\u0627\u0639\u0645\u0644\u0648\u0627 \u0628\u0637\u0627\u0639\u062a\u064a \u0648\u0627\u062a\u0631\u0643\u0648\u0627 \u0645\u0639\u0635\u064a\u062a\u064a.","2:42":"\u0648\u0644\u0627 \u062a\u062e\u0644\u0650\u0637\u0648\u0627 \u0627\u0644\u062d\u0642 \u0627\u0644\u0630\u064a \u0628\u064a\u0651\u064e\u0646\u062a\u0647 \u0644\u0643\u0645 \u0628\u0627\u0644\u0628\u0627\u0637\u0644 \u0627\u0644\u0630\u064a \u0627\u0641\u062a\u0631\u064a\u062a\u0645\u0648\u0647\u060c \u0648\u0627\u062d\u0630\u0631\u0648\u0627 \u0643\u062a\u0645\u0627\u0646 \u0627\u0644\u062d\u0642 \u0627\u0644\u0635\u0631\u064a\u062d \u0645\u0646 \u0635\u0641\u0629 \u0646\u0628\u064a \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0627\u0644\u062a\u064a \u0641\u064a \u0643\u062a\u0628\u0643\u0645\u060c \u0648\u0623\u0646\u062a\u0645 \u062a\u062c\u062f\u0648\u0646\u0647\u0627 \u0645\u0643\u062a\u0648\u0628\u0629 \u0639\u0646\u062f\u0643\u0645\u060c \u0641\u064a\u0645\u0627 \u062a\u0639\u0644\u0645\u0648\u0646 \u0645\u0646 \u0627\u0644\u0643\u062a\u0628 \u0627\u0644\u062a\u064a \u0628\u0623\u064a\u062f\u064a\u0643\u0645.","2:43":"\u0648\u0627\u062f\u062e\u0644\u0648\u0627 \u0641\u064a \u062f\u064a\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645: \u0628\u0623\u0646 \u062a\u0642\u064a\u0645\u0648\u0627 \u0627\u0644\u0635\u0644\u0627\u0629 \u0639\u0644\u0649 \u0627\u0644\u0648\u062c\u0647 \u0627\u0644\u0635\u062d\u064a\u062d\u060c \u0643\u0645\u0627 \u062c\u0627\u0621 \u0628\u0647\u0627 \u0646\u0628\u064a \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u062a\u0624\u062f\u0648\u0627 \u0627\u0644\u0632\u0643\u0627\u0629 \u0627\u0644\u0645\u0641\u0631\u0648\u0636\u0629 \u0639\u0644\u0649 \u0627\u0644\u0648\u062c\u0647 \u0627\u0644\u0645\u0634\u0631\u0648\u0639\u060c \u0648\u062a\u0643\u0648\u0646\u0648\u0627 \u0645\u0639 \u0627\u0644\u0631\u0627\u0643\u0639\u064a\u0646 \u0645\u0646 \u0623\u0645\u062a\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645.","2:44":"\u0645\u0627 \u0623\u0642\u0628\u062d \u062d\u0627\u0644\u064e\u0643\u0645 \u0648\u062d\u0627\u0644\u064e \u0639\u0644\u0645\u0627\u0626\u0643\u0645 \u062d\u064a\u0646 \u062a\u0623\u0645\u0631\u0648\u0646 \u0627\u0644\u0646\u0627\u0633 \u0628\u0639\u0645\u0644 \u0627\u0644\u062e\u064a\u0631\u0627\u062a\u060c \u0648\u062a\u062a\u0631\u0643\u0648\u0646 \u0623\u0646\u0641\u0633\u0643\u0645\u060c \u0641\u0644\u0627 \u062a\u0623\u0645\u0631\u0648\u0646\u0647\u0627 \u0628\u0627\u0644\u062e\u064a\u0631 \u0627\u0644\u0639\u0638\u064a\u0645\u060c \u0648\u0647\u0648 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0648\u0623\u0646\u062a\u0645 \u062a\u0642\u0631\u0621\u0648\u0646 \u0627\u0644\u062a\u0648\u0631\u0627\u0629\u060c \u0627\u0644\u062a\u064a \u0641\u064a\u0647\u0627 \u0635\u0641\u0627\u062a \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0648\u062c\u0648\u0628 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0647!! \u0623\u0641\u0644\u0627 \u062a\u0633\u062a\u0639\u0645\u0644\u0648\u0646 \u0639\u0642\u0648\u0644\u0643\u0645 \u0627\u0633\u062a\u0639\u0645\u0627\u0644\u0627 \u0635\u062d\u064a\u062d\u064b\u0627\u061f","2:45":"\u0648\u0627\u0633\u062a\u0639\u064a\u0646\u0648\u0627 \u0641\u064a \u0643\u0644 \u0623\u0645\u0648\u0631\u0643\u0645 \u0628\u0627\u0644\u0635\u0628\u0631 \u0628\u062c\u0645\u064a\u0639 \u0623\u0646\u0648\u0627\u0639\u0647\u060c \u0648\u0643\u0630\u0644\u0643 \u0627\u0644\u0635\u0644\u0627\u0629. \u0648\u0625\u0646\u0647\u0627 \u0644\u0634\u0627\u0642\u0629 \u0625\u0644\u0627 \u0639\u0644\u0649 \u0627\u0644\u062e\u0627\u0634\u0639\u064a\u0646.","2:46":"\u0627\u0644\u0630\u064a\u0646 \u064a\u062e\u0634\u0648\u0646 \u0627\u0644\u0644\u0647 \u0648\u064a\u0631\u062c\u0648\u0646 \u0645\u0627 \u0639\u0646\u062f\u0647\u060c \u0648\u064a\u0648\u0642\u0646\u0648\u0646 \u0623\u0646\u0647\u0645 \u0645\u0644\u0627\u0642\u0648 \u0631\u0628\u0651\u0650\u0647\u0645 \u062c\u0644\u0651\u064e \u0648\u0639\u0644\u0627 \u0628\u0639\u062f \u0627\u0644\u0645\u0648\u062a\u060c \u0648\u0623\u0646\u0647\u0645 \u0625\u0644\u064a\u0647 \u0631\u0627\u062c\u0639\u0648\u0646 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u0644\u0644\u062d\u0633\u0627\u0628 \u0648\u0627\u0644\u062c\u0632\u0627\u0621.","2:47":"\u064a\u0627 \u0630\u0631\u064a\u0629 \u064a\u0639\u0642\u0648\u0628 \u062a\u0630\u0643\u0651\u064e\u0631\u0648\u0627 \u0646\u0639\u0645\u064a \u0627\u0644\u0643\u062b\u064a\u0631\u0629 \u0639\u0644\u064a\u0643\u0645\u060c \u0648\u0627\u0634\u0643\u0631\u0648\u0627 \u0644\u064a \u0639\u0644\u064a\u0647\u0627\u060c \u0648\u062a\u0630\u0643\u0631\u0648\u0627 \u0623\u0646\u064a \u0641\u064e\u0636\u0651\u064e\u0644\u0652\u062a\u0643\u0645 \u0639\u0644\u0649 \u0639\u0627\u0644\u064e\u0645\u064a \u0632\u0645\u0627\u0646\u0643\u0645 \u0628\u0643\u062b\u0631\u0629 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621\u060c \u0648\u0627\u0644\u0643\u062a\u0628 \u0627\u0644\u0645\u0646\u0632\u0651\u064e\u0644\u0629 \u0643\u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644.","2:48":"\u0648\u062e\u0627\u0641\u0648\u0627 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u064a\u0648\u0645 \u0644\u0627 \u064a\u063a\u0646\u064a \u0623\u062d\u062f \u0639\u0646 \u0623\u062d\u062f \u0634\u064a\u0626\u064b\u0627\u060c \u0648\u0644\u0627 \u064a\u0642\u0628\u0644 \u0627\u0644\u0644\u0647 \u0634\u0641\u0627\u0639\u0629 \u0641\u064a \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646\u060c \u0648\u0644\u0627 \u064a\u0642\u0628\u0644 \u0645\u0646\u0647\u0645 \u0641\u062f\u064a\u0629\u060c \u0648\u0644\u0648 \u0643\u0627\u0646\u062a \u0623\u0645\u0648\u0627\u0644 \u0627\u0644\u0623\u0631\u0636 \u062c\u0645\u064a\u0639\u064b\u0627\u060c \u0648\u0644\u0627 \u064a\u0645\u0644\u0643 \u0623\u062d\u062f \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u064a\u0648\u0645 \u0623\u0646 \u064a\u062a\u0642\u062f\u0645 \u0644\u0646\u0635\u0631\u062a\u0647\u0645 \u0648\u0625\u0646\u0642\u0627\u0630\u0647\u0645 \u0645\u0646 \u0627\u0644\u0639\u0630\u0627\u0628.","2:49":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u0646\u0639\u0645\u062a\u0646\u0627 \u0639\u0644\u064a\u0643\u0645 \u062d\u064a\u0646 \u0623\u0646\u0642\u0630\u0646\u0627\u0643\u0645 \u0645\u0646 \u0628\u0637\u0634 \u0641\u0631\u0639\u0648\u0646 \u0648\u0623\u062a\u0628\u0627\u0639\u0647\u060c \u0648\u0647\u0645 \u064a\u064f\u0630\u064a\u0642\u0648\u0646\u0643\u0645 \u0623\u0634\u062f\u0651\u064e \u0627\u0644\u0639\u0630\u0627\u0628\u060c \u0641\u064a\u064f\u0643\u062b\u0650\u0631\u0648\u0646 \u0645\u0650\u0646 \u0630\u064e\u0628\u0652\u062d \u0623\u0628\u0646\u0627\u0626\u0643\u0645\u060c \u0648\u064a\u0633\u062a\u0628\u0642\u0648\u0646 \u0646\u0633\u0627\u0621\u0643\u0645 \u0644\u0644\u062e\u062f\u0645\u0629 \u0648\u0627\u0644\u0627\u0645\u062a\u0647\u0627\u0646. \u0648\u0641\u064a \u0630\u0644\u0643 \u0627\u062e\u062a\u0628\u0627\u0631 \u0644\u0643\u0645 \u0645\u0646 \u0631\u0628\u0643\u0645\u060c \u0648\u0641\u064a \u0625\u0646\u062c\u0627\u0626\u0643\u0645 \u0645\u0646\u0647 \u0646\u0639\u0645\u0629 \u0639\u0638\u064a\u0645\u0629\u060c \u062a\u0633\u062a\u0648\u062c\u0628 \u0634\u0643\u0631 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0641\u064a \u0643\u0644 \u0639\u0635\u0648\u0631\u0643\u0645 \u0648\u0623\u062c\u064a\u0627\u0644\u0643\u0645.","2:50":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u0646\u0639\u0645\u062a\u0646\u0627 \u0639\u0644\u064a\u0643\u0645\u060c \u062d\u064a\u0646 \u0641\u064e\u0635\u064e\u0644\u0652\u0646\u0627 \u0628\u0633\u0628\u0628\u0643\u0645 \u0627\u0644\u0628\u062d\u0631\u060c \u0648\u062c\u0639\u0644\u0646\u0627 \u0641\u064a\u0647 \u0637\u0631\u0642\u064b\u0627 \u064a\u0627\u0628\u0633\u0629\u064b\u060c \u0641\u0639\u0628\u0631\u062a\u0645\u060c \u0648\u0623\u0646\u0642\u0630\u0646\u0627\u0643\u0645 \u0645\u0646 \u0641\u0631\u0639\u0648\u0646 \u0648\u062c\u0646\u0648\u062f\u0647\u060c \u0648\u0645\u0646 \u0627\u0644\u0647\u0644\u0627\u0643 \u0641\u064a \u0627\u0644\u0645\u0627\u0621. \u0641\u0644\u0645\u0627 \u062f\u062e\u0644 \u0641\u0631\u0639\u0648\u0646 \u0648\u062c\u0646\u0648\u062f\u0647 \u0637\u0631\u0642\u0643\u0645 \u0623\u0647\u0644\u0643\u0646\u0627\u0647\u0645 \u0641\u064a \u0627\u0644\u0645\u0627\u0621 \u0623\u0645\u0627\u0645 \u0623\u0639\u064a\u0646\u0643\u0645.","2:51":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u0646\u0639\u0645\u062a\u0646\u0627 \u0639\u0644\u064a\u0643\u0645: \u062d\u064a\u0646 \u0648\u0627\u0639\u062f\u0646\u0627 \u0645\u0648\u0633\u0649 \u0623\u0631\u0628\u0639\u064a\u0646 \u0644\u064a\u0644\u0629 \u0644\u0625\u0646\u0632\u0627\u0644 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0647\u062f\u0627\u064a\u0629\u064b \u0648\u0646\u0648\u0631\u064b\u0627 \u0644\u0643\u0645\u060c \u0641\u0625\u0630\u0627 \u0628\u0643\u0645 \u062a\u0646\u062a\u0647\u0632\u0648\u0646 \u0641\u0631\u0635\u0629 \u063a\u064a\u0627\u0628\u0647 \u0647\u0630\u0647 \u0627\u0644\u0645\u062f\u0629 \u0627\u0644\u0642\u0644\u064a\u0644\u0629\u060c \u0648\u062a\u062c\u0639\u0644\u0648\u0646 \u0627\u0644\u0639\u062c\u0644 \u0627\u0644\u0630\u064a \u0635\u0646\u0639\u062a\u0645\u0648\u0647 \u0628\u0623\u064a\u062f\u064a\u0643\u0645 \u0645\u0639\u0628\u0648\u062f\u064b\u0627 \u0644\u0643\u0645 \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647 -\u0648\u0647\u0630\u0627 \u0623\u0634\u0646\u0639 \u0627\u0644\u0643\u0641\u0631 \u0628\u0627\u0644\u0644\u0647- \u0648\u0623\u0646\u062a\u0645 \u0638\u0627\u0644\u0645\u0648\u0646 \u0628\u0627\u062a\u062e\u0627\u0630\u0643\u0645 \u0627\u0644\u0639\u062c\u0644 \u0625\u0644\u0647\u064b\u0627.","2:52":"\u062b\u0645\u0651\u064e \u062a\u062c\u0627\u0648\u0632\u0646\u0627 \u0639\u0646 \u0647\u0630\u0647 \u0627\u0644\u0641\u0639\u0644\u0629 \u0627\u0644\u0645\u0646\u0643\u0631\u0629\u060c \u0648\u0642\u064e\u0628\u0650\u0644\u0652\u0646\u064e\u0627 \u062a\u0648\u0628\u062a\u0643\u0645 \u0628\u0639\u062f \u0639\u0648\u062f\u0629 \u0645\u0648\u0633\u0649; \u0631\u062c\u0627\u0621\u064e \u0623\u0646 \u062a\u0634\u0643\u0631\u0648\u0627 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0646\u0639\u0645\u0647 \u0648\u0623\u0641\u0636\u0627\u0644\u0647\u060c \u0648\u0644\u0627 \u062a\u062a\u0645\u0627\u062f\u0648\u0627 \u0641\u064a \u0627\u0644\u0643\u0641\u0631 \u0648\u0627\u0644\u0637\u063a\u064a\u0627\u0646.","2:53":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u0646\u0639\u0645\u062a\u0646\u0627 \u0639\u0644\u064a\u0643\u0645 \u062d\u064a\u0646 \u0623\u0639\u0637\u064a\u0646\u0627 \u0645\u0648\u0633\u0649 \u0627\u0644\u0643\u062a\u0627\u0628 \u0627\u0644\u0641\u0627\u0631\u0642 \u0628\u064a\u0646 \u0627\u0644\u062d\u0642 \u0648\u0627\u0644\u0628\u0627\u0637\u0644 -\u0648\u0647\u0648 \u0627\u0644\u062a\u0648\u0631\u0627\u0629-; \u0644\u0643\u064a \u062a\u0647\u062a\u062f\u0648\u0627 \u0645\u0646 \u0627\u0644\u0636\u0644\u0627\u0644\u0629.","2:54":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u0646\u0639\u0645\u062a\u0646\u0627 \u0639\u0644\u064a\u0643\u0645 \u062d\u064a\u0646 \u0642\u0627\u0644 \u0645\u0648\u0633\u0649 \u0644\u0642\u0648\u0645\u0647: \u0625\u0646\u0643\u0645 \u0638\u0644\u0645\u062a\u0645 \u0623\u0646\u0641\u0633\u0643\u0645 \u0628\u0627\u062a\u062e\u0627\u0630\u0643\u0645 \u0627\u0644\u0639\u062c\u0644 \u0625\u0644\u0647\u064b\u0627\u060c \u0641\u062a\u0648\u0628\u0648\u0627 \u0625\u0644\u0649 \u062e\u0627\u0644\u0642\u0643\u0645: \u0628\u0623\u0646 \u064a\u064e\u0642\u0652\u062a\u0644 \u0628\u0639\u0636\u0643\u0645 \u0628\u0639\u0636\u064b\u0627\u060c \u0648\u0647\u0630\u0627 \u062e\u064a\u0631 \u0644\u0643\u0645 \u0639\u0646\u062f \u062e\u0627\u0644\u0642\u0643\u0645 \u0645\u0646 \u0627\u0644\u062e\u0644\u0648\u062f \u0627\u0644\u0623\u0628\u062f\u064a \u0641\u064a \u0627\u0644\u0646\u0627\u0631\u060c \u0641\u0627\u0645\u062a\u062b\u0644\u062a\u0645 \u0630\u0644\u0643\u060c \u0641\u0645\u0646\u0651\u064e \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0628\u0642\u064e\u0628\u0648\u0644 \u062a\u0648\u0628\u062a\u0643\u0645. \u0625\u0646\u0647 \u062a\u0639\u0627\u0644\u0649 \u0647\u0648 \u0627\u0644\u062a\u0648\u0627\u0628 \u0644\u0645\u0646 \u062a\u0627\u0628 \u0645\u0650\u0646 \u0639\u0628\u0627\u062f\u0647\u060c \u0627\u0644\u0631\u062d\u064a\u0645 \u0628\u0647\u0645.","2:55":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u0625\u0630 \u0642\u0644\u062a\u0645: \u064a\u0627 \u0645\u0648\u0633\u0649 \u0644\u0646 \u0646\u0635\u062f\u0642\u0643 \u0641\u064a \u0623\u0646 \u0627\u0644\u0643\u0644\u0627\u0645 \u0627\u0644\u0630\u064a \u0646\u0633\u0645\u0639\u0647 \u0645\u0646\u0643 \u0647\u0648 \u0643\u0644\u0627\u0645 \u0627\u0644\u0644\u0647\u060c \u062d\u062a\u0649 \u0646\u0631\u0649 \u0627\u0644\u0644\u0647 \u0639\u0650\u064a\u064e\u0627\u0646\u064b\u0627\u060c \u0641\u0646\u0632\u0644\u062a \u0646\u0627\u0631 \u0645\u0646 \u0627\u0644\u0633\u0645\u0627\u0621 \u0631\u0623\u064a\u062a\u0645\u0648\u0647\u0627 \u0628\u0623\u0639\u064a\u0646\u0643\u0645\u060c \u0641\u0642\u064e\u062a\u064e\u0644\u064e\u062a\u0652\u0643\u0645 \u0628\u0633\u0628\u0628 \u0630\u0646\u0648\u0628\u0643\u0645\u060c \u0648\u062c\u064f\u0631\u0652\u0623\u062a\u0643\u0645 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649.","2:56":"\u062b\u0645 \u0623\u062d\u064a\u064a\u0646\u0627\u0643\u0645 \u0645\u0650\u0646 \u0628\u0639\u062f \u0645\u0648\u062a\u0643\u0645 \u0628\u0627\u0644\u0635\u0627\u0639\u0642\u0629; \u0644\u062a\u0634\u0643\u0631\u0648\u0627 \u0646\u0639\u0645\u0629 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645\u060c \u0641\u0647\u0630\u0627 \u0627\u0644\u0645\u0648\u062a \u0639\u0642\u0648\u0628\u0629 \u0644\u0647\u0645\u060c \u062b\u0645 \u0628\u0639\u062b\u0647\u0645 \u0627\u0644\u0644\u0647 \u0644\u0627\u0633\u062a\u064a\u0641\u0627\u0621 \u0622\u062c\u0627\u0644\u0647\u0645.","2:57":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u0646\u0639\u0645\u062a\u0646\u0627 \u0639\u0644\u064a\u0643\u0645 \u062d\u064a\u0646 \u0643\u0646\u062a\u0645 \u062a\u062a\u064a\u0647\u0648\u0646 \u0641\u064a \u0627\u0644\u0623\u0631\u0636; \u0625\u0630 \u062c\u0639\u0644\u0646\u0627 \u0627\u0644\u0633\u062d\u0627\u0628 \u0645\u0638\u0644\u0644\u0627 \u0639\u0644\u064a\u0643\u0645 \u0645\u0646 \u062d\u064e\u0631\u0651\u0650 \u0627\u0644\u0634\u0645\u0633\u060c \u0648\u0623\u0646\u0632\u0644\u0646\u0627 \u0639\u0644\u064a\u0643\u0645 \u0627\u0644\u0645\u0646\u0651\u064e\u060c \u0648\u0647\u0648 \u0634\u064a\u0621 \u064a\u0634\u0628\u0647 \u0627\u0644\u0635\u0651\u064e\u0645\u063a \u0637\u0639\u0645\u0647 \u0643\u0627\u0644\u0639\u0633\u0644\u060c \u0648\u0623\u0646\u0632\u0644\u0646\u0627 \u0639\u0644\u064a\u0643\u0645 \u0627\u0644\u0633\u0651\u064e\u0644\u0648\u0649 \u0648\u0647\u0648 \u0637\u064a\u0631 \u064a\u0634\u0628\u0647 \u0627\u0644\u0633\u0651\u064f\u0645\u0627\u0646\u064e\u0649\u060c \u0648\u0642\u0644\u0646\u0627 \u0644\u0643\u0645: \u0643\u0644\u0648\u0627 \u0645\u0646 \u0637\u064a\u0651\u0650\u0628\u0627\u062a \u0645\u0627 \u0631\u0632\u0642\u0646\u0627\u0643\u0645\u060c \u0648\u0644\u0627 \u062a\u062e\u0627\u0644\u0641\u0648\u0627 \u062f\u064a\u0646\u0643\u0645\u060c \u0641\u0644\u0645 \u062a\u0645\u062a\u062b\u0644\u0648\u0627. \u0648\u0645\u0627 \u0638\u0644\u0645\u0648\u0646\u0627 \u0628\u0643\u0641\u0631\u0627\u0646 \u0627\u0644\u0646\u0639\u0645\u060c \u0648\u0644\u0643\u0646 \u0643\u0627\u0646\u0648\u0627 \u0623\u0646\u0641\u0633\u0647\u0645 \u064a\u0638\u0644\u0645\u0648\u0646; \u0644\u0623\u0646 \u0639\u0627\u0642\u0628\u0629 \u0627\u0644\u0638\u0644\u0645 \u0639\u0627\u0626\u062f\u0629 \u0639\u0644\u064a\u0647\u0645.","2:58":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u0646\u0639\u0645\u062a\u0646\u0627 \u0639\u0644\u064a\u0643\u0645 \u062d\u064a\u0646 \u0642\u0644\u0646\u0627: \u0627\u062f\u062e\u0644\u0648\u0627 \u0645\u062f\u064a\u0646\u0629 \xab\u0628\u064a\u062a \u0627\u0644\u0645\u0642\u062f\u0633\xbb \u0641\u0643\u0644\u0648\u0627 \u0645\u0646 \u0637\u064a\u0628\u0627\u062a\u0647\u0627 \u0641\u064a \u0623\u064a \u0645\u0643\u0627\u0646 \u0645\u0646\u0647\u0627 \u0623\u0643\u0644\u0627 \u0647\u0646\u064a\u0626\u064b\u0627\u060c \u0648\u0643\u0648\u0646\u0648\u0627 \u0641\u064a \u062f\u062e\u0648\u0644\u0643\u0645 \u062e\u0627\u0636\u0639\u064a\u0646 \u0644\u0644\u0647\u060c \u0630\u0644\u064a\u0644\u064a\u0646 \u0644\u0647\u060c \u0648\u0642\u0648\u0644\u0648\u0627: \u0631\u0628\u0651\u064e\u0646\u0627 \u0636\u064e\u0639\u0652 \u0639\u0646\u0651\u064e\u0627 \u0630\u0646\u0648\u0628\u0646\u0627\u060c \u0646\u0633\u062a\u062c\u0628 \u0644\u0643\u0645 \u0648\u0646\u0639\u0641 \u0639\u0646\u0643\u0645 \u0648\u0646\u0633\u062a\u0631\u0647\u0627 \u0639\u0644\u064a\u0643\u0645\u060c \u0648\u0633\u0646\u0632\u064a\u062f \u0627\u0644\u0645\u062d\u0633\u0646\u064a\u0646 \u0628\u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u062e\u064a\u0631\u064b\u0627 \u0648\u062b\u0648\u0627\u0628\u064b\u0627.","2:59":"\u0641\u0628\u062f\u0651\u064e\u0644 \u0627\u0644\u062c\u0627\u0626\u0631\u0648\u0646 \u0627\u0644\u0636\u0627\u0644\u0648\u0646 \u0645\u0646 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0642\u0648\u0644 \u0627\u0644\u0644\u0647\u060c \u0648\u062d\u0631\u0651\u064e\u0641\u0648\u0627 \u0627\u0644\u0642\u0648\u0644 \u0648\u0627\u0644\u0641\u0639\u0644 \u062c\u0645\u064a\u0639\u064b\u0627\u060c \u0625\u0630 \u062f\u062e\u0644\u0648\u0627 \u064a\u0632\u062d\u0641\u0648\u0646 \u0639\u0644\u0649 \u0623\u0633\u062a\u0627\u0647\u0647\u0645 \u0648\u0642\u0627\u0644\u0648\u0627: \u062d\u0628\u0629 \u0641\u064a \u0634\u0639\u0631\u0629\u060c \u0648\u0627\u0633\u062a\u0647\u0632\u0621\u0648\u0627 \u0628\u062f\u064a\u0646 \u0627\u0644\u0644\u0647. \u0641\u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645 \u0639\u0630\u0627\u0628\u064b\u0627 \u0645\u0646 \u0627\u0644\u0633\u0645\u0627\u0621; \u0628\u0633\u0628\u0628 \u062a\u0645\u0631\u062f\u0647\u0645 \u0648\u062e\u0631\u0648\u062c\u0647\u0645 \u0639\u0646 \u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647.","2:60":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u0646\u0639\u0645\u062a\u0646\u0627 \u0639\u0644\u064a\u0643\u0645 -\u0648\u0623\u0646\u062a\u0645 \u0639\u0637\u0627\u0634 \u0641\u064a \u0627\u0644\u062a\u0651\u0650\u064a\u0652\u0647- \u062d\u064a\u0646 \u062f\u0639\u0627\u0646\u0627 \u0645\u0648\u0633\u0649 -\u0628\u0636\u0631\u0627\u0639\u0629- \u0623\u0646 \u0646\u0633\u0642\u064a \u0642\u0648\u0645\u0647\u060c \u0641\u0642\u0644\u0646\u0627: \u0627\u0636\u0631\u0628 \u0628\u0639\u0635\u0627\u0643 \u0627\u0644\u062d\u062c\u0631\u060c \u0641\u0636\u0631\u0628\u060c \u0641\u0627\u0646\u0641\u062c\u0631\u062a \u0645\u0646\u0647 \u0627\u062b\u0646\u062a\u0627 \u0639\u0634\u0631\u0629 \u0639\u064a\u0646\u064b\u0627\u060c \u0628\u0639\u062f\u062f \u0627\u0644\u0642\u0628\u0627\u0626\u0644\u060c \u0645\u0639 \u0625\u0639\u0644\u0627\u0645 \u0643\u0644 \u0642\u0628\u064a\u0644\u0629 \u0628\u0627\u0644\u0639\u064a\u0646 \u0627\u0644\u062e\u0627\u0635\u0629 \u0628\u0647\u0627 \u062d\u062a\u0649 \u0644\u0627 \u064a\u062a\u0646\u0627\u0632\u0639\u0648\u0627. \u0648\u0642\u0644\u0646\u0627 \u0644\u0647\u0645: \u0643\u0644\u0648\u0627 \u0648\u0627\u0634\u0631\u0628\u0648\u0627 \u0645\u0646 \u0631\u0632\u0642 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0627 \u062a\u0633\u0639\u0648\u0627 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0645\u0641\u0633\u062f\u064a\u0646.","2:61":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u062d\u064a\u0646 \u0623\u0646\u0632\u0644\u0646\u0627 \u0639\u0644\u064a\u0643\u0645 \u0627\u0644\u0637\u0639\u0627\u0645 \u0627\u0644\u062d\u0644\u0648\u060c \u0648\u0627\u0644\u0637\u064a\u0631 \u0627\u0644\u0634\u0647\u064a\u060c \u0641\u0628\u0637\u0650\u0631\u062a\u0645 \u0627\u0644\u0646\u0639\u0645\u0629 \u0643\u0639\u0627\u062f\u062a\u0643\u0645\u060c \u0648\u0623\u0635\u0627\u0628\u0643\u0645 \u0627\u0644\u0636\u064a\u0642 \u0648\u0627\u0644\u0645\u0644\u0644\u060c \u0641\u0642\u0644\u062a\u0645: \u064a\u0627 \u0645\u0648\u0633\u0649 \u0644\u0646 \u0646\u0635\u0628\u0631 \u0639\u0644\u0649 \u0637\u0639\u0627\u0645 \u062b\u0627\u0628\u062a \u0644\u0627 \u064a\u062a\u063a\u064a\u0631 \u0645\u0639 \u0627\u0644\u0623\u064a\u0627\u0645\u060c \u0641\u0627\u062f\u0639 \u0644\u0646\u0627 \u0631\u0628\u0643 \u064a\u062e\u0631\u062c \u0644\u0646\u0627 \u0645\u0646 \u0646\u0628\u0627\u062a \u0627\u0644\u0623\u0631\u0636 \u0637\u0639\u0627\u0645\u064b\u0627 \u0645\u0646 \u0627\u0644\u0628\u0642\u0648\u0644 \u0648\u0627\u0644\u062e\u064f\u0636\u064e\u0631\u060c \u0648\u0627\u0644\u0642\u062b\u0627\u0621 \u0648\u0627\u0644\u062d\u0628\u0648\u0628 \u0627\u0644\u062a\u064a \u062a\u0624\u0643\u0644\u060c \u0648\u0627\u0644\u0639\u062f\u0633\u060c \u0648\u0627\u0644\u0628\u0635\u0644. \u0642\u0627\u0644 \u0645\u0648\u0633\u0649 -\u0645\u0633\u062a\u0646\u0643\u0631\u064b\u0627 \u0639\u0644\u064a\u0647\u0645-: \u0623\u062a\u0637\u0644\u0628\u0648\u0646 \u0647\u0630\u0647 \u0627\u0644\u0623\u0637\u0639\u0645\u0629 \u0627\u0644\u062a\u064a \u0647\u064a \u0623\u0642\u0644 \u0642\u062f\u0631\u064b\u0627\u060c \u0648\u062a\u062a\u0631\u0643\u0648\u0646 \u0647\u0630\u0627 \u0627\u0644\u0631\u0632\u0642 \u0627\u0644\u0646\u0627\u0641\u0639 \u0627\u0644\u0630\u064a \u0627\u062e\u062a\u0627\u0631\u0647 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645\u061f \u0627\u0647\u0628\u0637\u0648\u0627 \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0628\u0627\u062f\u064a\u0629 \u0625\u0644\u0649 \u0623\u064a \u0645\u062f\u064a\u0646\u0629\u060c \u062a\u062c\u062f\u0648\u0627 \u0645\u0627 \u0627\u0634\u062a\u0647\u064a\u062a\u0645 \u0643\u062b\u064a\u0631\u064b\u0627 \u0641\u064a \u0627\u0644\u062d\u0642\u0648\u0644 \u0648\u0627\u0644\u0623\u0633\u0648\u0627\u0642. \u0648\u0644\u0645\u0627 \u0647\u0628\u0637\u0648\u0627 \u062a\u0628\u064a\u0651\u064e\u0646 \u0644\u0647\u0645 \u0623\u0646\u0647\u0645 \u064a\u064f\u0642\u064e\u062f\u0651\u0650\u0645\u0648\u0646 \u0627\u062e\u062a\u064a\u0627\u0631\u0647\u0645 -\u0641\u064a \u0643\u0644 \u0645\u0648\u0637\u0646- \u0639\u0644\u0649 \u0627\u062e\u062a\u064a\u0627\u0631 \u0627\u0644\u0644\u0647\u060c \u0648\u064a\u064f\u0624\u0652\u062b\u0650\u0631\u0648\u0646 \u0634\u0647\u0648\u0627\u062a\u0647\u0645 \u0639\u0644\u0649 \u0645\u0627 \u0627\u062e\u062a\u0627\u0631\u0647 \u0627\u0644\u0644\u0647 \u0644\u0647\u0645; \u0644\u0630\u0644\u0643 \u0644\u0632\u0645\u062a\u0647\u0645 \u0635\u0650\u0641\u064e\u0629\u064f \u0627\u0644\u0630\u0644 \u0648\u0641\u0642\u0631 \u0627\u0644\u0646\u0641\u0648\u0633\u060c \u0648\u0627\u0646\u0635\u0631\u0641\u0648\u0627 \u0648\u0631\u062c\u0639\u0648\u0627 \u0628\u063a\u0636\u0628 \u0645\u0646 \u0627\u0644\u0644\u0647; \u0644\u0625\u0639\u0631\u0627\u0636\u0647\u0645 \u0639\u0646 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0623\u0646\u0647\u0645 \u0643\u0627\u0646\u0648\u0627 \u064a\u0643\u0641\u0631\u0648\u0646 \u0628\u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0648\u064a\u0642\u062a\u0644\u0648\u0646 \u0627\u0644\u0646\u0628\u064a\u064a\u0646 \u0638\u0644\u0645\u064b\u0627 \u0648\u0639\u062f\u0648\u0627\u0646\u064b\u0627; \u0648\u0630\u0644\u0643 \u0628\u0633\u0628\u0628 \u0639\u0635\u064a\u0627\u0646\u0647\u0645 \u0648\u062a\u062c\u0627\u0648\u0632\u0647\u0645 \u062d\u062f\u0648\u062f \u0631\u0628\u0647\u0645.","2:62":"\u0625\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0623\u0645\u0629\u060c \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0644\u0647\u060c \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647\u060c \u0648\u0627\u0644\u0630\u064a\u0646 \u0643\u0627\u0646\u0648\u0627 \u0642\u0628\u0644 \u0628\u0639\u062b\u0629 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0645\u0646 \u0627\u0644\u0623\u0645\u0645 \u0627\u0644\u0633\u0627\u0644\u0641\u0629 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f\u060c \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649\u060c \u0648\u0627\u0644\u0635\u0627\u0628\u0626\u064a\u0646 -\u0648\u0647\u0645 \u0642\u0648\u0645 \u0628\u0627\u0642\u0648\u0646 \u0639\u0644\u0649 \u0641\u0637\u0631\u062a\u0647\u0645\u060c \u0648\u0644\u0627 \u062f\u064a\u0646 \u0645\u0642\u0631\u0631 \u0644\u0647\u0645 \u064a\u062a\u0628\u0639\u0648\u0646\u0647- \u0647\u0624\u0644\u0627\u0621 \u062c\u0645\u064a\u0639\u064b\u0627 \u0625\u0630\u0627 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u062a\u0635\u062f\u064a\u0642\u064b\u0627 \u0635\u062d\u064a\u062d\u064b\u0627 \u062e\u0627\u0644\u0635\u064b\u0627\u060c \u0648\u0628\u064a\u0648\u0645 \u0627\u0644\u0628\u0639\u062b \u0648\u0627\u0644\u062c\u0632\u0627\u0621\u060c \u0648\u0639\u0645\u0644\u0648\u0627 \u0639\u0645\u0644\u0627 \u0645\u0631\u0636\u064a\u064b\u0627 \u0639\u0646\u062f \u0627\u0644\u0644\u0647\u060c \u0641\u062b\u0648\u0627\u0628\u0647\u0645 \u062b\u0627\u0628\u062a \u0644\u0647\u0645 \u0639\u0646\u062f \u0631\u0628\u0647\u0645\u060c \u0648\u0644\u0627 \u062e\u0648\u0641 \u0639\u0644\u064a\u0647\u0645 \u0641\u064a\u0645\u0627 \u064a\u0633\u062a\u0642\u0628\u0644\u0648\u0646\u0647 \u0645\u0646 \u0623\u0645\u0631 \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u0644\u0627 \u0647\u0645 \u064a\u062d\u0632\u0646\u0648\u0646 \u0639\u0644\u0649 \u0645\u0627 \u0641\u0627\u062a\u0647\u0645 \u0645\u0646 \u0623\u0645\u0648\u0631 \u0627\u0644\u062f\u0646\u064a\u0627. \u0648\u0623\u0645\u0627 \u0628\u0639\u062f \u0628\u0639\u062b\u0629 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u062e\u0627\u062a\u0645\u064b\u0627 \u0644\u0644\u0646\u0628\u064a\u064a\u0646 \u0648\u0627\u0644\u0645\u0631\u0633\u0644\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u0646\u0627\u0633 \u0643\u0627\u0641\u0629\u060c \u0641\u0644\u0627 \u064a\u0642\u0628\u0644 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0623\u062d\u062f \u062f\u064a\u0646\u064b\u0627 \u063a\u064a\u0631 \u0645\u0627 \u062c\u0627\u0621 \u0628\u0647\u060c \u0648\u0647\u0648 \u0627\u0644\u0625\u0633\u0644\u0627\u0645.","2:63":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 -\u064a\u0627 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644- \u062d\u064a\u0646 \u0623\u064e\u062e\u064e\u0630\u0652\u0646\u0627 \u0627\u0644\u0639\u0647\u062f \u0627\u0644\u0645\u0624\u0643\u0651\u064e\u062f \u0645\u0646\u0643\u0645 \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0625\u0641\u0631\u0627\u062f\u0647 \u0628\u0627\u0644\u0639\u0628\u0627\u062f\u0629\u060c \u0648\u0631\u0641\u0639\u0646\u0627 \u062c\u0628\u0644 \u0627\u0644\u0637\u0648\u0631 \u0641\u0648\u0642\u0643\u0645\u060c \u0648\u0642\u0644\u0646\u0627 \u0644\u0643\u0645: \u062e\u0630\u0648\u0627 \u0627\u0644\u0643\u062a\u0627\u0628 \u0627\u0644\u0630\u064a \u0623\u0639\u0637\u064a\u0646\u0627\u0643\u0645 \u0628\u062c\u062f\u064d \u0648\u0627\u062c\u062a\u0647\u0627\u062f \u0648\u0627\u062d\u0641\u0638\u0648\u0647\u060c \u0648\u0625\u0644\u0627 \u0623\u0637\u0628\u0642\u0646\u0627 \u0639\u0644\u064a\u0643\u0645 \u0627\u0644\u062c\u0628\u0644\u060c \u0648\u0644\u0627 \u062a\u0646\u0633\u0648\u0627 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0642\u0648\u0644\u0627 \u0648\u0639\u0645\u0644\u0627 \u0643\u064a \u062a\u062a\u0642\u0648\u0646\u064a \u0648\u062a\u062e\u0627\u0641\u0648\u0627 \u0639\u0642\u0627\u0628\u064a.","2:64":"\u062b\u0645 \u062e\u0627\u0644\u0641\u062a\u0645 \u0648\u0639\u0635\u064a\u062a\u0645 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649\u060c \u0628\u0639\u062f \u0623\u064e\u062e\u0652\u0630\u0650 \u0627\u0644\u0645\u064a\u062b\u0627\u0642 \u0648\u0631\u064e\u0641\u0652\u0639 \u0627\u0644\u062c\u0628\u0644 \u0643\u0634\u0623\u0646\u0643\u0645 \u062f\u0627\u0626\u0645\u064b\u0627. \u0641\u0644\u0648\u0644\u0627 \u0641\u064e\u0636\u0652\u0644\u064f \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0648\u0631\u062d\u0645\u062a\u0647 \u0628\u0627\u0644\u062a\u0648\u0628\u0629\u060c \u0648\u0627\u0644\u062a\u062c\u0627\u0648\u0632 \u0639\u0646 \u062e\u0637\u0627\u064a\u0627\u0643\u0645\u060c \u0644\u0635\u0631\u062a\u0645 \u0645\u0646 \u0627\u0644\u062e\u0627\u0633\u0631\u064a\u0646 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629.","2:65":"\u0648\u0644\u0642\u062f \u0639\u0644\u0645\u062a\u0645 -\u064a\u0627 \u0645\u0639\u0634\u0631 \u0627\u0644\u064a\u0647\u0648\u062f- \u0645\u0627 \u062d\u0644\u0651\u064e \u0645\u0646 \u0627\u0644\u0628\u0623\u0633 \u0628\u0623\u0633\u0644\u0627\u0641\u0643\u0645 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0642\u0631\u064a\u0629 \u0627\u0644\u062a\u064a \u0639\u0635\u062a \u0627\u0644\u0644\u0647\u060c \u0641\u064a\u0645\u0627 \u0623\u062e\u0630\u0647 \u0639\u0644\u064a\u0647\u0645 \u0645\u0646 \u062a\u0639\u0638\u064a\u0645 \u0627\u0644\u0633\u0628\u062a\u060c \u0641\u0627\u062d\u062a\u0627\u0644\u0648\u0627 \u0644\u0627\u0635\u0637\u064a\u0627\u062f \u0627\u0644\u0633\u0645\u0643 \u0641\u064a \u064a\u0648\u0645 \u0627\u0644\u0633\u0628\u062a\u060c \u0628\u0648\u0636\u0639 \u0627\u0644\u0634\u0651\u0650\u0628\u0627\u0643 \u0648\u062d\u0641\u0631 \u0627\u0644\u0628\u0650\u0631\u064e\u0643\u060c \u062b\u0645 \u0627\u0635\u0637\u0627\u062f\u0648\u0627 \u0627\u0644\u0633\u0645\u0643 \u064a\u0648\u0645 \u0627\u0644\u0623\u062d\u062f \u062d\u064a\u0644\u0629 \u0625\u0644\u0649 \u0627\u0644\u0645\u062d\u0631\u0645\u060c \u0641\u0644\u0645\u0627 \u0641\u0639\u0644\u0648\u0627 \u0630\u0644\u0643\u060c \u0645\u0633\u062e\u0647\u0645 \u0627\u0644\u0644\u0647 \u0642\u0631\u062f\u0629 \u0645\u0646\u0628\u0648\u0630\u064a\u0646.","2:66":"\u0641\u062c\u0639\u0644\u0646\u0627 \u0647\u0630\u0647 \u0627\u0644\u0642\u0631\u064a\u0629 \u0639\u0628\u0631\u0629 \u0644\u0645\u0646 \u0628\u062d\u0636\u0631\u062a\u0647\u0627 \u0645\u0646 \u0627\u0644\u0642\u0631\u0649\u060c \u064a\u0628\u0644\u063a\u0647\u0645 \u062e\u0628\u0631\u0647\u0627 \u0648\u0645\u0627 \u062d\u0644\u0651\u064e \u0628\u0647\u0627\u060c \u0648\u0639\u0628\u0631\u0629 \u0644\u0645\u0646 \u064a\u0639\u0645\u0644 \u0628\u0639\u062f\u0647\u0627 \u0645\u062b\u0644 \u062a\u0644\u0643 \u0627\u0644\u0630\u0651\u064f\u0646\u0648\u0628\u060c \u0648\u062c\u0639\u0644\u0646\u0627\u0647\u0627 \u062a\u0630\u0643\u0631\u0629 \u0644\u0644\u0635\u0627\u0644\u062d\u064a\u0646; \u0644\u064a\u0639\u0644\u0645\u0648\u0627 \u0623\u0646\u0647\u0645 \u0639\u0644\u0649 \u0627\u0644\u062d\u0642\u060c \u0641\u064a\u062b\u0628\u062a\u0648\u0627 \u0639\u0644\u064a\u0647.","2:67":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 -\u064a\u0627 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644- \u062c\u0646\u0627\u064a\u0629 \u0623\u0633\u0644\u0627\u0641\u0643\u0645\u060c \u0648\u0643\u062b\u0631\u0629 \u062a\u0639\u0646\u062a\u0647\u0645 \u0648\u062c\u062f\u0627\u0644\u0647\u0645 \u0644\u0645\u0648\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0627\u0644\u0633\u0644\u0627\u0645\u060c \u062d\u064a\u0646 \u0642\u0627\u0644 \u0644\u0647\u0645: \u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u0623\u0645\u0631\u0643\u0645 \u0623\u0646 \u062a\u0630\u0628\u062d\u0648\u0627 \u0628\u0642\u0631\u0629\u060c \u0641\u0642\u0627\u0644\u0648\u0627 -\u0645\u0633\u062a\u0643\u0628\u0631\u064a\u0646-: \u0623\u062a\u062c\u0639\u0644\u0646\u0627 \u0645\u0648\u0636\u0639\u064b\u0627 \u0644\u0644\u0633\u062e\u0631\u064a\u0629 \u0648\u0627\u0644\u0627\u0633\u062a\u062e\u0641\u0627\u0641\u061f \u0641\u0631\u062f\u0651\u064e \u0639\u0644\u064a\u0647\u0645 \u0645\u0648\u0633\u0649 \u0628\u0642\u0648\u0644\u0647: \u0623\u0633\u062a\u062c\u064a\u0631 \u0628\u0627\u0644\u0644\u0647 \u0623\u0646 \u0623\u0643\u0648\u0646 \u0645\u0646 \u0627\u0644\u0645\u0633\u062a\u0647\u0632\u0626\u064a\u0646.","2:68":"\u0642\u0627\u0644\u0648\u0627: \u0627\u062f\u0639 \u0644\u0646\u0627 \u0631\u0628\u0651\u064e\u0643 \u064a\u0648\u0636\u062d \u0644\u0646\u0627 \u0635\u0641\u0629 \u0647\u0630\u0647 \u0627\u0644\u0628\u0642\u0631\u0629\u060c \u0641\u0623\u062c\u0627\u0628\u0647\u0645: \u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u0642\u0648\u0644 \u0644\u0643\u0645: \u0635\u0641\u062a\u0647\u0627 \u0623\u0644\u0627 \u062a\u0643\u0648\u0646 \u0645\u0633\u0646\u0651\u064e\u0629 \u0647\u064e\u0631\u0650\u0645\u0629\u060c \u0648\u0644\u0627 \u0635\u063a\u064a\u0631\u0629 \u0641\u064e\u062a\u0650\u064a\u0651\u064e\u0629\u060c \u0648\u0625\u0646\u0645\u0627 \u0647\u064a \u0645\u062a\u0648\u0633\u0637\u0629 \u0628\u064a\u0646\u0647\u0645\u0627\u060c \u0641\u0633\u0627\u0631\u0650\u0639\u0648\u0627 \u0625\u0644\u0649 \u0627\u0645\u062a\u062b\u0627\u0644 \u0623\u0645\u0631 \u0631\u0628\u0643\u0645.","2:69":"\u0641\u0639\u0627\u062f\u0648\u0627 \u0625\u0644\u0649 \u062c\u062f\u0627\u0644\u0647\u0645 \u0642\u0627\u0626\u0644\u064a\u0646: \u0627\u062f\u0639 \u0644\u0646\u0627 \u0631\u0628\u0643 \u064a\u0648\u0636\u062d \u0644\u0646\u0627 \u0644\u0648\u0646\u0647\u0627. \u0642\u0627\u0644: \u0625\u0646\u0647 \u064a\u0642\u0648\u0644: \u0625\u0646\u0647\u0627 \u0628\u0642\u0631\u0629 \u0635\u0641\u0631\u0627\u0621 \u0634\u062f\u064a\u062f\u0629 \u0627\u0644\u0635\u0651\u064f\u0641\u0652\u0631\u0629\u060c \u062a\u064e\u0633\u064f\u0631\u0651\u064f \u0645\u064e\u0646 \u064a\u0646\u0638\u0631 \u0625\u0644\u064a\u0647\u0627.","2:70":"\u0642\u0627\u0644 \u0628\u0646\u0648 \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0644\u0645\u0648\u0633\u0649: \u0627\u062f\u0639 \u0644\u0646\u0627 \u0631\u0628\u0643 \u064a\u0648\u0636\u062d \u0644\u0646\u0627 \u0635\u0641\u0627\u062a \u0623\u062e\u0631\u0649 \u063a\u064a\u0631 \u0645\u0627 \u0633\u0628\u0642; \u0644\u0623\u0646 \u0627\u0644\u0628\u0642\u0631 -\u0628\u0647\u0630\u0647 \u0627\u0644\u0635\u0641\u0627\u062a- \u0643\u062b\u064a\u0631 \u0641\u0627\u0634\u0652\u062a\u064e\u0628\u064e\u0647\u064e \u0639\u0644\u064a\u0646\u0627 \u0645\u0627\u0630\u0627 \u0646\u062e\u062a\u0627\u0631\u061f \u0648\u0625\u0646\u0646\u0627 -\u0625\u0646 \u0634\u0627\u0621 \u0627\u0644\u0644\u0647- \u0644\u0645\u0647\u062a\u062f\u0648\u0646 \u0625\u0644\u0649 \u0627\u0644\u0628\u0642\u0631\u0629 \u0627\u0644\u0645\u0623\u0645\u0648\u0631 \u0628\u0630\u0628\u062d\u0647\u0627.","2:71":"\u0642\u0627\u0644 \u0644\u0647\u0645 \u0645\u0648\u0633\u0649: \u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u0642\u0648\u0644: \u0625\u0646\u0647\u0627 \u0628\u0642\u0631\u0629 \u063a\u064a\u0631 \u0645\u0630\u0644\u0644\u0629 \u0644\u0644\u0639\u0645\u0644 \u0641\u064a \u062d\u0631\u0627\u062b\u0629 \u0627\u0644\u0623\u0631\u0636 \u0644\u0644\u0632\u0631\u0627\u0639\u0629\u060c \u0648\u063a\u064a\u0631 \u0645\u0639\u062f\u0629 \u0644\u0644\u0633\u0642\u064a \u0645\u0646 \u0627\u0644\u0633\u0627\u0642\u064a\u0629\u060c \u0648\u062e\u0627\u0644\u064a\u0629 \u0645\u0646 \u0627\u0644\u0639\u064a\u0648\u0628 \u062c\u0645\u064a\u0639\u0647\u0627\u060c \u0648\u0644\u064a\u0633 \u0641\u064a\u0647\u0627 \u0639\u0644\u0627\u0645\u0629 \u0645\u0646 \u0644\u0648\u0646 \u063a\u064a\u0631 \u0644\u0648\u0646 \u062c\u0644\u062f\u0647\u0627. \u0642\u0627\u0644\u0648\u0627: \u0627\u0644\u0622\u0646 \u062c\u0626\u062a \u0628\u062d\u0642\u064a\u0642\u0629 \u0648\u0635\u0641 \u0627\u0644\u0628\u0642\u0631\u0629\u060c \u0641\u0627\u0636\u0637\u0631\u0648\u0627 \u0625\u0644\u0649 \u0630\u0628\u062d\u0647\u0627 \u0628\u0639\u062f \u0637\u0648\u0644 \u0627\u0644\u0645\u0631\u0627\u0648\u063a\u0629\u060c \u0648\u0642\u062f \u0642\u0627\u0631\u0628\u0648\u0627 \u0623\u0644\u0627 \u064a\u0641\u0639\u0644\u0648\u0627 \u0630\u0644\u0643 \u0644\u0639\u0646\u0627\u062f\u0647\u0645. \u0648\u0647\u0643\u0630\u0627 \u0634\u062f\u062f\u0648\u0627 \u0641\u0634\u062f\u0651\u064e\u062f \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645.","2:72":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u0625\u0630 \u0642\u062a\u0644\u062a\u0645 \u0646\u0641\u0633\u064b\u0627 \u0641\u062a\u0646\u0627\u0632\u0639\u062a\u0645 \u0628\u0634\u0623\u0646\u0647\u0627\u060c \u0643\u0644\u0651\u064c \u064a\u062f\u0641\u0639 \u0639\u0646 \u0646\u0641\u0633\u0647 \u062a\u0647\u0645\u0629 \u0627\u0644\u0642\u062a\u0644\u060c \u0648\u0627\u0644\u0644\u0647 \u0645\u062e\u0631\u062c \u0645\u0627 \u0643\u0646\u062a\u0645 \u062a\u062e\u0641\u0648\u0646 \u0645\u0650\u0646 \u0642\u064e\u062a\u0652\u0644 \u0627\u0644\u0642\u062a\u064a\u0644.","2:73":"\u0641\u0642\u0644\u0646\u0627: \u0627\u0636\u0631\u0628\u0648\u0627 \u0627\u0644\u0642\u062a\u064a\u0644 \u0628\u062c\u0632\u0621 \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0628\u0642\u0631\u0629 \u0627\u0644\u0645\u0630\u0628\u0648\u062d\u0629\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0633\u064a\u0628\u0639\u062b\u0647 \u062d\u064a\u064b\u0627\u060c \u0648\u064a\u062e\u0628\u0631\u0643\u0645 \u0639\u0646 \u0642\u0627\u062a\u0644\u0647. \u0641\u0636\u0631\u0628\u0648\u0647 \u0628\u0628\u0639\u0636\u0647\u0627 \u0641\u0623\u062d\u064a\u0627\u0647 \u0627\u0644\u0644\u0647 \u0648\u0623\u062e\u0628\u0631 \u0628\u0642\u0627\u062a\u0644\u0647. \u0643\u0630\u0644\u0643 \u064a\u064f\u062d\u064a\u064a \u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u0648\u062a\u0649 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u0648\u064a\u0631\u064a\u0643\u0645 -\u064a\u0627 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644- \u0645\u0639\u062c\u0632\u0627\u062a\u0647 \u0627\u0644\u062f\u0627\u0644\u0629 \u0639\u0644\u0649 \u0643\u0645\u0627\u0644 \u0642\u062f\u0631\u062a\u0647 \u062a\u0639\u0627\u0644\u0649; \u0644\u0643\u064a \u062a\u062a\u0641\u0643\u0631\u0648\u0627 \u0628\u0639\u0642\u0648\u0644\u0643\u0645\u060c \u0641\u062a\u0645\u062a\u0646\u0639\u0648\u0627 \u0639\u0646 \u0645\u0639\u0627\u0635\u064a\u0647.","2:74":"\u0648\u0644\u0643\u0646\u0643\u0645 \u0644\u0645 \u062a\u0646\u062a\u0641\u0639\u0648\u0627 \u0628\u0630\u0644\u0643; \u0625\u0630 \u0628\u0639\u062f \u0643\u0644 \u0647\u0630\u0647 \u0627\u0644\u0645\u0639\u062c\u0632\u0627\u062a \u0627\u0644\u062e\u0627\u0631\u0642\u0629 \u0627\u0634\u062a\u062f\u062a \u0642\u0644\u0648\u0628\u0643\u0645 \u0648\u063a\u0644\u0638\u062a\u060c \u0641\u0644\u0645 \u064a\u064e\u0646\u0652\u0641\u064f\u0630 \u0625\u0644\u064a\u0647\u0627 \u062e\u064a\u0631\u060c \u0648\u0644\u0645 \u062a\u064e\u0644\u0650\u0646\u0652 \u0623\u0645\u0627\u0645 \u0627\u0644\u0622\u064a\u0627\u062a \u0627\u0644\u0628\u0627\u0647\u0631\u0629 \u0627\u0644\u062a\u064a \u0623\u0631\u064a\u062a\u0643\u0645\u0648\u0647\u0627\u060c \u062d\u062a\u0649 \u0635\u0627\u0631\u062a \u0642\u0644\u0648\u0628\u0643\u0645 \u0645\u062b\u0644 \u0627\u0644\u062d\u062c\u0627\u0631\u0629 \u0627\u0644\u0635\u0645\u0651\u064e\u0627\u0621\u060c \u0628\u0644 \u0647\u064a \u0623\u0634\u062f \u0645\u0646\u0647\u0627 \u063a\u0644\u0638\u0629; \u0644\u0623\u0646 \u0645\u0646 \u0627\u0644\u062d\u062c\u0627\u0631\u0629 \u0645\u0627 \u064a\u062a\u0633\u0639 \u0648\u064a\u0646\u0641\u0631\u062c \u062d\u062a\u0649 \u062a\u0646\u0635\u0628\u0651\u064e \u0645\u0646\u0647 \u0627\u0644\u0645\u064a\u0627\u0647 \u0635\u0628\u064b\u0627\u060c \u0641\u062a\u0635\u064a\u0631 \u0623\u0646\u0647\u0627\u0631\u064b\u0627 \u062c\u0627\u0631\u064a\u0629\u064b\u060c \u0648\u0645\u0646 \u0627\u0644\u062d\u062c\u0627\u0631\u0629 \u0645\u0627 \u064a\u062a\u0635\u062f\u0639 \u0641\u064a\u0646\u0634\u0642\u060c \u0641\u062a\u062e\u0631\u062c \u0645\u0646\u0647 \u0627\u0644\u0639\u064a\u0648\u0646 \u0648\u0627\u0644\u064a\u0646\u0627\u0628\u064a\u0639\u060c \u0648\u0645\u0646 \u0627\u0644\u062d\u062c\u0627\u0631\u0629 \u0645\u0627 \u064a\u0633\u0642\u0637 \u0645\u0646 \u0623\u0639\u0627\u0644\u064a \u0627\u0644\u062c\u0628\u0627\u0644 \u0645\u0650\u0646 \u062e\u0634\u064a\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u062a\u0639\u0638\u064a\u0645\u0647. \u0648\u0645\u0627 \u0627\u0644\u0644\u0647 \u0628\u063a\u0627\u0641\u0644 \u0639\u0645\u0627 \u062a\u0639\u0645\u0644\u0648\u0646.","2:75":"\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0623\u0646\u0633\u064a\u062a\u0645 \u0623\u0641\u0639\u0627\u0644 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644\u060c \u0641\u0637\u0645\u0639\u062a \u0646\u0641\u0648\u0633\u0643\u0645 \u0623\u0646 \u064a\u0635\u062f\u0651\u0650\u0642 \u0627\u0644\u064a\u0647\u0648\u062f\u064f \u0628\u062f\u064a\u0646\u0643\u0645\u061f \u0648\u0642\u062f \u0643\u0627\u0646 \u0639\u0644\u0645\u0627\u0624\u0647\u0645 \u064a\u0633\u0645\u0639\u0648\u0646 \u0643\u0644\u0627\u0645 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u062a\u0648\u0631\u0627\u0629\u060c \u062b\u0645 \u064a\u062d\u0631\u0641\u0648\u0646\u0647 \u0628\u0650\u0635\u064e\u0631\u0652\u0641\u0650\u0647 \u0625\u0644\u0649 \u063a\u064a\u0631 \u0645\u0639\u0646\u0627\u0647 \u0627\u0644\u0635\u062d\u064a\u062d \u0628\u0639\u062f \u0645\u0627 \u0639\u0642\u0644\u0648\u0627 \u062d\u0642\u064a\u0642\u062a\u0647\u060c \u0623\u0648 \u0628\u062a\u062d\u0631\u064a\u0641 \u0623\u0644\u0641\u0627\u0638\u0647\u060c \u0648\u0647\u0645 \u064a\u0639\u0644\u0645\u0648\u0646 \u0623\u0646\u0647\u0645 \u064a\u062d\u0631\u0641\u0648\u0646 \u0643\u0644\u0627\u0645 \u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064a\u0646 \u0639\u0645\u062f\u064b\u0627 \u0648\u0643\u0630\u0628\u064b\u0627.","2:76":"\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u064a\u0647\u0648\u062f \u0625\u0630\u0627 \u0644\u0642\u0648\u0627 \u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0642\u0627\u0644\u0648\u0627 \u0628\u0644\u0633\u0627\u0646\u0647\u0645: \u0622\u0645\u0646\u0651\u064e\u0627 \u0628\u062f\u064a\u0646\u0643\u0645 \u0648\u0631\u0633\u0648\u0644\u0643\u0645 \u0627\u0644\u0645\u0628\u0634\u0651\u064e\u0631 \u0628\u0647 \u0641\u064a \u0627\u0644\u062a\u0648\u0631\u0627\u0629\u060c \u0648\u0625\u0630\u0627 \u062e\u0644\u0627 \u0628\u0639\u0636 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0625\u0644\u0649 \u0628\u0639\u0636 \u0642\u0627\u0644\u0648\u0627 \u0641\u064a \u0625\u0646\u0643\u0627\u0631: \u0623\u062a\u062d\u062f\u0651\u0650\u062b\u0648\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0628\u0645\u0627 \u0628\u064a\u0651\u064e\u0646 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0641\u064a \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0645\u0646 \u0623\u0645\u0631 \u0645\u062d\u0645\u062f; \u0644\u062a\u0643\u0648\u0646 \u0644\u0647\u0645 \u0627\u0644\u062d\u062c\u0629 \u0639\u0644\u064a\u0643\u0645 \u0639\u0646\u062f \u0631\u0628\u0643\u0645 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u061f \u0623\u0641\u0644\u0627 \u062a\u0641\u0642\u0647\u0648\u0646 \u0641\u062a\u062d\u0630\u0631\u0648\u0627\u061f","2:77":"\u0623\u064a\u0641\u0639\u0644\u0648\u0646 \u0643\u0644\u0651\u064e \u0647\u0630\u0647 \u0627\u0644\u062c\u0631\u0627\u0626\u0645\u060c \u0648\u0644\u0627 \u064a\u0639\u0644\u0645\u0648\u0646 \u0623\u0646 \u0627\u0644\u0644\u0647 \u064a\u0639\u0644\u0645 \u062c\u0645\u064a\u0639 \u0645\u0627 \u064a\u062e\u0641\u0648\u0646\u0647 \u0648\u0645\u0627 \u064a\u0638\u0647\u0631\u0648\u0646\u0647\u061f","2:78":"\u0648\u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u062c\u0645\u0627\u0639\u0629 \u064a\u062c\u0647\u0644\u0648\u0646 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0648\u0627\u0644\u0643\u062a\u0627\u0628\u0629\u060c \u0648\u0644\u0627 \u064a\u0639\u0644\u0645\u0648\u0646 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u0645\u0627 \u0641\u064a\u0647\u0627 \u0645\u0646 \u0635\u0641\u0627\u062a \u0646\u0628\u064a \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0645\u0627 \u0639\u0646\u062f\u0647\u0645 \u0645\u0646 \u0630\u0644\u0643 \u0625\u0644\u0627 \u0623\u0643\u0627\u0630\u064a\u0628\u064f \u0648\u0638\u0646\u0648\u0646 \u0641\u0627\u0633\u062f\u0629.","2:79":"\u0641\u0647\u0644\u0627\u0643 \u0648\u0648\u0639\u064a\u062f \u0634\u062f\u064a\u062f \u0644\u0623\u062d\u0628\u0627\u0631 \u0627\u0644\u0633\u0648\u0621 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0627\u0644\u0630\u064a\u0646 \u064a\u0643\u062a\u0628\u0648\u0646 \u0627\u0644\u0643\u062a\u0627\u0628 \u0628\u0623\u064a\u062f\u064a\u0647\u0645\u060c \u062b\u0645 \u064a\u0642\u0648\u0644\u0648\u0646: \u0647\u0630\u0627 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0648\u0647\u0648 \u0645\u062e\u0627\u0644\u0641 \u0644\u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0646\u0628\u064a\u0651\u0650\u0647 \u0645\u0648\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0627\u0644\u0633\u0644\u0627\u0645; \u0644\u064a\u0623\u062e\u0630\u0648\u0627 \u0641\u064a \u0645\u0642\u0627\u0628\u0644 \u0647\u0630\u0627 \u0639\u0631\u0636 \u0627\u0644\u062f\u0646\u064a\u0627. \u0641\u0644\u0647\u0645 \u0639\u0642\u0648\u0628\u0629 \u0645\u0647\u0644\u0643\u0629 \u0628\u0633\u0628\u0628 \u0643\u062a\u0627\u0628\u062a\u0647\u0645 \u0647\u0630\u0627 \u0627\u0644\u0628\u0627\u0637\u0644 \u0628\u0623\u064a\u062f\u064a\u0647\u0645\u060c \u0648\u0644\u0647\u0645 \u0639\u0642\u0648\u0628\u0629 \u0645\u0647\u0644\u0643\u0629 \u0628\u0633\u0628\u0628 \u0645\u0627 \u064a\u0623\u062e\u0630\u0648\u0646\u0647 \u0641\u064a \u0627\u0644\u0645\u0642\u0627\u0628\u0644 \u0645\u0646 \u0627\u0644\u0645\u0627\u0644 \u0627\u0644\u062d\u0631\u0627\u0645\u060c \u0643\u0627\u0644\u0631\u0634\u0648\u0629 \u0648\u063a\u064a\u0631\u0647\u0627.","2:80":"\u0648\u0642\u0627\u0644 \u0628\u0646\u0648 \u0625\u0633\u0631\u0627\u0626\u064a\u0644: \u0644\u0646 \u062a\u0635\u064a\u0628\u0646\u0627 \u0627\u0644\u0646\u0627\u0631 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u0625\u0644\u0627 \u0623\u064a\u0627\u0645\u064b\u0627 \u0642\u0644\u064a\u0644\u0629 \u0627\u0644\u0639\u062f\u062f. \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644 \u0645\u0628\u0637\u0644\u0627 \u062f\u0639\u0648\u0627\u0647\u0645-: \u0623\u0639\u0646\u062f\u0643\u0645 \u0639\u0647\u062f \u0645\u0646 \u0627\u0644\u0644\u0647 \u0628\u0647\u0630\u0627\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u062e\u0644\u0641 \u0639\u0647\u062f\u0647\u061f \u0628\u0644 \u0625\u0646\u0643\u0645 \u062a\u0642\u0648\u0644\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0645\u0627 \u0644\u0627 \u062a\u0639\u0644\u0645\u0648\u0646 \u0628\u0627\u0641\u062a\u0631\u0627\u0626\u0643\u0645 \u0627\u0644\u0643\u0630\u0628.","2:81":"\u0641\u062d\u064f\u0643\u0652\u0645\u064f \u0627\u0644\u0644\u0647 \u062b\u0627\u0628\u062a: \u0623\u0646 \u0645\u0646 \u0627\u0631\u062a\u0643\u0628 \u0627\u0644\u0622\u062b\u0627\u0645 \u062d\u062a\u0649 \u062c\u064e\u0631\u0651\u064e\u062a\u0647 \u0625\u0644\u0649 \u0627\u0644\u0643\u0641\u0631\u060c \u0648\u0627\u0633\u062a\u0648\u0644\u062a \u0639\u0644\u064a\u0647 \u0630\u0646\u0648\u0628\u0647 \u0645\u0650\u0646 \u062c\u0645\u064a\u0639 \u062c\u0648\u0627\u0646\u0628\u0647 -\u0648\u0647\u0630\u0627 \u0644\u0627 \u064a\u0643\u0648\u0646 \u0625\u0644\u0627 \u0641\u064a\u0645\u0646 \u0623\u0634\u0631\u0643 \u0628\u0627\u0644\u0644\u0647- \u0641\u0623\u0648\u0644\u0626\u0643 \u0647\u0645 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0648\u0627\u0644\u0643\u0641\u0627\u0631 \u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u064a\u0644\u0627\u0632\u0645\u0648\u0646 \u0646\u0627\u0631 \u062c\u0647\u0646\u0645 \u0645\u0644\u0627\u0632\u0645\u0629 \u062f\u0627\u0626\u0645\u0629\u064b \u0644\u0627 \u062a\u0646\u0642\u0637\u0639.","2:82":"\u0648\u062d\u0643\u0645 \u0627\u0644\u0644\u0647 \u0627\u0644\u062b\u0627\u0628\u062a\u064f \u0641\u064a \u0645\u0642\u0627\u0628\u0644 \u0647\u0630\u0627: \u0623\u0646\u0651\u064e \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0644\u0647 \u062a\u0635\u062f\u064a\u0642\u064b\u0627 \u062e\u0627\u0644\u0635\u064b\u0627\u060c \u0648\u0639\u0645\u0644\u0648\u0627 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0645\u062a\u0641\u0642\u0629 \u0645\u0639 \u0634\u0631\u064a\u0639\u0629 \u0627\u0644\u0644\u0647 \u0627\u0644\u062a\u064a \u0623\u0648\u062d\u0627\u0647\u0627 \u0625\u0644\u0649 \u0631\u0633\u0644\u0647\u060c \u0647\u0624\u0644\u0627\u0621 \u064a\u0644\u0627\u0632\u0645\u0648\u0646 \u0627\u0644\u062c\u0646\u0629 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u0645\u0644\u0627\u0632\u0645\u0629\u064b \u062f\u0627\u0626\u0645\u0629\u064b \u0644\u0627 \u062a\u0646\u0642\u0637\u0639.","2:83":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u064a\u0627 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u062d\u064a\u0646 \u0623\u062e\u064e\u0630\u0652\u0646\u0627 \u0639\u0644\u064a\u0643\u0645 \u0639\u0647\u062f\u064b\u0627 \u0645\u0624\u0643\u062f\u064b\u0627: \u0628\u0623\u0646 \u062a\u0639\u0628\u062f\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0644\u0627 \u0634\u0631\u064a\u0643 \u0644\u0647\u060c \u0648\u0623\u0646 \u062a\u062d\u0633\u0646\u0648\u0627 \u0644\u0644\u0648\u0627\u0644\u062f\u064a\u0646\u060c \u0648\u0644\u0644\u0623\u0642\u0631\u0628\u064a\u0646\u060c \u0648\u0644\u0644\u0623\u0648\u0644\u0627\u062f \u0627\u0644\u0630\u064a\u0646 \u0645\u0627\u062a \u0622\u0628\u0627\u0624\u0647\u0645 \u0648\u0647\u0645 \u062f\u0648\u0646 \u0628\u0644\u0648\u063a \u0627\u0644\u062d\u0644\u0645\u060c \u0648\u0644\u0644\u0645\u062d\u062a\u0627\u062c\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0644\u0627 \u064a\u0645\u0644\u0643\u0648\u0646 \u0645\u0627 \u064a\u0643\u0641\u064a\u0647\u0645 \u0648\u064a\u0633\u062f \u062d\u0627\u062c\u062a\u0647\u0645\u060c \u0648\u0623\u0646 \u062a\u0642\u0648\u0644\u0648\u0627 \u0644\u0644\u0646\u0627\u0633 \u0623\u0637\u064a\u0628 \u0627\u0644\u0643\u0644\u0627\u0645\u060c \u0645\u0639 \u0623\u062f\u0627\u0621 \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0625\u064a\u062a\u0627\u0621 \u0627\u0644\u0632\u0643\u0627\u0629\u060c \u062b\u0645 \u0623\u064e\u0639\u0652\u0631\u064e\u0636\u0652\u062a\u0645 \u0648\u0646\u0642\u0636\u062a\u0645 \u0627\u0644\u0639\u0647\u062f -\u0625\u0644\u0627 \u0642\u0644\u064a\u0644\u0627 \u0645\u0646\u0643\u0645 \u062b\u0628\u062a \u0639\u0644\u064a\u0647- \u0648\u0623\u0646\u062a\u0645 \u0645\u0633\u062a\u0645\u0631\u0648\u0646 \u0641\u064a \u0625\u0639\u0631\u0627\u0636\u0643\u0645.","2:84":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 -\u064a\u0627 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644- \u062d\u064a\u0646 \u0623\u064e\u062e\u064e\u0630\u0652\u0646\u0627 \u0639\u0644\u064a\u0643\u0645 \u0639\u0647\u062f\u064b\u0627 \u0645\u0624\u0643\u062f\u064b\u0627 \u0641\u064a \u0627\u0644\u062a\u0648\u0631\u0627\u0629: \u064a\u062d\u0631\u0645 \u0633\u0641\u0643 \u0628\u0639\u0636\u0643\u0645 \u062f\u0645 \u0628\u0639\u0636\u060c \u0648\u0625\u062e\u0631\u0627\u062c \u0628\u0639\u0636\u0643\u0645 \u0628\u0639\u0636\u064b\u0627 \u0645\u0646 \u062f\u064a\u0627\u0631\u0643\u0645\u060c \u062b\u0645 \u0627\u0639\u062a\u0631\u0641\u062a\u0645 \u0628\u0630\u0644\u0643\u060c \u0648\u0623\u0646\u062a\u0645 \u062a\u0634\u0647\u062f\u0648\u0646 \u0639\u0644\u0649 \u0635\u062d\u062a\u0647.","2:85":"\u062b\u0645 \u0623\u0646\u062a\u0645 \u064a\u0627 \u0647\u0624\u0644\u0627\u0621 \u064a\u0642\u062a\u0644 \u0628\u0639\u0636\u0643\u0645 \u0628\u0639\u0636\u064b\u0627\u060c \u0648\u064a\u064f\u062e\u0631\u062c \u0628\u0639\u0636\u0643\u0645 \u0628\u0639\u0636\u064b\u0627 \u0645\u0646 \u062f\u064a\u0627\u0631\u0647\u0645\u060c \u0648\u064a\u064e\u062a\u064e\u0642\u064e\u0648\u0651\u064e\u0649 \u0643\u0644 \u0641\u0631\u064a\u0642 \u0645\u0646\u0643\u0645 \u0639\u0644\u0649 \u0625\u062e\u0648\u0627\u0646\u0647 \u0628\u0627\u0644\u0623\u0639\u062f\u0627\u0621 \u0628\u063a\u064a\u064b\u0627 \u0648\u0639\u062f\u0648\u0627\u0646\u064b\u0627. \u0648\u0623\u0646 \u064a\u0623\u062a\u0648\u0643\u0645 \u0623\u0633\u0627\u0631\u0649 \u0641\u064a \u064a\u062f \u0627\u0644\u0623\u0639\u062f\u0627\u0621 \u0633\u0639\u064a\u062a\u0645 \u0641\u064a \u062a\u062d\u0631\u064a\u0631\u0647\u0645 \u0645\u0646 \u0627\u0644\u0623\u0633\u0631\u060c \u0628\u062f\u0641\u0639 \u0627\u0644\u0641\u062f\u064a\u0629\u060c \u0645\u0639 \u0623\u0646\u0647 \u0645\u062d\u0631\u0645 \u0639\u0644\u064a\u0643\u0645 \u0625\u062e\u0631\u0627\u062c\u0647\u0645 \u0645\u0646 \u062f\u064a\u0627\u0631\u0647\u0645. \u0645\u0627 \u0623\u0642\u0628\u062d \u0645\u0627 \u062a\u0641\u0639\u0644\u0648\u0646 \u062d\u064a\u0646 \u062a\u0624\u0645\u0646\u0648\u0646 \u0628\u0628\u0639\u0636 \u0623\u062d\u0643\u0627\u0645 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u062a\u0643\u0641\u0631\u0648\u0646 \u0628\u0628\u0639\u0636\u0647\u0627! \u0641\u0644\u064a\u0633 \u062c\u0632\u0627\u0621 \u0645\u064e\u0646 \u064a\u0641\u0639\u0644 \u0630\u0644\u0643 \u0645\u0646\u0643\u0645 \u0625\u0644\u0627 \u0630\u064f\u0644\u0627 \u0648\u0641\u0636\u064a\u062d\u0629 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627. \u0648\u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u064a\u0631\u062f\u0651\u064f\u0647\u0645 \u0627\u0644\u0644\u0647 \u0625\u0644\u0649 \u0623\u0641\u0638\u0639 \u0627\u0644\u0639\u0630\u0627\u0628 \u0641\u064a \u0627\u0644\u0646\u0627\u0631. \u0648\u0645\u0627 \u0627\u0644\u0644\u0647 \u0628\u063a\u0627\u0641\u0644 \u0639\u0645\u0627 \u062a\u0639\u0645\u0644\u0648\u0646.","2:86":"\u0623\u0648\u0644\u0626\u0643 \u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u0622\u062b\u0631\u0648\u0627 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627 \u0639\u0644\u0649 \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0641\u0644\u0627 \u064a\u062e\u0641\u0641 \u0639\u0646\u0647\u0645 \u0627\u0644\u0639\u0630\u0627\u0628\u060c \u0648\u0644\u064a\u0633 \u0644\u0647\u0645 \u0646\u0627\u0635\u0631 \u064a\u0646\u0635\u0631\u0647\u0645 \u0645\u0650\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647.","2:87":"\u0648\u0644\u0642\u062f \u0623\u0639\u0637\u064a\u0646\u0627 \u0645\u0648\u0633\u0649 \u0627\u0644\u062a\u0648\u0631\u0627\u0629\u060c \u0648\u0623\u062a\u0628\u0639\u0646\u0627\u0647 \u0628\u0631\u0633\u0644 \u0645\u0646 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644\u060c \u0648\u0623\u0639\u0637\u064a\u0646\u0627 \u0639\u064a\u0633\u0649 \u0627\u0628\u0646 \u0645\u0631\u064a\u0645 \u0627\u0644\u0645\u0639\u062c\u0632\u0627\u062a \u0627\u0644\u0648\u0627\u0636\u062d\u0627\u062a\u060c \u0648\u0642\u0648\u0651\u064e\u064a\u0646\u0627\u0647 \u0628\u062c\u0628\u0631\u064a\u0644 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645. \u0623\u0641\u0643\u0644\u0645\u0627 \u062c\u0627\u0621\u0643\u0645 \u0631\u0633\u0648\u0644 \u0628\u0648\u062d\u064a \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u0648\u0627\u0641\u0642 \u0623\u0647\u0648\u0627\u0621\u0643\u0645\u060c \u0627\u0633\u062a\u0639\u0644\u064a\u062a\u0645 \u0639\u0644\u064a\u0647\u060c \u0641\u0643\u0630\u0651\u064e\u0628\u062a\u0645 \u0641\u0631\u064a\u0642\u064b\u0627 \u0648\u062a\u0642\u062a\u0644\u0648\u0646 \u0641\u0631\u064a\u0642\u064b\u0627\u061f","2:88":"\u0648\u0642\u0627\u0644 \u0628\u0646\u0648 \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0644\u0646\u0628\u064a \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645: \u0642\u0644\u0648\u0628\u0646\u0627 \u0645\u063a\u0637\u0627\u0629\u060c \u0644\u0627 \u064a\u064e\u0646\u0652\u0641\u064f\u0630 \u0625\u0644\u064a\u0647\u0627 \u0642\u0648\u0644\u0643. \u0648\u0644\u064a\u0633 \u0627\u0644\u0623\u0645\u0631 \u0643\u0645\u0627 \u0627\u062f\u0651\u064e\u0639\u064e\u0648\u0652\u0627\u060c \u0628\u0644 \u0642\u0644\u0648\u0628\u0647\u0645 \u0645\u0644\u0639\u0648\u0646\u0629\u060c \u0645\u0637\u0628\u0648\u0639 \u0639\u0644\u064a\u0647\u0627\u060c \u0648\u0647\u0645 \u0645\u0637\u0631\u0648\u062f\u0648\u0646 \u0645\u0646 \u0631\u062d\u0645\u0629 \u0627\u0644\u0644\u0647 \u0628\u0633\u0628\u0628 \u062c\u062d\u0648\u062f\u0647\u0645\u060c \u0641\u0644\u0627 \u064a\u0624\u0645\u0646\u0648\u0646 \u0625\u0644\u0627 \u0625\u064a\u0645\u0627\u0646\u064b\u0627 \u0642\u0644\u064a\u0644\u0627 \u0644\u0627 \u064a\u0646\u0641\u0639\u0647\u0645.","2:89":"\u0648\u062d\u064a\u0646 \u062c\u0627\u0621\u0647\u0645 \u0627\u0644\u0642\u0631\u0622\u0646 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0645\u0635\u062f\u0642\u0627 \u0644\u0645\u0627 \u0645\u0639\u0647\u0645 \u0645\u0646 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u062c\u062d\u062f\u0648\u0647\u060c \u0648\u0623\u0646\u0643\u0631\u0648\u0627 \u0646\u0628\u0648\u0629 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0643\u0627\u0646\u0648\u0627 \u0642\u0628\u0644 \u0628\u0639\u062b\u062a\u0647 \u064a\u0633\u062a\u0646\u0635\u0631\u0648\u0646 \u0628\u0647 \u0639\u0644\u0649 \u0645\u0634\u0631\u0643\u064a \u0627\u0644\u0639\u0631\u0628\u060c \u0648\u064a\u0642\u0648\u0644\u0648\u0646: \u0642\u064e\u0631\u064f\u0628\u064e \u0645\u0628\u0639\u062b \u0646\u0628\u064a\u0651\u0650 \u0622\u062e\u0631\u0650 \u0627\u0644\u0632\u0645\u0627\u0646\u060c \u0648\u0633\u0646\u062a\u0628\u0639\u0647 \u0648\u0646\u0642\u0627\u062a\u0644\u0643\u0645 \u0645\u0639\u0647. \u0641\u0644\u0645\u0651\u064e\u0627 \u062c\u0627\u0621\u0647\u0645 \u0627\u0644\u0631\u0633\u0648\u0644 \u0627\u0644\u0630\u064a \u0639\u0631\u0641\u0648\u0627 \u0635\u0641\u0627\u062a\u0650\u0647 \u0648\u0635\u0650\u062f\u0652\u0642\u064e\u0647 \u0643\u0641\u0631\u0648\u0627 \u0628\u0647 \u0648\u0643\u0630\u0628\u0648\u0647. \u0641\u0644\u0639\u0646\u0629\u064f \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0643\u0644 \u0645\u064e\u0646 \u0643\u0641\u0631 \u0628\u0646\u0628\u064a \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0643\u062a\u0627\u0628\u0647 \u0627\u0644\u0630\u064a \u0623\u0648\u062d\u0627\u0647 \u0627\u0644\u0644\u0647 \u0625\u0644\u064a\u0647.","2:90":"\u0642\u064e\u0628\u064f\u062d\u064e \u0645\u0627 \u0627\u062e\u062a\u0627\u0631\u0647 \u0628\u0646\u0648 \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0644\u0623\u0646\u0641\u0633\u0647\u0645; \u0625\u0630 \u0627\u0633\u062a\u0628\u062f\u0644\u0648\u0627 \u0627\u0644\u0643\u0641\u0631 \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0638\u0644\u0645\u064b\u0627 \u0648\u062d\u0633\u062f\u064b\u0627 \u0644\u0625\u0646\u0632\u0627\u0644 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0641\u0636\u0644\u0647 \u0627\u0644\u0642\u0631\u0622\u0646 \u0639\u0644\u0649 \u0646\u0628\u064a \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0641\u0631\u062c\u0639\u0648\u0627 \u0628\u063a\u0636\u0628 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645 \u0628\u0633\u0628\u0628 \u062c\u062d\u0648\u062f\u0647\u0645 \u0628\u0627\u0644\u0646\u0628\u064a \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0628\u0639\u062f \u063a\u0636\u0628 \u0627\u0644\u0644\u0647 \u0643\u0630\u0644\u0643 \u0639\u0644\u064a\u0647\u0645 \u0628\u0633\u0628\u0628 \u062a\u062d\u0631\u064a\u0641\u0647\u0645 \u0627\u0644\u062a\u0648\u0631\u0627\u0629. \u0648\u0644\u0644\u062c\u0627\u062d\u062f\u064a\u0646 \u0646\u0628\u0648\u0651\u064e\u0629 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0639\u0630\u0627\u0628\u064c \u064a\u0630\u0644\u0651\u064f\u0647\u0645 \u0648\u064a\u062e\u0632\u064a\u0647\u0645.","2:91":"\u0648\u0625\u0630\u0627 \u0642\u0627\u0644 \u0628\u0639\u0636 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0644\u0644\u064a\u0647\u0648\u062f: \u0635\u062f\u0651\u0650\u0642\u0648\u0627 \u0628\u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0642\u0627\u0644\u0648\u0627: \u0646\u062d\u0646 \u0646\u0635\u062f\u0651\u0650\u0642 \u0628\u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0623\u0646\u0628\u064a\u0627\u0626\u0646\u0627\u060c \u0648\u064a\u062c\u062d\u062f\u0648\u0646 \u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0628\u0639\u062f \u0630\u0644\u0643\u060c \u0648\u0647\u0648 \u0627\u0644\u062d\u0642 \u0645\u0635\u062f\u0642\u064b\u0627 \u0644\u0645\u0627 \u0645\u0639\u0647\u0645. \u0641\u0644\u0648 \u0643\u0627\u0646\u0648\u0627 \u064a\u0624\u0645\u0646\u0648\u0646 \u0628\u0643\u062a\u0628\u0647\u0645 \u062d\u0642\u064b\u0627 \u0644\u0622\u0645\u0646\u0648\u0627 \u0628\u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0630\u064a \u0635\u062f\u0651\u064e\u0642\u0647\u0627. \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0625\u0646 \u0643\u0646\u062a\u0645 \u0645\u0624\u0645\u0646\u064a\u0646 \u0628\u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645\u060c \u0641\u0644\u0645\u0627\u0630\u0627 \u0642\u062a\u0644\u062a\u0645 \u0623\u0646\u0628\u064a\u0627\u0621 \u0627\u0644\u0644\u0647 \u0645\u0650\u0646 \u0642\u0628\u0644\u061f","2:92":"\u0648\u0644\u0642\u062f \u062c\u0627\u0621\u0643\u0645 \u0646\u0628\u064a \u0627\u0644\u0644\u0647 \u0645\u0648\u0633\u0649 \u0628\u0627\u0644\u0645\u0639\u062c\u0632\u0627\u062a \u0627\u0644\u0648\u0627\u0636\u062d\u0627\u062a \u0627\u0644\u062f\u0627\u0644\u0629 \u0639\u0644\u0649 \u0635\u062f\u0642\u0647\u060c \u0643\u0627\u0644\u0637\u0648\u0641\u0627\u0646 \u0648\u0627\u0644\u062c\u0631\u0627\u062f \u0648\u0627\u0644\u0642\u064f\u0645\u0651\u064e\u0644 \u0648\u0627\u0644\u0636\u0641\u0627\u062f\u0639\u060c \u0648\u063a\u064a\u0631 \u0630\u0644\u0643 \u0645\u0645\u0627 \u0630\u0643\u0631\u0647 \u0627\u0644\u0644\u0647 \u0641\u064a \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0639\u0638\u064a\u0645\u060c \u0648\u0645\u0639 \u0630\u0644\u0643 \u0627\u062a\u062e\u0630\u062a\u0645 \u0627\u0644\u0639\u062c\u0644 \u0645\u0639\u0628\u0648\u062f\u064b\u0627\u060c \u0628\u0639\u062f \u0630\u0647\u0627\u0628 \u0645\u0648\u0633\u0649 \u0625\u0644\u0649 \u0645\u064a\u0642\u0627\u062a \u0631\u0628\u0647\u060c \u0648\u0623\u0646\u062a\u0645 \u0645\u062a\u062c\u0627\u0648\u0632\u0648\u0646 \u062d\u062f\u0648\u062f \u0627\u0644\u0644\u0647.","2:93":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u062d\u064a\u0646 \u0623\u064e\u062e\u064e\u0630\u0652\u0646\u0627 \u0639\u0644\u064a\u0643\u0645 \u0639\u0647\u062f\u064b\u0627 \u0645\u0624\u0643\u062f\u064b\u0627 \u0628\u0642\u064e\u0628\u0648\u0644 \u0645\u0627 \u062c\u0627\u0621\u0643\u0645 \u0628\u0647 \u0645\u0648\u0633\u0649 \u0645\u0646 \u0627\u0644\u062a\u0648\u0631\u0627\u0629\u060c \u0641\u0646\u0642\u0636\u062a\u0645 \u0627\u0644\u0639\u0647\u062f\u060c \u0641\u0631\u0641\u0639\u0646\u0627 \u062c\u0628\u0644 \u0627\u0644\u0637\u0648\u0631 \u0641\u0648\u0642 \u0631\u0624\u0648\u0633\u0643\u0645\u060c \u0648\u0642\u0644\u0646\u0627 \u0644\u0643\u0645: \u062e\u0630\u0648\u0627 \u0645\u0627 \u0622\u062a\u064a\u0646\u0627\u0643\u0645 \u0628\u062c\u062f\u0651\u064d\u060c \u0648\u0627\u0633\u0645\u0639\u0648\u0627 \u0648\u0623\u0637\u064a\u0639\u0648\u0627\u060c \u0648\u0625\u0644\u0627 \u0623\u0633\u0642\u0637\u0646\u0627 \u0627\u0644\u062c\u0628\u0644 \u0639\u0644\u064a\u0643\u0645\u060c \u0641\u0642\u0644\u062a\u0645: \u0633\u0645\u0639\u0646\u0627 \u0642\u0648\u0644\u0643 \u0648\u0639\u0635\u064a\u0646\u0627 \u0623\u0645\u0631\u0643; \u0644\u0623\u0646 \u0639\u0628\u0627\u062f\u0629 \u0627\u0644\u0639\u062c\u0644 \u0642\u062f \u0627\u0645\u062a\u0632\u062c\u062a \u0628\u0642\u0644\u0648\u0628\u0643\u0645 \u0628\u0633\u0628\u0628 \u062a\u0645\u0627\u062f\u064a\u0643\u0645 \u0641\u064a \u0627\u0644\u0643\u0641\u0631. \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0642\u064e\u0628\u064f\u062d\u064e \u0645\u0627 \u064a\u0623\u0645\u0631\u0643\u0645 \u0628\u0647 \u0625\u064a\u0645\u0627\u0646\u0643\u0645 \u0645\u0646 \u0627\u0644\u0643\u0641\u0631 \u0648\u0627\u0644\u0636\u0644\u0627\u0644\u060c \u0625\u0646 \u0643\u0646\u062a\u0645 \u0645\u0635\u062f\u0651\u0650\u0642\u064a\u0646 \u0628\u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645.","2:94":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0644\u064a\u0647\u0648\u062f \u0627\u0644\u0630\u064a\u0646 \u064a\u062f\u0651\u064e\u0639\u0648\u0646 \u0623\u0646 \u0627\u0644\u062c\u0646\u0629 \u062e\u0627\u0635\u0629 \u0628\u0647\u0645; \u0644\u0632\u0639\u0645\u0647\u0645 \u0623\u0646\u0647\u0645 \u0623\u0648\u0644\u064a\u0627\u0621 \u0627\u0644\u0644\u0647 \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0646\u0627\u0633\u060c \u0648\u0623\u0646\u0647\u0645 \u0623\u0628\u0646\u0627\u0624\u0647 \u0648\u0623\u062d\u0628\u0627\u0624\u0647: \u0625\u0646 \u0643\u0627\u0646 \u0627\u0644\u0623\u0645\u0631 \u0643\u0630\u0644\u0643 \u0641\u0627\u062f\u0652\u0639\u064f\u0648\u0627 \u0639\u0644\u0649 \u0627\u0644\u0643\u0627\u0630\u0628\u064a\u0646 \u0645\u0646\u0643\u0645 \u0623\u0648 \u0645\u0646 \u063a\u064a\u0631\u0643\u0645 \u0628\u0627\u0644\u0645\u0648\u062a\u060c \u0625\u0646 \u0643\u0646\u062a\u0645 \u0635\u0627\u062f\u0642\u064a\u0646 \u0641\u064a \u062f\u0639\u0648\u0627\u0643\u0645 \u0647\u0630\u0647.","2:95":"\u0648\u0644\u0646 \u064a\u0641\u0639\u0644\u0648\u0627 \u0630\u0644\u0643 \u0623\u0628\u062f\u064b\u0627; \u0644\u0645\u0627 \u064a\u0639\u0631\u0641\u0648\u0646\u0647 \u0645\u0646 \u0635\u062f\u0642 \u0627\u0644\u0646\u0628\u064a \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u0645\u0646 \u0643\u0630\u0628\u0647\u0645 \u0648\u0627\u0641\u062a\u0631\u0627\u0626\u0647\u0645\u060c \u0648\u0628\u0633\u0628\u0628 \u0645\u0627 \u0627\u0631\u062a\u0643\u0628\u0648\u0647 \u0645\u0646 \u0627\u0644\u0643\u0641\u0631 \u0648\u0627\u0644\u0639\u0635\u064a\u0627\u0646\u060c \u0627\u0644\u0645\u0624\u064e\u062f\u0651\u0650\u064a\u064e\u064a\u0652\u0646 \u0625\u0644\u0649 \u062d\u0631\u0645\u0627\u0646\u0647\u0645 \u0645\u0646 \u0627\u0644\u062c\u0646\u0629 \u0648\u062f\u062e\u0648\u0644 \u0627\u0644\u0646\u0627\u0631. \u0648\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0644\u064a\u0645 \u0628\u0627\u0644\u0638\u0627\u0644\u0645\u064a\u0646 \u0645\u0646 \u0639\u0628\u0627\u062f\u0647\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a\u0647\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643.","2:96":"\u0648\u0644\u062a\u0639\u0644\u0645\u064e\u0646\u0651\u064e -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0623\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0623\u0634\u062f \u0627\u0644\u0646\u0627\u0633 \u0631\u063a\u0628\u0629 \u0641\u064a \u0637\u0648\u0644 \u0627\u0644\u062d\u064a\u0627\u0629 \u0623\u064a\u0651\u064b\u0627 \u0643\u0627\u0646\u062a \u0647\u0630\u0647 \u0627\u0644\u062d\u064a\u0627\u0629 \u0645\u0646 \u0627\u0644\u0630\u0644\u0651\u064e\u0629 \u0648\u0627\u0644\u0645\u0647\u0627\u0646\u0629\u060c \u0628\u0644 \u062a\u0632\u064a\u062f \u0631\u063a\u0628\u062a\u0647\u0645 \u0641\u064a \u0637\u0648\u0644 \u0627\u0644\u062d\u064a\u0627\u0629 \u0639\u0644\u0649 \u0631\u063a\u0628\u0627\u062a \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646. \u064a\u062a\u0645\u0646\u0649 \u0627\u0644\u064a\u0647\u0648\u062f\u064a \u0623\u0646 \u064a\u0639\u064a\u0634 \u0623\u0644\u0641 \u0633\u0646\u0629\u060c \u0648\u0644\u0627 \u064a\u064f\u0628\u0652\u0639\u062f\u0647 \u0647\u0630\u0627 \u0627\u0644\u0639\u0645\u0631 \u0627\u0644\u0637\u0648\u064a\u0644 -\u0625\u0646 \u062d\u0635\u0644- \u0645\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647. \u0648\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0627 \u064a\u062e\u0641\u0649 \u0639\u0644\u064a\u0647 \u0634\u064a\u0621 \u0645\u0646 \u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0648\u0633\u064a\u062c\u0627\u0632\u064a\u0647\u0645 \u0639\u0644\u064a\u0647\u0627 \u0628\u0645\u0627 \u064a\u0633\u062a\u062d\u0642\u0648\u0646 \u0645\u0646 \u0627\u0644\u0639\u0630\u0627\u0628.","2:97":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0644\u064a\u0647\u0648\u062f \u062d\u064a\u0646 \u0642\u0627\u0644\u0648\u0627: \u0625\u0646 \u062c\u0628\u0631\u064a\u0644 \u0647\u0648 \u0639\u062f\u0648\u0646\u0627 \u0645\u0646 \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629: \u0645\u0646 \u0643\u0627\u0646 \u0639\u062f\u0648\u064b\u0627 \u0644\u062c\u0628\u0631\u064a\u0644 \u0641\u0625\u0646\u0647 \u0646\u0632\u0651\u064e\u0644 \u0627\u0644\u0642\u0631\u0622\u0646 \u0639\u0644\u0649 \u0642\u0644\u0628\u0643 \u0628\u0625\u0630\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0645\u0635\u062f\u0651\u0650\u0642\u064b\u0627 \u0644\u0645\u0627 \u0633\u0628\u0642\u0647 \u0645\u0646 \u0643\u062a\u0628 \u0627\u0644\u0644\u0647\u060c \u0648\u0647\u0627\u062f\u064a\u064b\u0627 \u0625\u0644\u0649 \u0627\u0644\u062d\u0642\u060c \u0648\u0645\u0628\u0634\u0631\u064b\u0627 \u0644\u0644\u0645\u0635\u062f\u0651\u0650\u0642\u064a\u0646 \u0628\u0647 \u0628\u0643\u0644 \u062e\u064a\u0631 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629.","2:98":"\u0645\u0646 \u0639\u0627\u062f\u0649 \u0627\u0644\u0644\u0647 \u0648\u0645\u0644\u0627\u0626\u0643\u062a\u0647\u060c \u0648\u0631\u0633\u0644\u0647 \u0645\u0646 \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u0623\u0648 \u0627\u0644\u0628\u0634\u0631\u060c \u0648\u0628\u062e\u0627\u0635\u0629 \u0627\u0644\u0645\u064e\u0644\u064e\u0643\u0627\u0646 \u062c\u0628\u0631\u064a\u0644\u064f \u0648\u0645\u064a\u0643\u0627\u0644\u064f\u061b \u0644\u0623\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0632\u0639\u0645\u0648\u0627 \u0623\u0646 \u062c\u0628\u0631\u064a\u0644 \u0639\u062f\u0648\u0647\u0645\u060c \u0648\u0645\u064a\u0643\u0627\u0644 \u0648\u0644\u064a\u0651\u064f\u0647\u0645\u060c \u0641\u0623\u0639\u0644\u0645\u0647\u0645 \u0627\u0644\u0644\u0647 \u0623\u0646\u0647 \u0645\u0646 \u0639\u0627\u062f\u0649 \u0648\u0627\u062d\u062f\u064b\u0627 \u0645\u0646\u0647\u0645\u0627 \u0641\u0642\u062f \u0639\u0627\u062f\u0649 \u0627\u0644\u0622\u062e\u0631\u060c \u0648\u0639\u0627\u062f\u0649 \u0627\u0644\u0644\u0647 \u0623\u064a\u0636\u064b\u0627\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0639\u062f\u0648 \u0644\u0644\u062c\u0627\u062d\u062f\u064a\u0646 \u0645\u0627 \u0623\u0646\u0632\u0644 \u0639\u0644\u0649 \u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645.","2:99":"\u0648\u0644\u0642\u062f \u0623\u0646\u0632\u0644\u0646\u0627 \u0625\u0644\u064a\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0622\u064a\u0627\u062a \u0628\u064a\u0646\u0627\u062a \u0648\u0627\u0636\u062d\u0627\u062a \u062a\u062f\u0644 \u0639\u0644\u0649 \u0623\u0646\u0651\u0643 \u0631\u0633\u0648\u0644 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0635\u062f\u0642\u0627 \u0648\u062d\u0642\u0627\u060c \u0648\u0645\u0627 \u064a\u0646\u0643\u0631 \u062a\u0644\u0643 \u0627\u0644\u0622\u064a\u0627\u062a \u0625\u0644\u0627 \u0627\u0644\u062e\u0627\u0631\u062c\u0648\u0646 \u0639\u0646 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647.","2:100":"\u0645\u0627 \u0623\u0642\u0628\u062d \u062d\u0627\u0644 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0641\u064a \u0646\u0642\u0636\u0647\u0645 \u0644\u0644\u0639\u0647\u0648\u062f!! \u0641\u0643\u0644\u0645\u0627 \u0639\u0627\u0647\u062f\u0648\u0627 \u0639\u0647\u062f\u064b\u0627 \u0637\u0631\u062d \u0630\u0644\u0643 \u0627\u0644\u0639\u0647\u062f \u0641\u0631\u064a\u0642 \u0645\u0646\u0647\u0645\u060c \u0648\u0646\u0642\u0636\u0648\u0647\u060c \u0641\u062a\u0631\u0627\u0647\u0645 \u064a\u064f\u0628\u0652\u0631\u0650\u0645\u0648\u0646 \u0627\u0644\u0639\u0647\u062f \u0627\u0644\u064a\u0648\u0645 \u0648\u064a\u0646\u0642\u0636\u0648\u0646\u0647 \u063a\u062f\u064b\u0627\u060c \u0628\u0644 \u0623\u0643\u062b\u0631\u0647\u0645 \u0644\u0627 \u064a\u0635\u062f\u0651\u0650\u0642\u0648\u0646 \u0628\u0645\u0627 \u062c\u0627\u0621 \u0628\u0647 \u0646\u0628\u064a \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645.","2:101":"\u0648\u0644\u0645\u0627 \u062c\u0627\u0621\u0647\u0645 \u0645\u062d\u0645\u062f \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0628\u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0645\u0648\u0627\u0641\u0642 \u0644\u0645\u0627 \u0645\u0639\u0647\u0645 \u0645\u0646 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0637\u0631\u062d \u0641\u0631\u064a\u0642 \u0645\u0646\u0647\u0645 \u0643\u062a\u0627\u0628 \u0627\u0644\u0644\u0647\u060c \u0648\u062c\u0639\u0644\u0648\u0647 \u0648\u0631\u0627\u0621 \u0638\u0647\u0648\u0631\u0647\u0645\u060c \u0634\u0623\u0646\u0647\u0645 \u0634\u0623\u0646 \u0627\u0644\u062c\u0647\u0627\u0644 \u0627\u0644\u0630\u064a\u0646 \u0644\u0627 \u064a\u0639\u0644\u0645\u0648\u0646 \u062d\u0642\u064a\u0642\u062a\u0647.","2:102":"\u0648\u0627\u062a\u0628\u0639 \u0627\u0644\u064a\u0647\u0648\u062f \u0645\u0627 \u062a\u064f\u062d\u064e\u062f\u0651\u0650\u062b \u0627\u0644\u0634\u064a\u0627\u0637\u064a\u0646\u064f \u0628\u0647 \u0627\u0644\u0633\u062d\u0631\u0629\u064e \u0639\u0644\u0649 \u0639\u0647\u062f \u0645\u0644\u0643 \u0633\u0644\u064a\u0645\u0627\u0646 \u0628\u0646 \u062f\u0627\u0648\u062f. \u0648\u0645\u0627 \u0643\u0641\u0631 \u0633\u0644\u064a\u0645\u0627\u0646 \u0648\u0645\u0627 \u062a\u064e\u0639\u064e\u0644\u0651\u064e\u0645 \u0627\u0644\u0633\u0651\u0650\u062d\u0631\u060c \u0648\u0644\u0643\u0646\u0651\u064e \u0627\u0644\u0634\u064a\u0627\u0637\u064a\u0646 \u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u062d\u064a\u0646 \u0639\u0644\u0651\u064e\u0645\u0648\u0627 \u0627\u0644\u0646\u0627\u0633 \u0627\u0644\u0633\u062d\u0631; \u0625\u0641\u0633\u0627\u062f\u064b\u0627 \u0644\u062f\u064a\u0646\u0647\u0645. \u0648\u0643\u0630\u0644\u0643 \u0627\u062a\u0628\u0639 \u0627\u0644\u064a\u0647\u0648\u062f \u0627\u0644\u0633\u0651\u0650\u062d\u0631 \u0627\u0644\u0630\u064a \u0623\u064f\u0646\u0632\u0644 \u0639\u0644\u0649 \u0627\u0644\u0645\u0644\u064e\u0643\u064e\u064a\u0646 \u0647\u0627\u0631\u0648\u062a \u0648\u0645\u0627\u0631\u0648\u062a\u060c \u0628\u0623\u0631\u0636 \xab\u0628\u0627\u0628\u0644\xbb \u0641\u064a \xab\u0627\u0644\u0639\u0631\u0627\u0642\xbb ; \u0627\u0645\u062a\u062d\u0627\u0646\u064b\u0627 \u0648\u0627\u0628\u062a\u0644\u0627\u0621 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0644\u0639\u0628\u0627\u062f\u0647\u060c \u0648\u0645\u0627 \u064a\u0639\u0644\u0651\u0650\u0645 \u0627\u0644\u0645\u0644\u0643\u0627\u0646 \u0645\u0646 \u0623\u062d\u062f \u062d\u062a\u0649 \u064a\u0646\u0635\u062d\u0627\u0647 \u0648\u064a\u062d\u0630\u0651\u0650\u0631\u0627\u0647 \u0645\u0646 \u062a\u0639\u0644\u0645 \u0627\u0644\u0633\u062d\u0631\u060c \u0648\u064a\u0642\u0648\u0644\u0627 \u0644\u0647: \u0644\u0627 \u062a\u0643\u0641\u0631 \u0628\u062a\u0639\u0644\u0645 \u0627\u0644\u0633\u0651\u0650\u062d\u0631 \u0648\u0637\u0627\u0639\u0629 \u0627\u0644\u0634\u064a\u0627\u0637\u064a\u0646. \u0641\u064a\u062a\u0639\u0644\u0645 \u0627\u0644\u0646\u0627\u0633 \u0645\u0646 \u0627\u0644\u0645\u0644\u0643\u064a\u0646 \u0645\u0627 \u064a\u064f\u062d\u0652\u062f\u0650\u062b\u0648\u0646 \u0628\u0647 \u0627\u0644\u0643\u0631\u0627\u0647\u064a\u0629 \u0628\u064a\u0646 \u0627\u0644\u0632\u0648\u062c\u064a\u0646 \u062d\u062a\u0649 \u064a\u062a\u0641\u0631\u0642\u0627. \u0648\u0644\u0627 \u064a\u0633\u062a\u0637\u064a\u0639 \u0627\u0644\u0633\u062d\u0631\u0629 \u0623\u0646 \u064a\u0636\u0631\u0648\u0627 \u0628\u0647 \u0623\u062d\u062f\u064b\u0627 \u0625\u0644\u0627 \u0628\u0625\u0630\u0646 \u0627\u0644\u0644\u0647 \u0648\u0642\u0636\u0627\u0626\u0647. \u0648\u0645\u0627 \u064a\u062a\u0639\u0644\u0645 \u0627\u0644\u0633\u062d\u0631\u0629 \u0625\u0644\u0627 \u0634\u0631\u064b\u0627 \u064a\u0636\u0631\u0647\u0645 \u0648\u0644\u0627 \u064a\u0646\u0641\u0639\u0647\u0645\u060c \u0648\u0642\u062f \u0646\u0642\u0644\u062a\u0647 \u0627\u0644\u0634\u064a\u0627\u0637\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u064a\u0647\u0648\u062f\u060c \u0641\u0634\u0627\u0639 \u0641\u064a\u0647\u0645 \u062d\u062a\u0649 \u0641\u0636\u0651\u064e\u0644\u0648\u0647 \u0639\u0644\u0649 \u0643\u062a\u0627\u0628 \u0627\u0644\u0644\u0647. \u0648\u0644\u0642\u062f \u0639\u0644\u0645 \u0627\u0644\u064a\u0647\u0648\u062f \u0623\u0646 \u0645\u0646 \u0627\u062e\u062a\u0627\u0631 \u0627\u0644\u0633\u0651\u0650\u062d\u0631 \u0648\u062a\u0631\u0643 \u0627\u0644\u062d\u0642 \u0645\u0627 \u0644\u0647 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u0645\u0646 \u0646\u0635\u064a\u0628 \u0641\u064a \u0627\u0644\u062e\u064a\u0631. \u0648\u0644\u0628\u0626\u0633 \u0645\u0627 \u0628\u0627\u0639\u0648\u0627 \u0628\u0647 \u0623\u0646\u0641\u0633\u0647\u0645 \u0645\u0646 \u0627\u0644\u0633\u062d\u0631 \u0648\u0627\u0644\u0643\u0641\u0631 \u0639\u0648\u0636\u064b\u0627 \u0639\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0645\u062a\u0627\u0628\u0639\u0629 \u0627\u0644\u0631\u0633\u0648\u0644\u060c \u0644\u0648 \u0643\u0627\u0646 \u0644\u0647\u0645 \u0639\u0650\u0644\u0652\u0645\u064c \u064a\u062b\u0645\u0631 \u0627\u0644\u0639\u0645\u0644 \u0628\u0645\u0627 \u0648\u064f\u0639\u0650\u0638\u0648\u0627 \u0628\u0647.","2:103":"\u0648\u0644\u0648 \u0623\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0622\u0645\u0646\u0648\u0627 \u0648\u062e\u0627\u0641\u0648\u0627 \u0627\u0644\u0644\u0647 \u0644\u0623\u064a\u0642\u0646\u0648\u0627 \u0623\u0646 \u062b\u0648\u0627\u0628 \u0627\u0644\u0644\u0647 \u062e\u064a\u0631 \u0644\u0647\u0645 \u0645\u0646 \u0627\u0644\u0633\u0651\u0650\u062d\u0631 \u0648\u0645\u0645\u0627 \u0627\u0643\u062a\u0633\u0628\u0648\u0647 \u0628\u0647\u060c \u0644\u0648 \u0643\u0627\u0646\u0648\u0627 \u064a\u0639\u0644\u0645\u0648\u0646 \u0645\u0627 \u064a\u062d\u0635\u0644 \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0627\u0644\u062a\u0642\u0648\u0649 \u0645\u0646 \u0627\u0644\u062b\u0648\u0627\u0628 \u0648\u0627\u0644\u062c\u0632\u0627\u0621 \u0639\u0644\u0645\u0627 \u062d\u0642\u064a\u0642\u064a\u0627 \u0644\u0622\u0645\u0646\u0648\u0627.","2:104":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0644\u0627 \u062a\u0642\u0648\u0644\u0648\u0627 \u0644\u0644\u0631\u0633\u0648\u0644 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645: \u0631\u0627\u0639\u0646\u0627\u060c \u0623\u064a: \u0631\u0627\u0639\u0646\u0627 \u0633\u0645\u0639\u0643\u060c \u0641\u0627\u0641\u0647\u0645 \u0639\u0646\u0627 \u0648\u0623\u0641\u0647\u0645\u0646\u0627; \u0644\u0623\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0643\u0627\u0646\u0648\u0627 \u064a\u0642\u0648\u0644\u0648\u0646\u0647\u0627 \u0644\u0644\u0646\u0628\u064a \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u064a\u0644\u0648\u0648\u0646 \u0623\u0644\u0633\u0646\u062a\u0647\u0645 \u0628\u0647\u0627\u060c \u064a\u0642\u0635\u062f\u0648\u0646 \u0633\u0628\u0651\u064e\u0647 \u0648\u0646\u0633\u0628\u062a\u0647 \u0625\u0644\u0649 \u0627\u0644\u0631\u0639\u0648\u0646\u0629\u060c \u0648\u0642\u0648\u0644\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0628\u062f\u0644\u0627 \u0645\u0646\u0647\u0627: \u0627\u0646\u0638\u0631\u0646\u0627\u060c \u0623\u064a \u0627\u0646\u0638\u0631 \u0625\u0644\u064a\u0646\u0627 \u0648\u062a\u0639\u0647\u0651\u064e\u062f\u0652\u0646\u0627\u060c \u0648\u0647\u064a \u062a\u0624\u062f\u064a \u0627\u0644\u0645\u0639\u0646\u0649 \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0646\u0641\u0633\u0647 \u0648\u0627\u0633\u0645\u0639\u0648\u0627 \u0645\u0627 \u064a\u062a\u0644\u0649 \u0639\u0644\u064a\u0643\u0645 \u0645\u0646 \u0643\u062a\u0627\u0628 \u0631\u0628\u0643\u0645 \u0648\u0627\u0641\u0647\u0645\u0648\u0647. \u0648\u0644\u0644\u062c\u0627\u062d\u062f\u064a\u0646 \u0639\u0630\u0627\u0628 \u0645\u0648\u062c\u0639.","2:105":"\u0645\u0627 \u064a\u062d\u0628 \u0627\u0644\u0643\u0641\u0627\u0631 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0648\u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0623\u0646 \u064a\u064f\u0646\u0632\u0651\u064e\u0644 \u0639\u0644\u064a\u0643\u0645 \u0623\u062f\u0646\u0649 \u062e\u064a\u0631 \u0645\u0646 \u0631\u0628\u0643\u0645 \u0642\u0631\u0622\u0646\u064b\u0627 \u0623\u0648 \u0639\u0644\u0645\u064b\u0627\u060c \u0623\u0648 \u0646\u0635\u0631\u064b\u0627 \u0623\u0648 \u0628\u0634\u0627\u0631\u0629. \u0648\u0627\u0644\u0644\u0647 \u064a\u062e\u062a\u0635 \u0628\u0631\u062d\u0645\u062a\u0647 \u0645\u064e\u0646 \u064a\u0634\u0627\u0621 \u0645\u0650\u0646 \u0639\u0628\u0627\u062f\u0647 \u0628\u0627\u0644\u0646\u0628\u0648\u0629 \u0648\u0627\u0644\u0631\u0633\u0627\u0644\u0629. \u0648\u0627\u0644\u0644\u0647 \u0630\u0648 \u0627\u0644\u0639\u0637\u0627\u0621 \u0627\u0644\u0643\u062b\u064a\u0631 \u0627\u0644\u0648\u0627\u0633\u0639.","2:106":"\u0645\u0627 \u0646\u0628\u062f\u0651\u0650\u0644 \u0645\u0646 \u0622\u064a\u0629 \u0623\u0648 \u0646\u064f\u0632\u0650\u0644\u0647\u0627 \u0645\u0646 \u0627\u0644\u0642\u0644\u0648\u0628 \u0648\u0627\u0644\u0623\u0630\u0647\u0627\u0646 \u0646\u0623\u062a \u0628\u0623\u0646\u0641\u0639 \u0644\u0643\u0645 \u0645\u0646\u0647\u0627\u060c \u0623\u0648 \u0646\u0623\u062a \u0628\u0645\u062b\u0644\u0647\u0627 \u0641\u064a \u0627\u0644\u062a\u0643\u0644\u064a\u0641 \u0648\u0627\u0644\u062b\u0648\u0627\u0628\u060c \u0648\u0644\u0643\u0644\u064d \u062d\u0643\u0645\u0629. \u0623\u0644\u0645 \u062a\u0639\u0644\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0623\u0646\u062a \u0648\u0623\u0645\u062a\u0643 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0642\u0627\u062f\u0631 \u0644\u0627 \u064a\u0639\u062c\u0632\u0647 \u0634\u064a\u0621\u061f","2:107":"\u0623\u0645\u0627 \u0639\u0644\u0645\u062a\u064e -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0623\u0646\u062a\u064e \u0648\u0623\u0645\u062a\u0643 \u0623\u0646\u0651\u064e \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0647\u0648 \u0627\u0644\u0645\u0627\u0644\u0643 \u0627\u0644\u0645\u062a\u0635\u0631\u0641 \u0641\u064a \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636\u061f \u064a\u0641\u0639\u0644 \u0645\u0627 \u064a\u0634\u0627\u0621\u060c \u0648\u064a\u062d\u0643\u0645 \u0645\u0627 \u064a\u0631\u064a\u062f\u060c \u0648\u064a\u0623\u0645\u0631 \u0639\u0628\u0627\u062f\u0647 \u0648\u064a\u0646\u0647\u0627\u0647\u0645 \u0643\u064a\u0641\u0645\u0627 \u0634\u0627\u0621\u060c \u0648\u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0637\u0627\u0639\u0629 \u0648\u0627\u0644\u0642\u064e\u0628\u0648\u0644. \u0648\u0644\u064a\u0639\u0644\u0645 \u0645\u0646 \u0639\u0635\u0649 \u0623\u0646 \u0644\u064a\u0633 \u0644\u0623\u062d\u062f \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0648\u0644\u064a\u0651\u064d \u064a\u062a\u0648\u0644\u0627\u0647\u0645\u060c \u0648\u0644\u0627 \u0646\u0635\u064a\u0631 \u064a\u0645\u0646\u0639\u0647\u0645 \u0645\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647.","2:108":"\u0628\u0644 \u0623\u062a\u0631\u064a\u062f\u0648\u0646 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633- \u0623\u0646 \u062a\u0637\u0644\u0628\u0648\u0627 \u0645\u0646 \u0631\u0633\u0648\u0644\u0643\u0645 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0623\u0634\u064a\u0627\u0621 \u0628\u0642\u0635\u062f \u0627\u0644\u0639\u0646\u0627\u062f \u0648\u0627\u0644\u0645\u0643\u0627\u0628\u0631\u0629\u060c \u0643\u0645\u0627 \u0637\u064f\u0644\u0650\u0628\u064e \u0645\u062b\u0644 \u0630\u0644\u0643 \u0645\u0646 \u0645\u0648\u0633\u0649. \u0639\u0644\u0645\u0648\u0627 \u0623\u0646 \u0645\u0646 \u064a\u062e\u062a\u0631 \u0627\u0644\u0643\u0641\u0631 \u0648\u064a\u062a\u0631\u0643 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0641\u0642\u062f \u062e\u0631\u062c \u0639\u0646 \u0635\u0631\u0627\u0637 \u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645 \u0625\u0644\u0649 \u0627\u0644\u062c\u0647\u0644 \u0648\u0627\u0644\u0636\u0651\u064e\u0644\u0627\u0644.","2:109":"\u062a\u0645\u0646\u0649 \u0643\u062b\u064a\u0631 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0623\u0646 \u064a\u064f\u0631\u0652\u062c\u0650\u0639\u064f\u0648\u064f\u0643\u0645 \u0628\u0639\u062f \u0625\u064a\u0645\u0627\u0646\u0643\u0645 \u0643\u0641\u0627\u0631\u064b\u0627 \u0643\u0645\u0627 \u0643\u0646\u062a\u0645 \u0645\u0646 \u0642\u0628\u0644\u064f \u062a\u0639\u0628\u062f\u0648\u0646 \u0627\u0644\u0623\u0635\u0646\u0627\u0645; \u0628\u0633\u0628\u0628 \u0627\u0644\u062d\u0642\u062f \u0627\u0644\u0630\u064a \u0627\u0645\u062a\u0644\u0623\u062a \u0628\u0647 \u0646\u0641\u0648\u0633\u0647\u0645 \u0645\u0646 \u0628\u0639\u062f \u0645\u0627 \u062a\u0628\u064a\u0651\u064e\u0646 \u0644\u0647\u0645 \u0635\u062f\u0642 \u0646\u0628\u064a \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0641\u064a\u0645\u0627 \u062c\u0627\u0621 \u0628\u0647\u060c \u0641\u062a\u062c\u0627\u0648\u0632\u0648\u0627 \u0639\u0645\u0651\u064e\u0627 \u0643\u0627\u0646 \u0645\u0646\u0647\u0645 \u0645\u0646 \u0625\u0633\u0627\u0621\u0629 \u0648\u062e\u0637\u0623\u060c \u0648\u0627\u0635\u0641\u062d\u0648\u0627 \u0639\u0646 \u062c\u0647\u0644\u0647\u0645\u060c \u062d\u062a\u0649 \u064a\u0623\u062a\u064a \u0627\u0644\u0644\u0647 \u0628\u062d\u0643\u0645\u0647 \u0641\u064a\u0647\u0645 \u0628\u0642\u062a\u0627\u0644\u0647\u0645 (\u0648\u0642\u062f \u062c\u0627\u0621 \u0648\u0648\u0642\u0639) \u060c \u0648\u0633\u064a\u0639\u0627\u0642\u0628\u0647\u0645 \u0644\u0633\u0648\u0621 \u0623\u0641\u0639\u0627\u0644\u0647\u0645. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0643\u0644 \u0634\u064a\u0621 \u0642\u062f\u064a\u0631 \u0644\u0627 \u064a\u0639\u062c\u0632\u0647 \u0634\u064a\u0621.","2:110":"\u0648\u0627\u0634\u062a\u063a\u0644\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0628\u0623\u062f\u0627\u0621 \u0627\u0644\u0635\u0644\u0627\u0629 \u0639\u0644\u0649 \u0648\u062c\u0647\u0647\u0627 \u0627\u0644\u0635\u062d\u064a\u062d\u060c \u0648\u0625\u0639\u0637\u0627\u0621 \u0627\u0644\u0632\u0643\u0627\u0629 \u0627\u0644\u0645\u0641\u0631\u0648\u0636\u0629. \u0648\u0627\u0639\u0644\u0645\u0648\u0627 \u0623\u0646\u0651\u064e \u0643\u0644 \u062e\u064a\u0631 \u062a\u0642\u062f\u0645\u0648\u0646\u0647 \u0644\u0623\u0646\u0641\u0633\u0643\u0645 \u062a\u062c\u062f\u0648\u0646 \u062b\u0648\u0627\u0628\u0647 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629. \u0625\u0646\u0647 \u062a\u0639\u0627\u0644\u0649 \u0628\u0635\u064a\u0631 \u0628\u0643\u0644 \u0623\u0639\u0645\u0627\u0644\u0643\u0645\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a\u0643\u0645 \u0639\u0644\u064a\u0647\u0627.","2:111":"\u0627\u062f\u0651\u064e\u0639\u0649 \u0643\u0644\u0651\u064c \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0623\u0646 \u0627\u0644\u062c\u0646\u0629 \u062e\u0627\u0635\u0629 \u0628\u0637\u0627\u0626\u0641\u062a\u0647 \u0644\u0627 \u064a\u062f\u062e\u0644\u0647\u0627 \u063a\u064a\u0631\u0647\u0645\u060c \u062a\u0644\u0643 \u0623\u0648\u0647\u0627\u0645\u0647\u0645 \u0627\u0644\u0641\u0627\u0633\u062f\u0629. \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0623\u062d\u0636\u0631\u0648\u0627 \u062f\u0644\u064a\u0644\u0643\u0645 \u0639\u0644\u0649 \u0635\u062d\u0629 \u0645\u0627 \u062a\u062f\u0651\u064e\u0639\u0648\u0646 \u0625\u0646 \u0643\u0646\u062a\u0645 \u0635\u0627\u062f\u0642\u064a\u0646 \u0641\u064a \u062f\u0639\u0648\u0627\u0643\u0645.","2:112":"\u0644\u064a\u0633 \u0627\u0644\u0623\u0645\u0631 \u0643\u0645\u0627 \u0632\u0639\u0645\u0648\u0627 \u0623\u0646\u0651\u064e \u0627\u0644\u062c\u0646\u0629 \u062a\u062e\u062a\u0635 \u0628\u0637\u0627\u0626\u0641\u0629 \u062f\u0648\u0646 \u063a\u064a\u0631\u0647\u0627\u060c \u0648\u0625\u0646\u0645\u0627 \u064a\u062f\u062e\u0644 \u0627\u0644\u062c\u0646\u0651\u064e\u0629 \u0645\u064e\u0646 \u0623\u062e\u0644\u0635 \u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0644\u0627 \u0634\u0631\u064a\u0643 \u0644\u0647\u060c \u0648\u0647\u0648 \u0645\u062a\u0628\u0639 \u0644\u0644\u0631\u0633\u0648\u0644 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0641\u064a \u0643\u0644 \u0623\u0642\u0648\u0627\u0644\u0647 \u0648\u0623\u0639\u0645\u0627\u0644\u0647. \u0641\u0645\u0646 \u0641\u0639\u0644 \u0630\u0644\u0643 \u0641\u0644\u0647 \u062b\u0648\u0627\u0628 \u0639\u0645\u0644\u0647 \u0639\u0646\u062f \u0631\u0628\u0647 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u0647\u0648 \u062f\u062e\u0648\u0644 \u0627\u0644\u062c\u0646\u0629\u060c \u0648\u0647\u0645 \u0644\u0627 \u064a\u062e\u0627\u0641\u0648\u0646 \u0641\u064a\u0645\u0627 \u064a\u0633\u062a\u0642\u0628\u0644\u0648\u0646\u0647 \u0645\u0646 \u0623\u0645\u0631 \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u0644\u0627 \u0647\u0645 \u064a\u062d\u0632\u0646\u0648\u0646 \u0639\u0644\u0649 \u0645\u0627 \u0641\u0627\u062a\u0647\u0645 \u0645\u0646 \u062d\u0638\u0648\u0638 \u0627\u0644\u062f\u0646\u064a\u0627.","2:113":"\u0648\u0642\u0627\u0644\u062a \u0627\u0644\u064a\u0647\u0648\u062f: \u0644\u064a\u0633\u062a \u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0639\u0644\u0649 \u0634\u064a\u0621 \u0645\u0646 \u0627\u0644\u062f\u064a\u0646 \u0627\u0644\u0635\u062d\u064a\u062d\u060c \u0648\u0643\u0630\u0644\u0643 \u0642\u0627\u0644\u062a \u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0641\u064a \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0647\u0645 \u064a\u0642\u0631\u0624\u0648\u0646 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644\u060c \u0648\u0641\u064a\u0647\u0645\u0627 \u0648\u062c\u0648\u0628 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u062c\u0645\u064a\u0639\u064b\u0627. \u0643\u0630\u0644\u0643 \u0642\u0627\u0644 \u0627\u0644\u0630\u064a\u0646 \u0644\u0627 \u064a\u0639\u0644\u0645\u0648\u0646 \u0645\u0646 \u0645\u0634\u0631\u0643\u064a \u0627\u0644\u0639\u0631\u0628 \u0648\u063a\u064a\u0631\u0647\u0645 \u0645\u062b\u0644 \u0642\u0648\u0644\u0647\u0645\u060c \u0623\u064a \u0642\u0627\u0644\u0648\u0627 \u0644\u0643\u0644 \u0630\u064a \u062f\u064a\u0646: \u0644\u0633\u062a\u064e \u0639\u0644\u0649 \u0634\u064a\u0621\u060c \u0641\u0627\u0644\u0644\u0647 \u064a\u0641\u0635\u0644 \u0628\u064a\u0646\u0647\u0645 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u0641\u064a\u0645\u0627 \u0627\u062e\u062a\u0644\u0641\u0648\u0627 \u0641\u064a\u0647 \u0645\u0650\u0646 \u0623\u0645\u0631 \u0627\u0644\u062f\u064a\u0646\u060c \u0648\u064a\u062c\u0627\u0632\u064a \u0643\u0644\u0627 \u0628\u0639\u0645\u0644\u0647.","2:114":"\u0644\u0627 \u0623\u062d\u062f \u0623\u0638\u0644\u0645 \u0645\u0646 \u0627\u0644\u0630\u064a\u0646 \u0645\u064e\u0646\u064e\u0639\u064f\u0648\u0627 \u0630\u0650\u0643\u0652\u0631\u064e \u0627\u0644\u0644\u0647 \u0641\u064a \u0627\u0644\u0645\u0633\u0627\u062c\u062f \u0645\u0646 \u0625\u0642\u0627\u0645 \u0627\u0644\u0635\u0644\u0627\u0629\u060c \u0648\u062a\u0644\u0627\u0648\u0629 \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0648\u0646\u062d\u0648 \u0630\u0644\u0643\u060c \u0648\u062c\u062f\u0651\u064f\u0648\u0627 \u0641\u064a \u062a\u062e\u0631\u064a\u0628\u0647\u0627 \u0628\u0627\u0644\u0647\u062f\u0645 \u0623\u0648 \u0627\u0644\u0625\u063a\u0644\u0627\u0642\u060c \u0623\u0648 \u0628\u0645\u0646\u0639 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0645\u0646\u0647\u0627. \u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0638\u0627\u0644\u0645\u0648\u0646 \u0645\u0627 \u0643\u0627\u0646 \u064a\u0646\u0628\u063a\u064a \u0644\u0647\u0645 \u0623\u0646 \u064a\u062f\u062e\u0644\u0648\u0627 \u0627\u0644\u0645\u0633\u0627\u062c\u062f \u0625\u0644\u0627 \u0639\u0644\u0649 \u062e\u0648\u0641 \u0648\u064e\u0648\u064e\u062c\u064e\u0644\u064d \u0645\u0646 \u0627\u0644\u0639\u0642\u0648\u0628\u0629\u060c \u0644\u0647\u0645 \u0628\u0630\u0644\u0643 \u0635\u064e\u063a\u0627\u0631 \u0648\u0641\u0636\u064a\u062d\u0629 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0644\u0647\u0645 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u0639\u0630\u0627\u0628 \u0634\u062f\u064a\u062f.","2:115":"\u0648\u0644\u0644\u0647 \u062c\u0647\u062a\u0627 \u0634\u0631\u0648\u0642 \u0627\u0644\u0634\u0645\u0633 \u0648\u063a\u0631\u0648\u0628\u0647\u0627 \u0648\u0645\u0627 \u0628\u064a\u0646\u0647\u0645\u0627\u060c \u0641\u0647\u0648 \u0645\u0627\u0644\u0643 \u0627\u0644\u0623\u0631\u0636 \u0643\u0644\u0647\u0627. \u0641\u0623\u064a \u062c\u0647\u0629 \u062a\u0648\u062c\u0647\u062a\u0645 \u0625\u0644\u064a\u0647\u0627 \u0641\u064a \u0627\u0644\u0635\u0644\u0627\u0629 \u0628\u0623\u0645\u0631 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0641\u0625\u0646\u0643\u0645 \u0645\u0628\u062a\u063a\u0648\u0646 \u0648\u062c\u0647\u0647\u060c \u0644\u0645 \u062a\u062e\u0631\u062c\u0648\u0627 \u0639\u0646 \u0645\u0644\u0643\u0647 \u0648\u0637\u0627\u0639\u062a\u0647. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0648\u0627\u0633\u0639 \u0627\u0644\u0631\u062d\u0645\u0629 \u0628\u0639\u0628\u0627\u062f\u0647\u060c \u0639\u0644\u064a\u0645 \u0628\u0623\u0641\u0639\u0627\u0644\u0647\u0645\u060c \u0644\u0627 \u064a\u063a\u064a\u0628 \u0639\u0646\u0647 \u0645\u0646\u0647\u0627 \u0634\u064a\u0621.","2:116":"\u0648\u0642\u0627\u0644\u062a \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0648\u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646: \u0627\u062a\u062e\u0630 \u0627\u0644\u0644\u0647 \u0644\u0646\u0641\u0633\u0647 \u0648\u0644\u062f\u064b\u0627\u060c \u062a\u0646\u0632\u0651\u064e\u0647 \u0627\u0644\u0644\u0647 -\u0633\u0628\u062d\u0627\u0646\u0647- \u0639\u0646 \u0647\u0630\u0627 \u0627\u0644\u0642\u0648\u0644 \u0627\u0644\u0628\u0627\u0637\u0644\u060c \u0628\u0644 \u0643\u0644 \u0645\u064e\u0646 \u0641\u064a \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636 \u0645\u0644\u0643\u0647 \u0648\u0639\u0628\u064a\u062f\u0647\u060c \u0648\u0647\u0645 \u062c\u0645\u064a\u0639\u064b\u0627 \u062e\u0627\u0636\u0639\u0648\u0646 \u0644\u0647\u060c \u0645\u0633\u062e\u0651\u064e\u0631\u0648\u0646 \u062a\u062d\u062a \u062a\u062f\u0628\u064a\u0631\u0647.","2:117":"\u0648\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0647\u0648 \u062e\u0627\u0644\u0642 \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636 \u0639\u0644\u0649 \u063a\u064a\u0631 \u0645\u062b\u0627\u0644 \u0633\u0628\u0642. \u0648\u0625\u0630\u0627 \u0642\u062f\u0651\u064e\u0631 \u0623\u0645\u0631\u064b\u0627 \u0648\u0623\u0631\u0627\u062f \u0643\u0648\u0646\u0647 \u0641\u0625\u0646\u0645\u0627 \u064a\u0642\u0648\u0644 \u0644\u0647: \xab\u0643\u0646\xbb \u0641\u064a\u0643\u0648\u0646.","2:118":"\u0648\u0642\u0627\u0644 \u0627\u0644\u062c\u0647\u0644\u0629 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0648\u063a\u064a\u0631\u0647\u0645 \u0644\u0646\u0628\u064a \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0639\u0644\u0649 \u0633\u0628\u064a\u0644 \u0627\u0644\u0639\u0646\u0627\u062f: \u0647\u0644\u0627 \u064a\u0643\u0644\u0645\u0646\u0627 \u0627\u0644\u0644\u0647 \u0645\u0628\u0627\u0634\u0631\u0629 \u0644\u064a\u062e\u0628\u0631\u0646\u0627 \u0623\u0646\u0643 \u0631\u0633\u0648\u0644\u0647\u060c \u0623\u0648 \u062a\u0623\u062a\u064a\u0646\u0627 \u0645\u0639\u062c\u0632\u0629 \u0645\u0646 \u0627\u0644\u0644\u0647 \u062a\u062f\u0644 \u0639\u0644\u0649 \u0635\u062f\u0642\u0643. \u0648\u0645\u062b\u0644 \u0647\u0630\u0627 \u0627\u0644\u0642\u0648\u0644 \u0642\u0627\u0644\u062a\u0647 \u0627\u0644\u0623\u0645\u0645 \u0645\u0646 \u0642\u0628\u0644\u064f \u0644\u0631\u0633\u0644\u0647\u0627 \u0639\u0646\u0627\u062f\u064b\u0627 \u0648\u0645\u0643\u0627\u0628\u0631\u0629; \u0628\u0633\u0628\u0628 \u062a\u0634\u0627\u0628\u0647 \u0642\u0644\u0648\u0628 \u0627\u0644\u0633\u0627\u0628\u0642\u064a\u0646 \u0648\u0627\u0644\u0644\u0627\u062d\u0642\u064a\u0646 \u0641\u064a \u0627\u0644\u0643\u0641\u0631 \u0648\u0627\u0644\u0636\u0651\u064e\u0644\u0627\u0644\u060c \u0642\u062f \u0623\u0648\u0636\u062d\u0646\u0627 \u0627\u0644\u0622\u064a\u0627\u062a \u0644\u0644\u0630\u064a\u0646 \u064a\u0635\u062f\u0651\u0650\u0642\u0648\u0646 \u062a\u0635\u062f\u064a\u0642\u064b\u0627 \u062c\u0627\u0632\u0645\u064b\u0627\u061b \u0644\u0643\u0648\u0646\u0647\u0645 \u0645\u0624\u0645\u0646\u064a\u0646 \u0628\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0645\u062a\u0651\u064e\u0628\u0639\u064a\u0646 \u0645\u0627 \u0634\u0631\u0639\u0647 \u0644\u0647\u0645.","2:119":"\u0625\u0646\u0651\u064e\u0627 \u0623\u0631\u0633\u0644\u0646\u0627\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644\u064f- \u0628\u0627\u0644\u062f\u0651\u0650\u064a\u0652\u0646\u0650 \u0627\u0644\u062d\u0642 \u0627\u0644\u0645\u0624\u064a\u062f \u0628\u0627\u0644\u062d\u062c\u062c \u0648\u0627\u0644\u0645\u0639\u062c\u0632\u0627\u062a\u060c \u0641\u0628\u0644\u0651\u0650\u063a\u0647 \u0644\u0644\u0646\u0627\u0633 \u0645\u0639 \u062a\u0628\u0634\u064a\u0631 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0628\u062e\u064a\u0631\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u062a\u062e\u0648\u064a\u0641 \u0627\u0644\u0645\u0639\u0627\u0646\u062f\u064a\u0646 \u0628\u0645\u0627 \u064a\u0646\u062a\u0638\u0631\u0647\u0645 \u0645\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0633\u062a -\u0628\u0639\u062f \u0627\u0644\u0628\u0644\u0627\u063a- \u0645\u0633\u0626\u0648\u0644\u0627 \u0639\u0646 \u0643\u0641\u0631 \u0645\u064e\u0646 \u0643\u0641\u0631 \u0628\u0643; \u0641\u0625\u0646\u0647\u0645 \u064a\u062f\u062e\u0644\u0648\u0646 \u0627\u0644\u0646\u0627\u0631 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u0648\u0644\u0627 \u064a\u062e\u0631\u062c\u0648\u0646 \u0645\u0646\u0647\u0627.","2:120":"\u0648\u0644\u0646 \u062a\u0631\u0636\u0649 \u0639\u0646\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0644\u0627 \u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0625\u0644\u0627 \u0625\u0630\u0627 \u062a\u0631\u0643\u062a \u062f\u064a\u0646\u0643 \u0648\u0627\u062a\u0628\u0639\u062a\u064e \u062f\u064a\u0646\u0647\u0645. \u0642\u0644 \u0644\u0647\u0645: \u0625\u0646 \u062f\u064a\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0647\u0648 \u0627\u0644\u062f\u064a\u0646 \u0627\u0644\u0635\u062d\u064a\u062d. \u0648\u0644\u0626\u0646 \u0627\u062a\u0628\u0639\u062a \u0623\u0647\u0648\u0627\u0621 \u0647\u0624\u0644\u0627\u0621 \u0628\u0639\u062f \u0627\u0644\u0630\u064a \u062c\u0627\u0621\u0643 \u0645\u0646 \u0627\u0644\u0648\u062d\u064a \u0645\u0627 \u0644\u0643 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0645\u0650\u0646 \u0648\u0644\u064a\u0651\u064d \u064a\u0646\u0641\u0639\u0643\u060c \u0648\u0644\u0627 \u0646\u0635\u064a\u0631 \u064a\u0646\u0635\u0631\u0643. \u0648\u0647\u0630\u0627 \u0627\u0644\u062e\u0637\u0627\u0628 \u0648\u0625\u0646 \u0643\u0627\u0646 \u062e\u0627\u0635\u064b\u0627 \u0628\u0627\u0644\u0646\u0628\u064a \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0641\u0647\u0648 \u0645\u0648\u062c\u0647 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0651\u0629 \u0639\u0627\u0645\u0629.","2:121":"\u0627\u0644\u0630\u064a\u0646 \u0623\u0639\u0637\u064a\u0646\u0627\u0647\u0645 \u0627\u0644\u0643\u062a\u0627\u0628 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649\u060c \u064a\u0642\u0631\u0624\u0648\u0646\u0647 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629\u060c \u0648\u064a\u062a\u0628\u0639\u0648\u0646\u0647 \u062d\u0642 \u0627\u0644\u0627\u062a\u0628\u0627\u0639\u060c \u0648\u064a\u0624\u0645\u0646\u0648\u0646 \u0628\u0645\u0627 \u062c\u0627\u0621 \u0641\u064a\u0647 \u0645\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0631\u0633\u0644 \u0627\u0644\u0644\u0647\u060c \u0648\u0645\u0646\u0647\u0645 \u062e\u0627\u062a\u0645\u0647\u0645 \u0646\u0628\u064a\u0646\u0627 \u0648\u0631\u0633\u0648\u0644\u0646\u0627 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0644\u0627 \u064a\u062d\u0631\u0641\u0648\u0646 \u0648\u0644\u0627 \u064a\u0628\u062f\u0651\u0650\u0644\u0648\u0646 \u0645\u0627 \u062c\u0627\u0621 \u0641\u064a\u0647. \u0647\u0624\u0644\u0627\u0621 \u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u064a\u0624\u0645\u0646\u0648\u0646 \u0628\u0627\u0644\u0646\u0628\u064a \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u0628\u0645\u0627 \u0623\u0646\u0632\u0644 \u0639\u0644\u064a\u0647\u060c \u0648\u0623\u0645\u0627 \u0627\u0644\u0630\u064a\u0646 \u0628\u062f\u0651\u064e\u0644\u0648\u0627 \u0628\u0639\u0636 \u0627\u0644\u0643\u062a\u0627\u0628 \u0648\u0643\u062a\u0645\u0648\u0627 \u0628\u0639\u0636\u0647\u060c \u0641\u0647\u0624\u0644\u0627\u0621 \u0643\u0641\u0627\u0631 \u0628\u0646\u0628\u064a \u0627\u0644\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u0628\u0645\u0627 \u0623\u0646\u0632\u0644 \u0639\u0644\u064a\u0647\u060c \u0648\u0645\u0646 \u064a\u0643\u0641\u0631 \u0628\u0647 \u0641\u0623\u0648\u0644\u0626\u0643 \u0647\u0645 \u0623\u0634\u062f \u0627\u0644\u0646\u0627\u0633 \u062e\u0633\u0631\u0627\u0646\u064b\u0627 \u0639\u0646\u062f \u0627\u0644\u0644\u0647.","2:122":"\u064a\u0627 \u0630\u0631\u064a\u0629 \u064a\u0639\u0642\u0648\u0628 \u0627\u0630\u0643\u0631\u0648\u0627 \u0646\u0639\u0645\u064a \u0627\u0644\u0643\u062b\u064a\u0631\u0629 \u0639\u0644\u064a\u0643\u0645\u060c \u0648\u0623\u0646\u064a \u0641\u064e\u0636\u0651\u064e\u0644\u062a\u0643\u0645 \u0639\u0644\u0649 \u0639\u0627\u0644\u064e\u0645\u064a \u0632\u0645\u0627\u0646\u0643\u0645 \u0628\u0643\u062b\u0631\u0629 \u0623\u0646\u0628\u064a\u0627\u0626\u0643\u0645\u060c \u0648\u0645\u0627 \u0623\u064f\u0646\u0632\u0644 \u0639\u0644\u064a\u0647\u0645 \u0645\u0646 \u0627\u0644\u0643\u062a\u0628.","2:123":"\u0648\u062e\u0627\u0641\u0648\u0627 \u0623\u0647\u0648\u0627\u0644 \u064a\u0648\u0645 \u0627\u0644\u062d\u0633\u0627\u0628 \u0625\u0630 \u0644\u0627 \u062a\u063a\u0646\u064a \u0646\u0641\u0633 \u0639\u0646 \u0646\u0641\u0633 \u0634\u064a\u0626\u064b\u0627\u060c \u0648\u0644\u0627 \u064a\u0642\u0628\u0644 \u0627\u0644\u0644\u0647 \u0645\u0646\u0647\u0627 \u0641\u062f\u064a\u0629 \u062a\u0646\u062c\u064a\u0647\u0627 \u0645\u0646 \u0627\u0644\u0639\u0630\u0627\u0628\u060c \u0648\u0644\u0627 \u062a\u0646\u0641\u0639\u0647\u0627 \u0648\u0633\u0627\u0637\u0629\u060c \u0648\u0644\u0627 \u0623\u062d\u062f \u064a\u0646\u0635\u0631\u0647\u0627.","2:124":"\u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u062d\u064a\u0646 \u0627\u062e\u062a\u0628\u0631 \u0627\u0644\u0644\u0647 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0628\u0645\u0627 \u0634\u0631\u0639 \u0644\u0647 \u0645\u0646 \u062a\u0643\u0627\u0644\u064a\u0641\u060c \u0641\u0623\u062f\u0651\u064e\u0627\u0647\u0627 \u0648\u0642\u0627\u0645 \u0628\u0647\u0627 \u062e\u064a\u0631 \u0642\u064a\u0627\u0645. \u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u0644\u0647: \u0625\u0646\u064a \u062c\u0627\u0639\u0644\u0643 \u0642\u062f\u0648\u0629 \u0644\u0644\u0646\u0627\u0633. \u0642\u0627\u0644 \u0625\u0628\u0631\u0627\u0647\u064a\u0645: \u0631\u0628\u0651\u0650 \u0627\u062c\u0639\u0644 \u0628\u0639\u0636 \u0646\u0633\u0644\u064a \u0623\u0626\u0645\u0629 \u0641\u0636\u0644\u0627 \u0645\u0646\u0643\u060c \u0641\u0623\u062c\u0627\u0628\u0647 \u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0623\u0646\u0647 \u0644\u0627 \u062a\u062d\u0635\u0644 \u0644\u0644\u0638\u0627\u0644\u0645\u064a\u0646 \u0627\u0644\u0625\u0645\u0627\u0645\u0629\u064f \u0641\u064a \u0627\u0644\u062f\u064a\u0646.","2:125":"\u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u062d\u064a\u0646 \u062c\u0639\u0644\u0646\u0627 \u0627\u0644\u0643\u0639\u0628\u0629 \u0645\u0631\u062c\u0639\u064b\u0627 \u0644\u0644\u0646\u0627\u0633\u060c \u064a\u0623\u062a\u0648\u0646\u0647\u060c \u062b\u0645 \u064a\u0631\u062c\u0639\u0648\u0646 \u0625\u0644\u0649 \u0623\u0647\u0644\u064a\u0647\u0645\u060c \u062b\u0645 \u064a\u0639\u0648\u062f\u0648\u0646 \u0625\u0644\u064a\u0647\u060c \u0648\u0645\u062c\u0645\u0639\u064b\u0627 \u0644\u0647\u0645 \u0641\u064a \u0627\u0644\u062d\u062c \u0648\u0627\u0644\u0639\u0645\u0631\u0629 \u0648\u0627\u0644\u0637\u0648\u0627\u0641 \u0648\u0627\u0644\u0635\u0644\u0627\u0629\u060c \u0648\u0623\u0645\u0646\u064b\u0627 \u0644\u0647\u0645\u060c \u0644\u0627 \u064a\u064f\u063a\u0650\u064a\u0631 \u0639\u0644\u064a\u0647\u0645 \u0639\u062f\u0648 \u0641\u064a\u0647. \u0648\u0642\u0644\u0646\u0627: \u0627\u062a\u062e\u0650\u0630\u0648\u0627 \u0645\u0646 \u0645\u0642\u0627\u0645 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0645\u0643\u0627\u0646\u064b\u0627 \u0644\u0644\u0635\u0644\u0627\u0629 \u0641\u064a\u0647\u060c \u0648\u0647\u0648 \u0627\u0644\u062d\u062c\u0631 \u0627\u0644\u0630\u064a \u0648\u0642\u0641 \u0639\u0644\u064a\u0647 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0639\u0646\u062f \u0628\u0646\u0627\u0626\u0647 \u0627\u0644\u0643\u0639\u0628\u0629. \u0648\u0623\u0648\u062d\u064a\u0646\u0627 \u0625\u0644\u0649 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0648\u0627\u0628\u0646\u0647 \u0625\u0633\u0645\u0627\u0639\u064a\u0644: \u0623\u0646 \u0637\u0647\u0651\u0650\u0631\u0627 \u0628\u064a\u062a\u064a \u0645\u0646 \u0643\u0644 \u0631\u062c\u0633 \u0648\u062f\u0646\u0633; \u0644\u0644\u0645\u062a\u0639\u0628\u062f\u064a\u0646 \u0641\u064a\u0647 \u0628\u0627\u0644\u0637\u0648\u0627\u0641 \u062d\u0648\u0644 \u0627\u0644\u0643\u0639\u0628\u0629\u060c \u0623\u0648 \u0627\u0644\u0627\u0639\u062a\u0643\u0627\u0641 \u0641\u064a \u0627\u0644\u0645\u0633\u062c\u062f\u060c \u0648\u0627\u0644\u0635\u0644\u0627\u0629 \u0641\u064a\u0647.","2:126":"\u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u062d\u064a\u0646 \u0642\u0627\u0644 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u062f\u0627\u0639\u064a\u064b\u0627: \u0631\u0628\u0651\u0650 \u0627\u062c\u0639\u0644 \xab\u0645\u0643\u0629\xbb \u0628\u0644\u062f\u064b\u0627 \u0622\u0645\u0646\u064b\u0627 \u0645\u0646 \u0627\u0644\u062e\u0648\u0641\u060c \u0648\u0627\u0631\u0632\u0642 \u0623\u0647\u0644\u0647 \u0645\u0646 \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u062b\u0645\u0631\u0627\u062a\u060c \u0648\u062e\u064f\u0635\u0651\u064e \u0628\u0647\u0630\u0627 \u0627\u0644\u0631\u0632\u0642 \u0645\u064e\u0646 \u0622\u0645\u0646 \u0645\u0646\u0647\u0645 \u0628\u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0622\u062e\u0631. \u0642\u0627\u0644 \u0627\u0644\u0644\u0647: \u0648\u0645\u0646 \u0643\u0641\u0631 \u0645\u0646\u0647\u0645 \u0641\u0623\u0631\u0632\u0642\u0647 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0623\u064f\u0645\u062a\u0639\u0647 \u0645\u062a\u0627\u0639\u064b\u0627 \u0642\u0644\u064a\u0644\u0627 \u062b\u0645 \u0623\u064f\u0644\u062c\u0626\u064f\u0647 \u0645\u0631\u063a\u0645\u064b\u0627 \u0625\u0644\u0649 \u0639\u0630\u0627\u0628 \u0627\u0644\u0646\u0627\u0631. \u0648\u0628\u0626\u0633 \u0627\u0644\u0645\u0631\u062c\u0639 \u0648\u0627\u0644\u0645\u0642\u0627\u0645 \u0647\u0630\u0627 \u0627\u0644\u0645\u0635\u064a\u0631.","2:127":"\u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u062d\u064a\u0646 \u0631\u0641\u0639 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0648\u0625\u0633\u0645\u0627\u0639\u064a\u0644 \u0623\u0633\u0633 \u0627\u0644\u0643\u0639\u0628\u0629\u060c \u0648\u0647\u0645\u0627 \u064a\u062f\u0639\u0648\u0627\u0646 \u0627\u0644\u0644\u0647 \u0641\u064a \u062e\u0634\u0648\u0639: \u0631\u0628\u0646\u0627 \u062a\u0642\u0628\u0644 \u0645\u0646\u0651\u064e\u0627 \u0635\u0627\u0644\u062d \u0623\u0639\u0645\u0627\u0644\u0646\u0627 \u0648\u062f\u0639\u0627\u0621\u0646\u0627\u060c \u0625\u0646\u0643 \u0623\u0646\u062a \u0627\u0644\u0633\u0645\u064a\u0639 \u0644\u0623\u0642\u0648\u0627\u0644 \u0639\u0628\u0627\u062f\u0643\u060c \u0627\u0644\u0639\u0644\u064a\u0645 \u0628\u0623\u062d\u0648\u0627\u0644\u0647\u0645.","2:128":"\u0631\u0628\u0646\u0627 \u0648\u0627\u062c\u0639\u0644\u0646\u0627 \u062b\u0627\u0628\u062a\u064e\u064a\u0652\u0646 \u0639\u0644\u0649 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0645\u0646\u0642\u0627\u062f\u064e\u064a\u0652\u0646 \u0644\u0623\u062d\u0643\u0627\u0645\u0643\u060c \u0648\u0627\u062c\u0639\u0644 \u0645\u0646 \u0630\u0631\u064a\u062a\u0646\u0627 \u0623\u0645\u0629 \u0645\u0646\u0642\u0627\u062f\u0629 \u0644\u0643\u060c \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0646\u060c \u0648\u0628\u0635\u0651\u0650\u0631\u0652\u0646\u0627 \u0628\u0645\u0639\u0627\u0644\u0645 \u0639\u0628\u0627\u062f\u062a\u0646\u0627 \u0644\u0643\u060c \u0648\u062a\u062c\u0627\u0648\u0632 \u0639\u0646 \u0630\u0646\u0648\u0628\u0646\u0627. \u0625\u0646\u0643 \u0623\u0646\u062a \u0643\u062b\u064a\u0631 \u0627\u0644\u062a\u0648\u0628\u0629 \u0639\u0644\u0649 \u0639\u0628\u0627\u062f\u0643\u060c \u0648\u0627\u0633\u0639 \u0627\u0644\u0631\u062d\u0645\u0629 \u0628\u0647\u0645.","2:129":"\u0631\u0628\u0646\u0627 \u0648\u0627\u0628\u0639\u062b \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0623\u0645\u0629 \u0631\u0633\u0648\u0644\u0627 \u0645\u0646 \u0630\u0631\u064a\u0629 \u0625\u0633\u0645\u0627\u0639\u064a\u0644 \u064a\u062a\u0644\u0648 \u0639\u0644\u064a\u0647\u0645 \u0622\u064a\u0627\u062a\u0643 \u0648\u064a\u0639\u0644\u0645\u0647\u0645 \u0627\u0644\u0642\u0631\u0622\u0646 \u0648\u0627\u0644\u0633\u0646\u0629\u060c \u0648\u064a\u064f\u0637\u0647\u0631\u0647\u0645 \u0645\u0646 \u0627\u0644\u0634\u0631\u0643 \u0648\u0633\u0648\u0621 \u0627\u0644\u0623\u062e\u0644\u0627\u0642. \u0625\u0646\u0643 \u0623\u0646\u062a \u0627\u0644\u0639\u0632\u064a\u0632 \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u0645\u062a\u0646\u0639 \u0639\u0644\u064a\u0647 \u0634\u064a\u0621\u060c \u0627\u0644\u062d\u0643\u064a\u0645 \u0627\u0644\u0630\u064a \u064a\u0636\u0639 \u0627\u0644\u0623\u0634\u064a\u0627\u0621 \u0641\u064a \u0645\u0648\u0627\u0636\u0639\u0647\u0627.","2:130":"\u0648\u0644\u0627 \u0623\u062d\u062f \u064a\u064f\u0639\u0631\u0636 \u0639\u0646 \u062f\u064a\u0646 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 -\u0648\u0647\u0648 \u0627\u0644\u0625\u0633\u0644\u0627\u0645- \u0625\u0644\u0627 \u0633\u0641\u064a\u0647 \u062c\u0627\u0647\u0644\u060c \u0648\u0644\u0642\u062f \u0627\u062e\u062a\u0631\u0646\u0627 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0646\u0628\u064a\u0651\u064b\u0627 \u0648\u0631\u0633\u0648\u0644\u0627 \u0648\u0625\u0646\u0647 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u0644\u0645\u0646 \u0627\u0644\u0635\u0627\u0644\u062d\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0644\u0647\u0645 \u0623\u0639\u0644\u0649 \u0627\u0644\u062f\u0631\u062c\u0627\u062a.","2:131":"\u0648\u0633\u0628\u0628 \u0647\u0630\u0627 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631 \u0645\u0633\u0627\u0631\u0639\u062a\u0647 \u0625\u0644\u0649 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u062f\u0648\u0646 \u062a\u0631\u062f\u062f\u060c \u062d\u064a\u0646 \u0642\u0627\u0644 \u0644\u0647 \u0631\u0628\u0647: \u0623\u062e\u0644\u0635 \u0646\u0641\u0633\u0643 \u0644\u0644\u0647 \u0645\u0646\u0642\u0627\u062f\u064b\u0627 \u0644\u0647. \u0641\u0627\u0633\u062a\u062c\u0627\u0628 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0648\u0642\u0627\u0644: \u0623\u0633\u0644\u0645\u062a \u0644\u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064a\u0646 \u0625\u062e\u0644\u0627\u0635\u064b\u0627 \u0648\u062a\u0648\u062d\u064a\u062f\u064b\u0627 \u0648\u0645\u062d\u0628\u0629 \u0648\u0625\u0646\u0627\u0628\u0629.","2:132":"\u0648\u062d\u062b\u0651\u064e \u0625\u0628\u0631\u0627\u0647\u064a\u0645\u064f \u0648\u064a\u0639\u0642\u0648\u0628\u064f \u0623\u0628\u0646\u0627\u0621\u0647\u0645\u0627 \u0639\u0644\u0649 \u0627\u0644\u062b\u0628\u0627\u062a \u0639\u0644\u0649 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0642\u0627\u0626\u0644\u064e\u064a\u0652\u0646: \u064a\u0627 \u0623\u0628\u0646\u0627\u0621\u0646\u0627 \u0625\u0646 \u0627\u0644\u0644\u0647 \u0627\u062e\u062a\u0627\u0631 \u0644\u0643\u0645 \u0647\u0630\u0627 \u0627\u0644\u062f\u064a\u0646 -\u0648\u0647\u0648 \u062f\u064a\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645- \u0641\u0644\u0627 \u062a\u0641\u0627\u0631\u0642\u0648\u0647 \u0623\u064a\u0627\u0645 \u062d\u064a\u0627\u062a\u0643\u0645\u060c \u0648\u0644\u0627 \u064a\u0623\u062a\u0643\u0645 \u0627\u0644\u0645\u0648\u062a \u0625\u0644\u0627 \u0648\u0623\u0646\u062a\u0645 \u0639\u0644\u064a\u0647.","2:133":"\u0623\u0643\u0646\u062a\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u064a\u0647\u0648\u062f- \u062d\u0627\u0636\u0631\u064a\u0646 \u062d\u064a\u0646 \u062c\u0627\u0621 \u0627\u0644\u0645\u0648\u062a\u064f \u064a\u0639\u0642\u0648\u0628\u064e\u060c \u0625\u0630 \u062c\u0645\u0639 \u0623\u0628\u0646\u0627\u0621\u0647 \u0648\u0633\u0623\u0644\u0647\u0645 \u0645\u0627 \u062a\u0639\u0628\u062f\u0648\u0646 \u0645\u0646 \u0628\u0639\u062f \u0645\u0648\u062a\u064a\u061f \u0642\u0627\u0644\u0648\u0627: \u0646\u0639\u0628\u062f \u0625\u0644\u0647\u0643 \u0648\u0625\u0644\u0647 \u0622\u0628\u0627\u0626\u0643 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0648\u0625\u0633\u0645\u0627\u0639\u064a\u0644 \u0648\u0625\u0633\u062d\u0627\u0642 \u0625\u0644\u0647\u064b\u0627 \u0648\u0627\u062d\u062f\u064b\u0627\u060c \u0648\u0646\u062d\u0646 \u0644\u0647 \u0645\u0646\u0642\u0627\u062f\u0648\u0646 \u062e\u0627\u0636\u0639\u0648\u0646.","2:134":"\u062a\u0644\u0643 \u0623\u064f\u0645\u0651\u064e\u0629 \u0645\u0646 \u0623\u0633\u0644\u0627\u0641\u0643\u0645 \u0642\u062f \u0645\u0636\u064e\u062a\u0652\u060c \u0644\u0647\u0645 \u0623\u0639\u0645\u0627\u0644\u0647\u0645\u060c \u0648\u0644\u0643\u0645 \u0623\u0639\u0645\u064e\u0627\u0644\u0643\u0645\u060c \u0648\u0644\u0627 \u062a\u064f\u0633\u0652\u0623\u0644\u0648\u0646 \u0639\u0646 \u0623\u0639\u0645\u0627\u0644\u0647\u0645\u060c \u0648\u0647\u0645 \u0644\u0627 \u064a\u064f\u0633\u0652\u0623\u0644\u0648\u0646 \u0639\u0646 \u0623\u0639\u0645\u0627\u0644\u0643\u0645\u060c \u0648\u0643\u0644\u0651\u064c \u0633\u064a\u062c\u0627\u0632\u0649 \u0628\u0645\u0627 \u0641\u0639\u0644\u0647\u060c \u0644\u0627 \u064a\u0624\u0627\u062e\u0630 \u0623\u062d\u062f \u0628\u0630\u0646\u0628 \u0623\u062d\u062f\u060c \u0648\u0644\u0627 \u064a\u0646\u0641\u0639\u064f \u0623\u062d\u062f\u064b\u0627 \u0625\u0644\u0627 \u0625\u064a\u0645\u0627\u0646\u064f\u0647 \u0648\u062a\u0642\u0648\u0627\u0647.","2:135":"\u0648\u0642\u0627\u0644\u062a \u0627\u0644\u064a\u0647\u0648\u062f \u0644\u0623\u0645\u0651\u064e\u0629 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645: \u0627\u062f\u062e\u0644\u0648\u0627 \u0641\u064a \u062f\u064a\u0646 \u0627\u0644\u064a\u0647\u0648\u062f\u064a\u0629 \u062a\u062c\u062f\u0648\u0627 \u0627\u0644\u0647\u062f\u0627\u064a\u0629\u060c \u0648\u0642\u0627\u0644\u062a \u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0644\u0647\u0645 \u0645\u062b\u0644 \u0630\u0644\u0643. \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0628\u0644 \u0627\u0644\u0647\u062f\u0627\u064a\u0629 \u0623\u0646 \u0646\u062a\u0628\u0639- \u062c\u0645\u064a\u0639\u064b\u0627- \u0645\u0644\u0629 \u0625\u0628\u0631\u0627\u0647\u064a\u0645\u060c \u0627\u0644\u0630\u064a \u0645\u0627\u0644 \u0639\u0646 \u0643\u0644 \u062f\u064a\u0646 \u0628\u0627\u0637\u0644 \u0625\u0644\u0649 \u062f\u064a\u0646 \u0627\u0644\u062d\u0642\u060c \u0648\u0645\u0627 \u0643\u0627\u0646 \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0628\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649.","2:136":"\u0642\u0648\u0644\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0651\u064e\u0635\u0627\u0631\u0649: \u0635\u062f\u0651\u064e\u0642\u0646\u0627 \u0628\u0627\u0644\u0644\u0647 \u0627\u0644\u0648\u0627\u062d\u062f \u0627\u0644\u0645\u0639\u0628\u0648\u062f \u0628\u062d\u0642\u060c \u0648\u0628\u0645\u0627 \u0623\u0646\u0632\u0644 \u0625\u0644\u064a\u0646\u0627 \u0645\u0646 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0630\u064a \u0623\u0648\u062d\u0627\u0647 \u0627\u0644\u0644\u0647 \u0625\u0644\u0649 \u0646\u0628\u064a\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0645\u0627 \u0623\u0646\u0632\u0644 \u0645\u0646 \u0627\u0644\u0635\u062d\u0641 \u0625\u0644\u0649 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0648\u0627\u0628\u0646\u064a\u0647 \u0625\u0633\u0645\u0627\u0639\u064a\u0644 \u0648\u0625\u0633\u062d\u0627\u0642\u060c \u0648\u0625\u0644\u0649 \u064a\u0639\u0642\u0648\u0628 \u0648\u0627\u0644\u0623\u0633\u0628\u0627\u0637 -\u0648\u0647\u0645 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0645\u0650\u0646 \u0648\u0644\u062f \u064a\u0639\u0642\u0648\u0628 \u0627\u0644\u0630\u064a\u0646 \u0643\u0627\u0646\u0648\u0627 \u0641\u064a \u0642\u0628\u0627\u0626\u0644 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0627\u0644\u0627\u062b\u0646\u062a\u064a \u0639\u0634\u0631\u0629- \u0648\u0645\u0627 \u0623\u064f\u0639\u0637\u064a \u0645\u0648\u0633\u0649 \u0645\u0646 \u0627\u0644\u062a\u0648\u0631\u0627\u0629\u060c \u0648\u0639\u064a\u0633\u0649 \u0645\u0646 \u0627\u0644\u0625\u0646\u062c\u064a\u0644\u060c \u0648\u0645\u0627 \u0623\u064f\u0639\u0637\u064a \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u062c\u0645\u064a\u0639\u064b\u0627 \u0645\u0646 \u0648\u062d\u064a \u0631\u0628\u0647\u0645\u060c \u0644\u0627 \u0646\u0641\u0631\u0642 \u0628\u064a\u0646 \u0623\u062d\u062f \u0645\u0646\u0647\u0645 \u0641\u064a \u0627\u0644\u0625\u064a\u0645\u0627\u0646\u060c \u0648\u0646\u062d\u0646 \u062e\u0627\u0636\u0639\u0648\u0646 \u0644\u0644\u0647 \u0628\u0627\u0644\u0637\u0627\u0639\u0629 \u0648\u0627\u0644\u0639\u0628\u0627\u062f\u0629.","2:137":"\u0641\u0625\u0646\u0652 \u0622\u0645\u0646 \u0627\u0644\u0643\u0641\u0627\u0631 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0648\u063a\u064a\u0631\u0647\u0645 \u0628\u0645\u062b\u0644 \u0627\u0644\u0630\u064a \u0622\u0645\u0646\u062a\u0645 \u0628\u0647\u060c \u0645\u0645\u0627 \u062c\u0627\u0621 \u0628\u0647 \u0627\u0644\u0631\u0633\u0648\u0644\u060c \u0641\u0642\u062f \u0627\u0647\u062a\u062f\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u062d\u0642\u060c \u0648\u0625\u0646 \u0623\u0639\u0631\u0636\u0648\u0627 \u0641\u0625\u0646\u0645\u0627 \u0647\u0645 \u0641\u064a \u062e\u0644\u0627\u0641 \u0634\u062f\u064a\u062f\u060c \u0641\u0633\u064a\u0643\u0641\u064a\u0643 \u0627\u0644\u0644\u0647 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0634\u0631\u0651\u064e\u0647\u0645 \u0648\u064a\u0646\u0635\u0631\u0643 \u0639\u0644\u064a\u0647\u0645\u060c \u0648\u0647\u0648 \u0627\u0644\u0633\u0645\u064a\u0639 \u0644\u0623\u0642\u0648\u0627\u0644\u0643\u0645\u060c \u0627\u0644\u0639\u0644\u064a\u0645 \u0628\u0623\u062d\u0648\u0627\u0644\u0643\u0645.","2:138":"\u0627\u0644\u0632\u0645\u0648\u0627 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a \u0641\u0637\u0631\u0643\u0645 \u0639\u0644\u064a\u0647\u060c \u0641\u0644\u064a\u0633 \u0647\u0646\u0627\u0643 \u0623\u062d\u0633\u0646\u064f \u0645\u0650\u0646 \u0641\u0637\u0631\u0629 \u0627\u0644\u0644\u0647 \u0627\u0644\u062a\u064a \u0641\u0637\u0631 \u0627\u0644\u0646\u0627\u0633 \u0639\u0644\u064a\u0647\u0627\u060c \u0641\u0627\u0644\u0632\u0645\u0648\u0647\u0627 \u0648\u0642\u0648\u0644\u0648\u0627 \u0646\u062d\u0646 \u062e\u0627\u0636\u0639\u0648\u0646 \u0645\u0637\u064a\u0639\u0648\u0646 \u0644\u0631\u0628\u0646\u0627 \u0641\u064a \u0627\u062a\u0628\u0627\u0639\u0646\u0627 \u0645\u0644\u0651\u064e\u0629 \u0625\u0628\u0631\u0627\u0647\u064a\u0645.","2:139":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644 \u0644\u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628-: \u0623\u062a\u062c\u0627\u062f\u0644\u0648\u0646\u0646\u0627 \u0641\u064a \u062a\u0648\u062d\u064a\u062f \u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u0625\u062e\u0644\u0627\u0635 \u0644\u0647\u060c \u0648\u0647\u0648 \u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064a\u0646 \u062c\u0645\u064a\u0639\u064b\u0627\u060c \u0644\u0627 \u064a\u062e\u062a\u0635 \u0628\u0642\u0648\u0645 \u062f\u0648\u0646 \u0642\u0648\u0645\u060c \u0648\u0644\u0646\u0627 \u0623\u0639\u0645\u0627\u0644\u0646\u0627 \u0648\u0644\u0643\u0645 \u0623\u0639\u0645\u0627\u0644\u0643\u0645\u060c \u0648\u0646\u062d\u0646 \u0644\u0644\u0647 \u0645\u062e\u0644\u0635\u0648 \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u0648\u0627\u0644\u0637\u0651\u064e\u0627\u0639\u0629 \u0644\u0627 \u0646\u0634\u0631\u0643 \u0628\u0647 \u0634\u064a\u0626\u064b\u0627\u060c \u0648\u0644\u0627 \u0646\u0639\u0628\u062f \u0623\u062d\u062f\u064b\u0627 \u063a\u064a\u0631\u0647\u061f","2:140":"\u0628\u0644 \u0623\u062a\u0642\u0648\u0644\u0648\u0646 \u0645\u062c\u0627\u062f\u0644\u064a\u0646 \u0641\u064a \u0627\u0644\u0644\u0647: \u0625\u0646 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0648\u0625\u0633\u0645\u0627\u0639\u064a\u0644 \u0648\u0625\u0633\u062d\u0627\u0642 \u0648\u064a\u0639\u0642\u0648\u0628 \u0648\u0627\u0644\u0623\u0633\u0628\u0627\u0637 -\u0648\u0647\u0645 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u0643\u0627\u0646\u0648\u0627 \u0641\u064a \u0642\u0628\u0627\u0626\u0644 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0627\u0644\u0627\u062b\u0646\u062a\u064a \u0639\u0634\u0631\u0629 \u0645\u0646 \u0648\u0644\u062f \u064a\u0639\u0642\u0648\u0628- \u0643\u0627\u0646\u0648\u0627 \u0639\u0644\u0649 \u062f\u064a\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0623\u0648 \u0627\u0644\u0646\u0635\u0627\u0631\u0649\u061f \u0648\u0647\u0630\u0627 \u0643\u0630\u0628; \u0641\u0642\u062f \u0628\u064f\u0639\u0650\u062b\u0648\u0627 \u0648\u0645\u0627\u062a\u0648\u0627 \u0642\u0628\u0644 \u0646\u0632\u0648\u0644 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644. \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0623\u0623\u0646\u062a\u0645 \u0623\u0639\u0644\u0645 \u0628\u062f\u064a\u0646\u0647\u0645 \u0623\u0645 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u061f \u0648\u0642\u062f \u0623\u062e\u0628\u0631 \u0641\u064a \u0627\u0644\u0642\u0631\u0622\u0646 \u0628\u0623\u0646\u0647\u0645 \u0643\u0627\u0646\u0648\u0627 \u062d\u0646\u0641\u0627\u0621 \u0645\u0633\u0644\u0645\u064a\u0646\u060c \u0648\u0644\u0627 \u0623\u062d\u062f \u0623\u0638\u0644\u0645 \u0645\u0646\u0643\u0645 \u062d\u064a\u0646 \u062a\u062e\u0641\u0648\u0646 \u0634\u0647\u0627\u062f\u0629 \u062b\u0627\u0628\u062a\u0629 \u0639\u0646\u062f\u0643\u0645 \u0645\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u062a\u062f\u0651\u064e\u0639\u0648\u0646 \u062e\u0644\u0627\u0641\u0647\u0627 \u0627\u0641\u062a\u0631\u0627\u0621 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647. \u0648\u0645\u0627 \u0627\u0644\u0644\u0647 \u0628\u063a\u0627\u0641\u0644 \u0639\u0646 \u0634\u064a\u0621 \u0645\u0646 \u0623\u0639\u0645\u0627\u0644\u0643\u0645\u060c \u0628\u0644 \u0647\u0648 \u0645\u064f\u062d\u0652\u0635\u064d \u0644\u0647\u0627 \u0648\u0645\u062c\u0627\u0632\u064a\u0643\u0645 \u0639\u0644\u064a\u0647\u0627.","2:141":"\u062a\u0644\u0643 \u0623\u064f\u0645\u0651\u064e\u0629 \u0645\u0646 \u0623\u0633\u0644\u0627\u0641\u0643\u0645 \u0642\u062f \u0645\u0636\u064e\u062a\u0652\u060c \u0644\u0647\u0645 \u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0648\u0644\u0643\u0645 \u0623\u0639\u0645\u0627\u0644\u0643\u0645\u060c \u0648\u0644\u0627 \u062a\u064f\u0633\u0652\u0623\u0644\u0648\u0646 \u0639\u0646 \u0623\u0639\u0645\u0627\u0644\u0647\u0645\u060c \u0648\u0647\u0645 \u0644\u0627 \u064a\u064f\u0633\u0652\u0623\u0644\u0648\u0646 \u0639\u0646 \u0623\u0639\u0645\u0627\u0644\u0643\u0645. \u0648\u0641\u064a \u0627\u0644\u0622\u064a\u0629 \u0642\u0637\u0639 \u0644\u0644\u062a\u0639\u0644\u0642 \u0628\u0627\u0644\u0645\u062e\u0644\u0648\u0642\u064a\u0646\u060c \u0648\u0639\u062f\u0645 \u0627\u0644\u0627\u063a\u062a\u0631\u0627\u0631 \u0628\u0627\u0644\u0627\u0646\u062a\u0633\u0627\u0628 \u0625\u0644\u064a\u0647\u0645\u060c \u0648\u0623\u0646 \u0627\u0644\u0639\u0628\u0631\u0629 \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0639\u0628\u0627\u062f\u062a\u0647 \u0648\u062d\u062f\u0647\u060c \u0648\u0627\u062a\u0628\u0627\u0639 \u0631\u0633\u0644\u0647\u060c \u0648\u0623\u0646 \u0645\u0646 \u0643\u0641\u0631 \u0628\u0631\u0633\u0648\u0644 \u0645\u0646\u0647\u0645 \u0641\u0642\u062f \u0643\u0641\u0631 \u0628\u0633\u0627\u0626\u0631 \u0627\u0644\u0631\u0633\u0644.","2:142":"\u0633\u064a\u0642\u0648\u0644 \u0627\u0644\u062c\u0647\u0627\u0644 \u0648\u0636\u0639\u0627\u0641 \u0627\u0644\u0639\u0642\u0648\u0644 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0623\u0645\u062b\u0627\u0644\u0647\u0645\u060c \u0641\u064a \u0633\u062e\u0631\u064a\u0629 \u0648\u0627\u0639\u062a\u0631\u0627\u0636: \u0645\u0627 \u0627\u0644\u0630\u064a \u0635\u0631\u0641 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0639\u0646 \u0642\u0628\u0644\u062a\u0647\u0645 \u0627\u0644\u062a\u064a \u0643\u0627\u0646\u0648\u0627 \u064a\u064f\u0635\u064e\u0644\u0651\u064f\u0648\u0646 \u0625\u0644\u0649 \u062c\u0647\u062a\u0647\u0627 \u0623\u0648\u0644 \u0627\u0644\u0625\u0633\u0644\u0627\u0645; (\u0648\u0647\u064a \xab\u0628\u064a\u062a \u0627\u0644\u0645\u0642\u062f\u0633\xbb ) \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0627\u0644\u0645\u0634\u0631\u0642 \u0648\u0627\u0644\u0645\u063a\u0631\u0628 \u0648\u0645\u0627 \u0628\u064a\u0646\u0647\u0645\u0627 \u0645\u0644\u0643 \u0644\u0644\u0647\u060c \u0641\u0644\u064a\u0633\u062a \u062c\u0647\u0629 \u0645\u0646 \u0627\u0644\u062c\u0647\u0627\u062a \u062e\u0627\u0631\u062c\u0629 \u0639\u0646 \u0645\u0644\u0643\u0647\u060c \u064a\u0647\u062f\u064a \u0645\u064e\u0646 \u064a\u0634\u0627\u0621 \u0645\u0646 \u0639\u0628\u0627\u062f\u0647 \u0625\u0644\u0649 \u0637\u0631\u064a\u0642 \u0627\u0644\u0647\u062f\u0627\u064a\u0629 \u0627\u0644\u0642\u0648\u064a\u0645. \u0648\u0641\u064a \u0647\u0630\u0627 \u0625\u0634\u0639\u0627\u0631 \u0628\u0623\u0646 \u0627\u0644\u0634\u0623\u0646 \u0643\u0644\u0647 \u0644\u0644\u0647 \u0641\u064a \u0627\u0645\u062a\u062b\u0627\u0644 \u0623\u0648\u0627\u0645\u0631\u0647\u060c \u0641\u062d\u064a\u062b\u0645\u0627 \u0648\u064e\u062c\u0651\u064e\u0647\u064e\u0646\u0627 \u062a\u064e\u0648\u064e\u062c\u0651\u064e\u0647\u0652\u0646\u0627.","2:143":"\u0648\u0643\u0645\u0627 \u0647\u062f\u064a\u0646\u0627\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646- \u0625\u0644\u0649 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0635\u062d\u064a\u062d \u0641\u064a \u0627\u0644\u062f\u064a\u0646\u060c \u062c\u0639\u0644\u0646\u0627\u0643\u0645 \u0623\u0645\u0629 \u062e\u064a\u0627\u0631\u064b\u0627 \u0639\u062f\u0648\u0644\u0627 \u0644\u062a\u0634\u0647\u062f\u0648\u0627 \u0639\u0644\u0649 \u0627\u0644\u0623\u0645\u0645 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u0623\u0646 \u0631\u0633\u0644\u0647\u0645 \u0628\u0644\u0651\u064e\u063a\u062a\u0647\u0645 \u0631\u0633\u0627\u0644\u0627\u062a \u0631\u0628\u0647\u0645\u060c \u0648\u064a\u0643\u0648\u0646 \u0627\u0644\u0631\u0633\u0648\u0644 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 -\u0643\u0630\u0644\u0643- \u0634\u0647\u064a\u062f\u064b\u0627 \u0639\u0644\u064a\u0643\u0645 \u0623\u0646\u0651\u064e\u0647 \u0628\u0644\u0651\u064e\u063a\u0643\u0645 \u0631\u0633\u0627\u0644\u0629 \u0631\u0628\u0647. \u0648\u0645\u0627 \u062c\u0639\u0644\u0646\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0642\u0628\u0644\u0629 \xab\u0628\u064a\u062a \u0627\u0644\u0645\u0642\u062f\u0633\xbb \u0627\u0644\u062a\u064a \u0643\u0646\u062a \u0639\u0644\u064a\u0647\u0627\u060c \u062b\u0645 \u0635\u0631\u0641\u0646\u0627\u0643 \u0639\u0646\u0647\u0627 \u0625\u0644\u0649 \u0627\u0644\u0643\u0639\u0628\u0629 \u0628\u0640 \xab\u0645\u0643\u0629\xbb \u060c \u0625\u0644\u0627 \u0644\u064a\u0638\u0647\u0631 \u0645\u0627 \u0639\u0644\u0645\u0646\u0627\u0647 \u0641\u064a \u0627\u0644\u0623\u0632\u0644\u061b \u0639\u0644\u0645\u0627 \u064a\u062a\u0639\u0644\u0642 \u0628\u0647 \u0627\u0644\u062b\u0648\u0627\u0628 \u0648\u0627\u0644\u0639\u0642\u0627\u0628 \u0644\u0646\u0645\u064a\u0632 \u0645\u064e\u0646 \u064a\u062a\u0628\u0639\u0643 \u0648\u064a\u0637\u064a\u0639\u0643 \u0648\u064a\u0633\u062a\u0642\u0628\u0644 \u0645\u0639\u0643 \u062d\u064a\u062b \u062a\u0648\u062c\u0647\u062a\u060c \u0648\u0645\u064e\u0646 \u0647\u0648 \u0636\u0639\u064a\u0641 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0641\u064a\u0646\u0642\u0644\u0628 \u0645\u0631\u062a\u062f\u064b\u0627 \u0639\u0646 \u062f\u064a\u0646\u0647 \u0644\u0634\u0643\u0647 \u0648\u0646\u0641\u0627\u0642\u0647. \u0648\u0625\u0646 \u0647\u0630\u0647 \u0627\u0644\u062d\u0627\u0644 \u0627\u0644\u062a\u064a \u0647\u064a \u062a\u062d\u0648\u0644 \u0627\u0644\u0645\u0633\u0644\u0645 \u0641\u064a \u0635\u0644\u0627\u062a\u0647 \u0645\u0646 \u0627\u0633\u062a\u0642\u0628\u0627\u0644 \u0628\u064a\u062a \u0627\u0644\u0645\u0642\u062f\u0633 \u0625\u0644\u0649 \u0627\u0633\u062a\u0642\u0628\u0627\u0644 \u0627\u0644\u0643\u0639\u0628\u0629 \u0644\u062b\u0642\u064a\u0644\u0629 \u0634\u0627\u0642\u0629 \u0625\u0644\u0627 \u0639\u0644\u0649 \u0627\u0644\u0630\u064a\u0646 \u0647\u062f\u0627\u0647\u0645 \u0627\u0644\u0644\u0647 \u0648\u0645\u0646\u0651 \u0639\u0644\u064a\u0647\u0645 \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0627\u0644\u062a\u0642\u0648\u0649 \u0648\u0645\u0627 \u0643\u0627\u0646 \u0627\u0644\u0644\u0647 \u0644\u064a\u0636\u064a\u0639 \u0625\u064a\u0645\u0627\u0646\u0643\u0645 \u0628\u0647 \u0648\u0627\u062a\u0628\u0627\u0639\u0643\u0645 \u0644\u0631\u0633\u0648\u0644\u0647\u060c \u0648\u064a\u0628\u0637\u0644 \u0635\u0644\u0627\u062a\u0643\u0645 \u0625\u0644\u0649 \u0627\u0644\u0642\u0628\u0644\u0629 \u0627\u0644\u0633\u0627\u0628\u0642\u0629. \u0625\u0646\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649 \u0628\u0627\u0644\u0646\u0627\u0633 \u0644\u0631\u0621\u0648\u0641 \u0631\u062d\u064a\u0645.","2:144":"\u0642\u062f \u0646\u0631\u0649 \u062a\u062d\u0648\u0651\u064f\u0644 \u0648\u062c\u0647\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0641\u064a \u062c\u0647\u0629 \u0627\u0644\u0633\u0645\u0627\u0621\u060c \u0645\u0631\u0629 \u0628\u0639\u062f \u0645\u0631\u0629; \u0627\u0646\u062a\u0638\u0627\u0631\u064b\u0627 \u0644\u0646\u0632\u0648\u0644 \u0627\u0644\u0648\u062d\u064a \u0625\u0644\u064a\u0643 \u0641\u064a \u0634\u0623\u0646 \u0627\u0644\u0642\u0628\u0644\u0629\u060c \u0641\u0644\u0646\u0635\u0631\u0641\u0646\u0643 \u0639\u0646 \xab\u0628\u064a\u062a \u0627\u0644\u0645\u0642\u062f\u0633\xbb \u0625\u0644\u0649 \u0642\u0628\u0644\u0629 \u062a\u062d\u0628\u0647\u0627 \u0648\u062a\u0631\u0636\u0627\u0647\u0627\u060c \u0648\u0647\u064a \u0648\u062c\u0647\u0629 \u0627\u0644\u0645\u0633\u062c\u062f \u0627\u0644\u062d\u0631\u0627\u0645 \u0628\u0640 \xab\u0645\u0643\u0629\xbb \u060c \u0641\u0648\u0644\u0651\u0650 \u0648\u062c\u0647\u0643 \u0625\u0644\u064a\u0647\u0627. \u0648\u0641\u064a \u0623\u064a \u0645\u0643\u0627\u0646 \u0643\u0646\u062a\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646- \u0648\u0623\u0631\u062f\u062a\u0645 \u0627\u0644\u0635\u0644\u0627\u0629 \u0641\u062a\u0648\u062c\u0647\u0648\u0627 \u0646\u062d\u0648 \u0627\u0644\u0645\u0633\u062c\u062f \u0627\u0644\u062d\u0631\u0627\u0645. \u0648\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u0623\u0639\u0637\u0627\u0647\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u0645 \u0627\u0644\u0643\u062a\u0627\u0628 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0644\u064e\u064a\u0639\u0644\u0645\u0648\u0646 \u0623\u0646 \u062a\u062d\u0648\u064a\u0644\u0643 \u0625\u0644\u0649 \u0627\u0644\u0643\u0639\u0628\u0629 \u0647\u0648 \u0627\u0644\u062d\u0642 \u0627\u0644\u062b\u0627\u0628\u062a \u0641\u064a \u0643\u062a\u0628\u0647\u0645. \u0648\u0645\u0627 \u0627\u0644\u0644\u0647 \u0628\u063a\u0627\u0641\u0644 \u0639\u0645\u0627 \u064a\u0639\u0645\u0644 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0639\u062a\u0631\u0636\u0648\u0646 \u0627\u0644\u0645\u0634\u0643\u0643\u0648\u0646\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a\u0647\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643.","2:145":"\u0648\u0644\u0626\u0646 \u062c\u0626\u062a\u064e -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0627\u0644\u0630\u064a\u0646 \u0623\u064f\u0639\u0637\u0648\u0627 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644 \u0628\u0643\u0644 \u062d\u062c\u0629 \u0648\u0628\u0631\u0647\u0627\u0646 \u0639\u0644\u0649 \u0623\u0646 \u062a\u0648\u062c\u0651\u064f\u0647\u0643 \u0625\u0644\u0649 \u0627\u0644\u0643\u0639\u0628\u0629 \u0641\u064a \u0627\u0644\u0635\u0644\u0627\u0629 \u0647\u0648 \u0627\u0644\u062d\u0642 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647\u060c \u0645\u0627 \u062a\u0628\u0639\u0648\u0627 \u0642\u0628\u0644\u062a\u0643 \u0639\u0646\u0627\u062f\u064b\u0627 \u0648\u0627\u0633\u062a\u0643\u0628\u0627\u0631\u064b\u0627\u060c \u0648\u0645\u0627 \u0623\u0646\u062a \u0628\u062a\u0627\u0628\u0639 \u0642\u0628\u0644\u062a\u0647\u0645 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649\u060c \u0648\u0645\u0627 \u0628\u0639\u0636\u0647\u0645 \u0628\u062a\u0627\u0628\u0639 \u0642\u0628\u0644\u0629 \u0628\u0639\u0636. \u0648\u0644\u0626\u0646 \u0627\u062a\u0628\u0639\u062a \u0623\u0647\u0648\u0627\u0621\u0647\u0645 \u0641\u064a \u0634\u0623\u0646 \u0627\u0644\u0642\u0628\u0644\u0629 \u0648\u063a\u064a\u0631\u0647\u0627 \u0628\u0639\u062f \u0645\u0627 \u062c\u0627\u0621\u0643 \u0645\u0646 \u0627\u0644\u0639\u0644\u0645 \u0628\u0623\u0646\u0643 \u0639\u0644\u0649 \u0627\u0644\u062d\u0642 \u0648\u0647\u0645 \u0639\u0644\u0649 \u0627\u0644\u0628\u0627\u0637\u0644\u060c \u0625\u0646\u0643 \u062d\u064a\u0646\u0626\u0630 \u0644\u0645\u0646 \u0627\u0644\u0638\u0627\u0644\u0645\u064a\u0646 \u0644\u0623\u0646\u0641\u0633\u0647\u0645. \u0648\u0647\u0630\u0627 \u062e\u0637\u0627\u0628 \u0644\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u0645\u0629 \u0648\u0647\u0648 \u062a\u0647\u062f\u064a\u062f \u0648\u0648\u0639\u064a\u062f \u0644\u0645\u0646 \u064a\u062a\u0628\u0639 \u0623\u0647\u0648\u0627\u0621 \u0627\u0644\u0645\u062e\u0627\u0644\u0641\u064a\u0646 \u0644\u0634\u0631\u064a\u0639\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645.","2:146":"\u0627\u0644\u0630\u064a\u0646 \u0623\u0639\u0637\u064a\u0646\u0627\u0647\u0645 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644 \u0645\u0646 \u0623\u062d\u0628\u0627\u0631 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0639\u0644\u0645\u0627\u0621 \u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u064a\u0639\u0631\u0641\u0648\u0646 \u0623\u0646\u0651\u064e \u0645\u062d\u0645\u062f\u064b\u0627 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0628\u0623\u0648\u0635\u0627\u0641\u0647 \u0627\u0644\u0645\u0630\u0643\u0648\u0631\u0629 \u0641\u064a \u0643\u062a\u0628\u0647\u0645\u060c \u0645\u062b\u0644 \u0645\u0639\u0631\u0641\u062a\u0647\u0645 \u0623\u0628\u0646\u0627\u0626\u0647\u0645. \u0648\u0625\u0646 \u0641\u0631\u064a\u0642\u064b\u0627 \u0645\u0646\u0647\u0645 \u0644\u064a\u0643\u062a\u0645\u0648\u0646 \u0627\u0644\u062d\u0642 \u0648\u0647\u0645 \u064a\u0639\u0644\u0645\u0648\u0646 \u0635\u0650\u062f\u0652\u0642\u0647\u060c \u0648\u062b\u0628\u0648\u062a \u0623\u0648\u0635\u0627\u0641\u0647.","2:147":"\u0627\u0644\u0630\u064a \u0623\u0646\u0632\u0644 \u0625\u0644\u064a\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0647\u0648 \u0627\u0644\u062d\u0642 \u0645\u0646 \u0631\u0628\u0643\u060c \u0641\u0644\u0627 \u062a\u0643\u0648\u0646\u0646 \u0645\u0646 \u0627\u0644\u0634\u0627\u0643\u064a\u0646 \u0641\u064a\u0647. \u0648\u0647\u0630\u0627 \u0648\u0625\u0646 \u0643\u0627\u0646 \u062e\u0637\u0627\u0628\u0627 \u0644\u0644\u0631\u0633\u0648\u0644 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0641\u0647\u0648 \u0645\u0648\u062c\u0647 \u0644\u0644\u0623\u0645\u0629.","2:148":"\u0648\u0644\u0643\u0644 \u0623\u0645\u0629 \u0645\u0646 \u0627\u0644\u0623\u0645\u0645 \u0642\u0628\u0644\u0629 \u064a\u062a\u0648\u062c\u0651\u064e\u0647 \u0625\u0644\u064a\u0647\u0627 \u0643\u0644 \u0648\u0627\u062d\u062f \u0645\u0646\u0647\u0627 \u0641\u064a \u0635\u0644\u0627\u062a\u0647\u060c \u0641\u0628\u0627\u062f\u0631\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0645\u062a\u0633\u0627\u0628\u0642\u064a\u0646 \u0625\u0644\u0649 \u0641\u0650\u0639\u0652\u0644 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0635\u0627\u0644\u062d\u0629 \u0627\u0644\u062a\u064a \u0634\u0631\u0639\u0647\u0627 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0641\u064a \u062f\u064a\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645. \u0648\u0633\u064a\u062c\u0645\u0639\u0643\u0645 \u0627\u0644\u0644\u0647 \u062c\u0645\u064a\u0639\u0627 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u0645\u0646 \u0623\u064a \u0645\u0648\u0636\u0639 \u0643\u0646\u062a\u0645 \u0641\u064a\u0647. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0643\u0644 \u0634\u064a\u0621 \u0642\u062f\u064a\u0631.","2:149":"\u0648\u0645\u0646 \u0623\u064a \u0645\u0643\u0627\u0646 \u062e\u064e\u0631\u064e\u062c\u0652\u062a\u064e -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0645\u0633\u0627\u0641\u0631\u064b\u0627\u060c \u0648\u0623\u0631\u062f\u062a \u0627\u0644\u0635\u0644\u0627\u0629\u060c \u0641\u0648\u062c\u0651\u0650\u0647 \u0648\u062c\u0647\u0643 \u0646\u062d\u0648 \u0627\u0644\u0645\u0633\u062c\u062f \u0627\u0644\u062d\u0631\u0627\u0645. \u0648\u0625\u0646\u0651\u064e \u062a\u0648\u062c\u0651\u064f\u0647\u0643 \u0625\u0644\u064a\u0647 \u0644\u0647\u0648 \u0627\u0644\u062d\u0642 \u0627\u0644\u062b\u0627\u0628\u062a \u0645\u0646 \u0631\u0628\u0643. \u0648\u0645\u0627 \u0627\u0644\u0644\u0647 \u0628\u063a\u0627\u0641\u0644 \u0639\u0645\u0627 \u062a\u0639\u0645\u0644\u0648\u0646\u0647\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a\u0643\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643.","2:150":"\u0648\u0645\u0646 \u0623\u0649 \u0645\u0643\u0627\u0646 \u062e\u0631\u062c\u062a -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0641\u062a\u0648\u062c\u0651\u064e\u0647 \u0625\u0644\u0649 \u0627\u0644\u0645\u0633\u062c\u062f \u0627\u0644\u062d\u0631\u0627\u0645\u060c \u0648\u062d\u064a\u062b\u0645\u0627 \u0643\u0646\u062a\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646-\u060c \u0628\u0623\u064a \u0642\u064f\u0637\u0652\u0631\u064d \u0645\u0646 \u0623\u0642\u0637\u0627\u0631 \u0627\u0644\u0623\u0631\u0636 \u0641\u0648\u0644\u0651\u064f\u0648\u0627 \u0648\u062c\u0648\u0647\u0643\u0645 \u0646\u062d\u0648 \u0627\u0644\u0645\u0633\u062c\u062f \u0627\u0644\u062d\u0631\u0627\u0645; \u0644\u0643\u064a \u0644\u0627 \u064a\u0643\u0648\u0646 \u0644\u0644\u0646\u0627\u0633 \u0627\u0644\u0645\u062e\u0627\u0644\u0641\u064a\u0646 \u0644\u0643\u0645 \u0627\u062d\u062a\u062c\u0627\u062c \u0639\u0644\u064a\u0643\u0645 \u0628\u0627\u0644\u0645\u062e\u0627\u0635\u0645\u0629 \u0648\u0627\u0644\u0645\u062c\u0627\u062f\u0644\u0629\u060c \u0628\u0639\u062f \u0647\u0630\u0627 \u0627\u0644\u062a\u0648\u062c\u0647 \u0625\u0644\u064a\u0647\u060c \u0625\u0644\u0627 \u0623\u0647\u0644 \u0627\u0644\u0638\u0644\u0645 \u0648\u0627\u0644\u0639\u0646\u0627\u062f \u0645\u0646\u0647\u0645\u060c \u0641\u0633\u064a\u0638\u0644\u0651\u064f\u0648\u0646 \u0639\u0644\u0649 \u062c\u062f\u0627\u0644\u0647\u0645\u060c \u0641\u0644\u0627 \u062a\u062e\u0627\u0641\u0648\u0647\u0645 \u0648\u062e\u0627\u0641\u0648\u0646\u064a \u0628\u0627\u0645\u062a\u062b\u0627\u0644 \u0623\u0645\u0631\u064a\u060c \u0648\u0627\u062c\u062a\u0646\u0627\u0628 \u0646\u0647\u064a\u064a; \u0648\u0644\u0643\u064a \u0623\u062a\u0645 \u0646\u0639\u0645\u062a\u064a \u0639\u0644\u064a\u0643\u0645 \u0628\u0627\u062e\u062a\u064a\u0627\u0631 \u0623\u0643\u0645\u0644 \u0627\u0644\u0634\u0631\u0627\u0626\u0639 \u0644\u0643\u0645\u060c \u0648\u0644\u0639\u0644\u0643\u0645 \u062a\u0647\u062a\u062f\u0648\u0646 \u0625\u0644\u0649 \u0627\u0644\u062d\u0642 \u0648\u0627\u0644\u0635\u0648\u0627\u0628.","2:151":"\u0643\u0645\u0627 \u0623\u0646\u0639\u0645\u0646\u0627 \u0639\u0644\u064a\u0643\u0645 \u0628\u0627\u0633\u062a\u0642\u0628\u0627\u0644 \u0627\u0644\u0643\u0639\u0628\u0629 \u0623\u0631\u0633\u0644\u0646\u0627 \u0641\u064a\u0643\u0645 \u0631\u0633\u0648\u0644\u0627 \u0645\u0646\u0643\u0645 \u064a\u062a\u0644\u0648 \u0639\u0644\u064a\u0643\u0645 \u0627\u0644\u0622\u064a\u0627\u062a \u0627\u0644\u0645\u0628\u064a\u0646\u0629 \u0644\u0644\u062d\u0642 \u0645\u0646 \u0627\u0644\u0628\u0627\u0637\u0644\u060c \u0648\u064a\u0637\u0647\u0631\u0643\u0645 \u0645\u0646 \u062f\u0646\u0633 \u0627\u0644\u0634\u0631\u0643 \u0648\u0633\u0648\u0621 \u0627\u0644\u0623\u062e\u0644\u0627\u0642\u060c \u0648\u064a\u0639\u0644\u0645\u0643\u0645 \u0627\u0644\u0643\u062a\u0627\u0628 \u0648\u0627\u0644\u0633\u0646\u0629 \u0648\u0623\u062d\u0643\u0627\u0645 \u0627\u0644\u0634\u0631\u064a\u0639\u0629\u060c \u0648\u064a\u0639\u0644\u0645\u0643\u0645 \u0645\u0646 \u0623\u062e\u0628\u0627\u0631 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621\u060c \u0648\u0642\u0635\u0635 \u0627\u0644\u0623\u0645\u0645 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0645\u0627 \u0643\u0646\u062a\u0645 \u062a\u062c\u0647\u0644\u0648\u0646\u0647.","2:152":"\u0623\u0645\u0631 \u062a\u0639\u0627\u0644\u0649 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0628\u0630\u0643\u0631\u0647\u060c \u0648\u0648\u0639\u062f \u0639\u0644\u064a\u0647 \u0623\u0641\u0636\u0644 \u0627\u0644\u062c\u0632\u0627\u0621\u060c \u0648\u0647\u0648 \u0627\u0644\u062b\u0646\u0627\u0621 \u0641\u064a \u0627\u0644\u0645\u0644\u0623 \u0627\u0644\u0623\u0639\u0644\u0649 \u0639\u0644\u0649 \u0645\u064e\u0646\u0652 \u0630\u0643\u0631\u0647\u060c \u0648\u062e\u0635\u0648\u0646\u064a -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0628\u0627\u0644\u0634\u0643\u0631 \u0642\u0648\u0644\u0627 \u0648\u0639\u0645\u0644\u0627 \u0648\u0644\u0627 \u062a\u062c\u062d\u062f\u0648\u0627 \u0646\u0639\u0645\u064a \u0639\u0644\u064a\u0643\u0645.","2:153":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0627\u0637\u0644\u0628\u0648\u0627 \u0627\u0644\u0639\u0648\u0646 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0641\u064a \u0643\u0644 \u0623\u0645\u0648\u0631\u0643\u0645: \u0628\u0627\u0644\u0635\u0628\u0631 \u0639\u0644\u0649 \u0627\u0644\u0646\u0648\u0627\u0626\u0628 \u0648\u0627\u0644\u0645\u0635\u0627\u0626\u0628\u060c \u0648\u0628\u0627\u0644\u0635\u0628\u0631 \u0639\u0644\u0649 \u062a\u0631\u0643 \u0627\u0644\u0645\u0639\u0627\u0635\u064a \u0648\u0627\u0644\u0630\u0646\u0648\u0628\u060c \u0648\u0627\u0644\u0635\u0628\u0631 \u0639\u0644\u0649 \u0627\u0644\u0637\u0627\u0639\u0627\u062a \u0648\u0627\u0644\u0642\u0631\u0628\u0627\u062a\u060c \u0648\u0628\u0627\u0644\u0635\u0644\u0627\u0629 \u0627\u0644\u062a\u064a \u062a\u0637\u0645\u0626\u0646 \u0628\u0647\u0627 \u0627\u0644\u0646\u0641\u0633\u060c \u0648\u062a\u0646\u0647\u0649 \u0639\u0646 \u0627\u0644\u0641\u062d\u0634\u0627\u0621 \u0648\u0627\u0644\u0645\u0646\u0643\u0631. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0645\u0639 \u0627\u0644\u0635\u0627\u0628\u0631\u064a\u0646 \u0628\u0639\u0648\u0646\u0647 \u0648\u062a\u0648\u0641\u064a\u0642\u0647 \u0648\u062a\u0633\u062f\u064a\u062f\u0647. \u0648\u0641\u064a \u0627\u0644\u0622\u064a\u0629: \u0625\u062b\u0628\u0627\u062a \u0645\u0639\u064a\u0651\u064e\u0629 \u0627\u0644\u0644\u0647 \u0627\u0644\u062e\u0627\u0635\u0629 \u0628\u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0627\u0644\u0645\u0642\u062a\u0636\u064a\u0629 \u0644\u0645\u0627 \u0633\u0644\u0641 \u0630\u0643\u0631\u0647; \u0623\u0645\u0627 \u0627\u0644\u0645\u0639\u064a\u0629 \u0627\u0644\u0639\u0627\u0645\u0629\u060c \u0627\u0644\u0645\u0642\u062a\u0636\u064a\u0629 \u0644\u0644\u0639\u0644\u0645 \u0648\u0627\u0644\u0625\u062d\u0627\u0637\u0629 \u0641\u0647\u064a \u0644\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u0644\u0642.","2:154":"\u0648\u0644\u0627 \u062a\u0642\u0648\u0644\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0641\u064a\u0645\u0646 \u064a\u064f\u0642\u062a\u0644\u0648\u0646 \u0645\u062c\u0627\u0647\u062f\u064a\u0646 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647: \u0647\u0645 \u0623\u0645\u0648\u0627\u062a\u060c \u0628\u0644 \u0647\u0645 \u0623\u062d\u064a\u0627\u0621 \u062d\u064a\u0627\u0629 \u062e\u0627\u0635\u0629 \u0628\u0647\u0645 \u0641\u064a \u0642\u0628\u0648\u0631\u0647\u0645\u060c \u0644\u0627 \u064a\u0639\u0644\u0645 \u0643\u064a\u0641\u064a\u062a\u0647\u0627 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647 -\u062a\u0639\u0627\u0644\u0649-\u060c \u0648\u0644\u0643\u0646\u0643\u0645 \u0644\u0627 \u062a\u064f\u062d\u0633\u0651\u064f\u0648\u0646 \u0628\u0647\u0627. \u0648\u0641\u064a \u0647\u0630\u0627 \u062f\u0644\u064a\u0644 \u0639\u0644\u0649 \u0646\u0639\u064a\u0645 \u0627\u0644\u0642\u0628\u0631.","2:155":"\u0648\u0644\u0646\u062e\u062a\u0628\u0631\u0646\u0643\u0645 \u0628\u0634\u064a\u0621 \u064a\u0633\u064a\u0631 \u0645\u0646 \u0627\u0644\u062e\u0648\u0641\u060c \u0648\u0645\u0646 \u0627\u0644\u062c\u0648\u0639\u060c \u0648\u0628\u0646\u0642\u0635 \u0645\u0646 \u0627\u0644\u0623\u0645\u0648\u0627\u0644 \u0628\u062a\u0639\u0633\u0631 \u0627\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u064a\u0647\u0627\u060c \u0623\u0648 \u0630\u0647\u0627\u0628\u0647\u0627\u060c \u0648\u0645\u0646 \u0627\u0644\u0623\u0646\u0641\u0633: \u0628\u0627\u0644\u0645\u0648\u062a \u0623\u0648 \u0627\u0644\u0634\u0647\u0627\u062f\u0629 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647\u060c \u0648\u0628\u0646\u0642\u0635 \u0645\u0646 \u062b\u0645\u0631\u0627\u062a \u0627\u0644\u0646\u062e\u064a\u0644 \u0648\u0627\u0644\u0623\u0639\u0646\u0627\u0628 \u0648\u0627\u0644\u062d\u0628\u0648\u0628\u060c \u0628\u0642\u0644\u0651\u064e\u0629 \u0646\u0627\u062a\u062c\u0647\u0627 \u0623\u0648 \u0641\u0633\u0627\u062f\u0647\u0627. \u0648\u0628\u0634\u0651\u0650\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0627\u0644\u0635\u0627\u0628\u0631\u064a\u0646 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0648\u0623\u0645\u062b\u0627\u0644\u0647 \u0628\u0645\u0627 \u064a\u0641\u0631\u062d\u0647\u0645 \u0648\u064a\u064e\u0633\u064f\u0631\u0651\u064f\u0647\u0645 \u0645\u0646 \u062d\u0633\u0646 \u0627\u0644\u0639\u0627\u0642\u0628\u0629 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629.","2:156":"\u0645\u0646 \u0635\u0641\u0629 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0635\u0627\u0628\u0631\u064a\u0646 \u0623\u0646\u0647\u0645 \u0625\u0630\u0627 \u0623\u0635\u0627\u0628\u0647\u0645 \u0634\u064a\u0621 \u064a\u0643\u0631\u0647\u0648\u0646\u0647 \u0642\u0627\u0644\u0648\u0627: \u0625\u0646\u0651\u064e\u0627 \u0639\u0628\u064a\u062f \u0645\u0645\u0644\u0648\u0643\u0648\u0646 \u0644\u0644\u0647\u060c \u0645\u062f\u0628\u0651\u064e\u0631\u0648\u0646 \u0628\u0623\u0645\u0631\u0647 \u0648\u062a\u0635\u0631\u064a\u0641\u0647\u060c \u064a\u0641\u0639\u0644 \u0628\u0646\u0627 \u0645\u0627 \u064a\u0634\u0627\u0621\u060c \u0648\u0625\u0646\u0627 \u0625\u0644\u064a\u0647 \u0631\u0627\u062c\u0639\u0648\u0646 \u0628\u0627\u0644\u0645\u0648\u062a\u060c \u062b\u0645 \u0628\u0627\u0644\u0628\u0639\u062b \u0644\u0644\u062d\u0633\u0627\u0628 \u0648\u0627\u0644\u062c\u0632\u0627\u0621.","2:157":"\u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0635\u0627\u0628\u0631\u0648\u0646 \u0644\u0647\u0645 \u062b\u0646\u0627\u0621 \u0645\u0646 \u0631\u0628\u0647\u0645 \u0648\u0631\u062d\u0645\u0629 \u0639\u0638\u064a\u0645\u0629 \u0645\u0646\u0647 \u0633\u0628\u062d\u0627\u0646\u0647\u060c \u0648\u0623\u0648\u0644\u0626\u0643 \u0647\u0645 \u0627\u0644\u0645\u0647\u062a\u062f\u0648\u0646 \u0625\u0644\u0649 \u0627\u0644\u0631\u0634\u0627\u062f.","2:158":"\u0625\u0646 \u0627\u0644\u0635\u0641\u0627 \u0648\u0627\u0644\u0645\u0631\u0648\u0629 -\u0648\u0647\u0645\u0627 \u062c\u0628\u0644\u0627\u0646 \u0635\u063a\u064a\u0631\u0627\u0646 \u0642\u0631\u0628 \u0627\u0644\u0643\u0639\u0628\u0629 \u0645\u0646 \u062c\u0647\u0629 \u0627\u0644\u0634\u0631\u0642- \u0645\u0646 \u0645\u0639\u0627\u0644\u0645 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647 \u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0627\u0644\u062a\u064a \u062a\u0639\u0628\u0651\u064e\u062f \u0627\u0644\u0644\u0647 \u0639\u0628\u0627\u062f\u0647 \u0628\u0627\u0644\u0633\u0639\u064a \u0628\u064a\u0646\u0647\u0645\u0627. \u0641\u0645\u064e\u0646 \u0642\u0635\u062f \u0627\u0644\u0643\u0639\u0628\u0629 \u062d\u0627\u062c\u0651\u064b\u0627 \u0623\u0648 \u0645\u0639\u062a\u0645\u0631\u064b\u0627\u060c \u0641\u0644\u0627 \u0625\u062b\u0645 \u0639\u0644\u064a\u0647 \u0648\u0644\u0627 \u062d\u0631\u062c \u0641\u064a \u0623\u0646 \u064a\u0633\u0639\u0649 \u0628\u064a\u0646\u0647\u0645\u0627\u060c \u0628\u0644 \u064a\u062c\u0628 \u0639\u0644\u064a\u0647 \u0630\u0644\u0643\u060c \u0648\u0645\u0646 \u0641\u0639\u0644 \u0627\u0644\u0637\u0627\u0639\u0627\u062a \u0637\u0648\u0627\u0639\u064a\u0629 \u0645\u0646 \u0646\u0641\u0633\u0647 \u0645\u062e\u0644\u0635\u064b\u0627 \u0628\u0647\u0627 \u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0634\u0627\u0643\u0631 \u064a\u062b\u064a\u0628 \u0639\u0644\u0649 \u0627\u0644\u0642\u0644\u064a\u0644 \u0628\u0627\u0644\u0643\u062b\u064a\u0631\u060c \u0639\u0644\u064a\u0645 \u0628\u0623\u0639\u0645\u0627\u0644 \u0639\u0628\u0627\u062f\u0647 \u0641\u0644\u0627 \u064a\u0636\u064a\u0639\u0647\u0627\u060c \u0648\u0644\u0627 \u064a\u0628\u062e\u0633 \u0623\u062d\u062f\u064b\u0627 \u0645\u062b\u0642\u0627\u0644 \u0630\u0631\u0629.","2:159":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u064f\u062e\u0652\u0641\u0648\u0646 \u0645\u0627 \u0623\u0646\u0632\u0644\u0646\u0627 \u0645\u0646 \u0627\u0644\u0622\u064a\u0627\u062a \u0627\u0644\u0648\u0627\u0636\u062d\u0627\u062a \u0627\u0644\u062f\u0627\u0644\u0629 \u0639\u0644\u0649 \u0646\u0628\u0648\u0629 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u0645\u0627 \u062c\u0627\u0621 \u0628\u0647\u060c \u0648\u0647\u0645 \u0623\u062d\u0628\u0627\u0631 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0639\u0644\u0645\u0627\u0621 \u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0648\u063a\u064a\u0631\u0647\u0645 \u0645\u0645\u0646 \u064a\u0643\u062a\u0645 \u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0628\u0639\u062f \u0645\u0627 \u0623\u0638\u0647\u0631\u0646\u0627\u0647 \u0644\u0644\u0646\u0627\u0633 \u0641\u064a \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644\u060c \u0623\u0648\u0644\u0626\u0643 \u064a\u0637\u0631\u062f\u0647\u0645 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0631\u062d\u0645\u062a\u0647\u060c \u0648\u064a\u062f\u0639\u0648 \u0639\u0644\u064a\u0647\u0645 \u0628\u0627\u0644\u0644\u0639\u0646\u0629 \u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u0644\u064a\u0642\u0629.","2:160":"\u0625\u0644\u0627 \u0627\u0644\u0630\u064a\u0646 \u0631\u062c\u0639\u0648\u0627 \u0645\u0633\u062a\u063a\u0641\u0631\u064a\u0646 \u0627\u0644\u0644\u0647 \u0645\u0646 \u062e\u0637\u0627\u064a\u0627\u0647\u0645\u060c \u0648\u0623\u0635\u0644\u062d\u0648\u0627 \u0645\u0627 \u0623\u0641\u0633\u062f\u0648\u0647\u060c \u0648\u0628\u064e\u064a\u0651\u064e\u0646\u0648\u0627 \u0645\u0627 \u0643\u062a\u0645\u0648\u0647\u060c \u0641\u0623\u0648\u0644\u0626\u0643 \u0623\u0642\u0628\u0644 \u062a\u0648\u0628\u062a\u0647\u0645 \u0648\u0623\u062c\u0627\u0632\u064a\u0647\u0645 \u0628\u0627\u0644\u0645\u063a\u0641\u0631\u0629\u060c \u0648\u0623\u0646\u0627 \u0627\u0644\u062a\u0648\u0627\u0628 \u0639\u0644\u0649 \u0645\u0646 \u062a\u0627\u0628 \u0645\u0646 \u0639\u0628\u0627\u062f\u064a\u060c \u0627\u0644\u0631\u062d\u064a\u0645 \u0628\u0647\u0645; \u0625\u0630 \u0648\u0641\u0642\u062a\u064f\u0647\u0645 \u0644\u0644\u062a\u0648\u0628\u0629 \u0648\u0642\u0628\u0644\u062a\u0647\u0627 \u0645\u0646\u0647\u0645.","2:161":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u062c\u062d\u062f\u0648\u0627 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0643\u062a\u0645\u0648\u0627 \u0627\u0644\u062d\u0642\u060c \u0648\u0627\u0633\u062a\u0645\u0631\u0648\u0627 \u0639\u0644\u0649 \u0630\u0644\u0643 \u062d\u062a\u0649 \u0645\u0627\u062a\u0648\u0627\u060c \u0623\u0648\u0644\u0626\u0643 \u0639\u0644\u064a\u0647\u0645 \u0644\u0639\u0646\u0629 \u0627\u0644\u0644\u0647 \u0628\u0627\u0644\u0637\u0631\u062f \u0645\u0646 \u0631\u062d\u0645\u062a\u0647\u060c \u0648\u0639\u0644\u064a\u0647\u0645 \u0644\u0639\u0646\u0629 \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u0648\u0627\u0644\u0646\u0627\u0633 \u0623\u062c\u0645\u0639\u064a\u0646.","2:162":"\u062f\u0627\u0626\u0645\u064a\u0646 \u0641\u064a \u0627\u0644\u0644\u0639\u0646\u0629 \u0648\u0627\u0644\u0646\u0627\u0631\u060c \u0644\u0627 \u064a\u062e\u0641\u0641 \u0639\u0646\u0647\u0645 \u0627\u0644\u0639\u0630\u0627\u0628\u060c \u0648\u0644\u0627 \u0647\u0645 \u064a\u0645\u0647\u0644\u0648\u0646 \u0628\u0645\u0639\u0630\u0631\u0629 \u064a\u0639\u062a\u0630\u0631\u0648\u0646 \u0628\u0647\u0627.","2:163":"\u0648\u0625\u0644\u0647\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633- \u0625\u0644\u0647 \u0648\u0627\u062d\u062f \u0645\u062a\u0641\u0631\u062f \u0641\u064a \u0630\u0627\u062a\u0647 \u0648\u0623\u0633\u0645\u0627\u0626\u0647 \u0648\u0635\u0641\u0627\u062a\u0647 \u0648\u0623\u0641\u0639\u0627\u0644\u0647 \u0648\u0639\u0628\u0648\u062f\u064a\u0629 \u062e\u0644\u0642\u0647 \u0644\u0647\u060c \u0644\u0627 \u0645\u0639\u0628\u0648\u062f \u0628\u062d\u0642 \u0625\u0644\u0627 \u0647\u0648\u060c \u0627\u0644\u0631\u062d\u0645\u0646 \u0627\u0644\u0645\u062a\u0635\u0641 \u0628\u0627\u0644\u0631\u062d\u0645\u0629 \u0641\u064a \u0630\u0627\u062a\u0647 \u0648\u0623\u0641\u0639\u0627\u0644\u0647 \u0644\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u0644\u0642\u060c \u0627\u0644\u0631\u062d\u064a\u0645 \u0628\u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646.","2:164":"\u0625\u0646 \u0641\u064a \u062e\u0644\u0642 \u0627\u0644\u0633\u0645\u0627\u0648\u0627\u062a \u0628\u0627\u0631\u062a\u0641\u0627\u0639\u0647\u0627 \u0648\u0627\u062a\u0633\u0627\u0639\u0647\u0627\u060c \u0648\u0627\u0644\u0623\u0631\u0636 \u0628\u062c\u0628\u0627\u0644\u0647\u0627 \u0648\u0633\u0647\u0648\u0644\u0647\u0627 \u0648\u0628\u062d\u0627\u0631\u0647\u0627\u060c \u0648\u0641\u064a \u0627\u062e\u062a\u0644\u0627\u0641 \u0627\u0644\u0644\u064a\u0644 \u0648\u0627\u0644\u0646\u0647\u0627\u0631 \u0645\u0646 \u0627\u0644\u0637\u0648\u0644 \u0648\u0627\u0644\u0642\u0635\u0631\u060c \u0648\u0627\u0644\u0638\u0644\u0645\u0629 \u0648\u0627\u0644\u0646\u0648\u0631\u060c \u0648\u062a\u0639\u0627\u0642\u0628\u0647\u0645\u0627 \u0628\u0623\u0646 \u064a\u062e\u0644\u0641 \u0643\u0644 \u0645\u0646\u0647\u0645\u0627 \u0627\u0644\u0622\u062e\u0631\u060c \u0648\u0641\u064a \u0627\u0644\u0633\u0641\u0646 \u0627\u0644\u062c\u0627\u0631\u064a\u0629 \u0641\u064a \u0627\u0644\u0628\u062d\u0627\u0631\u060c \u0627\u0644\u062a\u064a \u062a\u062d\u0645\u0644 \u0645\u0627 \u064a\u0646\u0641\u0639 \u0627\u0644\u0646\u0627\u0633\u060c \u0648\u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u0633\u0645\u0627\u0621 \u0645\u0646 \u0645\u0627\u0621 \u0627\u0644\u0645\u0637\u0631\u060c \u0641\u0623\u062d\u064a\u0627 \u0628\u0647 \u0627\u0644\u0623\u0631\u0636\u060c \u0641\u0635\u0627\u0631\u062a \u0645\u062e\u0636\u0631\u0651\u064e\u0629 \u0630\u0627\u062a \u0628\u0647\u062c\u0629 \u0628\u0639\u062f \u0623\u0646 \u0643\u0627\u0646\u062a \u064a\u0627\u0628\u0633\u0629 \u0644\u0627 \u0646\u0628\u0627\u062a \u0641\u064a\u0647\u0627\u060c \u0648\u0645\u0627 \u0646\u0634\u0631\u0647 \u0627\u0644\u0644\u0647 \u0641\u064a\u0647\u0627 \u0645\u0646 \u0643\u0644 \u0645\u0627 \u062f\u0628\u0651\u064e \u0639\u0644\u0649 \u0648\u062c\u0647 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0645\u0627 \u0623\u0646\u0639\u0645 \u0628\u0647 \u0639\u0644\u064a\u0643\u0645 \u0645\u0646 \u062a\u0642\u0644\u064a\u0628 \u0627\u0644\u0631\u064a\u0627\u062d \u0648\u062a\u0648\u062c\u064a\u0647\u0647\u0627\u060c \u0648\u0627\u0644\u0633\u062d\u0627\u0628 \u0627\u0644\u0645\u064f\u0633\u064a\u0651\u064e\u0631 \u0628\u064a\u0646 \u0627\u0644\u0633\u0645\u0627\u0621 \u0648\u0627\u0644\u0623\u0631\u0636\u060c \u0625\u0646 \u0641\u064a \u0643\u0644 \u0627\u0644\u062f\u0644\u0627\u0626\u0644 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0644\u0622\u064a\u0627\u062a\u064d \u0639\u0644\u0649 \u0648\u062d\u062f\u0627\u0646\u064a\u0629 \u0627\u0644\u0644\u0647\u060c \u0648\u062c\u0644\u064a\u0644 \u0646\u0639\u0645\u0647\u060c \u0644\u0642\u0648\u0645 \u064a\u0639\u0642\u0644\u0648\u0646 \u0645\u0648\u0627\u0636\u0639 \u0627\u0644\u062d\u062c\u062c\u060c \u0648\u064a\u0641\u0647\u0645\u0648\u0646 \u0623\u062f\u0644\u062a\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0639\u0644\u0649 \u0648\u062d\u062f\u0627\u0646\u064a\u062a\u0647\u060c \u0648\u0627\u0633\u062a\u062d\u0642\u0627\u0642\u0647 \u0648\u062d\u062f\u0647 \u0644\u0644\u0639\u0628\u0627\u062f\u0629.","2:165":"\u0648\u0645\u0639 \u0647\u0630\u0647 \u0627\u0644\u0628\u0631\u0627\u0647\u064a\u0646 \u0627\u0644\u0642\u0627\u0637\u0639\u0629 \u064a\u062a\u062e\u0630 \u0641\u0631\u064a\u0642 \u0645\u0646 \u0627\u0644\u0646\u0627\u0633 \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647 \u0623\u0635\u0646\u0627\u0645\u064b\u0627 \u0648\u0623\u0648\u062b\u0627\u0646\u064b\u0627 \u0648\u0623\u0648\u0644\u064a\u0627\u0621 \u064a\u062c\u0639\u0644\u0648\u0646\u0647\u0645 \u0646\u0638\u0631\u0627\u0621 \u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u064a\u0639\u0637\u0648\u0646\u0647\u0645 \u0645\u0646 \u0627\u0644\u0645\u062d\u0628\u0629 \u0648\u0627\u0644\u062a\u0639\u0638\u064a\u0645 \u0648\u0627\u0644\u0637\u0627\u0639\u0629\u060c \u0645\u0627 \u0644\u0627 \u064a\u0644\u064a\u0642 \u0625\u0644\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647. \u0648\u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0623\u0639\u0638\u0645 \u062d\u0628\u0627 \u0644\u0644\u0647 \u0645\u0646 \u062d\u0628 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0643\u0641\u0627\u0631 \u0644\u0644\u0647 \u0648\u0644\u0622\u0644\u0647\u062a\u0647\u0645; \u0644\u0623\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0623\u062e\u0644\u0635\u0648\u0627 \u0627\u0644\u0645\u062d\u0628\u0629 \u0643\u0644\u0647\u0627 \u0644\u0644\u0647\u060c \u0648\u0623\u0648\u0644\u0626\u0643 \u0623\u0634\u0631\u0643\u0648\u0627 \u0641\u064a \u0627\u0644\u0645\u062d\u0628\u0629. \u0648\u0644\u0648 \u064a\u0639\u0644\u0645 \u0627\u0644\u0630\u064a\u0646 \u0638\u0644\u0645\u0648\u0627 \u0623\u0646\u0641\u0633\u0647\u0645 \u0628\u0627\u0644\u0634\u0631\u0643 \u0641\u064a \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u062d\u064a\u0646 \u064a\u0634\u0627\u0647\u062f\u0648\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0623\u0646 \u0627\u0644\u0644\u0647 \u0647\u0648 \u0627\u0644\u0645\u062a\u0641\u0631\u062f \u0628\u0627\u0644\u0642\u0648\u0629 \u062c\u0645\u064a\u0639\u064b\u0627\u060c \u0648\u0623\u0646 \u0627\u0644\u0644\u0647 \u0634\u062f\u064a\u062f \u0627\u0644\u0639\u0630\u0627\u0628\u060c \u0644\u0645\u0627 \u0627\u062a\u062e\u0630\u0648\u0627 \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647 \u0622\u0644\u0647\u0629 \u064a\u0639\u0628\u062f\u0648\u0646\u0647\u0645 \u0645\u0646 \u062f\u0648\u0646\u0647\u060c \u0648\u064a\u062a\u0642\u0631\u0628\u0648\u0646 \u0628\u0647\u0645 \u0625\u0644\u064a\u0647.","2:166":"\u0639\u0646\u062f \u0645\u0639\u0627\u064a\u0646\u062a\u0647\u0645 \u0639\u0630\u0627\u0628 \u0627\u0644\u0622\u062e\u0631\u0629 \u064a\u062a\u0628\u0631\u0623 \u0627\u0644\u0631\u0624\u0633\u0627\u0621 \u0627\u0644\u0645\u062a\u0628\u0648\u0639\u0648\u0646 \u0645\u0645\u0646 \u0627\u062a\u0628\u0639\u0647\u0645 \u0639\u0644\u0649 \u0627\u0644\u0634\u0631\u0643\u060c \u0648\u062a\u0646\u0642\u0637\u0639 \u0628\u064a\u0646\u0647\u0645 \u0643\u0644 \u0627\u0644\u0635\u0644\u0627\u062a \u0627\u0644\u062a\u064a \u0627\u0631\u062a\u0628\u0637\u0648\u0627 \u0628\u0647\u0627 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627: \u0645\u0646 \u0627\u0644\u0642\u0631\u0627\u0628\u0629\u060c \u0648\u0627\u0644\u0627\u062a\u0651\u0650\u0628\u0627\u0639\u060c \u0648\u0627\u0644\u062f\u064a\u0646\u060c \u0648\u063a\u064a\u0631 \u0630\u0644\u0643.","2:167":"\u0648\u0642\u0627\u0644 \u0627\u0644\u062a\u0627\u0628\u0639\u0648\u0646: \u064a\u0627 \u0644\u064a\u062a \u0644\u0646\u0627 \u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0641\u0646\u0639\u0644\u0646 \u0628\u0631\u0627\u0621\u062a\u0646\u0627 \u0645\u0646 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0631\u0624\u0633\u0627\u0621\u060c \u0643\u0645\u0627 \u0623\u0639\u0644\u0646\u0648\u0627 \u0628\u0631\u0627\u0621\u062a\u0647\u0645 \u0645\u0650\u0646\u0651\u064e\u0627. \u0648\u0643\u0645\u0627 \u0623\u0631\u0627\u0647\u0645 \u0627\u0644\u0644\u0647 \u0634\u062f\u0629 \u0639\u0630\u0627\u0628\u0647 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u064a\u0631\u064a\u0647\u0645 \u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0627\u0644\u0628\u0627\u0637\u0644\u0629 \u0646\u062f\u0627\u0645\u0627\u062a \u0639\u0644\u064a\u0647\u0645\u060c \u0648\u0644\u064a\u0633\u0648\u0627 \u0628\u062e\u0627\u0631\u062c\u064a\u0646 \u0645\u0646 \u0627\u0644\u0646\u0627\u0631 \u0623\u0628\u062f\u064b\u0627.","2:168":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633 \u0643\u0644\u0648\u0627 \u0645\u0646 \u0631\u0632\u0642 \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a \u0623\u0628\u0627\u062d\u0647 \u0644\u0643\u0645 \u0641\u064a \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0647\u0648 \u0627\u0644\u0637\u0627\u0647\u0631 \u063a\u064a\u0631 \u0627\u0644\u0646\u062c\u0633\u060c \u0627\u0644\u0646\u0627\u0641\u0639 \u063a\u064a\u0631 \u0627\u0644\u0636\u0627\u0631\u060c \u0648\u0644\u0627 \u062a\u062a\u0628\u0639\u0648\u0627 \u0637\u0631\u0642 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0641\u064a \u0627\u0644\u062a\u062d\u0644\u064a\u0644 \u0648\u0627\u0644\u062a\u062d\u0631\u064a\u0645\u060c \u0648\u0627\u0644\u0628\u062f\u0639 \u0648\u0627\u0644\u0645\u0639\u0627\u0635\u064a. \u0625\u0646\u0647 \u0639\u062f\u0648 \u0644\u0643\u0645 \u0638\u0627\u0647\u0631 \u0627\u0644\u0639\u062f\u0627\u0648\u0629.","2:169":"\u0625\u0646\u0645\u0627 \u064a\u0623\u0645\u0631\u0643\u0645 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0628\u0643\u0644 \u0630\u0646\u0628 \u0642\u0628\u064a\u062d \u064a\u0633\u0648\u0621\u064f\u0643\u0645\u060c \u0648\u0628\u0643\u0644 \u0645\u0639\u0635\u064a\u0629 \u0628\u0627\u0644\u063a\u0629 \u0627\u0644\u0642\u0628\u062d\u060c \u0648\u0628\u0623\u0646 \u062a\u0641\u062a\u0631\u0648\u0627 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0627\u0644\u0643\u0630\u0628 \u0645\u0646 \u062a\u062d\u0631\u064a\u0645 \u0627\u0644\u062d\u0644\u0627\u0644 \u0648\u063a\u064a\u0631\u0647 \u0628\u062f\u0648\u0646 \u0639\u0644\u0645.","2:170":"\u0648\u0625\u0630\u0627 \u0642\u0627\u0644 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0646\u0627\u0635\u062d\u064a\u0646 \u0623\u0647\u0644 \u0627\u0644\u0636\u0644\u0627\u0644: \u0627\u062a\u0628\u0639\u0648\u0627 \u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u0642\u0631\u0622\u0646 \u0648\u0627\u0644\u0647\u062f\u0649\u060c \u0623\u0635\u0631\u0651\u064f\u0648\u0627 \u0639\u0644\u0649 \u062a\u0642\u0644\u064a\u062f \u0623\u0633\u0644\u0627\u0641\u0647\u0645 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0642\u0627\u0626\u0644\u064a\u0646: \u0644\u0627 \u0646\u062a\u0628\u0639 \u062f\u064a\u0646\u0643\u0645\u060c \u0628\u0644 \u0646\u062a\u0628\u0639 \u0645\u0627 \u0648\u062c\u062f\u0646\u0627 \u0639\u0644\u064a\u0647 \u0622\u0628\u0627\u0621\u0646\u0627. \u0623\u064a\u062a\u0628\u0639\u0648\u0646 \u0622\u0628\u0627\u0621\u0647\u0645 \u0648\u0644\u0648 \u0643\u0627\u0646\u0648\u0627 \u0644\u0627 \u064a\u0639\u0642\u0644\u0648\u0646 \u0639\u0646 \u0627\u0644\u0644\u0647 \u0634\u064a\u0626\u064b\u0627\u060c \u0648\u0644\u0627 \u064a\u062f\u0631\u0643\u0648\u0646 \u0631\u0634\u062f\u064b\u0627\u061f","2:171":"\u0648\u0635\u0641\u0629 \u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0648\u062f\u064e\u0627\u0639\u0650\u064a\u0647\u0645 \u0625\u0644\u0649 \u0627\u0644\u0647\u062f\u0649 \u0648\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0643\u0635\u0641\u0629 \u0627\u0644\u0631\u0651\u064e\u0627\u0639\u064a \u0627\u0644\u0630\u064a \u064a\u0635\u064a\u062d \u0628\u0627\u0644\u0628\u0647\u0627\u0626\u0645 \u0648\u064a\u0632\u062c\u0631\u0647\u0627\u060c \u0648\u0647\u064a \u0644\u0627 \u062a\u0641\u0647\u0645 \u0645\u0639\u0627\u0646\u064a \u0643\u0644\u0627\u0645\u0647\u060c \u0648\u0625\u0646\u0645\u0627 \u062a\u0633\u0645\u0639 \u0627\u0644\u0646\u062f\u0627\u0621 \u0648\u062f\u064e\u0648\u0650\u064a\u0651\u064e \u0627\u0644\u0635\u0648\u062a \u0641\u0642\u0637. \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0643\u0641\u0627\u0631 \u0635\u064f\u0645\u0651\u064c \u0633\u062f\u0651\u064f\u0648\u0627 \u0623\u0633\u0645\u0627\u0639\u0647\u0645 \u0639\u0646 \u0627\u0644\u062d\u0642\u060c \u0628\u064f\u0643\u0652\u0645 \u0623\u062e\u0631\u0633\u0648\u0627 \u0623\u0644\u0633\u0646\u062a\u0647\u0645 \u0639\u0646 \u0627\u0644\u0646\u0637\u0642 \u0628\u0647\u060c \u0639\u064f\u0645\u0652\u064a \u0644\u0627 \u062a\u0631\u0649 \u0623\u0639\u064a\u0646\u0647\u0645 \u0628\u0631\u0627\u0647\u064a\u0646\u0647 \u0627\u0644\u0628\u0627\u0647\u0631\u0629\u060c \u0641\u0647\u0645 \u0644\u0627 \u064a\u0639\u0645\u0644\u0648\u0646 \u0639\u0642\u0648\u0644\u0647\u0645 \u0641\u064a\u0645\u0627 \u064a\u0646\u0641\u0639\u0647\u0645.","2:172":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0643\u0644\u0648\u0627 \u0645\u0646 \u0627\u0644\u0623\u0637\u0639\u0645\u0629 \u0627\u0644\u0645\u0633\u062a\u0644\u064e\u0630\u0651\u064e\u0629 \u0627\u0644\u062d\u0644\u0627\u0644 \u0627\u0644\u062a\u064a \u0631\u0632\u0642\u0646\u0627\u0643\u0645\u060c \u0648\u0644\u0627 \u062a\u0643\u0648\u0646\u0648\u0627 \u0643\u0627\u0644\u0643\u0641\u0627\u0631 \u0627\u0644\u0630\u064a\u0646 \u064a\u062d\u0631\u0645\u0648\u0646 \u0627\u0644\u0637\u064a\u0628\u0627\u062a\u060c \u0648\u064a\u0633\u062a\u062d\u0650\u0644\u0651\u064f\u0648\u0646 \u0627\u0644\u062e\u0628\u0627\u0626\u062b\u060c \u0648\u0627\u0634\u0643\u0631\u0648\u0627 \u0644\u0644\u0647 \u0646\u0639\u0645\u0647 \u0627\u0644\u0639\u0638\u064a\u0645\u0629 \u0639\u0644\u064a\u0643\u0645 \u0628\u0642\u0644\u0648\u0628\u0643\u0645 \u0648\u0623\u0644\u0633\u0646\u062a\u0643\u0645 \u0648\u062c\u0648\u0627\u0631\u062d\u0643\u0645\u060c \u0625\u0646 \u0643\u0646\u062a\u0645 \u062d\u0642\u064b\u0627 \u0645\u0646\u0642\u0627\u062f\u064a\u0646 \u0644\u0623\u0645\u0631\u0647\u060c \u0633\u0627\u0645\u0639\u064a\u0646 \u0645\u0637\u064a\u0639\u064a\u0646 \u0644\u0647\u060c \u062a\u0639\u0628\u062f\u0648\u0646\u0647 \u0648\u062d\u062f\u0647 \u0644\u0627 \u0634\u0631\u064a\u0643 \u0644\u0647.","2:173":"\u0625\u0646\u0645\u0627 \u062d\u0631\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0645\u0627 \u064a\u0636\u0631\u0643\u0645 \u0643\u0627\u0644\u0645\u064a\u062a\u0629 \u0627\u0644\u062a\u064a \u0644\u0645 \u062a\u0630\u0628\u062d \u0628\u0637\u0631\u064a\u0642\u0629 \u0634\u0631\u0639\u064a\u0629\u060c \u0648\u0627\u0644\u062f\u0645 \u0627\u0644\u0645\u0633\u0641\u0648\u062d\u060c \u0648\u0644\u062d\u0645 \u0627\u0644\u062e\u0646\u0632\u064a\u0631\u060c \u0648\u0627\u0644\u0630\u0628\u0627\u0626\u062d \u0627\u0644\u062a\u064a \u0630\u0628\u062d\u062a \u0644\u063a\u064a\u0631 \u0627\u0644\u0644\u0647. \u0648\u0645\u0650\u0646\u0652 \u0641\u064e\u0636\u0652\u0644\u0650 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0648\u062a\u064a\u0633\u064a\u0631\u0647 \u0623\u0646\u0647 \u0623\u0628\u0627\u062d \u0644\u0643\u0645 \u0623\u0643\u0644 \u0647\u0630\u0647 \u0627\u0644\u0645\u062d\u0631\u0645\u0627\u062a \u0639\u0646\u062f \u0627\u0644\u0636\u0631\u0648\u0631\u0629. \u0641\u0645\u0646 \u0623\u0644\u062c\u0623\u062a\u0647 \u0627\u0644\u0636\u0631\u0648\u0631\u0629 \u0625\u0644\u0649 \u0623\u0643\u0644 \u0634\u064a\u0621 \u0645\u0646\u0647\u0627\u060c \u063a\u064a\u0631 \u0638\u0627\u0644\u0645 \u0641\u064a \u0623\u0643\u0644\u0647 \u0641\u0648\u0642 \u062d\u0627\u062c\u062a\u0647\u060c \u0648\u0644\u0627 \u0645\u062a\u062c\u0627\u0648\u0632 \u062d\u062f\u0648\u062f \u0627\u0644\u0644\u0647 \u0641\u064a\u0645\u0627 \u0623\u064f\u0628\u064a\u062d \u0644\u0647\u060c \u0641\u0644\u0627 \u0630\u0646\u0628 \u0639\u0644\u064a\u0647 \u0641\u064a \u0630\u0644\u0643. \u0625\u0646 \u0627\u0644\u0644\u0647 \u063a\u0641\u0648\u0631 \u0644\u0639\u0628\u0627\u062f\u0647\u060c \u0631\u062d\u064a\u0645 \u0628\u0647\u0645.","2:174":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u064f\u062e\u0652\u0641\u0648\u0646 \u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0641\u064a \u0643\u062a\u0628\u0647 \u0645\u0646 \u0635\u0641\u0629 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u063a\u064a\u0631 \u0630\u0644\u0643 \u0645\u0646 \u0627\u0644\u062d\u0642\u060c \u0648\u064a\u062d\u0631\u0635\u0648\u0646 \u0639\u0644\u0649 \u0623\u062e\u0630 \u0639\u0648\u0636 \u0642\u0644\u064a\u0644 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627 \u0645\u0642\u0627\u0628\u0644 \u0647\u0630\u0627 \u0627\u0644\u0625\u062e\u0641\u0627\u0621\u060c \u0647\u0624\u0644\u0627\u0621 \u0645\u0627 \u064a\u0623\u0643\u0644\u0648\u0646 \u0641\u064a \u0645\u0642\u0627\u0628\u0644\u0629 \u0643\u062a\u0645\u0627\u0646 \u0627\u0644\u062d\u0642 \u0625\u0644\u0627 \u0646\u0627\u0631 \u062c\u0647\u0646\u0645 \u062a\u062a\u0623\u062c\u062c \u0641\u064a \u0628\u0637\u0648\u0646\u0647\u0645\u060c \u0648\u0644\u0627 \u064a\u0643\u0644\u0645\u0647\u0645 \u0627\u0644\u0644\u0647 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u0644\u063a\u0636\u0628\u0647 \u0648\u0633\u062e\u0637\u0647 \u0639\u0644\u064a\u0647\u0645\u060c \u0648\u0644\u0627 \u064a\u0637\u0647\u0631\u0647\u0645 \u0645\u0646 \u062f\u0646\u0633 \u0630\u0646\u0648\u0628\u0647\u0645 \u0648\u0643\u0641\u0631\u0647\u0645\u060c \u0648\u0644\u0647\u0645 \u0639\u0630\u0627\u0628 \u0645\u0648\u062c\u0639.","2:175":"\u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0645\u062a\u0635\u0641\u0648\u0646 \u0628\u0647\u0630\u0647 \u0627\u0644\u0635\u0641\u0627\u062a \u0627\u0633\u062a\u0628\u062f\u0644\u0648\u0627 \u0627\u0644\u0636\u0644\u0627\u0644\u0629 \u0628\u0627\u0644\u0647\u062f\u0649 \u0648\u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647 \u0628\u0645\u063a\u0641\u0631\u062a\u0647\u060c \u0641\u0645\u0627 \u0623\u0634\u062f \u062c\u0631\u0627\u0621\u062a\u0647\u0645 \u0639\u0644\u0649 \u0627\u0644\u0646\u0627\u0631 \u0628\u0639\u0645\u0644\u0647\u0645 \u0623\u0639\u0645\u0627\u0644 \u0623\u0647\u0644 \u0627\u0644\u0646\u0627\u0631!! \u064a\u0639\u062c\u0628 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0625\u0642\u062f\u0627\u0645\u0647\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643\u060c \u0641\u0627\u0639\u062c\u0628\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633- \u0645\u0646 \u062c\u0631\u0627\u0621\u062a\u0647\u0645\u060c \u0648\u0645\u0646 \u0635\u0628\u0631\u0647\u0645 \u0639\u0644\u0649 \u0627\u0644\u0646\u0627\u0631 \u0648\u0645\u0643\u062b\u0647\u0645 \u0641\u064a\u0647\u0627. \u0648\u0647\u0630\u0627 \u0639\u0644\u0649 \u0648\u062c\u0647 \u0627\u0644\u0627\u0633\u062a\u0647\u0627\u0646\u0629 \u0628\u0647\u0645\u060c \u0648\u0627\u0644\u0627\u0633\u062a\u062e\u0641\u0627\u0641 \u0628\u0623\u0645\u0631\u0647\u0645.","2:176":"\u0630\u0644\u0643 \u0627\u0644\u0639\u0630\u0627\u0628 \u0627\u0644\u0630\u064a \u0627\u0633\u062a\u062d\u0642\u0648\u0647 \u0628\u0633\u0628\u0628 \u0623\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0646\u0632\u0651\u064e\u0644 \u0643\u062a\u0628\u0647 \u0639\u0644\u0649 \u0631\u0633\u0644\u0647 \u0645\u0634\u062a\u0645\u0644\u0629 \u0639\u0644\u0649 \u0627\u0644\u062d\u0642 \u0627\u0644\u0645\u0628\u064a\u0646\u060c \u0641\u0643\u0641\u0631\u0648\u0627 \u0628\u0647. \u0648\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u0627\u062e\u062a\u0644\u0641\u0648\u0627 \u0641\u064a \u0627\u0644\u0643\u062a\u0627\u0628 \u0641\u0622\u0645\u0646\u0648\u0627 \u0628\u0628\u0639\u0636\u0647 \u0648\u0643\u0641\u0631\u0648\u0627 \u0628\u0628\u0639\u0636\u0647\u060c \u0644\u0641\u064a \u0645\u0646\u0627\u0632\u0639\u0629 \u0648\u0645\u0641\u0627\u0631\u0642\u0629 \u0628\u0639\u064a\u062f\u0629 \u0639\u0646 \u0627\u0644\u0631\u0634\u062f \u0648\u0627\u0644\u0635\u0648\u0627\u0628.","2:177":"\u0644\u064a\u0633 \u0627\u0644\u062e\u064a\u0631 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 -\u062a\u0639\u0627\u0644\u0649- \u0641\u064a \u0627\u0644\u062a\u0648\u062c\u0647 \u0641\u064a \u0627\u0644\u0635\u0644\u0627\u0629 \u0625\u0644\u0649 \u062c\u0647\u0629 \u0627\u0644\u0645\u0634\u0631\u0642 \u0648\u0627\u0644\u0645\u063a\u0631\u0628 \u0625\u0646 \u0644\u0645 \u064a\u0643\u0646 \u0639\u0646 \u0623\u0645\u0631 \u0627\u0644\u0644\u0647 \u0648\u0634\u0631\u0639\u0647\u060c \u0648\u0625\u0646\u0645\u0627 \u0627\u0644\u062e\u064a\u0631 \u0643\u0644 \u0627\u0644\u062e\u064a\u0631 \u0647\u0648 \u0625\u064a\u0645\u0627\u0646 \u0645\u0646 \u0622\u0645\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0635\u062f\u0651\u064e\u0642 \u0628\u0647 \u0645\u0639\u0628\u0648\u062f\u064b\u0627 \u0648\u062d\u062f\u064e\u0647 \u0644\u0627 \u0634\u0631\u064a\u0643 \u0644\u0647\u060c \u0648\u0622\u0645\u0646 \u0628\u064a\u0648\u0645 \u0627\u0644\u0628\u0639\u062b \u0648\u0627\u0644\u062c\u0632\u0627\u0621\u060c \u0648\u0628\u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u062c\u0645\u064a\u0639\u064b\u0627\u060c \u0648\u0628\u0627\u0644\u0643\u062a\u0628 \u0627\u0644\u0645\u0646\u0632\u0644\u0629 \u0643\u0627\u0641\u0629\u060c \u0648\u0628\u062c\u0645\u064a\u0639 \u0627\u0644\u0646\u0628\u064a\u064a\u0646 \u0645\u0646 \u063a\u064a\u0631 \u062a\u0641\u0631\u064a\u0642\u060c \u0648\u0623\u0639\u0637\u0649 \u0627\u0644\u0645\u0627\u0644 \u062a\u0637\u0648\u0651\u064f\u0639\u064b\u0627 -\u0645\u0639 \u0634\u062f\u0629 \u062d\u0628\u0647- \u0630\u0648\u064a \u0627\u0644\u0642\u0631\u0628\u0649\u060c \u0648\u0627\u0644\u064a\u062a\u0627\u0645\u0649 \u0627\u0644\u0645\u062d\u062a\u0627\u062c\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0645\u0627\u062a \u0622\u0628\u0627\u0624\u0647\u0645 \u0648\u0647\u0645 \u062f\u0648\u0646 \u0633\u0646 \u0627\u0644\u0628\u0644\u0648\u063a\u060c \u0648\u0627\u0644\u0645\u0633\u0627\u0643\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0623\u0631\u0647\u0642\u0647\u0645 \u0627\u0644\u0641\u0642\u0631\u060c \u0648\u0627\u0644\u0645\u0633\u0627\u0641\u0631\u064a\u0646 \u0627\u0644\u0645\u062d\u062a\u0627\u062c\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0628\u064e\u0639\u064f\u062f\u0648\u0627 \u0639\u0646 \u0623\u0647\u0644\u0647\u0645 \u0648\u0645\u0627\u0644\u0647\u0645\u060c \u0648\u0627\u0644\u0633\u0627\u0626\u0644\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0627\u0636\u0637\u0631\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u0633\u0624\u0627\u0644 \u0644\u0634\u062f\u0629 \u062d\u0627\u062c\u062a\u0647\u0645\u060c \u0648\u0623\u0646\u0641\u0642 \u0641\u064a \u062a\u062d\u0631\u064a\u0631 \u0627\u0644\u0631\u0642\u064a\u0642 \u0648\u0627\u0644\u0623\u0633\u0631\u0649\u060c \u0648\u0623\u0642\u0627\u0645 \u0627\u0644\u0635\u0644\u0627\u0629\u060c \u0648\u0623\u062f\u0649 \u0627\u0644\u0632\u0643\u0627\u0629 \u0627\u0644\u0645\u0641\u0631\u0648\u0636\u0629\u060c \u0648\u0627\u0644\u0630\u064a\u0646 \u064a\u0648\u0641\u0648\u0646 \u0628\u0627\u0644\u0639\u0647\u0648\u062f\u060c \u0648\u0645\u0646 \u0635\u0628\u0631 \u0641\u064a \u062d\u0627\u0644 \u0641\u0642\u0631\u0647 \u0648\u0645\u0631\u0636\u0647\u060c \u0648\u0641\u064a \u0634\u062f\u0629 \u0627\u0644\u0642\u062a\u0627\u0644. \u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0645\u062a\u0635\u0641\u0648\u0646 \u0628\u0647\u0630\u0647 \u0627\u0644\u0635\u0641\u0627\u062a \u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0642\u0648\u0627 \u0641\u064a \u0625\u064a\u0645\u0627\u0646\u0647\u0645\u060c \u0648\u0623\u0648\u0644\u0626\u0643 \u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u0627\u062a\u0642\u064e\u0648\u0627 \u0639\u0642\u0627\u0628 \u0627\u0644\u0644\u0647 \u0641\u062a\u062c\u0646\u0628\u0648\u0627 \u0645\u0639\u0627\u0635\u064a\u0647.","2:178":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647 \u0641\u0631\u0636 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0623\u0646 \u062a\u0642\u062a\u0635\u0648\u0627 \u0645\u0646 \u0627\u0644\u0642\u0627\u062a\u0644 \u0639\u0645\u062f\u0627 \u0628\u0642\u062a\u0644\u0647\u060c \u0628\u0634\u0631\u0637 \u0627\u0644\u0645\u0633\u0627\u0648\u0627\u0629 \u0648\u0627\u0644\u0645\u0645\u0627\u062b\u0644\u0629: \u064a\u064f\u0642\u062a\u0644 \u0627\u0644\u062d\u0631 \u0628\u0645\u062b\u0644\u0647\u060c \u0648\u0627\u0644\u0639\u0628\u062f \u0628\u0645\u062b\u0644\u0647\u060c \u0648\u0627\u0644\u0623\u0646\u062b\u0649 \u0628\u0645\u062b\u0644\u0647\u0627. \u0641\u0645\u0646 \u0633\u0627\u0645\u062d\u0647 \u0648\u0644\u064a \u0627\u0644\u0645\u0642\u062a\u0648\u0644 \u0628\u0627\u0644\u0639\u0641\u0648 \u0639\u0646 \u0627\u0644\u0627\u0642\u062a\u0635\u0627\u0635 \u0645\u0646\u0647 \u0648\u0627\u0644\u0627\u0643\u062a\u0641\u0627\u0621 \u0628\u0623\u062e\u0630 \u0627\u0644\u062f\u064a\u0629 -\u0648\u0647\u064a \u0642\u062f\u0631 \u0645\u0627\u0644\u064a \u0645\u062d\u062f\u062f \u064a\u062f\u0641\u0639\u0647 \u0627\u0644\u062c\u0627\u0646\u064a \u0645\u0642\u0627\u0628\u0644 \u0627\u0644\u0639\u0641\u0648 \u0639\u0646\u0647- \u0641\u0644\u064a\u0644\u062a\u0632\u0645 \u0627\u0644\u0637\u0631\u0641\u0627\u0646 \u0628\u062d\u0633\u0646 \u0627\u0644\u062e\u0644\u0642\u060c \u0641\u064a\u0637\u0627\u0644\u0628 \u0627\u0644\u0648\u0644\u064a \u0628\u0627\u0644\u062f\u064a\u0629 \u0645\u0646 \u063a\u064a\u0631 \u0639\u0646\u0641\u060c \u0648\u064a\u062f\u0641\u0639 \u0627\u0644\u0642\u0627\u062a\u0644 \u0625\u0644\u064a\u0647 \u062d\u0642\u0647 \u0628\u0625\u062d\u0633\u0627\u0646\u060c \u0645\u0650\u0646 \u063a\u064a\u0631 \u062a\u0623\u062e\u064a\u0631 \u0648\u0644\u0627 \u0646\u0642\u0635. \u0630\u0644\u0643 \u0627\u0644\u0639\u0641\u0648 \u0645\u0639 \u0623\u062e\u0630 \u0627\u0644\u062f\u064a\u0629 \u062a\u062e\u0641\u064a\u0641 \u0645\u0646 \u0631\u0628\u0643\u0645 \u0648\u0631\u062d\u0645\u0629 \u0628\u0643\u0645; \u0644\u0645\u0627 \u0641\u064a\u0647 \u0645\u0646 \u0627\u0644\u062a\u0633\u0647\u064a\u0644 \u0648\u0627\u0644\u0627\u0646\u062a\u0641\u0627\u0639. \u0641\u0645\u064e\u0646 \u0642\u062a\u0644 \u0627\u0644\u0642\u0627\u062a\u0644 \u0628\u0639\u062f \u0627\u0644\u0639\u0641\u0648 \u0639\u0646\u0647 \u0648\u0623\u064e\u062e\u0652\u0630\u0650 \u0627\u0644\u062f\u064a\u0629 \u0641\u0644\u0647 \u0639\u0630\u0627\u0628 \u0623\u0644\u064a\u0645 \u0628\u0642\u062a\u0644\u0647 \u0642\u0635\u0627\u0635\u064b\u0627 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0623\u0648 \u0628\u0627\u0644\u0646\u0627\u0631 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629.","2:179":"\u0648\u0644\u0643\u0645 \u0641\u064a \u062a\u0634\u0631\u064a\u0639 \u0627\u0644\u0642\u0635\u0627\u0635 \u0648\u062a\u0646\u0641\u064a\u0630\u0647 \u062d\u064a\u0627\u0629 \u0622\u0645\u0646\u0629 -\u064a\u0627 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0639\u0642\u0648\u0644 \u0627\u0644\u0633\u0644\u064a\u0645\u0629-; \u0631\u062c\u0627\u0621 \u062a\u0642\u0648\u0649 \u0627\u0644\u0644\u0647 \u0648\u062e\u0634\u064a\u062a\u0647 \u0628\u0637\u0627\u0639\u062a\u0647 \u062f\u0627\u0626\u0645\u064b\u0627.","2:180":"\u0641\u0631\u0636 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0625\u0630\u0627 \u062d\u0636\u0631 \u0623\u062d\u062f\u0643\u0645 \u0639\u0644\u0627\u0645\u0627\u062a \u0627\u0644\u0645\u0648\u062a \u0648\u0645\u0642\u062f\u0645\u0627\u062a\u0647 -\u0625\u0646 \u062a\u0631\u0643 \u0645\u0627\u0644\u0627- \u0627\u0644\u0648\u0635\u064a\u0629 \u0628\u062c\u0632\u0621 \u0645\u0646 \u0645\u0627\u0644\u0647 \u0644\u0644\u0648\u0627\u0644\u062f\u064a\u0646 \u0648\u0627\u0644\u0623\u0642\u0631\u0628\u064a\u0646 \u0645\u0639 \u0645\u0631\u0627\u0639\u0627\u0629 \u0627\u0644\u0639\u062f\u0644; \u0641\u0644\u0627 \u064a\u062f\u0639 \u0627\u0644\u0641\u0642\u064a\u0631 \u0648\u064a\u0648\u0635\u064a \u0644\u0644\u063a\u0646\u064a\u060c \u0648\u0644\u0627 \u064a\u062a\u062c\u0627\u0648\u0632 \u0627\u0644\u062b\u0644\u062b\u060c \u0648\u0630\u0644\u0643 \u062d\u0642 \u062b\u0627\u0628\u062a \u064a\u0639\u0645\u0644 \u0628\u0647 \u0623\u0647\u0644 \u0627\u0644\u062a\u0642\u0648\u0649 \u0627\u0644\u0630\u064a\u0646 \u064a\u062e\u0627\u0641\u0648\u0646 \u0627\u0644\u0644\u0647. \u0648\u0643\u0627\u0646 \u0647\u0630\u0627 \u0642\u0628\u0644 \u0646\u0632\u0648\u0644 \u0622\u064a\u0627\u062a \u0627\u0644\u0645\u0648\u0627\u0631\u064a\u062b \u0627\u0644\u062a\u064a \u062d\u062f\u0651\u064e\u062f \u0627\u0644\u0644\u0647 \u0641\u064a\u0647\u0627 \u0646\u0635\u064a\u0628 \u0643\u0644 \u0648\u0627\u0631\u062b.","2:181":"\u0641\u0645\u064e\u0646 \u063a\u064e\u064a\u0651\u064e\u0631 \u0648\u0635\u064a\u0629 \u0627\u0644\u0645\u064a\u062a \u0628\u0639\u062f\u0645\u0627 \u0633\u0645\u0639\u0647\u0627 \u0645\u0646\u0647 \u0642\u0628\u0644 \u0645\u0648\u062a\u0647\u060c \u0641\u0625\u0646\u0645\u0627 \u0627\u0644\u0630\u0646\u0628 \u0639\u0644\u0649 \u0645\u064e\u0646 \u063a\u064a\u0651\u064e\u0631 \u0648\u0628\u062f\u0651\u064e\u0644. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0633\u0645\u064a\u0639 \u0644\u0648\u0635\u064a\u062a\u0643\u0645 \u0648\u0623\u0642\u0648\u0627\u0644\u0643\u0645\u060c \u0639\u0644\u064a\u0645 \u0628\u0645\u0627 \u062a\u062e\u0641\u064a\u0647 \u0635\u062f\u0648\u0631\u0643\u0645 \u0645\u0646 \u0627\u0644\u0645\u064a\u0644 \u0625\u0644\u0649 \u0627\u0644\u062d\u0642 \u0648\u0627\u0644\u0639\u062f\u0644 \u0623\u0648 \u0627\u0644\u062c\u0648\u0631 \u0648\u0627\u0644\u062d\u064a\u0641\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a\u0643\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643.","2:182":"\u0641\u0645\u064e\u0646 \u0639\u0644\u0645 \u0645\u0650\u0646 \u0645\u064f\u0648\u0635\u064d \u0645\u064a\u0644\u0627 \u0639\u0646 \u0627\u0644\u062d\u0642 \u0641\u064a \u0648\u0635\u064a\u062a\u0647 \u0639\u0644\u0649 \u0633\u0628\u064a\u0644 \u0627\u0644\u062e\u0637\u0623 \u0623\u0648 \u0627\u0644\u0639\u0645\u062f\u060c \u0641\u0646\u0635\u062d \u0627\u0644\u0645\u0648\u0635\u064a\u064e \u0648\u0642\u062a \u0627\u0644\u0648\u0635\u064a\u0629 \u0628\u0645\u0627 \u0647\u0648 \u0627\u0644\u0623\u0639\u062f\u0644\u060c \u0641\u0625\u0646 \u0644\u0645 \u064a\u062d\u0635\u0644 \u0644\u0647 \u0630\u0644\u0643 \u0641\u0623\u0635\u0644\u062d \u0628\u064a\u0646 \u0627\u0644\u0623\u0637\u0631\u0627\u0641 \u0628\u062a\u063a\u064a\u064a\u0631 \u0627\u0644\u0648\u0635\u064a\u0629; \u0644\u062a\u0648\u0627\u0641\u0642 \u0627\u0644\u0634\u0631\u064a\u0639\u0629\u060c \u0641\u0644\u0627 \u0630\u0646\u0628 \u0639\u0644\u064a\u0647 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0625\u0635\u0644\u0627\u062d. \u0625\u0646 \u0627\u0644\u0644\u0647 \u063a\u0641\u0648\u0631 \u0644\u0639\u0628\u0627\u062f\u0647\u060c \u0631\u062d\u064a\u0645 \u0628\u0647\u0645.","2:183":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647\u060c \u0641\u0631\u0636 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0627\u0644\u0635\u064a\u0627\u0645 \u0643\u0645\u0627 \u0641\u0631\u0636\u0647 \u0639\u0644\u0649 \u0627\u0644\u0623\u0645\u0645 \u0642\u0628\u0644\u0643\u0645; \u0644\u0639\u0644\u0643\u0645 \u062a\u062a\u0642\u0648\u0646 \u0631\u0628\u0643\u0645\u060c \u0641\u062a\u062c\u0639\u0644\u0648\u0646 \u0628\u064a\u0646\u0643\u0645 \u0648\u0628\u064a\u0646 \u0627\u0644\u0645\u0639\u0627\u0635\u064a \u0648\u0642\u0627\u064a\u0629 \u0628\u0637\u0627\u0639\u062a\u0647 \u0648\u0639\u0628\u0627\u062f\u062a\u0647 \u0648\u062d\u062f\u0647.","2:184":"\u0641\u0631\u0636 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0635\u064a\u0627\u0645 \u0623\u064a\u0627\u0645 \u0645\u0639\u0644\u0648\u0645\u0629 \u0627\u0644\u0639\u062f\u062f \u0648\u0647\u064a \u0623\u064a\u0627\u0645 \u0634\u0647\u0631 \u0631\u0645\u0636\u0627\u0646. \u0641\u0645\u0646 \u0643\u0627\u0646 \u0645\u0646\u0643\u0645 \u0645\u0631\u064a\u0636\u064b\u0627 \u064a\u0634\u0642 \u0639\u0644\u064a\u0647 \u0627\u0644\u0635\u0648\u0645\u060c \u0623\u0648 \u0645\u0633\u0627\u0641\u0631\u064b\u0627 \u0641\u0644\u0647 \u0623\u0646 \u064a\u0641\u0637\u0631\u060c \u0648\u0639\u0644\u064a\u0647 \u0635\u064a\u0627\u0645 \u0639\u062f\u062f \u0645\u0646 \u0623\u064a\u0627\u0645 \u0623\u064f\u062e\u064e\u0631 \u0628\u0642\u062f\u0631 \u0627\u0644\u062a\u064a \u0623\u0641\u0637\u0631 \u0641\u064a\u0647\u0627. \u0648\u0639\u0644\u0649 \u0627\u0644\u0630\u064a\u0646 \u064a\u062a\u0643\u0644\u0641\u0648\u0646 \u0627\u0644\u0635\u064a\u0627\u0645 \u0648\u064a\u0634\u0642\u0651\u064f \u0639\u0644\u064a\u0647\u0645 \u0645\u0634\u0642\u0629 \u063a\u064a\u0631 \u0645\u062d\u062a\u0645\u0644\u0629 \u0643\u0627\u0644\u0634\u064a\u062e \u0627\u0644\u0643\u0628\u064a\u0631\u060c \u0648\u0627\u0644\u0645\u0631\u064a\u0636 \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u064f\u0631\u0652\u062c\u064e\u0649 \u0634\u0641\u0627\u0624\u0647\u060c \u0641\u0650\u062f\u0652\u064a\u064e\u0629\u064c \u0639\u0646 \u0643\u0644 \u064a\u0648\u0645 \u064a\u0641\u0637\u0631\u0647\u060c \u0648\u0647\u064a \u0637\u0639\u0627\u0645 \u0645\u062d\u062a\u0627\u062c \u0644\u0627 \u064a\u0645\u0644\u0643 \u0645\u0627 \u064a\u0643\u0641\u064a\u0647 \u0648\u064a\u0633\u062f \u062d\u0627\u062c\u062a\u0647\u060c \u0641\u0645\u0646 \u0632\u0627\u062f \u0641\u064a \u0642\u062f\u0631 \u0627\u0644\u0641\u062f\u064a\u0629 \u062a\u0628\u0631\u0639\u064b\u0627 \u0645\u0646\u0647 \u0641\u0647\u0648 \u062e\u064a\u0631 \u0644\u0647\u060c \u0648\u0635\u064a\u0627\u0645\u0643\u0645 \u062e\u064a\u0631 \u0644\u0643\u0645 -\u0645\u0639 \u062a\u062d\u0645\u0651\u064f\u0644 \u0627\u0644\u0645\u0634\u0642\u0629- \u0645\u0646 \u0625\u0639\u0637\u0627\u0621 \u0627\u0644\u0641\u062f\u064a\u0629\u060c \u0625\u0646 \u0643\u0646\u062a\u0645 \u062a\u0639\u0644\u0645\u0648\u0646 \u0627\u0644\u0641\u0636\u0644 \u0627\u0644\u0639\u0638\u064a\u0645 \u0644\u0644\u0635\u0648\u0645 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649.","2:185":"\u0634\u0647\u0631 \u0631\u0645\u0636\u0627\u0646 \u0627\u0644\u0630\u064a \u0627\u0628\u062a\u062f\u0623 \u0627\u0644\u0644\u0647 \u0641\u064a\u0647 \u0625\u0646\u0632\u0627\u0644 \u0627\u0644\u0642\u0631\u0622\u0646 \u0641\u064a \u0644\u064a\u0644\u0629 \u0627\u0644\u0642\u062f\u0631; \u0647\u062f\u0627\u064a\u0629 \u0644\u0644\u0646\u0627\u0633 \u0625\u0644\u0649 \u0627\u0644\u062d\u0642\u060c \u0641\u064a\u0647 \u0623\u0648\u0636\u062d \u0627\u0644\u062f\u0644\u0627\u0626\u0644 \u0639\u0644\u0649 \u0647\u062f\u0649 \u0627\u0644\u0644\u0647\u060c \u0648\u0639\u0644\u0649 \u0627\u0644\u0641\u0627\u0631\u0642 \u0628\u064a\u0646 \u0627\u0644\u062d\u0642 \u0648\u0627\u0644\u0628\u0627\u0637\u0644. \u0641\u0645\u0646 \u062d\u0636\u0631 \u0645\u0646\u0643\u0645 \u0627\u0644\u0634\u0647\u0631 \u0648\u0643\u0627\u0646 \u0635\u062d\u064a\u062d\u064b\u0627 \u0645\u0642\u064a\u0645\u064b\u0627 \u0641\u0644\u064a\u0635\u0645 \u0646\u0647\u0627\u0631\u0647. \u0648\u064a\u064f\u0631\u062e\u0651\u064e\u0635 \u0644\u0644\u0645\u0631\u064a\u0636 \u0648\u0627\u0644\u0645\u0633\u0627\u0641\u0631 \u0641\u064a \u0627\u0644\u0641\u0637\u0631\u060c \u062b\u0645 \u064a\u0642\u0636\u064a\u0627\u0646 \u0639\u062f\u062f \u062a\u0644\u0643 \u0627\u0644\u0623\u064a\u0627\u0645. \u064a\u0631\u064a\u062f \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0628\u0643\u0645 \u0627\u0644\u064a\u0633\u0631 \u0648\u0627\u0644\u0633\u0647\u0648\u0644\u0629 \u0641\u064a \u0634\u0631\u0627\u0626\u0639\u0647\u060c \u0648\u0644\u0627 \u064a\u0631\u064a\u062f \u0628\u0643\u0645 \u0627\u0644\u0639\u0633\u0631 \u0648\u0627\u0644\u0645\u0634\u0642\u0629\u060c \u0648\u0644\u062a\u0643\u0645\u0644\u0648\u0627 \u0639\u062f\u0629 \u0627\u0644\u0635\u064a\u0627\u0645 \u0634\u0647\u0631\u064b\u0627\u060c \u0648\u0644\u062a\u062e\u062a\u0645\u0648\u0627 \u0627\u0644\u0635\u064a\u0627\u0645 \u0628\u062a\u0643\u0628\u064a\u0631 \u0627\u0644\u0644\u0647 \u0641\u064a \u0639\u064a\u062f \u0627\u0644\u0641\u0637\u0631\u060c \u0648\u0644\u062a\u0639\u0638\u0645\u0648\u0647 \u0639\u0644\u0649 \u0647\u062f\u0627\u064a\u062a\u0647 \u0644\u0643\u0645\u060c \u0648\u0644\u0643\u064a \u062a\u0634\u0643\u0631\u0648\u0627 \u0644\u0647 \u0639\u0644\u0649 \u0645\u0627 \u0623\u0646\u0639\u0645 \u0628\u0647 \u0639\u0644\u064a\u0643\u0645 \u0645\u0646 \u0627\u0644\u0647\u062f\u0627\u064a\u0629 \u0648\u0627\u0644\u062a\u0648\u0641\u064a\u0642 \u0648\u0627\u0644\u062a\u064a\u0633\u064a\u0631.","2:186":"\u0648\u0625\u0630\u0627 \u0633\u0623\u0644\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0639\u0628\u0627\u062f\u064a \u0639\u0646\u064a \u0641\u0642\u0644 \u0644\u0647\u0645: \u0625\u0646\u064a \u0642\u0631\u064a\u0628 \u0645\u0646\u0647\u0645\u060c \u0623\u064f\u062c\u064a\u0628 \u062f\u0639\u0648\u0629 \u0627\u0644\u062f\u0627\u0639\u064a \u0625\u0630\u0627 \u062f\u0639\u0627\u0646\u064a\u060c \u0641\u0644\u064a\u0637\u064a\u0639\u0648\u0646\u064a \u0641\u064a\u0645\u0627 \u0623\u0645\u0631\u062a\u0647\u0645 \u0628\u0647 \u0648\u0646\u0647\u064a\u062a\u0647\u0645 \u0639\u0646\u0647\u060c \u0648\u0644\u064a\u0624\u0645\u0646\u0648\u0627 \u0628\u064a\u060c \u0644\u0639\u0644\u0647\u0645 \u064a\u0647\u062a\u062f\u0648\u0646 \u0625\u0644\u0649 \u0645\u0635\u0627\u0644\u062d \u062f\u064a\u0646\u0647\u0645 \u0648\u062f\u0646\u064a\u0627\u0647\u0645. \u0648\u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0629 \u0625\u062e\u0628\u0627\u0631 \u0645\u0646\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0639\u0646 \u0642\u0631\u0628\u0647 \u0645\u0646 \u0639\u0628\u0627\u062f\u0647\u060c \u0627\u0644\u0642\u0631\u0628 \u0627\u0644\u0644\u0627\u0626\u0642 \u0628\u062c\u0644\u0627\u0644\u0647.","2:187":"\u0623\u0628\u0627\u062d \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0641\u064a \u0644\u064a\u0627\u0644\u064a \u0634\u0647\u0631 \u0631\u0645\u0636\u0627\u0646 \u062c\u0645\u0627\u0639\u064e \u0646\u0633\u0627\u0626\u0643\u0645\u060c \u0647\u0646\u0651\u064e \u0633\u062a\u0631 \u0648\u062d\u0641\u0638 \u0644\u0643\u0645\u060c \u0648\u0623\u0646\u062a\u0645 \u0633\u062a\u0631 \u0648\u062d\u0641\u0638 \u0644\u0647\u0646. \u0639\u0644\u0645 \u0627\u0644\u0644\u0647 \u0623\u0646\u0643\u0645 \u0643\u0646\u062a\u0645 \u062a\u062e\u0648\u0646\u0648\u0646 \u0623\u0646\u0641\u0633\u0643\u0645; \u0628\u0645\u062e\u0627\u0644\u0641\u0629 \u0645\u0627 \u062d\u0631\u0651\u064e\u0645\u0647 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0645\u0646 \u0645\u062c\u0627\u0645\u0639\u0629 \u0627\u0644\u0646\u0633\u0627\u0621 \u0628\u0639\u062f \u0627\u0644\u0639\u0634\u0627\u0621 \u0641\u064a \u0644\u064a\u0627\u0644\u064a \u0627\u0644\u0635\u064a\u0627\u0645 -\u0648\u0643\u0627\u0646 \u0630\u0644\u0643 \u0641\u064a \u0623\u0648\u0644 \u0627\u0644\u0625\u0633\u0644\u0627\u0645-\u060c \u0641\u062a\u0627\u0628 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0648\u0648\u0633\u0651\u064e\u0639 \u0644\u0643\u0645 \u0641\u064a \u0627\u0644\u0623\u0645\u0631\u060c \u0641\u0627\u0644\u0622\u0646 \u062c\u0627\u0645\u0639\u0648\u0647\u0646\u060c \u0648\u0627\u0637\u0644\u0628\u0648\u0627 \u0645\u0627 \u0642\u062f\u0651\u064e\u0631\u0647 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0645\u0646 \u0627\u0644\u0623\u0648\u0644\u0627\u062f\u060c \u0648\u0643\u0644\u0648\u0627 \u0648\u0627\u0634\u0631\u0628\u0648\u0627 \u062d\u062a\u0649 \u064a\u062a\u0628\u064e\u064a\u0651\u064e\u0646 \u0636\u064a\u0627\u0621 \u0627\u0644\u0635\u0628\u0627\u062d \u0645\u0646 \u0633\u0648\u0627\u062f \u0627\u0644\u0644\u064a\u0644\u060c \u0628\u0638\u0647\u0648\u0631 \u0627\u0644\u0641\u062c\u0631 \u0627\u0644\u0635\u0627\u062f\u0642\u060c \u062b\u0645 \u0623\u062a\u0645\u0648\u0627 \u0627\u0644\u0635\u064a\u0627\u0645 \u0628\u0627\u0644\u0625\u0645\u0633\u0627\u0643 \u0639\u0646 \u0627\u0644\u0645\u0641\u0637\u0631\u0627\u062a \u0625\u0644\u0649 \u062f\u062e\u0648\u0644 \u0627\u0644\u0644\u064a\u0644 \u0628\u063a\u0631\u0648\u0628 \u0627\u0644\u0634\u0645\u0633. \u0648\u0644\u0627 \u062a\u062c\u0627\u0645\u0639\u0648\u0627 \u0646\u0633\u0627\u0621\u0643\u0645 \u0623\u0648 \u062a\u062a\u0639\u0627\u0637\u0648\u0627 \u0645\u0627 \u064a\u0641\u0636\u064a \u0625\u0644\u0649 \u062c\u0645\u0627\u0639\u0647\u0646 \u0625\u0630\u0627 \u0643\u0646\u062a\u0645 \u0645\u0639\u062a\u0643\u0641\u064a\u0646 \u0641\u064a \u0627\u0644\u0645\u0633\u0627\u062c\u062f; \u0644\u0623\u0646 \u0647\u0630\u0627 \u064a\u0641\u0633\u062f \u0627\u0644\u0627\u0639\u062a\u0643\u0627\u0641 (\u0648\u0647\u0648 \u0627\u0644\u0625\u0642\u0627\u0645\u0629 \u0641\u064a \u0627\u0644\u0645\u0633\u062c\u062f \u0645\u062f\u0629 \u0645\u0639\u0644\u0648\u0645\u0629 \u0628\u0646\u064a\u0651\u064e\u0629 \u0627\u0644\u062a\u0642\u0631\u0628 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649) . \u062a\u0644\u0643 \u0627\u0644\u0623\u062d\u0643\u0627\u0645 \u0627\u0644\u062a\u064a \u0634\u0631\u0639\u0647\u0627 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0647\u064a \u062d\u062f\u0648\u062f\u0647 \u0627\u0644\u0641\u0627\u0635\u0644\u0629 \u0628\u064a\u0646 \u0627\u0644\u062d\u0644\u0627\u0644 \u0648\u0627\u0644\u062d\u0631\u0627\u0645\u060c \u0641\u0644\u0627 \u062a\u0642\u0631\u0628\u0648\u0647\u0627 \u062d\u062a\u0649 \u0644\u0627 \u062a\u0642\u0639\u0648\u0627 \u0641\u064a \u0627\u0644\u062d\u0631\u0627\u0645. \u0628\u0645\u062b\u0644 \u0647\u0630\u0627 \u0627\u0644\u0628\u064a\u0627\u0646 \u0627\u0644\u0648\u0627\u0636\u062d \u064a\u0628\u064a\u0646 \u0627\u0644\u0644\u0647 \u0622\u064a\u0627\u062a\u0647 \u0648\u0623\u062d\u0643\u0627\u0645\u0647 \u0644\u0644\u0646\u0627\u0633; \u0643\u064a \u064a\u062a\u0642\u0648\u0647 \u0648\u064a\u062e\u0634\u064e\u0648\u0652\u0647.","2:188":"\u0648\u0644\u0627 \u064a\u0623\u0643\u0644 \u0628\u0639\u0636\u0643\u0645 \u0645\u0627\u0644 \u0628\u0639\u0636 \u0628\u0633\u0628\u0628 \u0628\u0627\u0637\u0644 \u0643\u0627\u0644\u064a\u0645\u064a\u0646 \u0627\u0644\u0643\u0627\u0630\u0628\u0629\u060c \u0648\u0627\u0644\u063a\u0635\u0628\u060c \u0648\u0627\u0644\u0633\u0631\u0642\u0629\u060c \u0648\u0627\u0644\u0631\u0634\u0648\u0629\u060c \u0648\u0627\u0644\u0631\u0628\u0627 \u0648\u0646\u062d\u0648 \u0630\u0644\u0643\u060c \u0648\u0644\u0627 \u062a\u0644\u0642\u0648\u0627 \u0628\u0627\u0644\u062d\u062c\u062c \u0627\u0644\u0628\u0627\u0637\u0644\u0629 \u0625\u0644\u0649 \u0627\u0644\u062d\u0643\u0627\u0645; \u0644\u062a\u0623\u0643\u0644\u0648\u0627 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u062a\u062e\u0627\u0635\u0645 \u0623\u0645\u0648\u0627\u0644 \u0637\u0627\u0626\u0641\u0629 \u0645\u0646 \u0627\u0644\u0646\u0627\u0633 \u0628\u0627\u0644\u0628\u0627\u0637\u0644\u060c \u0648\u0623\u0646\u062a\u0645 \u062a\u0639\u0644\u0645\u0648\u0646 \u062a\u062d\u0631\u064a\u0645 \u0630\u0644\u0643 \u0639\u0644\u064a\u0643\u0645.","2:189":"\u064a\u0633\u0623\u0644\u0643 \u0623\u0635\u062d\u0627\u0628\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a-: \u0639\u0646 \u0627\u0644\u0623\u0647\u0644\u0629 \u0648\u062a\u063a\u064a\u0651\u064f\u0631 \u0623\u062d\u0648\u0627\u0644\u0647\u0627\u060c \u0642\u0644 \u0644\u0647\u0645: \u062c\u0639\u0644 \u0627\u0644\u0644\u0647\u064f \u0627\u0644\u0623\u0647\u0644\u0629 \u0639\u0644\u0627\u0645\u0627\u062a \u064a\u0639\u0631\u0641 \u0628\u0647\u0627 \u0627\u0644\u0646\u0627\u0633 \u0623\u0648\u0642\u0627\u062a \u0639\u0628\u0627\u062f\u0627\u062a\u0647\u0645 \u0627\u0644\u0645\u062d\u062f\u062f\u0629 \u0628\u0648\u0642\u062a \u0645\u062b\u0644 \u0627\u0644\u0635\u064a\u0627\u0645 \u0648\u0627\u0644\u062d\u062c\u060c \u0648\u0645\u0639\u0627\u0645\u0644\u0627\u062a\u0647\u0645. \u0648\u0644\u064a\u0633 \u0627\u0644\u062e\u064a\u0631 \u0645\u0627 \u062a\u0639\u0648\u062f\u062a\u0645 \u0639\u0644\u064a\u0647 \u0641\u064a \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629 \u0648\u0623\u0648\u0644 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0645\u0646 \u062f\u062e\u0648\u0644 \u0627\u0644\u0628\u064a\u0648\u062a \u0645\u0646 \u0638\u0647\u0648\u0631\u0647\u0627 \u062d\u064a\u0646 \u062a\u064f\u062d\u0652\u0631\u0650\u0645\u0648\u0646 \u0628\u0627\u0644\u062d\u062c \u0623\u0648 \u0627\u0644\u0639\u0645\u0631\u0629\u060c \u0638\u0627\u0646\u064a\u0646 \u0623\u0646 \u0630\u0644\u0643 \u0642\u0631\u0628\u0629 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0643\u0646 \u0627\u0644\u062e\u064a\u0631 \u0647\u0648 \u0641\u0650\u0639\u0652\u0644\u064f \u0645\u064e\u0646\u0650 \u0627\u062a\u0642\u0649 \u0627\u0644\u0644\u0647 \u0648\u0627\u062c\u062a\u0646\u0628 \u0627\u0644\u0645\u0639\u0627\u0635\u064a\u060c \u0648\u0627\u062f\u062e\u0644\u0648\u0627 \u0627\u0644\u0628\u064a\u0648\u062a \u0645\u0646 \u0623\u0628\u0648\u0627\u0628\u0647\u0627 \u0639\u0646\u062f \u0625\u062d\u0631\u0627\u0645\u0643\u0645 \u0628\u0627\u0644\u062d\u062c \u0623\u0648 \u0627\u0644\u0639\u0645\u0631\u0629\u060c \u0648\u0627\u062e\u0634\u0648\u0627 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0641\u064a \u0643\u0644 \u0623\u0645\u0648\u0631\u0643\u0645\u060c \u0644\u062a\u0641\u0648\u0632\u0648\u0627 \u0628\u0643\u0644 \u0645\u0627 \u062a\u062d\u0628\u0648\u0646 \u0645\u0646 \u062e\u064a\u0631\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629.","2:190":"\u0648\u0642\u0627\u062a\u0644\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0644\u0646\u0635\u0631\u0629 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a\u0646 \u064a\u0642\u0627\u062a\u0644\u0648\u0646\u0643\u0645\u060c \u0648\u0644\u0627 \u062a\u0631\u062a\u0643\u0628\u0648\u0627 \u0627\u0644\u0645\u0646\u0627\u0647\u064a \u0645\u0646 \u0627\u0644\u0645\u064f\u062b\u0652\u0644\u0629\u060c \u0648\u0627\u0644\u063a\u064f\u0644\u0648\u0644\u060c \u0648\u0642\u064e\u062a\u0652\u0644\u0650 \u0645\u0646 \u0644\u0627 \u064a\u062d\u0644 \u0642\u062a\u0644\u0647 \u0645\u0646 \u0627\u0644\u0646\u0633\u0627\u0621 \u0648\u0627\u0644\u0635\u0628\u064a\u0627\u0646 \u0648\u0627\u0644\u0634\u064a\u0648\u062e\u060c \u0648\u0645\u0646 \u0641\u064a \u062d\u0643\u0645\u0647\u0645. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u062d\u0628\u0651\u064f \u0627\u0644\u0630\u064a\u0646 \u064a\u064f\u062c\u0627\u0648\u0632\u0648\u0646 \u062d\u062f\u0648\u062f\u0647\u060c \u0641\u064a\u0633\u062a\u062d\u0644\u0648\u0646 \u0645\u0627 \u062d\u0631\u0651\u064e\u0645 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645.","2:191":"\u0648\u0627\u0642\u062a\u0644\u0648\u0627 \u0627\u0644\u0630\u064a\u0646 \u064a\u0642\u0627\u062a\u0644\u0648\u0646\u0643\u0645 \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u062d\u064a\u062b \u0648\u062c\u062f\u062a\u0645\u0648\u0647\u0645\u060c \u0648\u0623\u062e\u0631\u062c\u0648\u0647\u0645 \u0645\u0646 \u0627\u0644\u0645\u0643\u0627\u0646 \u0627\u0644\u0630\u064a \u0623\u062e\u0631\u062c\u0648\u0643\u0645 \u0645\u0646\u0647 \u0648\u0647\u0648 \xab\u0645\u0643\u0629\xbb . \u0648\u0627\u0644\u0641\u062a\u0646\u0629 -\u0648\u0647\u064a \u0627\u0644\u0643\u0641\u0631 \u0648\u0627\u0644\u0634\u0631\u0643 \u0648\u0627\u0644\u0635\u062f \u0639\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645- \u0623\u0634\u062f \u0645\u0646 \u0642\u062a\u0644\u0643\u0645 \u0625\u064a\u0627\u0647\u0645. \u0648\u0644\u0627 \u062a\u0628\u062f\u0624\u0648\u0647\u0645 \u0628\u0627\u0644\u0642\u062a\u0627\u0644 \u0639\u0646\u062f \u0627\u0644\u0645\u0633\u062c\u062f \u0627\u0644\u062d\u0631\u0627\u0645 \u062a\u0639\u0638\u064a\u0645\u064b\u0627 \u0644\u062d\u0631\u0645\u0627\u062a\u0647 \u062d\u062a\u0649 \u064a\u0628\u062f\u0624\u0648\u0643\u0645 \u0628\u0627\u0644\u0642\u062a\u0627\u0644 \u0641\u064a\u0647\u060c \u0641\u0625\u0646 \u0642\u0627\u062a\u0644\u0648\u0643\u0645 \u0641\u064a \u0627\u0644\u0645\u0633\u062c\u062f \u0627\u0644\u062d\u0631\u0627\u0645 \u0641\u0627\u0642\u062a\u0644\u0648\u0647\u0645 \u0641\u064a\u0647. \u0645\u062b\u0644 \u0630\u0644\u0643 \u0627\u0644\u062c\u0632\u0627\u0621 \u0627\u0644\u0631\u0627\u062f\u0639 \u064a\u0643\u0648\u0646 \u062c\u0632\u0627\u0621 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646.","2:192":"\u0641\u0625\u0646 \u062a\u0631\u0643\u0648\u0627 \u0645\u0627 \u0647\u0645 \u0641\u064a\u0647 \u0645\u0646 \u0627\u0644\u0643\u0641\u0631 \u0648\u0642\u062a\u0627\u0644\u0643\u0645 \u0639\u0646\u062f \u0627\u0644\u0645\u0633\u062c\u062f \u0627\u0644\u062d\u0631\u0627\u0645\u060c \u0648\u062f\u062e\u0644\u0648\u0627 \u0641\u064a \u0627\u0644\u0625\u064a\u0645\u0627\u0646\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u063a\u0641\u0648\u0631 \u0644\u0639\u0628\u0627\u062f\u0647\u060c \u0631\u062d\u064a\u0645 \u0628\u0647\u0645.","2:193":"\u0648\u0627\u0633\u062a\u0645\u0631\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0641\u064a \u0642\u062a\u0627\u0644 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0627\u0644\u0645\u0639\u062a\u062f\u064a\u0646\u060c \u062d\u062a\u0649 \u0644\u0627 \u062a\u0643\u0648\u0646 \u0641\u062a\u0646\u0629 \u0644\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0639\u0646 \u062f\u064a\u0646\u0647\u0645 \u0648\u0644\u0627 \u0634\u0631\u0643 \u0628\u0627\u0644\u0644\u0647\u060c \u0648\u064a\u0628\u0642\u0649 \u0627\u0644\u062f\u064a\u0646 \u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u062e\u0627\u0644\u0635\u064b\u0627 \u0644\u0627 \u064a\u064f\u0639\u0652\u0628\u064e\u062f \u0645\u0639\u0647 \u063a\u064a\u0631\u0647. \u0641\u0625\u0646 \u0643\u0641\u0651\u064f\u0648\u0627 \u0639\u0646 \u0627\u0644\u0643\u0641\u0631 \u0648\u0627\u0644\u0642\u062a\u0627\u0644 \u0641\u0643\u064f\u0641\u0651\u064f\u0648\u0627 \u0639\u0646\u0647\u0645; \u0641\u0627\u0644\u0639\u0642\u0648\u0628\u0629 \u0644\u0627 \u062a\u0643\u0648\u0646 \u0625\u0644\u0627 \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u062a\u0645\u0631\u064a\u0646 \u0639\u0644\u0649 \u0643\u0641\u0631\u0647\u0645 \u0648\u0639\u062f\u0648\u0627\u0646\u0647\u0645.","2:194":"\u0642\u062a\u0627\u0644\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0644\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0641\u064a \u0627\u0644\u0634\u0647\u0631 \u0627\u0644\u0630\u064a \u062d\u0631\u0651\u064e\u0645 \u0627\u0644\u0644\u0647 \u0627\u0644\u0642\u062a\u0627\u0644 \u0641\u064a\u0647 \u0647\u0648 \u062c\u0632\u0627\u0621 \u0644\u0642\u062a\u0627\u0644\u0647\u0645 \u0644\u0643\u0645 \u0641\u064a \u0627\u0644\u0634\u0647\u0631 \u0627\u0644\u062d\u0631\u0627\u0645. \u0648\u0627\u0644\u0630\u064a \u064a\u0639\u062a\u062f\u064a \u0639\u0644\u0649 \u0645\u0627 \u062d\u064e\u0631\u0651\u064e\u0645 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u0645\u0643\u0627\u0646 \u0648\u0627\u0644\u0632\u0645\u0627\u0646\u060c \u064a\u0639\u0627\u0642\u0628 \u0628\u0645\u062b\u0644 \u0641\u0639\u0644\u0647\u060c \u0648\u0645\u0646 \u062c\u0646\u0633 \u0639\u0645\u0644\u0647. \u0641\u0645\u0646 \u0627\u0639\u062a\u062f\u0649 \u0639\u0644\u064a\u0643\u0645 \u0628\u0627\u0644\u0642\u062a\u0627\u0644 \u0623\u0648 \u063a\u064a\u0631\u0647 \u0641\u0623\u0646\u0632\u0644\u0648\u0627 \u0628\u0647 \u0639\u0642\u0648\u0628\u0629 \u0645\u0645\u0627\u062b\u0644\u0629 \u0644\u062c\u0646\u0627\u064a\u062a\u0647\u060c \u0648\u0644\u0627 \u062d\u0631\u062c \u0639\u0644\u064a\u0643\u0645 \u0641\u064a \u0630\u0644\u0643; \u0644\u0623\u0646\u0647\u0645 \u0647\u0645 \u0627\u0644\u0628\u0627\u062f\u0626\u0648\u0646 \u0628\u0627\u0644\u0639\u062f\u0648\u0627\u0646\u060c \u0648\u062e\u0627\u0641\u0648\u0627 \u0627\u0644\u0644\u0647 \u0641\u0644\u0627 \u062a\u062a\u062c\u0627\u0648\u0632\u0648\u0627 \u0627\u0644\u0645\u0645\u0627\u062b\u0644\u0629 \u0641\u064a \u0627\u0644\u0639\u0642\u0648\u0628\u0629\u060c \u0648\u0627\u0639\u0644\u0645\u0648\u0627 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0645\u0639 \u0627\u0644\u0630\u064a\u0646 \u064a\u062a\u0642\u0648\u0646\u0647 \u0648\u064a\u0637\u064a\u0639\u0648\u0646\u0647 \u0628\u0623\u062f\u0627\u0621 \u0641\u0631\u0627\u0626\u0636\u0647 \u0648\u062a\u062c\u0646\u0628 \u0645\u062d\u0627\u0631\u0645\u0647.","2:195":"\u0648\u0627\u0633\u062a\u0645\u0631\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0641\u064a \u0625\u0646\u0641\u0627\u0642 \u0627\u0644\u0623\u0645\u0648\u0627\u0644 \u0644\u0646\u0635\u0631\u0629 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0627\u0644\u062c\u0647\u0627\u062f \u0641\u064a \u0633\u0628\u064a\u0644\u0647\u060c \u0648\u0644\u0627 \u062a\u0648\u0642\u0639\u0648\u0627 \u0623\u0646\u0641\u0633\u0643\u0645 \u0641\u064a \u0627\u0644\u0645\u0647\u0627\u0644\u0643 \u0628\u062a\u0631\u0643 \u0627\u0644\u062c\u0647\u0627\u062f \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647\u060c \u0648\u0639\u062f\u0645 \u0627\u0644\u0625\u0646\u0641\u0627\u0642 \u0641\u064a\u0647\u060c \u0648\u0623\u062d\u0633\u0646\u0648\u0627 \u0641\u064a \u0627\u0644\u0627\u0646\u0641\u0627\u0642 \u0648\u0627\u0644\u0637\u0627\u0639\u0629\u060c \u0648\u0627\u062c\u0639\u0644\u0648\u0627 \u0639\u064e\u0645\u064e\u0644\u064e\u0643\u064f\u0645 \u0643\u0644\u0647 \u062e\u0627\u0644\u0635\u064b\u0627 \u0644\u0648\u062c\u0647 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649. \u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u062d\u0628 \u0623\u0647\u0644 \u0627\u0644\u0625\u062e\u0644\u0627\u0635 \u0648\u0627\u0644\u0625\u062d\u0633\u0627\u0646.","2:196":"\u0648\u0623\u062f\u0651\u064f\u0648\u0627 \u0627\u0644\u062d\u062c \u0648\u0627\u0644\u0639\u0645\u0631\u0629 \u062a\u0627\u0645\u0651\u064e\u064a\u0652\u0646\u0650\u060c \u062e\u0627\u0644\u0635\u064a\u0646 \u0644\u0648\u062c\u0647 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649. \u0641\u0625\u0646 \u0645\u0646\u0639\u0643\u0645 \u0639\u0646 \u0627\u0644\u0630\u0647\u0627\u0628 \u0644\u0625\u062a\u0645\u0627\u0645\u0647\u0645\u0627 \u0628\u0639\u062f \u0627\u0644\u0625\u062d\u0631\u0627\u0645 \u0628\u0647\u0645\u0627 \u0645\u0627\u0646\u0639 \u0643\u0627\u0644\u0639\u062f\u0648 \u0648\u0627\u0644\u0645\u0631\u0636\u060c \u0641\u0627\u0644\u0648\u0627\u062c\u0628 \u0639\u0644\u064a\u0643\u0645 \u0630\u064e\u0628\u0652\u062d\u064f \u0645\u0627 \u062a\u064a\u0633\u0631 \u0644\u0643\u0645 \u0645\u0646 \u0627\u0644\u0625\u0628\u0644 \u0623\u0648 \u0627\u0644\u0628\u0642\u0631 \u0623\u0648 \u0627\u0644\u063a\u0646\u0645 \u062a\u0642\u0631\u0628\u064b\u0627 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649; \u0644\u0643\u064a \u062a\u064e\u062e\u0652\u0631\u064f\u062c\u0648\u0627 \u0645\u0646 \u0625\u062d\u0631\u0627\u0645\u0643\u0645 \u0628\u062d\u0644\u0642 \u0634\u0639\u0631 \u0627\u0644\u0631\u0623\u0633 \u0623\u0648 \u062a\u0642\u0635\u064a\u0631\u0647\u060c \u0648\u0644\u0627 \u062a\u062d\u0644\u0642\u0648\u0627 \u0631\u0624\u0648\u0633\u0643\u0645 \u0625\u0630\u0627 \u0643\u0646\u062a\u0645 \u0645\u062d\u0635\u0631\u064a\u0646 \u062d\u062a\u0649 \u064a\u0646\u062d\u0631 \u0627\u0644\u0645\u062d\u0635\u0631 \u0647\u062f\u064a\u0647 \u0641\u064a \u0627\u0644\u0645\u0648\u0636\u0639 \u0627\u0644\u0630\u064a \u062d\u064f\u0635\u0631 \u0641\u064a\u0647 \u062b\u0645 \u064a\u062d\u0644 \u0645\u0646 \u0625\u062d\u0631\u0627\u0645\u0647\u060c \u0643\u0645\u0627 \u0646\u062d\u0631 \u0627\u0644\u0646\u0628\u064a \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0641\u064a \xab\u0627\u0644\u062d\u062f\u064a\u0628\u064a\u0629\xbb \u062b\u0645 \u062d\u0644\u0642 \u0631\u0623\u0633\u0647\u060c \u0648\u063a\u064a\u0631 \u0627\u0644\u0645\u062d\u0635\u0631 \u0644\u0627 \u064a\u0646\u062d\u0631 \u0627\u0644\u0647\u062f\u064a \u0625\u0644\u0627 \u0641\u064a \u0627\u0644\u062d\u0631\u0645\u060c \u0627\u0644\u0630\u064a \u0647\u0648 \u0645\u062d\u0644\u0647 \u0641\u064a \u064a\u0648\u0645 \u0627\u0644\u0639\u064a\u062f\u060c \u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0639\u0627\u0634\u0631 \u0648\u0645\u0627 \u0628\u0639\u062f\u0647 \u0645\u0646 \u0623\u064a\u0627\u0645 \u0627\u0644\u062a\u0634\u0631\u064a\u0642. \u0641\u0645\u0646 \u0643\u0627\u0646 \u0645\u0646\u0643\u0645 \u0645\u0631\u064a\u0636\u064b\u0627\u060c \u0623\u0648 \u0628\u0647 \u0623\u0630\u0649 \u0645\u0646 \u0631\u0623\u0633\u0647 \u064a\u062d\u062a\u0627\u062c \u0645\u0639\u0647 \u0625\u0644\u0649 \u0627\u0644\u062d\u0644\u0642 -\u0648\u0647\u0648 \u0645\u064f\u062d\u0652\u0631\u0650\u0645- \u062d\u064e\u0644\u064e\u0642\u060c \u0648\u0639\u0644\u064a\u0647 \u0641\u062f\u064a\u0629: \u0628\u0623\u0646 \u064a\u0635\u0648\u0645 \u062b\u0644\u0627\u062b\u0629 \u0623\u064a\u0627\u0645\u060c \u0623\u0648 \u064a\u062a\u0635\u062f\u0642 \u0639\u0644\u0649 \u0633\u062a\u0629 \u0645\u0633\u0627\u0643\u064a\u0646 \u0644\u0643\u0644 \u0645\u0633\u0643\u064a\u0646 \u0646\u0635\u0641 \u0635\u0627\u0639 \u0645\u0646 \u0637\u0639\u0627\u0645\u060c \u0623\u0648 \u064a\u0630\u0628\u062d \u0634\u0627\u0629 \u0644\u0641\u0642\u0631\u0627\u0621 \u0627\u0644\u062d\u0631\u0645. \u0641\u0625\u0630\u0627 \u0643\u0646\u062a\u0645 \u0641\u064a \u0623\u0645\u0646 \u0648\u0635\u062d\u0651\u064e\u0629: \u0641\u0645\u0646 \u0627\u0633\u062a\u0645\u062a\u0639 \u0628\u0627\u0644\u0639\u0645\u0631\u0629 \u0625\u0644\u0649 \u0627\u0644\u062d\u062c \u0648\u0630\u0644\u0643 \u0628\u0627\u0633\u062a\u0628\u0627\u062d\u0629 \u0645\u0627 \u062d\u064f\u0631\u0651\u0650\u0645 \u0639\u0644\u064a\u0647 \u0628\u0633\u0628\u0628 \u0627\u0644\u0625\u062d\u0631\u0627\u0645 \u0628\u0639\u062f \u0627\u0646\u062a\u0647\u0627\u0621 \u0639\u0645\u0631\u062a\u0647\u060c \u0641\u0639\u0644\u064a\u0647 \u0630\u0628\u062d \u0645\u0627 \u062a\u064a\u0633\u0631 \u0645\u0646 \u0627\u0644\u0647\u062f\u064a\u060c \u0641\u0645\u0646 \u0644\u0645 \u064a\u062c\u062f \u0647\u064e\u062f\u0652\u064a\u064b\u0627 \u064a\u0630\u0628\u062d\u0647 \u0641\u0639\u0644\u064a\u0647 \u0635\u064a\u0627\u0645 \u062b\u0644\u0627\u062b\u0629 \u0623\u064a\u0627\u0645 \u0641\u064a \u0623\u0634\u0647\u0631 \u0627\u0644\u062d\u062c\u060c \u0648\u0633\u0628\u0639\u0629 \u0625\u0630\u0627 \u0641\u0631\u063a\u062a\u0645 \u0645\u0646 \u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u062d\u062c \u0648\u0631\u062c\u0639\u062a\u0645 \u0625\u0644\u0649 \u0623\u0647\u0644\u064a\u0643\u0645\u060c \u062a\u0644\u0643 \u0639\u0634\u0631\u0629 \u0643\u0627\u0645\u0644\u0629 \u0644\u0627 \u0628\u062f \u0645\u0646 \u0635\u064a\u0627\u0645\u0647\u0627. \u0630\u0644\u0643 \u0627\u0644\u0647\u064e\u062f\u0652\u064a\u064f \u0648\u0645\u0627 \u062a\u0631\u062a\u0628 \u0639\u0644\u064a\u0647 \u0645\u0646 \u0627\u0644\u0635\u064a\u0627\u0645 \u0644\u0645\u0646 \u0644\u0645 \u064a\u0643\u0646 \u0623\u0647\u0644\u0647 \u0645\u0646 \u0633\u0627\u0643\u0646\u064a \u0623\u0631\u0636 \u0627\u0644\u062d\u0631\u0645\u060c \u0648\u062e\u0627\u0641\u0648\u0627 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u062d\u0627\u0641\u0638\u0648\u0627 \u0639\u0644\u0649 \u0627\u0645\u062a\u062b\u0627\u0644 \u0623\u0648\u0627\u0645\u0631\u0647 \u0648\u0627\u062c\u062a\u0646\u0627\u0628 \u0646\u0648\u0627\u0647\u064a\u0647\u060c \u0648\u0627\u0639\u0644\u0645\u0648\u0627 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0634\u062f\u064a\u062f \u0627\u0644\u0639\u0642\u0627\u0628 \u0644\u0645\u0646 \u062e\u0627\u0644\u0641 \u0623\u0645\u0631\u0647\u060c \u0648\u0627\u0631\u062a\u0643\u0628 \u0645\u0627 \u0639\u0646\u0647 \u0632\u062c\u0631.","2:197":"\u0648\u0642\u062a \u0627\u0644\u062d\u062c \u0623\u0634\u0647\u0631 \u0645\u0639\u0644\u0648\u0645\u0627\u062a\u060c \u0648\u0647\u064a: \u0634\u0648\u0627\u0644\u060c \u0648\u0630\u0648 \u0627\u0644\u0642\u0639\u062f\u0629\u060c \u0648\u0639\u0634\u0631 \u0645\u0646 \u0630\u064a \u0627\u0644\u062d\u062c\u0629. \u0641\u0645\u0646 \u0623\u0648\u062c\u0628 \u0627\u0644\u062d\u062c \u0639\u0644\u0649 \u0646\u0641\u0633\u0647 \u0641\u064a\u0647\u0646 \u0628\u0627\u0644\u0625\u062d\u0631\u0627\u0645\u060c \u0641\u064a\u062d\u0631\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u062c\u0645\u0627\u0639 \u0648\u0645\u0642\u062f\u0645\u0627\u062a\u0647 \u0627\u0644\u0642\u0648\u0644\u064a\u0629 \u0648\u0627\u0644\u0641\u0639\u0644\u064a\u0629\u060c \u0648\u064a\u062d\u0631\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u062e\u0631\u0648\u062c \u0639\u0646 \u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0628\u0641\u0639\u0644 \u0627\u0644\u0645\u0639\u0627\u0635\u064a\u060c \u0648\u0627\u0644\u062c\u062f\u0627\u0644 \u0641\u064a \u0627\u0644\u062d\u062c \u0627\u0644\u0630\u064a \u064a\u0624\u062f\u064a \u0625\u0644\u0649 \u0627\u0644\u063a\u0636\u0628 \u0648\u0627\u0644\u0643\u0631\u0627\u0647\u064a\u0629. \u0648\u0645\u0627 \u062a\u0641\u0639\u0644\u0648\u0627 \u0645\u0646 \u062e\u064a\u0631 \u064a\u0639\u0644\u0645\u0647 \u0627\u0644\u0644\u0647\u060c \u0641\u064a\u062c\u0627\u0632\u064a \u0643\u0644\u0627 \u0639\u0644\u0649 \u0639\u0645\u0644\u0647. \u0648\u062e\u0630\u0648\u0627 \u0644\u0623\u0646\u0641\u0633\u0643\u0645 \u0632\u0627\u062f\u064b\u0627 \u0645\u0646 \u0627\u0644\u0637\u0639\u0627\u0645 \u0648\u0627\u0644\u0634\u0631\u0627\u0628 \u0644\u0633\u0641\u0631 \u0627\u0644\u062d\u062c\u060c \u0648\u0632\u0627\u062f\u064b\u0627 \u0645\u0646 \u0635\u0627\u0644\u062d \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0644\u0644\u062f\u0627\u0631 \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0641\u0625\u0646 \u062e\u064a\u0631 \u0627\u0644\u0632\u0627\u062f \u062a\u0642\u0648\u0649 \u0627\u0644\u0644\u0647\u060c \u0648\u062e\u0627\u0641\u0648\u0646\u064a \u064a\u0627 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0639\u0642\u0648\u0644 \u0627\u0644\u0633\u0644\u064a\u0645\u0629.","2:198":"\u0644\u064a\u0633 \u0639\u0644\u064a\u0643\u0645 \u062d\u0631\u062c \u0641\u064a \u0623\u0646 \u062a\u0637\u0644\u0628\u0648\u0627 \u0631\u0632\u0642\u064b\u0627 \u0645\u0646 \u0631\u0628\u0643\u0645 \u0628\u0627\u0644\u0631\u0628\u062d \u0645\u0646 \u0627\u0644\u062a\u062c\u0627\u0631\u0629 \u0641\u064a \u0623\u064a\u0627\u0645 \u0627\u0644\u062d\u062c. \u0641\u0625\u0630\u0627 \u062f\u0641\u0639\u062a\u0645 \u0628\u0639\u062f \u063a\u0631\u0648\u0628 \u0627\u0644\u0634\u0645\u0633 \u0631\u0627\u062c\u0639\u064a\u0646 \u0645\u0646 \xab\u0639\u0631\u0641\u0627\u062a\xbb -\u0648\u0647\u064a \u0627\u0644\u0645\u0643\u0627\u0646 \u0627\u0644\u0630\u064a \u064a\u0642\u0641 \u0641\u064a\u0647 \u0627\u0644\u062d\u062c\u0627\u062c \u064a\u0648\u0645 \u0627\u0644\u062a\u0627\u0633\u0639 \u0645\u0646 \u0630\u064a \u0627\u0644\u062d\u062c\u0629- \u0641\u0627\u0630\u0643\u0631\u0648\u0627 \u0627\u0644\u0644\u0647 \u0628\u0627\u0644\u062a\u0633\u0628\u064a\u062d \u0648\u0627\u0644\u062a\u0644\u0628\u064a\u0629 \u0648\u0627\u0644\u062f\u0639\u0627\u0621 \u0639\u0646\u062f \u0627\u0644\u0645\u0634\u0639\u0631 \u0627\u0644\u062d\u0631\u0627\u0645 - \xab\u0627\u0644\u0645\u0632\u062f\u0644\u0641\u0629\xbb -\u060c \u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0627\u0644\u0648\u062c\u0647 \u0627\u0644\u0635\u062d\u064a\u062d \u0627\u0644\u0630\u064a \u0647\u062f\u0627\u0643\u0645 \u0625\u0644\u064a\u0647\u060c \u0648\u0644\u0642\u062f \u0643\u0646\u062a\u0645 \u0645\u0646 \u0642\u0628\u0644 \u0647\u0630\u0627 \u0627\u0644\u0647\u062f\u0649 \u0641\u064a \u0636\u0644\u0627\u0644 \u0644\u0627 \u062a\u0639\u0631\u0641\u0648\u0646 \u0645\u0639\u0647 \u0627\u0644\u062d\u0642.","2:199":"\u0648\u0644\u064a\u0643\u0646 \u0627\u0646\u062f\u0641\u0627\u0639\u0643\u0645 \u0645\u0646 \xab\u0639\u0631\u0641\u0627\u062a\xbb \u0627\u0644\u062a\u064a \u0623\u0641\u0627\u0636 \u0645\u0646\u0647\u0627 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0645\u062e\u0627\u0644\u0641\u064a\u0646 \u0628\u0630\u0644\u0643 \u0645\u0646 \u0644\u0627 \u064a\u0642\u0641 \u0628\u0647\u0627 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629\u060c \u0648\u0627\u0633\u0623\u0644\u0648\u0627 \u0627\u0644\u0644\u0647 \u0623\u0646 \u064a\u063a\u0641\u0631 \u0644\u0643\u0645 \u0630\u0646\u0648\u0628\u0643\u0645. \u0625\u0646 \u0627\u0644\u0644\u0647 \u063a\u0641\u0648\u0631 \u0644\u0639\u0628\u0627\u062f\u0647 \u0627\u0644\u0645\u0633\u062a\u063a\u0641\u0631\u064a\u0646 \u0627\u0644\u062a\u0627\u0626\u0628\u064a\u0646\u060c \u0631\u062d\u064a\u0645 \u0628\u0647\u0645.","2:200":"\u0641\u0625\u0630\u0627 \u0623\u062a\u0645\u0645\u062a\u0645 \u0639\u0628\u0627\u062f\u062a\u0643\u0645\u060c \u0648\u0641\u0631\u063a\u062a\u0645 \u0645\u0646 \u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u062d\u062c\u060c \u0641\u0623\u0643\u062b\u0631\u0648\u0627 \u0645\u0646 \u0630\u0643\u0631 \u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u062b\u0646\u0627\u0621 \u0639\u0644\u064a\u0647\u060c \u0645\u062b\u0644 \u0630\u0643\u0631\u0643\u0645 \u0645\u0641\u0627\u062e\u0631 \u0622\u0628\u0627\u0626\u0643\u0645 \u0648\u0623\u0639\u0638\u0645 \u0645\u0646 \u0630\u0644\u0643. \u0641\u0645\u0646 \u0627\u0644\u0646\u0627\u0633 \u0641\u0631\u064a\u0642 \u064a\u062c\u0639\u0644 \u0647\u0645\u0647 \u0627\u0644\u062f\u0646\u064a\u0627 \u0641\u0642\u0637\u060c \u0641\u064a\u062f\u0639\u0648 \u0642\u0627\u0626\u0644\u0627 \u0631\u0628\u0646\u0627 \u0622\u062a\u0646\u0627 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0635\u062d\u0629\u060c \u0648\u0645\u0627\u0644\u0627 \u0648\u0623\u0648\u0644\u0627\u062f\u064b\u0627\u060c \u0648\u0647\u0624\u0644\u0627\u0621 \u0644\u064a\u0633 \u0644\u0647\u0645 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u062d\u0638 \u0648\u0644\u0627 \u0646\u0635\u064a\u0628; \u0644\u0631\u063a\u0628\u062a\u0647\u0645 \u0639\u0646\u0647\u0627 \u0648\u0642\u064e\u0635\u0652\u0631\u0650 \u0647\u064e\u0645\u0651\u0650\u0647\u0645 \u0639\u0644\u0649 \u0627\u0644\u062f\u0646\u064a\u0627.","2:201":"\u0648\u0645\u0646 \u0627\u0644\u0646\u0627\u0633 \u0641\u0631\u064a\u0642 \u0645\u0624\u0645\u0646 \u064a\u0642\u0648\u0644 \u0641\u064a \u062f\u0639\u0627\u0626\u0647: \u0631\u0628\u0646\u0627 \u0622\u062a\u0646\u0627 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0639\u0627\u0641\u064a\u0629 \u0648\u0631\u0632\u0642\u064b\u0627 \u0648\u0639\u0644\u0645\u064b\u0627 \u0646\u0627\u0641\u0639\u064b\u0627\u060c \u0648\u0639\u0645\u0644\u0627 \u0635\u0627\u0644\u062d\u064b\u0627\u060c \u0648\u063a\u064a\u0631 \u0630\u0644\u0643 \u0645\u0646 \u0623\u0645\u0648\u0631 \u0627\u0644\u062f\u064a\u0646 \u0648\u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u0627\u0644\u062c\u0646\u0629\u060c \u0648\u0627\u0635\u0631\u0641 \u0639\u0646\u0651\u064e\u0627 \u0639\u0630\u0627\u0628 \u0627\u0644\u0646\u0627\u0631. \u0648\u0647\u0630\u0627 \u0627\u0644\u062f\u0639\u0627\u0621 \u0645\u0646 \u0623\u062c\u0645\u0639 \u0627\u0644\u0623\u062f\u0639\u064a\u0629\u060c \u0648\u0644\u0647\u0630\u0627 \u0643\u0627\u0646 \u0623\u0643\u062b\u0631 \u062f\u0639\u0627\u0621 \u0627\u0644\u0646\u0628\u064a \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0643\u0645\u0627 \u062b\u0628\u062a \u0641\u064a \u0627\u0644\u0635\u062d\u064a\u062d\u064a\u0646.","2:202":"\u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u062f\u0627\u0639\u0648\u0646 \u0628\u0647\u0630\u0627 \u0627\u0644\u062f\u0639\u0627\u0621 \u0644\u0647\u0645 \u062b\u0648\u0627\u0628 \u0639\u0638\u064a\u0645 \u0628\u0633\u0628\u0628 \u0645\u0627 \u0643\u0633\u0628\u0648\u0647 \u0645\u0646 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0635\u0627\u0644\u062d\u0629. \u0648\u0627\u0644\u0644\u0647 \u0633\u0631\u064a\u0639 \u0627\u0644\u062d\u0633\u0627\u0628\u060c \u0645\u064f\u062d\u0652\u0635\u064d \u0623\u0639\u0645\u0627\u0644 \u0639\u0628\u0627\u062f\u0647\u060c \u0648\u0645\u062c\u0627\u0632\u064a\u0647\u0645 \u0628\u0647\u0627.","2:203":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u0627\u0644\u0644\u0647 \u062a\u0633\u0628\u064a\u062d\u064b\u0627 \u0648\u062a\u0643\u0628\u064a\u0631\u064b\u0627 \u0641\u064a \u0623\u064a\u0627\u0645 \u0642\u0644\u0627\u0626\u0644\u060c \u0648\u0647\u064a \u0623\u064a\u0627\u0645 \u0627\u0644\u062a\u0634\u0631\u064a\u0642: \u0627\u0644\u062d\u0627\u062f\u064a \u0639\u0634\u0631 \u0648\u0627\u0644\u062b\u0627\u0646\u064a \u0639\u0634\u0631 \u0648\u0627\u0644\u062b\u0627\u0644\u062b \u0639\u0634\u0631 \u0645\u0646 \u0634\u0647\u0631 \u0630\u064a \u0627\u0644\u062d\u062c\u0629. \u0641\u0645\u0646 \u0623\u0631\u0627\u062f \u0627\u0644\u062a\u0639\u062c\u0644 \u0648\u062e\u0631\u062c \u0645\u0646 \xab\u0645\u0650\u0646\u0649\xbb \u0642\u0628\u0644 \u063a\u0631\u0648\u0628 \u0634\u0645\u0633 \u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u062b\u0627\u0646\u064a \u0639\u0634\u0631 \u0628\u0639\u062f \u0631\u0645\u064a \u0627\u0644\u062c\u0645\u0627\u0631 \u0641\u0644\u0627 \u0630\u0646\u0628 \u0639\u0644\u064a\u0647\u060c \u0648\u0645\u0646 \u062a\u0623\u062e\u0631 \u0628\u0623\u0646 \u0628\u0627\u062a \u0628\u0640 \xab\u0645\u0650\u0646\u0649\xbb \u062d\u062a\u0649 \u064a\u0631\u0645\u064a \u0627\u0644\u062c\u0645\u0627\u0631 \u0641\u064a \u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u062b\u0627\u0644\u062b \u0639\u0634\u0631 \u0641\u0644\u0627 \u0630\u0646\u0628 \u0639\u0644\u064a\u0647\u060c \u0644\u0645\u0646 \u0627\u062a\u0642\u0649 \u0627\u0644\u0644\u0647 \u0641\u064a \u062d\u062c\u0647. \u0648\u0627\u0644\u062a\u0623\u062e\u0631 \u0623\u0641\u0636\u0644; \u0644\u0623\u0646\u0647 \u062a\u0632\u0648\u0651\u064f\u062f \u0641\u064a \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u0648\u0627\u0642\u062a\u062f\u0627\u0621 \u0628\u0641\u0639\u0644 \u0627\u0644\u0646\u0628\u064a \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645.","2:204":"\u0648\u0628\u0639\u0636 \u0627\u0644\u0646\u0627\u0633 \u0645\u0646 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u064a\u0639\u062c\u0628\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0643\u0644\u0627\u0645\u0647 \u0627\u0644\u0641\u0635\u064a\u062d \u0627\u0644\u0630\u064a \u064a\u0631\u064a\u062f \u0628\u0647 \u062d\u0638\u0651\u064b\u0627 \u0645\u0646 \u062d\u0638\u0648\u0638 \u0627\u0644\u062f\u0646\u064a\u0627 \u0644\u0627 \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u064a\u062d\u0644\u0641 \u0645\u0633\u062a\u0634\u0647\u062f\u064b\u0627 \u0628\u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0645\u0627 \u0641\u064a \u0642\u0644\u0628\u0647 \u0645\u0646 \u0645\u062d\u0628\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0648\u0641\u064a \u0647\u0630\u0627 \u063a\u0627\u064a\u0629 \u0627\u0644\u062c\u0631\u0623\u0629 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0648\u0647\u0648 \u0634\u062f\u064a\u062f \u0627\u0644\u0639\u062f\u0627\u0648\u0629 \u0648\u0627\u0644\u062e\u0635\u0648\u0645\u0629 \u0644\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646.","2:205":"\u0648\u0625\u0630\u0627 \u062e\u0631\u062c \u0645\u0646 \u0639\u0646\u062f\u0643 \u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644\u060c \u062c\u064e\u062f\u0651\u064e \u0648\u0646\u064e\u0634\u0650\u0637 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0644\u064a\u0641\u0633\u062f \u0641\u064a\u0647\u0627\u060c \u0648\u064a\u062a\u0644\u0641 \u0632\u0631\u0648\u0639 \u0627\u0644\u0646\u0627\u0633\u060c \u0648\u064a\u0642\u062a\u0644 \u0645\u0627\u0634\u064a\u062a\u0647\u0645. \u0648\u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u062d\u0628 \u0627\u0644\u0641\u0633\u0627\u062f.","2:206":"\u0648\u0625\u0630\u0627 \u0646\u064f\u0635\u0650\u062d \u0630\u0644\u0643 \u0627\u0644\u0645\u0646\u0627\u0641\u0642 \u0627\u0644\u0645\u0641\u0633\u062f\u060c \u0648\u0642\u064a\u0644 \u0644\u0647: \u0627\u062a\u0642 \u0627\u0644\u0644\u0647 \u0648\u0627\u062d\u0630\u0631 \u0639\u0642\u0627\u0628\u0647\u060c \u0648\u0643\u064f\u0641\u0651\u064e \u0639\u0646 \u0627\u0644\u0641\u0633\u0627\u062f \u0641\u064a \u0627\u0644\u0623\u0631\u0636\u060c \u0644\u0645 \u064a\u0642\u0628\u0644 \u0627\u0644\u0646\u0635\u064a\u062d\u0629\u060c \u0628\u0644 \u064a\u062d\u0645\u0644\u0647 \u0627\u0644\u0643\u0628\u0631 \u0648\u062d\u0645\u064a\u0651\u064e\u0629 \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629 \u0639\u0644\u0649 \u0645\u0632\u064a\u062f \u0645\u0646 \u0627\u0644\u0622\u062b\u0627\u0645\u060c \u0641\u064e\u062d\u064e\u0633\u0652\u0628\u064f\u0647 \u062c\u0647\u0646\u0645 \u0648\u0643\u0627\u0641\u064a\u062a\u0647 \u0639\u0630\u0627\u0628\u064b\u0627\u060c \u0648\u0644\u0628\u0626\u0633 \u0627\u0644\u0641\u0631\u0627\u0634 \u0647\u064a.","2:207":"\u0648\u0628\u0639\u0636 \u0627\u0644\u0646\u0627\u0633 \u064a\u0628\u064a\u0639 \u0646\u0641\u0633\u0647 \u0637\u0644\u0628\u064b\u0627 \u0644\u0631\u0636\u0627 \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u060c \u0628\u0627\u0644\u062c\u0647\u0627\u062f \u0641\u064a \u0633\u0628\u064a\u0644\u0647\u060c \u0648\u0627\u0644\u062a\u0632\u0627\u0645 \u0637\u0627\u0639\u062a\u0647. \u0648\u0627\u0644\u0644\u0647 \u0631\u0621\u0648\u0641 \u0628\u0627\u0644\u0639\u0628\u0627\u062f\u060c \u064a\u0631\u062d\u0645 \u0639\u0628\u0627\u062f\u0647 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0631\u062d\u0645\u0629 \u0648\u0627\u0633\u0639\u0629 \u0641\u064a \u0639\u0627\u062c\u0644\u0647\u0645 \u0648\u0622\u062c\u0644\u0647\u0645\u060c \u0641\u064a\u062c\u0627\u0632\u0628\u0647\u0645 \u0623\u062d\u0633\u0646 \u0627\u0644\u062c\u0632\u0627\u0621.","2:208":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0631\u0628\u064b\u0627 \u0648\u0628\u0645\u062d\u0645\u062f \u0646\u0628\u064a\u064b\u0627 \u0648\u0631\u0633\u0648\u0644\u0627 \u0648\u0628\u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u062f\u064a\u0646\u064b\u0627\u060c \u0627\u062f\u062e\u0644\u0648\u0627 \u0641\u064a \u062c\u0645\u064a\u0639 \u0634\u0631\u0627\u0626\u0639 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0639\u0627\u0645\u0644\u064a\u0646 \u0628\u062c\u0645\u064a\u0639 \u0623\u062d\u0643\u0627\u0645\u0647\u060c \u0648\u0644\u0627 \u062a\u062a\u0631\u0643\u0648\u0627 \u0645\u0646\u0647\u0627 \u0634\u064a\u0626\u064b\u0627\u060c \u0648\u0644\u0627 \u062a\u062a\u0628\u0639\u0648\u0627 \u0637\u0631\u0642 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0641\u064a\u0645\u0627 \u064a\u062f\u0639\u0648\u0643\u0645 \u0625\u0644\u064a\u0647 \u0645\u0646 \u0627\u0644\u0645\u0639\u0627\u0635\u064a. \u0625\u0646\u0647 \u0644\u0643\u0645 \u0639\u062f\u0648 \u0638\u0627\u0647\u0631 \u0627\u0644\u0639\u062f\u0627\u0648\u0629 \u0641\u0627\u062d\u0630\u0631\u0648\u0647.","2:209":"\u0641\u0625\u0646 \u0627\u0646\u062d\u0631\u0641\u062a\u0645 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u062d\u0642\u060c \u0645\u0646 \u0628\u0639\u062f \u0645\u0627 \u062c\u0627\u0621\u062a\u0643\u0645 \u0627\u0644\u062d\u062c\u062c \u0627\u0644\u0648\u0627\u0636\u062d\u0629 \u0645\u0646 \u0627\u0644\u0642\u0631\u0622\u0646 \u0648\u0627\u0644\u0633\u0646\u0629\u060c \u0641\u0627\u0639\u0644\u0645\u0648\u0627 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0639\u0632\u064a\u0632 \u0641\u064a \u0645\u0644\u0643\u0647 \u0644\u0627 \u064a\u0641\u0648\u062a\u0647 \u0634\u064a\u0621\u060c \u062d\u0643\u064a\u0645 \u0641\u064a \u0623\u0645\u0631\u0647 \u0648\u0646\u0647\u064a\u0647\u060c \u064a\u0636\u0639 \u0643\u0644 \u0634\u064a\u0621 \u0641\u064a \u0645\u0648\u0636\u0639\u0647 \u0627\u0644\u0645\u0646\u0627\u0633\u0628 \u0644\u0647.","2:210":"\u0645\u0627 \u064a\u0646\u062a\u0638\u0631 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0639\u0627\u0646\u062f\u0648\u0646 \u0627\u0644\u0643\u0627\u0641\u0631\u0648\u0646 \u0628\u0639\u062f \u0642\u064a\u0627\u0645 \u0627\u0644\u0623\u062f\u0644\u0629 \u0627\u0644\u0628\u064a\u0646\u0629 \u0625\u0644\u0627 \u0623\u0646 \u064a\u0623\u062a\u064a\u0647\u0645 \u0627\u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644 \u0639\u0644\u0649 \u0627\u0644\u0648\u062c\u0647 \u0627\u0644\u0644\u0627\u0626\u0642 \u0628\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0641\u064a \u0638\u064f\u0644\u064e\u0644 \u0645\u0646 \u0627\u0644\u0633\u062d\u0627\u0628 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629; \u0644\u064a\u0641\u0635\u0644 \u0628\u064a\u0646\u0647\u0645 \u0628\u0627\u0644\u0642\u0636\u0627\u0621 \u0627\u0644\u0639\u0627\u062f\u0644\u060c \u0648\u0623\u0646 \u062a\u0623\u062a\u064a \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629\u060c \u0648\u062d\u064a\u0646\u0626\u0630 \u064a\u0642\u0636\u064a \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0641\u064a\u0647\u0645 \u0642\u0636\u0627\u0621\u0647. \u0648\u0625\u0644\u064a\u0647 \u0648\u062d\u062f\u0647 \u062a\u0631\u062c\u0639 \u0623\u0645\u0648\u0631 \u0627\u0644\u062e\u0644\u0627\u0626\u0642 \u062c\u0645\u064a\u0639\u0647\u0627.","2:211":"\u0633\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0627\u0644\u0645\u0639\u0627\u0646\u062f\u064a\u0646 \u0644\u0643: \u0643\u0645 \u0623\u0639\u0637\u064a\u0646\u0627\u0647\u0645 \u0645\u0646 \u0622\u064a\u0627\u062a \u0648\u0627\u0636\u062d\u0627\u062a \u0641\u064a \u0643\u062a\u0628\u0647\u0645 \u062a\u0647\u062f\u064a\u0647\u0645 \u0625\u0644\u0649 \u0627\u0644\u062d\u0642\u060c \u0641\u0643\u0641\u0631\u0648\u0627 \u0628\u0647\u0627 \u0643\u0644\u0647\u0627\u060c \u0648\u0623\u0639\u0631\u0636\u0648\u0627 \u0639\u0646\u0647\u0627\u060c \u0648\u062d\u064e\u0631\u0651\u064e\u0641\u0648\u0647\u0627 \u0639\u0646 \u0645\u0648\u0627\u0636\u0639\u0647\u0627. \u0648\u0645\u0646 \u064a\u0628\u062f\u0644 \u0646\u0639\u0645\u0629 \u0627\u0644\u0644\u0647 -\u0648\u0647\u064a \u062f\u064a\u0646\u0647- \u0648\u064a\u0643\u0641\u0631 \u0628\u0647\u0627 \u0645\u0646 \u0628\u0639\u062f \u0645\u0639\u0631\u0641\u062a\u0647\u0627\u060c \u0648\u0642\u064a\u0627\u0645 \u0627\u0644\u062d\u062c\u0629 \u0639\u0644\u064a\u0647 \u0628\u0647\u0627\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0634\u062f\u064a\u062f \u0627\u0644\u0639\u0642\u0627\u0628 \u0644\u0647.","2:212":"\u062d\u064f\u0633\u0651\u0650\u0646 \u0644\u0644\u0630\u064a\u0646 \u062c\u062d\u062f\u0648\u0627 \u0648\u062d\u062f\u0627\u0646\u064a\u0629 \u0627\u0644\u0644\u0647 \u0627\u0644\u062d\u064a\u0627\u0629\u064f \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0645\u0627 \u0641\u064a\u0647\u0627 \u0645\u0646 \u0627\u0644\u0634\u0647\u0648\u0627\u062a \u0648\u0627\u0644\u0645\u0644\u0630\u0627\u062a\u060c \u0648\u0647\u0645 \u064a\u0633\u062a\u0647\u0632\u0626\u0648\u0646 \u0628\u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646. \u0648\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u064a\u062e\u0634\u0648\u0646 \u0631\u0628\u0647\u0645 \u0641\u0648\u0642 \u062c\u0645\u064a\u0639 \u0627\u0644\u0643\u0641\u0627\u0631 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629; \u062d\u064a\u062b \u064a\u062f\u062e\u0644\u0647\u0645 \u0627\u0644\u0644\u0647 \u0623\u0639\u0644\u0649 \u062f\u0631\u062c\u0627\u062a \u0627\u0644\u062c\u0646\u0629\u060c \u0648\u064a\u0646\u0632\u0644 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0623\u0633\u0641\u0644 \u062f\u0631\u0643\u0627\u062a \u0627\u0644\u0646\u0627\u0631. \u0648\u0627\u0644\u0644\u0647 \u064a\u0631\u0632\u0642 \u0645\u064e\u0646 \u064a\u0634\u0627\u0621 \u0645\u0650\u0646 \u062e\u0644\u0642\u0647 \u0628\u063a\u064a\u0631 \u062d\u0633\u0627\u0628.","2:213":"\u0643\u0627\u0646 \u0627\u0644\u0646\u0627\u0633 \u062c\u0645\u0627\u0639\u0629 \u0648\u0627\u062d\u062f\u0629\u060c \u0645\u062a\u0641\u0642\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647 \u062b\u0645 \u0627\u062e\u062a\u0644\u0641\u0648\u0627 \u0641\u064a \u062f\u064a\u0646\u0647\u0645\u060c \u0641\u0628\u0639\u062b \u0627\u0644\u0644\u0647 \u0627\u0644\u0646\u0628\u064a\u064a\u0646 \u062f\u0639\u0627\u0629 \u0644\u062f\u064a\u0646 \u0627\u0644\u0644\u0647\u060c \u0645\u0628\u0634\u0631\u064a\u0646 \u0645\u064e\u0646 \u0623\u0637\u0627\u0639 \u0627\u0644\u0644\u0647 \u0628\u0627\u0644\u062c\u0646\u0629\u060c \u0648\u0645\u062d\u0630\u0631\u064a\u0646 \u0645\u0646 \u0643\u0641\u0631 \u0628\u0647 \u0648\u0639\u0635\u0627\u0647 \u0627\u0644\u0646\u0627\u0631\u060c \u0648\u0623\u0646\u0632\u0644 \u0645\u0639\u0647\u0645 \u0627\u0644\u0643\u062a\u0628 \u0627\u0644\u0633\u0645\u0627\u0648\u064a\u0629 \u0628\u0627\u0644\u062d\u0642 \u0627\u0644\u0630\u064a \u0627\u0634\u062a\u0645\u0644\u062a \u0639\u0644\u064a\u0647; \u0644\u064a\u062d\u0643\u0645\u0648\u0627 \u0628\u0645\u0627 \u0641\u064a\u0647\u0627 \u0628\u064a\u0646 \u0627\u0644\u0646\u0627\u0633 \u0641\u064a\u0645\u0627 \u0627\u062e\u062a\u0644\u0641\u0648\u0627 \u0641\u064a\u0647\u060c \u0648\u0645\u0627 \u0627\u062e\u0652\u062a\u064e\u0644\u064e\u0641 \u0641\u064a \u0623\u0645\u0631 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u0643\u062a\u0627\u0628\u0647 \u0638\u0644\u0645\u064b\u0627 \u0648\u062d\u0633\u062f\u064b\u0627 \u0625\u0644\u0627 \u0627\u0644\u0630\u064a\u0646 \u0623\u0639\u0637\u0627\u0647\u0645 \u0627\u0644\u0644\u0647 \u0627\u0644\u062a\u0648\u0631\u0627\u0629\u060c \u0648\u0639\u0631\u0641\u0648\u0627 \u0645\u0627 \u0641\u064a\u0647\u0627 \u0645\u0646 \u0627\u0644\u062d\u062c\u062c \u0648\u0627\u0644\u0623\u062d\u0643\u0627\u0645\u060c \u0641\u0648\u0641\u0651\u064e\u0642 \u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0628\u0641\u0636\u0644\u0647 \u0625\u0644\u0649 \u062a\u0645\u064a\u064a\u0632 \u0627\u0644\u062d\u0642 \u0645\u0646 \u0627\u0644\u0628\u0627\u0637\u0644\u060c \u0648\u0645\u0639\u0631\u0641\u0629 \u0645\u0627 \u0627\u062e\u062a\u0644\u0641\u0648\u0627 \u0641\u064a\u0647. \u0648\u0627\u0644\u0644\u0647 \u064a\u0648\u0641\u0651\u0650\u0642 \u0645\u0646 \u064a\u0634\u0627\u0621 \u0645\u0646 \u0639\u0628\u0627\u062f\u0647 \u0625\u0644\u0649 \u0637\u0631\u064a\u0642 \u0645\u0633\u062a\u0642\u064a\u0645.","2:214":"\u0628\u0644 \u0623\u0638\u0646\u0646\u062a\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0623\u0646 \u062a\u062f\u062e\u0644\u0648\u0627 \u0627\u0644\u062c\u0646\u0629\u060c \u0648\u0644\u0645\u0651\u064e\u0627 \u064a\u0635\u0628\u0643\u0645 \u0645\u0646 \u0627\u0644\u0627\u0628\u062a\u0644\u0627\u0621 \u0645\u062b\u0644 \u0645\u0627 \u0623\u0635\u0627\u0628 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0645\u0636\u0648\u0627 \u0645\u0646 \u0642\u0628\u0644\u0643\u0645: \u0645\u0646 \u0627\u0644\u0641\u0642\u0631 \u0648\u0627\u0644\u0623\u0645\u0631\u0627\u0636 \u0648\u0627\u0644\u062e\u0648\u0641 \u0648\u0627\u0644\u0631\u0639\u0628\u060c \u0648\u0632\u064f\u0644\u0632\u0644\u0648\u0627 \u0628\u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0645\u062e\u0627\u0648\u0641\u060c \u062d\u062a\u0649 \u0642\u0627\u0644 \u0631\u0633\u0648\u0644\u0647\u0645 \u0648\u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0645\u0639\u0647 -\u0639\u0644\u0649 \u0633\u0628\u064a\u0644 \u0627\u0644\u0627\u0633\u062a\u0639\u062c\u0627\u0644 \u0644\u0644\u0646\u0635\u0631 \u0645\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649-: \u0645\u062a\u0649 \u0646\u0635\u0631 \u0627\u0644\u0644\u0647\u061f \u0623\u0644\u0627 \u0625\u0646 \u0646\u0635\u0631 \u0627\u0644\u0644\u0647 \u0642\u0631\u064a\u0628 \u0645\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646.","2:215":"\u064a\u0633\u0623\u0644\u0643 \u0623\u0635\u062d\u0627\u0628\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0623\u064a \u0634\u064a\u0621 \u064a\u0646\u0641\u0642\u0648\u0646 \u0645\u0646 \u0623\u0635\u0646\u0627\u0641 \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u062a\u0642\u0631\u0628\u064b\u0627 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0639\u0644\u0649 \u0645\u064e\u0646 \u064a\u0646\u0641\u0642\u0648\u0646\u061f \u0642\u0644 \u0644\u0647\u0645: \u0623\u0646\u0641\u0642\u0648\u0627 \u0623\u064a\u0651\u064e \u062e\u064a\u0631 \u064a\u062a\u064a\u0633\u0631 \u0644\u0643\u0645 \u0645\u0646 \u0623\u0635\u0646\u0627\u0641 \u0627\u0644\u0645\u0627\u0644 \u0627\u0644\u062d\u0644\u0627\u0644 \u0627\u0644\u0637\u064a\u0628\u060c \u0648\u0627\u062c\u0639\u0644\u0648\u0627 \u0646\u0641\u0642\u062a\u0643\u0645 \u0644\u0644\u0648\u0627\u0644\u062f\u064a\u0646\u060c \u0648\u0627\u0644\u0623\u0642\u0631\u0628\u064a\u0646 \u0645\u0646 \u0623\u0647\u0644\u0643\u0645 \u0648\u0630\u0648\u064a \u0623\u0631\u062d\u0627\u0645\u0643\u0645\u060c \u0648\u0627\u0644\u064a\u062a\u0627\u0645\u0649 \u0627\u0644\u0630\u064a\u0646 \u0645\u0627\u062a \u0622\u0628\u0627\u0624\u0647\u0645 \u0648\u0647\u0645 \u062f\u0648\u0646 \u0633\u0646 \u0627\u0644\u0628\u0644\u0648\u063a\u060c \u0648\u0627\u0644\u0645\u062d\u062a\u0627\u062c\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0644\u0627 \u064a\u0645\u0644\u0643\u0648\u0646 \u0645\u0627 \u064a\u0643\u0641\u064a\u0647\u0645 \u0648\u064a\u0633\u062f \u062d\u0627\u062c\u062a\u0647\u0645\u060c \u0648\u0627\u0644\u0645\u0633\u0627\u0641\u0631 \u0627\u0644\u0645\u062d\u062a\u0627\u062c \u0627\u0644\u0630\u064a \u0628\u064e\u0639\u064f\u062f\u064e \u0639\u0646 \u0623\u0647\u0644\u0647 \u0648\u0645\u0627\u0644\u0647. \u0648\u0645\u0627 \u062a\u0641\u0639\u0644\u0648\u0627 \u0645\u0646 \u062e\u064a\u0631 \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0628\u0647 \u0639\u0644\u064a\u0645.","2:216":"\u0641\u0631\u0636 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0642\u062a\u0627\u0644 \u0627\u0644\u0643\u0641\u0627\u0631\u060c \u0648\u0627\u0644\u0642\u062a\u0627\u0644 \u0645\u0643\u0631\u0648\u0647 \u0644\u0643\u0645 \u0645\u0646 \u062c\u0647\u0629 \u0627\u0644\u0637\u0628\u0639; \u0644\u0645\u0634\u0642\u062a\u0647 \u0648\u0643\u062b\u0631\u0629 \u0645\u062e\u0627\u0637\u0631\u0647\u060c \u0648\u0642\u062f \u062a\u0643\u0631\u0647\u0648\u0646 \u0634\u064a\u0626\u064b\u0627 \u0648\u0647\u0648 \u0641\u064a \u062d\u0642\u064a\u0642\u062a\u0647 \u062e\u064a\u0631 \u0644\u0643\u0645\u060c \u0648\u0642\u062f \u062a\u062d\u0628\u0648\u0646 \u0634\u064a\u0626\u064b\u0627 \u0644\u0645\u0627 \u0641\u064a\u0647 \u0645\u0646 \u0627\u0644\u0631\u0627\u062d\u0629 \u0623\u0648 \u0627\u0644\u0644\u0630\u0629 \u0627\u0644\u0639\u0627\u062c\u0644\u0629\u060c \u0648\u0647\u0648 \u0634\u0631 \u0644\u0643\u0645. \u0648\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u064a\u0639\u0644\u0645 \u0645\u0627 \u0647\u0648 \u062e\u064a\u0631 \u0644\u0643\u0645\u060c \u0648\u0623\u0646\u062a\u0645 \u0644\u0627 \u062a\u0639\u0644\u0645\u0648\u0646 \u0630\u0644\u0643. \u0641\u0628\u0627\u062f\u0631\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u062c\u0647\u0627\u062f \u0641\u064a \u0633\u0628\u064a\u0644\u0647.","2:217":"\u064a\u0633\u0623\u0644\u0643 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0639\u0646 \u0627\u0644\u0634\u0647\u0631 \u0627\u0644\u062d\u0631\u0627\u0645: \u0647\u0644 \u064a\u062d\u0644 \u0641\u064a\u0647 \u0627\u0644\u0642\u062a\u0627\u0644\u061f \u0642\u0644 \u0644\u0647\u0645: \u0627\u0644\u0642\u062a\u0627\u0644 \u0641\u064a \u0627\u0644\u0634\u0647\u0631 \u0627\u0644\u062d\u0631\u0627\u0645 \u0639\u0638\u064a\u0645 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0627\u0633\u062a\u062d\u0644\u0627\u0644\u0647 \u0648\u0633\u0641\u0643 \u0627\u0644\u062f\u0645\u0627\u0621 \u0641\u064a\u0647\u060c \u0648\u0645\u064e\u0646\u0652\u0639\u0643\u0645 \u0627\u0644\u0646\u0627\u0633 \u0645\u0646 \u062f\u062e\u0648\u0644 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0628\u0627\u0644\u062a\u0639\u0630\u064a\u0628 \u0648\u0627\u0644\u062a\u062e\u0648\u064a\u0641\u060c \u0648\u062c\u062d\u0648\u062f\u0643\u0645 \u0628\u0627\u0644\u0644\u0647 \u0648\u0628\u0631\u0633\u0648\u0644\u0647 \u0648\u0628\u062f\u064a\u0646\u0647\u060c \u0648\u0645\u064e\u0646\u0652\u0639 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0645\u0646 \u062f\u062e\u0648\u0644 \u0627\u0644\u0645\u0633\u062c\u062f \u0627\u0644\u062d\u0631\u0627\u0645\u060c \u0648\u0625\u062e\u0631\u0627\u062c \u0627\u0644\u0646\u0628\u064a \u0648\u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0645\u0646\u0647 \u0648\u0647\u0645 \u0623\u0647\u0644\u0647 \u0648\u0623\u0648\u0644\u064a\u0627\u0624\u0647\u060c \u0630\u0644\u0643 \u0623\u0643\u0628\u0631 \u0630\u0646\u0628\u064b\u0627\u060c \u0648\u0623\u0639\u0638\u0645 \u062c\u0631\u0645\u064b\u0627 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u0642\u062a\u0627\u0644 \u0641\u064a \u0627\u0644\u0634\u0647\u0631 \u0627\u0644\u062d\u0631\u0627\u0645. \u0648\u0627\u0644\u0634\u0631\u0643 \u0627\u0644\u0630\u064a \u0623\u0646\u062a\u0645 \u0641\u064a\u0647 \u0623\u0643\u0628\u0631 \u0648\u0623\u0634\u062f \u0645\u0646 \u0627\u0644\u0642\u062a\u0644 \u0641\u064a \u0627\u0644\u0634\u0647\u0631 \u0627\u0644\u062d\u0631\u0627\u0645. \u0648\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0643\u0641\u0627\u0631 \u0644\u0645 \u064a\u0631\u062a\u062f\u0639\u0648\u0627 \u0639\u0646 \u062c\u0631\u0627\u0626\u0645\u0647\u0645\u060c \u0628\u0644 \u0647\u0645 \u0645\u0633\u062a\u0645\u0631\u0648\u0646 \u0639\u0644\u064a\u0647\u0627\u060c \u0648\u0644\u0627 \u064a\u0632\u0627\u0644\u0648\u0646 \u064a\u0642\u0627\u062a\u0644\u0648\u0646\u0643\u0645 \u062d\u062a\u0649 \u064a\u0631\u062f\u0648\u0643\u0645 \u0639\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0625\u0644\u0649 \u0627\u0644\u0643\u0641\u0631 \u0625\u0646 \u0627\u0633\u062a\u0637\u0627\u0639\u0648\u0627 \u062a\u062d\u0642\u064a\u0642 \u0630\u0644\u0643. \u0648\u0645\u0646 \u064a\u0637\u0639\u0647\u0645 \u0645\u0646\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646- \u0648\u064a\u0631\u062a\u062f\u062f \u0639\u0646 \u062f\u064a\u0646\u0647 \u0641\u064a\u0645\u062a \u0639\u0644\u0649 \u0627\u0644\u0643\u0641\u0631\u060c \u0641\u0642\u062f \u0630\u0647\u0628 \u0639\u0645\u0644\u0647 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u0635\u0627\u0631 \u0645\u0646 \u0627\u0644\u0645\u0644\u0627\u0632\u0645\u064a\u0646 \u0644\u0646\u0627\u0631 \u062c\u0647\u0646\u0645 \u0644\u0627 \u064a\u062e\u0631\u062c \u0645\u0646\u0647\u0627 \u0623\u0628\u062f\u064b\u0627.","2:218":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u0635\u064e\u062f\u0651\u064e\u0642\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647 \u0648\u0627\u0644\u0630\u064a\u0646 \u062a\u0631\u0643\u0648\u0627 \u062f\u064a\u0627\u0631\u0647\u0645\u060c \u0648\u062c\u0627\u0647\u062f\u0648\u0627 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647\u060c \u0623\u0648\u0644\u0626\u0643 \u064a\u0637\u0645\u0639\u0648\u0646 \u0641\u064a \u0641\u0636\u0644 \u0627\u0644\u0644\u0647 \u0648\u062b\u0648\u0627\u0628\u0647. \u0648\u0627\u0644\u0644\u0647 \u063a\u0641\u0648\u0631 \u0644\u0630\u0646\u0648\u0628 \u0639\u0628\u0627\u062f\u0647 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0631\u062d\u064a\u0645 \u0628\u0647\u0645 \u0631\u062d\u0645\u0629 \u0648\u0627\u0633\u0639\u0629.","2:219":"\u064a\u0633\u0623\u0644\u0643 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0639\u0646 \u062d\u0643\u0645 \u062a\u0639\u0627\u0637\u064a \u0627\u0644\u062e\u0645\u0631 \u0634\u0631\u0628\u064b\u0627 \u0648\u0628\u064a\u0639\u064b\u0627 \u0648\u0634\u0631\u0627\u0621\u064b\u060c \u0648\u0627\u0644\u062e\u0645\u0631 \u0643\u0644 \u0645\u0633\u0643\u0631 \u062e\u0627\u0645\u0631 \u0627\u0644\u0639\u0642\u0644 \u0648\u063a\u0637\u0627\u0647 \u0645\u0634\u0631\u0648\u0628\u064b\u0627 \u0643\u0627\u0646 \u0623\u0648 \u0645\u0623\u0643\u0648\u0644\u0627 \u0648\u064a\u0633\u0623\u0644\u0648\u0646\u0643 \u0639\u0646 \u062d\u0643\u0645 \u0627\u0644\u0642\u0645\u0627\u0631 -\u0648\u0647\u0648 \u0623\u064e\u062e\u0652\u0630\u064f \u0627\u0644\u0645\u0627\u0644 \u0623\u0648 \u0625\u0639\u0637\u0627\u0624\u0647 \u0628\u0627\u0644\u0645\u0642\u0627\u0645\u0631\u0629 \u0648\u0647\u064a \u0627\u0644\u0645\u063a\u0627\u0644\u0628\u0627\u062a \u0627\u0644\u062a\u064a \u0641\u064a\u0647\u0627 \u0639\u0648\u0636 \u0645\u0646 \u0627\u0644\u0637\u0631\u0641\u064a\u0646-\u060c \u0642\u0644 \u0644\u0647\u0645: \u0641\u064a \u0630\u0644\u0643 \u0623\u0636\u0631\u0627\u0631 \u0648\u0645\u0641\u0627\u0633\u062f \u0643\u062b\u064a\u0631\u0629 \u0641\u064a \u0627\u0644\u062f\u064a\u0646 \u0648\u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0627\u0644\u0639\u0642\u0648\u0644 \u0648\u0627\u0644\u0623\u0645\u0648\u0627\u0644\u060c \u0648\u0641\u064a\u0647\u0645\u0627 \u0645\u0646\u0627\u0641\u0639 \u0644\u0644\u0646\u0627\u0633 \u0645\u0646 \u062c\u0647\u0629 \u0643\u0633\u0628 \u0627\u0644\u0623\u0645\u0648\u0627\u0644 \u0648\u063a\u064a\u0631\u0647\u0627\u060c \u0648\u0625\u062b\u0645\u0647\u0645\u0627 \u0623\u0643\u0628\u0631 \u0645\u0646 \u0646\u0641\u0639\u0647\u0645\u0627; \u0625\u0630 \u064a\u0635\u062f\u0651\u064e\u0627\u0646 \u0639\u0646 \u0630\u0643\u0631 \u0627\u0644\u0644\u0647 \u0648\u0639\u0646 \u0627\u0644\u0635\u0644\u0627\u0629\u060c \u0648\u064a\u0648\u0642\u0639\u0627\u0646 \u0627\u0644\u0639\u062f\u0627\u0648\u0629 \u0648\u0627\u0644\u0628\u063a\u0636\u0627\u0621 \u0628\u064a\u0646 \u0627\u0644\u0646\u0627\u0633\u060c \u0648\u064a\u062a\u0644\u0641\u0627\u0646 \u0627\u0644\u0645\u0627\u0644. \u0648\u0643\u0627\u0646 \u0647\u0630\u0627 \u062a\u0645\u0647\u064a\u062f\u064b\u0627 \u0644\u062a\u062d\u0631\u064a\u0645\u0647\u0645\u0627. \u0648\u064a\u0633\u0623\u0644\u0648\u0646\u0643 \u0639\u0646 \u0627\u0644\u0642\u064e\u062f\u0652\u0631 \u0627\u0644\u0630\u064a \u064a\u0646\u0641\u0642\u0648\u0646\u0647 \u0645\u0646 \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u062a\u0628\u0631\u0639\u064b\u0627 \u0648\u0635\u062f\u0642\u0629\u060c \u0642\u0644 \u0644\u0647\u0645: \u0623\u0646\u0641\u0642\u0648\u0627 \u0627\u0644\u0642\u064e\u062f\u0652\u0631 \u0627\u0644\u0630\u064a \u064a\u0632\u064a\u062f \u0639\u0644\u0649 \u062d\u0627\u062c\u062a\u0643\u0645. \u0645\u062b\u0644 \u0630\u0644\u0643 \u0627\u0644\u0628\u064a\u0627\u0646 \u0627\u0644\u0648\u0627\u0636\u062d \u064a\u0628\u064a\u0651\u0650\u0646 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0627\u0644\u0622\u064a\u0627\u062a \u0648\u0623\u062d\u0643\u0627\u0645 \u0627\u0644\u0634\u0631\u064a\u0639\u0629; \u0644\u0643\u064a \u062a\u062a\u0641\u0643\u0631\u0648\u0627 \u0641\u064a\u0645\u0627 \u064a\u0646\u0641\u0639\u0643\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629.","2:220":"\u0648\u064a\u0633\u0623\u0644\u0648\u0646\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0639\u0646 \u0627\u0644\u064a\u062a\u0627\u0645\u0649 \u0627\u0644\u0630\u064a\u0646 \u0645\u0627\u062a \u0622\u0628\u0627\u0624\u0647\u0645 \u0648\u0647\u0645 \u062f\u0648\u0646 \u0633\u0646 \u0627\u0644\u0628\u0644\u0648\u063a \u0643\u064a\u0641 \u064a\u062a\u0635\u0631\u0641\u0648\u0646 \u0645\u0639\u0647\u0645 \u0641\u064a \u0645\u0639\u0627\u0634\u0647\u0645 \u0648\u0623\u0645\u0648\u0627\u0644\u0647\u0645\u061f \u0642\u0644 \u0644\u0647\u0645: \u0625\u0635\u0644\u0627\u062d\u0643\u0645 \u0644\u0647\u0645 \u062e\u064a\u0631\u060c \u0641\u0627\u0641\u0639\u0644\u0648\u0627 \u0627\u0644\u0623\u0646\u0641\u0639 \u0644\u0647\u0645 \u062f\u0627\u0626\u0645\u064b\u0627\u060c \u0648\u0625\u0646 \u062a\u062e\u0627\u0644\u0637\u0648\u0647\u0645 \u0641\u064a \u0633\u0627\u0626\u0631 \u0634\u0624\u0648\u0646 \u0627\u0644\u0645\u0639\u0627\u0634 \u0641\u0647\u0645 \u0625\u062e\u0648\u0627\u0646\u0643\u0645 \u0641\u064a \u0627\u0644\u062f\u064a\u0646. \u0648\u0639\u0644\u0649 \u0627\u0644\u0623\u062e \u0623\u0646 \u064a\u0631\u0639\u0649 \u0645\u0635\u0644\u062d\u0629 \u0623\u062e\u064a\u0647. \u0648\u0627\u0644\u0644\u0647 \u064a\u0639\u0644\u0645 \u0627\u0644\u0645\u0636\u064a\u0639 \u0644\u0623\u0645\u0648\u0627\u0644 \u0627\u0644\u064a\u062a\u0627\u0645\u0649 \u0645\u0646 \u0627\u0644\u062d\u0631\u064a\u0635 \u0639\u0644\u0649 \u0625\u0635\u0644\u0627\u062d\u0647\u0627. \u0648\u0644\u0648 \u0634\u0627\u0621 \u0627\u0644\u0644\u0647 \u0644\u0636\u064a\u0651\u064e\u0642 \u0648\u0634\u0642\u0651\u064e \u0639\u0644\u064a\u0643\u0645 \u0628\u062a\u062d\u0631\u064a\u0645 \u0627\u0644\u062e\u0627\u0644\u0637\u0629. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0639\u0632\u064a\u0632 \u0641\u064a \u0645\u0644\u0643\u0647\u060c \u062d\u0643\u064a\u0645 \u0641\u064a \u062e\u0644\u0642\u0647 \u0648\u062a\u062f\u0628\u064a\u0631\u0647 \u0648\u062a\u0634\u0631\u064a\u0639\u0647.","2:221":"\u0648\u0644\u0627 \u062a\u062a\u0632\u0648\u062c\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646- \u0627\u0644\u0645\u0634\u0631\u0643\u0627\u062a \u0639\u0627\u0628\u062f\u0627\u062a \u0627\u0644\u0623\u0648\u062b\u0627\u0646\u060c \u062d\u062a\u0649 \u064a\u062f\u062e\u0644\u0646 \u0641\u064a \u0627\u0644\u0625\u0633\u0644\u0627\u0645. \u0648\u0627\u0639\u0644\u0645\u0648\u0627 \u0623\u0646\u0651\u064e \u0627\u0645\u0631\u0623\u0629 \u0645\u0645\u0644\u0648\u0643\u0629\u064b \u0644\u0627 \u0645\u0627\u0644 \u0644\u0647\u0627 \u0648\u0644\u0627 \u062d\u0633\u0628\u060c \u0645\u0624\u0645\u0646\u0629\u064b \u0628\u0627\u0644\u0644\u0647\u060c \u062e\u064a\u0631 \u0645\u0646 \u0627\u0645\u0631\u0623\u0629 \u0645\u0634\u0631\u0643\u0629\u060c \u0648\u0625\u0646 \u0623\u0639\u062c\u0628\u062a\u0643\u0645 \u0627\u0644\u0645\u0634\u0631\u0643\u0629 \u0627\u0644\u062d\u0631\u0629. \u0648\u0644\u0627 \u062a\u064f\u0632\u064e\u0648\u0651\u0650\u062c\u0648\u0627 \u0646\u0633\u0627\u0621\u0643\u0645 \u0627\u0644\u0645\u0624\u0645\u0646\u0627\u062a -\u0625\u0645\u0627\u0621 \u0623\u0648 \u062d\u0631\u0627\u0626\u0631- \u0644\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u062d\u062a\u0649 \u064a\u0624\u0645\u0646\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647. \u0648\u0627\u0639\u0644\u0645\u0648\u0627 \u0623\u0646 \u0639\u0628\u062f\u064b\u0627 \u0645\u0624\u0645\u0646\u064b\u0627 \u0645\u0639 \u0641\u0642\u0631\u0647\u060c \u062e\u064a\u0631 \u0645\u0646 \u0645\u0634\u0631\u0643. \u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0645\u062a\u0635\u0641\u0648\u0646 \u0628\u0627\u0644\u0634\u0631\u0643 \u0631\u062c\u0627\u0644\u0627 \u0648\u0646\u0633\u0627\u0621\u064b \u064a\u062f\u0639\u0648\u0646 \u0643\u0644 \u0645\u064e\u0646 \u064a\u0639\u0627\u0634\u0631\u0647\u0645 \u0625\u0644\u0649 \u0645\u0627 \u064a\u0624\u062f\u064a \u0628\u0647 \u0625\u0644\u0649 \u0627\u0644\u0646\u0627\u0631\u060c \u0648\u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u064a\u062f\u0639\u0648 \u0639\u0628\u0627\u062f\u0647 \u0625\u0644\u0649 \u062f\u064a\u0646\u0647 \u0627\u0644\u062d\u0642 \u0627\u0644\u0645\u0624\u062f\u064a \u0628\u0647\u0645 \u0625\u0644\u0649 \u0627\u0644\u062c\u0646\u0629 \u0648\u0645\u063a\u0641\u0631\u0629 \u0630\u0646\u0648\u0628\u0647\u0645 \u0628\u0625\u0630\u0646\u0647\u060c \u0648\u064a\u0628\u064a\u0646 \u0622\u064a\u0627\u062a\u0647 \u0648\u0623\u062d\u0643\u0627\u0645\u0647 \u0644\u0644\u0646\u0627\u0633; \u0644\u0643\u064a \u064a\u062a\u0630\u0643\u0631\u0648\u0627\u060c \u0641\u064a\u0639\u062a\u0628\u0631\u0648\u0627.","2:222":"\u0648\u064a\u0633\u0623\u0644\u0648\u0646\u0643 \u0639\u0646 \u0627\u0644\u062d\u064a\u0636 -\u0648\u0647\u0648 \u0627\u0644\u062f\u0645 \u0627\u0644\u0630\u064a \u064a\u0633\u064a\u0644 \u0645\u0646 \u0623\u0631\u062d\u0627\u0645 \u0627\u0644\u0646\u0633\u0627\u0621 \u062c\u0650\u0628\u0650\u0644\u0651\u064e\u0629 \u0641\u064a \u0623\u0648\u0642\u0627\u062a \u0645\u062e\u0635\u0648\u0635\u0629-\u060c \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a-: \u0647\u0648 \u0623\u0630\u0649 \u0645\u0633\u062a\u0642\u0630\u0631 \u064a\u0636\u0631 \u0645\u0646 \u064a\u064e\u0642\u0652\u0631\u064e\u0628\u064f\u0647\u060c \u0641\u0627\u062c\u062a\u0646\u0628\u0648\u0627 \u062c\u0645\u0627\u0639 \u0627\u0644\u0646\u0633\u0627\u0621 \u0645\u062f\u0629 \u0627\u0644\u062d\u064a\u0636 \u062d\u062a\u0649 \u064a\u0646\u0642\u0637\u0639 \u0627\u0644\u062f\u0645\u060c \u0641\u0625\u0630\u0627 \u0627\u0646\u0642\u0637\u0639 \u0627\u0644\u062f\u0645\u060c \u0648\u0627\u063a\u062a\u0633\u0644\u0646\u060c \u0641\u062c\u0627\u0645\u0639\u0648\u0647\u0646 \u0641\u064a \u0627\u0644\u0645\u0648\u0636\u0639 \u0627\u0644\u0630\u064a \u0623\u062d\u0644\u0651\u064e\u0647 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645\u060c \u0648\u0647\u0648 \u0627\u0644\u0642\u0628\u0644 \u0644\u0627 \u0627\u0644\u062f\u0628\u0631. \u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u062d\u0628 \u0639\u0628\u0627\u062f\u0647 \u0627\u0644\u0645\u0643\u062b\u0631\u064a\u0646 \u0645\u0646 \u0627\u0644\u0627\u0633\u062a\u063a\u0641\u0627\u0631 \u0648\u0627\u0644\u062a\u0648\u0628\u0629\u060c \u0648\u064a\u062d\u0628 \u0639\u0628\u0627\u062f\u0647 \u0627\u0644\u0645\u062a\u0637\u0647\u0631\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u0628\u062a\u0639\u062f\u0648\u0646 \u0639\u0646 \u0627\u0644\u0641\u0648\u0627\u062d\u0634 \u0648\u0627\u0644\u0623\u0642\u0630\u0627\u0631.","2:223":"\u0646\u0633\u0627\u0624\u0643\u0645 \u0645\u0648\u0636\u0639 \u0632\u0631\u0639 \u0644\u0643\u0645\u060c \u062a\u0636\u0639\u0648\u0646 \u0627\u0644\u0646\u0637\u0641\u0629 \u0641\u064a \u0623\u0631\u062d\u0627\u0645\u0647\u0646\u060c \u0641\u064e\u064a\u064e\u062e\u0652\u0631\u062c \u0645\u0646\u0647\u0627 \u0627\u0644\u0623\u0648\u0644\u0627\u062f \u0628\u0645\u0634\u064a\u0626\u0629 \u0627\u0644\u0644\u0647\u060c \u0641\u062c\u0627\u0645\u0639\u0648\u0647\u0646 \u0641\u064a \u0645\u062d\u0644 \u0627\u0644\u062c\u0645\u0627\u0639 \u0641\u0642\u0637\u060c \u0648\u0647\u0648 \u0627\u0644\u0642\u0628\u0644 \u0628\u0623\u064a \u0643\u064a\u0641\u064a\u0629 \u0634\u0626\u062a\u0645\u060c \u0648\u0642\u064e\u062f\u0651\u0650\u0645\u0648\u0627 \u0644\u0623\u0646\u0641\u0633\u0643\u0645 \u0623\u0639\u0645\u0627\u0644\u0627 \u0635\u0627\u0644\u062d\u0629 \u0628\u0645\u0631\u0627\u0639\u0627\u0629 \u0623\u0648\u0627\u0645\u0631 \u0627\u0644\u0644\u0647\u060c \u0648\u062e\u0627\u0641\u0648\u0627 \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u0639\u0644\u0645\u0648\u0627 \u0623\u0646\u0643\u0645 \u0645\u0644\u0627\u0642\u0648\u0647 \u0644\u0644\u062d\u0633\u0627\u0628 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629. \u0648\u0628\u0634\u0651\u0650\u0631 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0628\u0645\u0627 \u064a\u0641\u0631\u062d\u0647\u0645 \u0648\u064a\u0633\u0631\u0651\u064f\u0647\u0645 \u0645\u0646 \u062d\u0633\u0646 \u0627\u0644\u062c\u0632\u0627\u0621 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629.","2:224":"\u0648\u0644\u0627 \u062a\u062c\u0639\u0644\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646- \u062d\u0644\u0641\u0643\u0645 \u0628\u0627\u0644\u0644\u0647 \u0645\u0627\u0646\u0639\u064b\u0627 \u0644\u0643\u0645 \u0645\u0646 \u0627\u0644\u0628\u0631 \u0648\u0635\u0644\u0629 \u0627\u0644\u0631\u062d\u0645 \u0648\u0627\u0644\u062a\u0642\u0648\u0649 \u0648\u0627\u0644\u0625\u0635\u0644\u0627\u062d \u0628\u064a\u0646 \u0627\u0644\u0646\u0627\u0633: \u0628\u0623\u0646 \u062a\u064f\u062f\u0652\u0639\u064e\u0648\u0627 \u0625\u0644\u0649 \u0641\u0639\u0644 \u0634\u064a\u0621 \u0645\u0646\u0647\u0627\u060c \u0641\u062a\u062d\u062a\u062c\u0648\u0627 \u0628\u0623\u0646\u0643\u0645 \u0623\u0642\u0633\u0645\u062a\u0645 \u0628\u0627\u0644\u0644\u0647 \u0623\u0644\u0627 \u062a\u0641\u0639\u0644\u0648\u0647\u060c \u0628\u0644 \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0644\u0641 \u0623\u0646 \u064a\u0639\u062f\u0644 \u0639\u0646 \u062d\u0644\u0641\u0647\u060c \u0648\u064a\u0641\u0639\u0644 \u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0628\u0631\u060c \u0648\u064a\u0643\u0641\u0631 \u0639\u0646 \u064a\u0645\u064a\u0646\u0647\u060c \u0648\u0644\u0627 \u064a\u0639\u062a\u0627\u062f \u0630\u0644\u0643. \u0648\u0627\u0644\u0644\u0647 \u0633\u0645\u064a\u0639 \u0644\u0623\u0642\u0648\u0627\u0644\u0643\u0645\u060c \u0639\u0644\u064a\u0645 \u0628\u062c\u0645\u064a\u0639 \u0623\u062d\u0648\u0627\u0644\u0643\u0645.","2:225":"\u0644\u0627 \u064a\u0639\u0627\u0642\u0628\u0643\u0645 \u0627\u0644\u0644\u0647 \u0628\u0633\u0628\u0628 \u0623\u064a\u0645\u0627\u0646\u0643\u0645 \u0627\u0644\u062a\u064a \u062a\u062d\u0644\u0641\u0648\u0646\u0647\u0627 \u0628\u063a\u064a\u0631 \u0642\u0635\u062f\u060c \u0648\u0644\u0643\u0646 \u064a\u0639\u0627\u0642\u0628\u0643\u0645 \u0628\u0645\u0627 \u0642\u0635\u062f\u064e\u062a\u0652\u0647 \u0642\u0644\u0648\u0628\u0643\u0645. \u0648\u0627\u0644\u0644\u0647 \u063a\u0641\u0648\u0631 \u0644\u0645\u0646 \u062a\u0627\u0628 \u0625\u0644\u064a\u0647\u060c \u062d\u0644\u064a\u0645 \u0628\u0645\u0646 \u0639\u0635\u0627\u0647 \u062d\u064a\u062b \u0644\u0645 \u064a\u0639\u0627\u062c\u0644\u0647 \u0628\u0627\u0644\u0639\u0642\u0648\u0628\u0629.","2:226":"\u0644\u0644\u0630\u064a\u0646 \u064a\u062d\u0644\u0641\u0648\u0646 \u0628\u0627\u0644\u0644\u0647 \u0623\u0646 \u0644\u0627 \u064a\u062c\u0627\u0645\u0639\u0648\u0627 \u0646\u0633\u0627\u0621\u0647\u0645\u060c \u0627\u0646\u062a\u0638\u0627\u0631 \u0623\u0631\u0628\u0639\u0629 \u0623\u0634\u0647\u0631\u060c \u0641\u0625\u0646 \u0631\u062c\u0639\u0648\u0627 \u0642\u0628\u0644 \u0641\u0648\u0627\u062a \u0627\u0644\u0623\u0634\u0647\u0631 \u0627\u0644\u0623\u0631\u0628\u0639\u0629\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u063a\u0641\u0648\u0631 \u0644\u0645\u0627 \u0648\u0642\u0639 \u0645\u0646\u0647\u0645 \u0645\u0646 \u0627\u0644\u062d\u0644\u0641 \u0628\u0633\u0628\u0628 \u0631\u062c\u0648\u0639\u0647\u0645\u060c \u0631\u062d\u064a\u0645 \u0628\u0647\u0645.","2:227":"\u0648\u0625\u0646 \u0639\u0642\u062f\u0648\u0627 \u0639\u0632\u0645\u0647\u0645 \u0639\u0644\u0649 \u0627\u0644\u0637\u0644\u0627\u0642\u060c \u0628\u0627\u0633\u062a\u0645\u0631\u0627\u0631\u0647\u0645 \u0641\u064a \u0627\u0644\u064a\u0645\u064a\u0646\u060c \u0648\u062a\u0631\u0643 \u0627\u0644\u062c\u0645\u0627\u0639\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0633\u0645\u064a\u0639 \u0644\u0623\u0642\u0648\u0627\u0644\u0647\u0645\u060c \u0639\u0644\u064a\u0645 \u0628\u0645\u0642\u0627\u0635\u062f\u0647\u0645\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a\u0647\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643.","2:228":"\u0648\u0627\u0644\u0645\u0637\u0644\u0642\u0627\u062a \u0630\u0648\u0627\u062a \u0627\u0644\u062d\u064a\u0636\u060c \u064a\u062c\u0628 \u0623\u0646 \u064a\u0646\u062a\u0638\u0631\u0646 \u062f\u0648\u0646 \u0646\u0643\u0627\u062d \u0628\u0639\u062f \u0627\u0644\u0637\u0644\u0627\u0642 \u0645\u062f\u0629 \u062b\u0644\u0627\u062b\u0629 \u0623\u0637\u0647\u0627\u0631 \u0623\u0648 \u062b\u0644\u0627\u062b \u062d\u064a\u0636\u0627\u062a \u0639\u0644\u0649 \u0633\u0628\u064a\u0644 \u0627\u0644\u0639\u062f\u0629; \u0644\u064a\u062a\u0623\u0643\u062f\u0646 \u0645\u0646 \u0641\u0631\u0627\u063a \u0627\u0644\u0631\u062d\u0645 \u0645\u0646 \u0627\u0644\u062d\u0645\u0644. \u0648\u0644\u0627 \u064a\u062c\u0648\u0632 \u0644\u0647\u0646 \u062a\u0632\u0648\u062c \u0631\u062c\u0644 \u0622\u062e\u0631 \u0641\u064a \u0623\u062b\u0646\u0627\u0621 \u0647\u0630\u0647 \u0627\u0644\u0639\u062f\u0629 \u062d\u062a\u0649 \u062a\u0646\u062a\u0647\u064a. \u0648\u0644\u0627 \u064a\u062d\u0644 \u0644\u0647\u0646 \u0623\u0646 \u064a\u062e\u0641\u064a\u0646 \u0645\u0627 \u062e\u0644\u0642 \u0627\u0644\u0644\u0647 \u0641\u064a \u0623\u0631\u062d\u0627\u0645\u0647\u0646 \u0645\u0646 \u0627\u0644\u062d\u0645\u0644 \u0623\u0648 \u0627\u0644\u062d\u064a\u0636\u060c \u0625\u0646 \u0643\u0627\u0646\u062a \u0627\u0644\u0645\u0637\u0644\u0642\u0627\u062a \u0645\u0624\u0645\u0646\u0627\u062a \u062d\u0642\u064b\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0622\u062e\u0631. \u0648\u0623\u0632\u0648\u0627\u062c \u0627\u0644\u0645\u0637\u0644\u0642\u0627\u062a \u0623\u062d\u0642 \u0628\u0645\u0631\u0627\u062c\u0639\u062a\u0647\u0646 \u0641\u064a \u0627\u0644\u0639\u062f\u0629. \u0648\u064a\u0646\u0628\u063a\u064a \u0623\u0646 \u064a\u0643\u0648\u0646 \u0630\u0644\u0643 \u0628\u0642\u0635\u062f \u0627\u0644\u0625\u0635\u0644\u0627\u062d \u0648\u0627\u0644\u062e\u064a\u0631\u060c \u0648\u0644\u064a\u0633 \u0628\u0642\u0635\u062f \u0627\u0644\u0625\u0636\u0631\u0627\u0631 \u062a\u0639\u0630\u064a\u0628\u064b\u0627 \u0644\u0647\u0646 \u0628\u062a\u0637\u0648\u064a\u0644 \u0627\u0644\u0639\u062f\u0629. \u0648\u0644\u0644\u0646\u0633\u0627\u0621 \u062d\u0642\u0648\u0642 \u0639\u0644\u0649 \u0627\u0644\u0623\u0632\u0648\u0627\u062c\u060c \u0645\u062b\u0644 \u0627\u0644\u062a\u064a \u0639\u0644\u064a\u0647\u0646\u060c \u0639\u0644\u0649 \u0627\u0644\u0648\u062c\u0647 \u0627\u0644\u0645\u0639\u0631\u0648\u0641\u060c \u0648\u0644\u0644\u0631\u062c\u0627\u0644 \u0639\u0644\u0649 \u0627\u0644\u0646\u0633\u0627\u0621 \u0645\u0646\u0632\u0644\u0629 \u0632\u0627\u0626\u062f\u0629 \u0645\u0646 \u062d\u0633\u0646 \u0627\u0644\u0635\u062d\u0628\u0629 \u0648\u0627\u0644\u0639\u0634\u0631\u0629 \u0628\u0627\u0644\u0645\u0639\u0631\u0648\u0641 \u0648\u0627\u0644\u0642\u0650\u0648\u0627\u0645\u0629 \u0639\u0644\u0649 \u0627\u0644\u0628\u064a\u062a \u0648\u0645\u0644\u0643 \u0627\u0644\u0637\u0644\u0627\u0642. \u0648\u0627\u0644\u0644\u0647 \u0639\u0632\u064a\u0632 \u0644\u0647 \u0627\u0644\u0639\u0632\u0629 \u0627\u0644\u0642\u0627\u0647\u0631\u0629\u060c \u062d\u0643\u064a\u0645 \u064a\u0636\u0639 \u0643\u0644 \u0634\u064a\u0621 \u0641\u064a \u0645\u0648\u0636\u0639\u0647 \u0627\u0644\u0645\u0646\u0627\u0633\u0628.","2:229":"\u0627\u0644\u0637\u0644\u0627\u0642 \u0627\u0644\u0630\u064a \u062a\u062d\u0635\u0644 \u0628\u0647 \u0627\u0644\u0631\u062c\u0639\u0629 \u0645\u0631\u062a\u0627\u0646\u060c \u0648\u0627\u062d\u062f\u0629 \u0628\u0639\u062f \u0627\u0644\u0623\u062e\u0631\u0649\u060c \u0641\u062d\u0643\u0645 \u0627\u0644\u0644\u0647 \u0628\u0639\u062f \u0643\u0644 \u0637\u0644\u0642\u0629 \u0647\u0648 \u0625\u0645\u0633\u0627\u0643 \u0627\u0644\u0645\u0631\u0623\u0629 \u0628\u0627\u0644\u0645\u0639\u0631\u0648\u0641\u060c \u0648\u062d\u0633\u0646 \u0627\u0644\u0639\u0634\u0631\u0629 \u0628\u0639\u062f \u0645\u0631\u0627\u062c\u0639\u062a\u0647\u0627\u060c \u0623\u0648 \u062a\u062e\u0644\u064a\u0629 \u0633\u0628\u064a\u0644\u0647\u0627 \u0645\u0639 \u062d\u0633\u0646 \u0645\u0639\u0627\u0645\u0644\u062a\u0647\u0627 \u0628\u0623\u062f\u0627\u0621 \u062d\u0642\u0648\u0642\u0647\u0627\u060c \u0648\u0623\u0644\u0627 \u064a\u0630\u0643\u0631\u0647\u0627 \u0645\u0637\u0644\u0642\u0647\u0627 \u0628\u0633\u0648\u0621. \u0648\u0644\u0627 \u064a\u062d\u0644 \u0644\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0623\u0632\u0648\u0627\u062c- \u0623\u0646 \u062a\u0623\u062e\u0630\u0648\u0627 \u0634\u064a\u0626\u064b\u0627 \u0645\u0645\u0627 \u0623\u0639\u0637\u064a\u062a\u0645\u0648\u0647\u0646 \u0645\u0646 \u0627\u0644\u0645\u0647\u0631 \u0648\u0646\u062d\u0648\u0647\u060c \u0625\u0644\u0627 \u0623\u0646 \u064a\u062e\u0627\u0641 \u0627\u0644\u0632\u0648\u062c\u0627\u0646 \u0623\u0644\u0627 \u064a\u0642\u0648\u0645\u0627 \u0628\u0627\u0644\u062d\u0642\u0648\u0642 \u0627\u0644\u0632\u0648\u062c\u064a\u0629\u060c \u0641\u062d\u064a\u0646\u0626\u0630 \u064a\u0639\u0631\u0636\u0627\u0646 \u0623\u0645\u0631\u0647\u0645\u0627 \u0639\u0644\u0649 \u0627\u0644\u0623\u0648\u0644\u064a\u0627\u0621\u060c \u0641\u0625\u0646 \u062e\u0627\u0641 \u0627\u0644\u0623\u0648\u0644\u064a\u0627\u0621 \u0639\u062f\u0645 \u0625\u0642\u0627\u0645\u0629 \u0627\u0644\u0632\u0648\u062c\u064a\u0646 \u062d\u062f\u0648\u062f \u0627\u0644\u0644\u0647\u060c \u0641\u0644\u0627 \u062d\u0631\u062c \u0639\u0644\u0649 \u0627\u0644\u0632\u0648\u062c\u064a\u0646 \u0641\u064a\u0645\u0627 \u062a\u062f\u0641\u0639\u0647 \u0627\u0644\u0645\u0631\u0623\u0629 \u0644\u0644\u0632\u0648\u062c \u0645\u0642\u0627\u0628\u0644 \u0637\u0644\u0627\u0642\u0647\u0627. \u062a\u0644\u0643 \u0627\u0644\u0623\u062d\u0643\u0627\u0645 \u0647\u064a \u062d\u062f\u0648\u062f \u0627\u0644\u0644\u0647 \u0627\u0644\u0641\u0627\u0635\u0644\u0629 \u0628\u064a\u0646 \u0627\u0644\u062d\u0644\u0627\u0644 \u0648\u0627\u0644\u062d\u0631\u0627\u0645\u060c \u0641\u0644\u0627 \u062a\u062a\u062c\u0627\u0648\u0632\u0648\u0647\u0627\u060c \u0648\u0645\u0646 \u064a\u062a\u062c\u0627\u0648\u0632 \u062d\u062f\u0648\u062f \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0641\u0623\u0648\u0644\u0626\u0643 \u0647\u0645 \u0627\u0644\u0638\u0627\u0644\u0645\u0648\u0646 \u0623\u0646\u0641\u0633\u0647\u0645 \u0628\u062a\u0639\u0631\u064a\u0636\u0647\u0627 \u0644\u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647.","2:230":"\u0641\u0625\u0646 \u0637\u0644\u0651\u064e\u0642 \u0627\u0644\u0631\u062c\u0644 \u0632\u0648\u062c\u062a\u0647 \u0627\u0644\u0637\u0644\u0642\u0629 \u0627\u0644\u062b\u0627\u0644\u062b\u0629\u060c \u0641\u0644\u0627 \u062a\u062d\u0644\u0651\u064f \u0644\u0647 \u0625\u0644\u0627 \u0625\u0630\u0627 \u062a\u0632\u0648\u062c\u062a \u0631\u062c\u0644\u0627 \u063a\u064a\u0631\u0647 \u0632\u0648\u0627\u062c\u064b\u0627 \u0635\u062d\u064a\u062d\u064b\u0627 \u0648\u062c\u0627\u0645\u0639\u0647\u0627 \u0641\u064a\u0647 \u0648\u064a\u0643\u0648\u0646 \u0627\u0644\u0632\u0648\u0627\u062c \u0639\u0646 \u0631\u063a\u0628\u0629\u060c \u0644\u0627 \u0628\u0646\u064a\u0629 \u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u0645\u0631\u0623\u0629 \u0644\u0632\u0648\u062c\u0647\u0627 \u0627\u0644\u0623\u0648\u0644\u060c \u0641\u0625\u0646 \u0637\u0644\u0642\u0647\u0627 \u0627\u0644\u0632\u0648\u062c \u0627\u0644\u0622\u062e\u0631 \u0623\u0648 \u0645\u0627\u062a \u0639\u0646\u0647\u0627 \u0648\u0627\u0646\u0642\u0636\u062a \u0639\u062f\u062a\u0647\u0627\u060c \u0641\u0644\u0627 \u0625\u062b\u0645 \u0639\u0644\u0649 \u0627\u0644\u0645\u0631\u0623\u0629 \u0648\u0632\u0648\u062c\u0647\u0627 \u0627\u0644\u0623\u0648\u0644 \u0623\u0646 \u064a\u062a\u0632\u0648\u062c\u0627 \u0628\u0639\u0642\u062f \u062c\u062f\u064a\u062f\u060c \u0648\u0645\u0647\u0631 \u062c\u062f\u064a\u062f\u060c \u0625\u0646 \u063a\u0644\u0628 \u0639\u0644\u0649 \u0638\u0646\u0647\u0645\u0627 \u0623\u0646 \u064a\u0642\u064a\u0645\u0627 \u0623\u062d\u0643\u0627\u0645 \u0627\u0644\u0644\u0647 \u0627\u0644\u062a\u064a \u0634\u0631\u0639\u0647\u0627 \u0644\u0644\u0632\u0648\u062c\u064a\u0646. \u0648\u062a\u0644\u0643 \u0623\u062d\u0643\u0627\u0645 \u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u062d\u062f\u062f\u0629 \u064a\u0628\u064a\u0646\u0647\u0627 \u0644\u0642\u0648\u0645 \u064a\u0639\u0644\u0645\u0648\u0646 \u0623\u062d\u0643\u0627\u0645\u0647 \u0648\u062d\u062f\u0648\u062f\u0647; \u0644\u0623\u0646\u0647\u0645 \u0627\u0644\u0645\u0646\u062a\u0641\u0639\u0648\u0646 \u0628\u0647\u0627.","2:231":"\u0648\u0625\u0630\u0627 \u0637\u064e\u0644\u0651\u064e\u0642\u062a\u0645 \u0627\u0644\u0646\u0633\u0627\u0621 \u0641\u0642\u0627\u0631\u0628\u0646 \u0627\u0646\u062a\u0647\u0627\u0621 \u0639\u062f\u062a\u0647\u0646\u060c \u0641\u0631\u0627\u062c\u0639\u0648\u0647\u0646\u060c \u0648\u0646\u064a\u062a\u0643\u0645 \u0627\u0644\u0642\u064a\u0627\u0645 \u0628\u062d\u0642\u0648\u0642\u0647\u0646 \u0639\u0644\u0649 \u0627\u0644\u0648\u062c\u0647 \u0627\u0644\u0645\u0633\u062a\u062d\u0633\u0646 \u0634\u0631\u0639\u064b\u0627 \u0648\u0639\u0631\u0641\u064b\u0627\u060c \u0623\u0648 \u0627\u062a\u0631\u0643\u0648\u0647\u0646 \u062d\u062a\u0649 \u062a\u0646\u0642\u0636\u064a \u0639\u062f\u062a\u0647\u0646. \u0648\u0627\u062d\u0630\u0631\u0648\u0627 \u0623\u0646 \u062a\u0643\u0648\u0646 \u0645\u0631\u0627\u062c\u0639\u062a\u0647\u0646 \u0628\u0642\u0635\u062f \u0627\u0644\u0625\u0636\u0631\u0627\u0631 \u0628\u0647\u0646 \u0644\u0623\u062c\u0644 \u0627\u0644\u0627\u0639\u062a\u062f\u0627\u0621 \u0639\u0644\u0649 \u062d\u0642\u0648\u0642\u0647\u0646. \u0648\u0645\u0646 \u064a\u0641\u0639\u0644 \u0630\u0644\u0643 \u0641\u0642\u062f \u0638\u0644\u0645 \u0646\u0641\u0633\u0647 \u0628\u0627\u0633\u062a\u062d\u0642\u0627\u0642\u0647 \u0627\u0644\u0639\u0642\u0648\u0628\u0629\u060c \u0648\u0644\u0627 \u062a\u062a\u062e\u0630\u0648\u0627 \u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0648\u0623\u062d\u0643\u0627\u0645\u0647 \u0644\u0639\u0628\u064b\u0627 \u0648\u0644\u0647\u0648\u064b\u0627. \u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u0646\u0639\u0645\u0629 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0628\u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u062a\u0641\u0635\u064a\u0644 \u0627\u0644\u0623\u062d\u0643\u0627\u0645. \u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0645\u0646 \u0627\u0644\u0642\u0631\u0622\u0646 \u0648\u0627\u0644\u0633\u0646\u0629\u060c \u0648\u0627\u0634\u0643\u0631\u0648\u0627 \u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0639\u0644\u0649 \u0647\u0630\u0647 \u0627\u0644\u0646\u0639\u0645 \u0627\u0644\u062c\u0644\u064a\u0644\u0629\u060c \u064a\u064f\u0630\u0643\u0651\u0650\u0631\u0643\u0645 \u0627\u0644\u0644\u0647 \u0628\u0647\u0630\u0627\u060c \u0648\u064a\u062e\u0648\u0641\u0643\u0645 \u0645\u0646 \u0627\u0644\u0645\u062e\u0627\u0644\u0641\u0629\u060c \u0641\u062e\u0627\u0641\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0627\u0642\u0628\u0648\u0647\u060c \u0648\u0627\u0639\u0644\u0645\u0648\u0627 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0645 \u0628\u0643\u0644 \u0634\u064a\u0621\u060c \u0644\u0627 \u064a\u062e\u0641\u0649 \u0639\u0644\u064a\u0647 \u0634\u064a\u0621\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a \u0643\u0644\u0627 \u0628\u0645\u0627 \u064a\u0633\u062a\u062d\u0642.","2:232":"\u0648\u0627\u0630\u0627 \u0637\u0644\u0651\u064e\u0642\u062a\u0645 \u0646\u0633\u0627\u0621\u0643\u0645 \u062f\u0648\u0646 \u0627\u0644\u062b\u0644\u0627\u062b \u0648\u0627\u0646\u062a\u0647\u062a \u0639\u062f\u062a\u0647\u0646 \u0645\u0646 \u063a\u064a\u0631 \u0645\u0631\u0627\u062c\u0639\u0629 \u0644\u0647\u0646\u060c \u0641\u0644\u0627 \u062a\u0636\u064a\u0642\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0623\u0648\u0644\u064a\u0627\u0621- \u0639\u0644\u0649 \u0627\u0644\u0645\u0637\u0644\u0642\u0627\u062a \u0628\u0645\u0646\u0639\u0647\u0646 \u0645\u0646 \u0627\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0623\u0632\u0648\u0627\u062c\u0647\u0646 \u0628\u0639\u0642\u062f \u062c\u062f\u064a\u062f \u0625\u0630\u0627 \u0623\u0631\u062f\u0646 \u0630\u0644\u0643\u060c \u0648\u062d\u062f\u062b \u0627\u0644\u062a\u0631\u0627\u0636\u064a \u0634\u0631\u0639\u064b\u0627 \u0648\u0639\u0631\u0641\u064b\u0627. \u0630\u0644\u0643 \u064a\u0648\u0639\u0638 \u0628\u0647 \u0645\u0646 \u0643\u0627\u0646 \u0645\u0646\u0643\u0645 \u0635\u0627\u062f\u0642 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0622\u062e\u0631. \u0625\u0646 \u062a\u064e\u0631\u0652\u0643\u064e \u0627\u0644\u0639\u0636\u0644 \u0648\u062a\u0645\u0643\u064a\u0646 \u0627\u0644\u0623\u0632\u0648\u0627\u062c \u0645\u0646 \u0646\u0643\u0627\u062d \u0632\u0648\u062c\u0627\u062a\u0647\u0645 \u0623\u0643\u062b\u0631 \u0646\u0645\u0627\u0621 \u0648\u0637\u0647\u0627\u0631\u0629 \u0644\u0623\u0639\u0631\u0627\u0636\u0643\u0645\u060c \u0648\u0623\u0639\u0638\u0645 \u0645\u0646\u0641\u0639\u0629 \u0648\u062b\u0648\u0627\u0628\u064b\u0627 \u0644\u0643\u0645. \u0648\u0627\u0644\u0644\u0647 \u064a\u0639\u0644\u0645 \u0645\u0627 \u0641\u064a\u0647 \u0635\u0644\u0627\u062d\u0643\u0645 \u0648\u0623\u0646\u062a\u0645 \u0644\u0627 \u062a\u0639\u0644\u0645\u0648\u0646 \u0630\u0644\u0643.","2:233":"\u0648\u0639\u0644\u0649 \u0627\u0644\u0648\u0627\u0644\u062f\u0627\u062a \u0625\u0631\u0636\u0627\u0639 \u0623\u0648\u0644\u0627\u062f\u0647\u0646 \u0645\u062f\u0629 \u0633\u0646\u062a\u064a\u0646 \u0643\u0627\u0645\u0644\u062a\u064a\u0646 \u0644\u0645\u0646 \u0623\u0631\u0627\u062f \u0625\u062a\u0645\u0627\u0645 \u0627\u0644\u0631\u0636\u0627\u0639\u0629\u060c \u0648\u064a\u062c\u0628 \u0639\u0644\u0649 \u0627\u0644\u0622\u0628\u0627\u0621 \u0623\u0646 \u064a\u0643\u0641\u064f\u0644\u0648\u0627 \u0644\u0644\u0645\u0631\u0636\u0639\u0627\u062a \u0627\u0644\u0645\u0637\u0644\u0642\u0627\u062a \u0637\u0639\u0627\u0645\u0647\u0646 \u0648\u0643\u0633\u0648\u062a\u0647\u0646\u060c \u0639\u0644\u0649 \u0627\u0644\u0648\u062c\u0647 \u0627\u0644\u0645\u0633\u062a\u062d\u0633\u0646 \u0634\u0631\u0639\u064b\u0627 \u0648\u0639\u0631\u0641\u064b\u0627; \u0644\u0623\u0646 \u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u0643\u0644\u0641 \u0646\u0641\u0633\u064b\u0627 \u0625\u0644\u0627 \u0642\u062f\u0631 \u0637\u0627\u0642\u062a\u0647\u0627\u060c \u0648\u0644\u0627 \u064a\u062d\u0644 \u0644\u0644\u0648\u0627\u0644\u062f\u064a\u0646 \u0623\u0646 \u064a\u062c\u0639\u0644\u0648\u0627 \u0627\u0644\u0645\u0648\u0644\u0648\u062f \u0648\u0633\u064a\u0644\u0629 \u0644\u0644\u0645\u0636\u0627\u0631\u0629 \u0628\u064a\u0646\u0647\u0645\u0627\u060c \u0648\u064a\u062c\u0628 \u0639\u0644\u0649 \u0627\u0644\u0648\u0627\u0631\u062b \u0639\u0646\u062f \u0645\u0648\u062a \u0627\u0644\u0648\u0627\u0644\u062f \u0645\u062b\u0644 \u0645\u0627 \u064a\u062c\u0628 \u0639\u0644\u0649 \u0627\u0644\u0648\u0627\u0644\u062f \u0642\u0628\u0644 \u0645\u0648\u062a\u0647 \u0645\u0646 \u0627\u0644\u0646\u0641\u0642\u0629 \u0648\u0627\u0644\u0643\u0633\u0648\u0629. \u0641\u0625\u0646 \u0623\u0631\u0627\u062f \u0627\u0644\u0648\u0627\u0644\u062f\u0627\u0646 \u0641\u0637\u0627\u0645 \u0627\u0644\u0645\u0648\u0644\u0648\u062f \u0642\u0628\u0644 \u0627\u0646\u062a\u0647\u0627\u0621 \u0627\u0644\u0633\u0646\u062a\u064a\u0646 \u0641\u0644\u0627 \u062d\u0631\u062c \u0639\u0644\u064a\u0647\u0645\u0627 \u0625\u0630\u0627 \u062a\u0631\u0627\u0636\u064a\u0627 \u0648\u062a\u0634\u0627\u0648\u0631\u0627 \u0641\u064a \u0630\u0644\u0643; \u0644\u064a\u0635\u0644\u0627 \u0625\u0644\u0649 \u0645\u0627 \u0641\u064a\u0647 \u0645\u0635\u0644\u062d\u0629 \u0627\u0644\u0645\u0648\u0644\u0648\u062f. \u0648\u0625\u0646 \u0627\u062a\u0641\u0642 \u0627\u0644\u0648\u0627\u0644\u062f\u0627\u0646 \u0639\u0644\u0649 \u0625\u0631\u0636\u0627\u0639 \u0627\u0644\u0645\u0648\u0644\u0648\u062f \u0645\u0646 \u0645\u0631\u0636\u0639\u0629 \u0623\u062e\u0631\u0649 \u063a\u064a\u0631 \u0648\u0627\u0644\u062f\u062a\u0647 \u0641\u0644\u0627 \u062d\u0631\u062c \u0639\u0644\u064a\u0647\u0645\u0627\u060c \u0625\u0630\u0627 \u0633\u0644\u0651\u064e\u0645 \u0627\u0644\u0648\u0627\u0644\u062f \u0644\u0644\u0623\u0645 \u062d\u0642\u0651\u064e\u0647\u0627\u060c \u0648\u0633\u0644\u0651\u064e\u0645 \u0644\u0644\u0645\u0631\u0636\u0639\u0629 \u0623\u062c\u0631\u0647\u0627 \u0628\u0645\u0627 \u064a\u062a\u0639\u0627\u0631\u0641\u0647 \u0627\u0644\u0646\u0627\u0633. \u0648\u062e\u0627\u0641\u0648\u0627 \u0627\u0644\u0644\u0647 \u0641\u064a \u062c\u0645\u064a\u0639 \u0623\u062d\u0648\u0627\u0644\u0643\u0645\u060c \u0648\u0627\u0639\u0644\u0645\u0648\u0627 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0628\u0645\u0627 \u062a\u0639\u0645\u0644\u0648\u0646 \u0628\u0635\u064a\u0631\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a\u0643\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643.","2:234":"\u0648\u0627\u0644\u0630\u064a\u0646 \u064a\u0645\u0648\u062a\u0648\u0646 \u0645\u0646\u0643\u0645\u060c \u0648\u064a\u062a\u0631\u0643\u0648\u0646 \u0632\u0648\u062c\u0627\u062a \u0628\u0639\u062f\u0647\u0645\u060c \u064a\u062c\u0628 \u0639\u0644\u064a\u0647\u0646 \u0627\u0644\u0627\u0646\u062a\u0638\u0627\u0631 \u0628\u0623\u0646\u0641\u0633\u0647\u0646 \u0645\u062f\u0629 \u0623\u0631\u0628\u0639\u0629 \u0623\u0634\u0647\u0631 \u0648\u0639\u0634\u0631\u0629 \u0623\u064a\u0627\u0645\u060c \u0644\u0627 \u064a\u062e\u0631\u062c\u0646 \u0645\u0646 \u0645\u0646\u0632\u0644 \u0627\u0644\u0632\u0648\u062c\u064a\u0629\u060c \u0648\u0644\u0627 \u064a\u062a\u0632\u064a\u0651\u064e\u0646\u0651\u064e\u060c \u0648\u0644\u0627 \u064a\u062a\u0632\u0648\u062c\u0646\u060c \u0641\u0625\u0630\u0627 \u0627\u0646\u062a\u0647\u062a \u0627\u0644\u0645\u062f\u0629 \u0627\u0644\u0645\u0630\u0643\u0648\u0631\u0629 \u0641\u0644\u0627 \u0625\u062b\u0645 \u0639\u0644\u064a\u0643\u0645 \u064a\u0627 \u0623\u0648\u0644\u064a\u0627\u0621 \u0627\u0644\u0646\u0633\u0627\u0621 \u0641\u064a\u0645\u0627 \u064a\u0641\u0639\u0644\u0646 \u0641\u064a \u0623\u0646\u0641\u0633\u0647\u0646 \u0645\u0646 \u0627\u0644\u062e\u0631\u0648\u062c\u060c \u0648\u0627\u0644\u062a\u0632\u064a\u0646\u060c \u0648\u0627\u0644\u0632\u0648\u0627\u062c \u0639\u0644\u0649 \u0627\u0644\u0648\u062c\u0647 \u0627\u0644\u0645\u0642\u0631\u0631 \u0634\u0631\u0639\u064b\u0627. \u0648\u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649 \u062e\u0628\u064a\u0631 \u0628\u0623\u0639\u0645\u0627\u0644\u0643\u0645 \u0638\u0627\u0647\u0631\u0647\u0627 \u0648\u0628\u0627\u0637\u0646\u0647\u0627\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a\u0643\u0645 \u0639\u0644\u064a\u0647\u0627.","2:235":"\u0648\u0644\u0627 \u0625\u062b\u0645 \u0639\u0644\u064a\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u062c\u0627\u0644- \u0641\u064a\u0645\u0627 \u062a\u064f\u0644\u064e\u0645\u0651\u0650\u062d\u0648\u0646 \u0628\u0647 \u0645\u0650\u0646 \u0637\u0644\u0628 \u0627\u0644\u0632\u0648\u0627\u062c \u0628\u0627\u0644\u0646\u0633\u0627\u0621 \u0627\u0644\u0645\u062a\u0648\u0641\u0651\u064e\u0649 \u0639\u0646\u0647\u0646\u0651\u064e \u0623\u0632\u0648\u0627\u062c\u0647\u0646\u060c \u0623\u0648 \u0627\u0644\u0645\u0637\u0644\u0642\u0627\u062a \u0637\u0644\u0627\u0642\u064b\u0627 \u0628\u0627\u0626\u0646\u064b\u0627 \u0641\u064a \u0623\u062b\u0646\u0627\u0621 \u0639\u062f\u062a\u0647\u0646\u060c \u0648\u0644\u0627 \u0630\u0646\u0628 \u0639\u0644\u064a\u0643\u0645 \u0623\u064a\u0636\u064b\u0627 \u0641\u064a\u0645\u0627 \u0623\u0636\u0645\u0631\u062a\u0645\u0648\u0647 \u0641\u064a \u0623\u0646\u0641\u0633\u0643\u0645 \u0645\u0646 \u0646\u064a\u0629 \u0627\u0644\u0632\u0648\u0627\u062c \u0628\u0647\u0646 \u0628\u0639\u062f \u0627\u0646\u062a\u0647\u0627\u0621 \u0639\u062f\u062a\u0647\u0646. \u0639\u0644\u0645 \u0627\u0644\u0644\u0647 \u0623\u0646\u0643\u0645 \u0633\u062a\u0630\u0643\u0631\u0648\u0646 \u0627\u0644\u0646\u0633\u0627\u0621 \u0627\u0644\u0645\u0639\u062a\u062f\u0651\u064e\u0627\u062a\u060c \u0648\u0644\u0646 \u062a\u0635\u0628\u0631\u0648\u0627 \u0639\u0644\u0649 \u0627\u0644\u0633\u0643\u0648\u062a \u0639\u0646\u0647\u0646\u060c \u0644\u0636\u0639\u0641\u0643\u0645; \u0644\u0630\u0644\u0643 \u0623\u0628\u0627\u062d \u0644\u0643\u0645 \u0623\u0646 \u062a\u0630\u0643\u0631\u0648\u0647\u0646 \u062a\u0644\u0645\u064a\u062d\u064b\u0627 \u0623\u0648 \u0625\u0636\u0645\u0627\u0631\u064b\u0627 \u0641\u064a \u0627\u0644\u0646\u0641\u0633\u060c \u0648\u0627\u062d\u0630\u0631\u0648\u0627 \u0623\u0646 \u062a\u0648\u0627\u0639\u062f\u0648\u0647\u0646 \u0639\u0644\u0649 \u0627\u0644\u0646\u0643\u0627\u062d \u0633\u0631\u064b\u0627 \u0628\u0627\u0644\u0632\u0646\u0649 \u0623\u0648 \u0627\u0644\u0627\u062a\u0641\u0627\u0642 \u0639\u0644\u0649 \u0627\u0644\u0632\u0648\u0627\u062c \u0641\u064a \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0639\u062f\u0629\u060c \u0625\u0644\u0627 \u0623\u0646 \u062a\u0642\u0648\u0644\u0648\u0627 \u0642\u0648\u0644\u0627 \u064a\u064f\u0641\u0652\u0647\u064e\u0645 \u0645\u0646\u0647 \u0623\u0646 \u0645\u062b\u0644\u0647\u0627 \u064a\u064f\u0631\u0652\u063a\u064e\u0628\u064f \u0641\u064a\u0647\u0627 \u0627\u0644\u0623\u0632\u0648\u0627\u062c\u060c \u0648\u0644\u0627 \u062a\u0639\u0632\u0645\u0648\u0627 \u0639\u0644\u0649 \u0639\u0642\u062f \u0627\u0644\u0646\u0643\u0627\u062d \u0641\u064a \u0632\u0645\u0627\u0646 \u0627\u0644\u0639\u062f\u0629 \u062d\u062a\u0649 \u062a\u0646\u0642\u0636\u064a \u0645\u062f\u062a\u0647\u0627. \u0648\u0627\u0639\u0644\u0645\u0648\u0627 \u0623\u0646 \u0627\u0644\u0644\u0647 \u064a\u0639\u0644\u0645 \u0645\u0627 \u0641\u064a \u0623\u0646\u0641\u0633\u0643\u0645 \u0641\u062e\u0627\u0641\u0648\u0647\u060c \u0648\u0627\u0639\u0644\u0645\u0648\u0627 \u0623\u0646\u0651\u064e \u0627\u0644\u0644\u0647 \u063a\u0641\u0648\u0631 \u0644\u0645\u0646 \u062a\u0627\u0628 \u0645\u0646 \u0630\u0646\u0648\u0628\u0647\u060c \u062d\u0644\u064a\u0645 \u0639\u0644\u0649 \u0639\u0628\u0627\u062f\u0647 \u0644\u0627 \u064a\u0639\u062c\u0644 \u0639\u0644\u064a\u0647\u0645 \u0628\u0627\u0644\u0639\u0642\u0648\u0628\u0629.","2:236":"\u0644\u0627 \u0625\u062b\u0645 \u0639\u0644\u064a\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0623\u0632\u0648\u0627\u062c- \u0625\u0646 \u0637\u0644\u0642\u062a\u0645 \u0627\u0644\u0646\u0633\u0627\u0621 \u0628\u0639\u062f \u0627\u0644\u0639\u0642\u062f \u0639\u0644\u064a\u0647\u0646\u060c \u0648\u0642\u0628\u0644 \u0623\u0646 \u062a\u062c\u0627\u0645\u0639\u0648\u0647\u0646\u060c \u0623\u0648 \u062a\u062d\u062f\u062f\u0648\u0627 \u0645\u0647\u0631\u064b\u0627 \u0644\u0647\u0646\u060c \u0648\u0645\u062a\u0651\u0650\u0639\u0648\u0647\u0646 \u0628\u0634\u064a\u0621 \u064a\u0646\u062a\u0641\u0639\u0646 \u0628\u0647 \u062c\u0628\u0631\u064b\u0627 \u0644\u0647\u0646\u060c \u0648\u062f\u0641\u0639\u064b\u0627 \u0644\u0648\u062d\u0634\u0629 \u0627\u0644\u0637\u0644\u0627\u0642\u060c \u0648\u0625\u0632\u0627\u0644\u0629 \u0644\u0644\u0623\u062d\u0642\u0627\u062f. \u0648\u0647\u0630\u0647 \u0627\u0644\u0645\u062a\u0639\u0629 \u062a\u062c\u0628 \u0628\u062d\u0633\u0628 \u062d\u0627\u0644 \u0627\u0644\u0631\u062c\u0644 \u0627\u0644\u0645\u0637\u0644\u0651\u0650\u0642: \u0639\u0644\u0649 \u0627\u0644\u063a\u0646\u064a \u0642\u064e\u062f\u0652\u0631 \u0633\u064e\u0639\u064e\u0629 \u0631\u0632\u0642\u0647\u060c \u0648\u0639\u0644\u0649 \u0627\u0644\u0641\u0642\u064a\u0631 \u0642\u064e\u062f\u0652\u0631 \u0645\u0627 \u064a\u0645\u0644\u0643\u0647\u060c \u0645\u062a\u0627\u0639\u064b\u0627 \u0639\u0644\u0649 \u0627\u0644\u0648\u062c\u0647 \u0627\u0644\u0645\u0639\u0631\u0648\u0641 \u0634\u0631\u0639\u064b\u0627\u060c \u0648\u0647\u0648 \u062d\u0642 \u062b\u0627\u0628\u062a \u0639\u0644\u0649 \u0627\u0644\u0630\u064a\u0646 \u064a\u062d\u0633\u0646\u0648\u0646 \u0625\u0644\u0649 \u0627\u0644\u0645\u0637\u0644\u0642\u0627\u062a \u0648\u0625\u0644\u0649 \u0623\u0646\u0641\u0633\u0647\u0645 \u0628\u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647.","2:237":"\u0648\u0625\u0646 \u0637\u0644\u0651\u064e\u0642\u062a\u0645 \u0627\u0644\u0646\u0633\u0627\u0621 \u0628\u0639\u062f \u0627\u0644\u0639\u0642\u062f \u0639\u0644\u064a\u0647\u0646\u060c \u0648\u0644\u0645 \u062a\u062c\u0627\u0645\u0639\u0648\u0647\u0646\u060c \u0648\u0644\u0643\u0646\u0643\u0645 \u0623\u0644\u0632\u0645\u062a\u0645 \u0623\u0646\u0641\u0633\u0643\u0645 \u0628\u0645\u0647\u0631 \u0645\u062d\u062f\u062f \u0644\u0647\u0646\u060c \u0641\u064a\u062c\u0628 \u0639\u0644\u064a\u0643\u0645 \u0623\u0646 \u062a\u0639\u0637\u0648\u0647\u0646 \u0646\u0635\u0641 \u0627\u0644\u0645\u0647\u0631 \u0627\u0644\u0645\u062a\u0641\u0642 \u0639\u0644\u064a\u0647\u060c \u0625\u0644\u0627 \u0623\u0646\u0652 \u062a\u064f\u0633\u0627\u0645\u0650\u062d \u0627\u0644\u0645\u0637\u0644\u0642\u0627\u062a\u060c \u0641\u064a\u062a\u0631\u0643\u0646 \u0646\u0635\u0641 \u0627\u0644\u0645\u0647\u0631 \u0627\u0644\u0645\u0633\u062a\u062d\u0642 \u0644\u0647\u0646\u060c \u0623\u0648 \u064a\u0633\u0645\u062d \u0627\u0644\u0632\u0648\u062c \u0628\u0623\u0646 \u064a\u062a\u0631\u0643 \u0644\u0644\u0645\u0637\u0644\u0642\u0629 \u0627\u0644\u0645\u0647\u0631 \u0643\u0644\u0647\u060c \u0648\u062a\u0633\u0627\u0645\u062d\u0643\u0645 \u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u062c\u0627\u0644 \u0648\u0627\u0644\u0646\u0633\u0627\u0621 \u0623\u0642\u0631\u0628 \u0625\u0644\u0649 \u062e\u0634\u064a\u0629 \u0627\u0644\u0644\u0647 \u0648\u0637\u0627\u0639\u062a\u0647\u060c \u0648\u0644\u0627 \u062a\u0646\u0633\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633- \u0627\u0644\u0641\u0636\u0644 \u0648\u0627\u0644\u0625\u062d\u0633\u0627\u0646 \u0628\u064a\u0646\u0643\u0645\u060c \u0648\u0647\u0648 \u0625\u0639\u0637\u0627\u0621 \u0645\u0627 \u0644\u064a\u0633 \u0628\u0648\u0627\u062c\u0628 \u0639\u0644\u064a\u0643\u0645\u060c \u0648\u0627\u0644\u062a\u0633\u0627\u0645\u062d \u0641\u064a \u0627\u0644\u062d\u0642\u0648\u0642. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0628\u0645\u0627 \u062a\u0639\u0645\u0644\u0648\u0646 \u0628\u0635\u064a\u0631\u060c \u064a\u064f\u0631\u063a\u0651\u0650\u0628\u0643\u0645 \u0641\u064a \u0627\u0644\u0645\u0639\u0631\u0648\u0641\u060c \u0648\u064a\u062d\u062b\u0651\u064f\u0643\u0645 \u0639\u0644\u0649 \u0627\u0644\u0641\u0636\u0644.","2:238":"\u062d\u0627\u0641\u0638\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646- \u0639\u0644\u0649 \u0627\u0644\u0635\u0644\u0648\u0627\u062a \u0627\u0644\u062e\u0645\u0633 \u0627\u0644\u0645\u0641\u0631\u0648\u0636\u0629 \u0628\u0627\u0644\u0645\u062f\u0627\u0648\u0645\u0629 \u0639\u0644\u0649 \u0623\u062f\u0627\u0626\u0647\u0627 \u0641\u064a \u0623\u0648\u0642\u0627\u062a\u0647\u0627 \u0628\u0634\u0631\u0648\u0637\u0647\u0627 \u0648\u0623\u0631\u0643\u0627\u0646\u0647\u0627 \u0648\u0648\u0627\u062c\u0628\u0627\u062a\u0647\u0627\u060c \u0648\u062d\u0627\u0641\u0638\u0648\u0627 \u0639\u0644\u0649 \u0627\u0644\u0635\u0644\u0627\u0629 \u0627\u0644\u0645\u062a\u0648\u0633\u0637\u0629 \u0628\u064a\u0646\u0647\u0627 \u0648\u0647\u064a \u0635\u0644\u0627\u0629 \u0627\u0644\u0639\u0635\u0631\u060c \u0648\u0642\u0648\u0645\u0648\u0627 \u0641\u064a \u0635\u0644\u0627\u062a\u0643\u0645 \u0645\u0637\u064a\u0639\u064a\u0646 \u0644\u0644\u0647\u060c \u062e\u0627\u0634\u0639\u064a\u0646 \u0630\u0644\u064a\u0644\u064a\u0646.","2:239":"\u0641\u0625\u0646 \u062e\u0641\u062a\u0645 \u0645\u0646 \u0639\u062f\u0648 \u0644\u0643\u0645 \u0641\u0635\u0644\u0648\u0627 \u0635\u0644\u0627\u0629 \u0627\u0644\u062e\u0648\u0641 \u0645\u0627\u0634\u064a\u0646\u060c \u0623\u0648 \u0631\u0627\u0643\u0628\u064a\u0646\u060c \u0639\u0644\u0649 \u0623\u064a \u0647\u064a\u0626\u0629 \u062a\u0633\u062a\u0637\u064a\u0639\u0648\u0646\u0647\u0627 \u0648\u0644\u0648 \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0621\u060c \u0623\u0648 \u0625\u0644\u0649 \u063a\u064a\u0631 \u062c\u0647\u0629 \u0627\u0644\u0642\u0628\u0644\u0629\u060c \u0641\u0625\u0630\u0627 \u0632\u0627\u0644 \u062e\u0648\u0641\u0643\u0645 \u0641\u0635\u0644\u0651\u064f\u0648\u0627 \u0635\u0644\u0627\u0629 \u0627\u0644\u0623\u0645\u0646\u060c \u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u0627\u0644\u0644\u0647 \u0641\u064a\u0647\u0627\u060c \u0648\u0644\u0627 \u062a\u0646\u0642\u0635\u0648\u0647\u0627 \u0639\u0646 \u0647\u064a\u0626\u062a\u0647\u0627 \u0627\u0644\u0623\u0635\u0644\u064a\u0629\u060c \u0648\u0627\u0634\u0643\u0631\u0648\u0627 \u0644\u0647 \u0639\u0644\u0649 \u0645\u0627 \u0639\u0644\u0651\u064e\u0645\u0643\u0645 \u0645\u0646 \u0623\u0645\u0648\u0631 \u0627\u0644\u0639\u0628\u0627\u062f\u0627\u062a \u0648\u0627\u0644\u0623\u062d\u0643\u0627\u0645 \u0645\u0627 \u0644\u0645 \u062a\u0643\u0648\u0646\u0648\u0627 \u0639\u0644\u0649 \u0639\u0644\u0645 \u0628\u0647.","2:240":"\u0648\u0627\u0644\u0623\u0632\u0648\u0627\u062c \u0627\u0644\u0630\u064a\u0646 \u064a\u0645\u0648\u062a\u0648\u0646 \u0648\u064a\u062a\u0631\u0643\u0648\u0646 \u0632\u0648\u062c\u0627\u062a \u0628\u0639\u062f\u0647\u0645\u060c \u0641\u0639\u0644\u064a\u0647\u0645 \u0648\u0635\u064a\u0629\u064b \u0644\u0647\u0646\u0651\u064e: \u0623\u0646 \u064a\u064f\u0645\u064e\u062a\u0651\u064e\u0639\u0646 \u0633\u0646\u0647 \u062a\u0627\u0645\u0629 \u0645\u0646 \u064a\u0648\u0645 \u0627\u0644\u0648\u0641\u0627\u0629\u060c \u0628\u0627\u0644\u0633\u0643\u0646\u0649 \u0641\u064a \u0645\u0646\u0632\u0644 \u0627\u0644\u0632\u0648\u062c \u0645\u0646 \u063a\u064a\u0631 \u0625\u062e\u0631\u0627\u062c \u0627\u0644\u0648\u0631\u062b\u0629 \u0644\u0647\u0646 \u0645\u062f\u0629 \u0627\u0644\u0633\u0646\u0629; \u062c\u0628\u0631\u064b\u0627 \u0644\u062e\u0627\u0637\u0631 \u0627\u0644\u0632\u0648\u062c\u0629\u060c \u0648\u0628\u0631\u064b\u0627 \u0628\u0627\u0644\u0645\u062a\u0648\u0641\u0651\u064e\u0649. \u0641\u0625\u0646 \u062e\u0631\u062c\u062a \u0627\u0644\u0632\u0648\u062c\u0627\u062a \u0628\u0627\u062e\u062a\u064a\u0627\u0631\u0647\u0646 \u0642\u0628\u0644 \u0627\u0646\u0642\u0636\u0627\u0621 \u0627\u0644\u0633\u0646\u0629 \u0641\u0644\u0627 \u0625\u062b\u0645 \u0639\u0644\u064a\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0648\u0631\u062b\u0629- \u0641\u064a \u0630\u0644\u0643\u060c \u0648\u0644\u0627 \u062d\u0631\u062c \u0639\u0644\u0649 \u0627\u0644\u0632\u0648\u062c\u0627\u062a \u0641\u064a\u0645\u0627 \u0641\u0639\u0644\u0646 \u0641\u064a \u0623\u0646\u0641\u0633\u0647\u0646 \u0645\u0646 \u0623\u0645\u0648\u0631 \u0645\u0628\u0627\u062d\u0629. \u0648\u0627\u0644\u0644\u0647 \u0639\u0632\u064a\u0632 \u0641\u064a \u0645\u0644\u0643\u0647\u060c \u062d\u0643\u064a\u0645 \u0641\u064a \u0623\u0645\u0631\u0647 \u0648\u0646\u0647\u064a\u0647. \u0648\u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0629 \u0645\u0646\u0633\u0648\u062e\u0629 \u0628\u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: (\u0648\u0627\u0644\u0630\u064a\u0646 \u064a\u062a\u0648\u0641\u0648\u0646 \u0645\u0646\u0643\u0645 \u0648\u064a\u0630\u0631\u0648\u0646 \u0623\u0632\u0648\u0627\u062c\u064b\u0627 \u064a\u062a\u0631\u0628\u0635\u0646 \u0628\u0623\u0646\u0641\u0633\u0647\u0646 \u0623\u0631\u0628\u0639\u0629 \u0623\u0634\u0647\u0631 \u0648\u0639\u0634\u0631\u064b\u0627) .","2:241":"\u0648\u0644\u0644\u0645\u0637\u0644\u0642\u0627\u062a \u0645\u062a\u0627\u0639 \u0645\u0646 \u0643\u0633\u0648\u0629 \u0648\u0646\u0641\u0642\u0629 \u0639\u0644\u0649 \u0627\u0644\u0648\u062c\u0647 \u0627\u0644\u0645\u0639\u0631\u0648\u0641 \u0627\u0644\u0645\u0633\u062a\u062d\u0633\u0646 \u0634\u0631\u0639\u064b\u0627\u060c \u062d\u0642\u064b\u0627 \u0639\u0644\u0649 \u0627\u0644\u0630\u064a\u0646 \u064a\u062e\u0627\u0641\u0648\u0646 \u0627\u0644\u0644\u0647 \u0648\u064a\u062a\u0642\u0648\u0646\u0647 \u0641\u064a \u0623\u0645\u0631\u0647 \u0648\u0646\u0647\u064a\u0647.","2:242":"\u0645\u062b\u0644 \u0630\u0644\u0643 \u0627\u0644\u0628\u064a\u0627\u0646 \u0627\u0644\u0648\u0627\u0636\u062d \u0641\u064a \u0623\u062d\u0643\u0627\u0645 \u0627\u0644\u0623\u0648\u0644\u0627\u062f \u0648\u0627\u0644\u0646\u0633\u0627\u0621\u060c \u064a\u0628\u064a\u0651\u0650\u0646 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0622\u064a\u0627\u062a\u0647 \u0648\u0623\u062d\u0643\u0627\u0645\u0647 \u0641\u064a \u0643\u0644 \u0645\u0627 \u062a\u062d\u062a\u0627\u062c\u0648\u0646\u0647 \u0641\u064a \u0645\u0639\u0627\u0634\u0643\u0645 \u0648\u0645\u0639\u0627\u062f\u0643\u0645; \u0644\u0643\u064a \u062a\u0639\u0642\u0644\u0648\u0647\u0627 \u0648\u062a\u0639\u0645\u0644\u0648\u0627 \u0628\u0647\u0627.","2:243":"\u0623\u0644\u0645 \u062a\u0639\u0644\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0642\u0635\u0629 \u0627\u0644\u0630\u064a\u0646 \u0641\u0631\u0651\u064f\u0648\u0627 \u0645\u0646 \u0623\u0631\u0636\u0647\u0645 \u0648\u0645\u0646\u0627\u0632\u0644\u0647\u0645\u060c \u0648\u0647\u0645 \u0623\u0644\u0648\u0641 \u0643\u062b\u064a\u0631\u0629; \u062e\u0634\u064a\u0629 \u0627\u0644\u0645\u0648\u062a \u0645\u0646 \u0627\u0644\u0637\u0627\u0639\u0648\u0646 \u0623\u0648 \u0627\u0644\u0642\u062a\u0627\u0644\u060c \u0641\u0642\u0627\u0644 \u0644\u0647\u0645 \u0627\u0644\u0644\u0647: \u0645\u0648\u062a\u0648\u0627\u060c \u0641\u0645\u0627\u062a\u0648\u0627 \u062f\u0641\u0639\u0629 \u0648\u0627\u062d\u062f\u0629 \u0639\u0642\u0648\u0628\u0629 \u0639\u0644\u0649 \u0641\u0631\u0627\u0631\u0647\u0645 \u0645\u0646 \u0642\u062f\u0631 \u0627\u0644\u0644\u0647\u060c \u062b\u0645 \u0623\u062d\u064a\u0627\u0647\u0645 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0628\u0639\u062f \u0645\u062f\u0629; \u0644\u064a\u0633\u062a\u0648\u0641\u0648\u0627 \u0622\u062c\u0627\u0644\u0647\u0645\u060c \u0648\u0644\u064a\u062a\u0639\u0638\u0648\u0627 \u0648\u064a\u062a\u0648\u0628\u0648\u0627\u061f \u0625\u0646 \u0627\u0644\u0644\u0647 \u0644\u0630\u0648 \u0641\u0636\u0644 \u0639\u0638\u064a\u0645 \u0639\u0644\u0649 \u0627\u0644\u0646\u0627\u0633 \u0628\u0646\u0639\u0645\u0647 \u0627\u0644\u0643\u062b\u064a\u0631\u0629\u060c \u0648\u0644\u0643\u0646 \u0623\u0643\u062b\u0631 \u0627\u0644\u0646\u0627\u0633 \u0644\u0627 \u064a\u0634\u0643\u0631\u0648\u0646 \u0641\u0636\u0644 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645.","2:244":"\u0648\u0642\u0627\u062a\u0644\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646- \u0627\u0644\u0643\u0641\u0627\u0631 \u0644\u0646\u0635\u0631\u0629 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u0639\u0644\u0645\u0648\u0627 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0633\u0645\u064a\u0639 \u0644\u0623\u0642\u0648\u0627\u0644\u0643\u0645\u060c \u0639\u0644\u064a\u0645 \u0628\u0646\u064a\u0651\u064e\u0627\u062a\u0643\u0645 \u0648\u0623\u0639\u0645\u0627\u0644\u0643\u0645.","2:245":"\u0645\u0646 \u0630\u0627 \u0627\u0644\u0630\u064a \u064a\u0646\u0641\u0642 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0625\u0646\u0641\u0627\u0642\u064b\u0627 \u062d\u0633\u0646\u064b\u0627 \u0627\u062d\u062a\u0633\u0627\u0628\u064b\u0627 \u0644\u0644\u0623\u062c\u0631\u060c \u0641\u064a\u0636\u0627\u0639\u0641\u0647 \u0644\u0647 \u0623\u0636\u0639\u0627\u0641\u0627 \u0643\u062b\u064a\u0631\u0629 \u0644\u0627 \u062a\u062d\u0635\u0649 \u0645\u0646 \u0627\u0644\u062b\u0648\u0627\u0628 \u0648\u062d\u0633\u0646 \u0627\u0644\u062c\u0632\u0627\u0621\u061f \u0648\u0627\u0644\u0644\u0647 \u064a\u0642\u0628\u0636 \u0648\u064a\u0628\u0633\u0637\u060c \u0641\u0623\u0646\u0641\u0642\u0648\u0627 \u0648\u0644\u0627 \u062a\u0628\u0627\u0644\u0648\u0627; \u0641\u0625\u0646\u0647 \u0647\u0648 \u0627\u0644\u0631\u0632\u0627\u0642\u060c \u064a\u064f\u0636\u064a\u0651\u0650\u0642 \u0639\u0644\u0649 \u0645\u064e\u0646 \u064a\u0634\u0627\u0621 \u0645\u0646 \u0639\u0628\u0627\u062f\u0647 \u0641\u064a \u0627\u0644\u0631\u0632\u0642\u060c \u0648\u064a\u0648\u0633\u0639\u0647 \u0639\u0644\u0649 \u0622\u062e\u0631\u064a\u0646\u060c \u0644\u0647 \u0627\u0644\u062d\u0643\u0645\u0629 \u0627\u0644\u0628\u0627\u0644\u063a\u0629 \u0641\u064a \u0630\u0644\u0643\u060c \u0648\u0625\u0644\u064a\u0647 \u0648\u062d\u062f\u0647 \u062a\u0631\u062c\u0639\u0648\u0646 \u0628\u0639\u062f \u0627\u0644\u0645\u0648\u062a\u060c \u0641\u064a\u062c\u0627\u0632\u064a\u0643\u0645 \u0639\u0644\u0649 \u0623\u0639\u0645\u0627\u0644\u0643\u0645.","2:246":"\u0623\u0644\u0645 \u062a\u0639\u0644\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0642\u0635\u0629 \u0627\u0644\u0623\u0634\u0631\u0627\u0641 \u0648\u0627\u0644\u0648\u062c\u0647\u0627\u0621 \u0645\u0646 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0645\u0646 \u0628\u0639\u062f \u0632\u0645\u0627\u0646 \u0645\u0648\u0633\u0649; \u062d\u064a\u0646 \u0637\u0644\u0628\u0648\u0627 \u0645\u0646 \u0646\u0628\u064a\u0647\u0645 \u0623\u0646 \u064a\u0648\u0644\u064a \u0639\u0644\u064a\u0647\u0645 \u0645\u0644\u0643\u0627\u060c \u064a\u062c\u062a\u0645\u0639\u0648\u0646 \u062a\u062d\u062a \u0642\u064a\u0627\u062f\u062a\u0647\u060c \u0648\u064a\u0642\u0627\u062a\u0644\u0648\u0646 \u0623\u0639\u062f\u0627\u0621\u0647\u0645 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647. \u0642\u0627\u0644 \u0644\u0647\u0645 \u0646\u0628\u064a\u0647\u0645: \u0647\u0644 \u0627\u0644\u0623\u0645\u0631 \u0643\u0645\u0627 \u0623\u062a\u0648\u0642\u0639\u0647 \u0625\u0646\u0652 \u0641\u064f\u0631\u0650\u0636 \u0639\u0644\u064a\u0643\u0645 \u0627\u0644\u0642\u062a\u0627\u0644 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0623\u0646\u0643\u0645 \u0644\u0627 \u062a\u0642\u0627\u062a\u0644\u0648\u0646; \u0641\u0625\u0646\u064a \u0623\u062a\u0648\u0642\u0639 \u062c\u0628\u0646\u0643\u0645 \u0648\u0641\u0631\u0627\u0631\u0643\u0645 \u0645\u0646 \u0627\u0644\u0642\u062a\u0627\u0644\u060c \u0642\u0627\u0644\u0648\u0627 \u0645\u0633\u062a\u0646\u0643\u0631\u064a\u0646 \u062a\u0648\u0642\u0639 \u0646\u0628\u064a\u0647\u0645: \u0648\u0623\u064a \u0645\u0627\u0646\u0639 \u064a\u0645\u0646\u0639\u0646\u0627 \u0639\u0646 \u0627\u0644\u0642\u062a\u0627\u0644 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647\u060c \u0648\u0642\u062f \u0623\u064e\u062e\u0652\u0631\u064e\u062c\u064e\u0646\u064e\u0627 \u0639\u062f\u0648\u0651\u064f\u0646\u0627 \u0645\u0646 \u062f\u064a\u0627\u0631\u0646\u0627\u060c \u0648\u0623\u0628\u0639\u062f\u0646\u0627 \u0639\u0646 \u0623\u0648\u0644\u0627\u062f\u0646\u0627 \u0628\u0627\u0644\u0642\u062a\u0644 \u0648\u0627\u0644\u0623\u0633\u0631\u061f \u0641\u0644\u0645\u0627 \u0641\u0631\u0636 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0642\u062a\u0627\u0644 \u0645\u0639 \u0627\u0644\u0645\u0644\u0650\u0643 \u0627\u0644\u0630\u064a \u0639\u064a\u0651\u064e\u0646\u0647 \u0644\u0647\u0645 \u062c\u064e\u0628\u064f\u0646\u0648\u0627 \u0648\u0641\u0631\u0651\u064f\u0648\u0627 \u0639\u0646 \u0627\u0644\u0642\u062a\u0627\u0644\u060c \u0625\u0644\u0627 \u0642\u0644\u064a\u0644\u0627 \u0645\u0646\u0647\u0645 \u062b\u0628\u062a\u0648\u0627 \u0628\u0641\u0636\u0644 \u0627\u0644\u0644\u0647. \u0648\u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0645 \u0628\u0627\u0644\u0638\u0627\u0644\u0645\u064a\u0646 \u0627\u0644\u0646\u0627\u0643\u062b\u064a\u0646 \u0639\u0647\u0648\u062f\u0647\u0645.","2:247":"\u0648\u0642\u0627\u0644 \u0644\u0647\u0645 \u0646\u0628\u064a\u0647\u0645: \u0625\u0646 \u0627\u0644\u0644\u0647 \u0642\u062f \u0623\u0631\u0633\u0644 \u0625\u0644\u064a\u0643\u0645 \u0637\u0627\u0644\u0648\u062a \u0645\u064e\u0644\u0650\u0643\u064b\u0627 \u0625\u062c\u0627\u0628\u0629 \u0644\u0637\u0644\u0628\u0643\u0645\u060c \u064a\u0642\u0648\u062f\u0643\u0645 \u0644\u0642\u062a\u0627\u0644 \u0639\u062f\u0648\u0643\u0645 \u0643\u0645\u0627 \u0637\u0644\u0628\u062a\u0645. \u0642\u0627\u0644 \u0643\u0628\u0631\u0627\u0621 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644: \u0643\u064a\u0641 \u064a\u0643\u0648\u0646 \u0637\u0627\u0644\u0648\u062a \u0645\u064e\u0644\u0650\u0643\u064b\u0627 \u0639\u0644\u064a\u0646\u0627\u060c \u0648\u0647\u0648 \u0644\u0627 \u064a\u0633\u062a\u062d\u0642 \u0630\u0644\u0643\u061f \u0644\u0623\u0646\u0647 \u0644\u064a\u0633 \u0645\u0646 \u0633\u0628\u0637 \u0627\u0644\u0645\u0644\u0648\u0643\u060c \u0648\u0644\u0627 \u0645\u0646 \u0628\u064a\u062a \u0627\u0644\u0646\u0628\u0648\u0629\u060c \u0648\u0644\u0645 \u064a\u064f\u0639\u0652\u0637 \u0643\u062b\u0631\u0629 \u0641\u064a \u0627\u0644\u0623\u0645\u0648\u0627\u0644 \u064a\u0633\u062a\u0639\u064a\u0646 \u0628\u0647\u0627 \u0641\u064a \u0645\u0644\u0643\u0647\u060c \u0641\u0646\u062d\u0646 \u0623\u062d\u0642 \u0628\u0627\u0644\u0645\u0644\u0643 \u0645\u0646\u0647; \u0644\u0623\u0646\u0646\u0627 \u0645\u0646 \u0633\u0628\u0637 \u0627\u0644\u0645\u0644\u0648\u0643 \u0648\u0645\u0646 \u0628\u064a\u062a \u0627\u0644\u0646\u0628\u0648\u0629. \u0642\u0627\u0644 \u0644\u0647\u0645 \u0646\u0628\u064a\u0647\u0645: \u0625\u0646 \u0627\u0644\u0644\u0647 \u0627\u062e\u062a\u0627\u0631\u0647 \u0639\u0644\u064a\u0643\u0645 \u0648\u0647\u0648 \u0633\u0628\u062d\u0627\u0646\u0647 \u0623\u0639\u0644\u0645 \u0628\u0623\u0645\u0648\u0631 \u0639\u0628\u0627\u062f\u0647\u060c \u0648\u0632\u0627\u062f\u0647 \u0633\u064e\u0639\u064e\u0629 \u0641\u064a \u0627\u0644\u0639\u0644\u0645 \u0648\u0642\u0648\u0629 \u0641\u064a \u0627\u0644\u062c\u0633\u0645 \u0644\u064a\u062c\u0627\u0647\u062f \u0627\u0644\u0639\u062f\u0648. \u0648\u0627\u0644\u0644\u0647 \u0645\u0627\u0644\u0643 \u0627\u0644\u0645\u0644\u0643 \u064a\u0639\u0637\u064a \u0645\u0644\u0643\u0647 \u0645\u064e\u0646 \u064a\u0634\u0627\u0621 \u0645\u0646 \u0639\u0628\u0627\u062f\u0647\u060c \u0648\u0627\u0644\u0644\u0647 \u0648\u0627\u0633\u0639 \u0627\u0644\u0641\u0636\u0644 \u0648\u0627\u0644\u0639\u0637\u0627\u0621\u060c \u0639\u0644\u064a\u0645 \u0628\u062d\u0642\u0627\u0626\u0642 \u0627\u0644\u0623\u0645\u0648\u0631\u060c \u0644\u0627 \u064a\u062e\u0641\u0649 \u0639\u0644\u064a\u0647 \u0634\u064a\u0621.","2:248":"\u0648\u0642\u0627\u0644 \u0644\u0647\u0645 \u0646\u0628\u064a\u0647\u0645: \u0625\u0646 \u0639\u0644\u0627\u0645\u0629 \u0645\u0644\u0643\u0647 \u0623\u0646 \u064a\u0623\u062a\u064a\u0643\u0645 \u0627\u0644\u0635\u0646\u062f\u0648\u0642 \u0627\u0644\u0630\u064a \u0641\u064a\u0647 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 -\u0648\u0643\u0627\u0646 \u0623\u0639\u062f\u0627\u0624\u0647\u0645 \u0642\u062f \u0627\u0646\u062a\u0632\u0639\u0648\u0647 \u0645\u0646\u0647\u0645- \u0641\u064a\u0647 \u0637\u0645\u0623\u0646\u064a\u0646\u0629 \u0645\u0646 \u0631\u0628\u0643\u0645 \u062a\u062b\u0628\u062a \u0642\u0644\u0648\u0628 \u0627\u0644\u0645\u062e\u0644\u0635\u064a\u0646\u060c \u0648\u0641\u064a\u0647 \u0628\u0642\u064a\u0629 \u0645\u0646 \u0628\u0639\u0636 \u0623\u0634\u064a\u0627\u0621 \u062a\u0631\u0643\u0647\u0627 \u0622\u0644 \u0645\u0648\u0633\u0649 \u0648\u0622\u0644 \u0647\u0627\u0631\u0648\u0646\u060c \u0645\u062b\u0644 \u0627\u0644\u0639\u0635\u0627 \u0648\u0641\u064f\u062a\u0627\u062a \u0627\u0644\u0623\u0644\u0648\u0627\u062d \u062a\u062d\u0645\u0644\u0647 \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629. \u0625\u0646 \u0641\u064a \u0630\u0644\u0643 \u0644\u0623\u0639\u0638\u0645 \u0628\u0631\u0647\u0627\u0646 \u0644\u0643\u0645 \u0639\u0644\u0649 \u0627\u062e\u062a\u064a\u0627\u0631 \u0637\u0627\u0644\u0648\u062a \u0645\u0644\u0643\u064b\u0627 \u0639\u0644\u064a\u0643\u0645 \u0628\u0623\u0645\u0631 \u0627\u0644\u0644\u0647\u060c \u0625\u0646 \u0643\u0646\u062a\u0645 \u0645\u0635\u062f\u0642\u064a\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0644\u0647.","2:249":"\u0641\u0644\u0645\u0627 \u062e\u0631\u062c \u0637\u0627\u0644\u0648\u062a \u0628\u062c\u0646\u0648\u062f\u0647 \u0644\u0642\u062a\u0627\u0644 \u0627\u0644\u0639\u0645\u0627\u0644\u0642\u0629 \u0642\u0627\u0644 \u0644\u0647\u0645: \u0625\u0646 \u0627\u0644\u0644\u0647 \u0645\u0645\u062a\u062d\u0646\u0643\u0645 \u0639\u0644\u0649 \u0627\u0644\u0635\u0628\u0631 \u0628\u0646\u0647\u0631 \u0623\u0645\u0627\u0645\u0643\u0645 \u062a\u0639\u0628\u0631\u0648\u0646\u0647; \u0644\u064a\u062a\u0645\u064a\u0651\u064e\u0632 \u0627\u0644\u0645\u0624\u0645\u0646 \u0645\u0646 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u060c \u0641\u0645\u0646 \u0634\u0631\u0628 \u0645\u0646\u0643\u0645 \u0645\u0646 \u0645\u0627\u0621 \u0627\u0644\u0646\u0647\u0631 \u0641\u0644\u064a\u0633 \u0645\u0646\u064a\u060c \u0648\u0644\u0627 \u064a\u0635\u0644\u062d \u0644\u0644\u062c\u0647\u0627\u062f \u0645\u0639\u064a\u060c \u0648\u0645\u0646 \u0644\u0645 \u064a\u0630\u0642 \u0627\u0644\u0645\u0627\u0621 \u0641\u0625\u0646\u0647 \u0645\u0646\u064a; \u0644\u0623\u0646\u0647 \u0645\u0637\u064a\u0639 \u0644\u0623\u0645\u0631\u064a \u0648\u0635\u0627\u0644\u062d \u0644\u0644\u062c\u0647\u0627\u062f\u060c \u0625\u0644\u0627 \u0645\u064e\u0646 \u062a\u0631\u062e\u0651\u064e\u0635 \u0648\u0627\u063a\u062a\u0631\u0641 \u063a\u064f\u0631\u0652\u0641\u0629 \u0648\u0627\u062d\u062f\u0629 \u0628\u064a\u062f\u0647 \u0641\u0644\u0627 \u0644\u0648\u0645 \u0639\u0644\u064a\u0647. \u0641\u0644\u0645\u0627 \u0648\u0635\u0644\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u0646\u0647\u0631 \u0627\u0646\u0643\u0628\u0648\u0627 \u0639\u0644\u0649 \u0627\u0644\u0645\u0627\u0621\u060c \u0648\u0623\u0641\u0631\u0637\u0648\u0627 \u0641\u064a \u0627\u0644\u0634\u0631\u0628 \u0645\u0646\u0647\u060c \u0625\u0644\u0627 \u0639\u062f\u062f\u064b\u0627 \u0642\u0644\u064a\u0644\u0627 \u0645\u0646\u0647\u0645 \u0635\u0628\u0631\u0648\u0627 \u0639\u0644\u0649 \u0627\u0644\u0639\u0637\u0634 \u0648\u0627\u0644\u062d\u0631\u060c \u0648\u0627\u0643\u062a\u0641\u0648\u0627 \u0628\u063a\u064f\u0631\u0652\u0641\u0629 \u0627\u0644\u064a\u062f\u060c \u0648\u062d\u064a\u0646\u0626\u0630 \u062a\u062e\u0644\u0641 \u0627\u0644\u0639\u0635\u0627\u0629. \u0648\u0644\u0645\u0627 \u0639\u0628\u0631 \u0637\u0627\u0644\u0648\u062a \u0627\u0644\u0646\u0647\u0631 \u0647\u0648 \u0648\u0627\u0644\u0642\u0644\u0629 \u0627\u0644\u0645\u0624\u0645\u0646\u0629 \u0645\u0639\u0647 -\u0648\u0647\u0645 \u062b\u0644\u0627\u062b\u0645\u0627\u0626\u0629 \u0648\u0628\u0636\u0639\u0629 \u0639\u0634\u0631 \u0631\u062c\u0644\u0627- \u0644\u0645\u0644\u0627\u0642\u0627\u0629 \u0627\u0644\u0639\u062f\u0648\u060c \u0648\u0631\u0623\u0648\u0627 \u0643\u062b\u0631\u0629 \u0639\u062f\u0648\u0647\u0645 \u0648\u0639\u062f\u0651\u064e\u062a\u0647\u0645\u060c \u0642\u0627\u0644\u0648\u0627: \u0644\u0627 \u0642\u062f\u0631\u0629 \u0644\u0646\u0627 \u0627\u0644\u064a\u0648\u0645 \u0628\u062c\u0627\u0644\u0648\u062a \u0648\u062c\u0646\u0648\u062f\u0647 \u0627\u0644\u0623\u0634\u062f\u0627\u0621\u060c \u0641\u0623\u062c\u0627\u0628 \u0627\u0644\u0630\u064a\u0646 \u064a\u0648\u0642\u0646\u0648\u0646 \u0628\u0644\u0642\u0627\u0621 \u0627\u0644\u0644\u0647\u060c \u064a\u064f\u0630\u064e\u0643\u0651\u0650\u0631\u0648\u0646 \u0625\u062e\u0648\u0627\u0646\u0647\u0645 \u0628\u0627\u0644\u0644\u0647 \u0648\u0642\u062f\u0631\u062a\u0647 \u0642\u0627\u0626\u0644\u064a\u0646: \u0643\u0645 \u0645\u0646 \u062c\u0645\u0627\u0639\u0629 \u0642\u0644\u064a\u0644\u0629 \u0645\u0624\u0645\u0646\u0629 \u0635\u0627\u0628\u0631\u0629\u060c \u063a\u0644\u0628\u062a \u0628\u0625\u0630\u0646 \u0627\u0644\u0644\u0647 \u0648\u0623\u0645\u0631\u0647 \u062c\u0645\u0627\u0639\u0629 \u0643\u062b\u064a\u0631\u0629 \u0643\u0627\u0641\u0631\u0629 \u0628\u0627\u063a\u064a\u0629. \u0648\u0627\u0644\u0644\u0647 \u0645\u0639 \u0627\u0644\u0635\u0627\u0628\u0631\u064a\u0646 \u0628\u062a\u0648\u0641\u064a\u0642\u0647 \u0648\u0646\u0635\u0631\u0647\u060c \u0648\u062d\u0633\u0646 \u0645\u062b\u0648\u0628\u062a\u0647.","2:250":"\u0648\u0644\u0645\u0627 \u0638\u0647\u0631\u0648\u0627 \u0644\u062c\u0627\u0644\u0648\u062a \u0648\u062c\u0646\u0648\u062f\u0647\u060c \u0648\u0631\u0623\u0648\u0627 \u0627\u0644\u062e\u0637\u0631 \u0631\u0623\u064a \u0627\u0644\u0639\u064a\u0646\u060c \u0641\u0632\u0639\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0628\u0627\u0644\u062f\u0639\u0627\u0621 \u0648\u0627\u0644\u0636\u0631\u0627\u0639\u0629 \u0642\u0627\u0626\u0644\u064a\u0646: \u0631\u0628\u0646\u0627 \u0623\u0646\u0632\u0644 \u0639\u0644\u0649 \u0642\u0644\u0648\u0628\u0646\u0627 \u0635\u0628\u0631\u064b\u0627 \u0639\u0638\u064a\u0645\u064b\u0627\u060c \u0648\u062b\u0628\u062a \u0623\u0642\u062f\u0627\u0645\u0646\u0627\u060c \u0648\u0627\u062c\u0639\u0644\u0647\u0627 \u0631\u0627\u0633\u062e\u0629 \u0641\u064a \u0642\u062a\u0627\u0644 \u0627\u0644\u0639\u062f\u0648\u060c \u0644\u0627 \u062a\u0641\u0631 \u0645\u0650\u0646 \u0647\u0648\u0644 \u0627\u0644\u062d\u0631\u0628\u060c \u0648\u0627\u0646\u0635\u0631\u0646\u0627 \u0628\u0639\u0648\u0646\u0643 \u0648\u062a\u0623\u064a\u064a\u062f\u0643 \u0639\u0644\u0649 \u0627\u0644\u0642\u0648\u0645 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646.","2:251":"\u0641\u0647\u0632\u0645\u0648\u0647\u0645 \u0628\u0625\u0630\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u0642\u062a\u0644 \u062f\u0627\u0648\u062f -\u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645- \u062c\u0627\u0644\u0648\u062a\u064e \u0642\u0627\u0626\u062f\u064e \u0627\u0644\u062c\u0628\u0627\u0628\u0631\u0629\u060c \u0648\u0623\u0639\u0637\u0649 \u0627\u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644 \u062f\u0627\u0648\u062f \u0628\u0639\u062f \u0630\u0644\u0643 \u0627\u0644\u0645\u0644\u0643 \u0648\u0627\u0644\u0646\u0628\u0648\u0629 \u0641\u064a \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644\u060c \u0648\u0639\u064e\u0644\u0651\u064e\u0645\u0647 \u0645\u0645\u0627 \u064a\u0634\u0627\u0621 \u0645\u0646 \u0627\u0644\u0639\u0644\u0648\u0645. \u0648\u0644\u0648\u0644\u0627 \u0623\u0646 \u064a\u062f\u0641\u0639 \u0627\u0644\u0644\u0647 \u0628\u0628\u0639\u0636 \u0627\u0644\u0646\u0627\u0633 -\u0648\u0647\u0645 \u0623\u0647\u0644 \u0627\u0644\u0637\u0627\u0639\u0629 \u0644\u0647 \u0648\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0647- \u0628\u0639\u0636\u064b\u0627\u060c \u0648\u0647\u0645 \u0623\u0647\u0644 \u0627\u0644\u0645\u0639\u0635\u064a\u0629 \u0644\u0644\u0647 \u0648\u0627\u0644\u0634\u0631\u0643 \u0628\u0647\u060c \u0644\u0641\u0633\u062f\u062a \u0627\u0644\u0623\u0631\u0636 \u0628\u063a\u0644\u0628\u0629 \u0627\u0644\u0643\u0641\u0631\u060c \u0648\u062a\u0645\u0643\u0651\u064f\u0646 \u0627\u0644\u0637\u063a\u064a\u0627\u0646\u060c \u0648\u0623\u0647\u0644 \u0627\u0644\u0645\u0639\u0627\u0635\u064a\u060c \u0648\u0644\u0643\u0646 \u0627\u0644\u0644\u0647 \u0630\u0648 \u0641\u0636\u0644 \u0639\u0644\u0649 \u0627\u0644\u0645\u062e\u0644\u0648\u0642\u064a\u0646 \u062c\u0645\u064a\u0639\u064b\u0627.","2:252":"\u062a\u0644\u0643 \u062d\u062c\u062c \u0627\u0644\u0644\u0647 \u0648\u0628\u0631\u0627\u0647\u064a\u0646\u0647\u060c \u0646\u0642\u0635\u0651\u064f\u0647\u0627 \u0639\u0644\u064a\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0628\u0627\u0644\u0635\u062f\u0642\u060c \u0648\u0625\u0646\u0643 \u0644\u0645\u0646 \u0627\u0644\u0645\u0631\u0633\u0644\u064a\u0646 \u0627\u0644\u0635\u0627\u062f\u0642\u064a\u0646.","2:253":"\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0631\u0633\u0644 \u0627\u0644\u0643\u0631\u0627\u0645 \u0641\u0636\u0651\u064e\u0644 \u0627\u0644\u0644\u0647 \u0628\u0639\u0636\u0647\u0645 \u0639\u0644\u0649 \u0628\u0639\u0636\u060c \u0628\u062d\u0633\u0628 \u0645\u0627 \u0645\u0646\u0651\u064e \u0627\u0644\u0644\u0647 \u0628\u0647 \u0639\u0644\u064a\u0647\u0645: \u0641\u0645\u0646\u0647\u0645 \u0645\u064e\u0646 \u0643\u0644\u0645\u0647 \u0627\u0644\u0644\u0647 \u0643\u0645\u0648\u0633\u0649 \u0648\u0645\u062d\u0645\u062f \u0639\u0644\u064a\u0647\u0645\u0627 \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0648\u0641\u064a \u0647\u0630\u0627 \u0625\u062b\u0628\u0627\u062a \u0635\u0641\u0629 \u0627\u0644\u0643\u0644\u0627\u0645 \u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644 \u0639\u0644\u0649 \u0627\u0644\u0648\u062c\u0647 \u0627\u0644\u0644\u0627\u0626\u0642 \u0628\u062c\u0644\u0627\u0644\u0647\u060c \u0648\u0645\u0646\u0647\u0645 \u0645\u064e\u0646 \u0631\u0641\u0639\u0647 \u0627\u0644\u0644\u0647 \u062f\u0631\u062c\u0627\u062a\u064d \u0639\u0627\u0644\u064a\u0629\u064b \u0643\u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0628\u0639\u0645\u0648\u0645 \u0631\u0633\u0627\u0644\u062a\u0647\u060c \u0648\u062e\u062a\u0645 \u0627\u0644\u0646\u0628\u0648\u0629 \u0628\u0647\u060c \u0648\u062a\u0641\u0636\u064a\u0644 \u0623\u0645\u062a\u0647 \u0639\u0644\u0649 \u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u0645\u0645\u060c \u0648\u063a\u064a\u0631 \u0630\u0644\u0643. \u0648\u0622\u062a\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u064a\u0633\u0649 \u0627\u0628\u0646 \u0645\u0631\u064a\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0627\u0644\u0628\u064a\u0646\u0627\u062a \u0627\u0644\u0645\u0639\u062c\u0632\u0627\u062a \u0627\u0644\u0628\u0627\u0647\u0631\u0627\u062a\u060c \u0643\u0625\u0628\u0631\u0627\u0621 \u0645\u064e\u0646 \u0648\u0644\u062f \u0623\u0639\u0645\u0649 \u0628\u0625\u0630\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0645\u064e\u0646 \u0628\u0647 \u0628\u0631\u0635 \u0628\u0625\u0630\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u0643\u0625\u062d\u064a\u0627\u0626\u0647 \u0627\u0644\u0645\u0648\u062a\u0649 \u0628\u0625\u0630\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u0623\u064a\u062f\u0647 \u0628\u062c\u0628\u0631\u064a\u0644 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645. \u0648\u0644\u0648 \u0634\u0627\u0621 \u0627\u0644\u0644\u0647 \u0623\u0644\u0627 \u064a\u0642\u062a\u062a\u0644 \u0627\u0644\u0630\u064a\u0646 \u062c\u0627\u0624\u0648\u0627 \u0645\u0650\u0646 \u0628\u0639\u062f \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0631\u0633\u0644 \u0645\u0650\u0646 \u0628\u0639\u062f \u0645\u0627 \u062c\u0627\u0621\u062a\u0647\u0645 \u0627\u0644\u0628\u064a\u0646\u0627\u062a \u0645\u0627 \u0627\u0642\u062a\u062a\u0644\u0648\u0627\u060c \u0648\u0644\u0643\u0646 \u0648\u0642\u0639 \u0627\u0644\u0627\u062e\u062a\u0644\u0627\u0641 \u0628\u064a\u0646\u0647\u0645: \u0641\u0645\u0646\u0647\u0645 \u0645\u064e\u0646 \u062b\u0628\u062a \u0639\u0644\u0649 \u0625\u064a\u0645\u0627\u0646\u0647\u060c \u0648\u0645\u0646\u0647\u0645 \u0645\u064e\u0646 \u0623\u0635\u0631 \u0639\u0644\u0649 \u0643\u0641\u0631\u0647. \u0648\u0644\u0648 \u0634\u0627\u0621 \u0627\u0644\u0644\u0647 \u0628\u0639\u062f \u0645\u0627 \u0648\u0642\u0639 \u0627\u0644\u0627\u062e\u062a\u0644\u0627\u0641 \u0628\u064a\u0646\u0647\u0645\u060c \u0627\u0644\u0645\u0648\u062c\u0628 \u0644\u0644\u0627\u0642\u062a\u062a\u0627\u0644\u060c \u0645\u0627 \u0627\u0642\u062a\u062a\u0644\u0648\u0627\u060c \u0648\u0644\u0643\u0646 \u0627\u0644\u0644\u0647 \u064a\u0648\u0641\u0642 \u0645\u064e\u0646 \u064a\u0634\u0627\u0621 \u0644\u0637\u0627\u0639\u062a\u0647 \u0648\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0647\u060c \u0648\u064a\u062e\u0630\u0644 \u0645\u064e\u0646 \u064a\u0634\u0627\u0621\u060c \u0641\u064a\u0639\u0635\u064a\u0647 \u0648\u064a\u0643\u0641\u0631 \u0628\u0647\u060c \u0641\u0647\u0648 \u064a\u0641\u0639\u0644 \u0645\u0627 \u064a\u0634\u0627\u0621 \u0648\u064a\u062e\u062a\u0627\u0631.","2:254":"\u064a\u0627 \u0645\u0646 \u0622\u0645\u0646\u062a\u0645 \u0628\u0627\u0644\u0644\u0647 \u0648\u0635\u062f\u0651\u064e\u0642\u062a\u0645 \u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u062a\u0645 \u0628\u0647\u062f\u064a\u0647 \u0623\u062e\u0631\u062c\u0648\u0627 \u0627\u0644\u0632\u0643\u0627\u0629 \u0627\u0644\u0645\u0641\u0631\u0648\u0636\u0629\u060c \u0648\u062a\u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0645\u0645\u0627 \u0623\u0639\u0637\u0627\u0643\u0645 \u0627\u0644\u0644\u0647 \u0642\u0628\u0644 \u0645\u062c\u064a\u0621 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u062d\u064a\u0646 \u0644\u0627 \u0628\u064a\u0639 \u0641\u064a\u0643\u0648\u0646 \u0631\u0628\u062d\u060c \u0648\u0644\u0627 \u0645\u0627\u0644 \u062a\u0641\u062a\u062f\u0648\u0646 \u0628\u0647 \u0623\u0646\u0641\u0633\u0643\u0645 \u0645\u0650\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0627 \u0635\u062f\u0627\u0642\u0629 \u0635\u062f\u064a\u0642 \u062a\u064f\u0646\u0642\u0630\u0643\u0645\u060c \u0648\u0644\u0627 \u0634\u0627\u0641\u0639 \u064a\u0645\u0644\u0643 \u062a\u062e\u0641\u064a\u0641 \u0627\u0644\u0639\u0630\u0627\u0628 \u0639\u0646\u0643\u0645. \u0648\u0627\u0644\u0643\u0627\u0641\u0631\u0648\u0646 \u0647\u0645 \u0627\u0644\u0638\u0627\u0644\u0645\u0648\u0646 \u0627\u0644\u0645\u062a\u062c\u0627\u0648\u0632\u0648\u0646 \u062d\u062f\u0648\u062f \u0627\u0644\u0644\u0647.","2:255":"\u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u0633\u062a\u062d\u0642 \u0627\u0644\u0623\u0644\u0648\u0647\u064a\u0629 \u0648\u0627\u0644\u0639\u0628\u0648\u062f\u064a\u0629 \u0625\u0644\u0627 \u0647\u0648\u060c \u0627\u0644\u062d\u064a\u0651\u064f \u0627\u0644\u0630\u064a \u0644\u0647 \u062c\u0645\u064a\u0639 \u0645\u0639\u0627\u0646\u064a \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u0643\u0627\u0645\u0644\u0629 \u0643\u0645\u0627 \u064a\u0644\u064a\u0642 \u0628\u062c\u0644\u0627\u0644\u0647\u060c \u0627\u0644\u0642\u0627\u0626\u0645 \u0639\u0644\u0649 \u0643\u0644 \u0634\u064a\u0621\u060c \u0644\u0627 \u062a\u0623\u062e\u0630\u0647 \u0633\u0650\u0646\u064e\u0629 \u0623\u064a: \u0646\u0639\u0627\u0633\u060c \u0648\u0644\u0627 \u0646\u0648\u0645\u060c \u0643\u0644 \u0645\u0627 \u0641\u064a \u0627\u0644\u0633\u0645\u0627\u0648\u0627\u062a \u0648\u0645\u0627 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0645\u0644\u0643 \u0644\u0647\u060c \u0648\u0644\u0627 \u064a\u062a\u062c\u0627\u0633\u0631 \u0623\u062d\u062f \u0623\u0646 \u064a\u0634\u0641\u0639 \u0639\u0646\u062f\u0647 \u0625\u0644\u0627 \u0628\u0625\u0630\u0646\u0647\u060c \u0645\u062d\u064a\u0637 \u0639\u0644\u0645\u0647 \u0628\u062c\u0645\u064a\u0639 \u0627\u0644\u0643\u0627\u0626\u0646\u0627\u062a \u0645\u0627\u0636\u064a\u0647\u0627 \u0648\u062d\u0627\u0636\u0631\u0647\u0627 \u0648\u0645\u0633\u062a\u0642\u0628\u0644\u0647\u0627\u060c \u064a\u0639\u0644\u0645 \u0645\u0627 \u0628\u064a\u0646 \u0623\u064a\u062f\u064a \u0627\u0644\u062e\u0644\u0627\u0626\u0642 \u0645\u0646 \u0627\u0644\u0623\u0645\u0648\u0631 \u0627\u0644\u0645\u0633\u062a\u0642\u0628\u0644\u0629\u060c \u0648\u0645\u0627 \u062e\u0644\u0641\u0647\u0645 \u0645\u0646 \u0627\u0644\u0623\u0645\u0648\u0631 \u0627\u0644\u0645\u0627\u0636\u064a\u0629\u060c \u0648\u0644\u0627 \u064a\u064e\u0637\u0651\u064e\u0644\u0639\u064f \u0623\u062d\u062f \u0645\u0646 \u0627\u0644\u062e\u0644\u0642 \u0639\u0644\u0649 \u0634\u064a\u0621 \u0645\u0646 \u0639\u0644\u0645\u0647 \u0625\u0644\u0627 \u0628\u0645\u0627 \u0623\u0639\u0644\u0645\u0647 \u0627\u0644\u0644\u0647 \u0648\u0623\u0637\u0644\u0639\u0647 \u0639\u0644\u064a\u0647. \u0648\u0633\u0639 \u0643\u0631\u0633\u064a\u0647 \u0627\u0644\u0633\u0645\u0627\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0627\u0644\u0643\u0631\u0633\u064a: \u0647\u0648 \u0645\u0648\u0636\u0639 \u0642\u062f\u0645\u064a \u0627\u0644\u0631\u0628 -\u062c\u0644 \u062c\u0644\u0627\u0644\u0647- \u0648\u0644\u0627 \u064a\u0639\u0644\u0645 \u0643\u064a\u0641\u064a\u062a\u0647 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647\u060c \u0648\u0644\u0627 \u064a\u062b\u0642\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u062d\u0641\u0638\u0647\u0645\u0627\u060c \u0648\u0647\u0648 \u0627\u0644\u0639\u0644\u064a \u0628\u0630\u0627\u062a\u0647 \u0648\u0635\u0641\u0627\u062a\u0647 \u0639\u0644\u0649 \u062c\u0645\u064a\u0639 \u0645\u062e\u0644\u0648\u0642\u0627\u062a\u0647\u060c \u0627\u0644\u062c\u0627\u0645\u0639 \u0644\u062c\u0645\u064a\u0639 \u0635\u0641\u0627\u062a \u0627\u0644\u0639\u0638\u0645\u0629 \u0648\u0627\u0644\u0643\u0628\u0631\u064a\u0627\u0621. \u0648\u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0629 \u0623\u0639\u0638\u0645 \u0622\u064a\u0629 \u0641\u064a \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0648\u062a\u0633\u0645\u0649: (\u0622\u064a\u0629 \u0627\u0644\u0643\u0631\u0633\u064a) .","2:256":"\u0644\u0643\u0645\u0627\u0644 \u0647\u0630\u0627 \u0627\u0644\u062f\u064a\u0646 \u0648\u0627\u062a\u0636\u0627\u062d \u0622\u064a\u0627\u062a\u0647 \u0644\u0627 \u064a\u064f\u062d\u062a\u0627\u062c \u0625\u0644\u0649 \u0627\u0644\u0625\u0643\u0631\u0627\u0647 \u0639\u0644\u064a\u0647 \u0644\u0645\u0646 \u062a\u064f\u0642\u0628\u0644 \u0645\u0646\u0647\u0645 \u0627\u0644\u062c\u0632\u064a\u0629\u060c \u0641\u0627\u0644\u062f\u0644\u0627\u0626\u0644 \u0628\u064a\u0646\u0629 \u064a\u062a\u0636\u062d \u0628\u0647\u0627 \u0627\u0644\u062d\u0642 \u0645\u0646 \u0627\u0644\u0628\u0627\u0637\u0644\u060c \u0648\u0627\u0644\u0647\u062f\u0649 \u0645\u0646 \u0627\u0644\u0636\u0644\u0627\u0644. \u0641\u064e\u0645\u064e\u0646 \u064a\u0643\u0641\u0631 \u0628\u0643\u0644 \u0645\u0627 \u0639\u064f\u0628\u0650\u062f \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647 \u0648\u064a\u0624\u0645\u0646 \u0628\u0627\u0644\u0644\u0647\u060c \u0641\u0642\u062f \u062b\u0628\u062a \u0648\u0627\u0633\u062a\u0642\u0627\u0645 \u0639\u0644\u0649 \u0627\u0644\u0637\u0631\u064a\u0642\u0629 \u0627\u0644\u0645\u062b\u0644\u0649\u060c \u0648\u0627\u0633\u062a\u0645\u0633\u0643 \u0645\u0646 \u0627\u0644\u062f\u064a\u0646 \u0628\u0623\u0642\u0648\u0649 \u0633\u0628\u0628 \u0644\u0627 \u0627\u0646\u0642\u0637\u0627\u0639 \u0644\u0647. \u0648\u0627\u0644\u0644\u0647 \u0633\u0645\u064a\u0639 \u0644\u0623\u0642\u0648\u0627\u0644 \u0639\u0628\u0627\u062f\u0647\u060c \u0639\u0644\u064a\u0645 \u0628\u0623\u0641\u0639\u0627\u0644\u0647\u0645 \u0648\u0646\u064a\u0627\u062a\u0647\u0645\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a\u0647\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643.","2:257":"\u0627\u0644\u0644\u0647 \u064a\u062a\u0648\u0644\u0649 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0628\u0646\u0635\u0631\u0647 \u0648\u062a\u0648\u0641\u064a\u0642\u0647 \u0648\u062d\u0641\u0638\u0647\u060c \u064a\u062e\u0631\u062c\u0647\u0645 \u0645\u0646 \u0638\u0644\u0645\u0627\u062a \u0627\u0644\u0643\u0641\u0631\u060c \u0625\u0644\u0649 \u0646\u0648\u0631 \u0627\u0644\u0625\u064a\u0645\u0627\u0646. \u0648\u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0623\u0646\u0635\u0627\u0631\u0647\u0645 \u0648\u0623\u0648\u0644\u064a\u0627\u0624\u0647\u0645 \u0627\u0644\u0623\u0646\u062f\u0627\u062f \u0648\u0627\u0644\u0623\u0648\u062b\u0627\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u0639\u0628\u062f\u0648\u0646\u0647\u0645 \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647\u060c \u064a\u064f\u062e\u0631\u062c\u0648\u0646\u0647\u0645 \u0645\u0646 \u0646\u0648\u0631 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0625\u0644\u0649 \u0638\u0644\u0645\u0627\u062a \u0627\u0644\u0643\u0641\u0631\u060c \u0623\u0648\u0644\u0626\u0643 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0646\u0627\u0631 \u0627\u0644\u0645\u0644\u0627\u0632\u0645\u0648\u0646 \u0644\u0647\u0627\u060c \u0647\u0645 \u0641\u064a\u0647\u0627 \u0628\u0627\u0642\u0648\u0646 \u0628\u0642\u0627\u0621 \u0623\u0628\u062f\u064a\u064b\u0627 \u0644\u0627 \u064a\u062e\u0631\u062c\u0648\u0646 \u0645\u0646\u0647\u0627.","2:258":"\u0647\u0644 \u0631\u0623\u064a\u062a -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0623\u0639\u062c\u0628 \u0645\u0650\u0646 \u062d\u0627\u0644 \u0647\u0630\u0627 \u0627\u0644\u0630\u064a \u062c\u0627\u062f\u0644 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0641\u064a \u062a\u0648\u062d\u064a\u062f \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0631\u0628\u0648\u0628\u064a\u062a\u0647; \u0644\u0623\u0646 \u0627\u0644\u0644\u0647 \u0623\u0639\u0637\u0627\u0647 \u0627\u0644\u0645\u064f\u0644\u0652\u0643 \u0641\u062a\u062c\u0628\u0651\u064e\u0631 \u0648\u0633\u0623\u0644 \u0625\u0628\u0631\u0627\u0647\u064a\u0645\u064e: \u0645\u064e\u0646 \u0631\u0628\u0651\u064f\u0643\u061f \u0641\u0642\u0627\u0644 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645: \u0631\u0628\u064a \u0627\u0644\u0630\u064a \u064a\u062d\u064a\u064a \u0627\u0644\u062e\u0644\u0627\u0626\u0642 \u0641\u062a\u062d\u064a\u0627\u060c \u0648\u064a\u0633\u0644\u0628\u0647\u0627 \u0627\u0644\u062d\u064a\u0627\u0629 \u0641\u062a\u0645\u0648\u062a\u060c \u0641\u0647\u0648 \u0627\u0644\u0645\u062a\u0641\u0631\u062f \u0628\u0627\u0644\u0625\u062d\u064a\u0627\u0621 \u0648\u0627\u0644\u0625\u0645\u0627\u062a\u0629\u060c \u0642\u0627\u0644: \u0623\u0646\u0627 \u0623\u062d\u064a\u064a \u0648\u0623\u0645\u064a\u062a\u060c \u0623\u064a \u0623\u0642\u062a\u0644 \u0645\u064e\u0646 \u0623\u0631\u062f\u062a\u064f \u0642\u064e\u062a\u0652\u0644\u064e\u0647\u060c \u0648\u0623\u0633\u062a\u0628\u0642\u064a \u0645\u064e\u0646 \u0623\u0631\u062f\u062a \u0627\u0633\u062a\u0628\u0642\u0627\u0621\u0647\u060c \u0641\u0642\u0627\u0644 \u0644\u0647 \u0625\u0628\u0631\u0627\u0647\u064a\u0645: \u0625\u0646 \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a \u0623\u0639\u0628\u062f\u0647 \u064a\u0623\u062a\u064a \u0628\u0627\u0644\u0634\u0645\u0633 \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0642\u060c \u0641\u0647\u0644 \u062a\u0633\u062a\u0637\u064a\u0639 \u062a\u063a\u064a\u064a\u0631 \u0647\u0630\u0647 \u0627\u0644\u0633\u0651\u064f\u0646\u0651\u064e\u0629 \u0627\u0644\u0625\u0644\u0647\u064a\u0629 \u0628\u0623\u0646 \u062a\u062c\u0639\u0644\u0647\u0627 \u062a\u0623\u062a\u064a \u0645\u0646 \u0627\u0644\u0645\u063a\u0631\u0628; \u0641\u062a\u062d\u064a\u0651\u064e\u0631 \u0647\u0630\u0627 \u0627\u0644\u0643\u0627\u0641\u0631 \u0648\u0627\u0646\u0642\u0637\u0639\u062a \u062d\u062c\u062a\u0647\u060c \u0634\u0623\u0646\u0647 \u0634\u0623\u0646 \u0627\u0644\u0638\u0627\u0644\u0645\u064a\u0646 \u0644\u0627 \u064a\u0647\u062f\u064a\u0647\u0645 \u0627\u0644\u0644\u0647 \u0625\u0644\u0649 \u0627\u0644\u062d\u0642 \u0648\u0627\u0644\u0635\u0648\u0627\u0628.","2:259":"\u0623\u0648 \u0647\u0644 \u0631\u0623\u064a\u062a -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0645\u062b\u0644 \u0627\u0644\u0630\u064a \u0645\u0631\u0651\u064e \u0639\u0644\u0649 \u0642\u0631\u064a\u0629 \u0642\u062f \u062a\u0647\u062f\u0651\u064e\u0645\u062a \u062f\u0648\u0631\u0647\u0627\u060c \u0648\u062e\u064e\u0648\u064e\u062a\u0652 \u0639\u0644\u0649 \u0639\u0631\u0648\u0634\u0647\u0627\u060c \u0641\u0642\u0627\u0644: \u0643\u064a\u0641 \u064a\u062d\u064a\u064a \u0627\u0644\u0644\u0647 \u0647\u0630\u0647 \u0627\u0644\u0642\u0631\u064a\u0629 \u0628\u0639\u062f \u0645\u0648\u062a\u0647\u0627\u061f \u0641\u0623\u0645\u0627\u062a\u0647 \u0627\u0644\u0644\u0647 \u0645\u0627\u0626\u0629 \u0639\u0627\u0645\u060c \u062b\u0645 \u0631\u062f\u0651\u064e \u0625\u0644\u064a\u0647 \u0631\u0648\u062d\u0647\u060c \u0648\u0642\u0627\u0644 \u0644\u0647: \u0643\u0645 \u0642\u062f\u0631 \u0627\u0644\u0632\u0645\u0627\u0646 \u0627\u0644\u0630\u064a \u0644\u0628\u062b\u062a \u0645\u064a\u062a\u064b\u0627\u061f \u0642\u0627\u0644: \u0628\u0642\u064a\u062a \u064a\u0648\u0645\u064b\u0627 \u0623\u0648 \u0628\u0639\u0636 \u064a\u0648\u0645\u060c \u0641\u0623\u062e\u0628\u0631\u0647 \u0628\u0623\u0646\u0647 \u0628\u0642\u064a \u0645\u064a\u062a\u064b\u0627 \u0645\u0627\u0626\u0629 \u0639\u0627\u0645\u060c \u0648\u0623\u0645\u0631\u0647 \u0623\u0646 \u064a\u0646\u0638\u0631 \u0625\u0644\u0649 \u0637\u0639\u0627\u0645\u0647 \u0648\u0634\u0631\u0627\u0628\u0647\u060c \u0648\u0643\u064a\u0641 \u062d\u0641\u0638\u0647\u0645\u0627 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u062a\u063a\u064a\u0651\u064f\u0631 \u0647\u0630\u0647 \u0627\u0644\u0645\u062f\u0629 \u0627\u0644\u0637\u0648\u064a\u0644\u0629\u060c \u0648\u0623\u0645\u0631\u0647 \u0623\u0646 \u064a\u0646\u0638\u0631 \u0625\u0644\u0649 \u062d\u0645\u0627\u0631\u0647 \u0643\u064a\u0641 \u0623\u062d\u064a\u0627\u0647 \u0627\u0644\u0644\u0647 \u0628\u0639\u062f \u0623\u0646 \u0643\u0627\u0646 \u0639\u0638\u0627\u0645\u064b\u0627 \u0645\u062a\u0641\u0631\u0642\u0629\u061f \u0648\u0642\u0627\u0644 \u0644\u0647: \u0648\u0644\u0646\u062c\u0639\u0644\u0643 \u0622\u064a\u0629 \u0644\u0644\u0646\u0627\u0633\u060c \u0623\u064a: \u062f\u0644\u0627\u0644\u0629 \u0638\u0627\u0647\u0631\u0629 \u0639\u0644\u0649 \u0642\u062f\u0631\u0629 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0627\u0644\u0628\u0639\u062b \u0628\u0639\u062f \u0627\u0644\u0645\u0648\u062a\u060c \u0648\u0623\u0645\u0631\u0647 \u0623\u0646 \u064a\u0646\u0638\u0631 \u0625\u0644\u0649 \u0627\u0644\u0639\u0638\u0627\u0645 \u0643\u064a\u0641 \u064a\u0631\u0641\u0639 \u0627\u0644\u0644\u0647 \u0628\u0639\u0636\u0647\u0627 \u0639\u0644\u0649 \u0628\u0639\u0636\u060c \u0648\u064a\u0635\u0644 \u0628\u0639\u0636\u0647\u0627 \u0628\u0628\u0639\u0636\u060c \u062b\u0645 \u064a\u0643\u0633\u0648\u0647\u0627 \u0628\u0639\u062f \u0627\u0644\u0627\u0644\u062a\u0626\u0627\u0645 \u0644\u062d\u0645\u064b\u0627\u060c \u062b\u0645 \u064a\u0639\u064a\u062f \u0641\u064a\u0647\u0627 \u0627\u0644\u062d\u064a\u0627\u0629\u061f \u0641\u0644\u0645\u0627 \u0627\u062a\u0636\u062d \u0644\u0647 \u0630\u0644\u0643 \u0639\u0650\u064a\u0627\u0646\u064b\u0627 \u0627\u0639\u062a\u0631\u0641 \u0628\u0639\u0638\u0645\u0629 \u0627\u0644\u0644\u0647\u060c \u0648\u0623\u0646\u0647 \u0639\u0644\u0649 \u0643\u0644 \u0634\u064a\u0621 \u0642\u062f\u064a\u0631\u060c \u0648\u0635\u0627\u0631 \u0622\u064a\u0629 \u0644\u0644\u0646\u0627\u0633.","2:260":"\u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0637\u0644\u0628 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0645\u0646 \u0631\u0628\u0647 \u0623\u0646 \u064a\u0631\u064a\u0647 \u0643\u064a\u0641\u064a\u0629 \u0627\u0644\u0628\u0639\u062b\u060c \u0641\u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u0644\u0647: \u0623\u064e\u0648\u064e \u0644\u0645 \u062a\u0624\u0645\u0646\u061f \u0642\u0627\u0644: \u0628\u0644\u0649\u060c \u0648\u0644\u0643\u0646 \u0623\u0637\u0644\u0628 \u0630\u0644\u0643 \u0644\u0623\u0632\u062f\u0627\u062f \u064a\u0642\u064a\u0646\u064b\u0627 \u0639\u0644\u0649 \u064a\u0642\u064a\u0646\u064a\u060c \u0642\u0627\u0644: \u0641\u062e\u0630 \u0623\u0631\u0628\u0639\u0629 \u0645\u0646 \u0627\u0644\u0637\u064a\u0631 \u0641\u0627\u0636\u0645\u0645\u0647\u0646 \u0625\u0644\u064a\u0643 \u0648\u0627\u0630\u0628\u062d\u0647\u0646 \u0648\u0642\u0637\u0639\u0647\u0646\u060c \u062b\u0645 \u0627\u062c\u0639\u0644 \u0639\u0644\u0649 \u0643\u0644 \u062c\u0628\u0644 \u0645\u0646\u0647\u0646 \u062c\u0632\u0621\u064b\u0627\u060c \u062b\u0645 \u0646\u0627\u062f\u0650\u0647\u0646 \u064a\u0623\u062a\u064a\u0646\u0643 \u0645\u0633\u0631\u0639\u0627\u062a. \u0641\u0646\u0627\u062f\u0649 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0641\u0625\u0630\u0627 \u0643\u0644 \u062c\u0632\u0621 \u064a\u0639\u0648\u062f \u0625\u0644\u0649 \u0645\u0648\u0636\u0639\u0647\u060c \u0648\u0625\u0630\u0627 \u0628\u0647\u0627 \u062a\u0623\u062a\u064a \u0645\u0633\u0631\u0639\u0629. \u0648\u0627\u0639\u0644\u0645 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0639\u0632\u064a\u0632 \u0644\u0627 \u064a\u063a\u0644\u0628\u0647 \u0634\u064a\u0621\u060c \u062d\u0643\u064a\u0645 \u0641\u064a \u0623\u0642\u0648\u0627\u0644\u0647 \u0648\u0623\u0641\u0639\u0627\u0644\u0647 \u0648\u0634\u0631\u0639\u0647 \u0648\u0642\u062f\u0631\u0647.","2:261":"\u0648\u0645\u0650\u0646 \u0623\u0639\u0638\u0645 \u0645\u0627 \u064a\u0646\u062a\u0641\u0639 \u0628\u0647 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0627\u0644\u0625\u0646\u0641\u0627\u0642\u064f \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647. \u0648\u0645\u062b\u0644 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u0646\u0641\u0642\u0648\u0646 \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0643\u0645\u062b\u0644 \u062d\u0628\u0629 \u0632\u064f\u0631\u0650\u0639\u062a\u0652 \u0641\u064a \u0623\u0631\u0636 \u0637\u064a\u0628\u0629\u060c \u0641\u0625\u0630\u0627 \u0628\u0647\u0627 \u0642\u062f \u0623\u062e\u0631\u062c\u062a \u0633\u0627\u0642\u064b\u0627 \u062a\u0634\u0639\u0628 \u0645\u0646\u0647\u0627 \u0633\u0628\u0639 \u0634\u0639\u0628\u060c \u0644\u0643\u0644 \u0648\u0627\u062d\u062f\u0629 \u0633\u0646\u0628\u0644\u0629\u060c \u0641\u064a \u0643\u0644 \u0633\u0646\u0628\u0644\u0629 \u0645\u0627\u0626\u0629 \u062d\u0628\u0629. \u0648\u0627\u0644\u0644\u0647 \u064a\u0636\u0627\u0639\u0641 \u0627\u0644\u0623\u062c\u0631 \u0644\u0645\u0646 \u064a\u0634\u0627\u0621\u060c \u0628\u062d\u0633\u0628 \u0645\u0627 \u064a\u0642\u0648\u0645 \u0628\u0642\u0644\u0628 \u0627\u0644\u0645\u0646\u0641\u0642 \u0645\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0627\u0644\u0625\u062e\u0644\u0627\u0635 \u0627\u0644\u062a\u0627\u0645. \u0648\u0641\u0636\u0644 \u0627\u0644\u0644\u0647 \u0648\u0627\u0633\u0639\u060c \u0648\u0647\u0648 \u0633\u0628\u062d\u0627\u0646\u0647 \u0639\u0644\u064a\u0645 \u0628\u0645\u0646 \u064a\u0633\u062a\u062d\u0642\u0647\u060c \u0645\u0637\u0644\u0639 \u0639\u0644\u0649 \u0646\u064a\u0627\u062a \u0639\u0628\u0627\u062f\u0647.","2:262":"\u0627\u0644\u0630\u064a\u0646 \u064a\u062e\u0631\u062c\u0648\u0646 \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0641\u064a \u0627\u0644\u062c\u0647\u0627\u062f \u0648\u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u062e\u064a\u0631\u060c \u062b\u0645 \u0644\u0627 \u064a\u062a\u0628\u0639\u0648\u0646 \u0645\u0627 \u0623\u0646\u0641\u0642\u0648\u0627 \u0645\u0646 \u0627\u0644\u062e\u064a\u0631\u0627\u062a \u0645\u064e\u0646\u0651\u0627\u064b \u0639\u0644\u0649 \u0645\u064e\u0646 \u0623\u0639\u0637\u064e\u0648\u0647 \u0648\u0644\u0627 \u0623\u0630\u0649 \u0628\u0642\u0648\u0644 \u0623\u0648 \u0641\u0650\u0639\u0652\u0644\u064d \u064a\u0634\u0639\u0631\u0647 \u0628\u0627\u0644\u062a\u0641\u0636\u0644 \u0639\u0644\u064a\u0647\u060c \u0644\u0647\u0645 \u062b\u0648\u0627\u0628\u0647\u0645 \u0627\u0644\u0639\u0638\u064a\u0645 \u0639\u0646\u062f \u0631\u0628\u0647\u0645\u060c \u0648\u0644\u0627 \u062e\u0648\u0641 \u0639\u0644\u064a\u0647\u0645 \u0641\u064a\u0645\u0627 \u064a\u0633\u062a\u0642\u0628\u0644\u0648\u0646\u0647 \u0645\u0646 \u0623\u0645\u0631 \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u0644\u0627 \u0647\u0645 \u064a\u062d\u0632\u0646\u0648\u0646 \u0639\u0644\u0649 \u0634\u064a\u0621 \u0641\u0627\u062a\u0647\u0645 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u062f\u0646\u064a\u0627.","2:263":"\u0643\u0644\u0627\u0645 \u0637\u064a\u0628 \u064a\u0631\u062f \u0628\u0647 \u0627\u0644\u0633\u0627\u0626\u0644\u060c \u0648\u0639\u0641\u0648 \u0639\u0645\u0627 \u0628\u062f\u0631 \u0645\u0650\u0646\u0647 \u0645\u0650\u0646 \u0625\u0644\u062d\u0627\u062d\u064d \u0641\u064a \u0627\u0644\u0633\u0624\u0627\u0644\u060c \u062e\u064a\u0631 \u0645\u0646 \u0635\u062f\u0642\u0629 \u064a\u062a\u0628\u0639\u0647\u0627 \u0645\u0646 \u0627\u0644\u0645\u062a\u0635\u062f\u0642 \u0623\u0630\u0649 \u0648\u0625\u0633\u0627\u0621\u0629. \u0648\u0627\u0644\u0644\u0647 \u063a\u0646\u064a \u0639\u0646 \u0635\u062f\u0642\u0627\u062a \u0627\u0644\u0639\u0628\u0627\u062f\u060c \u062d\u0644\u064a\u0645 \u0644\u0627 \u064a\u0639\u0627\u062c\u0644\u0647\u0645 \u0628\u0627\u0644\u0639\u0642\u0648\u0628\u0629.","2:264":"\u064a\u0627 \u0645\u0646 \u0622\u0645\u0646\u062a\u0645 \u0628\u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0622\u062e\u0631 \u0644\u0627 \u062a\u064f\u0630\u0652\u0647\u0650\u0628\u064f\u0648\u0627 \u062b\u0648\u0627\u0628 \u0645\u0627 \u062a\u062a\u0635\u062f\u0642\u0648\u0646 \u0628\u0647 \u0628\u0627\u0644\u0645\u0646\u0651\u0650 \u0648\u0627\u0644\u0623\u0630\u0649\u060c \u0641\u0647\u0630\u0627 \u0634\u0628\u064a\u0647 \u0628\u0627\u0644\u0630\u064a \u064a\u062e\u0631\u062c \u0645\u0627\u0644\u0647 \u0644\u064a\u0631\u0627\u0647 \u0627\u0644\u0646\u0627\u0633\u060c \u0641\u064a\u064f\u062b\u0646\u0648\u0627 \u0639\u0644\u064a\u0647\u060c \u0648\u0647\u0648 \u0644\u0627 \u064a\u0624\u0645\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0644\u0627 \u064a\u0648\u0642\u0646 \u0628\u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0622\u062e\u0631\u060c \u0641\u0645\u062b\u0644 \u0630\u0644\u0643 \u0645\u062b\u0644 \u062d\u062c\u0631 \u0623\u0645\u0644\u0633 \u0639\u0644\u064a\u0647 \u062a\u0631\u0627\u0628 \u0647\u0637\u0644 \u0639\u0644\u064a\u0647 \u0645\u0637\u0631 \u063a\u0632\u064a\u0631 \u0641\u0623\u0632\u0627\u062d \u0639\u0646\u0647 \u0627\u0644\u062a\u0631\u0627\u0628\u060c \u0641\u062a\u0631\u0643\u0647 \u0623\u0645\u0644\u0633 \u0644\u0627 \u0634\u064a\u0621 \u0639\u0644\u064a\u0647\u060c \u0641\u0643\u0630\u0644\u0643 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0631\u0627\u0624\u0648\u0646 \u062a\u0636\u0645\u062d\u0644\u0651\u064f \u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0639\u0646\u062f \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0627 \u064a\u062c\u062f\u0648\u0646 \u0634\u064a\u0626\u064b\u0627 \u0645\u0646 \u0627\u0644\u062b\u0648\u0627\u0628 \u0639\u0644\u0649 \u0645\u0627 \u0623\u0646\u0641\u0642\u0648\u0647. \u0648\u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u0648\u0641\u0642 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0644\u0625\u0635\u0627\u0628\u0629 \u0627\u0644\u062d\u0642 \u0641\u064a \u0646\u0641\u0642\u0627\u062a\u0647\u0645 \u0648\u063a\u064a\u0631\u0647\u0627.","2:265":"\u0648\u0645\u062b\u0644 \u0627\u0644\u0630\u064a\u0646 \u064a\u0646\u0641\u0642\u0648\u0646 \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0637\u0644\u0628\u064b\u0627 \u0644\u0631\u0636\u0627 \u0627\u0644\u0644\u0647 \u0648\u0627\u0639\u062a\u0642\u0627\u062f\u064b\u0627 \u0631\u0627\u0633\u062e\u064b\u0627 \u0628\u0635\u062f\u0642 \u0648\u0639\u062f\u0647\u060c \u0643\u0645\u062b\u0644 \u0628\u0633\u062a\u0627\u0646 \u0639\u0638\u064a\u0645 \u0628\u0623\u0631\u0636 \u0639\u0627\u0644\u064a\u0629 \u0637\u064a\u0628\u0629 \u0647\u0637\u0644\u062a \u0639\u0644\u064a\u0647 \u0623\u0645\u0637\u0627\u0631 \u063a\u0632\u064a\u0631\u0629\u060c \u0641\u062a\u0636\u0627\u0639\u0641\u062a \u062b\u0645\u0631\u0627\u062a\u0647\u060c \u0648\u0625\u0646 \u0644\u0645 \u062a\u0633\u0642\u0637 \u0639\u0644\u064a\u0647 \u0627\u0644\u0623\u0645\u0637\u0627\u0631 \u0627\u0644\u063a\u0632\u064a\u0631\u0629 \u0641\u064a\u0643\u0641\u064a\u0647 \u0631\u0630\u0627\u0630 \u0627\u0644\u0645\u0637\u0631 \u0644\u064a\u0639\u0637\u064a \u0627\u0644\u062b\u0645\u0631\u0629 \u0627\u0644\u0645\u0636\u0627\u0639\u0641\u0629\u060c \u0648\u0643\u0630\u0644\u0643 \u0646\u0641\u0642\u0627\u062a \u0627\u0644\u0645\u062e\u0644\u0635\u064a\u0646 \u062a\u064f\u0642\u0628\u0644 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0648\u062a\u064f\u0636\u0627\u0639\u0641\u060c \u0642\u0644\u0651\u064e\u062a \u0623\u0645 \u0643\u062b\u064f\u0631\u062a\u060c \u0641\u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u064f\u0637\u0651\u064e\u0644\u0650\u0639 \u0639\u0644\u0649 \u0627\u0644\u0633\u0631\u0627\u0626\u0631\u060c \u0627\u0644\u0628\u0635\u064a\u0631 \u0628\u0627\u0644\u0638\u0648\u0627\u0647\u0631 \u0648\u0627\u0644\u0628\u0648\u0627\u0637\u0646\u060c \u064a\u062b\u064a\u0628 \u0643\u0644\u0627 \u0628\u062d\u0633\u0628 \u0625\u062e\u0644\u0627\u0635\u0647.","2:266":"\u0623\u064a\u0631\u063a\u0628 \u0627\u0644\u0648\u0627\u062d\u062f \u0645\u0646\u0643\u0645 \u0623\u0646 \u064a\u0643\u0648\u0646 \u0644\u0647 \u0628\u0633\u062a\u0627\u0646 \u0641\u064a\u0647 \u0627\u0644\u0646\u062e\u064a\u0644 \u0648\u0627\u0644\u0623\u0639\u0646\u0627\u0628\u060c \u062a\u062c\u0631\u064a \u0645\u0646 \u062a\u062d\u062a \u0623\u0634\u062c\u0627\u0631\u0650\u0647 \u0627\u0644\u0645\u064a\u0627\u0647 \u0627\u0644\u0639\u0630\u0628\u0629\u060c \u0648\u0644\u0647 \u0641\u064a\u0647 \u0645\u0646 \u0643\u0644 \u0623\u0644\u0648\u0627\u0646 \u0627\u0644\u062b\u0645\u0631\u0627\u062a\u060c \u0648\u0642\u062f \u0628\u0644\u063a \u0627\u0644\u0643\u0650\u0628\u064e\u0631\u060c \u0648\u0644\u0627 \u064a\u0633\u062a\u0637\u064a\u0639 \u0623\u0646 \u064a\u063a\u0631\u0633 \u0645\u062b\u0644 \u0647\u0630\u0627 \u0627\u0644\u063a\u0631\u0633\u060c \u0648\u0644\u0647 \u0623\u0648\u0644\u0627\u062f \u0635\u063a\u0627\u0631 \u0641\u064a \u062d\u0627\u062c\u0629 \u0625\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0628\u0633\u062a\u0627\u0646 \u0648\u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u062d\u0627\u0644\u0629 \u0647\u0628\u0651\u064e\u062a \u0639\u0644\u064a\u0647 \u0631\u064a\u062d \u0634\u062f\u064a\u062f\u0629\u060c \u0641\u064a\u0647\u0627 \u0646\u0627\u0631 \u0645\u062d\u0631\u0642\u0629 \u0641\u0623\u062d\u0631\u0642\u062a\u0647; \u0648\u0647\u0643\u0630\u0627 \u062d\u0627\u0644 \u063a\u064a\u0631 \u0627\u0644\u0645\u062e\u0644\u0635\u064a\u0646 \u0641\u064a \u0646\u0641\u0642\u0627\u062a\u0647\u0645\u060c \u064a\u0623\u062a\u0648\u0646 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u0648\u0644\u0627 \u062d\u0633\u0646\u0629 \u0644\u0647\u0645. \u0648\u0628\u0645\u062b\u0644 \u0647\u0630\u0627 \u0627\u0644\u0628\u064a\u0627\u0646 \u064a\u0628\u064a\u0651\u0650\u0646 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0645\u0627 \u064a\u0646\u0641\u0639\u0643\u0645; \u0643\u064a \u062a\u062a\u0623\u0645\u0644\u0648\u0627\u060c \u0641\u062a\u062e\u0644\u0635\u0648\u0627 \u0646\u0641\u0642\u0627\u062a\u0643\u0645 \u0644\u0644\u0647.","2:267":"\u064a\u0627 \u0645\u0646 \u0622\u0645\u0646\u062a\u0645 \u0628\u064a \u0648\u0627\u062a\u0628\u0639\u062a\u0645 \u0631\u0633\u0644\u064a \u0623\u0646\u0641\u0642\u0648\u0627 \u0645\u0646 \u0627\u0644\u062d\u0644\u0627\u0644 \u0627\u0644\u0637\u064a\u0628 \u0627\u0644\u0630\u064a \u0643\u0633\u0628\u062a\u0645\u0648\u0647 \u0648\u0645\u0645\u0627 \u0623\u062e\u0631\u062c\u0646\u0627 \u0644\u0643\u0645 \u0645\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0644\u0627 \u062a\u0642\u0635\u062f\u0648\u0627 \u0627\u0644\u0631\u062f\u064a\u0621 \u0645\u0646\u0647 \u0644\u062a\u0639\u0637\u0648\u0647 \u0627\u0644\u0641\u0642\u0631\u0627\u0621\u060c \u0648\u0644\u0648 \u0623\u064f\u0639\u0637\u0650\u064a\u062a\u0645\u0648\u0647 \u0644\u0645 \u062a\u0623\u062e\u0630\u0648\u0647 \u0625\u0644\u0627 \u0625\u0630\u0627 \u062a\u063a\u0627\u0636\u064a\u062a\u0645 \u0639\u0645\u0627 \u0641\u064a\u0647 \u0645\u0646 \u0631\u062f\u0627\u0621\u0629 \u0648\u0646\u0642\u0635. \u0641\u0643\u064a\u0641 \u062a\u0631\u0636\u0648\u0646 \u0644\u0644\u0647 \u0645\u0627 \u0644\u0627 \u062a\u0631\u0636\u0648\u0646\u0647 \u0644\u0623\u0646\u0641\u0633\u0643\u0645\u061f \u0648\u0627\u0639\u0644\u0645\u0648\u0627 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a \u0631\u0632\u0642\u0643\u0645 \u063a\u0646\u064a \u0639\u0646 \u0635\u062f\u0642\u0627\u062a\u0643\u0645\u060c \u0645\u0633\u062a\u062d\u0642 \u0644\u0644\u062b\u0646\u0627\u0621\u060c \u0645\u062d\u0645\u0648\u062f \u0641\u064a \u0643\u0644 \u062d\u0627\u0644.","2:268":"\u0647\u0630\u0627 \u0627\u0644\u0628\u062e\u0644 \u0648\u0627\u062e\u062a\u064a\u0627\u0631 \u0627\u0644\u0631\u062f\u064a\u0621 \u0644\u0644\u0635\u062f\u0642\u0629 \u0645\u0646 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0627\u0644\u0630\u064a \u064a\u062e\u0648\u0641\u0643\u0645 \u0627\u0644\u0641\u0642\u0631\u060c \u0648\u064a\u063a\u0631\u064a\u0643\u0645 \u0628\u0627\u0644\u0628\u062e\u0644\u060c \u0648\u064a\u0623\u0645\u0631\u0643\u0645 \u0628\u0627\u0644\u0645\u0639\u0627\u0635\u064a \u0648\u0645\u062e\u0627\u0644\u0641\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649 \u064a\u0639\u062f\u0643\u0645 \u0639\u0644\u0649 \u0625\u0646\u0641\u0627\u0642\u0643\u0645 \u063a\u0641\u0631\u0627\u0646\u064b\u0627 \u0644\u0630\u0646\u0648\u0628\u0643\u0645 \u0648\u0631\u0632\u0642\u0627 \u0648\u0627\u0633\u0639\u0627. \u0648\u0627\u0644\u0644\u0647 \u0648\u0627\u0633\u0639 \u0627\u0644\u0641\u0636\u0644\u060c \u0639\u0644\u064a\u0645 \u0628\u0627\u0644\u0646\u064a\u0651\u064e\u0627\u062a \u0648\u0627\u0644\u0623\u0639\u0645\u0627\u0644.","2:269":"\u064a\u0624\u062a\u064a \u0627\u0644\u0644\u0647 \u0627\u0644\u0625\u0635\u0627\u0628\u0629 \u0641\u064a \u0627\u0644\u0642\u0648\u0644 \u0648\u0627\u0644\u0641\u0639\u0644 \u0645\u064e\u0646 \u064a\u0634\u0627\u0621 \u0645\u0646 \u0639\u0628\u0627\u062f\u0647\u060c \u0648\u0645\u0646 \u0623\u0646\u0639\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0628\u0630\u0644\u0643 \u0641\u0642\u062f \u0623\u0639\u0637\u0627\u0647 \u062e\u064a\u0631\u064b\u0627 \u0643\u062b\u064a\u0631\u064b\u0627. \u0648\u0645\u0627 \u064a\u062a\u0630\u0643\u0631 \u0647\u0630\u0627 \u0648\u064a\u0646\u062a\u0641\u0639 \u0628\u0647 \u0625\u0644\u0627 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0639\u0642\u0648\u0644 \u0627\u0644\u0645\u0633\u062a\u0646\u064a\u0631\u0629 \u0628\u0646\u0648\u0631 \u0627\u0644\u0644\u0647 \u0648\u0647\u062f\u0627\u064a\u062a\u0647.","2:270":"\u0648\u0645\u0627 \u0623\u0639\u0637\u064a\u062a\u0645 \u0645\u0646 \u0645\u0627\u0644 \u0623\u0648 \u063a\u064a\u0631\u0647 \u0643\u062b\u064a\u0631 \u0623\u0648 \u0642\u0644\u064a\u0644 \u062a\u062a\u0635\u062f\u0642\u0648\u0646 \u0628\u0647 \u0627\u0628\u062a\u063a\u0627\u0621 \u0645\u0631\u0636\u0627\u062a \u0627\u0644\u0644\u0647 \u0623\u0648 \u0623\u0648\u062c\u0628\u062a\u0645 \u0639\u0644\u0649 \u0623\u0646\u0641\u0633\u0643\u0645 \u0634\u064a\u0626\u064b\u0627 \u0645\u0646 \u0645\u0627\u0644 \u0623\u0648 \u063a\u064a\u0631\u0647\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u0639\u0644\u0645\u0647\u060c \u0648\u0647\u0648 \u0627\u0644\u0645\u064f\u0637\u0651\u064e\u0644\u0650\u0639 \u0639\u0644\u0649 \u0646\u064a\u0627\u062a\u0643\u0645\u060c \u0648\u0633\u0648\u0641 \u064a\u062b\u064a\u0628\u0643\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643. \u0648\u0645\u064e\u0646 \u0645\u0646\u0639 \u062d\u0642 \u0627\u0644\u0644\u0647 \u0641\u0647\u0648 \u0638\u0627\u0644\u0645\u060c \u0648\u0627\u0644\u0638\u0627\u0644\u0645\u0648\u0646 \u0644\u064a\u0633 \u0644\u0647\u0645 \u0623\u0646\u0635\u0627\u0631 \u064a\u0645\u0646\u0639\u0648\u0646\u0647\u0645 \u0645\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647.","2:271":"\u0625\u0646 \u062a\u0638\u0647\u0631\u0648\u0627 \u0645\u0627 \u062a\u062a\u0635\u062f\u0642\u0648\u0646 \u0628\u0647 \u0644\u0644\u0647 \u0641\u0646\u0650\u0639\u0652\u0645\u064e \u0645\u0627 \u062a\u0635\u062f\u0642\u062a\u0645 \u0628\u0647\u060c \u0648\u0625\u0646 \u062a\u0633\u0631\u0651\u064f\u0648\u0627 \u0628\u0647\u0627\u060c \u0648\u062a\u0639\u0637\u0648\u0647\u0627 \u0627\u0644\u0641\u0642\u0631\u0627\u0621 \u0641\u0647\u0630\u0627 \u0623\u0641\u0636\u0644 \u0644\u0643\u0645; \u0644\u0623\u0646\u0647 \u0623\u0628\u0639\u062f \u0639\u0646 \u0627\u0644\u0631\u064a\u0627\u0621\u060c \u0648\u0641\u064a \u0627\u0644\u0635\u062f\u0642\u0629 -\u0645\u0639 \u0627\u0644\u0625\u062e\u0644\u0627\u0635- \u0645\u062d\u0648 \u0644\u0630\u0646\u0648\u0628\u0643\u0645. \u0648\u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a \u064a\u0639\u0644\u0645 \u062f\u0642\u0627\u0626\u0642 \u0627\u0644\u0623\u0645\u0648\u0631\u060c \u0644\u0627 \u064a\u062e\u0641\u0649 \u0639\u0644\u064a\u0647 \u0634\u064a\u0621 \u0645\u0646 \u0623\u062d\u0648\u0627\u0644\u0643\u0645\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a \u0643\u0644\u0627 \u0628\u0639\u0645\u0644\u0647.","2:272":"\u0644\u0633\u062a -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0645\u0633\u0626\u0648\u0644\u0627 \u0639\u0646 \u062a\u0648\u0641\u064a\u0642 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0644\u0644\u0647\u062f\u0627\u064a\u0629\u060c \u0648\u0644\u0643\u0646 \u0627\u0644\u0644\u0647 \u064a\u0634\u0631\u062d \u0635\u062f\u0648\u0631 \u0645\u064e\u0646 \u064a\u0634\u0627\u0621 \u0644\u062f\u064a\u0646\u0647\u060c \u0648\u064a\u0648\u0641\u0642\u0647 \u0644\u0647. \u0648\u0645\u0627 \u062a\u0628\u0630\u0644\u0648\u0627 \u0645\u0646 \u0645\u0627\u0644 \u064a\u064e\u0639\u064f\u062f\u0652 \u0639\u0644\u064a\u0643\u0645 \u0646\u064e\u0641\u0652\u0639\u064f\u0647 \u0645\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0644\u0627 \u064a\u0646\u0641\u0642\u0648\u0646 \u0625\u0644\u0627 \u0637\u0644\u0628\u064b\u0627 \u0644\u0645\u0631\u0636\u0627\u0629 \u0627\u0644\u0644\u0647. \u0648\u0645\u0627 \u062a\u0646\u0641\u0642\u0648\u0627 \u0645\u0646 \u0645\u0627\u0644 -\u0645\u062e\u0644\u0635\u064a\u0646 \u0644\u0644\u0647- \u062a\u0648\u0641\u0648\u0627 \u062b\u0648\u0627\u0628\u0647\u060c \u0648\u0644\u0627 \u062a\u064f\u0646\u0652\u0642\u064e\u0635\u064f\u0648\u0627 \u0634\u064a\u0626\u0627 \u0645\u0646 \u0630\u0644\u0643. \u0648\u0641\u064a \u0627\u0644\u0622\u064a\u0629 \u0625\u062b\u0628\u0627\u062a \u0635\u0641\u0629 \u0627\u0644\u0648\u062c\u0647 \u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0644\u0649 \u0645\u0627 \u064a\u0644\u064a\u0642 \u0628\u0647 \u0633\u0628\u062d\u0627\u0646\u0647.","2:273":"\u0627\u062c\u0639\u0644\u0648\u0627 \u0635\u062f\u0642\u0627\u062a\u0643\u0645 \u0644\u0641\u0642\u0631\u0627\u0621 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0644\u0627 \u064a\u0633\u062a\u0637\u064a\u0639\u0648\u0646 \u0627\u0644\u0633\u0641\u0631; \u0637\u0644\u0628\u064b\u0627 \u0644\u0644\u0631\u0632\u0642 \u0644\u0627\u0634\u062a\u063a\u0627\u0644\u0647\u0645 \u0628\u0627\u0644\u062c\u0647\u0627\u062f \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647\u060c \u064a\u0638\u0646\u0647\u0645 \u0645\u064e\u0646 \u0644\u0627 \u064a\u0639\u0631\u0641\u0647\u0645 \u063a\u064a\u0631 \u0645\u062d\u062a\u0627\u062c\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u0635\u062f\u0642\u0629; \u0644\u062a\u0639\u0641\u0641\u0647\u0645 \u0639\u0646 \u0627\u0644\u0633\u0624\u0627\u0644\u060c \u062a\u0639\u0631\u0641\u0647\u0645 \u0628\u0639\u0644\u0627\u0645\u0627\u062a\u0647\u0645 \u0648\u0622\u062b\u0627\u0631 \u0627\u0644\u062d\u0627\u062c\u0629 \u0641\u064a\u0647\u0645\u060c \u0644\u0627 \u064a\u0633\u0623\u0644\u0648\u0646 \u0627\u0644\u0646\u0627\u0633 \u0628\u0627\u0644\u0643\u064f\u0644\u064a\u0651\u064e\u0629\u060c \u0648\u0625\u0646 \u0633\u0623\u0644\u0648\u0627 \u0627\u0636\u0637\u0631\u0627\u0631\u064b\u0627 \u0644\u0645 \u064a\u064f\u0644\u0650\u062d\u0651\u064f\u0648\u0627 \u0641\u064a \u0627\u0644\u0633\u0624\u0627\u0644. \u0648\u0645\u0627 \u062a\u0646\u0641\u0642\u0648\u0627 \u0645\u0650\u0646 \u0645\u0627\u0644 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0641\u0644\u0627 \u064a\u062e\u0641\u0649 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0634\u064a\u0621 \u0645\u0646\u0647\u060c \u0648\u0633\u064a\u062c\u0632\u064a \u0639\u0644\u064a\u0647 \u0623\u0648\u0641\u0631 \u0627\u0644\u062c\u0632\u0627\u0621 \u0648\u0623\u062a\u0645\u0651\u064e\u0647 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629.","2:274":"\u0627\u0644\u0630\u064a\u0646 \u064a\u064f\u062e\u0652\u0631\u062c\u0648\u0646 \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0645\u0631\u0636\u0627\u0629 \u0644\u0644\u0647 \u0644\u064a\u0644\u0627 \u0648\u0646\u0647\u0627\u0631\u064b\u0627 \u0645\u0633\u0631\u0651\u0650\u064a\u0646 \u0648\u0645\u0639\u0644\u0646\u064a\u0646\u060c \u0641\u0644\u0647\u0645 \u0623\u062c\u0631\u0647\u0645 \u0639\u0646\u062f \u0631\u0628\u0647\u0645\u060c \u0648\u0644\u0627 \u062e\u0648\u0641 \u0639\u0644\u064a\u0647\u0645 \u0641\u064a\u0645\u0627 \u064a\u0633\u062a\u0642\u0628\u0644\u0648\u0646\u0647 \u0645\u0646 \u0623\u0645\u0631 \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u0644\u0627 \u0647\u0645 \u064a\u062d\u0632\u0646\u0648\u0646 \u0639\u0644\u0649 \u0645\u0627 \u0641\u0627\u062a\u0647\u0645 \u0645\u0646 \u062d\u0638\u0648\u0638 \u0627\u0644\u062f\u0646\u064a\u0627. \u0630\u0644\u0643 \u0627\u0644\u062a\u0634\u0631\u064a\u0639 \u0627\u0644\u0625\u0644\u0647\u064a \u0627\u0644\u062d\u0643\u064a\u0645 \u0647\u0648 \u0645\u0646\u0647\u0627\u062c \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0641\u064a \u0627\u0644\u0625\u0646\u0641\u0627\u0642 \u0644\u0645\u0627 \u0641\u064a\u0647 \u0645\u0650\u0646 \u0633\u062f\u0651\u0650 \u062d\u0627\u062c\u0629 \u0627\u0644\u0641\u0642\u0631\u0627\u0621 \u0641\u064a \u0643\u0631\u0627\u0645\u0629 \u0648\u0639\u0632\u0629\u060c \u0648\u062a\u0637\u0647\u064a\u0631 \u0645\u0627\u0644 \u0627\u0644\u0623\u063a\u0646\u064a\u0627\u0621\u060c \u0648\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u062a\u0639\u0627\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u0628\u0631 \u0648\u0627\u0644\u062a\u0642\u0648\u0649; \u0627\u0628\u062a\u063a\u0627\u0621 \u0648\u062c\u0647 \u0627\u0644\u0644\u0647 \u062f\u0648\u0646 \u0642\u0647\u0631 \u0623\u0648 \u0625\u0643\u0631\u0627\u0647.","2:275":"\u0627\u0644\u0630\u064a\u0646 \u064a\u062a\u0639\u0627\u0645\u0644\u0648\u0646 \u0628\u0627\u0644\u0631\u0628\u0627 -\u0648\u0647\u0648 \u0627\u0644\u0632\u064a\u0627\u062f\u0629 \u0639\u0644\u0649 \u0631\u0623\u0633 \u0627\u0644\u0645\u0627\u0644- \u0644\u0627 \u064a\u0642\u0648\u0645\u0648\u0646 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u0645\u0646 \u0642\u0628\u0648\u0631\u0647\u0645 \u0625\u0644\u0627 \u0643\u0645\u0627 \u064a\u0642\u0648\u0645 \u0627\u0644\u0630\u064a \u064a\u062a\u062e\u0628\u0637\u0647 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0645\u0646 \u0627\u0644\u062c\u0646\u0648\u0646; \u0630\u0644\u0643 \u0644\u0623\u0646\u0647\u0645 \u0642\u0627\u0644\u0648\u0627: \u0625\u0646\u0645\u0627 \u0627\u0644\u0628\u064a\u0639 \u0645\u062b\u0644 \u0627\u0644\u0631\u0628\u0627\u060c \u0641\u064a \u0623\u0646 \u0643\u0644\u0627 \u0645\u0646\u0647\u0645\u0627 \u062d\u0644\u0627\u0644\u060c \u0648\u064a\u0624\u062f\u064a \u0625\u0644\u0649 \u0632\u064a\u0627\u062f\u0629 \u0627\u0644\u0645\u0627\u0644\u060c \u0641\u0623\u0643\u0630\u0628\u0647\u0645 \u0627\u0644\u0644\u0647\u060c \u0648\u0628\u064a\u0651\u064e\u0646 \u0623\u0646\u0647 \u0623\u062d\u0644 \u0627\u0644\u0628\u064a\u0639 \u0648\u062d\u0631\u0651\u064e\u0645 \u0627\u0644\u0631\u0628\u0627; \u0644\u0645\u0627 \u0641\u064a \u0627\u0644\u0628\u064a\u0639 \u0648\u0627\u0644\u0634\u0631\u0627\u0621 \u0645\u0646 \u0646\u0641\u0639 \u0644\u0644\u0623\u0641\u0631\u0627\u062f \u0648\u0627\u0644\u062c\u0645\u0627\u0639\u0627\u062a\u060c \u0648\u0644\u0645\u0627 \u0641\u064a \u0627\u0644\u0631\u0628\u0627 \u0645\u0646 \u0627\u0633\u062a\u063a\u0644\u0627\u0644 \u0648\u0636\u064a\u0627\u0639 \u0648\u0647\u0644\u0627\u0643. \u0641\u0645\u0646 \u0628\u0644\u063a\u0647 \u0646\u0647\u064a \u0627\u0644\u0644\u0647 \u0639\u0646 \u0627\u0644\u0631\u0628\u0627 \u0641\u0627\u0631\u062a\u062f\u0639\u060c \u0641\u0644\u0647 \u0645\u0627 \u0645\u0636\u0649 \u0642\u0628\u0644 \u0623\u0646 \u064a\u0628\u0644\u063a\u0647 \u0627\u0644\u062a\u062d\u0631\u064a\u0645 \u0644\u0627 \u0625\u062b\u0645 \u0639\u0644\u064a\u0647 \u0641\u064a\u0647\u060c \u0648\u0623\u0645\u0631\u0647 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0641\u064a\u0645\u0627 \u064a\u0633\u062a\u0642\u0628\u0644 \u0645\u0646 \u0632\u0645\u0627\u0646\u0647\u060c \u0641\u0625\u0646 \u0627\u0633\u062a\u0645\u0631\u0651\u064e \u0639\u0644\u0649 \u062a\u0648\u0628\u062a\u0647 \u0641\u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u0636\u064a\u0639 \u0623\u062c\u0631 \u0627\u0644\u0645\u062d\u0633\u0646\u064a\u0646\u060c \u0648\u0645\u0646 \u0639\u0627\u062f \u0625\u0644\u0649 \u0627\u0644\u0631\u0628\u0627 \u0641\u0641\u0639\u0644\u0647 \u0628\u0639\u062f \u0628\u0644\u0648\u063a\u0647 \u0646\u0647\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u060c \u0641\u0642\u062f \u0627\u0633\u062a\u0648\u062c\u0628 \u0627\u0644\u0639\u0642\u0648\u0628\u0629\u060c \u0648\u0642\u0627\u0645\u062a \u0639\u0644\u064a\u0647 \u0627\u0644\u062d\u062c\u0629\u060c \u0648\u0644\u0647\u0630\u0627 \u0642\u0627\u0644 \u0633\u0628\u062d\u0627\u0646\u0647: {\u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e} .","2:276":"\u064a\u0630\u0647\u0628 \u0627\u0644\u0644\u0647 \u0627\u0644\u0631\u0628\u0627 \u0643\u0644\u0647 \u0623\u0648 \u064a\u062d\u0631\u0645 \u0635\u0627\u062d\u0628\u0647 \u0628\u0631\u0643\u0629 \u0645\u0627\u0644\u0647\u060c \u0641\u0644\u0627 \u064a\u0646\u062a\u0641\u0639 \u0628\u0647\u060c \u0648\u064a\u0646\u0645\u064a \u0627\u0644\u0635\u062f\u0642\u0627\u062a \u0648\u064a\u0643\u062b\u0631\u0647\u0627\u060c \u0648\u064a\u0636\u0627\u0639\u0641 \u0627\u0644\u0623\u062c\u0631 \u0644\u0644\u0645\u062a\u0635\u062f\u0642\u064a\u0646\u060c \u0648\u064a\u0628\u0627\u0631\u0643 \u0644\u0647\u0645 \u0641\u064a \u0623\u0645\u0648\u0627\u0644\u0647\u0645. \u0648\u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u062d\u0628 \u0643\u0644 \u0645\u064f\u0635\u0650\u0631\u0651\u064d \u0639\u0644\u0649 \u0643\u0641\u0631\u0647\u060c \u0645\u064f\u0633\u0652\u062a\u064e\u062d\u0650\u0644\u0651\u064d \u0623\u0643\u0644 \u0627\u0644\u0631\u0628\u0627\u060c \u0645\u062a\u0645\u0627\u062f\u064d \u0641\u064a \u0627\u0644\u0625\u062b\u0645 \u0648\u0627\u0644\u062d\u0631\u0627\u0645 \u0648\u0645\u0639\u0627\u0635\u064a \u0627\u0644\u0644\u0647.","2:277":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0639\u0645\u0644\u0648\u0627 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0637\u064a\u0628\u0629\u060c \u0648\u0623\u062f\u0651\u064e\u0648\u0627 \u0627\u0644\u0635\u0644\u0627\u0629 \u0643\u0645\u0627 \u0623\u0645\u0631 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0623\u062e\u0631\u062c\u0648\u0627 \u0632\u0643\u0627\u0629 \u0623\u0645\u0648\u0627\u0644\u0647\u0645\u060c \u0644\u0647\u0645 \u062b\u0648\u0627\u0628 \u0639\u0638\u064a\u0645 \u062e\u0627\u0635 \u0628\u0647\u0645 \u0639\u0646\u062f \u0631\u0628\u0647\u0645 \u0648\u0631\u0627\u0632\u0642\u0647\u0645\u060c \u0648\u0644\u0627 \u064a\u0644\u062d\u0642\u0647\u0645 \u062e\u0648\u0641 \u0641\u064a \u0622\u062e\u0631\u062a\u0647\u0645\u060c \u0648\u0644\u0627 \u062d\u0632\u0646 \u0639\u0644\u0649 \u0645\u0627 \u0641\u0627\u062a\u0647\u0645 \u0645\u0646 \u062d\u0638\u0648\u0638 \u062f\u0646\u064a\u0627\u0647\u0645.","2:278":"\u064a\u0627 \u0645\u0646 \u0622\u0645\u0646\u062a\u0645 \u0628\u0627\u0644\u0644\u0647 \u0648\u0627\u062a\u0628\u0639\u062a\u0645 \u0631\u0633\u0648\u0644\u0647 \u062e\u0627\u0641\u0648\u0627 \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u062a\u0631\u0643\u0648\u0627 \u0637\u0644\u0628 \u0645\u0627 \u0628\u0642\u064a \u0644\u0643\u0645 \u0645\u0646 \u0632\u064a\u0627\u062f\u0629 \u0639\u0644\u0649 \u0631\u0624\u0648\u0633 \u0623\u0645\u0648\u0627\u0644\u0643\u0645 \u0627\u0644\u062a\u064a \u0643\u0627\u0646\u062a \u0644\u0643\u0645 \u0642\u0628\u0644 \u062a\u062d\u0631\u064a\u0645 \u0627\u0644\u0631\u0628\u0627\u060c \u0625\u0646 \u0643\u0646\u062a\u0645 \u0645\u062d\u0642\u0642\u064a\u0646 \u0625\u064a\u0645\u0627\u0646\u0643\u0645 \u0642\u0648\u0644\u0627 \u0648\u0639\u0645\u0644\u0627.","2:279":"\u0641\u0625\u0646 \u0644\u0645 \u062a\u0631\u062a\u062f\u0639\u0648\u0627 \u0639\u0645\u0627 \u0646\u0647\u0627\u0643\u0645 \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0641\u0627\u0633\u062a\u064a\u0642\u0646\u0648\u0627 \u0628\u062d\u0631\u0628 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0625\u0646 \u0631\u062c\u0639\u062a\u0645 \u0625\u0644\u0649 \u0631\u0628\u0643\u0645 \u0648\u062a\u0631\u0643\u062a\u0645 \u0623\u064e\u0643\u0652\u0644\u064e \u0627\u0644\u0631\u0628\u0627 \u0641\u0644\u0643\u0645 \u0623\u064e\u062e\u0652\u0630\u064f \u0645\u0627 \u0644\u0643\u0645 \u0645\u0646 \u062f\u064a\u0648\u0646 \u062f\u0648\u0646 \u0632\u064a\u0627\u062f\u0629\u060c \u0644\u0627 \u062a\u064e\u0638\u0652\u0644\u0645\u0648\u0646 \u0623\u062d\u062f\u064b\u0627 \u0628\u0623\u062e\u0630 \u0645\u0627 \u0632\u0627\u062f \u0639\u0644\u0649 \u0631\u0624\u0648\u0633 \u0623\u0645\u0648\u0627\u0644\u0643\u0645\u060c \u0648\u0644\u0627 \u064a\u0638\u0644\u0645\u0643\u0645 \u0623\u062d\u062f \u0628\u0646\u0642\u0635 \u0645\u0627 \u0623\u0642\u0631\u0636\u062a\u0645.","2:280":"\u0648\u0625\u0646 \u0643\u0627\u0646 \u0627\u0644\u0645\u062f\u064a\u0646 \u063a\u064a\u0631 \u0642\u0627\u062f\u0631 \u0639\u0644\u0649 \u0627\u0644\u0633\u062f\u0627\u062f \u0641\u0623\u0645\u0647\u0644\u0648\u0647 \u0625\u0644\u0649 \u0623\u0646 \u064a\u064a\u0633\u0651\u0650\u0631 \u0627\u0644\u0644\u0647 \u0644\u0647 \u0631\u0632\u0642\u064b\u0627 \u0641\u064a\u062f\u0641\u0639 \u0625\u0644\u064a\u0643\u0645 \u0645\u0627\u0644\u0643\u0645\u060c \u0648\u0625\u0646 \u062a\u062a\u0631\u0643\u0648\u0627 \u0631\u0623\u0633 \u0627\u0644\u0645\u0627\u0644 \u0643\u0644\u0647 \u0623\u0648 \u0628\u0639\u0636\u0647 \u0648\u062a\u0636\u0639\u0648\u0647 \u0639\u0646 \u0627\u0644\u0645\u062f\u064a\u0646 \u0641\u0647\u0648 \u0623\u0641\u0636\u0644 \u0644\u0643\u0645\u060c \u0625\u0646 \u0643\u0646\u062a\u0645 \u062a\u0639\u0644\u0645\u0648\u0646 \u0641\u064e\u0636\u0652\u0644\u064e \u0630\u0644\u0643\u060c \u0648\u0623\u0646\u0651\u064e\u0647 \u062e\u064a\u0631 \u0644\u0643\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629.","2:281":"\u0648\u0627\u062d\u0630\u0631\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633- \u064a\u0648\u0645\u064b\u0627 \u062a\u0631\u062c\u0639\u0648\u0646 \u0641\u064a\u0647 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0648\u0647\u0648 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u062d\u064a\u062b \u062a\u0639\u0631\u0636\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0644\u064a\u062d\u0627\u0633\u0628\u0643\u0645\u060c \u0641\u064a\u062c\u0627\u0632\u064a \u0643\u0644 \u0648\u0627\u062d\u062f \u0645\u0646\u0643\u0645 \u0628\u0645\u0627 \u0639\u0645\u0644 \u0645\u0646 \u062e\u064a\u0631 \u0623\u0648 \u0634\u0631 \u062f\u0648\u0646 \u0623\u0646 \u064a\u0646\u0627\u0644\u0647 \u0638\u0644\u0645. \u0648\u0641\u064a \u0627\u0644\u0622\u064a\u0629 \u0625\u0634\u0627\u0631\u0629 \u0625\u0644\u0649 \u0623\u0646 \u0627\u062c\u062a\u0646\u0627\u0628 \u0645\u0627 \u062d\u0631\u0645 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u0645\u0643\u0627\u0633\u0628 \u0627\u0644\u0631\u0628\u0648\u064a\u0629\u060c \u062a\u0643\u0645\u064a\u0644 \u0644\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u062d\u0642\u0648\u0642\u0647 \u0645\u0646 \u0625\u0642\u0627\u0645 \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0625\u064a\u062a\u0627\u0621 \u0627\u0644\u0632\u0643\u0627\u0629 \u0648\u0639\u0645\u0644 \u0627\u0644\u0635\u0627\u0644\u062d\u0627\u062a.","2:282":"\u064a\u0627 \u0645\u0646 \u0622\u0645\u0646\u062a\u0645 \u0628\u0627\u0644\u0644\u0647 \u0648\u0627\u062a\u0628\u0639\u062a\u0645 \u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f\u064b\u0627 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0625\u0630\u0627 \u062a\u0639\u0627\u0645\u0644\u062a\u0645 \u0628\u062f\u064e\u064a\u0652\u0646 \u0625\u0644\u0649 \u0648\u0642\u062a \u0645\u0639\u0644\u0648\u0645 \u0641\u0627\u0643\u062a\u0628\u0648\u0647; \u062d\u0641\u0638\u064b\u0627 \u0644\u0644\u0645\u0627\u0644 \u0648\u062f\u0641\u0639\u064b\u0627 \u0644\u0644\u0646\u0632\u0627\u0639. \u0648\u0644\u0652\u064a\u0642\u064f\u0645 \u0628\u0627\u0644\u0643\u062a\u0627\u0628\u0629 \u0631\u062c\u0644 \u0623\u0645\u064a\u0646 \u0636\u0627\u0628\u0637\u060c \u0648\u0644\u0627 \u064a\u0645\u062a\u0646\u0639 \u0645\u064e\u0646 \u0639\u0644\u0651\u064e\u0645\u0647 \u0627\u0644\u0644\u0647 \u0627\u0644\u0643\u062a\u0627\u0628\u0629 \u0639\u0646 \u0630\u0644\u0643\u060c \u0648\u0644\u0652\u064a\u0642\u0645 \u0627\u0644\u0645\u062f\u064a\u0646 \u0628\u0625\u0645\u0644\u0627\u0621 \u0645\u0627 \u0639\u0644\u064a\u0647 \u0645\u0646 \u0627\u0644\u062f\u0651\u064e\u064a\u0652\u0646\u060c \u0648\u0644\u064a\u0631\u0627\u0642\u0628 \u0631\u0628\u0647\u060c \u0648\u0644\u0627 \u064a\u0646\u0642\u0635 \u0645\u0646 \u062f\u064a\u0646\u0647 \u0634\u064a\u0626\u0627. \u0641\u0625\u0646 \u0643\u0627\u0646 \u0627\u0644\u0645\u062f\u064a\u0646 \u0645\u062d\u062c\u0648\u0631\u064b\u0627 \u0639\u0644\u064a\u0647 \u0644\u062a\u0628\u0630\u064a\u0631\u0647 \u0648\u0625\u0633\u0631\u0627\u0641\u0647\u060c \u0623\u0648 \u0643\u0627\u0646 \u0635\u063a\u064a\u0631\u064b\u0627 \u0623\u0648 \u0645\u062c\u0646\u0648\u0646\u064b\u0627\u060c \u0623\u0648 \u0644\u0627 \u064a\u0633\u062a\u0637\u064a\u0639 \u0627\u0644\u0646\u0637\u0642 \u0644\u062e\u0631\u0633 \u0628\u0647 \u0623\u0648 \u0639\u062f\u0645 \u0642\u062f\u0631\u0629 \u0643\u0627\u0645\u0644\u0629 \u0639\u0644\u0649 \u0627\u0644\u0643\u0644\u0627\u0645\u060c \u0641\u0644\u064a\u062a\u0648\u0644\u0651\u064e \u0627\u0644\u0625\u0645\u0644\u0627\u0621 \u0639\u0646 \u0627\u0644\u0645\u062f\u064a\u0646 \u0627\u0644\u0642\u0627\u0626\u0645 \u0628\u0623\u0645\u0631\u0647\u060c \u0648\u0627\u0637\u0644\u0628\u0648\u0627 \u0634\u0647\u0627\u062f\u0629 \u0631\u062c\u0644\u064a\u0646 \u0645\u0633\u0644\u0645\u064e\u064a\u0652\u0646 \u0628\u0627\u0644\u0650\u063a\u064e\u064a\u0652\u0646 \u0639\u0627\u0642\u0644\u064e\u064a\u0652\u0646 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0639\u062f\u0627\u0644\u0629. \u0641\u0625\u0646 \u0644\u0645 \u064a\u0648\u062c\u062f \u0631\u062c\u0644\u0627\u0646\u060c \u0641\u0627\u0637\u0644\u0628\u0648\u0627 \u0634\u0647\u0627\u062f\u0629 \u0631\u062c\u0644 \u0648\u0627\u0645\u0631\u0623\u062a\u064a\u0646 \u062a\u0631\u0636\u0648\u0646 \u0634\u0647\u0627\u062f\u062a\u0647\u0645\u060c \u062d\u062a\u0649 \u0625\u0630\u0627 \u0646\u064e\u0633\u0650\u064a\u064e\u062a\u0652 \u0625\u062d\u062f\u0627\u0647\u0645\u0627 \u0630\u0643\u0651\u064e\u0631\u062a\u0647\u0627 \u0627\u0644\u0623\u062e\u0631\u0649\u060c \u0648\u0639\u0644\u0649 \u0627\u0644\u0634\u0647\u062f\u0627\u0621 \u0623\u0646 \u064a\u062c\u064a\u0628\u0648\u0627 \u0645\u064e\u0646 \u062f\u0639\u0627\u0647\u0645 \u0625\u0644\u0649 \u0627\u0644\u0634\u0647\u0627\u062f\u0629\u060c \u0648\u0639\u0644\u064a\u0647\u0645 \u0623\u062f\u0627\u0624\u0647\u0627 \u0625\u0630\u0627 \u0645\u0627 \u062f\u0639\u0648\u0627 \u0625\u0644\u064a\u0647\u0627\u060c \u0648\u0644\u0627 \u062a\u064e\u0645\u064e\u0644\u0651\u064f\u0648\u0627 \u0645\u0646 \u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u062f\u0651\u064e\u064a\u0646 \u0642\u0644\u064a\u0644\u0627 \u0623\u0648 \u0643\u062b\u064a\u0631\u064b\u0627 \u0625\u0644\u0649 \u0648\u0642\u062a\u0647 \u0627\u0644\u0645\u0639\u0644\u0648\u0645. \u0630\u0644\u0643\u0645 \u0623\u0639\u062f\u0644 \u0641\u064a \u0634\u0631\u0639 \u0627\u0644\u0644\u0647 \u0648\u0647\u062f\u064a\u0647\u060c \u0648\u0623\u0639\u0638\u0645 \u0639\u0648\u0646\u064b\u0627 \u0639\u0644\u0649 \u0625\u0642\u0627\u0645\u0629 \u0627\u0644\u0634\u0647\u0627\u062f\u0629 \u0648\u0623\u062f\u0627\u0626\u0647\u0627\u060c \u0648\u0623\u0642\u0631\u0628 \u0625\u0644\u0649 \u0646\u0641\u064a \u0627\u0644\u0634\u0643 \u0641\u064a \u062c\u0646\u0633 \u0627\u0644\u062f\u0651\u064e\u064a\u0646 \u0648\u0642\u062f\u0631\u0647 \u0648\u0623\u062c\u0644\u0647. \u0644\u0643\u0646 \u0625\u0646 \u0643\u0627\u0646\u062a \u0627\u0644\u0645\u0633\u0623\u0644\u0629 \u0645\u0633\u0623\u0644\u0629 \u0628\u064a\u0639 \u0648\u0634\u0631\u0627\u0621\u060c \u0628\u0623\u062e\u0630 \u0633\u0644\u0639\u0629 \u0648\u062f\u0641\u0639 \u062b\u0645\u0646\u0647\u0627 \u0641\u064a \u0627\u0644\u062d\u0627\u0644\u060c \u0641\u0644\u0627 \u062d\u0627\u062c\u0629 \u0625\u0644\u0649 \u0627\u0644\u0643\u062a\u0627\u0628\u0629\u060c \u0648\u064a\u0633\u062a\u062d\u0628 \u0627\u0644\u0625\u0634\u0647\u0627\u062f \u0639\u0644\u0649 \u0630\u0644\u0643 \u0645\u0646\u0639\u064b\u0627 \u0644\u0644\u0646\u0632\u0627\u0639 \u0648\u0627\u0644\u0634\u0642\u0627\u0642\u060c \u0648\u0645\u0646 \u0627\u0644\u0648\u0627\u062c\u0628 \u0639\u0644\u0649 \u0627\u0644\u0634\u0627\u0647\u062f \u0648\u0627\u0644\u0643\u0627\u062a\u0628 \u0623\u062f\u0627\u0621 \u0627\u0644\u0634\u0647\u0627\u062f\u0629 \u0639\u0644\u0649 \u0648\u062c\u0647\u0647\u0627 \u0648\u0627\u0644\u0643\u062a\u0627\u0628\u0629 \u0643\u0645\u0627 \u0623\u0645\u0631 \u0627\u0644\u0644\u0647. \u0648\u0644\u0627 \u064a\u062c\u0648\u0632 \u0644\u0635\u0627\u062d\u0628 \u0627\u0644\u062d\u0642 \u0648\u0645\u064e\u0646 \u0639\u0644\u064a\u0647 \u0627\u0644\u062d\u0642 \u0627\u0644\u0625\u0636\u0631\u0627\u0631 \u0628\u0627\u0644\u0643\u064f\u062a\u0651\u064e\u0627\u0628 \u0648\u0627\u0644\u0634\u0647\u0648\u062f\u060c \u0648\u0643\u0630\u0644\u0643 \u0644\u0627 \u064a\u062c\u0648\u0632 \u0644\u0644\u0643\u064f\u062a\u0651\u064e\u0627\u0628 \u0648\u0627\u0644\u0634\u0647\u0648\u062f \u0623\u0646 \u064a\u0636\u0627\u0631\u0651\u064f\u0648\u0627 \u0628\u0645\u0646 \u0627\u062d\u062a\u0627\u062c \u0625\u0644\u0649 \u0643\u062a\u0627\u0628\u062a\u0647\u0645 \u0623\u0648 \u0634\u0647\u0627\u062f\u062a\u0647\u0645\u060c \u0648\u0625\u0646 \u062a\u0641\u0639\u0644\u0648\u0627 \u0645\u0627 \u0646\u0647\u064a\u062a\u0645 \u0639\u0646\u0647 \u0641\u0625\u0646\u0647 \u062e\u0631\u0648\u062c \u0639\u0646 \u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647\u060c \u0648\u0639\u0627\u0642\u0628\u0629 \u0630\u0644\u0643 \u062d\u0627\u0644\u0651\u064e\u0629 \u0628\u0643\u0645. \u0648\u062e\u0627\u0641\u0648\u0627 \u0627\u0644\u0644\u0647 \u0641\u064a \u062c\u0645\u064a\u0639 \u0645\u0627 \u0623\u0645\u0631\u0643\u0645 \u0628\u0647\u060c \u0648\u0646\u0647\u0627\u0643\u0645 \u0639\u0646\u0647\u060c \u0648\u064a\u0639\u0644\u0645\u0643\u0645 \u0627\u0644\u0644\u0647 \u062c\u0645\u064a\u0639 \u0645\u0627 \u064a\u0635\u0644\u062d \u062f\u0646\u064a\u0627\u0643\u0645 \u0648\u0623\u062e\u0631\u0627\u0643\u0645. \u0648\u0627\u0644\u0644\u0647 \u0628\u0643\u0644 \u0634\u064a\u0621 \u0639\u0644\u064a\u0645\u060c \u0641\u0644\u0627 \u064a\u062e\u0641\u0649 \u0639\u0644\u064a\u0647 \u0634\u064a\u0621 \u0645\u0646 \u0623\u0645\u0648\u0631\u0643\u0645\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a\u0643\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643.","2:283":"\u0648\u0625\u0646 \u0643\u0646\u062a\u0645 \u0645\u0633\u0627\u0641\u0631\u064a\u0646 \u0648\u0644\u0645 \u062a\u062c\u062f\u0648\u0627 \u0645\u064e\u0646 \u064a\u0643\u062a\u0628 \u0644\u0643\u0645 \u0641\u0627\u062f\u0641\u0639\u0648\u0627 \u0625\u0644\u0649 \u0635\u0627\u062d\u0628 \u0627\u0644\u062d\u0642 \u0634\u064a\u0626\u064b\u0627 \u064a\u0643\u0648\u0646 \u0639\u0646\u062f\u0647 \u0636\u0645\u0627\u0646\u064b\u0627 \u0644\u062d\u0642\u0651\u0650\u0647 \u0625\u0644\u0649 \u0623\u0646 \u064a\u0631\u062f\u0651\u064e \u0627\u0644\u0645\u062f\u064a\u0646\u064f \u0645\u0627 \u0639\u0644\u064a\u0647 \u0645\u0646 \u062f\u064a\u0646\u060c \u0641\u0625\u0646 \u0648\u062b\u0642 \u0628\u0639\u0636\u0643\u0645 \u0628\u0628\u0639\u0636 \u0641\u0644\u0627 \u062d\u0631\u062c \u0641\u064a \u062a\u0631\u0643 \u0627\u0644\u0643\u062a\u0627\u0628\u0629 \u0648\u0627\u0644\u0625\u0634\u0647\u0627\u062f \u0648\u0627\u0644\u0631\u0647\u0646\u060c \u0648\u064a\u0628\u0642\u0649 \u0627\u0644\u062f\u0651\u064e\u064a\u0646 \u0623\u0645\u0627\u0646\u0629 \u0641\u064a \u0630\u0645\u0651\u064e\u0629 \u0627\u0644\u0645\u062f\u064a\u0646\u060c \u0639\u0644\u064a\u0647 \u0623\u062f\u0627\u0624\u0647\u060c \u0648\u0639\u0644\u064a\u0647 \u0623\u0646 \u064a\u0631\u0627\u0642\u0628 \u0627\u0644\u0644\u0647 \u0641\u0644\u0627 \u064a\u062e\u0648\u0646 \u0635\u0627\u062d\u0628\u0647. \u0641\u0625\u0646 \u0623\u0646\u0643\u0631 \u0627\u0644\u0645\u062f\u064a\u0646 \u0645\u0627 \u0639\u0644\u064a\u0647 \u0645\u0646 \u062f\u064a\u0646\u060c \u0648\u0643\u0627\u0646 \u0647\u0646\u0627\u0643 \u0645\u064e\u0646 \u062d\u0636\u0631 \u0648\u0634\u0647\u062f\u060c \u0641\u0639\u0644\u064a\u0647 \u0623\u0646 \u064a\u0638\u0647\u0631 \u0634\u0647\u0627\u062f\u062a\u0647\u060c \u0648\u0645\u0646 \u0623\u062e\u0641\u0649 \u0647\u0630\u0647 \u0627\u0644\u0634\u0647\u0627\u062f\u0629 \u0641\u0647\u0648 \u0635\u0627\u062d\u0628 \u0642\u0644\u0628 \u063a\u0627\u062f\u0631 \u0641\u0627\u062c\u0631. \u0648\u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u064f\u0637\u0651\u064e\u0644\u0650\u0639 \u0639\u0644\u0649 \u0627\u0644\u0633\u0631\u0627\u0626\u0631\u060c \u0627\u0644\u0645\u062d\u064a\u0637 \u0639\u0644\u0645\u0647 \u0628\u0643\u0644 \u0623\u0645\u0648\u0631\u0643\u0645\u060c \u0633\u064a\u062d\u0627\u0633\u0628\u0643\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643.","2:284":"\u0644\u0644\u0647 \u0645\u0644\u0643 \u0627\u0644\u0633\u0645\u0627\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636 \u0648\u0645\u0627 \u0641\u064a\u0647\u0645\u0627 \u0645\u0644\u0643\u064b\u0627 \u0648\u062a\u062f\u0628\u064a\u0631\u064b\u0627 \u0648\u0625\u062d\u0627\u0637\u0629\u060c \u0644\u0627 \u064a\u062e\u0641\u0649 \u0639\u0644\u064a\u0647 \u0634\u064a\u0621. \u0648\u0645\u0627 \u062a\u0638\u0647\u0631\u0648\u0647 \u0645\u0645\u0627 \u0641\u064a \u0623\u0646\u0641\u0633\u0643\u0645 \u0623\u0648 \u062a\u062e\u0641\u0648\u0647 \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u0639\u0644\u0645\u0647\u060c \u0648\u0633\u064a\u062d\u0627\u0633\u0628\u0643\u0645 \u0628\u0647\u060c \u0641\u064a\u0639\u0641\u0648 \u0639\u0645\u0646 \u064a\u0634\u0627\u0621\u060c \u0648\u064a\u0624\u0627\u062e\u0630 \u0645\u0646 \u064a\u0634\u0627\u0621. \u0648\u0627\u0644\u0644\u0647 \u0642\u0627\u062f\u0631 \u0639\u0644\u0649 \u0643\u0644 \u0634\u064a\u0621. \u0648\u0642\u062f \u0623\u0643\u0631\u0645 \u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0628\u0639\u062f \u0630\u0644\u0643 \u0641\u0639\u0641\u0627 \u0639\u0646 \u062d\u062f\u064a\u062b \u0627\u0644\u0646\u0641\u0633 \u0648\u062e\u0637\u0631\u0627\u062a \u0627\u0644\u0642\u0644\u0628 \u0645\u0627 \u0644\u0645 \u064a\u062a\u0628\u0639\u0647\u0627 \u0643\u0644\u0627\u0645 \u0623\u0648 \u0639\u0645\u0644\u060c \u0643\u0645\u0627 \u062b\u0628\u062a \u0630\u0644\u0643 \u0639\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645.","2:285":"\u0635\u062f\u0651\u064e\u0642 \u0648\u0623\u064a\u0642\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0628\u0645\u0627 \u0623\u0648\u062d\u064a \u0625\u0644\u064a\u0647 \u0645\u0646 \u0631\u0628\u0647 \u0648\u062d\u064f\u0642\u0651\u064e \u0644\u0647 \u0623\u0646 \u064a\u064f\u0648\u0642\u0646\u060c \u0648\u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0643\u0630\u0644\u0643 \u0635\u062f\u0642\u0648\u0627 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0639\u0638\u064a\u0645\u060c \u0643\u0644 \u0645\u0646\u0647\u0645 \u0635\u062f\u0651\u064e\u0642 \u0628\u0627\u0644\u0644\u0647 \u0631\u0628\u0627\u064b \u0648\u0625\u0644\u0647\u064b\u0627 \u0645\u062a\u0635\u0641\u064b\u0627 \u0628\u0635\u0641\u0627\u062a \u0627\u0644\u062c\u0644\u0627\u0644 \u0648\u0627\u0644\u0643\u0645\u0627\u0644\u060c \u0648\u0623\u0646 \u0644\u0644\u0647 \u0645\u0644\u0627\u0626\u0643\u0629 \u0643\u0631\u0627\u0645\u064b\u0627\u060c \u0648\u0623\u0646\u0647 \u0623\u0646\u0632\u0644 \u0643\u062a\u0628\u064b\u0627\u060c \u0648\u0623\u0631\u0633\u0644 \u0625\u0644\u0649 \u062e\u0644\u0642\u0647 \u0631\u0633\u0644\u0627 \u0644\u0627 \u0646\u0624\u0645\u0646 -\u0646\u062d\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646- \u0628\u0628\u0639\u0636\u0647\u0645 \u0648\u0646\u0646\u0643\u0631 \u0628\u0639\u0636\u0647\u0645\u060c \u0628\u0644 \u0646\u0624\u0645\u0646 \u0628\u0647\u0645 \u062c\u0645\u064a\u0639\u064b\u0627. \u0648\u0642\u0627\u0644 \u0627\u0644\u0631\u0633\u0648\u0644 \u0648\u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646: \u0633\u0645\u0639\u0646\u0627 \u064a\u0627 \u0631\u0628\u0646\u0627 \u0645\u0627 \u0623\u0648\u062d\u064a\u062a \u0628\u0647\u060c \u0648\u0623\u0637\u0639\u0646\u0627 \u0641\u064a \u0643\u0644 \u0630\u0644\u0643\u060c \u0646\u0631\u062c\u0648 \u0623\u0646 \u062a\u063a\u0641\u0631 -\u0628\u0641\u0636\u0644\u0643- \u0630\u0646\u0648\u0628\u0646\u0627\u060c \u0641\u0623\u0646\u062a \u0627\u0644\u0630\u064a \u0631\u0628\u0651\u064e\u064a\u062a\u0646\u0627 \u0628\u0645\u0627 \u0623\u0646\u0639\u0645\u062a \u0628\u0647 \u0639\u0644\u064a\u0646\u0627\u060c \u0648\u0625\u0644\u064a\u0643 -\u0648\u062d\u062f\u0643- \u0645\u0631\u062c\u0639\u0646\u0627 \u0648\u0645\u0635\u064a\u0631\u0646\u0627.","2:286":"\u062f\u064a\u0646 \u0627\u0644\u0644\u0647 \u064a\u0633\u0631 \u0644\u0627 \u0645\u0634\u0642\u0629 \u0641\u064a\u0647\u060c \u0641\u0644\u0627 \u064a\u0637\u0644\u0628 \u0627\u0644\u0644\u0647 \u0645\u0650\u0646 \u0639\u0628\u0627\u062f\u0647 \u0645\u0627 \u0644\u0627 \u064a\u0637\u064a\u0642\u0648\u0646\u0647\u060c \u0641\u0645\u0646 \u0641\u0639\u0644 \u062e\u064a\u0631\u064b\u0627 \u0646\u0627\u0644 \u062e\u064a\u0631\u064b\u0627\u060c \u0648\u0645\u0646 \u0641\u0639\u0644 \u0634\u0631\u0651\u0627\u064b \u0646\u0627\u0644 \u0634\u0631\u0651\u0627\u064b. \u0631\u0628\u0646\u0627 \u0644\u0627 \u062a\u0639\u0627\u0642\u0628\u0646\u0627 \u0625\u0646 \u0646\u0633\u064a\u0646\u0627 \u0634\u064a\u0626\u064b\u0627 \u0645\u0645\u0627 \u0627\u0641\u062a\u0631\u0636\u062a\u0647 \u0639\u0644\u064a\u0646\u0627\u060c \u0623\u0648 \u0623\u062e\u0637\u0623\u0646\u0627 \u0641\u064a \u0641\u0650\u0639\u0652\u0644 \u0634\u064a\u0621 \u0646\u0647\u064a\u062a\u0646\u0627 \u0639\u0646 \u0641\u0639\u0644\u0647\u060c \u0631\u0628\u0651\u064e\u0646\u0627 \u0648\u0644\u0627 \u062a\u0643\u0644\u0641\u0646\u0627 \u0645\u0646 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0634\u0627\u0642\u0629 \u0645\u0627 \u0643\u0644\u0641\u062a\u0647 \u0645\u064e\u0646 \u0642\u0628\u0644\u0646\u0627 \u0645\u0646 \u0627\u0644\u0639\u0635\u0627\u0629 \u0639\u0642\u0648\u0628\u0629 \u0644\u0647\u0645\u060c \u0631\u0628\u0646\u0627 \u0648\u0644\u0627 \u062a\u064f\u062d\u064e\u0645\u0651\u0650\u0644\u0652\u0646\u064e\u0627 \u0645\u0627 \u0644\u0627 \u0646\u0633\u062a\u0637\u064a\u0639\u0647 \u0645\u0646 \u0627\u0644\u062a\u0643\u0627\u0644\u064a\u0641 \u0648\u0627\u0644\u0645\u0635\u0627\u0626\u0628\u060c \u0648\u0627\u0645\u062d \u0630\u0646\u0648\u0628\u0646\u0627\u060c \u0648\u0627\u0633\u062a\u0631 \u0639\u064a\u0648\u0628\u0646\u0627\u060c \u0648\u0623\u062d\u0633\u0646 \u0625\u0644\u064a\u0646\u0627\u060c \u0623\u0646\u062a \u0645\u0627\u0644\u0643 \u0623\u0645\u0631\u0646\u0627 \u0648\u0645\u062f\u0628\u0631\u0647\u060c \u0641\u0627\u0646\u0635\u0631\u0646\u0627 \u0639\u0644\u0649 \u0645\u064e\u0646 \u062c\u062d\u062f\u0648\u0627 \u062f\u064a\u0646\u0643 \u0648\u0623\u0646\u0643\u0631\u0648\u0627 \u0648\u062d\u062f\u0627\u0646\u064a\u062a\u0643\u060c \u0648\u0643\u0630\u0651\u064e\u0628\u0648\u0627 \u0646\u0628\u064a\u0643 \u0645\u062d\u0645\u062f\u064b\u0627 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0627\u062c\u0639\u0644 \u0627\u0644\u0639\u0627\u0642\u0628\u0629 \u0644\u0646\u0627 \u0639\u0644\u064a\u0647\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629.","3:1":"\u0633\u0628\u0642 \u0627\u0644\u0643\u0644\u0627\u0645 \u0639\u0644\u064a\u0647\u0627 \u0641\u064a \u0623\u0648\u0644 \u0633\u0648\u0631\u0629 \u0627\u0644\u0628\u0642\u0631\u0629.","3:2":"\u0647\u0648 \u0627\u0644\u0644\u0647\u060c \u0644\u0627 \u0645\u0639\u0628\u0648\u062f \u0628\u062d\u0642 \u0625\u0644\u0627 \u0647\u0648\u060c \u0627\u0644\u0645\u062a\u0635\u0641 \u0628\u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u0643\u0627\u0645\u0644\u0629 \u0643\u0645\u0627 \u064a\u0644\u064a\u0642 \u0628\u062c\u0644\u0627\u0644\u0647\u060c \u0627\u0644\u0642\u0627\u0626\u0645 \u0639\u0644\u0649 \u0643\u0644 \u0634\u064a\u0621.","3:3":"\u0646\u064e\u0632\u0651\u064e\u0644 \u0639\u0644\u064a\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0627\u0644\u0642\u0631\u0622\u0646 \u0628\u0627\u0644\u062d\u0642 \u0627\u0644\u0630\u064a \u0644\u0627 \u0631\u064a\u0628 \u0641\u064a\u0647\u060c \u0645\u0635\u062f\u0651\u0650\u0642\u064b\u0627 \u0644\u0645\u0627 \u0642\u0628\u0644\u0647 \u0645\u0646 \u0643\u062a\u0628 \u0648\u0631\u0633\u0644\u060c \u0648\u0623\u0646\u0632\u0644 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0639\u0644\u0649 \u0645\u0648\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644 \u0639\u0644\u0649 \u0639\u064a\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0645\u0646 \u0642\u0628\u0644 \u0646\u0632\u0648\u0644 \u0627\u0644\u0642\u0631\u0622\u0646; \u0644\u0625\u0631\u0634\u0627\u062f \u0627\u0644\u0645\u062a\u0642\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u0625\u064a\u0645\u0627\u0646\u060c \u0648\u0635\u0644\u0627\u062d \u062f\u064a\u0646\u0647\u0645 \u0648\u062f\u0646\u064a\u0627\u0647\u0645\u060c \u0648\u0623\u0646\u0632\u0644 \u0645\u0627 \u064a\u0641\u0631\u0642 \u0628\u064a\u0646 \u0627\u0644\u062d\u0642 \u0648\u0627\u0644\u0628\u0627\u0637\u0644. \u0648\u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0628\u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u0646\u0632\u0644\u0629\u060c \u0644\u0647\u0645 \u0639\u0630\u0627\u0628 \u0639\u0638\u064a\u0645. \u0648\u0627\u0644\u0644\u0647 \u0639\u0632\u064a\u0632 \u0644\u0627 \u064a\u064f\u063a\u064e\u0627\u0644\u064e\u0628\u060c \u0630\u0648 \u0627\u0646\u062a\u0642\u0627\u0645 \u0628\u0645\u0646 \u062c\u062d\u062f \u062d\u062c\u062c\u0647 \u0648\u0623\u062f\u0644\u062a\u0647\u060c \u0648\u062a\u0641\u0631\u0651\u064f\u062f\u0647 \u0628\u0627\u0644\u0623\u0644\u0648\u0647\u064a\u0629.","3:4":"\u0646\u064e\u0632\u0651\u064e\u0644 \u0639\u0644\u064a\u0643 \u0627\u0644\u0642\u0631\u0622\u0646 \u0628\u0627\u0644\u062d\u0642 \u0627\u0644\u0630\u064a \u0644\u0627 \u0631\u064a\u0628 \u0641\u064a\u0647\u060c \u0645\u0635\u062f\u0651\u0650\u0642\u064b\u0627 \u0644\u0645\u0627 \u0642\u0628\u0644\u0647 \u0645\u0646 \u0643\u062a\u0628 \u0648\u0631\u0633\u0644\u060c \u0648\u0623\u0646\u0632\u0644 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0639\u0644\u0649 \u0645\u0648\u0633\u0649 \u0639\u0644\u0628\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644 \u0639\u0644\u0649 \u0639\u064a\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0645\u0646 \u0642\u0628\u0644 \u0646\u0632\u0648\u0644 \u0627\u0644\u0642\u0631\u0622\u0646\u061b \u0644\u0625\u0631\u0634\u0627\u062f \u0627\u0644\u0645\u062a\u0642\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u0625\u064a\u0645\u0627\u0646\u060c \u0648\u0635\u0644\u0627\u062d \u062f\u064a\u0646\u0647\u0645 \u0648\u062f\u0646\u064a\u0627\u0647\u0645\u060c \u0648\u0623\u0646\u0632\u0644 \u0645\u0627 \u064a\u0641\u0631\u0642 \u0628\u064a\u0646 \u0627\u0644\u062d\u0642 \u0648\u0627\u0644\u0628\u0627\u0637\u0644. \u0648\u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0628\u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u0646\u0632\u0644\u0629\u060c \u0644\u0647\u0645 \u0639\u0630\u0627\u0628 \u0639\u0638\u064a\u0645. \u0648\u0627\u0644\u0644\u0647 \u0639\u0632\u064a\u0632 \u0644\u0627 \u064a\u064f\u063a\u064e\u0627\u0644\u064e\u0628\u060c \u0630\u0648 \u0627\u0646\u062a\u0642\u0627\u0645 \u0628\u0645\u0646 \u062c\u062d\u062f \u062d\u062c\u062c\u0647 \u0648\u0623\u062f\u0644\u062a\u0647\u060c \u0648\u062a\u0641\u0631\u0651\u064f\u062f\u0647 \u0628\u0627\u0644\u0623\u0644\u0648\u0647\u064a\u0629.","3:5":"\u0625\u0646 \u0627\u0644\u0644\u0647 \u0645\u062d\u064a\u0637 \u0639\u0644\u0645\u0647 \u0628\u0627\u0644\u062e\u0644\u0627\u0626\u0642\u060c \u0644\u0627 \u064a\u062e\u0641\u0649 \u0639\u0644\u064a\u0647 \u0634\u064a\u0621 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0648\u0644\u0627 \u0641\u064a \u0627\u0644\u0633\u0645\u0627\u0621\u060c \u0642\u0644\u0651\u064e \u0623\u0648 \u0643\u062b\u0631.","3:6":"\u0647\u0648 \u0648\u062d\u062f\u0647 \u0627\u0644\u0630\u064a \u064a\u062e\u0644\u0642\u0643\u0645 \u0641\u064a \u0623\u0631\u062d\u0627\u0645 \u0623\u0645\u0647\u0627\u062a\u0643\u0645 \u0643\u0645\u0627 \u064a\u0634\u0627\u0621\u060c \u0645\u0646 \u0630\u0643\u0631 \u0648\u0623\u0646\u062b\u0649\u060c \u0648\u062d\u0633\u0646 \u0648\u0642\u0628\u064a\u062d\u060c \u0648\u0634\u0642\u064a \u0648\u0633\u0639\u064a\u062f\u060c \u0644\u0627 \u0645\u0639\u0628\u0648\u062f \u0628\u062d\u0642 \u0633\u0648\u0627\u0647\u060c \u0627\u0644\u0639\u0632\u064a\u0632 \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u064f\u063a\u0627\u0644\u064e\u0628\u060c \u0627\u0644\u062d\u0643\u064a\u0645 \u0641\u064a \u0623\u0645\u0631\u0647 \u0648\u062a\u062f\u0628\u064a\u0631\u0647.","3:7":"\u0647\u0648 \u0648\u062d\u062f\u0647 \u0627\u0644\u0630\u064a \u0623\u0646\u0632\u0644 \u0639\u0644\u064a\u0643 \u0627\u0644\u0642\u0631\u0622\u0646: \u0645\u0646\u0647 \u0622\u064a\u0627\u062a \u0648\u0627\u0636\u062d\u0627\u062a \u0627\u0644\u062f\u0644\u0627\u0644\u0629\u060c \u0647\u0646 \u0623\u0635\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0627\u0644\u0630\u064a \u064a\u064f\u0631\u062c\u0639 \u0625\u0644\u064a\u0647 \u0639\u0646\u062f \u0627\u0644\u0627\u0634\u062a\u0628\u0627\u0647\u060c \u0648\u064a\u064f\u0631\u064e\u062f\u0651\u064f \u0645\u0627 \u062e\u0627\u0644\u0641\u0647 \u0625\u0644\u064a\u0647\u060c \u0648\u0645\u0646\u0647 \u0622\u064a\u0627\u062a \u0623\u062e\u0631 \u0645\u062a\u0634\u0627\u0628\u0647\u0627\u062a \u062a\u062d\u062a\u0645\u0644 \u0628\u0639\u0636 \u0627\u0644\u0645\u0639\u0627\u0646\u064a\u060c \u0644\u0627 \u064a\u062a\u0639\u064a\u0651\u064e\u0646 \u0627\u0644\u0645\u0631\u0627\u062f \u0645\u0646\u0647\u0627 \u0625\u0644\u0627 \u0628\u0636\u0645\u0647\u0627 \u0625\u0644\u0649 \u0627\u0644\u0645\u062d\u0643\u0645\u060c \u0641\u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0642\u0644\u0648\u0628 \u0627\u0644\u0645\u0631\u064a\u0636\u0629 \u0627\u0644\u0632\u0627\u0626\u063a\u0629\u060c \u0644\u0633\u0648\u0621 \u0642\u0635\u062f\u0647\u0645 \u064a\u062a\u0628\u0639\u0648\u0646 \u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0627\u062a \u0627\u0644\u0645\u062a\u0634\u0627\u0628\u0647\u0627\u062a \u0648\u062d\u062f\u0647\u0627; \u0644\u064a\u062b\u064a\u0631\u0648\u0627 \u0627\u0644\u0634\u0628\u0647\u0627\u062a \u0639\u0646\u062f \u0627\u0644\u0646\u0627\u0633\u060c \u0643\u064a \u064a\u0636\u0644\u0648\u0647\u0645\u060c \u0648\u0644\u062a\u0623\u0648\u064a\u0644\u0647\u0645 \u0644\u0647\u0627 \u0639\u0644\u0649 \u0645\u0630\u0627\u0647\u0628\u0647\u0645 \u0627\u0644\u0628\u0627\u0637\u0644\u0629. \u0648\u0644\u0627 \u064a\u0639\u0644\u0645 \u062d\u0642\u064a\u0642\u0629 \u0645\u0639\u0627\u0646\u064a \u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0627\u062a \u0625\u0644\u0627 \u0627\u0644\u0644\u0647. \u0648\u0627\u0644\u0645\u062a\u0645\u0643\u0646\u0648\u0646 \u0641\u064a \u0627\u0644\u0639\u0644\u0645 \u064a\u0642\u0648\u0644\u0648\u0646: \u0622\u0645\u0646\u0627 \u0628\u0647\u0630\u0627 \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0643\u0644\u0647 \u0642\u062f \u062c\u0627\u0621\u0646\u0627 \u0645\u0646 \u0639\u0646\u062f \u0631\u0628\u0646\u0627 \u0639\u0644\u0649 \u0644\u0633\u0627\u0646 \u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u064a\u0631\u062f\u0651\u064f\u0648\u0646 \u0645\u062a\u0634\u0627\u0628\u0647\u0647 \u0625\u0644\u0649 \u0645\u062d\u0643\u0645\u0647\u060c \u0648\u0625\u0646\u0645\u0627 \u064a\u0641\u0647\u0645 \u0648\u064a\u0639\u0642\u0644 \u0648\u064a\u062a\u062f\u0628\u0631 \u0627\u0644\u0645\u0639\u0627\u0646\u064a \u0639\u0644\u0649 \u0648\u062c\u0647\u0647\u0627 \u0627\u0644\u0635\u062d\u064a\u062d \u0623\u0648\u0644\u0648 \u0627\u0644\u0639\u0642\u0648\u0644 \u0627\u0644\u0633\u0644\u064a\u0645\u0629.","3:8":"\u0648\u064a\u0642\u0648\u0644\u0648\u0646: \u064a\u0627 \u0631\u0628\u0646\u0627 \u0644\u0627 \u062a\u064e\u0635\u0652\u0631\u0650\u0641 \u0642\u0644\u0648\u0628\u0646\u0627 \u0639\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0643 \u0628\u0639\u062f \u0623\u0646 \u0645\u0646\u0646\u062a \u0639\u0644\u064a\u0646\u0627 \u0628\u0627\u0644\u0647\u062f\u0627\u064a\u0629 \u0644\u062f\u064a\u0646\u0643\u060c \u0648\u0627\u0645\u0646\u062d\u0646\u0627 \u0645\u0646 \u0641\u0636\u0644\u0643 \u0631\u062d\u0645\u0629 \u0648\u0627\u0633\u0639\u0629\u060c \u0625\u0646\u0643 \u0623\u0646\u062a \u0627\u0644\u0648\u0647\u0627\u0628: \u0643\u062b\u064a\u0631 \u0627\u0644\u0641\u0636\u0644 \u0648\u0627\u0644\u0639\u0637\u0627\u0621\u060c \u062a\u0639\u0637\u064a \u0645\u064e\u0646 \u062a\u0634\u0627\u0621 \u0628\u063a\u064a\u0631 \u062d\u0633\u0627\u0628.","3:9":"\u064a\u0627 \u0631\u0628\u0646\u0627 \u0625\u0646\u0627 \u0646\u064f\u0642\u0650\u0631\u0651\u064f \u0648\u0646\u0634\u0647\u062f \u0628\u0623\u0646\u0643 \u0633\u062a\u062c\u0645\u0639 \u0627\u0644\u0646\u0627\u0633 \u0641\u064a \u064a\u0648\u0645 \u0644\u0627 \u0634\u064e\u0643\u0651\u064e \u0641\u064a\u0647\u060c \u0648\u0647\u0648 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u0625\u0646\u0651\u064e\u0643 \u0644\u0627 \u062a\u064f\u062e\u0644\u0641 \u0645\u0627 \u0648\u0639\u064e\u062f\u0652\u062a\u064e \u0628\u0647 \u0639\u0628\u0627\u062f\u0643.","3:10":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u062c\u062d\u062f\u0648\u0627 \u0627\u0644\u062f\u064a\u0646 \u0627\u0644\u062d\u0642 \u0648\u0623\u0646\u0643\u0631\u0648\u0647\u060c \u0644\u0646 \u062a\u0646\u0641\u0639\u0647\u0645 \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0648\u0644\u0627 \u0623\u0648\u0644\u0627\u062f\u0647\u0645 \u0645\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647 \u0634\u064a\u0626\u064b\u0627 \u0625\u0646 \u0648\u0642\u0639 \u0628\u0647\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0644\u0646 \u062a\u062f\u0641\u0639\u0647 \u0639\u0646\u0647\u0645 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u0647\u0624\u0644\u0627\u0621 \u0647\u0645 \u062d\u0637\u0628 \u0627\u0644\u0646\u0627\u0631 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629.","3:11":"\u0634\u0623\u0646 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0641\u064a \u062a\u0643\u0630\u064a\u0628\u0647\u0645 \u0648\u0645\u0627 \u064a\u0646\u0632\u0644 \u0628\u0647\u0645\u060c \u0634\u0623\u0646 \u0622\u0644 \u0641\u0631\u0639\u0648\u0646 \u0648\u0627\u0644\u0630\u064a\u0646 \u0645\u0646 \u0642\u0628\u0644\u0647\u0645 \u0645\u0646 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646\u060c \u0623\u0646\u0643\u0631\u0648\u0627 \u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0627\u0644\u0648\u0627\u0636\u062d\u0629\u060c \u0641\u0639\u0627\u062c\u0644\u0647\u0645 \u0628\u0627\u0644\u0639\u0642\u0648\u0628\u0629 \u0628\u0633\u0628\u0628 \u062a\u0643\u0630\u064a\u0628\u0647\u0645 \u0648\u0639\u0646\u0627\u062f\u0647\u0645. \u0648\u0627\u0644\u0644\u0647 \u0634\u062f\u064a\u062f \u0627\u0644\u0639\u0642\u0627\u0628 \u0644\u0645\u0646 \u0643\u0641\u0631 \u0628\u0647 \u0648\u0643\u0630\u0651\u064e\u0628 \u0631\u0633\u0644\u0647.","3:12":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-\u060c \u0644\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u063a\u064a\u0631\u0647\u0645 \u0648\u0627\u0644\u0630\u064a\u0646 \u0627\u0633\u062a\u0647\u0627\u0646\u0648\u0627 \u0628\u0646\u0635\u0631\u0643 \u0641\u064a \xab\u0628\u064e\u062f\u0652\u0631\xbb : \u0625\u0646\u0643\u0645 \u0633\u062a\u064f\u0647\u0652\u0632\u064e\u0645\u0648\u0646 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0633\u062a\u0645\u0648\u062a\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u0643\u0641\u0631\u060c \u0648\u062a\u062d\u0634\u0631\u0648\u0646 \u0625\u0644\u0649 \u0646\u0627\u0631 \u062c\u0647\u0646\u0645; \u0644\u062a\u0643\u0648\u0646 \u0641\u0631\u0627\u0634\u064b\u0627 \u062f\u0627\u0626\u0645\u064b\u0627 \u0644\u0643\u0645\u060c \u0648\u0628\u0626\u0633 \u0627\u0644\u0641\u0631\u0627\u0634.","3:13":"\u0642\u062f \u0643\u0627\u0646 \u0644\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u064a\u0647\u0648\u062f \u0627\u0644\u0645\u062a\u0643\u0628\u0631\u0648\u0646 \u0627\u0644\u0645\u0639\u0627\u0646\u062f\u0648\u0646- \u062f\u0644\u0627\u0644\u0629 \u0639\u0638\u064a\u0645\u0629 \u0641\u064a \u062c\u0645\u0627\u0639\u062a\u064a\u0646 \u062a\u0642\u0627\u0628\u0644\u062a\u0627 \u0641\u064a \u0645\u0639\u0631\u0643\u0629 \xab\u0628\u064e\u062f\u0652\u0631\xbb : \u062c\u0645\u0627\u0639\u0629 \u062a\u0642\u0627\u062a\u0644 \u0645\u0646 \u0623\u062c\u0644 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u0647\u0645 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u0623\u0635\u062d\u0627\u0628\u0647\u060c \u0648\u062c\u0645\u0627\u0639\u0629 \u0623\u062e\u0631\u0649 \u0643\u0627\u0641\u0631\u0629 \u0628\u0627\u0644\u0644\u0647\u060c \u062a\u0642\u0627\u062a\u0644 \u0645\u0646 \u0623\u062c\u0644 \u0627\u0644\u0628\u0627\u0637\u0644\u060c \u062a\u0631\u0649 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0641\u064a \u0627\u0644\u0639\u062f\u062f \u0645\u062b\u0644\u064a\u0647\u0645 \u0631\u0623\u064a \u0627\u0644\u0639\u064a\u0646\u060c \u0648\u0642\u062f \u062c\u0639\u0644 \u0627\u0644\u0644\u0647 \u0630\u0644\u0643 \u0633\u0628\u0628\u064b\u0627 \u0644\u0646\u0635\u0631 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0639\u0644\u064a\u0647\u0645. \u0648\u0627\u0644\u0644\u0647 \u064a\u0624\u064a\u0651\u0650\u062f \u0628\u0646\u0635\u0631\u0647 \u0645\u0646 \u064a\u0634\u0627\u0621 \u0645\u0646 \u0639\u0628\u0627\u062f\u0647. \u0625\u0646 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0630\u064a \u062d\u062f\u062b \u0644\u064e\u0639\u0650\u0638\u0629 \u0639\u0638\u064a\u0645\u0629 \u0644\u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0628\u0635\u0627\u0626\u0631 \u0627\u0644\u0630\u064a\u0646 \u064a\u0647\u062a\u062f\u0648\u0646 \u0625\u0644\u0649 \u062d\u0643\u0645 \u0627\u0644\u0644\u0647 \u0648\u0623\u0641\u0639\u0627\u0644\u0647.","3:14":"\u062d\u064f\u0633\u0651\u0650\u0646 \u0644\u0644\u0646\u0627\u0633 \u062d\u0628\u0651\u064f \u0627\u0644\u0634\u0647\u0648\u0627\u062a \u0645\u0646 \u0627\u0644\u0646\u0633\u0627\u0621 \u0648\u0627\u0644\u0628\u0646\u064a\u0646\u060c \u0648\u0627\u0644\u0623\u0645\u0648\u0627\u0644 \u0627\u0644\u0643\u062b\u064a\u0631\u0629 \u0645\u0646 \u0627\u0644\u0630\u0647\u0628 \u0648\u0627\u0644\u0641\u0636\u0629\u060c \u0648\u0627\u0644\u062e\u064a\u0644 \u0627\u0644\u062d\u0633\u0627\u0646\u060c \u0648\u0627\u0644\u0623\u0646\u0639\u0627\u0645 \u0645\u0646 \u0627\u0644\u0625\u0628\u0644 \u0648\u0627\u0644\u0628\u0642\u0631 \u0648\u0627\u0644\u063a\u0646\u0645\u060c \u0648\u0627\u0644\u0623\u0631\u0636 \u0627\u0644\u0645\u062a\u0651\u064e\u062e\u064e\u0630\u0629 \u0644\u0644\u063a\u0631\u0627\u0633 \u0648\u0627\u0644\u0632\u0631\u0627\u0639\u0629. \u0630\u0644\u0643 \u0632\u0647\u0631\u0629 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0632\u064a\u0646\u062a\u0647\u0627 \u0627\u0644\u0641\u0627\u0646\u064a\u0629. \u0648\u0627\u0644\u0644\u0647 \u0639\u0646\u062f\u0647 \u062d\u0633\u0646 \u0627\u0644\u0645\u0631\u062c\u0639 \u0648\u0627\u0644\u062b\u0648\u0627\u0628\u060c \u0648\u0647\u0648 \u0627\u0644\u062c\u0646\u0651\u064e\u0629.","3:15":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0623\u0623\u062e\u0628\u0631\u0643\u0645 \u0628\u062e\u064a\u0631 \u0645\u0645\u0627 \u0632\u064f\u064a\u0651\u0650\u0646 \u0644\u0644\u0646\u0651\u064e\u0627\u0633 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0644\u0645\u0646 \u0631\u0627\u0642\u0628 \u0627\u0644\u0644\u0647 \u0648\u062e\u0627\u0641 \u0639\u0642\u0627\u0628\u0647 \u062c\u0646\u0627\u062a \u062a\u062c\u0631\u064a \u0645\u0646 \u062a\u062d\u062a \u0642\u0635\u0648\u0631\u0647\u0627 \u0648\u0623\u0634\u062c\u0627\u0631\u0647\u0627 \u0627\u0644\u0623\u0646\u0647\u0627\u0631\u060c \u062e\u0627\u0644\u062f\u064a\u0646 \u0641\u064a\u0647\u0627\u060c \u0648\u0644\u0647\u0645 \u0641\u064a\u0647\u0627 \u0623\u0632\u0648\u0627\u062c \u0645\u0637\u0647\u0631\u0627\u062a \u0645\u0646 \u0627\u0644\u062d\u064a\u0636 \u0648\u0627\u0644\u0646\u0641\u0627\u0633 \u0648\u0633\u0648\u0621 \u0627\u0644\u062e\u0644\u0642\u060c \u0648\u0644\u0647\u0645 \u0623\u0639\u0638\u0645 \u0645\u0646 \u0630\u0644\u0643: \u0631\u0636\u0648\u0627\u0646 \u0645\u0646 \u0627\u0644\u0644\u0647. \u0648\u0627\u0644\u0644\u0647 \u0645\u0637\u0651\u064e\u0644\u0650\u0639 \u0639\u0644\u0649 \u0633\u0631\u0627\u0626\u0631 \u062e\u0644\u0642\u0647\u060c \u0639\u0627\u0644\u0645 \u0628\u0623\u062d\u0648\u0627\u0644\u0647\u0645\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a\u0647\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643.","3:16":"\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0639\u0628\u0627\u062f \u0627\u0644\u0645\u062a\u0642\u0648\u0646 \u064a\u0642\u0648\u0644\u0648\u0646: \u0625\u0646\u0646\u0627 \u0622\u0645\u0646\u0627 \u0628\u0643\u060c \u0648\u0627\u062a\u0628\u0639\u0646\u0627 \u0631\u0633\u0648\u0644\u0643 \u0645\u062d\u0645\u062f\u064b\u0627 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0641\u0627\u0645\u0652\u062d\u064f \u0639\u0646\u0627 \u0645\u0627 \u0627\u0642\u062a\u0631\u0641\u0646\u0627\u0647 \u0645\u0646 \u0630\u0646\u0648\u0628\u060c \u0648\u0646\u062c\u0646\u0627 \u0645\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0646\u0627\u0631.","3:17":"\u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u0627\u062a\u0635\u0641\u0648\u0627 \u0628\u0627\u0644\u0635\u0628\u0631 \u0639\u0644\u0649 \u0627\u0644\u0637\u0627\u0639\u0627\u062a\u060c \u0648\u0639\u0646 \u0627\u0644\u0645\u0639\u0627\u0635\u064a\u060c \u0648\u0639\u0644\u0649 \u0645\u0627 \u064a\u0635\u064a\u0628\u0647\u0645 \u0645\u0646 \u0623\u0642\u062f\u0627\u0631 \u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u0624\u0644\u0645\u0629\u060c \u0648\u0628\u0627\u0644\u0635\u062f\u0642 \u0641\u064a \u0627\u0644\u0623\u0642\u0648\u0627\u0644 \u0648\u0627\u0644\u0623\u0641\u0639\u0627\u0644 \u0648\u0628\u0627\u0644\u0637\u0627\u0639\u0629 \u0627\u0644\u062a\u0627\u0645\u0629\u060c \u0648\u0628\u0627\u0644\u0625\u0646\u0641\u0627\u0642 \u0633\u0631\u0627 \u0648\u0639\u0644\u0627\u0646\u064a\u0629\u060c \u0648\u0628\u0627\u0644\u0627\u0633\u062a\u063a\u0641\u0627\u0631 \u0641\u064a \u0622\u062e\u0631 \u0627\u0644\u0644\u064a\u0644; \u0644\u0623\u0646\u0647 \u0645\u064e\u0638\u0650\u0646\u0651\u064e\u0629 \u0627\u0644\u0642\u0628\u0648\u0644 \u0648\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u062f\u0639\u0627\u0621.","3:18":"\u0634\u0647\u062f \u0627\u0644\u0644\u0647 \u0623\u0646\u0647 \u0627\u0644\u0645\u062a\u0641\u0631\u062f \u0628\u0627\u0644\u0625\u0644\u0647\u064a\u0629\u060c \u0648\u0642\u064e\u0631\u064e\u0646\u064e \u0634\u0647\u0627\u062f\u062a\u0647 \u0628\u0634\u0647\u0627\u062f\u0629 \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u0648\u0623\u0647\u0644 \u0627\u0644\u0639\u0644\u0645\u060c \u0639\u0644\u0649 \u0623\u062c\u0644\u0651\u0650 \u0645\u0634\u0647\u0648\u062f \u0639\u0644\u064a\u0647\u060c \u0648\u0647\u0648 \u062a\u0648\u062d\u064a\u062f\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0642\u064a\u0627\u0645\u0647 \u0628\u0627\u0644\u0639\u062f\u0644\u060c \u0644\u0627 \u0625\u0644\u0647 \u0625\u0644\u0627 \u0647\u0648 \u0627\u0644\u0639\u0632\u064a\u0632 \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u0645\u062a\u0646\u0639 \u0639\u0644\u064a\u0647 \u0634\u064a\u0621 \u0623\u0631\u0627\u062f\u0647\u060c \u0627\u0644\u062d\u0643\u064a\u0645 \u0641\u064a \u0623\u0642\u0648\u0627\u0644\u0647 \u0648\u0623\u0641\u0639\u0627\u0644\u0647.","3:19":"\u0625\u0646 \u0627\u0644\u062f\u064a\u0646 \u0627\u0644\u0630\u064a \u0627\u0631\u062a\u0636\u0627\u0647 \u0627\u0644\u0644\u0647 \u0644\u062e\u0644\u0642\u0647 \u0648\u0623\u0631\u0633\u0644 \u0628\u0647 \u0631\u0633\u0644\u0647\u060c \u0648\u0644\u0627 \u064a\u064e\u0642\u0652\u0628\u064e\u0644 \u063a\u064a\u0631\u0647 \u0647\u0648 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0648\u0647\u0648 \u0627\u0644\u0627\u0646\u0642\u064a\u0627\u062f \u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0628\u0627\u0644\u0637\u0627\u0639\u0629 \u0648\u0627\u0644\u0627\u0633\u062a\u0633\u0644\u0627\u0645 \u0644\u0647 \u0628\u0627\u0644\u0639\u0628\u0648\u062f\u064a\u0629\u060c \u0648\u0627\u062a\u0628\u0627\u0639 \u0627\u0644\u0631\u0633\u0644 \u0641\u064a\u0645\u0627 \u0628\u0639\u062b\u0647\u0645 \u0627\u0644\u0644\u0647 \u0628\u0647 \u0641\u064a \u0643\u0644 \u062d\u064a\u0646 \u062d\u062a\u0649 \u062e\u064f\u062a\u0645\u0648\u0627 \u0628\u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u0642\u0628\u0644 \u0627\u0644\u0644\u0647 \u0645\u0650\u0646 \u0623\u062d\u062f \u0628\u0639\u062f \u0628\u0639\u062b\u062a\u0647 \u062f\u064a\u0646\u064b\u0627 \u0633\u0648\u0649 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0627\u0644\u0630\u064a \u0623\u064f\u0631\u0633\u0644 \u0628\u0647. \u0648\u0645\u0627 \u0648\u0642\u0639 \u0627\u0644\u062e\u0644\u0627\u0641 \u0628\u064a\u0646 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649\u060c \u0641\u062a\u0641\u0631\u0642\u0648\u0627 \u0634\u064a\u0639\u064b\u0627 \u0648\u0623\u062d\u0632\u0627\u0628\u064b\u0627 \u0625\u0644\u0627 \u0645\u0646 \u0628\u0639\u062f \u0645\u0627 \u0642\u0627\u0645\u062a \u0627\u0644\u062d\u062c\u0629 \u0639\u0644\u064a\u0647\u0645 \u0628\u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u0631\u0633\u0644 \u0648\u0625\u0646\u0632\u0627\u0644 \u0627\u0644\u0643\u062a\u0628; \u0628\u063a\u064a\u064b\u0627 \u0648\u062d\u0633\u062f\u064b\u0627 \u0637\u0644\u0628\u064b\u0627 \u0644\u0644\u062f\u0646\u064a\u0627. \u0648\u0645\u0646 \u064a\u062c\u062d\u062f \u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u0646\u0632\u0644\u0629 \u0648\u0622\u064a\u0627\u062a\u0647 \u0627\u0644\u062f\u0627\u0644\u0629 \u0639\u0644\u0649 \u0631\u0628\u0648\u0628\u064a\u062a\u0647 \u0648\u0623\u0644\u0648\u0647\u064a\u062a\u0647\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0633\u0631\u064a\u0639 \u0627\u0644\u062d\u0633\u0627\u0628\u060c \u0648\u0633\u064a\u062c\u0632\u064a\u0647\u0645 \u0628\u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u064a\u0639\u0645\u0644\u0648\u0646.","3:20":"\u0641\u0625\u0646 \u062c\u0627\u062f\u0644\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0641\u064a \u0627\u0644\u062a\u0648\u062d\u064a\u062f \u0628\u0639\u062f \u0623\u0646 \u0623\u0642\u0645\u062a \u0627\u0644\u062d\u062c\u0629 \u0639\u0644\u064a\u0647\u0645 \u0641\u0642\u0644 \u0644\u0647\u0645: \u0625\u0646\u0646\u064a \u0623\u062e\u0644\u0635\u062a \u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0641\u0644\u0627 \u0623\u0634\u0631\u0643 \u0628\u0647 \u0623\u062d\u062f\u064b\u0627\u060c \u0648\u0643\u0630\u0644\u0643 \u0645\u0646 \u0627\u062a\u0628\u0639\u0646\u064a \u0645\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0623\u062e\u0644\u0635\u0648\u0627 \u0644\u0644\u0647 \u0648\u0627\u0646\u0642\u0627\u062f\u0648\u0627 \u0644\u0647. \u0648\u0642\u0644 \u0644\u0647\u0645 \u0648\u0644\u0645\u0634\u0631\u0643\u064a \u0627\u0644\u0639\u0631\u0628 \u0648\u063a\u064a\u0631\u0647\u0645: \u0625\u0646 \u0623\u0633\u0644\u0645\u062a\u0645 \u0641\u0623\u0646\u062a\u0645 \u0639\u0644\u0649 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645 \u0648\u0627\u0644\u0647\u062f\u0649 \u0648\u0627\u0644\u062d\u0642\u060c \u0648\u0625\u0646 \u062a\u0648\u0644\u064a\u062a\u0645 \u0641\u062d\u0633\u0627\u0628\u0643\u0645 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u064a\u0633 \u0639\u0644\u064a\u0651\u064e \u0625\u0644\u0627 \u0627\u0644\u0628\u0644\u0627\u063a\u060c \u0648\u0642\u062f \u0623\u0628\u0644\u063a\u062a\u0643\u0645 \u0648\u0623\u0642\u0645\u062a \u0639\u0644\u064a\u0643\u0645 \u0627\u0644\u062d\u062c\u0629. \u0648\u0627\u0644\u0644\u0647 \u0628\u0635\u064a\u0631 \u0628\u0627\u0644\u0639\u0628\u0627\u062f\u060c \u0644\u0627 \u064a\u062e\u0641\u0649 \u0639\u0644\u064a\u0647 \u0645\u0646 \u0623\u0645\u0631\u0647\u0645 \u0634\u064a\u0621.","3:21":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u062c\u062d\u062f\u0648\u0646 \u0628\u0627\u0644\u062f\u0644\u0627\u0626\u0644 \u0627\u0644\u0648\u0627\u0636\u062d\u0629 \u0648\u0645\u0627 \u062c\u0627\u0621 \u0628\u0647 \u0627\u0644\u0645\u0631\u0633\u0644\u0648\u0646\u060c \u0648\u064a\u0642\u062a\u0644\u0648\u0646 \u0623\u0646\u0628\u064a\u0627\u0621 \u0627\u0644\u0644\u0647 \u0638\u0644\u0645\u064b\u0627 \u0628\u063a\u064a\u0631 \u062d\u0642\u060c \u0648\u064a\u0642\u062a\u0644\u0648\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u0623\u0645\u0631\u0648\u0646 \u0628\u0627\u0644\u0639\u062f\u0644 \u0648\u0627\u062a\u0628\u0627\u0639 \u0637\u0631\u064a\u0642 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621\u060c \u0641\u0628\u0634\u0651\u0650\u0631\u0647\u0645 \u0628\u0639\u0630\u0627\u0628 \u0645\u0648\u062c\u0639.","3:22":"\u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0630\u064a\u0646 \u0628\u0637\u0644\u062a \u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0641\u0644\u0627 \u064a\u064f\u0642\u0628\u0644 \u0644\u0647\u0645 \u0639\u0645\u0644\u060c \u0648\u0645\u0627 \u0644\u0647\u0645 \u0645\u0646 \u0646\u0627\u0635\u0631\u064d \u064a\u0646\u0635\u0631\u0647\u0645 \u0645\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647.","3:23":"\u0623\u0631\u0623\u064a\u062a -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0623\u0639\u062c\u0628 \u0645\u0646 \u062d\u0627\u0644 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u064a\u0647\u0648\u062f \u0627\u0644\u0630\u064a\u0646 \u0623\u062a\u0627\u0647\u0645 \u0627\u0644\u0644\u0647 \u062d\u0638\u0627 \u0645\u0646 \u0627\u0644\u0643\u062a\u0627\u0628 \u0641\u0639\u0644\u0645\u0648\u0627 \u0623\u0646 \u0645\u0627 \u062c\u0626\u062a \u0628\u0647 \u0647\u0648 \u0627\u0644\u062d\u0642\u060c \u064a\u064f\u062f\u0652\u0639\u0648\u0646 \u0625\u0644\u0649 \u0645\u0627 \u062c\u0627\u0621 \u0641\u064a \u0643\u062a\u0627\u0628 \u0627\u0644\u0644\u0647 -\u0648\u0647\u0648 \u0627\u0644\u0642\u0631\u0622\u0646- \u0644\u064a\u0641\u0635\u0644 \u0628\u064a\u0646\u0647\u0645 \u0641\u064a\u0645\u0627 \u0627\u062e\u062a\u0644\u0641\u0648\u0627 \u0641\u064a\u0647\u060c \u0641\u0625\u0646 \u0644\u0645 \u064a\u0648\u0627\u0641\u0642 \u0623\u0647\u0648\u0627\u0621\u0647\u0645 \u064a\u064e\u0623\u0652\u0628\u064e \u0643\u062b\u064a\u0631 \u0645\u0646\u0647\u0645 \u062d\u0643\u0645 \u0627\u0644\u0644\u0647; \u0644\u0623\u0646 \u0645\u0646 \u0639\u0627\u062f\u062a\u0647\u0645 \u0627\u0644\u0625\u0639\u0631\u0627\u0636\u064e \u0639\u0646 \u0627\u0644\u062d\u0642\u061f","3:24":"\u0630\u0644\u0643 \u0627\u0644\u0627\u0646\u0635\u0631\u0627\u0641 \u0639\u0646 \u0627\u0644\u062d\u0642 \u0633\u0628\u0628\u0647 \u0627\u0639\u062a\u0642\u0627\u062f \u0641\u0627\u0633\u062f \u0644\u062f\u0649 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628; \u0628\u0623\u0646\u0647\u0645 \u0644\u0646 \u064a\u0639\u0630\u0651\u064e\u0628\u0648\u0627 \u0625\u0644\u0627 \u0623\u064a\u0627\u0645\u064b\u0627 \u0642\u0644\u064a\u0644\u0629\u060c \u0648\u0647\u0630\u0627 \u0627\u0644\u0627\u0639\u062a\u0642\u0627\u062f \u0623\u062f\u0649 \u0625\u0644\u0649 \u062c\u0631\u0623\u062a\u0647\u0645 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0648\u0627\u0633\u062a\u0647\u0627\u0646\u062a\u0647\u0645 \u0628\u062f\u064a\u0646\u0647\u060c \u0648\u0627\u0633\u062a\u0645\u0631\u0627\u0631\u0647\u0645 \u0639\u0644\u0649 \u062f\u064a\u0646\u0647\u0645 \u0627\u0644\u0628\u0627\u0637\u0644 \u0627\u0644\u0630\u064a \u062e\u064e\u062f\u064e\u0639\u0648\u0627 \u0628\u0647 \u0623\u0646\u0641\u0633\u0647\u0645.","3:25":"\u0641\u0643\u064a\u0641 \u064a\u0643\u0648\u0646 \u062d\u0627\u0644\u0647\u0645 \u0625\u0630\u0627 \u062c\u0645\u0639\u0647\u0645 \u0627\u0644\u0644\u0647 \u0644\u064a\u062d\u0627\u0633\u064e\u0628\u0648\u0627 \u0641\u064a \u064a\u0648\u0645 \u0644\u0627 \u0634\u0643 \u0641\u064a \u0648\u0642\u0648\u0639\u0647 -\u0648\u0647\u0648 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629-\u060c \u0648\u0623\u062e\u0630 \u0643\u0644 \u0648\u0627\u062d\u062f \u062c\u0632\u0627\u0621\u064e \u0645\u0627 \u0627\u0643\u062a\u0633\u0628\u060c \u0648\u0647\u0645 \u0644\u0627 \u064a\u0638\u0644\u0645\u0648\u0646 \u0634\u064a\u0626\u0627\u061f","3:26":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a \u0645\u062a\u0648\u062c\u0647\u0627 \u0625\u0644\u0649 \u0631\u0628\u0643 \u0628\u0627\u0644\u062f\u0639\u0627\u0621-: \u064a\u0627 \u0645\u064e\u0646 \u0644\u0643 \u0627\u0644\u0645\u0644\u0643 \u0643\u0644\u0651\u064f\u0647\u060c \u0623\u0646\u062a \u0627\u0644\u0630\u064a \u062a\u0645\u0646\u062d \u0627\u0644\u0645\u0644\u0643 \u0648\u0627\u0644\u0645\u0627\u0644 \u0648\u0627\u0644\u062a\u0645\u0643\u064a\u0646 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0645\u064e\u0646 \u062a\u0634\u0627\u0621 \u0645\u0650\u0646 \u062e\u0644\u0642\u0643\u060c \u0648\u062a\u0633\u0644\u0628 \u0627\u0644\u0645\u0644\u0643 \u0645\u0645\u0646 \u062a\u0634\u0627\u0621\u060c \u0648\u062a\u0647\u0628 \u0627\u0644\u0639\u0632\u0629 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629 \u0645\u064e\u0646 \u062a\u0634\u0627\u0621\u060c \u0648\u062a\u062c\u0639\u0644 \u0627\u0644\u0630\u0644\u0651\u064e\u0629 \u0639\u0644\u0649 \u0645\u0646 \u062a\u0634\u0627\u0621\u060c \u0628\u064a\u062f\u0643 \u0627\u0644\u062e\u064a\u0631\u060c \u0625\u0646\u0643 -\u0648\u062d\u062f\u0643- \u0639\u0644\u0649 \u0643\u0644 \u0634\u064a\u0621 \u0642\u062f\u064a\u0631. \u0648\u0641\u064a \u0627\u0644\u0622\u064a\u0629 \u0625\u062b\u0628\u0627\u062a \u0644\u0635\u0641\u0629 \u0627\u0644\u064a\u062f \u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0644\u0649 \u0645\u0627 \u064a\u0644\u064a\u0642 \u0628\u0647 \u0633\u0628\u062d\u0627\u0646\u0647.","3:27":"\u0648\u0645\u0646 \u062f\u0644\u0627\u0626\u0644 \u0642\u062f\u0631\u062a\u0643 \u0623\u0646\u0643 \u062a\u064f\u062f\u062e\u0644 \u0627\u0644\u0644\u064a\u0644 \u0641\u064a \u0627\u0644\u0646\u0647\u0627\u0631\u060c \u0648\u062a\u064f\u062f\u062e\u0644 \u0627\u0644\u0646\u0647\u0627\u0631 \u0641\u064a \u0627\u0644\u0644\u064a\u0644\u060c \u0641\u064a\u0637\u0648\u0644 \u0647\u0630\u0627 \u0648\u064a\u0642\u0635\u0631 \u0630\u0627\u0643\u060c \u0648\u062a\u064f\u062e\u0631\u062c \u0627\u0644\u062d\u064a \u0645\u0646 \u0627\u0644\u0645\u064a\u062a \u0627\u0644\u0630\u064a \u0644\u0627 \u062d\u064a\u0627\u0629 \u0641\u064a\u0647\u060c \u0643\u0625\u062e\u0631\u0627\u062c \u0627\u0644\u0632\u0631\u0639 \u0645\u0646 \u0627\u0644\u062d\u0628\u060c \u0648\u0627\u0644\u0645\u0624\u0645\u0646 \u0645\u0646 \u0627\u0644\u0643\u0627\u0641\u0631\u060c \u0648\u062a\u064f\u062e\u0631\u062c \u0627\u0644\u0645\u064a\u062a \u0645\u0646 \u0627\u0644\u062d\u064a \u0643\u0625\u062e\u0631\u0627\u062c \u0627\u0644\u0628\u064a\u0636 \u0645\u0646 \u0627\u0644\u062f\u062c\u0627\u062c\u060c \u0648\u062a\u0631\u0632\u0642 \u0645\u0646 \u062a\u0634\u0627\u0621 \u0645\u064e\u0646 \u062e\u0644\u0642\u0643 \u0628\u063a\u064a\u0631 \u062d\u0633\u0627\u0628.","3:28":"\u064a\u0646\u0647\u0649 \u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0623\u0646 \u064a\u062a\u062e\u0630\u0648\u0627 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0623\u0648\u0644\u064a\u0627\u0621 \u0628\u0627\u0644\u0645\u062d\u0628\u0629 \u0648\u0627\u0644\u0646\u0635\u0631\u0629 \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0648\u0645\u064e\u0646 \u064a\u062a\u0648\u0644\u0647\u0645 \u0641\u0642\u062f \u0628\u0631\u0650\u0626 \u0645\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u0644\u0644\u0647 \u0628\u0631\u0650\u064a\u0621 \u0645\u0646\u0647\u060c \u0625\u0644\u0627 \u0623\u0646 \u062a\u0643\u0648\u0646\u0648\u0627 \u0636\u0639\u0627\u0641\u064b\u0627 \u062e\u0627\u0626\u0641\u064a\u0646 \u0641\u0642\u062f \u0631\u062e\u0651\u064e\u0635 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0641\u064a \u0645\u0647\u0627\u062f\u0646\u062a\u0647\u0645 \u0627\u062a\u0642\u0627\u0621 \u0644\u0634\u0631\u0647\u0645\u060c \u062d\u062a\u0649 \u062a\u0642\u0648\u0649 \u0634\u0648\u0643\u062a\u0643\u0645\u060c \u0648\u064a\u062d\u0630\u0631\u0643\u0645 \u0627\u0644\u0644\u0647 \u0646\u0641\u0633\u0647\u060c \u0641\u0627\u062a\u0642\u0648\u0647 \u0648\u062e\u0627\u0641\u0648\u0647. \u0648\u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0631\u062c\u0648\u0639 \u0627\u0644\u062e\u0644\u0627\u0626\u0642 \u0644\u0644\u062d\u0633\u0627\u0628 \u0648\u0627\u0644\u062c\u0632\u0627\u0621.","3:29":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0644\u0644\u0645\u0624\u0645\u0646\u064a\u0646: \u0625\u0646 \u062a\u0643\u062a\u0645\u0648\u0627 \u0645\u0627 \u0627\u0633\u062a\u0642\u0631 \u0641\u064a \u0642\u0644\u0648\u0628\u0643\u0645 \u0645\u0646 \u0645\u0648\u0627\u0644\u0627\u0629 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0648\u0646\u0635\u0631\u062a\u0647\u0645 \u0623\u0648 \u062a\u0638\u0647\u0631\u0648\u0627 \u0630\u0644\u0643 \u0644\u0627 \u064a\u064e\u062e\u0652\u0641\u064e \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0645\u0646\u0647 \u0634\u064a\u0621\u060c \u0641\u0625\u0646\u0651\u064e \u0639\u0644\u0645\u0647 \u0645\u062d\u064a\u0637 \u0628\u0643\u0644 \u0645\u0627 \u0641\u064a \u0627\u0644\u0633\u0645\u0627\u0648\u0627\u062a \u0648\u0645\u0627 \u0641\u064a \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0644\u0647 \u0627\u0644\u0642\u062f\u0631\u0629 \u0627\u0644\u062a\u0627\u0645\u0629 \u0639\u0644\u0649 \u0643\u0644 \u0634\u064a\u0621.","3:30":"\u0648\u0641\u064a \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u064a\u0648\u0645 \u0627\u0644\u062c\u0632\u0627\u0621 \u062a\u062c\u062f \u0643\u0644 \u0646\u0641\u0633 \u0645\u0627 \u0639\u0645\u0644\u062a \u0645\u0646 \u062e\u064a\u0631 \u064a\u0646\u062a\u0638\u0631\u0647\u0627 \u0645\u0648\u0641\u0631\u064b\u0627 \u0644\u062a\u064f\u062c\u0632\u064e\u0649 \u0628\u0647\u060c \u0648\u0645\u0627 \u0639\u0645\u0644\u062a \u0645\u0646 \u0639\u0645\u0644 \u0633\u064a\u0651\u0650\u0626 \u062a\u062c\u062f\u0647 \u0641\u064a \u0627\u0646\u062a\u0638\u0627\u0631\u0647\u0627 \u0623\u064a\u0636\u064b\u0627\u060c \u0641\u062a\u062a\u0645\u0646\u0649 \u0644\u0648 \u0623\u0646 \u0628\u064a\u0646\u0647\u0627 \u0648\u0628\u064a\u0646 \u0647\u0630\u0627 \u0627\u0644\u0639\u0645\u0644 \u0632\u0645\u0646\u064b\u0627 \u0628\u0639\u064a\u062f\u064b\u0627. \u0641\u0627\u0633\u062a\u0639\u062f\u0648\u0627 \u0644\u0647\u0630\u0627 \u0627\u0644\u064a\u0648\u0645\u060c \u0648\u062e\u0627\u0641\u0648\u0627 \u0628\u0637\u0634 \u0627\u0644\u0625\u0644\u0647 \u0627\u0644\u062c\u0628\u0627\u0631. \u0648\u0645\u0639 \u0634\u062f\u0651\u064e\u0629 \u0639\u0642\u0627\u0628\u0647 \u0641\u0625\u0646\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0627\u0644\u0645\u062a\u0635\u0641 \u0628\u0643\u0645\u0627\u0644 \u0627\u0644\u0631\u062d\u0645\u0629 \u0628\u0627\u0644\u0639\u0628\u0627\u062f.","3:31":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0625\u0646 \u0643\u0646\u062a\u0645 \u062a\u062d\u0628\u0648\u0646 \u0627\u0644\u0644\u0647 \u062d\u0642\u0627 \u0641\u0627\u062a\u0628\u0639\u0648\u0646\u064a \u0648\u0622\u0645\u0646\u0648\u0627 \u0628\u064a \u0638\u0627\u0647\u0631\u064b\u0627 \u0648\u0628\u0627\u0637\u0646\u064b\u0627\u060c \u064a\u062d\u0628\u0628\u0643\u0645 \u0627\u0644\u0644\u0647\u060c \u0648\u064a\u0645\u062d\u064f \u0630\u0646\u0648\u0628\u0643\u0645\u060c \u0641\u0625\u0646\u0647 \u063a\u0641\u0648\u0631 \u0644\u0630\u0646\u0648\u0628 \u0639\u0628\u0627\u062f\u0647 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0631\u062d\u064a\u0645 \u0628\u0647\u0645. \u0648\u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0629 \u0627\u0644\u0643\u0631\u064a\u0645\u0629 \u062d\u0627\u0643\u0645\u0629 \u0639\u0644\u0649 \u0643\u0644 \u0645\u0646 \u0627\u062f\u0639\u0649 \u0645\u062d\u0628\u0629 \u0627\u0644\u0644\u0647 -\u062a\u0639\u0627\u0644\u0649- \u0648\u0644\u064a\u0633 \u0645\u062a\u0628\u0639\u064b\u0627 \u0644\u0646\u0628\u064a\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u064a\u0647 \u0648\u0633\u0644\u0645 \u062d\u0642 \u0627\u0644\u0627\u062a\u0628\u0627\u0639\u060c \u0645\u0637\u064a\u0639\u064b\u0627 \u0644\u0647 \u0641\u064a \u0623\u0645\u0631\u0647 \u0648\u0646\u0647\u064a\u0647\u060c \u0641\u0625\u0646\u0647 \u0643\u0627\u0630\u0628 \u0641\u064a \u062f\u0639\u0648\u0627\u0647 \u062d\u062a\u0649 \u064a\u062a\u0627\u0628\u0639 \u0627\u0644\u0631\u0633\u0648\u0644 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u062d\u0642 \u0627\u0644\u0627\u062a\u0628\u0627\u0639.","3:32":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0623\u0637\u064a\u0639\u0648\u0627 \u0627\u0644\u0644\u0647 \u0628\u0627\u062a\u0628\u0627\u0639 \u0643\u062a\u0627\u0628\u0647\u060c \u0648\u0623\u0637\u064a\u0639\u0648\u0627 \u0627\u0644\u0631\u0633\u0648\u0644 \u0628\u0627\u062a\u0628\u0627\u0639 \u0633\u0646\u062a\u0647 \u0641\u064a \u062d\u064a\u0627\u062a\u0647 \u0648\u0628\u0639\u062f \u0645\u0645\u0627\u062a\u0647\u060c \u0641\u0625\u0646 \u0647\u0645 \u0623\u0639\u0631\u0636\u0648\u0627 \u0639\u0646\u0643\u060c \u0648\u0623\u0635\u0631\u0648\u0627 \u0639\u0644\u0649 \u0645\u0627 \u0647\u0645 \u0639\u0644\u064a\u0647 \u0645\u0650\u0646 \u0643\u0641\u0631 \u0648\u0636\u0644\u0627\u0644\u060c \u0641\u0644\u064a\u0633\u0648\u0627 \u0623\u0647\u0644\u0627 \u0644\u0645\u062d\u0628\u0629 \u0627\u0644\u0644\u0647; \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u062d\u0628 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646.","3:33":"\u0625\u0646 \u0627\u0644\u0644\u0647 \u0627\u062e\u062a\u0627\u0631 \u0622\u062f\u0645 \u0648\u0646\u0648\u062d\u064b\u0627 \u0648\u0622\u0644 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0648\u0622\u0644 \u0639\u0645\u0631\u0627\u0646\u060c \u0648\u062c\u0639\u0644\u0647\u0645 \u0623\u0641\u0636\u0644 \u0623\u0647\u0644 \u0632\u0645\u0627\u0646\u0647\u0645.","3:34":"\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0648\u0627\u0644\u0631\u0633\u0644 \u0633\u0644\u0633\u0644\u0629 \u0637\u064f\u0647\u0652\u0631 \u0645\u062a\u0648\u0627\u0635\u0644\u0629 \u0641\u064a \u0627\u0644\u0625\u062e\u0644\u0627\u0635 \u0644\u0644\u0647 \u0648\u062a\u0648\u062d\u064a\u062f\u0647 \u0648\u0627\u0644\u0639\u0645\u0644 \u0628\u0648\u062d\u064a\u0647. \u0648\u0627\u0644\u0644\u0647 \u0633\u0645\u064a\u0639 \u0644\u0623\u0642\u0648\u0627\u0644 \u0639\u0628\u0627\u062f\u0647\u060c \u0639\u0644\u064a\u0645 \u0628\u0623\u0641\u0639\u0627\u0644\u0647\u0645\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a\u0647\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643.","3:35":"\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0645\u0627 \u0643\u0627\u0646 \u0645\u0646 \u0623\u0645\u0631 \u0645\u0631\u064a\u0645 \u0648\u0623\u0645\u0647\u0627 \u0648\u0627\u0628\u0646\u0647\u0627 \u0639\u064a\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645; \u0644\u062a\u0631\u062f\u0651\u064e \u0628\u0630\u0644\u0643 \u0639\u0644\u0649 \u0645\u0646 \u0627\u062f\u0639\u0648\u0627 \u0623\u064f\u0644\u0648\u0647\u064a\u0629 \u0639\u064a\u0633\u0649 \u0623\u0648 \u0628\u0646\u0648\u0651\u064e\u062a\u0647 \u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647\u060c \u0625\u0630 \u0642\u0627\u0644\u062a \u0627\u0645\u0631\u0623\u0629 \u0639\u0645\u0631\u0627\u0646 \u062d\u064a\u0646 \u062d\u0645\u0644\u062a: \u064a\u0627 \u0631\u0628\u0651\u0650 \u0625\u0646\u064a \u062c\u0639\u0644\u062a \u0644\u0643 \u0645\u0627 \u0641\u064a \u0628\u0637\u0646\u064a \u062e\u0627\u0644\u0635\u0627 \u0644\u0643\u060c \u0644\u062e\u062f\u0645\u0629 \xab\u0628\u064a\u062a \u0627\u0644\u0645\u0642\u062f\u0633\xbb \u060c \u0641\u062a\u0642\u0628\u0651\u064e\u0644 \u0645\u0646\u064a; \u0625\u0646\u0643 \u0623\u0646\u062a \u0648\u062d\u062f\u0643 \u0627\u0644\u0633\u0645\u064a\u0639 \u0644\u062f\u0639\u0627\u0626\u064a\u060c \u0627\u0644\u0639\u0644\u064a\u0645 \u0628\u0646\u064a\u062a\u064a.","3:36":"\u0641\u0644\u0645\u0627 \u062a\u0645\u0651\u064e \u062d\u0645\u0644\u0647\u0627 \u0648\u0648\u0636\u0639\u062a \u0645\u0648\u0644\u0648\u062f\u0647\u0627 \u0642\u0627\u0644\u062a: \u0631\u0628\u0651\u0650 \u0625\u0646\u064a \u0648\u0636\u0639\u062a\u0647\u0627 \u0623\u0646\u062b\u0649 \u0644\u0627 \u062a\u0635\u0644\u062d \u0644\u0644\u062e\u062f\u0645\u0629 \u0641\u064a \xab\u0628\u064a\u062a \u0627\u0644\u0645\u0642\u062f\u0633\xbb -\u0648\u0627\u0644\u0644\u0647 \u0623\u0639\u0644\u0645 \u0628\u0645\u0627 \u0648\u0636\u064e\u0639\u064e\u062a\u0652\u060c \u0648\u0633\u0648\u0641 \u064a\u062c\u0639\u0644 \u0627\u0644\u0644\u0647 \u0644\u0647\u0627 \u0634\u0623\u0646\u064b\u0627- \u0648\u0642\u0627\u0644\u062a: \u0648\u0644\u064a\u0633 \u0627\u0644\u0630\u0643\u0631 \u0627\u0644\u0630\u064a \u0623\u0631\u062f\u062a \u0644\u0644\u062e\u062f\u0645\u0629 \u0643\u0627\u0644\u0623\u0646\u062b\u0649 \u0641\u064a \u0630\u0644\u0643; \u0644\u0623\u0646 \u0627\u0644\u0630\u0643\u0631 \u0623\u0642\u0648\u0649 \u0639\u0644\u0649 \u0627\u0644\u062e\u062f\u0645\u0629 \u0648\u0623\u0642\u0652\u0648\u064e\u0645 \u0628\u0647\u0627\u060c \u0648\u0625\u0646\u064a \u0633\u0645\u0651\u064e\u064a\u062a\u0647\u0627 \u0645\u0631\u064a\u0645\u060c \u0648\u0625\u0646\u064a \u062d\u0635\u0651\u064e\u0646\u062a\u0647\u0627 \u0628\u0643 \u0647\u064a \u0648\u0630\u0631\u064a\u0651\u064e\u062a\u0647\u0627 \u0645\u0646 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0627\u0644\u0645\u0637\u0631\u0648\u062f \u0645\u0646 \u0631\u062d\u0645\u062a\u0643.","3:37":"\u0641\u0627\u0633\u062a\u062c\u0627\u0628 \u0627\u0644\u0644\u0647 \u062f\u0639\u0627\u0621\u0647\u0627 \u0648\u0642\u0628\u0644 \u0645\u0646\u0647\u0627 \u0646\u064e\u0630\u0652\u0631\u0647\u0627 \u0623\u062d\u0633\u0646 \u0642\u064e\u0628\u0648\u0644\u060c \u0648\u062a\u0648\u0644\u0651\u064e\u0649 \u0627\u0628\u0646\u062a\u0647\u0627 \u0645\u0631\u064a\u0645 \u0628\u0627\u0644\u0631\u0639\u0627\u064a\u0629 \u0641\u0623\u0646\u0628\u062a\u0647\u0627 \u0646\u0628\u0627\u062a\u064b\u0627 \u062d\u0633\u0646\u064b\u0627\u060c \u0648\u064a\u0633\u0651\u064e\u0631 \u0627\u0644\u0644\u0647 \u0644\u0647\u0627 \u0632\u0643\u0631\u064a\u0627 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0643\u0627\u0641\u0644\u0627 \u0641\u0623\u0633\u0643\u0646\u0647\u0627 \u0641\u064a \u0645\u0643\u0627\u0646 \u0639\u0628\u0627\u062f\u062a\u0647\u060c \u0648\u0643\u0627\u0646 \u0643\u0644\u0651\u064e\u0645\u0627 \u062f\u062e\u0644 \u0639\u0644\u064a\u0647\u0627 \u0647\u0630\u0627 \u0627\u0644\u0645\u0643\u0627\u0646 \u0648\u062c\u062f \u0639\u0646\u062f\u0647\u0627 \u0631\u0632\u0642\u064b\u0627 \u0647\u0646\u064a\u0626\u064b\u0627 \u0645\u0639\u062f\u0651\u0627\u064b \u0642\u0627\u0644: \u064a\u0627 \u0645\u0631\u064a\u0645 \u0645\u0646 \u0623\u064a\u0646 \u0644\u0643\u0650 \u0647\u0630\u0627 \u0627\u0644\u0631\u0632\u0642 \u0627\u0644\u0637\u064a\u0628\u061f \u0642\u0627\u0644\u062a: \u0647\u0648 \u0631\u0632\u0642 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647. \u0625\u0646 \u0627\u0644\u0644\u0647 -\u0628\u0641\u0636\u0644\u0647- \u064a\u0631\u0632\u0642 \u0645\u064e\u0646 \u064a\u0634\u0627\u0621 \u0645\u0650\u0646 \u062e\u0644\u0642\u0647 \u0628\u063a\u064a\u0631 \u062d\u0633\u0627\u0628.","3:38":"\u0639\u0646\u062f\u0645\u0627 \u0631\u0623\u0649 \u0632\u0643\u0631\u064a\u0627 \u0645\u0627 \u0623\u0643\u0631\u0645 \u0627\u0644\u0644\u0647 \u0628\u0647 \u0645\u0631\u064a\u0645 \u0645\u0650\u0646 \u0631\u0632\u0642\u0647 \u0648\u0641\u0636\u0644\u0647 \u062a\u0648\u062c\u0647 \u0625\u0644\u0649 \u0631\u0628\u0647 \u0642\u0627\u0626\u0644\u0627 \u064a\u0627 \u0631\u0628\u0651\u0650 \u0623\u0639\u0637\u0646\u064a \u0645\u0646 \u0639\u0646\u062f\u0643 \u0648\u0644\u062f\u064b\u0627 \u0635\u0627\u0644\u062d\u064b\u0627 \u0645\u0628\u0627\u0631\u0643\u064b\u0627\u060c \u0625\u0646\u0643 \u0633\u0645\u064a\u0639 \u0627\u0644\u062f\u0639\u0627\u0621 \u0644\u0645\u0646 \u062f\u0639\u0627\u0643.","3:39":"\u0641\u0646\u0627\u062f\u062a\u0647 \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u0648\u0647\u0648 \u0648\u0627\u0642\u0641 \u0628\u064a\u0646 \u064a\u062f\u064a \u0627\u0644\u0644\u0647 \u0641\u064a \u0645\u0643\u0627\u0646 \u0635\u0644\u0627\u062a\u0647 \u064a\u062f\u0639\u0648\u0647: \u0623\u0646 \u0627\u0644\u0644\u0647 \u064a\u062e\u0628\u0631\u0643 \u0628\u062e\u0628\u0631 \u064a\u0633\u0631\u0651\u064f\u0643\u060c \u0648\u0647\u0648 \u0623\u0646\u0643 \u0633\u062a\u0631\u0632\u0642 \u0628\u0648\u0644\u062f \u0627\u0633\u0645\u0647 \u064a\u062d\u064a\u0649\u060c \u064a\u064f\u0635\u064e\u062f\u0651\u0650\u0642 \u0628\u0643\u0644\u0645\u0629 \u0645\u0646 \u0627\u0644\u0644\u0647 -\u0648\u0647\u0648 \u0639\u064a\u0633\u0649 \u0628\u0646 \u0645\u0631\u064a\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645-\u060c \u0648\u064a\u0643\u0648\u0646 \u064a\u062d\u064a\u0649 \u0633\u064a\u062f\u064b\u0627 \u0641\u064a \u0642\u0648\u0645\u0647\u060c \u0644\u0647 \u0627\u0644\u0645\u0643\u0627\u0646\u0629 \u0648\u0627\u0644\u0645\u0646\u0632\u0644\u0629 \u0627\u0644\u0639\u0627\u0644\u064a\u0629\u060c \u0648\u062d\u0635\u0648\u0631\u064b\u0627 \u0644\u0627 \u064a\u0623\u062a\u064a \u0627\u0644\u0630\u0646\u0648\u0628 \u0648\u0627\u0644\u0634\u0647\u0648\u0627\u062a \u0627\u0644\u0636\u0627\u0631\u0629\u060c \u0648\u064a\u0643\u0648\u0646 \u0646\u0628\u064a\u0651\u0627\u064b \u0645\u0646 \u0627\u0644\u0635\u0627\u0644\u062d\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0628\u0644\u063a\u0648\u0627 \u0641\u064a \u0627\u0644\u0635\u0651\u064e\u0644\u0627\u062d \u0630\u0631\u0648\u062a\u0647.","3:40":"\u0642\u0627\u0644 \u0632\u0643\u0631\u064a\u0627 \u0641\u0631\u062d\u064b\u0627 \u0645\u062a\u0639\u062c\u0628\u064b\u0627: \u0631\u0628\u0651\u0650 \u0623\u0646\u0651\u064e\u0649 \u064a\u0643\u0648\u0646 \u0644\u064a \u063a\u0644\u0627\u0645 \u0645\u0639 \u0623\u0646 \u0627\u0644\u0634\u064a\u062e\u0648\u062e\u0629 \u0642\u062f \u0628\u0644\u063a\u062a \u0645\u0646\u064a \u0645\u0628\u0644\u063a\u0647\u0627\u060c \u0648\u0627\u0645\u0631\u0623\u062a\u064a \u0639\u0642\u064a\u0645 \u0644\u0627 \u062a\u0644\u062f\u061f \u0642\u0627\u0644: \u0643\u0630\u0644\u0643 \u064a\u0641\u0639\u0644 \u0627\u0644\u0644\u0647 \u0645\u0627 \u064a\u0634\u0627\u0621 \u0645\u0646 \u0627\u0644\u0623\u0641\u0639\u0627\u0644 \u0627\u0644\u0639\u062c\u064a\u0628\u0629 \u0627\u0644\u0645\u062e\u0627\u0644\u0641\u0629 \u0644\u0644\u0639\u0627\u062f\u0629.","3:41":"\u0642\u0627\u0644 \u0632\u0643\u0631\u064a\u0651\u064e\u0627: \u0631\u0628 \u0627\u062c\u0639\u0644 \u0644\u064a \u0639\u0644\u0627\u0645\u0629\u064b \u0623\u0633\u062a\u062f\u0644\u0651\u064f \u0628\u0647\u0627 \u0639\u0644\u0649 \u0648\u062c\u0648\u062f \u0627\u0644\u0648\u0644\u062f \u0645\u0646\u064a; \u0644\u064a\u062d\u0635\u0644 \u0644\u064a \u0627\u0644\u0633\u0631\u0648\u0631 \u0648\u0627\u0644\u0627\u0633\u062a\u0628\u0634\u0627\u0631\u060c \u0642\u0627\u0644: \u0639\u0644\u0627\u0645\u062a\u0643 \u0627\u0644\u062a\u064a \u0637\u0644\u0628\u062a\u0647\u0627: \u0623\u0644\u0627 \u062a\u0633\u062a\u0637\u064a\u0639 \u0627\u0644\u062a\u062d\u062f\u062b \u0625\u0644\u0649 \u0627\u0644\u0646\u0627\u0633 \u062b\u0644\u0627\u062b\u0629 \u0623\u064a\u0627\u0645 \u0625\u0644\u0627 \u0628\u0625\u0634\u0627\u0631\u0629 \u0625\u0644\u064a\u0647\u0645\u060c \u0645\u0639 \u0623\u0646\u0643 \u0633\u0648\u064a\u0651\u064c \u0635\u062d\u064a\u062d\u060c \u0648\u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0645\u062f\u0629 \u0623\u0643\u062b\u0650\u0631\u0652 \u0645\u0646 \u0630\u0643\u0631 \u0631\u0628\u0643\u060c \u0648\u0635\u0644\u0651\u0650 \u0644\u0647 \u0623\u0648\u0627\u062e\u0631 \u0627\u0644\u0646\u0647\u0627\u0631 \u0648\u0623\u0648\u0627\u0626\u0644\u0647.","3:42":"\u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u062d\u064a\u0646 \u0642\u0627\u0644\u062a \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629: \u064a\u0627 \u0645\u0631\u064a\u0645 \u0625\u0646 \u0627\u0644\u0644\u0647 \u0627\u062e\u062a\u0627\u0631\u0643\u0650 \u0644\u0637\u0627\u0639\u062a\u0647 \u0648\u0637\u0647\u0651\u064e\u0631\u0643\u0650 \u0645\u0646 \u0627\u0644\u0623\u062e\u0644\u0627\u0642 \u0627\u0644\u0631\u0630\u064a\u0644\u0629\u060c \u0648\u0627\u062e\u062a\u0627\u0631\u0643\u0650 \u0639\u0644\u0649 \u0646\u0633\u0627\u0621 \u0627\u0644\u0639\u0627\u0644\u0645\u064a\u0646 \u0641\u064a \u0632\u0645\u0627\u0646\u0643.","3:43":"\u064a\u0627 \u0645\u0631\u064a\u0645 \u062f\u0627\u0648\u0645\u064a \u0639\u0644\u0649 \u0627\u0644\u0637\u0627\u0639\u0629 \u0644\u0631\u0628\u0643\u060c \u0648\u0642\u0648\u0645\u064a \u0641\u064a \u062e\u0634\u0648\u0639 \u0648\u062a\u0648\u0627\u0636\u0639\u060c \u0648\u0627\u0633\u062c\u062f\u064a \u0648\u0627\u0631\u0643\u0639\u064a \u0645\u0639 \u0627\u0644\u0631\u0627\u0643\u0639\u064a\u0646; \u0634\u0643\u0631\u064b\u0627 \u0644\u0644\u0647 \u0639\u0644\u0649 \u0645\u0627 \u0623\u0648\u0644\u0627\u0643\u0650 \u0645\u0646 \u0646\u0639\u0645\u0647.","3:44":"\u0630\u0644\u0643 \u0627\u0644\u0630\u064a \u0642\u0635\u0635\u0646\u0627\u0647 \u0639\u0644\u064a\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0645\u0646 \u0623\u062e\u0628\u0627\u0631 \u0627\u0644\u063a\u064a\u0628 \u0627\u0644\u062a\u064a \u0623\u0648\u062d\u0627\u0647\u0627 \u0627\u0644\u0644\u0647 \u0625\u0644\u064a\u0643\u060c \u0625\u0630 \u0644\u0645 \u062a\u0643\u0646 \u0645\u0639\u0647\u0645 \u062d\u064a\u0646 \u0627\u062e\u062a\u0644\u0641\u0648\u0627 \u0641\u064a \u0643\u0641\u0627\u0644\u0629 \u0645\u0631\u064a\u0645 \u0623\u064a\u0651\u064f\u0647\u0645 \u0623\u062d\u0642 \u0628\u0647\u0627 \u0648\u0623\u0648\u0644\u0649\u060c \u0648\u0648\u0642\u0639 \u0628\u064a\u0646\u0647\u0645 \u0627\u0644\u062e\u0635\u0627\u0645\u060c \u0641\u0623\u062c\u0652\u0631\u064e\u0648\u0652\u0627 \u0627\u0644\u0642\u0631\u0639\u0629 \u0628\u0625\u0644\u0642\u0627\u0621 \u0623\u0642\u0644\u0627\u0645\u0647\u0645\u060c \u0641\u0623\u0635\u0627\u0628\u062a \u0632\u0643\u0631\u064a\u0627 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0641\u0641\u0627\u0632 \u0628\u0643\u0641\u0627\u0644\u062a\u0647\u0627.","3:45":"\u0648\u0645\u0627 \u0643\u0646\u062a -\u064a\u0627 \u0646\u0628\u064a \u0627\u0644\u0644\u0647- \u0647\u0646\u0627\u0643 \u062d\u064a\u0646 \u0642\u0627\u0644\u062a \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629: \u064a\u0627 \u0645\u0631\u064a\u0645 \u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u0652\u0643\u0650 \u0628\u0648\u0644\u062f \u064a\u0643\u0648\u0646 \u0648\u062c\u0648\u062f\u0647 \u0628\u0643\u0644\u0645\u0629 \u0645\u0646 \u0627\u0644\u0644\u0647\u060c \u0623\u064a \u064a\u0642\u0648\u0644 \u0644\u0647: \xab\u0643\u0646\xbb \u060c \u0641\u064a\u0643\u0648\u0646\u060c \u0627\u0633\u0645\u0647 \u0627\u0644\u0645\u0633\u064a\u062d \u0639\u064a\u0633\u0649 \u0627\u0628\u0646 \u0645\u0631\u064a\u0645\u060c \u0644\u0647 \u0627\u0644\u062c\u0627\u0647 \u0627\u0644\u0639\u0638\u064a\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u0645\u0646 \u0627\u0644\u0645\u0642\u0631\u0628\u064a\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629.","3:46":"\u0648\u064a\u0643\u0644\u0645 \u0627\u0644\u0646\u0627\u0633 \u0648\u0647\u0648 \u0631\u0636\u064a\u0639 \u0642\u0628\u0644 \u0623\u0648\u0627\u0646 \u0627\u0644\u0643\u0644\u0627\u0645\u060c \u0648\u064a\u062f\u0639\u0648\u0647\u0645 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0648\u0647\u0648 \u0643\u0628\u064a\u0631 \u0642\u062f \u0627\u062c\u062a\u0645\u0639\u062a \u0642\u0648\u062a\u0647 \u0648\u0643\u0645\u0644 \u0634\u0628\u0627\u0628\u0647 \u0628\u0645\u0627 \u0623\u0648\u062d\u0627\u0647 \u0627\u0644\u0644\u0647 \u0625\u0644\u064a\u0647. \u0648\u0647\u0630\u0627 \u062a\u0643\u0644\u064a\u0645 \u0627\u0644\u0646\u0628\u0648\u0651\u064e\u0629 \u0648\u0627\u0644\u062f\u0639\u0648\u0629 \u0648\u0627\u0644\u0625\u0631\u0634\u0627\u062f\u060c \u0648\u0647\u0648 \u0645\u0639\u062f\u0648\u062f \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0635\u0644\u0627\u062d \u0648\u0627\u0644\u0641\u0636\u0644 \u0641\u064a \u0642\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0647.","3:47":"\u0642\u0627\u0644\u062a \u0645\u0631\u064a\u0645 \u0645\u062a\u0639\u062c\u0628\u0629 \u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631: \u0623\u0646\u0651\u064e\u0649 \u064a\u0643\u0648\u0646 \u0644\u064a \u0648\u0644\u062f \u0648\u0623\u0646\u0627 \u0644\u0633\u062a \u0628\u0630\u0627\u062a \u0632\u0648\u062c \u0648\u0644\u0627 \u0628\u064e\u063a\u0650\u064a\u0651\u064d\u061f \u0642\u0627\u0644 \u0644\u0647\u0627 \u0627\u0644\u0645\u064e\u0644\u064e\u0643: \u0647\u0630\u0627 \u0627\u0644\u0630\u064a \u064a\u062d\u062f\u062b \u0644\u0643\u0650 \u0644\u064a\u0633 \u0628\u0645\u0633\u062a\u0628\u0639\u062f \u0639\u0644\u0649 \u0627\u0644\u0625\u0644\u0647 \u0627\u0644\u0642\u0627\u062f\u0631\u060c \u0627\u0644\u0630\u064a \u064a\u0648\u062c\u0650\u062f \u0645\u0627 \u064a\u0634\u0627\u0621 \u0645\u0646 \u0627\u0644\u0639\u064e\u062f\u064e\u0645\u060c \u0641\u0625\u0630\u0627 \u0623\u0631\u0627\u062f \u0625\u064a\u062c\u0627\u062f \u0634\u064a\u0621 \u0641\u0625\u0646\u0645\u0627 \u064a\u0642\u0648\u0644 \u0644\u0647: \xab\u0643\u064f\u0646\xbb \u0641\u064a\u0643\u0648\u0646.","3:48":"\u0648\u064a\u0639\u0644\u0645\u0647 \u0627\u0644\u0643\u062a\u0627\u0628\u0629\u060c \u0648\u0627\u0644\u0633\u062f\u0627\u062f \u0641\u064a \u0627\u0644\u0642\u0648\u0644 \u0648\u0627\u0644\u0641\u0639\u0644\u060c \u0648\u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0627\u0644\u062a\u064a \u0623\u0648\u062d\u0627\u0647\u0627 \u0627\u0644\u0644\u0647 \u0625\u0644\u0649 \u0645\u0648\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644 \u0627\u0644\u0630\u064a \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647.","3:49":"\u0648\u064a\u062c\u0639\u0644\u0647 \u0631\u0633\u0648\u0644\u0627 \u0625\u0644\u0649 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644\u060c \u0648\u064a\u0642\u0648\u0644 \u0644\u0647\u0645: \u0625\u0646\u064a \u0642\u062f \u062c\u0626\u062a\u0643\u0645 \u0628\u0639\u0644\u0627\u0645\u0629 \u0645\u0646 \u0631\u0628\u0643\u0645 \u062a\u062f\u0644\u0651\u064f \u0639\u0644\u0649 \u0623\u0646\u064a \u0645\u0631\u0633\u0644 \u0645\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u0647\u064a \u0623\u0646\u064a \u0623\u0635\u0646\u0639 \u0644\u0643\u0645 \u0645\u0646 \u0627\u0644\u0637\u064a\u0646 \u0645\u062b\u0644 \u0634\u0643\u0644 \u0627\u0644\u0637\u064a\u0631\u060c \u0641\u0623\u0646\u0641\u062e \u0641\u064a\u0647 \u0641\u064a\u0643\u0648\u0646 \u0637\u064a\u0631\u064b\u0627 \u062d\u0642\u064a\u0642\u064a\u0627 \u0628\u0625\u0630\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u0623\u064e\u0634\u0641\u064a \u0645\u064e\u0646 \u0648\u064f\u0644\u0650\u062f \u0623\u0639\u0645\u0649\u060c \u0648\u0645\u064e\u0646 \u0628\u0647 \u0628\u0631\u0635\u060c \u0648\u0623\u064f\u062d\u064a\u064a \u0645\u0646 \u0643\u0627\u0646 \u0645\u064a\u062a\u064b\u0627 \u0628\u0625\u0630\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u0623\u062e\u0628\u0631\u0643\u0645 \u0628\u0645\u0627 \u062a\u0623\u0643\u0644\u0648\u0646 \u0648\u062a\u062f\u0651\u064e\u062e\u0631\u0648\u0646 \u0641\u064a \u0628\u064a\u0648\u062a\u0643\u0645 \u0645\u0646 \u0637\u0639\u0627\u0645\u0643\u0645. \u0625\u0646 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0623\u0645\u0648\u0631 \u0627\u0644\u0639\u0638\u064a\u0645\u0629 \u0627\u0644\u062a\u064a \u0644\u064a\u0633\u062a \u0641\u064a \u0642\u062f\u0631\u0629 \u0627\u0644\u0628\u0634\u0631 \u0644\u062f\u0644\u064a\u0644\u0627 \u0639\u0644\u0649 \u0623\u0646\u064a \u0646\u0628\u064a \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0625\u0646 \u0643\u0646\u062a\u0645 \u0645\u0635\u062f\u0651\u0650\u0642\u064a\u0646 \u062d\u062c\u062c \u0627\u0644\u0644\u0647 \u0648\u0622\u064a\u0627\u062a\u0647\u060c \u0645\u0642\u0631\u0651\u0650\u064a\u0646 \u0628\u062a\u0648\u062d\u064a\u062f\u0647.","3:50":"\u0648\u062c\u0626\u062a\u0643\u0645 \u0645\u0635\u062f\u0642\u064b\u0627 \u0628\u0645\u0627 \u0641\u064a \u0627\u0644\u062a\u0648\u0631\u0627\u0629\u060c \u0648\u0644\u0623\u062d\u0644\u0651\u064e \u0644\u0643\u0645 \u0628\u0648\u062d\u064a \u0645\u0646 \u0627\u0644\u0644\u0647 \u0628\u0639\u0636 \u0645\u0627 \u062d\u0631\u0651\u064e\u0645\u0647 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u062a\u062e\u0641\u064a\u0641\u064b\u0627 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0648\u0631\u062d\u0645\u0629\u060c \u0648\u062c\u0626\u062a\u0643\u0645 \u0628\u062d\u062c\u0629 \u0645\u0646 \u0631\u0628\u0643\u0645 \u0639\u0644\u0649 \u0635\u062f\u0642 \u0645\u0627 \u0623\u0642\u0648\u0644 \u0644\u0643\u0645\u060c \u0641\u0627\u062a\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0644\u0627 \u062a\u062e\u0627\u0644\u0641\u0648\u0627 \u0623\u0645\u0631\u0647\u060c \u0648\u0623\u0637\u064a\u0639\u0648\u0646\u064a \u0641\u064a\u0645\u0627 \u0623\u0628\u0644\u063a\u0643\u0645 \u0628\u0647 \u0639\u0646 \u0627\u0644\u0644\u0647.","3:51":"\u0625\u0646\u0651\u064e \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a \u0623\u062f\u0639\u0648\u0643\u0645 \u0625\u0644\u064a\u0647 \u0647\u0648 \u0648\u062d\u062f\u0647 \u0631\u0628\u064a \u0648\u0631\u0628\u0643\u0645 \u0641\u0627\u0639\u0628\u062f\u0648\u0647\u060c \u0641\u0623\u0646\u0627 \u0648\u0623\u0646\u062a\u0645 \u0633\u0648\u0627\u0621 \u0641\u064a \u0627\u0644\u0639\u0628\u0648\u062f\u064a\u0629 \u0648\u0627\u0644\u062e\u0636\u0648\u0639 \u0644\u0647\u060c \u0648\u0647\u0630\u0627 \u0647\u0648 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0630\u064a \u0644\u0627 \u0627\u0639\u0648\u062c\u0627\u062c \u0641\u064a\u0647.","3:52":"\u0641\u0644\u0645\u0627 \u0627\u0633\u062a\u0634\u0639\u0631 \u0639\u064a\u0633\u0649 \u0645\u0646\u0647\u0645 \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0639\u0644\u0649 \u0627\u0644\u0643\u0641\u0631 \u0646\u0627\u062f\u0649 \u0641\u064a \u0623\u0635\u062d\u0627\u0628\u0647 \u0627\u0644\u062e\u064f\u0644\u0651\u064e\u0635: \u0645\u064e\u0646 \u064a\u0643\u0648\u0646 \u0645\u0639\u064a \u0641\u064a \u0646\u0635\u0631\u0629 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647\u061f \u0642\u0627\u0644 \u0623\u0635\u0641\u064a\u0627\u0621 \u0639\u064a\u0633\u0649: \u0646\u062d\u0646 \u0623\u0646\u0635\u0627\u0631 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u062f\u0627\u0639\u0648\u0646 \u0625\u0644\u064a\u0647\u060c \u0635\u062f\u0651\u064e\u0642\u0646\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0627\u062a\u0628\u0639\u0646\u0627\u0643\u060c \u0648\u0627\u0634\u0647\u062f \u0623\u0646\u062a \u064a\u0627 \u0639\u064a\u0633\u0649 \u0628\u0623\u0646\u0627 \u0645\u0633\u062a\u0633\u0644\u0645\u0648\u0646 \u0644\u0644\u0647 \u0628\u0627\u0644\u062a\u0648\u062d\u064a\u062f \u0648\u0627\u0644\u0637\u0627\u0639\u0629.","3:53":"\u0631\u0628\u0646\u0627 \u0635\u062f\u0651\u064e\u0642\u0646\u0627 \u0628\u0645\u0627 \u0623\u0646\u0632\u0644\u062a \u0645\u0646 \u0627\u0644\u0625\u0646\u062c\u064a\u0644\u060c \u0648\u0627\u062a\u0628\u0639\u0646\u0627 \u0631\u0633\u0648\u0644\u0643 \u0639\u064a\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0641\u0627\u062c\u0639\u0644\u0646\u0627 \u0645\u0645\u0646 \u0634\u0647\u062f\u0648\u0627 \u0644\u0643 \u0628\u0627\u0644\u0648\u062d\u062f\u0627\u0646\u064a\u0629 \u0648\u0644\u0623\u0646\u0628\u064a\u0627\u0626\u0643 \u0628\u0627\u0644\u0631\u0633\u0627\u0644\u0629\u060c \u0648\u0647\u0645 \u0623\u0645\u0629 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0627\u0644\u0630\u064a\u0646 \u064a\u0634\u0647\u062f\u0648\u0646 \u0644\u0644\u0631\u0633\u0644 \u0628\u0623\u0646\u0647\u0645 \u0628\u0644\u0651\u064e\u063a\u0648\u0627 \u0623\u0645\u0645\u0647\u0645.","3:54":"\u0648\u0645\u0643\u0631 \u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0645\u0646 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0628\u0639\u064a\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0628\u0623\u0646 \u0648\u0643\u0651\u064e\u0644\u0648\u0627 \u0628\u0647 \u0645\u0646 \u064a\u0642\u062a\u0644\u0647 \u063a\u0650\u064a\u0652\u0644\u0629\u060c \u0641\u0623\u0644\u0642\u0649 \u0627\u0644\u0644\u0647 \u0634\u064e\u0628\u064e\u0647 \u0639\u064a\u0633\u0649 \u0639\u0644\u0649 \u0631\u062c\u0644 \u062f\u0644\u0651\u064e\u0647\u0645 \u0639\u0644\u064a\u0647 \u0641\u0623\u0645\u0633\u0643\u0648\u0627 \u0628\u0647\u060c \u0648\u0642\u062a\u0644\u0648\u0647 \u0648\u0635\u0644\u0628\u0648\u0647 \u0638\u0646\u0627\u064b \u0645\u0646\u0647\u0645 \u0623\u0646\u0647 \u0639\u064a\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0648\u0627\u0644\u0644\u0647 \u062e\u064a\u0631 \u0627\u0644\u0645\u0627\u0643\u0631\u064a\u0646. \u0648\u0641\u064a \u0647\u0630\u0627 \u0625\u062b\u0628\u0627\u062a \u0635\u0641\u0629 \u0627\u0644\u0645\u0643\u0631 \u0644\u0644\u0647 -\u062a\u0639\u0627\u0644\u0649- \u0639\u0644\u0649 \u0645\u0627 \u064a\u0644\u064a\u0642 \u0628\u062c\u0644\u0627\u0644\u0647 \u0648\u0643\u0645\u0627\u0644\u0647; \u0644\u0623\u0646\u0647 \u0645\u0643\u0631 \u0628\u062d\u0642\u060c \u0648\u0641\u064a \u0645\u0642\u0627\u0628\u0644\u0629 \u0645\u0643\u0631 \u0627\u0644\u0645\u0627\u0643\u0631\u064a\u0646.","3:55":"\u0648\u0645\u0643\u0631 \u0627\u0644\u0644\u0647 \u0628\u0647\u0645 \u062d\u064a\u0646 \u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u0644\u0639\u064a\u0633\u0649: \u0625\u0646\u064a \u0642\u0627\u0628\u0636\u0643 \u0645\u0646 \u0627\u0644\u0623\u0631\u0636 \u0645\u0646 \u063a\u064a\u0631 \u0623\u0646 \u064a\u0646\u0627\u0644\u0643 \u0633\u0648\u0621\u060c \u0648\u0631\u0627\u0641\u0639\u0643 \u0625\u0644\u064a\u0651\u064e \u0628\u0628\u062f\u0646\u0643 \u0648\u0631\u0648\u062d\u0643\u060c \u0648\u0645\u062e\u0644\u0635\u0643 \u0645\u0646 \u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0628\u0643\u060c \u0648\u062c\u0627\u0639\u0644 \u0627\u0644\u0630\u064a\u0646 \u0627\u062a\u0628\u0639\u0648\u0643 -\u0623\u064a \u0639\u0644\u0649 \u062f\u064a\u0646\u0643 \u0648\u0645\u0627 \u062c\u0626\u062a \u0628\u0647 \u0639\u0646 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u062f\u064a\u0646 \u0648\u0627\u0644\u0628\u0634\u0627\u0631\u0629 \u0628\u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u0622\u0645\u064e\u0646\u0648\u0627 \u0628\u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0628\u0639\u062f \u0628\u0639\u062b\u062a\u0647\u060c \u0648\u0627\u0644\u062a\u0632\u0645\u0648\u0627 \u0634\u0631\u064a\u0639\u062a\u0647- \u0638\u0627\u0647\u0631\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0630\u064a\u0646 \u062c\u062d\u062f\u0648\u0627 \u0646\u0628\u0648\u062a\u0643 \u0625\u0644\u0649 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u062b\u0645 \u0625\u0644\u064a\u0651 \u0645\u0635\u064a\u0631\u0643\u0645 \u062c\u0645\u064a\u0639\u064b\u0627 \u064a\u0648\u0645 \u0627\u0644\u062d\u0633\u0627\u0628\u060c \u0641\u0623\u0641\u0635\u0650\u0644 \u0628\u064a\u0646\u0643\u0645 \u0641\u064a\u0645\u0627 \u0643\u0646\u062a\u0645 \u0641\u064a\u0647 \u062a\u062e\u062a\u0644\u0641\u0648\u0646 \u0645\u0646 \u0623\u0645\u0631 \u0639\u064a\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645.","3:56":"\u0641\u0623\u0645\u0651\u064e\u0627 \u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0628\u0627\u0644\u0645\u0633\u064a\u062d \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0623\u0648 \u063a\u064e\u0644\u064e\u0648\u0627 \u0641\u064a\u0647 \u0645\u0646 \u0627\u0644\u0646\u0635\u0627\u0631\u0649\u060c \u0641\u0623\u0639\u0630\u0628\u0647\u0645 \u0639\u0630\u0627\u0628\u064b\u0627 \u0634\u062f\u064a\u062f\u064b\u0627 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627: \u0628\u0627\u0644\u0642\u062a\u0644 \u0648\u0633\u0644\u0652\u0628\u0650 \u0627\u0644\u0623\u0645\u0648\u0627\u0644 \u0648\u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0645\u0644\u0643\u060c \u0648\u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u0628\u0627\u0644\u0646\u0627\u0631\u060c \u0648\u0645\u0627 \u0644\u0647\u0645 \u0645\u0650\u0646 \u0646\u0627\u0635\u0631 \u064a\u0646\u0635\u0631\u0647\u0645 \u0648\u064a\u062f\u0641\u0639 \u0639\u0646\u0647\u0645 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647.","3:57":"\u0648\u0623\u0645\u0627 \u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0635\u0627\u0644\u062d\u0629\u060c \u0641\u064a\u0639\u0637\u064a\u0647\u0645 \u0627\u0644\u0644\u0647 \u062b\u0648\u0627\u0628 \u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0643\u0627\u0645\u0644\u0627 \u063a\u064a\u0631 \u0645\u0646\u0642\u0648\u0635. \u0648\u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u062d\u0628 \u0627\u0644\u0638\u0627\u0644\u0645\u064a\u0646 \u0628\u0627\u0644\u0634\u0631\u0643 \u0648\u0627\u0644\u0643\u0641\u0631.","3:58":"\u0630\u0644\u0643 \u0627\u0644\u0630\u064a \u0646\u0642\u0635\u0651\u064f\u0647 \u0639\u0644\u064a\u0643 \u0641\u064a \u0634\u0623\u0646 \u0639\u064a\u0633\u0649\u060c \u0645\u0646 \u0627\u0644\u062f\u0644\u0627\u0626\u0644 \u0627\u0644\u0648\u0627\u0636\u062d\u0629 \u0639\u0644\u0649 \u0635\u062d\u0629 \u0631\u0633\u0627\u0644\u062a\u0643\u060c \u0648\u0635\u062d\u0629 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u062d\u0643\u064a\u0645 \u0627\u0644\u0630\u064a \u064a\u0641\u0635\u0644 \u0628\u064a\u0646 \u0627\u0644\u062d\u0642 \u0648\u0627\u0644\u0628\u0627\u0637\u0644\u060c \u0641\u0644\u0627 \u0634\u0643 \u0641\u064a\u0647 \u0648\u0644\u0627 \u0627\u0645\u062a\u0631\u0627\u0621.","3:59":"\u0625\u0646\u0651\u064e \u062e\u064e\u0644\u0652\u0642\u064e \u0627\u0644\u0644\u0647 \u0644\u0639\u064a\u0633\u0649 \u0645\u0646 \u063a\u064a\u0631 \u0623\u0628 \u0645\u062b\u064e\u0644\u064f\u0647 \u0643\u0645\u062b\u0644 \u062e\u0644\u0642 \u0627\u0644\u0644\u0647 \u0644\u0622\u062f\u0645 \u0645\u0646 \u063a\u064a\u0631 \u0623\u0628 \u0648\u0644\u0627 \u0623\u0645\u060c \u0625\u0630 \u062e\u0644\u0642\u0647 \u0645\u0646 \u062a\u0631\u0627\u0628 \u0627\u0644\u0623\u0631\u0636\u060c \u062b\u0645 \u0642\u0627\u0644 \u0644\u0647: \xab\u0643\u0646 \u0628\u0634\u0631\u064b\u0627\xbb \u0641\u0643\u0627\u0646. \u0641\u062f\u0639\u0648\u0649 \u0625\u0644\u0647\u064a\u0629 \u0639\u064a\u0633\u0649 \u0644\u0643\u0648\u0646\u0647 \u062e\u0644\u0642 \u0645\u0646 \u063a\u064a\u0631 \u0623\u0628 \u062f\u0639\u0648\u0649 \u0628\u0627\u0637\u0644\u0629; \u0641\u0622\u062f\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u062e\u0644\u0642 \u0645\u0646 \u063a\u064a\u0631 \u0623\u0628 \u0648\u0644\u0627 \u0623\u0645\u060c \u0648\u0627\u062a\u0641\u0642 \u0627\u0644\u062c\u0645\u064a\u0639 \u0639\u0644\u0649 \u0623\u0646\u0647 \u0639\u064e\u0628\u0652\u062f \u0645\u0646 \u0639\u0628\u0627\u062f \u0627\u0644\u0644\u0647.","3:60":"\u0627\u0644\u062d\u0642 \u0627\u0644\u0630\u064a \u0644\u0627 \u0634\u0643 \u0641\u064a\u0647 \u0641\u064a \u0623\u0645\u0631 \u0639\u064a\u0633\u0649 \u0647\u0648 \u0627\u0644\u0630\u064a \u062c\u0627\u0621\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0645\u0646 \u0631\u0628\u0643\u060c \u0641\u062f\u0645 \u0639\u0644\u0649 \u064a\u0642\u064a\u0646\u0643\u060c \u0648\u0639\u0644\u0649 \u0645\u0627 \u0623\u0646\u062a \u0639\u0644\u064a\u0647 \u0645\u0646 \u062a\u0631\u0643 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0621\u060c \u0648\u0644\u0627 \u062a\u0643\u0646 \u0645\u0646 \u0627\u0644\u0634\u0627\u0643\u0651\u0650\u064a\u0646\u060c \u0648\u0641\u064a \u0647\u0630\u0627 \u062a\u062b\u0628\u064a\u062a \u0648\u0637\u0645\u0623\u0646\u0629 \u0644\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645.","3:61":"\u0641\u0645\u064e\u0646 \u062c\u0627\u062f\u0644\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0641\u064a \u0627\u0644\u0645\u0633\u064a\u062d \u0639\u064a\u0633\u0649 \u0627\u0628\u0646 \u0645\u0631\u064a\u0645 \u0645\u0646 \u0628\u0639\u062f \u0645\u0627 \u062c\u0627\u0621\u0643 \u0645\u0646 \u0627\u0644\u0639\u0644\u0645 \u0641\u064a \u0623\u0645\u0631 \u0639\u064a\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0641\u0642\u0644 \u0644\u0647\u0645: \u062a\u0639\u0627\u0644\u0648\u0627 \u0646\u064f\u062d\u0652\u0636\u0650\u0631 \u0623\u0628\u0646\u0627\u0621\u0646\u0627 \u0648\u0623\u0628\u0646\u0627\u0621\u0643\u0645\u060c \u0648\u0646\u0633\u0627\u0621\u0646\u0627 \u0648\u0646\u0633\u0627\u0621\u0643\u0645\u060c \u0648\u0623\u0646\u0641\u0633\u0646\u0627 \u0648\u0623\u0646\u0641\u0633\u0643\u0645\u060c \u062b\u0645 \u0646\u062a\u062c\u0647 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0628\u0627\u0644\u062f\u0639\u0627\u0621 \u0623\u0646 \u064a\u064f\u0646\u0632\u0644 \u0639\u0642\u0648\u0628\u062a\u0647 \u0648\u0644\u0639\u0646\u062a\u0647 \u0639\u0644\u0649 \u0627\u0644\u0643\u0627\u0630\u0628\u064a\u0646 \u0641\u064a \u0642\u0648\u0644\u0647\u0645\u060c \u0627\u0644\u0645\u0635\u0631\u0651\u0650\u064a\u0646 \u0639\u0644\u0649 \u0639\u0646\u0627\u062f\u0647\u0645.","3:62":"\u0625\u0646 \u0647\u0630\u0627 \u0627\u0644\u0630\u064a \u0623\u0646\u0628\u0623\u062a\u0643 \u0628\u0647 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0645\u0646 \u0623\u0645\u0631 \u0639\u064a\u0633\u0649 \u0644\u0647\u0648 \u0627\u0644\u0646\u0628\u0623 \u0627\u0644\u062d\u0642 \u0627\u0644\u0630\u064a \u0644\u0627 \u0634\u0643 \u0641\u064a\u0647\u060c \u0648\u0645\u0627 \u0645\u0646 \u0645\u0639\u0628\u0648\u062f \u064a\u0633\u062a\u062d\u0642 \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647\u060c \u0648\u0625\u0646 \u0627\u0644\u0644\u0647 \u0644\u0647\u0648 \u0627\u0644\u0639\u0632\u064a\u0632 \u0641\u064a \u0645\u0644\u0643\u0647\u060c \u0627\u0644\u062d\u0643\u064a\u0645 \u0641\u064a \u062a\u062f\u0628\u064a\u0631\u0647 \u0648\u0641\u0639\u0644\u0647.","3:63":"\u0641\u0625\u0646 \u0623\u0639\u0631\u0636\u0648\u0627 \u0639\u0646 \u062a\u0635\u062f\u064a\u0642\u0643 \u0648\u0627\u062a\u0628\u0627\u0639\u0643 \u0641\u0647\u0645 \u0627\u0644\u0645\u0641\u0633\u062f\u0648\u0646\u060c \u0648\u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0645 \u0628\u0647\u0645\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a\u0647\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643.","3:64":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649: \u062a\u0639\u0627\u0644\u064e\u0648\u0652\u0627 \u0625\u0644\u0649 \u0643\u0644\u0645\u0629 \u0639\u062f\u0644 \u0648\u062d\u0642 \u0646\u0644\u062a\u0632\u0645 \u0628\u0647\u0627 \u062c\u0645\u064a\u0639\u064b\u0627: \u0648\u0647\u064a \u0623\u0646 \u0646\u064e\u062e\u064f\u0635 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0628\u0627\u0644\u0639\u0628\u0627\u062f\u0629\u060c \u0648\u0644\u0627 \u0646\u062a\u062e\u0630 \u0623\u064a \u0634\u0631\u064a\u0643 \u0645\u0639\u0647\u060c \u0645\u0646 \u0648\u062b\u0646 \u0623\u0648 \u0635\u0646\u0645 \u0623\u0648 \u0635\u0644\u064a\u0628 \u0623\u0648 \u0637\u0627\u063a\u0648\u062a \u0623\u0648 \u063a\u064a\u0631 \u0630\u0644\u0643\u060c \u0648\u0644\u0627 \u064a\u062f\u064a\u0646 \u0628\u0639\u0636\u0646\u0627 \u0644\u0628\u0639\u0636 \u0628\u0627\u0644\u0637\u0627\u0639\u0629 \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647. \u0641\u0625\u0646 \u0623\u0639\u0631\u0636\u0648\u0627 \u0639\u0646 \u0647\u0630\u0647 \u0627\u0644\u062f\u0639\u0648\u0629 \u0627\u0644\u0637\u064a\u0628\u0629 \u0641\u0642\u0648\u0644\u0648\u0627 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646-: \u0627\u0634\u0647\u062f\u0648\u0627 \u0639\u0644\u064a\u0646\u0627 \u0628\u0623\u0646\u0627 \u0645\u0633\u0644\u0645\u0648\u0646 \u0645\u0646\u0642\u0627\u062f\u0648\u0646 \u0644\u0631\u0628\u0646\u0627 \u0628\u0627\u0644\u0639\u0628\u0648\u062f\u064a\u0629 \u0648\u0627\u0644\u0625\u062e\u0644\u0627\u0635. \u0648\u0627\u0644\u062f\u0639\u0648\u0629 \u0625\u0644\u0649 \u0643\u0644\u0645\u0629 \u0633\u0648\u0627\u0621\u060c \u0643\u0645\u0627 \u062a\u064f\u0648\u062c\u0651\u064e\u0647 \u0625\u0644\u0649 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649\u060c \u062a\u0648\u062c\u0651\u064e\u0647 \u0625\u0644\u0649 \u0645\u0646 \u062c\u0631\u0649 \u0645\u062c\u0631\u0627\u0647\u0645.","3:65":"\u064a\u0627 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0643\u062a\u0628 \u0627\u0644\u0645\u0646\u0632\u0644\u0629 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649\u060c \u0643\u064a\u0641 \u064a\u062c\u0627\u062f\u0644 \u0643\u0644 \u0645\u0646\u0643\u0645 \u0641\u064a \u0623\u0646 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0643\u0627\u0646 \u0639\u0644\u0649 \u0645\u0644\u0651\u064e\u062a\u0647\u060c \u0648\u0645\u0627 \u0623\u064f\u0646\u0632\u0644\u062a \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644 \u0625\u0644\u0627 \u0645\u0646 \u0628\u0639\u062f\u0647\u061f \u0623\u0641\u0644\u0627 \u062a\u0641\u0642\u0647\u0648\u0646 \u062e\u0637\u0623 \u0642\u0648\u0644\u0643\u0645: \u0625\u0646 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0643\u0627\u0646 \u064a\u0647\u0648\u062f\u064a\u0627\u064b \u0623\u0648 \u0646\u0635\u0631\u0627\u0646\u064a\u0627\u064b\u060c \u0648\u0642\u062f \u0639\u0644\u0645\u062a\u0645 \u0623\u0646 \u0627\u0644\u064a\u0647\u0648\u062f\u064a\u0629 \u0648\u0627\u0644\u0646\u0635\u0631\u0627\u0646\u064a\u0629 \u062d\u062f\u062b\u062a \u0628\u0639\u062f \u0648\u0641\u0627\u062a\u0647 \u0628\u062d\u064a\u0646\u061f","3:66":"\u0647\u0627 \u0623\u0646\u062a\u0645 \u064a\u0627 \u0647\u0624\u0644\u0627\u0621 \u062c\u0627\u062f\u0644\u062a\u0645 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0645\u062d\u0645\u062f\u064b\u0627 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0641\u064a\u0645\u0627 \u0644\u0643\u0645 \u0628\u0647 \u0639\u0644\u0645 \u0645\u0650\u0646 \u0623\u0645\u0631 \u062f\u064a\u0646\u0643\u0645\u060c \u0645\u0645\u0627 \u062a\u0639\u062a\u0642\u062f\u0648\u0646 \u0635\u062d\u062a\u0647 \u0641\u064a \u0643\u062a\u0628\u0643\u0645\u060c \u0641\u0644\u0650\u0645\u064e \u062a\u062c\u0627\u062f\u0644\u0648\u0646 \u0641\u064a\u0645\u0627 \u0644\u064a\u0633 \u0644\u0643\u0645 \u0628\u0647 \u0639\u0644\u0645 \u0645\u0646 \u0623\u0645\u0631 \u0625\u0628\u0631\u0627\u0647\u064a\u0645\u061f \u0648\u0627\u0644\u0644\u0647 \u064a\u0639\u0644\u0645 \u0627\u0644\u0623\u0645\u0648\u0631 \u0639\u0644\u0649 \u062e\u0641\u0627\u0626\u0647\u0627\u060c \u0648\u0623\u0646\u062a\u0645 \u0644\u0627 \u062a\u0639\u0644\u0645\u0648\u0646.","3:67":"\u0645\u0627 \u0643\u0627\u0646 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u064a\u0647\u0648\u062f\u064a\u0627\u064b \u0648\u0644\u0627 \u0646\u0635\u0631\u0627\u0646\u064a\u0627\u064b\u060c \u0641\u0644\u0645 \u062a\u0643\u0646 \u0627\u0644\u064a\u0647\u0648\u062f\u064a\u0629 \u0648\u0644\u0627 \u0627\u0644\u0646\u0635\u0631\u0627\u0646\u064a\u0629 \u0625\u0644\u0627 \u0645\u0646 \u0628\u0639\u062f\u0647\u060c \u0648\u0644\u0643\u0646 \u0643\u0627\u0646 \u0645\u062a\u0628\u0639\u064b\u0627 \u0644\u0623\u0645\u0631 \u0627\u0644\u0644\u0647 \u0648\u0637\u0627\u0639\u062a\u0647\u060c \u0645\u0633\u062a\u0633\u0644\u0645\u064b\u0627 \u0644\u0631\u0628\u0647\u060c \u0648\u0645\u0627 \u0643\u0627\u0646 \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646.","3:68":"\u0625\u0646\u0651\u064e \u0623\u062d\u0642 \u0627\u0644\u0646\u0627\u0633 \u0628\u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0648\u0623\u062e\u0635\u0647\u0645 \u0628\u0647\u060c \u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0628\u0647 \u0648\u0635\u062f\u0642\u0648\u0627 \u0628\u0631\u0633\u0627\u0644\u062a\u0647 \u0648\u0627\u062a\u0628\u0639\u0648\u0647 \u0639\u0644\u0649 \u062f\u064a\u0646\u0647\u060c \u0648\u0647\u0630\u0627 \u0627\u0644\u0646\u0628\u064a \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0628\u0647. \u0648\u0627\u0644\u0644\u0647 \u0648\u0644\u064a\u0651\u064f \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0628\u0647 \u0627\u0644\u0645\u062a\u0628\u0639\u064a\u0646 \u0634\u0631\u0639\u0647.","3:69":"\u062a\u0645\u0646\u0651\u064e\u062a \u062c\u0645\u0627\u0639\u0629 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0644\u0648 \u064a\u0636\u0644\u0648\u0646\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646- \u0639\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0648\u0645\u0627 \u064a\u0636\u0644\u0648\u0646 \u0625\u0644\u0627 \u0623\u0646\u0641\u0633\u0647\u0645 \u0648\u0623\u062a\u0628\u0627\u0639\u0647\u0645\u060c \u0648\u0645\u0627 \u064a\u062f\u0631\u0648\u0646 \u0630\u0644\u0643 \u0648\u0644\u0627 \u064a\u0639\u0644\u0645\u0648\u0646\u0647.","3:70":"\u064a\u0627 \u0623\u0647\u0644 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644 \u0644\u0645 \u062a\u062c\u062d\u062f\u0648\u0646 \u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0627\u0644\u062a\u064a \u0623\u0646\u0632\u0644\u0647\u0627 \u0639\u0644\u0649 \u0631\u0633\u0644\u0647 \u0641\u064a \u0643\u062a\u0628\u0647\u0645\u060c \u0648\u0641\u064a\u0647\u0627 \u0623\u0646 \u0645\u062d\u0645\u062f\u064b\u0627 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0647\u0648 \u0627\u0644\u0631\u0633\u0648\u0644 \u0627\u0644\u0645\u0646\u062a\u0638\u0631\u060c \u0648\u0623\u0646 \u0645\u0627 \u062c\u0627\u0621\u0643\u0645 \u0628\u0647 \u0647\u0648 \u0627\u0644\u062d\u0642\u060c \u0648\u0623\u0646\u062a\u0645 \u062a\u0634\u0647\u062f\u0648\u0646 \u0628\u0630\u0644\u0643\u061f \u0648\u0644\u0643\u0646\u0643\u0645 \u062a\u0646\u0643\u0631\u0648\u0646\u0647.","3:71":"\u064a\u0627 \u0623\u0647\u0644 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644 \u0644\u0650\u0645\u064e \u062a\u062e\u0644\u0637\u0648\u0646 \u0627\u0644\u062d\u0642 \u0641\u064a \u0643\u062a\u0628\u0643\u0645 \u0628\u0645\u0627 \u062d\u0631\u0641\u062a\u0645\u0648\u0647 \u0648\u0643\u062a\u0628\u062a\u0645\u0648\u0647 \u0645\u0646 \u0627\u0644\u0628\u0627\u0637\u0644 \u0628\u0623\u064a\u062f\u064a\u0643\u0645\u060c \u0648\u062a\u064f\u062e\u0652\u0641\u0648\u0646 \u0645\u0627 \u0641\u064a\u0647\u0645\u0627 \u0645\u0646 \u0635\u0641\u0629 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0623\u0646 \u062f\u064a\u0646\u0647 \u0647\u0648 \u0627\u0644\u062d\u0642\u060c \u0648\u0623\u0646\u062a\u0645 \u062a\u0639\u0644\u0645\u0648\u0646 \u0630\u0644\u0643\u061f","3:72":"\u0648\u0642\u0627\u0644\u062a \u062c\u0645\u0627\u0639\u0629 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f: \u0635\u062f\u0651\u0650\u0642\u0648\u0627 \u0628\u0627\u0644\u0630\u064a \u0623\u064f\u0646\u0632\u0644 \u0639\u0644\u0649 \u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0623\u0648\u0644 \u0627\u0644\u0646\u0647\u0627\u0631 \u0648\u0627\u0643\u0641\u0631\u0648\u0627 \u0622\u062e\u0631\u0647; \u0644\u0639\u0644\u0647\u0645 \u064a\u062a\u0634\u0643\u0643\u0648\u0646 \u0641\u064a \u062f\u064a\u0646\u0647\u0645\u060c \u0648\u064a\u0631\u062c\u0639\u0648\u0646 \u0639\u0646\u0647.","3:73":"\u0648\u0644\u0627 \u062a\u0635\u062f\u0651\u0650\u0642\u0648\u0627 \u062a\u0635\u062f\u064a\u0642\u064b\u0627 \u0635\u062d\u064a\u062d\u064b\u0627 \u0625\u0644\u0627 \u0644\u0645\u064e\u0646 \u062a\u0628\u0639 \u062f\u064a\u0646\u0643\u0645 \u0641\u0643\u0627\u0646 \u064a\u0647\u0648\u062f\u064a\u0627\u064b\u060c \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0625\u0646 \u0627\u0644\u0647\u062f\u0649 \u0648\u0627\u0644\u062a\u0648\u0641\u064a\u0642 \u0647\u062f\u0649 \u0627\u0644\u0644\u0647 \u0648\u062a\u0648\u0641\u064a\u0642\u0647 \u0644\u0644\u0625\u064a\u0645\u0627\u0646 \u0627\u0644\u0635\u062d\u064a\u062d. \u0648\u0642\u0627\u0644\u0648\u0627: \u0644\u0627 \u062a\u0638\u0647\u0631\u0648\u0627 \u0645\u0627 \u0639\u0646\u062f\u0643\u0645 \u0645\u0646 \u0627\u0644\u0639\u0644\u0645 \u0644\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0641\u064a\u062a\u0639\u0644\u0645\u0648\u0646 \u0645\u0646\u0643\u0645 \u0641\u064a\u0633\u0627\u0648\u0648\u0643\u0645 \u0641\u064a \u0627\u0644\u0639\u0644\u0645 \u0628\u0647\u060c \u0648\u062a\u0643\u0648\u0646 \u0644\u0647\u0645 \u0627\u0644\u0623\u0641\u0636\u0644\u064a\u0629 \u0639\u0644\u064a\u0643\u0645\u060c \u0623\u0648 \u0623\u0646 \u064a\u062a\u062e\u0630\u0648\u0647 \u062d\u062c\u0629 \u0639\u0646\u062f \u0631\u0628\u0643\u0645 \u064a\u063a\u0644\u0628\u0648\u0646\u0643\u0645 \u0628\u0647\u0627. \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0625\u0646 \u0627\u0644\u0641\u0636\u0644 \u0648\u0627\u0644\u0639\u0637\u0627\u0621 \u0648\u0627\u0644\u0623\u0645\u0648\u0631 \u0643\u0644\u0647\u0627 \u0628\u064a\u062f \u0627\u0644\u0644\u0647 \u0648\u062a\u062d\u062a \u062a\u0635\u0631\u0641\u0647\u060c \u064a\u0624\u062a\u064a\u0647\u0627 \u0645\u0646 \u064a\u0634\u0627\u0621 \u0645\u0645\u0646 \u0622\u0645\u0646 \u0628\u0647 \u0648\u0628\u0631\u0633\u0648\u0644\u0647. \u0648\u0627\u0644\u0644\u0647 \u0648\u0627\u0633\u0639 \u0639\u0644\u064a\u0645\u060c \u064a\u064e\u0633\u064e\u0639\u064f \u0628\u0639\u0644\u0645\u0647 \u0648\u0639\u0637\u0627\u0626\u0647 \u062c\u0645\u064a\u0639 \u0645\u062e\u0644\u0648\u0642\u0627\u062a\u0647\u060c \u0645\u0645\u0646 \u064a\u0633\u062a\u062d\u0642 \u0641\u0636\u0644\u0647 \u0648\u0646\u0639\u0645\u0647.","3:74":"\u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u062e\u062a\u0635 \u0645\u0650\u0646 \u062e\u0644\u0642\u0647 \u0645\u064e\u0646 \u064a\u0634\u0627\u0621 \u0628\u0627\u0644\u0646\u0628\u0648\u0629 \u0648\u0627\u0644\u0647\u062f\u0627\u064a\u0629 \u0625\u0644\u0649 \u0623\u0643\u0645\u0644 \u0627\u0644\u0634\u0631\u0627\u0626\u0639\u060c \u0648\u0627\u0644\u0644\u0647 \u0630\u0648 \u0627\u0644\u0625\u062d\u0633\u0627\u0646 \u0648\u0627\u0644\u0639\u0637\u0627\u0621 \u0627\u0644\u0643\u062b\u064a\u0631 \u0627\u0644\u0648\u0627\u0633\u0639.","3:75":"\u0648\u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0645\u064e\u0646 \u0625\u0646\u0652 \u062a\u0623\u0645\u0646\u0647 \u0639\u0644\u0649 \u0643\u062b\u064a\u0631 \u0645\u0646 \u0627\u0644\u0645\u0627\u0644 \u064a\u0624\u062f\u0651\u0650\u0647 \u0625\u0644\u064a\u0643 \u0645\u0646 \u063a\u064a\u0631 \u062e\u064a\u0627\u0646\u0629\u060c \u0648\u0645\u0646\u0647\u0645 \u0645\u064e\u0646 \u0625\u0646\u0652 \u062a\u0623\u0645\u0646\u0647 \u0639\u0644\u0649 \u062f\u064a\u0646\u0627\u0631 \u0648\u0627\u062d\u062f\u064d \u0644\u0627 \u064a\u0624\u062f\u0651\u0650\u0647 \u0627\u0644\u064a\u0643\u060c \u0625\u0644\u0627 \u0625\u0630\u0627 \u0628\u0630\u0644\u062a \u063a\u0627\u064a\u0629 \u0627\u0644\u062c\u0647\u062f \u0641\u064a \u0645\u0637\u0627\u0644\u0628\u062a\u0647. \u0648\u0633\u0628\u0628 \u0630\u0644\u0643 \u0639\u0642\u064a\u062f\u0629 \u0641\u0627\u0633\u062f\u0629 \u062a\u062c\u0639\u0644\u0647\u0645 \u064a\u0633\u062a\u062d\u0644\u0651\u064f\u0648\u0646 \u0623\u0645\u0648\u0627\u0644 \u0627\u0644\u0639\u0631\u0628 \u0628\u0627\u0644\u0628\u0627\u0637\u0644\u060c \u0648\u064a\u0642\u0648\u0644\u0648\u0646: \u0644\u064a\u0633 \u0639\u0644\u064a\u0646\u0627 \u0641\u064a \u0623\u0643\u0644 \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0625\u062b\u0645 \u0648\u0644\u0627 \u062d\u0631\u062c; \u0644\u0623\u0646 \u0627\u0644\u0644\u0647 \u0623\u062d\u0644\u0651\u064e\u0647\u0627 \u0644\u0646\u0627. \u0648\u0647\u0630\u0627 \u0643\u0630\u0628 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u064a\u0642\u0648\u0644\u0648\u0646\u0647 \u0628\u0623\u0644\u0633\u0646\u062a\u0647\u0645\u060c \u0648\u0647\u0645 \u064a\u0639\u0644\u0645\u0648\u0646 \u0623\u0646\u0647\u0645 \u0643\u0627\u0630\u0628\u0648\u0646.","3:76":"\u0644\u064a\u0633 \u0627\u0644\u0623\u0645\u0631 \u0643\u0645\u0627 \u0632\u0639\u0645 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0643\u0627\u0630\u0628\u0648\u0646\u060c \u0641\u0625\u0646 \u0627\u0644\u0645\u062a\u0642\u064a \u062d\u0642\u0627\u064b \u0647\u0648 \u0645\u0646 \u0623\u0648\u0641\u0649 \u0628\u0645\u0627 \u0639\u0627\u0647\u062f \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0645\u0646 \u0623\u062f\u0627\u0621 \u0627\u0644\u0623\u0645\u0627\u0646\u0629 \u0648\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0647 \u0648\u0628\u0631\u0633\u0644\u0647 \u0648\u0627\u0644\u062a\u0632\u0645 \u0647\u062f\u064a\u0647 \u0648\u0634\u0631\u0639\u0647\u060c \u0648\u062e\u0627\u0641 \u0627\u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644 \u0641\u0627\u0645\u062a\u062b\u0644 \u0623\u0645\u0631\u0647 \u0648\u0627\u0646\u062a\u0647\u0649 \u0639\u0645\u0627 \u0646\u0647\u0649 \u0639\u0646\u0647. \u0648\u0627\u0644\u0644\u0647 \u064a\u062d\u0628 \u0627\u0644\u0645\u062a\u0642\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u062a\u0642\u0648\u0646 \u0627\u0644\u0634\u0631\u0643 \u0648\u0627\u0644\u0645\u0639\u0627\u0635\u064a.","3:77":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u0633\u062a\u0628\u062f\u0644\u0648\u0646 \u0628\u0639\u0647\u062f \u0627\u0644\u0644\u0647 \u0648\u0648\u0635\u064a\u062a\u0647 \u0627\u0644\u062a\u064a \u0623\u0648\u0635\u0649 \u0628\u0647\u0627 \u0641\u064a \u0627\u0644\u0643\u062a\u0628 \u0627\u0644\u062a\u064a \u0623\u0646\u0632\u0644\u0647\u0627 \u0639\u0644\u0649 \u0623\u0646\u0628\u064a\u0627\u0646\u0647\u0645\u060c \u0639\u0648\u0636\u064b\u0627 \u0648\u0628\u062f\u0644\u0627 \u062e\u0633\u064a\u0633\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u062d\u0637\u0627\u0645\u0647\u0627\u060c \u0623\u0648\u0644\u0626\u0643 \u0644\u0627 \u0646\u0635\u064a\u0628 \u0644\u0647\u0645 \u0645\u0646 \u0627\u0644\u062b\u0648\u0627\u0628 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u0644\u0627 \u064a\u0643\u0644\u0645\u0647\u0645 \u0627\u0644\u0644\u0647 \u0628\u0645\u0627 \u064a\u0633\u0631\u0647\u0645\u060c \u0648\u0644\u0627 \u064a\u0646\u0638\u0631 \u0625\u0644\u064a\u0647\u0645 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u0628\u0639\u064a\u0646 \u0627\u0644\u0631\u062d\u0645\u0629\u060c \u0648\u0644\u0627 \u064a\u0637\u0647\u0631\u0647\u0645 \u0645\u0646 \u062f\u0646\u0633 \u0627\u0644\u0630\u0646\u0648\u0628 \u0648\u0627\u0644\u0643\u0641\u0631\u060c \u0648\u0644\u0647\u0645 \u0639\u0630\u0627\u0628 \u0645\u0648\u062c\u0639.","3:78":"\u0648\u0625\u0646\u0651\u064e \u0645\u0650\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0644\u064e\u062c\u0645\u0627\u0639\u0629\u064b \u064a\u062d\u0631\u0641\u0648\u0646 \u0627\u0644\u0643\u0644\u0627\u0645 \u0639\u0646 \u0645\u0648\u0627\u0636\u0639\u0647\u060c \u0648\u064a\u0628\u062f\u0644\u0648\u0646 \u0643\u0644\u0627\u0645 \u0627\u0644\u0644\u0647; \u0644\u064a\u0648\u0647\u0645\u0648\u0627 \u063a\u064a\u0631\u0647\u0645 \u0623\u0646 \u0647\u0630\u0627 \u0645\u0646 \u0627\u0644\u0643\u0644\u0627\u0645 \u0627\u0644\u0645\u0646\u0632\u0644\u060c \u0648\u0647\u0648 \u0627\u0644\u062a\u0648\u0631\u0627\u0629\u060c \u0648\u0645\u0627 \u0647\u0648 \u0645\u0646\u0647\u0627 \u0641\u064a \u0634\u064a\u0621\u060c \u0648\u064a\u0642\u0648\u0644\u0648\u0646: \u0647\u0630\u0627 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0623\u0648\u062d\u0627\u0647 \u0627\u0644\u0644\u0647 \u0625\u0644\u0649 \u0646\u0628\u064a\u0647 \u0645\u0648\u0633\u0649\u060c \u0648\u0645\u0627 \u0647\u0648 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647\u060c \u0648\u0647\u0645 \u0644\u0623\u062c\u0644 \u062f\u0646\u064a\u0627\u0647\u0645 \u064a\u0642\u0648\u0644\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0627\u0644\u0643\u0630\u0628 \u0648\u0647\u0645 \u064a\u0639\u0644\u0645\u0648\u0646 \u0623\u0646\u0647\u0645 \u0643\u0627\u0630\u0628\u0648\u0646.","3:79":"\u0645\u0627 \u064a\u0646\u0628\u063a\u064a \u0644\u0623\u062d\u062f \u0645\u0646 \u0627\u0644\u0628\u0634\u0631 \u0623\u0646 \u064a\u064f\u0646\u0632\u0651\u0650\u0644 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0643\u062a\u0627\u0628\u0647 \u0648\u064a\u062c\u0639\u0644\u0647 \u062d\u0643\u0645\u064b\u0627 \u0628\u064a\u0646 \u062e\u0644\u0642\u0647 \u0648\u064a\u062e\u062a\u0627\u0631\u0647 \u0646\u0628\u064a\u0627\u064b\u060c \u062b\u0645 \u064a\u0642\u0648\u0644 \u0644\u0644\u0646\u0627\u0633: \u0627\u0639\u0628\u062f\u0648\u0646\u064a \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0643\u0646 \u064a\u0642\u0648\u0644: \u0643\u0648\u0646\u0648\u0627 \u062d\u0643\u0645\u0627\u0621 \u0641\u0642\u0647\u0627\u0621 \u0639\u0644\u0645\u0627\u0621 \u0628\u0645\u0627 \u0643\u0646\u062a\u0645 \u062a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u0648\u0646\u0647 \u063a\u064a\u0631\u0643\u0645 \u0645\u0646 \u0648\u062d\u064a \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0628\u0645\u0627 \u062a\u062f\u0631\u0633\u0648\u0646\u0647 \u0645\u0646\u0647 \u062d\u0641\u0638\u064b\u0627 \u0648\u0639\u0644\u0645\u064b\u0627 \u0648\u0641\u0642\u0647\u064b\u0627.","3:80":"\u0648\u0645\u0627 \u0643\u0627\u0646 \u0644\u0623\u062d\u062f \u0645\u0646\u0647\u0645 \u0623\u0646 \u064a\u0623\u0645\u0631\u0643\u0645 \u0628\u0627\u062a\u062e\u0627\u0630 \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u0648\u0627\u0644\u0646\u0628\u064a\u064a\u0646 \u0623\u0631\u0628\u0627\u0628\u064b\u0627 \u062a\u0639\u0628\u062f\u0648\u0646\u0647\u0645 \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647. \u0623\u064e\u064a\u064f\u0639\u0652\u0642\u064e\u0644\u064f -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633- \u0623\u0646 \u064a\u0623\u0645\u0631\u0643\u0645 \u0628\u0627\u0644\u0643\u0641\u0631 \u0628\u0627\u0644\u0644\u0647 \u0628\u0639\u062f \u0627\u0646\u0642\u064a\u0627\u062f\u0643\u0645 \u0644\u0623\u0645\u0631\u0647\u061f","3:81":"\u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0625\u0630 \u0623\u062e\u0630 \u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0627\u0644\u0639\u0647\u062f \u0627\u0644\u0645\u0624\u0643\u062f \u0639\u0644\u0649 \u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621: \u0644\u064e\u0626\u0650\u0646\u0652 \u0622\u062a\u064a\u062a\u0643\u0645 \u0645\u0646 \u0643\u062a\u0627\u0628 \u0648\u062d\u0643\u0645\u0629\u060c \u062b\u0645 \u062c\u0627\u0621\u0643\u0645 \u0631\u0633\u0648\u0644 \u0645\u0646 \u0639\u0646\u062f\u064a\u060c \u0645\u0635\u062f\u0642 \u0644\u0645\u0627 \u0645\u0639\u0643\u0645 \u0644\u062a\u0624\u0645\u0646\u0646 \u0628\u0647 \u0648\u0644\u062a\u0646\u0635\u0631\u0646\u0651\u064e\u0647. \u0641\u0647\u0644 \u0623\u0642\u0631\u0631\u062a\u0645 \u0648\u0627\u0639\u062a\u0631\u0641\u062a\u0645 \u0628\u0630\u0644\u0643 \u0648\u0623\u062e\u0630\u062a\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643 \u0639\u0647\u062f\u064a \u0627\u0644\u0645\u0648\u062b\u0642\u061f \u0642\u0627\u0644\u0648\u0627: \u0623\u0642\u0631\u0631\u0646\u0627 \u0628\u0630\u0644\u0643\u060c \u0642\u0627\u0644: \u0641\u0644\u064a\u0634\u0647\u062f\u0652 \u0628\u0639\u0636\u0643\u0645 \u0639\u0644\u0649 \u0628\u0639\u0636\u060c \u0648\u0627\u0634\u0647\u062f\u0648\u0627 \u0639\u0644\u0649 \u0623\u0645\u0645\u0643\u0645 \u0628\u0630\u0644\u0643\u060c \u0648\u0623\u0646\u0627 \u0645\u0639\u0643\u0645 \u0645\u0646 \u0627\u0644\u0634\u0627\u0647\u062f\u064a\u0646 \u0639\u0644\u064a\u0643\u0645 \u0648\u0639\u0644\u064a\u0647\u0645. \u0648\u0641\u064a \u0647\u0630\u0627 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0623\u062e\u0630 \u0627\u0644\u0645\u064a\u062b\u0627\u0642 \u0639\u0644\u0649 \u0643\u0644 \u0646\u0628\u064a \u0623\u0646 \u064a\u0624\u0645\u0646 \u0628\u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0623\u062e\u0630 \u0627\u0644\u0645\u064a\u062b\u0627\u0642 \u0639\u0644\u0649 \u0623\u0645\u0645 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0628\u0630\u0644\u0643.","3:82":"\u0641\u0645\u0646 \u0623\u0639\u0631\u0636 \u0639\u0646 \u062f\u0639\u0648\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0628\u0639\u062f \u0647\u0630\u0627 \u0627\u0644\u0628\u064a\u0627\u0646 \u0648\u0647\u0630\u0627 \u0627\u0644\u0639\u0647\u062f \u0627\u0644\u0630\u064a \u0623\u062e\u0630\u0647 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0623\u0646\u0628\u064a\u0627\u0626\u0647\u060c \u0641\u0623\u0648\u0644\u0626\u0643 \u0647\u0645 \u0627\u0644\u062e\u0627\u0631\u062c\u0648\u0646 \u0639\u0646 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647 \u0648\u0637\u0627\u0639\u0629 \u0631\u0628\u0647\u0645.","3:83":"\u0623\u064a\u0631\u064a\u062f \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0641\u0627\u0633\u0642\u0648\u0646 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u063a\u064a\u0631 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647 -\u0648\u0647\u0648 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0627\u0644\u0630\u064a \u0628\u0639\u062b \u0627\u0644\u0644\u0647 \u0628\u0647 \u0645\u062d\u0645\u062f\u0627 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645-\u060c \u0645\u0639 \u0623\u0646 \u0643\u0644 \u0645\u064e\u0646 \u0641\u064a \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636 \u0627\u0633\u062a\u0633\u0644\u0645 \u0648\u0627\u0646\u0642\u0627\u062f \u0648\u062e\u0636\u0639 \u0644\u0644\u0647 \u0637\u0648\u0627\u0639\u064a\u0629 -\u0643\u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646- \u0648\u0631\u063a\u0645\u064b\u0627 \u0639\u0646\u0647\u0645 \u0639\u0646\u062f \u0627\u0644\u0634\u062f\u0627\u0626\u062f\u060c \u062d\u064a\u0646 \u0644\u0627 \u064a\u0646\u0641\u0639\u0647\u0645 \u0630\u0644\u0643 \u0648\u0647\u0645 \u0627\u0644\u0643\u0641\u0627\u0631\u060c \u0643\u0645\u0627 \u062e\u0636\u0639 \u0644\u0647 \u0633\u0627\u0626\u0631 \u0627\u0644\u0643\u0627\u0626\u0646\u0627\u062a\u060c \u0648\u0625\u0644\u064a\u0647 \u064a\u064f\u0631\u062c\u064e\u0639\u0648\u0646 \u064a\u0648\u0645 \u0627\u0644\u0645\u0639\u0627\u062f\u060c \u0641\u064a\u062c\u0627\u0632\u064a \u0643\u0644\u0627 \u0628\u0639\u0645\u0644\u0647. \u0648\u0647\u0630\u0627 \u062a\u062d\u0630\u064a\u0631 \u0645\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u062e\u0644\u0642\u0647 \u0623\u0646 \u064a\u0631\u062c\u0639 \u0625\u0644\u064a\u0647 \u0623\u062d\u062f \u0645\u0646\u0647\u0645 \u0639\u0644\u0649 \u063a\u064a\u0631 \u0645\u0644\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645.","3:84":"\u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0635\u062f\u0651\u064e\u0642\u0646\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0623\u0637\u0639\u0646\u0627\u060c \u0641\u0644\u0627 \u0631\u0628 \u0644\u0646\u0627 \u063a\u064a\u0631\u0647\u060c \u0648\u0644\u0627 \u0645\u0639\u0628\u0648\u062f \u0644\u0646\u0627 \u0633\u0648\u0627\u0647\u060c \u0648\u0622\u0645\u0646\u0651\u064e\u0627 \u0628\u0627\u0644\u0648\u062d\u064a \u0627\u0644\u0630\u064a \u0623\u0646\u0632\u0644\u0647 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0646\u0627\u060c \u0648\u0627\u0644\u0630\u064a \u0623\u0646\u0632\u0644\u0647 \u0639\u0644\u0649 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u062e\u0644\u064a\u0644 \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u0628\u0646\u064a\u0647 \u0625\u0633\u0645\u0627\u0639\u064a\u0644 \u0648\u0625\u0633\u062d\u0627\u0642\u060c \u0648\u0627\u0628\u0646 \u0627\u0628\u0646\u0647 \u064a\u0639\u0642\u0648\u0628 \u0628\u0646 \u0625\u0633\u062d\u0627\u0642\u060c \u0648\u0627\u0644\u0630\u064a \u0623\u0646\u0632\u0644\u0647 \u0639\u0644\u0649 \u0627\u0644\u0623\u0633\u0628\u0627\u0637 -\u0648\u0647\u0645 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u0643\u0627\u0646\u0648\u0627 \u0641\u064a \u0642\u0628\u0627\u0626\u0644 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0627\u0644\u0627\u062b\u0646\u062a\u064a \u0639\u0634\u0631\u0629 \u0645\u0650\u0646 \u0648\u0644\u062f \u064a\u0639\u0642\u0648\u0628- \u0648\u0645\u0627 \u0623\u0648\u062a\u064a \u0645\u0648\u0633\u0649 \u0648\u0639\u064a\u0633\u0649 \u0645\u0646 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644\u060c \u0648\u0645\u0627 \u0623\u0646\u0632\u0644\u0647 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0623\u0646\u0628\u064a\u0627\u0626\u0647\u060c \u0646\u0624\u0645\u0646 \u0628\u0630\u0644\u0643 \u0643\u0644\u0647\u060c \u0648\u0644\u0627 \u0646\u0641\u0631\u0642 \u0628\u064a\u0646 \u0623\u062d\u062f \u0645\u0646\u0647\u0645\u060c \u0648\u0646\u062d\u0646 \u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0645\u0646\u0642\u0627\u062f\u0648\u0646 \u0628\u0627\u0644\u0637\u0627\u0639\u0629\u060c \u0645\u064f\u0642\u0650\u0631\u0651\u064f\u0648\u0646 \u0644\u0647 \u0628\u0627\u0644\u0631\u0628\u0648\u0628\u064a\u0629 \u0648\u0627\u0644\u0623\u0644\u0648\u0647\u064a\u0629 \u0648\u0627\u0644\u0639\u0628\u0627\u062f\u0629.","3:85":"\u0648\u0645\u0646 \u064a\u0637\u0644\u0628 \u062f\u064a\u0646\u064b\u0627 \u063a\u064a\u0631 \u062f\u064a\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0627\u0644\u0630\u064a \u0647\u0648 \u0627\u0644\u0627\u0633\u062a\u0633\u0644\u0627\u0645 \u0644\u0644\u0647 \u0628\u0627\u0644\u062a\u0648\u062d\u064a\u062f \u0648\u0627\u0644\u0627\u0646\u0642\u064a\u0627\u062f \u0644\u0647 \u0628\u0627\u0644\u0637\u0627\u0639\u0629\u060c \u0648\u0627\u0644\u0639\u0628\u0648\u062f\u064a\u0629\u060c \u0648\u0644\u0631\u0633\u0648\u0644\u0647 \u0627\u0644\u0646\u0628\u064a \u0627\u0644\u062e\u0627\u062a\u0645 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0647 \u0648\u0628\u0645\u062a\u0627\u0628\u0639\u062a\u0647 \u0648\u0645\u062d\u0628\u062a\u0647 \u0638\u0627\u0647\u0631\u064b\u0627 \u0648\u0628\u0627\u0637\u0646\u064b\u0627\u060c \u0641\u0644\u0646 \u064a\u064f\u0642\u0628\u0644 \u0645\u0646\u0647 \u0630\u0644\u0643\u060c \u0648\u0647\u0648 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u0645\u0646 \u0627\u0644\u062e\u0627\u0633\u0631\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0628\u062e\u0633\u0648\u0627 \u0623\u0646\u0641\u0633\u0647\u0645 \u062d\u0638\u0648\u0638\u0647\u0627.","3:86":"\u0643\u064a\u0641 \u064a\u0648\u0641\u0642 \u0627\u0644\u0644\u0647 \u0644\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0647 \u0648\u0628\u0631\u0633\u0648\u0644\u0647 \u0642\u0648\u0645\u064b\u0627 \u062c\u062d\u062f\u0648\u0627 \u0646\u0628\u0648\u0629 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0628\u0639\u062f \u0625\u064a\u0645\u0627\u0646\u0647\u0645 \u0628\u0647\u060c \u0648\u0634\u0647\u062f\u0648\u0627 \u0623\u0646 \u0645\u062d\u0645\u062f\u064b\u0627 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u062d\u0642 \u0648\u0645\u0627 \u062c\u0627\u0621 \u0628\u0647 \u0647\u0648 \u0627\u0644\u062d\u0642\u060c \u0648\u062c\u0627\u0621\u0647\u0645 \u0627\u0644\u062d\u062c\u062c \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u062f\u0644\u0627\u0626\u0644 \u0628\u0635\u062d\u0629 \u0630\u0644\u0643\u061f \u0648\u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u0648\u0641\u0642 \u0644\u0644\u062d\u0642 \u0648\u0627\u0644\u0635\u0648\u0627\u0628 \u0627\u0644\u062c\u0645\u0627\u0639\u0629 \u0627\u0644\u0638\u0644\u0645\u0629\u060c \u0648\u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u0639\u062f\u0644\u0648\u0627 \u0639\u0646 \u0627\u0644\u062d\u0642 \u0625\u0644\u0649 \u0627\u0644\u0628\u0627\u0637\u0644\u060c \u0641\u0627\u062e\u062a\u0627\u0631\u0648\u0627 \u0627\u0644\u0643\u0641\u0631 \u0639\u0644\u0649 \u0627\u0644\u0625\u064a\u0645\u0627\u0646.","3:87":"\u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0638\u0627\u0644\u0645\u0648\u0646 \u062c\u0632\u0627\u0624\u0647\u0645 \u0623\u0646\u0651\u064e \u0639\u0644\u064a\u0647\u0645 \u0644\u0639\u0646\u0629 \u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u0648\u0627\u0644\u0646\u0627\u0633\u0650 \u0623\u062c\u0645\u0639\u064a\u0646\u060c \u0641\u0647\u0645 \u0645\u0637\u0631\u0648\u062f\u0648\u0646 \u0645\u0646 \u0631\u062d\u0645\u0629 \u0627\u0644\u0644\u0647.","3:88":"\u0645\u0627\u0643\u062b\u064a\u0646 \u0641\u064a \u0627\u0644\u0646\u0627\u0631\u060c \u0644\u0627 \u064a\u064f\u0631\u0641\u0639 \u0639\u0646\u0647\u0645 \u0627\u0644\u0639\u0630\u0627\u0628 \u0642\u0644\u064a\u0644\u0627 \u0644\u064a\u0633\u062a\u0631\u064a\u062d\u0648\u0627\u060c \u0648\u0644\u0627 \u064a\u064f\u0624\u062e\u0631 \u0639\u0646\u0647\u0645 \u0644\u0645\u0639\u0630\u0631\u0629 \u064a\u0639\u062a\u0630\u0631\u0648\u0646 \u0628\u0647\u0627.","3:89":"\u0625\u0644\u0627 \u0627\u0644\u0630\u064a\u0646 \u0631\u062c\u0639\u0648\u0627 \u0625\u0644\u0649 \u0631\u0628\u0647\u0645 \u0628\u0627\u0644\u062a\u0648\u0628\u0629 \u0627\u0644\u0646\u0635\u0648\u062d \u0645\u0646 \u0628\u0639\u062f \u0643\u0641\u0631\u0647\u0645 \u0648\u0638\u0644\u0645\u0647\u0645\u060c \u0648\u0623\u0635\u0644\u062d\u0648\u0627 \u0645\u0627 \u0623\u0641\u0633\u062f\u0648\u0647 \u0628\u062a\u0648\u0628\u062a\u0647\u0645 \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u0642\u0628\u0644\u0647\u0627\u060c \u0641\u0647\u0648 \u063a\u0641\u0648\u0631 \u0644\u0630\u0646\u0648\u0628 \u0639\u0628\u0627\u062f\u0647\u060c \u0631\u062d\u064a\u0645 \u0628\u0647\u0645.","3:90":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0628\u0639\u062f \u0625\u064a\u0645\u0627\u0646\u0647\u0645 \u0648\u0627\u0633\u062a\u0645\u0631\u0648\u0627 \u0639\u0644\u0649 \u0627\u0644\u0643\u0641\u0631 \u0625\u0644\u0649 \u0627\u0644\u0645\u0645\u0627\u062a \u0644\u0646 \u062a\u064f\u0642\u0628\u0644 \u0644\u0647\u0645 \u062a\u0648\u0628\u0629 \u0639\u0646\u062f \u062d\u0636\u0648\u0631 \u0627\u0644\u0645\u0648\u062a\u060c \u0648\u0623\u0648\u0644\u0626\u0643 \u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u0636\u0644\u0651\u064f\u0648\u0627 \u0627\u0644\u0633\u0628\u064a\u0644\u060c \u0641\u0623\u062e\u0637\u064e\u0624\u064f\u0648\u0627 \u0645\u0646\u0647\u062c\u0647.","3:91":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u062c\u062d\u062f\u0648\u0627 \u0646\u0628\u0648\u0629 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0645\u0627\u062a\u0648\u0627 \u0639\u0644\u0649 \u0627\u0644\u0643\u0641\u0631 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0641\u0644\u0646 \u064a\u064f\u0642\u0628\u0644 \u0645\u0646 \u0623\u062d\u062f\u0647\u0645 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u0645\u0644\u0621 \u0627\u0644\u0623\u0631\u0636 \u0630\u0647\u0628\u064b\u0627; \u0644\u064a\u0641\u062a\u062f\u064a \u0628\u0647 \u0646\u0641\u0633\u0647 \u0645\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0648 \u0627\u0641\u062a\u062f\u0649 \u0628\u0647 \u0646\u0641\u0633\u0647 \u0641\u0650\u0639\u0652\u0644\u0627. \u0623\u0648\u0644\u0626\u0643 \u0644\u0647\u0645 \u0639\u0630\u0627\u0628 \u0645\u0648\u062c\u0639\u060c \u0648\u0645\u0627 \u0644\u0647\u0645 \u0645\u0646 \u0623\u062d\u062f \u064a\u0646\u0642\u0630\u0647\u0645 \u0645\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647.","3:92":"\u0644\u0646 \u062a\u062f\u0631\u0643\u0648\u0627 \u0627\u0644\u062c\u0646\u0629 \u062d\u062a\u0649 \u062a\u062a\u0635\u062f\u0642\u0648\u0627 \u0645\u0645\u0627 \u062a\u062d\u0628\u0648\u0646\u060c \u0648\u0623\u064a \u0634\u064a\u0621 \u062a\u062a\u0635\u062f\u0642\u0648\u0627 \u0628\u0647 \u0645\u0647\u0645\u0627 \u0643\u0627\u0646 \u0642\u0644\u064a\u0644\u0627 \u0623\u0648 \u0643\u062b\u064a\u0631\u064b\u0627 \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0628\u0647 \u0639\u0644\u064a\u0645\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a \u0643\u0644 \u0645\u0646\u0641\u0642 \u0628\u062d\u0633\u0628 \u0639\u0645\u0644\u0647.","3:93":"\u0643\u0644 \u0627\u0644\u0623\u0637\u0639\u0645\u0629 \u0627\u0644\u0637\u064a\u0651\u0650\u0628\u0629 \u0643\u0627\u0646\u062a \u062d\u0644\u0627\u0644\u0627 \u0644\u0623\u0628\u0646\u0627\u0621 \u064a\u0639\u0642\u0648\u0628 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0625\u0644\u0627 \u0645\u0627 \u062d\u0631\u0651\u064e\u0645 \u064a\u0639\u0642\u0648\u0628 \u0639\u0644\u0649 \u0646\u0641\u0633\u0647 \u0644\u0645\u0631\u0636 \u0646\u0632\u0644 \u0628\u0647\u060c \u0648\u0630\u0644\u0643 \u0645\u0650\u0646 \u0642\u0628\u0644 \u0623\u0646 \u062a\u064f\u0646\u064e\u0632\u0651\u064e\u0644 \u0627\u0644\u062a\u0648\u0631\u0627\u0629. \u0641\u0644\u0645\u0627 \u0646\u064f\u0632\u0651\u0650\u0644\u062a \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u062d\u0631\u0651\u064e\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0628\u0639\u0636 \u0627\u0644\u0623\u0637\u0639\u0645\u0629 \u0627\u0644\u062a\u064a \u0643\u0627\u0646\u062a \u062d\u0644\u0627\u0644\u0627 \u0644\u0647\u0645; \u0648\u0630\u0644\u0643 \u0644\u0638\u0644\u0645\u0647\u0645 \u0648\u0628\u063a\u064a\u0647\u0645. \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0647\u0627\u062a\u0648\u0627 \u0627\u0644\u062a\u0648\u0631\u0627\u0629\u060c \u0648\u0627\u0642\u0631\u0624\u0648\u0627 \u0645\u0627 \u0641\u064a\u0647\u0627 \u0625\u0646 \u0643\u0646\u062a\u0645 \u0645\u062d\u0642\u064a\u0646 \u0641\u064a \u062f\u0639\u0648\u0627\u0643\u0645 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0623\u0646\u0632\u0644 \u0641\u064a\u0647\u0627 \u062a\u062d\u0631\u064a\u0645 \u0645\u0627 \u062d\u0631\u0651\u064e\u0645\u0647 \u064a\u0639\u0642\u0648\u0628 \u0639\u0644\u0649 \u0646\u0641\u0633\u0647\u060c \u062d\u062a\u0649 \u062a\u0639\u0644\u0645\u0648\u0627 \u0635\u062f\u0642 \u0645\u0627 \u062c\u0627\u0621 \u0641\u064a \u0627\u0644\u0642\u0631\u0622\u0646 \u0645\u0646 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0644\u0645 \u064a\u062d\u0631\u0645 \u0639\u0644\u0649 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0634\u064a\u0626\u064b\u0627 \u0645\u0646 \u0642\u0628\u0644 \u0646\u0632\u0648\u0644 \u0627\u0644\u062a\u0648\u0631\u0627\u0629\u060c \u0625\u0644\u0627 \u0645\u0627 \u062d\u0631\u0651\u064e\u0645\u0647 \u064a\u0639\u0642\u0648\u0628 \u0639\u0644\u0649 \u0646\u0641\u0633\u0647.","3:94":"\u0641\u0645\u064e\u0646 \u0643\u0630\u0628 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0628\u0639\u062f \u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u0648\u0636\u0648\u062d \u0627\u0644\u062d\u0642\u064a\u0642\u0629\u060c \u0641\u0623\u0648\u0644\u0626\u0643 \u0647\u0645 \u0627\u0644\u0638\u0627\u0644\u0645\u0648\u0646 \u0627\u0644\u0642\u0627\u0626\u0644\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0628\u0627\u0644\u0628\u0627\u0637\u0644.","3:95":"\u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0635\u064e\u062f\u064e\u0642 \u0627\u0644\u0644\u0647 \u0641\u064a\u0645\u0627 \u0623\u062e\u0628\u0631 \u0628\u0647 \u0648\u0641\u064a\u0645\u0627 \u0634\u0631\u0639\u0647. \u0641\u0625\u0646 \u0643\u0646\u062a\u0645 \u0635\u0627\u062f\u0642\u064a\u0646 \u0641\u064a \u0645\u062d\u0628\u062a\u0643\u0645 \u0648\u0627\u0646\u062a\u0633\u0627\u0628\u0643\u0645 \u0644\u062e\u0644\u064a\u0644 \u0627\u0644\u0644\u0647 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0641\u0627\u062a\u0628\u0639\u0648\u0627 \u0645\u0644\u0651\u064e\u062a\u0647 \u0627\u0644\u062a\u064a \u0634\u0631\u0639\u0647\u0627 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0644\u0633\u0627\u0646 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0641\u0625\u0646\u0647\u0627 \u0627\u0644\u062d\u0642 \u0627\u0644\u0630\u064a \u0644\u0627 \u0634\u0643 \u0641\u064a\u0647. \u0648\u0645\u0627 \u0643\u0627\u0646 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0628\u0627\u0644\u0644\u0647 \u0641\u064a \u062a\u0648\u062d\u064a\u062f\u0647 \u0648\u0639\u0628\u0627\u062f\u062a\u0647 \u0623\u062d\u062f\u064b\u0627.","3:96":"\u0625\u0646 \u0623\u0648\u0644 \u0628\u064a\u062a \u0628\u064f\u0646\u064a \u0644\u0639\u0628\u0627\u062f\u0629 \u0627\u0644\u0644\u0647 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0644\u0647\u0648 \u0628\u064a\u062a \u0627\u0644\u0644\u0647 \u0627\u0644\u062d\u0631\u0627\u0645 \u0627\u0644\u0630\u064a \u0641\u064a \xab\u0645\u0643\u0629\xbb \u060c \u0648\u0647\u0630\u0627 \u0627\u0644\u0628\u064a\u062a \u0645\u0628\u0627\u0631\u0643 \u062a\u0636\u0627\u0639\u0641 \u0641\u064a\u0647 \u0627\u0644\u062d\u0633\u0646\u0627\u062a\u060c \u0648\u062a\u062a\u0646\u0632\u0644 \u0641\u064a\u0647 \u0627\u0644\u0631\u062d\u0645\u0627\u062a\u060c \u0648\u0641\u064a \u0627\u0633\u062a\u0642\u0628\u0627\u0644\u0647 \u0641\u064a \u0627\u0644\u0635\u0644\u0627\u0629\u060c \u0648\u0642\u0635\u062f\u0647 \u0644\u0623\u062f\u0627\u0621 \u0627\u0644\u062d\u062c \u0648\u0627\u0644\u0639\u0645\u0631\u0629\u060c \u0635\u0644\u0627\u062d \u0648\u0647\u062f\u0627\u064a\u0629 \u0644\u0644\u0646\u0627\u0633 \u0623\u062c\u0645\u0639\u064a\u0646.","3:97":"\u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0628\u064a\u062a \u062f\u0644\u0627\u0644\u0627\u062a \u0638\u0627\u0647\u0631\u0627\u062a \u0623\u0646\u0647 \u0645\u0646 \u0628\u0646\u0627\u0621 \u0625\u0628\u0631\u0627\u0647\u064a\u0645\u060c \u0648\u0623\u0646 \u0627\u0644\u0644\u0647 \u0639\u0638\u0651\u064e\u0645\u0647 \u0648\u0634\u0631\u0651\u064e\u0641\u0647\u060c \u0645\u0646\u0647\u0627: \u0645\u0642\u0627\u0645 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0648\u0647\u0648 \u0627\u0644\u062d\u064e\u062c\u064e\u0631 \u0627\u0644\u0630\u064a \u0643\u0627\u0646 \u064a\u0642\u0641 \u0639\u0644\u064a\u0647 \u062d\u064a\u0646 \u0643\u0627\u0646 \u064a\u0631\u0641\u0639 \u0627\u0644\u0642\u0648\u0627\u0639\u062f \u0645\u0646 \u0627\u0644\u0628\u064a\u062a \u0647\u0648 \u0648\u0627\u0628\u0646\u0647 \u0625\u0633\u0645\u0627\u0639\u064a\u0644\u060c \u0648\u0645\u0646 \u062f\u062e\u0644 \u0647\u0630\u0627 \u0627\u0644\u0628\u064a\u062a \u0623\u064e\u0645\u0650\u0646\u064e \u0639\u0644\u0649 \u0646\u0641\u0633\u0647 \u0641\u0644\u0627 \u064a\u0646\u0627\u0644\u0647 \u0623\u062d\u062f \u0628\u0633\u0648\u0621. \u0648\u0642\u062f \u0623\u0648\u062c\u0628 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u062a\u0637\u064a\u0639 \u0645\u0646 \u0627\u0644\u0646\u0627\u0633 \u0641\u064a \u0623\u064a \u0645\u0643\u0627\u0646 \u0642\u064e\u0635\u0652\u062f\u064e \u0647\u0630\u0627 \u0627\u0644\u0628\u064a\u062a \u0644\u0623\u062f\u0627\u0621 \u0645\u0646\u0627\u0633\u0643 \u0627\u0644\u062d\u062c. \u0648\u0645\u0646 \u062c\u062d\u062f \u0641\u0631\u064a\u0636\u0629 \u0627\u0644\u062d\u062c \u0641\u0642\u062f \u0643\u0641\u0631\u060c \u0648\u0627\u0644\u0644\u0647 \u063a\u0646\u064a \u0639\u0646\u0647 \u0648\u0639\u0646 \u062d\u062c\u0651\u0650\u0647 \u0648\u0639\u0645\u0644\u0647\u060c \u0648\u0639\u0646 \u0633\u0627\u0626\u0631 \u062e\u064e\u0644\u0652\u0642\u0647.","3:98":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649: \u0644\u0650\u0645\u064e \u062a\u062c\u062d\u062f\u0648\u0646 \u062d\u062c\u062c \u0627\u0644\u0644\u0647 \u0627\u0644\u062a\u064a \u062f\u0644\u0651\u064e\u062a\u0652 \u0639\u0644\u0649 \u0623\u0646 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647 \u0647\u0648 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0648\u062a\u0646\u0643\u0631\u0648\u0646 \u0645\u0627 \u0641\u064a \u0643\u062a\u0628\u0647\u0645 \u0645\u0646 \u062f\u0644\u0627\u0626\u0644 \u0648\u0628\u0631\u0627\u0647\u064a\u0646 \u0639\u0644\u0649 \u0630\u0644\u0643\u060c \u0648\u0623\u0646\u062a\u0645 \u062a\u0639\u0644\u0645\u0648\u0646\u061f \u0648\u0627\u0644\u0644\u0647 \u0634\u0647\u064a\u062f \u0639\u0644\u0649 \u0635\u0646\u064a\u0639\u0643\u0645. \u0648\u0641\u064a \u0630\u0644\u0643 \u062a\u0647\u062f\u064a\u062f \u0648\u0648\u0639\u064a\u062f \u0644\u0647\u0645.","3:99":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649: \u0644\u0650\u0645\u064e \u062a\u0645\u0646\u0639\u0648\u0646 \u0645\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0645\u0646 \u064a\u0631\u064a\u062f \u0627\u0644\u062f\u062e\u0648\u0644 \u0641\u064a\u0647 \u062a\u0637\u0644\u0628\u0648\u0646 \u0644\u0647 \u0632\u064a\u063a\u064b\u0627 \u0648\u0645\u064a\u0644\u0627 \u0639\u0646 \u0627\u0644\u0642\u0635\u062f \u0648\u0627\u0644\u0627\u0633\u062a\u0642\u0627\u0645\u0629\u060c \u0648\u0623\u0646\u062a\u0645 \u062a\u0639\u0644\u0645\u0648\u0646 \u0623\u0646 \u0645\u0627 \u062c\u0626\u062a\u064f \u0628\u0647 \u0647\u0648 \u0627\u0644\u062d\u0642\u061f \u0648\u0645\u0627 \u0627\u0644\u0644\u0647 \u0628\u063a\u0627\u0641\u0644 \u0639\u0645\u0627 \u062a\u0639\u0645\u0644\u0648\u0646\u060c \u0648\u0633\u0648\u0641 \u064a\u062c\u0627\u0632\u064a\u0643\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643.","3:100":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647\u060c \u0625\u0646 \u062a\u0637\u064a\u0639\u0648\u0627 \u062c\u0645\u0627\u0639\u0629 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0645\u0645\u0646 \u0622\u062a\u0627\u0647\u0645 \u0627\u0644\u0644\u0647 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644\u060c \u064a\u0636\u0644\u0648\u0643\u0645\u060c \u0648\u064a\u0644\u0642\u0648\u0627 \u0625\u0644\u064a\u0643\u0645 \u0627\u0644\u0634\u0651\u064f\u0628\u064e\u0647 \u0641\u064a \u062f\u064a\u0646\u0643\u0645; \u0644\u062a\u0631\u062c\u0639\u0648\u0627 \u062c\u0627\u062d\u062f\u064a\u0646 \u0644\u0644\u062d\u0642 \u0628\u0639\u062f \u0623\u0646 \u0643\u0646\u062a\u0645 \u0645\u0624\u0645\u0646\u064a\u0646 \u0628\u0647\u060c \u0641\u0644\u0627 \u062a\u0623\u0645\u0646\u0648\u0647\u0645 \u0639\u0644\u0649 \u062f\u064a\u0646\u0643\u0645\u060c \u0648\u0644\u0627 \u062a\u0642\u0628\u0644\u0648\u0627 \u0644\u0647\u0645 \u0631\u0623\u064a\u064b\u0627 \u0623\u0648 \u0645\u0634\u0648\u0631\u0629.","3:101":"\u0648\u0643\u064a\u0641 \u062a\u0643\u0641\u0631\u0648\u0646 \u0628\u0627\u0644\u0644\u0647 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646-\u060c \u0648\u0622\u064a\u0627\u062a \u0627\u0644\u0642\u0631\u0622\u0646 \u062a\u062a\u0644\u0649 \u0639\u0644\u064a\u0643\u0645\u060c \u0648\u0641\u064a\u0643\u0645 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u064a\u0628\u0644\u063a\u0647\u0627 \u0644\u0643\u0645\u061f \u0648\u0645\u064e\u0646 \u064a\u062a\u0648\u0643\u0644 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0648\u064a\u0633\u062a\u0645\u0633\u0643 \u0628\u0627\u0644\u0642\u0631\u0622\u0646 \u0648\u0627\u0644\u0633\u0646\u0629 \u0641\u0642\u062f \u0648\u064f\u0641\u0651\u0650\u0642 \u0644\u0637\u0631\u064a\u0642 \u0648\u0627\u0636\u062d\u060c \u0648\u0645\u0646\u0647\u0627\u062c \u0645\u0633\u062a\u0642\u064a\u0645.","3:102":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647\u060c \u062e\u0627\u0641\u0648\u0627 \u0627\u0644\u0644\u0647 \u062d\u0642 \u062e\u0648\u0641\u0647: \u0648\u0630\u0644\u0643 \u0628\u0623\u0646 \u064a\u0637\u0627\u0639 \u0641\u0644\u0627 \u064a\u064f\u0639\u0635\u0649\u060c \u0648\u064a\u064f\u0634\u0643\u064e\u0631 \u0641\u0644\u0627 \u064a\u0643\u0641\u0631\u060c \u0648\u064a\u064f\u0630\u0643\u064e\u0631 \u0641\u0644\u0627 \u064a\u0646\u0633\u0649\u060c \u0648\u062f\u0627\u0648\u0645\u0648\u0627 \u0639\u0644\u0649 \u062a\u0645\u0633\u0643\u0643\u0645 \u0628\u0625\u0633\u0644\u0627\u0645\u0643\u0645 \u0625\u0644\u0649 \u0622\u062e\u0631 \u062d\u064a\u0627\u062a\u0643\u0645; \u0644\u062a\u0644\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0623\u0646\u062a\u0645 \u0639\u0644\u064a\u0647.","3:103":"\u0648\u062a\u0645\u0633\u0651\u064e\u0643\u0648\u0627 \u062c\u0645\u064a\u0639\u064b\u0627 \u0628\u0643\u062a\u0627\u0628 \u0631\u0628\u0643\u0645 \u0648\u0647\u062f\u064a \u0646\u0628\u064a\u0643\u0645\u060c \u0648\u0644\u0627 \u062a\u0641\u0639\u0644\u0648\u0627 \u0645\u0627 \u064a\u0624\u062f\u064a \u0625\u0644\u0649 \u0641\u0631\u0642\u062a\u0643\u0645. \u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u0646\u0639\u0645\u0629 \u062c\u0644\u064a\u0644\u0629 \u0623\u0646\u0639\u0645 \u0627\u0644\u0644\u0647 \u0628\u0647\u0627 \u0639\u0644\u064a\u0643\u0645: \u0625\u0630 \u0643\u0646\u062a\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0642\u0628\u0644 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0623\u0639\u062f\u0627\u0621\u060c \u0641\u062c\u0645\u0639 \u0627\u0644\u0644\u0647 \u0642\u0644\u0648\u0628\u0643\u0645 \u0639\u0644\u0649 \u0645\u062d\u0628\u062a\u0647 \u0648\u0645\u062d\u0628\u0629 \u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0623\u0644\u0642\u0649 \u0641\u064a \u0642\u0644\u0648\u0628\u0643\u0645 \u0645\u062d\u0628\u0629 \u0628\u0639\u0636\u0643\u0645 \u0644\u0628\u0639\u0636\u060c \u0641\u0623\u0635\u0628\u062d\u062a\u0645 \u0628\u0641\u0636\u0644\u0647 \u0625\u062e\u0648\u0627\u0646\u0627 \u0645\u062a\u062d\u0627\u0628\u064a\u0646\u060c \u0648\u0643\u0646\u062a\u0645 \u0639\u0644\u0649 \u062d\u0627\u0641\u0629 \u0646\u0627\u0631 \u062c\u0647\u0646\u0645\u060c \u0641\u0647\u062f\u0627\u0643\u0645 \u0627\u0644\u0644\u0647 \u0628\u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u0646\u062c\u0651\u064e\u0627\u0643\u0645 \u0645\u0646 \u0627\u0644\u0646\u0627\u0631. \u0648\u0643\u0645\u0627 \u0628\u064a\u0651\u064e\u0646 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0645\u0639\u0627\u0644\u0645 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0627\u0644\u0635\u062d\u064a\u062d \u0641\u0643\u0630\u0644\u0643 \u064a\u0628\u064a\u0651\u0650\u0646 \u0644\u0643\u0645 \u0643\u0644 \u0645\u0627 \u0641\u064a\u0647 \u0635\u0644\u0627\u062d\u0643\u0645; \u0644\u062a\u0647\u062a\u062f\u0648\u0627 \u0625\u0644\u0649 \u0633\u0628\u064a\u0644 \u0627\u0644\u0631\u0634\u0627\u062f\u060c \u0648\u062a\u0633\u0644\u0643\u0648\u0647\u0627\u060c \u0641\u0644\u0627 \u062a\u0636\u0644\u0648\u0627 \u0639\u0646\u0647\u0627.","3:104":"\u0648\u0644\u062a\u0643\u0646 \u0645\u0646\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u062c\u0645\u0627\u0639\u0629 \u062a\u062f\u0639\u0648 \u0625\u0644\u0649 \u0627\u0644\u062e\u064a\u0631 \u0648\u062a\u0623\u0645\u0631 \u0628\u0627\u0644\u0645\u0639\u0631\u0648\u0641\u060c \u0648\u0647\u0648 \u0645\u0627 \u0639\u064f\u0631\u0641 \u062d\u0633\u0646\u0647 \u0634\u0631\u0639\u064b\u0627 \u0648\u0639\u0642\u0644\u0627 \u0648\u062a\u0646\u0647\u0649 \u0639\u0646 \u0627\u0644\u0645\u0646\u0643\u0631\u060c \u0648\u0647\u0648 \u0645\u0627 \u0639\u064f\u0631\u0641 \u0642\u0628\u062d\u0647 \u0634\u0631\u0639\u064b\u0627 \u0648\u0639\u0642\u0644\u0627 \u0648\u0623\u0648\u0644\u0626\u0643 \u0647\u0645 \u0627\u0644\u0641\u0627\u0626\u0632\u0648\u0646 \u0628\u062c\u0646\u0627\u062a \u0627\u0644\u0646\u0639\u064a\u0645.","3:105":"\u0648\u0644\u0627 \u062a\u0643\u0648\u0646\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0643\u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0627\u0644\u0630\u064a\u0646 \u0648\u0642\u0639\u062a \u0628\u064a\u0646\u0647\u0645 \u0627\u0644\u0639\u062f\u0627\u0648\u0629 \u0648\u0627\u0644\u0628\u063a\u0636\u0627\u0621 \u0641\u062a\u0641\u0631\u0651\u064e\u0642\u0648\u0627 \u0634\u064a\u0639\u064b\u0627 \u0648\u0623\u062d\u0632\u0627\u0628\u064b\u0627\u060c \u0648\u0627\u062e\u062a\u0644\u0641\u0648\u0627 \u0641\u064a \u0623\u0635\u0648\u0644 \u062f\u064a\u0646\u0647\u0645 \u0645\u0646 \u0628\u0639\u062f \u0623\u0646 \u0627\u062a\u0636\u062d \u0644\u0647\u0645 \u0627\u0644\u062d\u0642\u060c \u0648\u0623\u0648\u0644\u0626\u0643 \u0645\u0633\u062a\u062d\u0642\u0648\u0646 \u0644\u0639\u0630\u0627\u0628\u064d \u0639\u0638\u064a\u0645 \u0645\u0648\u062c\u0639.","3:106":"\u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u062a\u064e\u0628\u0652\u064a\u064e\u0636\u0651\u064f \u0648\u062c\u0648\u0647 \u0623\u0647\u0644 \u0627\u0644\u0633\u0639\u0627\u062f\u0629 \u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0627\u0645\u062a\u062b\u0644\u0648\u0627 \u0623\u0645\u0631\u0647\u060c \u0648\u062a\u064e\u0633\u0652\u0648\u064e\u062f\u0651\u064f \u0648\u062c\u0648\u0647 \u0623\u0647\u0644 \u0627\u0644\u0634\u0642\u0627\u0648\u0629 \u0645\u0645\u0646 \u0643\u0630\u0628\u0648\u0627 \u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0639\u0635\u0648\u0627 \u0623\u0645\u0631\u0647. \u0641\u0623\u0645\u0627 \u0627\u0644\u0630\u064a\u0646 \u0627\u0633\u0648\u062f\u0651\u064e\u062a \u0648\u062c\u0648\u0647\u0647\u0645\u060c \u0641\u064a\u0642\u0627\u0644 \u0644\u0647\u0645 \u062a\u0648\u0628\u064a\u062e\u064b\u0627: \u0623\u0643\u0641\u0631\u062a\u0645 \u0628\u0639\u062f \u0625\u064a\u0645\u0627\u0646\u0643\u0645\u060c \u0641\u0627\u062e\u062a\u0631\u062a\u0645 \u0627\u0644\u0643\u0641\u0631 \u0639\u0644\u0649 \u0627\u0644\u0625\u064a\u0645\u0627\u0646\u061f \u0641\u0630\u0648\u0642\u0648\u0627 \u0627\u0644\u0639\u0630\u0627\u0628 \u0628\u0633\u0628\u0628 \u0643\u0641\u0631\u0643\u0645.","3:107":"\u0648\u0623\u0645\u0627 \u0627\u0644\u0630\u064a\u0646 \u0627\u0628\u064a\u0636\u0651\u064e\u062a\u0652 \u0648\u062c\u0648\u0647\u0645 \u0628\u0646\u0636\u0631\u0629 \u0627\u0644\u0646\u0639\u064a\u0645\u060c \u0648\u0645\u0627 \u0628\u064f\u0634\u0651\u0650\u0631\u0648\u0627 \u0628\u0647 \u0645\u0646 \u0627\u0644\u062e\u064a\u0631\u060c \u0641\u0647\u0645 \u0641\u064a \u062c\u0646\u0629 \u0627\u0644\u0644\u0647 \u0648\u0646\u0639\u064a\u0645\u0647\u0627\u060c \u0648\u0647\u0645 \u0628\u0627\u0642\u0648\u0646 \u0641\u064a\u0647\u0627\u060c \u0644\u0627 \u064a\u062e\u0631\u062c\u0648\u0646 \u0645\u0646\u0647\u0627 \u0623\u0628\u062f\u064b\u0627.","3:108":"\u0647\u0630\u0647 \u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0648\u0628\u0631\u0627\u0647\u064a\u0646\u0647 \u0627\u0644\u0633\u0627\u0637\u0639\u0629\u060c \u0646\u062a\u0644\u0648\u0647\u0627 \u0648\u0646\u0642\u0635\u0651\u064f\u0647\u0627 \u0639\u0644\u064a\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0628\u0627\u0644\u0635\u062f\u0642 \u0648\u0627\u0644\u064a\u0642\u064a\u0646. \u0648\u0645\u0627 \u0627\u0644\u0644\u0647 \u0628\u0638\u0627\u0644\u0645 \u0623\u062d\u062f\u064b\u0627 \u0645\u0646 \u062e\u0644\u0642\u0647\u060c \u0648\u0644\u0627 \u0628\u0645\u0646\u0642\u0635 \u0634\u064a\u0626\u064b\u0627 \u0645\u0646 \u0623\u0639\u0645\u0627\u0644\u0647\u0645; \u0644\u0623\u0646\u0647 \u0627\u0644\u062d\u0627\u0643\u0645 \u0627\u0644\u0639\u062f\u0644 \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u062c\u0648\u0631.","3:109":"\u0648\u0644\u0644\u0647 \u0645\u0627 \u0641\u064a \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0645\u0627 \u0641\u064a \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0644\u0643\u064c \u0644\u0647 \u0648\u062d\u062f\u0647 \u062e\u0644\u0642\u064b\u0627 \u0648\u062a\u062f\u0628\u064a\u0631\u064b\u0627\u060c \u0648\u0645\u0635\u064a\u0631 \u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u0644\u0627\u0626\u0642 \u0625\u0644\u064a\u0647 \u0648\u062d\u062f\u0647\u060c \u0641\u064a\u062c\u0627\u0632\u064a \u0643\u0644\u0627 \u0639\u0644\u0649 \u0642\u062f\u0631 \u0627\u0633\u062a\u062d\u0642\u0627\u0642\u0647.","3:110":"\u0623\u0646\u062a\u0645 - \u064a\u0627 \u0623\u0645\u0629 \u0645\u062d\u0645\u062f - \u062e\u064a\u0631 \u0627\u0644\u0623\u0645\u0645 \u0648\u0623\u0646\u0641\u0639 \u0627\u0644\u0646\u0627\u0633 \u0644\u0644\u0646\u0627\u0633\u060c \u062a\u0623\u0645\u0631\u0648\u0646 \u0628\u0627\u0644\u0645\u0639\u0631\u0648\u0641\u060c \u0648\u0647\u0648 \u0645\u0627 \u0639\u064f\u0631\u0641 \u062d\u0633\u0646\u0647 \u0634\u0631\u0639\u064b\u0627 \u0648\u0639\u0642\u0644\u0627 \u0648\u062a\u0646\u0647\u0648\u0646 \u0639\u0646 \u0627\u0644\u0645\u0646\u0643\u0631\u060c \u0648\u0647\u0648 \u0645\u0627 \u0639\u064f\u0631\u0641 \u0642\u0628\u062d\u0647 \u0634\u0631\u0639\u064b\u0627 \u0648\u0639\u0642\u0644\u0627 \u0648\u062a\u0635\u062f\u0642\u0648\u0646 \u0628\u0627\u0644\u0644\u0647 \u062a\u0635\u062f\u064a\u0642\u064b\u0627 \u062c\u0627\u0632\u0645\u064b\u0627 \u064a\u0624\u064a\u062f\u0647 \u0627\u0644\u0639\u0645\u0644. \u0648\u0644\u0648 \u0622\u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0628\u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u0645\u0627 \u062c\u0627\u0621\u0647\u0645 \u0628\u0647 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0643\u0645\u0627 \u0622\u0645\u0646\u062a\u0645\u060c \u0644\u0643\u0627\u0646 \u062e\u064a\u0631\u0627 \u0644\u0647\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0645\u0646\u0647\u0645 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0627\u0644\u0645\u0635\u062f\u0642\u0648\u0646 \u0628\u0631\u0633\u0627\u0644\u0629 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0627\u0644\u0639\u0627\u0645\u0644\u0648\u0646 \u0628\u0647\u0627\u060c \u0648\u0647\u0645 \u0642\u0644\u064a\u0644\u060c \u0648\u0623\u0643\u062b\u0631\u0647\u0645 \u0627\u0644\u062e\u0627\u0631\u062c\u0648\u0646 \u0639\u0646 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647 \u0648\u0637\u0627\u0639\u062a\u0647.","3:111":"\u0644\u0646 \u064a\u0636\u0631\u0643\u0645 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0641\u0627\u0633\u0642\u0648\u0646 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0625\u0644\u0627 \u0645\u0627 \u064a\u0624\u0630\u064a \u0623\u0633\u0645\u0627\u0639\u0643\u0645 \u0645\u0646 \u0623\u0644\u0641\u0627\u0638 \u0627\u0644\u0634\u0631\u0643 \u0648\u0627\u0644\u0643\u0641\u0631 \u0648\u063a\u064a\u0631 \u0630\u0644\u0643\u060c \u0648\u0625\u0646 \u064a\u0642\u0627\u062a\u0644\u0648\u0643\u0645 \u064a\u064f\u0647\u0652\u0632\u064e\u0645\u0648\u0627\u060c \u0648\u064a\u0647\u0631\u0628\u0648\u0627 \u0645\u0648\u0644\u0651\u0650\u064a\u0646 \u0627\u0644\u0623\u062f\u0628\u0627\u0631\u060c \u062b\u0645 \u0644\u0627 \u064a\u0646\u0635\u0631\u0648\u0646 \u0639\u0644\u064a\u0643\u0645 \u0628\u0623\u064a \u062d\u0627\u0644.","3:112":"\u062c\u0639\u0644 \u0627\u0644\u0644\u0647 \u0627\u0644\u0647\u0648\u0627\u0646 \u0648\u0627\u0644\u0635\u063a\u0627\u0631 \u0623\u0645\u0631\u064b\u0627 \u0644\u0627\u0632\u0645\u064b\u0627 \u0644\u0627 \u064a\u0641\u0627\u0631\u0642 \u0627\u0644\u064a\u0647\u0648\u062f\u060c \u0641\u0647\u0645 \u0623\u0630\u0644\u0627\u0621 \u0645\u062d\u062a\u0642\u0631\u0648\u0646 \u0623\u064a\u0646\u0645\u0627 \u0648\u064f\u062c\u0650\u062f\u0648\u0627\u060c \u0625\u0644\u0627 \u0628\u0639\u0647\u062f \u0645\u0646 \u0627\u0644\u0644\u0647 \u0648\u0639\u0647\u062f \u0645\u0646 \u0627\u0644\u0646\u0627\u0633 \u064a\u0623\u0645\u0646\u0648\u0646 \u0628\u0647 \u0639\u0644\u0649 \u0623\u0646\u0641\u0633\u0647\u0645 \u0648\u0623\u0645\u0648\u0627\u0644\u0647\u0645\u060c \u0648\u0630\u0644\u0643 \u0647\u0648 \u0639\u0642\u062f \u0627\u0644\u0630\u0645\u0629 \u0644\u0647\u0645 \u0648\u0625\u0644\u0632\u0627\u0645\u0647\u0645 \u0623\u062d\u0643\u0627\u0645 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0648\u0631\u062c\u0639\u0648\u0627 \u0628\u063a\u0636\u0628 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0645\u0633\u062a\u062d\u0642\u064a\u0646 \u0644\u0647\u060c \u0648\u0636\u064f\u0631\u0628\u062a \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0630\u0644\u0651\u064e\u0629 \u0648\u0627\u0644\u0645\u0633\u0643\u0646\u0629\u060c \u0641\u0644\u0627 \u062a\u0631\u0649 \u0627\u0644\u064a\u0647\u0648\u062f\u064a\u0651\u064e \u0625\u0644\u0627 \u0648\u0639\u0644\u064a\u0647 \u0627\u0644\u062e\u0648\u0641 \u0648\u0627\u0644\u0631\u0639\u0628 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0625\u064a\u0645\u0627\u0646; \u0630\u0644\u0643 \u0627\u0644\u0630\u064a \u062c\u0639\u0644\u0647 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645 \u0628\u0633\u0628\u0628 \u0643\u0641\u0631\u0647\u0645 \u0628\u0627\u0644\u0644\u0647\u060c \u0648\u062a\u062c\u0627\u0648\u0632\u0647\u0645 \u062d\u062f\u0648\u062f\u0647\u060c \u0648\u0642\u064e\u062a\u0652\u0644\u0647\u0645 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0638\u0644\u0645\u064b\u0627 \u0648\u0627\u0639\u062a\u062f\u0627\u0621\u060c \u0648\u0645\u0627 \u062c\u0631\u0651\u064e\u0623\u0647\u0645 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0625\u0644\u0627 \u0627\u0631\u062a\u0643\u0627\u0628\u0647\u0645 \u0644\u0644\u0645\u0639\u0627\u0635\u064a\u060c \u0648\u062a\u062c\u0627\u0648\u0632\u0647\u0645 \u062d\u062f\u0648\u062f \u0627\u0644\u0644\u0647.","3:113":"\u0644\u064a\u0633 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0645\u062a\u0633\u0627\u0648\u064a\u0646: \u0641\u0645\u0646\u0647\u0645 \u062c\u0645\u0627\u0639\u0629 \u0645\u0633\u062a\u0642\u064a\u0645\u0629 \u0639\u0644\u0649 \u0623\u0645\u0631 \u0627\u0644\u0644\u0647 \u0645\u0624\u0645\u0646\u0629 \u0628\u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u064a\u0642\u0648\u0645\u0648\u0646 \u0627\u0644\u0644\u064a\u0644 \u0645\u0631\u062a\u0644\u064a\u0646 \u0622\u064a\u0627\u062a \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064a\u0645\u060c \u0645\u0642\u0628\u0644\u064a\u0646 \u0639\u0644\u0649 \u0645\u0646\u0627\u062c\u0627\u0629 \u0627\u0644\u0644\u0647 \u0641\u064a \u0635\u0644\u0648\u0627\u062a\u0647\u0645.","3:114":"\u064a\u0624\u0645\u0646\u0648\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0622\u062e\u0631\u060c \u0648\u064a\u0623\u0645\u0631\u0648\u0646 \u0628\u0627\u0644\u062e\u064a\u0631 \u0643\u0644\u0647\u060c \u0648\u064a\u0646\u0647\u0648\u0646 \u0639\u0646 \u0627\u0644\u0634\u0631 \u0643\u0644\u0651\u0650\u0647\u060c \u0648\u064a\u0628\u0627\u062f\u0631\u0648\u0646 \u0625\u0644\u0649 \u0641\u0639\u0644 \u0627\u0644\u062e\u064a\u0631\u0627\u062a\u060c \u0648\u0623\u0648\u0644\u0626\u0643 \u0645\u0650\u0646 \u0639\u0628\u0627\u062f \u0627\u0644\u0644\u0647 \u0627\u0644\u0635\u0627\u0644\u062d\u064a\u0646.","3:115":"\u0648\u0623\u064a\u0651\u064f \u0639\u0645\u0644 \u0642\u0644\u0651\u064e \u0623\u0648 \u0643\u064e\u062b\u064f\u0631 \u0645\u0646 \u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u062e\u064a\u0631 \u062a\u0639\u0645\u0644\u0647 \u0647\u0630\u0647 \u0627\u0644\u0637\u0627\u0626\u0641\u0629 \u0627\u0644\u0645\u0624\u0645\u0646\u0629 \u0641\u0644\u0646 \u064a\u0636\u064a\u0639 \u0639\u0646\u062f \u0627\u0644\u0644\u0647\u060c \u0628\u0644 \u064a\u064f\u0634\u0643\u0631 \u0644\u0647\u0645\u060c \u0648\u064a\u062c\u0627\u0632\u0648\u0646 \u0639\u0644\u064a\u0647. \u0648\u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0645 \u0628\u0627\u0644\u0645\u062a\u0642\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0641\u0639\u0644\u0648\u0627 \u0627\u0644\u062e\u064a\u0631\u0627\u062a \u0648\u0627\u0628\u062a\u0639\u062f\u0648\u0627 \u0639\u0646 \u0627\u0644\u0645\u062d\u0631\u0645\u0627\u062a; \u0627\u0628\u062a\u063a\u0627\u0621 \u0631\u0636\u0648\u0627\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u0637\u0644\u0628\u064b\u0627 \u0644\u062b\u0648\u0627\u0628\u0647.","3:116":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0628\u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647\u060c \u0648\u0643\u0630\u0628\u0648\u0627 \u0631\u0633\u0644\u0647\u060c \u0644\u0646 \u062a\u062f\u0641\u0639 \u0639\u0646\u0647\u0645 \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0648\u0644\u0627 \u0623\u0648\u0644\u0627\u062f\u0647\u0645 \u0634\u064a\u0626\u064b\u0627 \u0645\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0644\u0627 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u0623\u0648\u0644\u0626\u0643 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0646\u0627\u0631 \u0627\u0644\u0645\u0644\u0627\u0632\u0645\u0648\u0646 \u0644\u0647\u0627\u060c \u0644\u0627 \u064a\u062e\u0631\u062c\u0648\u0646 \u0645\u0646\u0647\u0627.","3:117":"\u0645\u064e\u062b\u064e\u0644\u064f \u0645\u0627 \u064a\u0646\u0641\u0642 \u0627\u0644\u0643\u0627\u0641\u0631\u0648\u0646 \u0641\u064a \u0648\u062c\u0648\u0647 \u0627\u0644\u062e\u064a\u0631 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0645\u0627 \u064a\u0624\u0645\u0644\u0648\u0646\u0647 \u0645\u0646 \u062b\u0648\u0627\u0628\u060c \u0643\u0645\u062b\u0644 \u0631\u064a\u062d \u0641\u064a\u0647\u0627 \u0628\u0631\u062f \u0634\u062f\u064a\u062f \u0647\u064e\u0628\u0651\u064e\u062a\u0652 \u0639\u0644\u0649 \u0632\u0631\u0639 \u0642\u0648\u0645 \u0643\u0627\u0646\u0648\u0627 \u064a\u0631\u062c\u0648\u0646 \u062e\u064a\u0631\u0647\u060c \u0648\u0628\u0633\u0628\u0628 \u0630\u0646\u0648\u0628\u0647\u0645 \u0644\u0645 \u062a\u064f\u0628\u0652\u0642\u0650 \u0627\u0644\u0631\u064a\u062d \u0645\u0646\u0647 \u0634\u064a\u0626\u064b\u0627. \u0648\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0643\u0627\u0641\u0631\u0648\u0646 \u0644\u0627 \u064a\u062c\u062f\u0648\u0646 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u062b\u0648\u0627\u0628\u064b\u0627\u060c \u0648\u0645\u0627 \u0638\u0644\u0645\u0647\u0645 \u0627\u0644\u0644\u0647 \u0628\u0630\u0644\u0643\u060c \u0648\u0644\u0643\u0646\u0647\u0645 \u0638\u0644\u0645\u0648\u0627 \u0623\u0646\u0641\u0633\u0647\u0645 \u0628\u0643\u0641\u0631\u0647\u0645 \u0648\u0639\u0635\u064a\u0627\u0646\u0647\u0645.","3:118":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647\u060c \u0644\u0627 \u062a\u062a\u062e\u0630\u0648\u0627 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0623\u0648\u0644\u064a\u0627\u0621 \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u062a\u064f\u0637\u0652\u0644\u0639\u0648\u0646\u0647\u0645 \u0639\u0644\u0649 \u0623\u0633\u0631\u0627\u0631\u0643\u0645\u060c \u0641\u0647\u0624\u0644\u0627\u0621 \u0644\u0627 \u064a\u064e\u0641\u0652\u062a\u064f\u0631\u0648\u0646 \u0639\u0646 \u0625\u0641\u0633\u0627\u062f \u062d\u0627\u0644\u0643\u0645\u060c \u0648\u0647\u0645 \u064a\u0641\u0631\u062d\u0648\u0646 \u0628\u0645\u0627 \u064a\u0635\u064a\u0628\u0643\u0645 \u0645\u0646 \u0636\u0631\u0631 \u0648\u0645\u0643\u0631\u0648\u0647\u060c \u0648\u0642\u062f \u0638\u0647\u0631\u062a \u0634\u062f\u0629 \u0627\u0644\u0628\u063a\u0636 \u0641\u064a \u0643\u0644\u0627\u0645\u0647\u0645\u060c \u0648\u0645\u0627 \u062a\u062e\u0641\u064a \u0635\u062f\u0648\u0631\u0647\u0645 \u0645\u0646 \u0627\u0644\u0639\u062f\u0627\u0648\u0629 \u0644\u0643\u0645 \u0623\u0643\u0628\u0631 \u0648\u0623\u0639\u0638\u0645. \u0642\u062f \u0628\u064a\u0651\u064e\u0646\u0651\u064e\u0627 \u0644\u0643\u0645 \u0627\u0644\u0628\u0631\u0627\u0647\u064a\u0646 \u0648\u0627\u0644\u062d\u062c\u062c\u060c \u0644\u062a\u062a\u0639\u0638\u0648\u0627 \u0648\u062a\u062d\u0630\u0631\u0648\u0627\u060c \u0625\u0646 \u0643\u0646\u062a\u0645 \u062a\u0639\u0642\u0644\u0648\u0646 \u0639\u0646 \u0627\u0644\u0644\u0647 \u0645\u0648\u0627\u0639\u0638\u0647 \u0648\u0623\u0645\u0631\u0647 \u0648\u0646\u0647\u064a\u0647.","3:119":"\u0647\u0627 \u0647\u0648 \u0630\u0627 \u0627\u0644\u062f\u0644\u064a\u0644 \u0639\u0644\u0649 \u062e\u0637\u0626\u0643\u0645 \u0641\u064a \u0645\u062d\u0628\u062a\u0647\u0645\u060c \u0641\u0623\u0646\u062a\u0645 \u062a\u062d\u0628\u0648\u0646\u0647\u0645 \u0648\u062a\u062d\u0633\u0646\u0648\u0646 \u0625\u0644\u064a\u0647\u0645\u060c \u0648\u0647\u0645 \u0644\u0627 \u064a\u062d\u0628\u0648\u0646\u0643\u0645 \u0648\u064a\u062d\u0645\u0644\u0648\u0646 \u0644\u0643\u0645 \u0627\u0644\u0639\u062f\u0627\u0648\u0629 \u0648\u0627\u0644\u0628\u063a\u0636\u0627\u0621\u060c \u0648\u0623\u0646\u062a\u0645 \u062a\u0624\u0645\u0646\u0648\u0646 \u0628\u0627\u0644\u0643\u062a\u0628 \u0627\u0644\u0645\u0646\u0632\u0644\u0629 \u0643\u0644\u0647\u0627 \u0648\u0645\u0646\u0647\u0627 \u0643\u062a\u0627\u0628\u0647\u0645\u060c \u0648\u0647\u0645 \u0644\u0627 \u064a\u0624\u0645\u0646\u0648\u0646 \u0628\u0643\u062a\u0627\u0628\u0643\u0645\u060c \u0641\u0643\u064a\u0641 \u062a\u062d\u0628\u0648\u0646\u0647\u0645\u061f \u0648\u0625\u0630\u0627 \u0644\u0642\u0648\u0643\u0645 \u0642\u0627\u0644\u0648\u0627 -\u0646\u0641\u0627\u0642\u064b\u0627-: \u0622\u0645\u0646\u0651\u064e\u0627 \u0648\u0635\u062f\u0651\u064e\u0642\u0652\u0646\u0627\u060c \u0648\u0625\u0630\u0627 \u062e\u0644\u0627 \u0628\u0639\u0636\u0647\u0645 \u0625\u0644\u0649 \u0628\u0639\u0636 \u0628\u062f\u0627 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u063a\u0645 \u0648\u0627\u0644\u062d\u0632\u0646\u060c \u0641\u0639\u064e\u0636\u0651\u064f\u0648\u0627 \u0623\u0637\u0631\u0627\u0641 \u0623\u0635\u0627\u0628\u0639\u0647\u0645 \u0645\u0646 \u0634\u062f\u0629 \u0627\u0644\u063a\u0636\u0628\u060c \u0644\u0645\u0627 \u064a\u0631\u0648\u0646 \u0645\u0646 \u0623\u0644\u0641\u0629 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0648\u0627\u062c\u062a\u0645\u0627\u0639 \u0643\u0644\u0645\u062a\u0647\u0645\u060c \u0648\u0625\u0639\u0632\u0627\u0632 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0648\u0625\u0630\u0644\u0627\u0644\u0647\u0645 \u0628\u0647. \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0645\u0648\u062a\u0648\u0627 \u0628\u0634\u062f\u0629 \u063a\u0636\u0628\u0643\u0645. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0645\u0637\u0651\u064e\u0644\u0650\u0639 \u0639\u0644\u0649 \u0645\u0627 \u062a\u062e\u0641\u064a \u0627\u0644\u0635\u062f\u0648\u0631\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a \u0643\u0644\u0627 \u0639\u0644\u0649 \u0645\u0627 \u0642\u062f\u0651\u064e\u0645 \u0645\u0650\u0646 \u062e\u064a\u0631 \u0623\u0648 \u0634\u0631.","3:120":"\u0648\u0645\u0646 \u0639\u062f\u0627\u0648\u0629 \u0647\u0624\u0644\u0627\u0621 \u0623\u0646\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0625\u0646 \u0646\u0632\u0644 \u0628\u0643\u0645 \u0623\u0645\u0631\u064c \u062d\u0633\u0646 \u0645\u0650\u0646 \u0646\u0635\u0631 \u0648\u063a\u0646\u064a\u0645\u0629 \u0638\u0647\u0631\u062a \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0643\u0622\u0628\u0629 \u0648\u0627\u0644\u062d\u0632\u0646\u060c \u0648\u0625\u0646 \u0648\u0642\u0639 \u0628\u0643\u0645 \u0645\u0643\u0631\u0648\u0647 \u0645\u0646 \u0647\u0632\u064a\u0645\u0629 \u0623\u0648 \u0646\u0642\u0635 \u0641\u064a \u0627\u0644\u0623\u0645\u0648\u0627\u0644 \u0648\u0627\u0644\u0623\u0646\u0641\u0633 \u0648\u0627\u0644\u062b\u0645\u0631\u0627\u062a \u0641\u0631\u062d\u0648\u0627 \u0628\u0630\u0644\u0643\u060c \u0648\u0625\u0646 \u062a\u0635\u0628\u0631\u0648\u0627 \u0639\u0644\u0649 \u0645\u0627 \u0623\u0635\u0627\u0628\u0643\u0645\u060c \u0648\u062a\u062a\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0641\u064a\u0645\u0627 \u0623\u0645\u0631\u0643\u0645 \u0628\u0647 \u0648\u0646\u0647\u0627\u0643\u0645 \u0639\u0646\u0647\u060c \u0644\u0627 \u064a\u0636\u0631\u0643\u0645 \u0623\u0630\u0649 \u0645\u0643\u0631\u0647\u0645. \u0648\u0627\u0644\u0644\u0647 \u0628\u062c\u0645\u064a\u0639 \u0645\u0627 \u064a\u0639\u0645\u0644 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0643\u0641\u0627\u0631 \u0645\u0646 \u0627\u0644\u0641\u0633\u0627\u062f \u0645\u062d\u064a\u0637\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a\u0647\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643.","3:121":"\u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u062d\u064a\u0646 \u062e\u064e\u0631\u064e\u062c\u0652\u062a\u064e \u0645\u0646 \u0628\u064a\u062a\u0643 \u0644\u0627\u0628\u0633\u064b\u0627 \u0639\u064f\u062f\u0651\u064e\u0629 \u0627\u0644\u062d\u0631\u0628\u060c \u062a\u0646\u0638\u0645 \u0635\u0641\u0648\u0641 \u0623\u0635\u062d\u0627\u0628\u0643\u060c \u0648\u062a\u064f\u0646\u0652\u0632\u0650\u0644 \u0643\u0644 \u0648\u0627\u062d\u062f \u0641\u064a \u0645\u0646\u0632\u0644\u0647 \u0644\u0644\u0642\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0641\u064a \u063a\u0632\u0648\u0629 \xab\u0623\u064f\u062d\u064f\u062f\xbb . \u0648\u0627\u0644\u0644\u0647 \u0633\u0645\u064a\u0639 \u0644\u0623\u0642\u0648\u0627\u0644\u0643\u0645\u060c \u0639\u0644\u064a\u0645 \u0628\u0623\u0641\u0639\u0627\u0644\u0643\u0645.","3:122":"\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0645\u0627 \u0643\u0627\u0646 \u0645\u0646 \u0623\u0645\u0631 \u0628\u0646\u064a \u0633\u064e\u0644\u0650\u0645\u0629 \u0648\u0628\u0646\u064a \u062d\u0627\u0631\u062b\u0629 \u062d\u064a\u0646 \u062d\u062f\u062b\u062a\u0647\u0645 \u0623\u0646\u0641\u0633\u0647\u0645 \u0628\u0627\u0644\u0631\u062c\u0648\u0639 \u0645\u0639 \u0632\u0639\u064a\u0645\u0647\u0645 \u0627\u0644\u0645\u0646\u0627\u0641\u0642 \u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0628\u0646 \u0623\u064f\u0628\u064a\u0651\u064d; \u062e\u0648\u0641\u064b\u0627 \u0645\u0646 \u0644\u0642\u0627\u0621 \u0627\u0644\u0639\u062f\u0648\u060c \u0648\u0644\u0643\u0646 \u0627\u0644\u0644\u0647 \u0639\u0635\u0645\u0647\u0645 \u0648\u062d\u0641\u0638\u0647\u0645\u060c \u0641\u0633\u0627\u0631\u0648\u0627 \u0645\u0639\u0643 \u0645\u062a\u0648\u0643\u0644\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647. \u0648\u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0641\u0644\u064a\u062a\u0648\u0643\u0644 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646.","3:123":"\u0648\u0644\u0642\u062f \u0646\u0635\u0631\u0643\u0645 \u0627\u0644\u0644\u0647 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0628\u0640 \xab\u0628\u062f\u0631\xbb \u0639\u0644\u0649 \u0623\u0639\u062f\u0627\u0626\u0643\u0645 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0645\u0639 \u0642\u0644\u0629 \u0639\u064e\u062f\u064e\u062f\u0643\u0645 \u0648\u0639\u064f\u062f\u064e\u062f\u0643\u0645\u060c \u0641\u062e\u0627\u0641\u0648\u0627 \u0627\u0644\u0644\u0647 \u0628\u0641\u0639\u0644 \u0623\u0648\u0627\u0645\u0631\u0647 \u0648\u0627\u062c\u062a\u0646\u0627\u0628 \u0646\u0648\u0627\u0647\u064a\u0647; \u0644\u0639\u0644\u0643\u0645 \u062a\u0634\u0643\u0631\u0648\u0646 \u0644\u0647 \u0646\u0639\u0645\u0647.","3:124":"\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0645\u0627 \u0643\u0627\u0646 \u0645\u0646 \u0623\u0645\u0631 \u0623\u0635\u062d\u0627\u0628\u0643 \u0641\u064a \xab\u0628\u062f\u0631\xbb \u062d\u064a\u0646 \u0634\u0642\u0651\u064e \u0639\u0644\u064a\u0647\u0645 \u0623\u0646 \u064a\u0623\u062a\u064a \u0645\u064e\u062f\u064e\u062f \u0644\u0644\u0645\u0634\u0631\u0643\u064a\u0646\u060c \u0641\u0623\u0648\u062d\u064a\u0646\u0627 \u0625\u0644\u064a\u0643 \u0623\u0646 \u062a\u0642\u0648\u0644 \u0644\u0647\u0645: \u0623\u0644\u0646 \u062a\u0643\u0641\u064a\u0643\u0645 \u0645\u0639\u0648\u0646\u0629 \u0631\u0628\u0643\u0645 \u0628\u0623\u0646 \u064a\u0645\u062f\u0643\u0645 \u0628\u062b\u0644\u0627\u062b\u0629 \u0622\u0644\u0627\u0641 \u0645\u0646 \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u0645\u064f\u0646\u0652\u0632\u064e\u0644\u064a\u0646 \u0645\u0646 \u0627\u0644\u0633\u0645\u0627\u0621 \u0625\u0644\u0649 \u0623\u0631\u0636 \u0627\u0644\u0645\u0639\u0631\u0643\u0629\u060c \u064a\u062b\u0628\u062a\u0648\u0646\u0643\u0645\u060c \u0648\u064a\u0642\u0627\u062a\u0644\u0648\u0646 \u0645\u0639\u0643\u0645\u061f","3:125":"\u0628\u0644\u0649 \u064a\u0643\u0641\u064a\u0643\u0645 \u0647\u0630\u0627 \u0627\u0644\u0645\u064e\u062f\u064e\u062f. \u0648\u0628\u0634\u0627\u0631\u0629 \u0623\u062e\u0631\u0649 \u0644\u0643\u0645: \u0625\u0646 \u062a\u0635\u0628\u0631\u0648\u0627 \u0639\u0644\u0649 \u0644\u0642\u0627\u0621 \u0627\u0644\u0639\u062f\u0648 \u0648\u062a\u062a\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0628\u0641\u0650\u0639\u0652\u0644 \u0645\u0627 \u0623\u0645\u0631\u0643\u0645 \u0628\u0647 \u0648\u0627\u062c\u062a\u0646\u0627\u0628 \u0645\u0627 \u0646\u0647\u0627\u0643\u0645 \u0639\u0646\u0647\u060c \u0648\u064a\u0623\u062a \u0643\u0641\u0627\u0631 \xab\u0645\u0643\u0629\xbb \u0639\u0644\u0649 \u0627\u0644\u0641\u0648\u0631 \u0645\u0633\u0631\u0639\u064a\u0646 \u0644\u0642\u062a\u0627\u0644\u0643\u0645\u060c \u064a\u0638\u0646\u0648\u0646 \u0623\u0646\u0647\u0645 \u064a\u0633\u062a\u0623\u0635\u0644\u0648\u0646\u0643\u0645\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u0645\u062f\u0643\u0645 \u0628\u062e\u0645\u0633\u0629 \u0622\u0644\u0627\u0641 \u0645\u0646 \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u0645\u0633\u0648\u0651\u0650\u0645\u064a\u0646 \u0623\u064a: \u0642\u062f \u0623\u0639\u0644\u0645\u0648\u0627 \u0623\u0646\u0641\u0633\u0647\u0645 \u0648\u062e\u064a\u0648\u0644\u0647\u0645 \u0628\u0639\u0644\u0627\u0645\u0627\u062a \u0648\u0627\u0636\u062d\u0627\u062a.","3:126":"\u0648\u0645\u0627 \u062c\u0639\u0644 \u0627\u0644\u0644\u0647 \u0647\u0630\u0627 \u0627\u0644\u0625\u0645\u062f\u0627\u062f \u0628\u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u0625\u0644\u0627 \u0628\u0634\u0631\u0649 \u0644\u0643\u0645 \u064a\u0628\u0634\u0631\u0643\u0645 \u0628\u0647\u0627 \u0648\u0644\u062a\u0637\u0645\u0626\u0646 \u0642\u0644\u0648\u0628\u0643\u0645\u060c \u0648\u062a\u0637\u064a\u0628 \u0628\u0648\u0639\u062f \u0627\u0644\u0644\u0647 \u0644\u0643\u0645. \u0648\u0645\u0627 \u0627\u0644\u0646\u0635\u0631 \u0625\u0644\u0627 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0627\u0644\u0639\u0632\u064a\u0632 \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u063a\u0627\u0644\u064e\u0628\u060c \u0627\u0644\u062d\u0643\u064a\u0645 \u0641\u064a \u062a\u062f\u0628\u064a\u0631\u0647 \u0648\u0641\u0639\u0644\u0647.","3:127":"\u0648\u0643\u0627\u0646 \u0646\u0635\u0631 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0628\u0640 \xab\u0628\u062f\u0652\u0631\xbb \u0644\u064a\u0647\u0644\u0643 \u0641\u0631\u064a\u0642\u064b\u0627 \u0645\u0646 \u0627\u0644\u0643\u0641\u0627\u0631 \u0628\u0627\u0644\u0642\u062a\u0644\u060c \u0648\u0645\u0646 \u0646\u062c\u0627 \u0645\u0646\u0647\u0645 \u0645\u0646 \u0627\u0644\u0642\u062a\u0644 \u0631\u062c\u0639 \u062d\u0632\u064a\u0646\u064b\u0627 \u0642\u062f \u0636\u0627\u0642\u062a \u0639\u0644\u064a\u0647 \u0646\u0641\u0633\u0647\u060c \u064a\u064e\u0638\u0652\u0647\u0631 \u0639\u0644\u064a\u0647 \u0627\u0644\u062e\u0632\u064a \u0648\u0627\u0644\u0639\u0627\u0631.","3:128":"\u0644\u064a\u0633 \u0644\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0645\u0646 \u0623\u0645\u0631 \u0627\u0644\u0639\u0628\u0627\u062f \u0634\u064a\u0621\u060c \u0628\u0644 \u0627\u0644\u0623\u0645\u0631 \u0643\u0644\u0647 \u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u062d\u062f\u0647 \u0644\u0627 \u0634\u0631\u064a\u0643 \u0644\u0647\u060c \u0648\u0644\u0639\u0644 \u0628\u0639\u0636 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u0642\u0627\u062a\u0644\u0648\u0643 \u062a\u0646\u0634\u0631\u062d \u0635\u062f\u0648\u0631\u0647\u0645 \u0644\u0644\u0625\u0633\u0644\u0627\u0645 \u0641\u064a\u0633\u0644\u0645\u0648\u0627\u060c \u0641\u064a\u062a\u0648\u0628 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645. \u0648\u0645\u0646 \u0628\u0642\u064a \u0639\u0644\u0649 \u0643\u0641\u0631\u0647 \u064a\u0639\u0630\u0628\u0647 \u0627\u0644\u0644\u0647 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629 \u0628\u0633\u0628\u0628 \u0638\u0644\u0645\u0647 \u0648\u0628\u063a\u064a\u0647.","3:129":"\u0648\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0645\u0627 \u0641\u064a \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0645\u0627 \u0641\u064a \u0627\u0644\u0623\u0631\u0636\u060c \u064a\u063a\u0641\u0631 \u0644\u0645\u0646 \u064a\u0634\u0627\u0621 \u0645\u0646 \u0639\u0628\u0627\u062f\u0647 \u0628\u0631\u062d\u0645\u062a\u0647\u060c \u0648\u064a\u0639\u0630\u0628 \u0645\u0646 \u064a\u0634\u0627\u0621 \u0628\u0639\u062f\u0644\u0647. \u0648\u0627\u0644\u0644\u0647 \u063a\u0641\u0648\u0631 \u0644\u0630\u0646\u0648\u0628 \u0639\u0628\u0627\u062f\u0647\u060c \u0631\u062d\u064a\u0645 \u0628\u0647\u0645.","3:130":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647 \u0627\u062d\u0630\u0631\u0648\u0627 \u0627\u0644\u0631\u0628\u0627 \u0628\u062c\u0645\u064a\u0639 \u0623\u0646\u0648\u0627\u0639\u0647\u060c \u0648\u0644\u0627 \u062a\u0623\u062e\u0630\u0648\u0627 \u0641\u064a \u0627\u0644\u0642\u0631\u0636 \u0632\u064a\u0627\u062f\u0629 \u0639\u0644\u0649 \u0631\u0624\u0648\u0633 \u0623\u0645\u0648\u0627\u0644\u0643\u0645 \u0648\u0625\u0646 \u0642\u0644\u0651\u064e\u062a\u060c \u0641\u0643\u064a\u0641 \u0625\u0630\u0627 \u0643\u0627\u0646\u062a \u0647\u0630\u0647 \u0627\u0644\u0632\u064a\u0627\u062f\u0629 \u062a\u062a\u0636\u0627\u0639\u0641 \u0643\u0644\u0645\u0627 \u062d\u0627\u0646 \u0645\u0648\u0639\u062f \u0633\u062f\u0627\u062f \u0627\u0644\u062f\u064a\u0646\u061f \u0648\u0627\u062a\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0628\u0627\u0644\u062a\u0632\u0627\u0645 \u0634\u0631\u0639\u0647; \u0644\u062a\u0641\u0648\u0632\u0648\u0627 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629.","3:131":"\u0648\u0627\u062c\u0639\u0644\u0648\u0627 \u0644\u0623\u0646\u0641\u0633\u0643\u0645 \u0648\u0642\u0627\u064a\u0629 \u0628\u064a\u0646\u0643\u0645 \u0648\u0628\u064a\u0646 \u0627\u0644\u0646\u0627\u0631 \u0627\u0644\u062a\u064a \u0647\u064f\u064a\u0651\u0650\u0626\u062a \u0644\u0644\u0643\u0627\u0641\u0631\u064a\u0646.","3:132":"\u0648\u0623\u0637\u064a\u0639\u0648\u0627 \u0627\u0644\u0644\u0647 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0641\u064a\u0645\u0627 \u0623\u0645\u0631\u0643\u0645 \u0628\u0647 \u0645\u0646 \u0627\u0644\u0637\u0627\u0639\u0627\u062a \u0648\u0641\u064a\u0645\u0627 \u0646\u0647\u0627\u0643\u0645 \u0639\u0646\u0647 \u0645\u0646 \u0623\u0643\u0644 \u0627\u0644\u0631\u0628\u0627 \u0648\u063a\u064a\u0631\u0647 \u0645\u0646 \u0627\u0644\u0623\u0634\u064a\u0627\u0621\u060c \u0648\u0623\u0637\u064a\u0639\u0648\u0627 \u0627\u0644\u0631\u0633\u0648\u0644; \u0644\u062a\u0631\u062d\u0645\u0648\u0627\u060c \u0641\u0644\u0627 \u062a\u0639\u0630\u0628\u0648\u0627.","3:133":"\u0648\u0628\u0627\u062f\u0631\u0648\u0627 \u0628\u0637\u0627\u0639\u062a\u0643\u0645 \u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0644\u0627\u063a\u062a\u0646\u0627\u0645 \u0645\u063a\u0641\u0631\u0629 \u0639\u0638\u064a\u0645\u0629 \u0645\u0646 \u0631\u0628\u0643\u0645 \u0648\u062c\u0646\u0629 \u0648\u0627\u0633\u0639\u0629\u060c \u0639\u0631\u0636\u0647\u0627 \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636\u060c \u0623\u0639\u062f\u0647\u0627 \u0627\u0644\u0644\u0647 \u0644\u0644\u0645\u062a\u0642\u064a\u0646.","3:134":"\u0627\u0644\u0630\u064a\u0646 \u064a\u0646\u0641\u0642\u0648\u0646 \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0641\u064a \u0627\u0644\u064a\u0633\u0631 \u0648\u0627\u0644\u0639\u0633\u0631\u060c \u0648\u0627\u0644\u0630\u064a\u0646 \u064a\u0645\u0633\u0643\u0648\u0646 \u0645\u0627 \u0641\u064a \u0623\u0646\u0641\u0633\u0647\u0645 \u0645\u0646 \u0627\u0644\u063a\u064a\u0638 \u0628\u0627\u0644\u0635\u0628\u0631\u060c \u0648\u0625\u0630\u0627 \u0642\u064e\u062f\u064e\u0631\u0648\u0627 \u0639\u064e\u0641\u064e\u0648\u0627 \u0639\u0645\u0651\u064e\u0646 \u0638\u0644\u0645\u0647\u0645. \u0648\u0647\u0630\u0627 \u0647\u0648 \u0627\u0644\u0625\u062d\u0633\u0627\u0646 \u0627\u0644\u0630\u064a \u064a\u062d\u0628 \u0627\u0644\u0644\u0647 \u0623\u0635\u062d\u0627\u0628\u0647.","3:135":"\u0648\u0627\u0644\u0630\u064a\u0646 \u0625\u0630\u0627 \u0627\u0631\u062a\u0643\u0628\u0648\u0627 \u0630\u0646\u0628\u064b\u0627 \u0643\u0628\u064a\u0631\u064b\u0627 \u0623\u0648 \u0638\u0644\u0645\u0648\u0627 \u0623\u0646\u0641\u0633\u0647\u0645 \u0628\u0627\u0631\u062a\u0643\u0627\u0628 \u0645\u0627 \u062f\u0648\u0646\u0647\u060c \u0630\u0643\u0631\u0648\u0627 \u0648\u0639\u062f \u0627\u0644\u0644\u0647 \u0648\u0648\u0639\u064a\u062f\u0647 \u0641\u0644\u062c\u0623\u0648\u0627 \u0625\u0644\u0649 \u0631\u0628\u0647\u0645 \u062a\u0627\u0626\u0628\u064a\u0646\u060c \u064a\u0637\u0644\u0628\u0648\u0646 \u0645\u0646\u0647 \u0623\u0646 \u064a\u063a\u0641\u0631 \u0644\u0647\u0645 \u0630\u0646\u0648\u0628\u0647\u0645\u060c \u0648\u0647\u0645 \u0645\u0648\u0642\u0646\u0648\u0646 \u0623\u0646\u0647 \u0644\u0627 \u064a\u063a\u0641\u0631 \u0627\u0644\u0630\u0646\u0648\u0628 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647\u060c \u0641\u0647\u0645 \u0644\u0630\u0644\u0643 \u0644\u0627 \u064a\u0642\u064a\u0645\u0648\u0646 \u0639\u0644\u0649 \u0645\u0639\u0635\u064a\u0629\u060c \u0648\u0647\u0645 \u064a\u0639\u0644\u0645\u0648\u0646 \u0623\u0646\u0647\u0645 \u0625\u0646 \u062a\u0627\u0628\u0648\u0627 \u062a\u0627\u0628 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645.","3:136":"\u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0645\u0648\u0635\u0648\u0641\u0648\u0646 \u0628\u062a\u0644\u0643 \u0627\u0644\u0635\u0641\u0627\u062a \u0627\u0644\u0639\u0638\u064a\u0645\u0629 \u062c\u0632\u0627\u0624\u0647\u0645 \u0623\u0646 \u064a\u0633\u062a\u0631 \u0627\u0644\u0644\u0647 \u0630\u0646\u0648\u0628\u0647\u0645\u060c \u0648\u0644\u0647\u0645 \u062c\u0646\u0627\u062a \u062a\u062c\u0631\u064a \u0645\u0646 \u062a\u062d\u062a \u0623\u0634\u062c\u0627\u0631\u0647\u0627 \u0648\u0642\u0635\u0648\u0631\u0647\u0627 \u0627\u0644\u0645\u064a\u0627\u0647 \u0627\u0644\u0639\u0630\u0628\u0629\u060c \u062e\u0627\u0644\u062f\u064a\u0646 \u0641\u064a\u0647\u0627 \u0644\u0627 \u064a\u062e\u0631\u062c\u0648\u0646 \u0645\u0646\u0647\u0627 \u0623\u0628\u062f\u064b\u0627. \u0648\u0646\u0650\u0639\u0652\u0645\u064e \u0623\u062c\u0631 \u0627\u0644\u0639\u0627\u0645\u0644\u064a\u0646 \u0627\u0644\u0645\u063a\u0641\u0631\u0629 \u0648\u0627\u0644\u062c\u0646\u0629.","3:137":"\u064a\u062e\u0627\u0637\u0628 \u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0644\u0645\u0651\u064e\u0627 \u0623\u064f\u0635\u064a\u0628\u0648\u0627 \u064a\u0648\u0645 \xab\u0623\u064f\u062d\u062f\xbb \u062a\u0639\u0632\u064a\u0629 \u0644\u0647\u0645 \u0628\u0623\u0646\u0647 \u0642\u062f \u0645\u0636\u062a \u0645\u0646 \u0642\u0628\u0644\u0643\u0645 \u0623\u0645\u0645\u060c \u0627\u0628\u062a\u064f\u0644\u064a \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0645\u0646\u0647\u0645 \u0628\u0642\u062a\u0627\u0644 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0641\u0643\u0627\u0646\u062a \u0627\u0644\u0639\u0627\u0642\u0628\u0629 \u0644\u0647\u0645\u060c \u0641\u0633\u064a\u0631\u0648\u0627 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0645\u0639\u062a\u0628\u0631\u064a\u0646 \u0628\u0645\u0627 \u0622\u0644 \u0625\u0644\u064a\u0647 \u0623\u0645\u0631 \u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0645\u0643\u0630\u0628\u064a\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0644\u0647.","3:138":"\u0647\u0630\u0627 \u0627\u0644\u0642\u0631\u0622\u0646 \u0628\u064a\u0627\u0646 \u0648\u0625\u0631\u0634\u0627\u062f \u0625\u0644\u0649 \u0637\u0631\u064a\u0642 \u0627\u0644\u062d\u0642\u060c \u0648\u062a\u0630\u0643\u064a\u0631 \u062a\u062e\u0634\u0639 \u0644\u0647 \u0642\u0644\u0648\u0628 \u0627\u0644\u0645\u062a\u0642\u064a\u0646\u060c \u0648\u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u064a\u062e\u0634\u0648\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u062e\u064f\u0635\u0651\u064f\u0648\u0627 \u0628\u0630\u0644\u0643; \u0644\u0623\u0646\u0647\u0645 \u0647\u0645 \u0627\u0644\u0645\u0646\u062a\u0641\u0639\u0648\u0646 \u0628\u0647 \u062f\u0648\u0646 \u063a\u064a\u0631\u0647\u0645.","3:139":"\u0648\u0644\u0627 \u062a\u0636\u0652\u0639\u064f\u0641\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0639\u0646 \u0642\u062a\u0627\u0644 \u0639\u062f\u0648\u0643\u0645\u060c \u0648\u0644\u0627 \u062a\u062d\u0632\u0646\u0648\u0627 \u0644\u0645\u0627 \u0623\u0635\u0627\u0628\u0643\u0645 \u0641\u064a \xab\u0623\u064f\u062d\u062f\xbb \u060c \u0648\u0623\u0646\u062a\u0645 \u0627\u0644\u063a\u0627\u0644\u0628\u0648\u0646 \u0648\u0627\u0644\u0639\u0627\u0642\u0628\u0629 \u0644\u0643\u0645\u060c \u0625\u0646 \u0643\u0646\u062a\u0645 \u0645\u0635\u062f\u0642\u064a\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0645\u062a\u0651\u064e\u0628\u0639\u064a\u0646 \u0634\u0631\u0639\u0647.","3:140":"\u0625\u0646 \u0623\u0635\u0627\u0628\u062a\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u062c\u0631\u0627\u062d \u0623\u0648 \u0642\u062a\u0644 \u0641\u064a \u063a\u0632\u0648\u0629 \xab\u0623\u064f\u062d\u062f\xbb \u0641\u062d\u0632\u0646\u062a\u0645 \u0644\u0630\u0644\u0643\u060c \u0641\u0642\u062f \u0623\u0635\u0627\u0628 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u062c\u0631\u0627\u062d \u0648\u0642\u062a\u0644 \u0645\u062b\u0644 \u0630\u0644\u0643 \u0641\u064a \u063a\u0632\u0648\u0629 \xab\u0628\u062f\u0631\xbb . \u0648\u062a\u0644\u0643 \u0627\u0644\u0623\u064a\u0627\u0645 \u064a\u064f\u0635\u064e\u0631\u0651\u0650\u0641\u0647\u0627 \u0627\u0644\u0644\u0647 \u0628\u064a\u0646 \u0627\u0644\u0646\u0627\u0633\u060c \u0646\u0635\u0631 \u0645\u0631\u0629 \u0648\u0647\u0632\u064a\u0645\u0629 \u0623\u062e\u0631\u0649\u060c \u0644\u0645\u0627 \u0641\u064a \u0630\u0644\u0643 \u0645\u0646 \u0627\u0644\u062d\u0643\u0645\u0629\u060c \u062d\u062a\u0649 \u064a\u0638\u0647\u0631 \u0645\u0627 \u0639\u0644\u0645\u0647 \u0627\u0644\u0644\u0647 \u0641\u064a \u0627\u0644\u0623\u0632\u0644 \u0644\u064a\u0645\u064a\u0632 \u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u0624\u0645\u0646 \u0627\u0644\u0635\u0627\u062f\u0642 \u0645\u0650\u0646 \u063a\u064a\u0631\u0647\u060c \u0648\u064a\u064f\u0643\u0652\u0631\u0650\u0645\u064e \u0623\u0642\u0648\u0627\u0645\u064b\u0627 \u0645\u0646\u0643\u0645 \u0628\u0627\u0644\u0634\u0647\u0627\u062f\u0629. \u0648\u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u062d\u0628 \u0627\u0644\u0630\u064a\u0646 \u0638\u0644\u0645\u0648\u0627 \u0623\u0646\u0641\u0633\u0647\u0645\u060c \u0648\u0642\u0639\u062f\u0648\u0627 \u0639\u0646 \u0627\u0644\u0642\u062a\u0627\u0644 \u0641\u064a \u0633\u0628\u064a\u0644\u0647.","3:141":"\u0648\u0647\u0630\u0647 \u0627\u0644\u0647\u0632\u064a\u0645\u0629 \u0627\u0644\u062a\u064a \u0648\u0642\u0639\u062a \u0641\u064a \xab\u0623\u064f\u062d\u062f\xbb \u0643\u0627\u0646\u062a \u0627\u062e\u062a\u0628\u0627\u0631\u064b\u0627 \u0648\u062a\u0635\u0641\u064a\u0629 \u0644\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0648\u062a\u062e\u0644\u064a\u0635\u064b\u0627 \u0644\u0647\u0645 \u0645\u0646 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0648\u0647\u0644\u0627\u0643\u064b\u0627 \u0644\u0644\u0643\u0627\u0641\u0631\u064a\u0646.","3:142":"\u064a\u0627 \u0623\u0635\u062d\u0627\u0628 \u0645\u062d\u0645\u062f -\u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645- \u0623\u0638\u0646\u0646\u062a\u0645 \u0623\u0646 \u062a\u062f\u062e\u0644\u0648\u0627 \u0627\u0644\u062c\u0646\u0629\u060c \u0648\u0644\u0645 \u062a\u064f\u0628\u0652\u062a\u064e\u0644\u0648\u0627 \u0628\u0627\u0644\u0642\u062a\u0627\u0644 \u0648\u0627\u0644\u0634\u062f\u0627\u0626\u062f\u061f \u0644\u0627 \u064a\u062d\u0635\u0644 \u0644\u0643\u0645 \u062f\u062e\u0648\u0644\u0647\u0627 \u062d\u062a\u0649 \u062a\u064f\u0628\u0652\u062a\u0644\u0648\u0627\u060c \u0648\u064a\u0639\u0644\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u0645\u0627 \u0638\u0627\u0647\u0631\u0627 \u0644\u0644\u062e\u0644\u0642 \u0627\u0644\u0645\u062c\u0627\u0647\u062f\u064a\u0646 \u0645\u0646\u0643\u0645 \u0641\u064a \u0633\u0628\u064a\u0644\u0647\u060c \u0648\u0627\u0644\u0635\u0627\u0628\u0631\u064a\u0646 \u0639\u0644\u0649 \u0645\u0642\u0627\u0648\u0645\u0629 \u0627\u0644\u0623\u0639\u062f\u0627\u0621.","3:143":"\u0648\u0644\u0642\u062f \u0643\u0646\u062a\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0642\u0628\u0644 \u063a\u0632\u0648\u0629 \xab\u0623\u064f\u062d\u062f\xbb \u062a\u062a\u0645\u0646\u0648\u0646 \u0644\u0642\u0627\u0621 \u0627\u0644\u0639\u062f\u0648; \u0644\u062a\u0646\u0627\u0644\u0648\u0627 \u0634\u0631\u0641 \u0627\u0644\u062c\u0647\u0627\u062f \u0648\u0627\u0644\u0627\u0633\u062a\u0634\u0647\u0627\u062f \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a \u062d\u064e\u0638\u0650\u064a \u0628\u0647 \u0625\u062e\u0648\u0627\u0646\u0643\u0645 \u0641\u064a \u063a\u0632\u0648\u0629 \xab\u0628\u062f\u0631\xbb \u060c \u0641\u0647\u0627 \u0647\u0648 \u0630\u0627 \u0642\u062f \u062d\u0635\u0644 \u0644\u0643\u0645 \u0627\u0644\u0630\u064a \u062a\u0645\u0646\u064a\u062a\u0645\u0648\u0647 \u0648\u0637\u0644\u0628\u062a\u0645\u0648\u0647\u060c \u0641\u062f\u0648\u0646\u0643\u0645 \u0641\u0642\u0627\u062a\u0644\u0648\u0627 \u0648\u0635\u0627\u0628\u0631\u0648\u0627.","3:144":"\u0648\u0645\u0627 \u0645\u062d\u0645\u062f - \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 - \u0625\u0644\u0627 \u0631\u0633\u0648\u0644 \u0645\u0646 \u062c\u0646\u0633 \u0627\u0644\u0631\u0633\u0644 \u0627\u0644\u0630\u064a\u0646 \u0642\u0628\u0644\u0647 \u064a\u0628\u0644\u063a \u0631\u0633\u0627\u0644\u0629 \u0631\u0628\u0647. \u0623\u0641\u0625\u0646 \u0645\u0627\u062a \u0628\u0627\u0646\u0642\u0636\u0627\u0621 \u0623\u062c\u0644\u0647 \u0623\u0648 \u0642\u064f\u062a\u0650\u0644 \u0643\u0645\u0627 \u0623\u0634\u0627\u0639\u0647 \u0627\u0644\u0623\u0639\u062f\u0627\u0621 \u0631\u062c\u0639\u062a\u0645 \u0639\u0646 \u062f\u064a\u0646\u0643\u0645\u060c\u060c \u062a\u0631\u0643\u062a\u0645 \u0645\u0627 \u062c\u0627\u0621\u0643\u0645 \u0628\u0647 \u0646\u0628\u064a\u0643\u0645\u061f \u0648\u0645\u0646 \u064a\u0631\u062c\u0650\u0639\u064f \u0645\u0646\u0643\u0645 \u0639\u0646 \u062f\u064a\u0646\u0647 \u0641\u0644\u0646 \u064a\u0636\u0631 \u0627\u0644\u0644\u0647 \u0634\u064a\u0626\u064b\u0627\u060c \u0625\u0646\u0645\u0627 \u064a\u0636\u0631 \u0646\u0641\u0633\u0647 \u0636\u0631\u0631\u064b\u0627 \u0639\u0638\u064a\u0645\u064b\u0627. \u0623\u0645\u0627 \u0645\u064e\u0646 \u062b\u0628\u062a \u0639\u0644\u0649 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0634\u0643\u0631 \u0631\u0628\u0647 \u0639\u0644\u0649 \u0646\u0639\u0645\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u062c\u0632\u064a\u0647 \u0623\u062d\u0633\u0646 \u0627\u0644\u062c\u0632\u0627\u0621.","3:145":"\u0644\u0646 \u064a\u0645\u0648\u062a \u0623\u062d\u062f \u0625\u0644\u0627 \u0628\u0625\u0630\u0646 \u0627\u0644\u0644\u0647 \u0648\u0642\u062f\u0631\u0647 \u0648\u062d\u062a\u0649 \u064a\u0633\u062a\u0648\u0641\u064a \u0627\u0644\u0645\u062f\u0629 \u0627\u0644\u062a\u064a \u0642\u062f\u0631\u0647\u0627 \u0627\u0644\u0644\u0647 \u0644\u0647 \u0643\u062a\u0627\u0628\u064b\u0627 \u0645\u0624\u062c\u0651\u064e\u0644\u0627. \u0648\u0645\u0646 \u064a\u0637\u0644\u0628 \u0628\u0639\u0645\u0644\u0647 \u0639\u064e\u0631\u064e\u0636 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0646\u0639\u0637\u0647 \u0645\u0627 \u0642\u0633\u0645\u0646\u0627\u0647 \u0644\u0647 \u0645\u0646 \u0631\u0632\u0642\u060c \u0648\u0644\u0627 \u062d\u0638\u0651\u064e \u0644\u0647 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u0645\u0646 \u064a\u0637\u0644\u0628 \u0628\u0639\u0645\u0644\u0647 \u0627\u0644\u062c\u0632\u0627\u0621 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u0646\u0645\u0646\u062d\u0647 \u0645\u0627 \u0637\u0644\u0628\u0647\u060c \u0648\u0646\u0624\u062a\u0647 \u062c\u0632\u0627\u0621\u0647 \u0648\u0627\u0641\u0631\u064b\u0627 \u0645\u0639 \u0645\u0627 \u0644\u064e\u0647 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0645\u0646 \u0631\u0632\u0642 \u0645\u0642\u0633\u0648\u0645\u060c \u0641\u0647\u0630\u0627 \u0642\u062f \u0634\u064e\u0643\u064e\u0631\u064e\u0646\u0627 \u0628\u0637\u0627\u0639\u062a\u0647 \u0648\u062c\u0647\u0627\u062f\u0647\u060c \u0648\u0633\u0646\u062c\u0632\u064a \u0627\u0644\u0634\u0627\u0643\u0631\u064a\u0646 \u062e\u064a\u0631\u064b\u0627.","3:146":"\u0643\u062b\u064a\u0631 \u0645\u0646 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0627\u0644\u0633\u0627\u0628\u0642\u064a\u0646 \u0642\u0627\u062a\u0644 \u0645\u0639\u0647\u0645 \u062c\u0645\u0648\u0639 \u0643\u062b\u064a\u0631\u0629 \u0645\u0646 \u0623\u0635\u062d\u0627\u0628\u0647\u0645\u060c \u0641\u0645\u0627 \u0636\u0639\u0641\u0648\u0627 \u0644\u0650\u0645\u064e\u0627 \u0646\u0632\u0644 \u0628\u0647\u0645 \u0645\u0646 \u062c\u0631\u0648\u062d \u0623\u0648 \u0642\u062a\u0644; \u0644\u0623\u0646 \u0630\u0644\u0643 \u0641\u064a \u0633\u0628\u064a\u0644 \u0631\u0628\u0647\u0645\u060c \u0648\u0645\u0627 \u0639\u064e\u062c\u064e\u0632\u0648\u0627\u060c \u0648\u0644\u0627 \u062e\u0636\u0639\u0648\u0627 \u0644\u0639\u062f\u0648\u0647\u0645\u060c \u0625\u0646\u0645\u0627 \u0635\u0628\u0631\u0648\u0627 \u0639\u0644\u0649 \u0645\u0627 \u0623\u0635\u0627\u0628\u0647\u0645. \u0648\u0627\u0644\u0644\u0647 \u064a\u062d\u0628 \u0627\u0644\u0635\u0627\u0628\u0631\u064a\u0646.","3:147":"\u0648\u0645\u0627 \u0643\u0627\u0646 \u0642\u0648\u0644 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0635\u0627\u0628\u0631\u064a\u0646 \u0625\u0644\u0627 \u0623\u0646 \u0642\u0627\u0644\u0648\u0627: \u0631\u0628\u0646\u0627 \u0627\u063a\u0641\u0631 \u0644\u0646\u0627 \u0630\u0646\u0648\u0628\u0646\u0627\u060c \u0648\u0645\u0627 \u0648\u0642\u0639 \u0645\u0646\u0627 \u0645\u0650\u0646 \u062a\u062c\u0627\u0648\u0632\u064d \u0641\u064a \u0623\u0645\u0631 \u062f\u064a\u0646\u0646\u0627\u060c \u0648\u062b\u0628\u0651\u0650\u062a \u0623\u0642\u062f\u0627\u0645\u0646\u0627 \u062d\u062a\u0649 \u0644\u0627 \u0646\u0641\u0631\u0651\u064e \u0645\u0646 \u0642\u062a\u0627\u0644 \u0639\u062f\u0648\u0646\u0627\u060c \u0648\u0627\u0646\u0635\u0631\u0646\u0627 \u0639\u0644\u0649 \u0645\u064e\u0646 \u062c\u062d\u062f \u0648\u062d\u062f\u0627\u0646\u064a\u062a\u0643 \u0648\u0646\u0628\u0648\u0629 \u0623\u0646\u0628\u064a\u0627\u0626\u0643.","3:148":"\u0641\u0623\u0639\u0637\u0649 \u0627\u0644\u0644\u0647 \u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0635\u0627\u0628\u0631\u064a\u0646 \u062c\u0632\u0627\u0621\u0647\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0628\u0627\u0644\u0646\u0635\u0631 \u0639\u0644\u0649 \u0623\u0639\u062f\u0627\u0626\u0647\u0645\u060c \u0648\u0628\u0627\u0644\u062a\u0645\u0643\u064a\u0646 \u0644\u0647\u0645 \u0641\u064a \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0628\u0627\u0644\u062c\u0632\u0627\u0621 \u0627\u0644\u062d\u0633\u0646 \u0627\u0644\u0639\u0638\u064a\u0645 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u0647\u0648 \u062c\u0646\u0627\u062a \u0627\u0644\u0646\u0639\u064a\u0645. \u0648\u0627\u0644\u0644\u0647 \u064a\u062d\u0628 \u0643\u0644\u0651\u064e \u0645\u064e\u0646 \u0623\u062d\u0633\u0646 \u0639\u0628\u0627\u062f\u062a\u0647 \u0644\u0631\u0628\u0647 \u0648\u0645\u0639\u0627\u0645\u0644\u062a\u0647 \u0644\u062e\u0644\u0642\u0647.","3:149":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647\u060c \u0625\u0646 \u062a\u0637\u064a\u0639\u0648\u0627 \u0627\u0644\u0630\u064a\u0646 \u062c\u062d\u062f\u0648\u0627 \u0623\u0644\u0648\u0647\u064a\u062a\u064a\u060c \u0648\u0644\u0645 \u064a\u0624\u0645\u0646\u0648\u0627 \u0628\u0631\u0633\u0644\u064a \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0648\u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0648\u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0641\u064a\u0645\u0627 \u064a\u0623\u0645\u0631\u0648\u0646\u0643\u0645 \u0628\u0647 \u0648\u064a\u0646\u0647\u0648\u0646\u0643\u0645 \u0639\u0646\u0647\u060c \u064a\u0636\u0644\u0648\u0643\u0645 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u062d\u0642\u060c \u0648\u062a\u0631\u062a\u062f\u0651\u064f\u0648\u0627 \u0639\u0646 \u062f\u064a\u0646\u0643\u0645\u060c \u0641\u062a\u0639\u0648\u062f\u0648\u0627 \u0628\u0627\u0644\u062e\u0633\u0631\u0627\u0646 \u0627\u0644\u0645\u0628\u064a\u0646 \u0648\u0627\u0644\u0647\u0644\u0627\u0643 \u0627\u0644\u0645\u062d\u0642\u0642.","3:150":"\u0625\u0646\u0647\u0645 \u0644\u0646 \u064a\u0646\u0635\u0631\u0648\u0643\u0645\u060c \u0628\u0644 \u0627\u0644\u0644\u0647 \u0646\u0627\u0635\u0631\u0643\u0645\u060c \u0648\u0647\u0648 \u062e\u064a\u0631 \u0646\u0627\u0635\u0631\u060c \u0641\u0644\u0627 \u064a\u062d\u062a\u0627\u062c \u0645\u0639\u0647 \u0625\u0644\u0649 \u0646\u0635\u0631\u0629 \u0623\u062d\u062f.","3:151":"\u0633\u0646\u0642\u0630\u0641 \u0641\u064a \u0642\u0644\u0648\u0628 \u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0623\u0634\u062f\u0651\u064e \u0627\u0644\u0641\u0632\u0639 \u0648\u0627\u0644\u062e\u0648\u0641 \u0628\u0633\u0628\u0628 \u0625\u0634\u0631\u0627\u0643\u0647\u0645 \u0628\u0627\u0644\u0644\u0647 \u0622\u0644\u0647\u0629 \u0645\u0632\u0639\u0648\u0645\u0629\u060c \u0644\u064a\u0633 \u0644\u0647\u0645 \u062f\u0644\u064a\u0644 \u0623\u0648 \u0628\u0631\u0647\u0627\u0646 \u0639\u0644\u0649 \u0627\u0633\u062a\u062d\u0642\u0627\u0642\u0647\u0627 \u0644\u0644\u0639\u0628\u0627\u062f\u0629 \u0645\u0639 \u0627\u0644\u0644\u0647\u060c \u0641\u062d\u0627\u0644\u062a\u0647\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627: \u0631\u0639\u0628 \u0648\u0647\u0644\u0639 \u0645\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0623\u0645\u0627 \u0645\u0643\u0627\u0646\u0647\u0645 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u0627\u0644\u0630\u064a \u064a\u0623\u0648\u0648\u0646 \u0625\u0644\u064a\u0647 \u0641\u0647\u0648 \u0627\u0644\u0646\u0627\u0631; \u0648\u0630\u0644\u0643 \u0628\u0633\u0628\u0628 \u0638\u0644\u0645\u0647\u0645 \u0648\u0639\u062f\u0648\u0627\u0646\u0647\u0645\u060c \u0648\u0633\u0627\u0621 \u0647\u0630\u0627 \u0627\u0644\u0645\u0642\u0627\u0645 \u0645\u0642\u0627\u0645\u064b\u0627 \u0644\u0647\u0645.","3:152":"\u0648\u0644\u0642\u062f \u062d\u0642\u0642 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0645\u0627 \u0648\u0639\u062f\u0643\u0645 \u0628\u0647 \u0645\u0646 \u0646\u0635\u0631\u060c \u062d\u064a\u0646 \u0643\u0646\u062a\u0645 \u062a\u0642\u062a\u0644\u0648\u0646 \u0627\u0644\u0643\u0641\u0627\u0631 \u0641\u064a \u063a\u0632\u0648\u0629 \xab\u0623\u064f\u062d\u062f\xbb \u0628\u0625\u0630\u0646\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u062d\u062a\u0649 \u0625\u0630\u0627 \u062c\u064e\u0628\u064f\u0646\u062a\u0645 \u0648\u0636\u0639\u0641\u062a\u0645 \u0639\u0646 \u0627\u0644\u0642\u062a\u0627\u0644 \u0648\u0627\u062e\u062a\u0644\u0641\u062a\u0645: \u0647\u0644 \u062a\u0628\u0642\u0648\u0646 \u0641\u064a \u0645\u0648\u0627\u0642\u0639\u0643\u0645 \u0623\u0648 \u062a\u062a\u0631\u0643\u0648\u0646\u0647\u0627 \u0644\u062c\u0645\u0639 \u0627\u0644\u063a\u0646\u0627\u0626\u0645 \u0645\u0639 \u0645\u064e\u0646 \u064a\u062c\u0645\u0639\u0647\u0627\u061f \u0648\u0639\u0635\u064a\u062a\u0645 \u0623\u0645\u0631 \u0631\u0633\u0648\u0644\u0643\u0645 \u062d\u064a\u0646 \u0623\u0645\u0631\u0643\u0645 \u0623\u0644\u0627 \u062a\u0641\u0627\u0631\u0641\u0648\u0627 \u0623\u0645\u0627\u0643\u0646\u0643\u0645 \u0628\u0623\u064a \u062d\u0627\u0644\u060c \u062d\u0644\u0651\u064e\u062a \u0628\u0643\u0645 \u0627\u0644\u0647\u0632\u064a\u0645\u0629 \u0645\u0646 \u0628\u0639\u062f \u0645\u0627 \u0623\u0631\u0627\u0643\u0645 \u0645\u0627 \u062a\u062d\u0628\u0648\u0646 \u0645\u0646 \u0627\u0644\u0646\u0635\u0631\u060c \u0648\u062a\u0628\u064a\u0651\u064e\u0646 \u0623\u0646 \u0645\u0646\u0643\u0645 \u0645\u064e\u0646 \u064a\u0631\u064a\u062f \u0627\u0644\u063a\u0646\u0627\u0626\u0645\u060c \u0648\u0623\u0646 \u0645\u0646\u0643\u0645 \u0645\u064e\u0646 \u064a\u0637\u0644\u0628 \u0627\u0644\u0622\u062e\u0631\u0629 \u0648\u062b\u0648\u0627\u0628\u0647\u0627\u060c \u062b\u0645 \u0635\u0631\u0641 \u0627\u0644\u0644\u0647 \u0648\u062c\u0648\u0647\u0643\u0645 \u0639\u0646 \u0639\u062f\u0648\u0643\u0645; \u0644\u064a\u062e\u062a\u0628\u0631\u0643\u0645\u060c \u0648\u0642\u062f \u0639\u0644\u0645 \u0627\u0644\u0644\u0647 \u0646\u062f\u0645\u0643\u0645 \u0648\u062a\u0648\u0628\u062a\u0643\u0645 \u0641\u0639\u0641\u0627 \u0639\u0646\u0643\u0645\u060c \u0648\u0627\u0644\u0644\u0647 \u0630\u0648 \u0641\u0636\u0644 \u0639\u0638\u064a\u0645 \u0639\u0644\u0649 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646.","3:153":"\u0627\u0630\u0643\u0631\u0648\u0627 -\u064a\u0627 \u0623\u0635\u062d\u0627\u0628 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645- \u0645\u0627 \u0643\u0627\u0646 \u0645\u0650\u0646 \u0623\u0645\u0631\u0643\u0645 \u062d\u064a\u0646 \u0623\u062e\u0630\u062a\u0645 \u062a\u0635\u0639\u062f\u0648\u0646 \u0627\u0644\u062c\u0628\u0644 \u0647\u0627\u0631\u0628\u064a\u0646 \u0645\u0646 \u0623\u0639\u062f\u0627\u0626\u0643\u0645\u060c \u0648\u0644\u0627 \u062a\u0644\u062a\u0641\u062a\u0648\u0646 \u0625\u0644\u0649 \u0623\u062d\u062f \u0644\u0650\u0645\u064e\u0627 \u0627\u0639\u062a\u0631\u0627\u0643\u0645 \u0645\u0646 \u0627\u0644\u062f\u0647\u0634\u0629 \u0648\u0627\u0644\u062e\u0648\u0641 \u0648\u0627\u0644\u0631\u0639\u0628\u060c \u0648\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u062b\u0627\u0628\u062a \u0641\u064a \u0627\u0644\u0645\u064a\u062f\u0627\u0646 \u064a\u0646\u0627\u062f\u064a\u0643\u0645 \u0645\u0646 \u062e\u0644\u0641\u0643\u0645 \u0642\u0627\u0626\u0644\u0627 \u0625\u0644\u064a\u0651\u064e \u0639\u0628\u0627\u062f\u064e \u0627\u0644\u0644\u0647\u060c \u0648\u0623\u0646\u062a\u0645 \u0644\u0627 \u062a\u0633\u0645\u0639\u0648\u0646 \u0648\u0644\u0627 \u062a\u0646\u0638\u0631\u0648\u0646\u060c \u0641\u0643\u0627\u0646 \u062c\u0632\u0627\u0624\u0643\u0645 \u0623\u0646 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0628\u0643\u0645 \u0623\u0644\u0645\u064b\u0627 \u0648\u0636\u064a\u0642\u064b\u0627 \u0648\u063a\u0645\u0651\u064b\u0627; \u0644\u0643\u064a \u0644\u0627 \u062a\u062d\u0632\u0646\u0648\u0627 \u0639\u0644\u0649 \u0645\u0627 \u0641\u0627\u062a\u0643\u0645 \u0645\u0646 \u0646\u0635\u0631 \u0648\u063a\u0646\u064a\u0645\u0629\u060c \u0648\u0644\u0627 \u0645\u0627 \u062d\u0644\u0651\u064e \u0628\u0643\u0645 \u0645\u0646 \u062e\u0648\u0641 \u0648\u0647\u0632\u064a\u0645\u0629. \u0648\u0627\u0644\u0644\u0647 \u062e\u0628\u064a\u0631 \u0628\u062c\u0645\u064a\u0639 \u0623\u0639\u0645\u0627\u0644\u0643\u0645\u060c \u0644\u0627 \u064a\u062e\u0641\u0649 \u0639\u0644\u064a\u0647 \u0645\u0646\u0647\u0627 \u0634\u064a\u0621.","3:154":"\u062b\u0645 \u0643\u0627\u0646 \u0645\u0646 \u0631\u062d\u0645\u0629 \u0627\u0644\u0644\u0647 \u0628\u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0627\u0644\u0645\u062e\u0644\u0635\u064a\u0646 \u0623\u0646 \u0623\u0644\u0642\u0649 \u0641\u064a \u0642\u0644\u0648\u0628\u0647\u0645 \u0645\u0646 \u0628\u0639\u062f \u0645\u0627 \u0646\u0632\u0644 \u0628\u0647\u0627 \u0645\u0646 \u0647\u0645\u0651\u064d \u0648\u063a\u0645\u0651\u064d \u0627\u0637\u0645\u0626\u0646\u0627\u0646\u064b\u0627 \u0648\u062b\u0642\u0629 \u0641\u064a \u0648\u0639\u062f \u0627\u0644\u0644\u0647\u060c \u0648\u0643\u0627\u0646 \u0645\u0646 \u0623\u062b\u0631\u0647 \u0646\u0639\u0627\u0633 \u063a\u064e\u0634\u0650\u064a \u0637\u0627\u0626\u0641\u0629 \u0645\u0646\u0647\u0645\u060c \u0648\u0647\u0645 \u0623\u0647\u0644 \u0627\u0644\u0625\u062e\u0644\u0627\u0635 \u0648\u0627\u0644\u064a\u0642\u064a\u0646\u060c \u0648\u0637\u0627\u0626\u0641\u0629 \u0623\u064f\u062e\u0631\u0649 \u0623\u0647\u0645\u0651\u064e\u0647\u0645 \u062e\u0644\u0627\u0635 \u0623\u0646\u0641\u0633\u0647\u0645 \u062e\u0627\u0635\u0629\u060c \u0648\u0636\u064e\u0639\u064f\u0641\u064e\u062a\u0652 \u0639\u0632\u064a\u0645\u062a\u0647\u0645 \u0648\u0634\u064f\u063a\u0650\u0644\u0648\u0627 \u0628\u0623\u0646\u0641\u0633\u0647\u0645\u060c \u0648\u0623\u0633\u0627\u0624\u0648\u0627 \u0627\u0644\u0638\u0646 \u0628\u0631\u0628\u0647\u0645 \u0648\u0628\u062f\u064a\u0646\u0647 \u0648\u0628\u0646\u0628\u064a\u0647\u060c \u0648\u0638\u0646\u0648\u0627 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u064f\u062a\u0650\u0645\u0651\u064f \u0623\u0645\u0631 \u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0623\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0644\u0646 \u062a\u0642\u0648\u0645 \u0644\u0647 \u0642\u0627\u0626\u0645\u0629\u060c \u0648\u0644\u0630\u0644\u0643 \u062a\u0631\u0627\u0647\u0645 \u0646\u0627\u062f\u0645\u064a\u0646 \u0639\u0644\u0649 \u062e\u0631\u0648\u062c\u0647\u0645\u060c \u064a\u0642\u0648\u0644 \u0628\u0639\u0636\u0647\u0645 \u0644\u0628\u0639\u0636: \u0647\u0644 \u0643\u0627\u0646 \u0644\u0646\u0627 \u0645\u0646 \u0627\u062e\u062a\u064a\u0627\u0631 \u0641\u064a \u0627\u0644\u062e\u0631\u0648\u062c \u0644\u0644\u0642\u062a\u0627\u0644\u061f \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0625\u0646 \u0627\u0644\u0623\u0645\u0631 \u0643\u0644\u0651\u064e\u0647 \u0644\u0644\u0647\u060c \u0641\u0647\u0648 \u0627\u0644\u0630\u064a \u0642\u062f\u0651\u064e\u0631 \u062e\u0631\u0648\u062c\u0643\u0645 \u0648\u0645\u0627 \u062d\u062f\u062b \u0644\u0643\u0645\u060c \u0648\u0647\u0645 \u064a\u064f\u062e\u0652\u0641\u0648\u0646 \u0641\u064a \u0623\u0646\u0641\u0633\u0647\u0645 \u0645\u0627 \u0644\u0627 \u064a\u0638\u0647\u0631\u0648\u0646\u0647 \u0644\u0643 \u0645\u0646 \u0627\u0644\u062d\u0633\u0631\u0629 \u0639\u0644\u0649 \u062e\u0631\u0648\u062c\u0647\u0645 \u0644\u0644\u0642\u062a\u0627\u0644\u060c \u064a\u0642\u0648\u0644\u0648\u0646: \u0644\u0648 \u0643\u0627\u0646 \u0644\u0646\u0627 \u0623\u062f\u0646\u0649 \u0627\u062e\u062a\u064a\u0627\u0631 \u0645\u0627 \u0642\u064f\u062a\u0650\u0644\u0646\u0627 \u0647\u0627\u0647\u0646\u0627. \u0642\u0644 \u0644\u0647\u0645: \u0625\u0646 \u0627\u0644\u0622\u062c\u0627\u0644 \u0628\u064a\u062f \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0648 \u0643\u0646\u062a\u0645 \u0641\u064a \u0628\u064a\u0648\u062a\u0643\u0645\u060c \u0648\u0642\u062f\u0651\u064e\u0631 \u0627\u0644\u0644\u0647 \u0623\u0646\u0643\u0645 \u062a\u0645\u0648\u062a\u0648\u0646\u060c \u0644\u062e\u0631\u062c \u0627\u0644\u0630\u064a\u0646 \u0643\u062a\u0628 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0645\u0648\u062a \u0625\u0644\u0649 \u062d\u064a\u062b \u064a\u064f\u0642\u0652\u062a\u0644\u0648\u0646\u060c \u0648\u0645\u0627 \u062c\u0639\u0644 \u0627\u0644\u0644\u0647 \u0630\u0644\u0643 \u0625\u0644\u0627 \u0644\u064a\u062e\u062a\u0628\u0631 \u0645\u0627 \u0641\u064a \u0635\u062f\u0648\u0631\u0643\u0645 \u0645\u0646 \u0627\u0644\u0634\u0643 \u0648\u0627\u0644\u0646\u0641\u0627\u0642\u060c \u0648\u0644\u064a\u0645\u064a\u0632 \u0627\u0644\u062e\u0628\u064a\u062b \u0645\u0646 \u0627\u0644\u0637\u064a\u0628\u060c \u0648\u064a\u0638\u0647\u0631 \u0623\u0645\u0631 \u0627\u0644\u0645\u0624\u0645\u0646 \u0645\u0646 \u0627\u0644\u0645\u0646\u0627\u0641\u0642 \u0644\u0644\u0646\u0627\u0633 \u0641\u064a \u0627\u0644\u0623\u0642\u0648\u0627\u0644 \u0648\u0627\u0644\u0623\u0641\u0639\u0627\u0644. \u0648\u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0645 \u0628\u0645\u0627 \u0641\u064a \u0635\u062f\u0648\u0631 \u062e\u0644\u0642\u0647\u060c \u0644\u0627 \u064a\u062e\u0641\u0649 \u0639\u0644\u064a\u0647 \u0634\u064a\u0621 \u0645\u0646 \u0623\u0645\u0648\u0631\u0647\u0645.","3:155":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u0641\u0631\u0651\u064f\u0648\u0627 \u0645\u0646\u0643\u0645 -\u064a\u0627 \u0623\u0635\u062d\u0627\u0628 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645- \u0645\u062d\u0645\u062f \u0639\u0646 \u0627\u0644\u0642\u062a\u0627\u0644 \u064a\u0648\u0645 \u0627\u0644\u062a\u0642\u0649 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0648\u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0641\u064a \u063a\u0632\u0648\u0629 \xab\u0623\u064f\u062d\u062f\xbb \u060c \u0625\u0646\u0645\u0627 \u0623\u0648\u0642\u0639\u0647\u0645 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0630\u0646\u0628 \u0628\u0628\u0639\u0636 \u0645\u0627 \u0639\u0645\u0644\u0648\u0627 \u0645\u0646 \u0627\u0644\u0630\u0646\u0648\u0628\u060c \u0648\u0644\u0642\u062f \u062a\u062c\u0627\u0648\u0632 \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645 \u0641\u0644\u0645 \u064a\u0639\u0627\u0642\u0628\u0647\u0645. \u0625\u0646 \u0627\u0644\u0644\u0647 \u063a\u0641\u0648\u0631 \u0644\u0644\u0645\u0630\u0646\u0628\u064a\u0646 \u0627\u0644\u062a\u0627\u0626\u0628\u064a\u0646\u060c \u062d\u0644\u064a\u0645 \u0644\u0627 \u064a\u0639\u0627\u062c\u0644 \u0645\u0646 \u0639\u0635\u0627\u0647 \u0628\u0627\u0644\u0639\u0642\u0648\u0628\u0629.","3:156":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647\u060c \u0644\u0627 \u062a\u064f\u0634\u0627\u0628\u0647\u0648\u0627 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0644\u0627 \u064a\u0624\u0645\u0646\u0648\u0646 \u0628\u0631\u0628\u0647\u0645\u060c \u0641\u0647\u0645 \u064a\u0642\u0648\u0644\u0648\u0646 \u0644\u0625\u062e\u0648\u0627\u0646\u0647\u0645 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0643\u0641\u0631 \u0625\u0630\u0627 \u062e\u0631\u062c\u0648\u0627 \u064a\u0628\u062d\u062b\u0648\u0646 \u0641\u064a \u0623\u0631\u0636 \u0627\u0644\u0644\u0647 \u0639\u0646 \u0645\u0639\u0627\u0634\u0647\u0645 \u0623\u0648 \u0643\u0627\u0646\u0648\u0627 \u0645\u0639 \u0627\u0644\u063a\u0632\u0627\u0629 \u0627\u0644\u0645\u0642\u0627\u062a\u0644\u064a\u0646 \u0641\u0645\u0627\u062a\u0648\u0627 \u0623\u0648 \u0642\u064f\u062a\u0650\u0644\u0648\u0627: \u0644\u0648 \u0644\u0645 \u064a\u062e\u0631\u062c \u0647\u0624\u0644\u0627\u0621 \u0648\u0644\u0645 \u064a\u0642\u0627\u062a\u0644\u0648\u0627 \u0648\u0623\u0642\u0627\u0645\u0648\u0627 \u0645\u0639\u0646\u0627 \u0645\u0627 \u0645\u0627\u062a\u0648\u0627 \u0648\u0645\u0627 \u0642\u064f\u062a\u0644\u0648\u0627. \u0648\u0647\u0630\u0627 \u0627\u0644\u0642\u0648\u0644 \u064a\u0632\u064a\u062f\u0647\u0645 \u0623\u0644\u0645\u064b\u0627 \u0648\u062d\u0632\u0646\u064b\u0627 \u0648\u062d\u0633\u0631\u0629 \u062a\u0633\u062a\u0642\u0631 \u0641\u064a \u0642\u0644\u0648\u0628\u0647\u0645\u060c \u0623\u0645\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0641\u0625\u0646\u0647\u0645 \u064a\u0639\u0644\u0645\u0648\u0646 \u0623\u0646 \u0630\u0644\u0643 \u0628\u0642\u062f\u0631 \u0627\u0644\u0644\u0647 \u0641\u064a\u0647\u062f\u064a \u0627\u0644\u0644\u0647 \u0642\u0644\u0648\u0628\u0647\u0645\u060c \u0648\u064a\u062e\u0641\u0641 \u0639\u0646\u0647\u0645 \u0627\u0644\u0645\u0635\u064a\u0628\u0629\u060c \u0648\u0627\u0644\u0644\u0647 \u064a\u062d\u064a\u064a \u0645\u064e\u0646 \u0642\u062f\u0651\u064e\u0631 \u0644\u0647 \u0627\u0644\u062d\u064a\u0627\u0629 -\u0648\u0625\u0646 \u0643\u0627\u0646 \u0645\u0633\u0627\u0641\u0631\u064b\u0627 \u0623\u0648 \u063a\u0627\u0632\u064a\u064b\u0627- \u0648\u064a\u0645\u064a\u062a \u0645\u064e\u0646\u0650 \u0627\u0646\u062a\u0647\u0649 \u0623\u062c\u0644\u0647 -\u0648\u0625\u0646 \u0643\u0627\u0646 \u0645\u0642\u064a\u0645\u064b\u0627- \u0648\u0627\u0644\u0644\u0647 \u0628\u0643\u0644 \u0645\u0627 \u062a\u0639\u0645\u0644\u0648\u0646\u0647 \u0628\u0635\u064a\u0631\u060c \u0641\u064a\u062c\u0627\u0632\u064a\u0643\u0645 \u0628\u0647.","3:157":"\u0648\u0644\u0626\u0646 \u0642\u064f\u062a\u0650\u0644\u062a\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0648\u0623\u0646\u062a\u0645 \u062a\u062c\u0627\u0647\u062f\u0648\u0646 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0623\u0648 \u0645\u062a\u0645 \u0641\u064a \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0642\u062a\u0627\u0644\u060c \u0644\u064a\u063a\u0641\u0631\u0646 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0630\u0646\u0648\u0628\u0643\u0645\u060c \u0648\u0644\u064a\u0631\u062d\u0645\u0646\u0643\u0645 \u0631\u062d\u0645\u0629 \u0645\u0646 \u0639\u0646\u062f\u0647\u060c \u0641\u062a\u0641\u0648\u0632\u0648\u0646 \u0628\u062c\u0646\u0627\u062a \u0627\u0644\u0646\u0639\u064a\u0645\u060c \u0648\u0630\u0644\u0643 \u062e\u064a\u0631 \u0645\u0646 \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0645\u0627 \u064a\u062c\u0645\u0639\u0647 \u0623\u0647\u0644\u0647\u0627.","3:158":"\u0648\u0644\u0626\u0646 \u0627\u0646\u0642\u0636\u062a \u0622\u062c\u0627\u0644\u0643\u0645 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0641\u0645\u062a\u0645 \u0639\u0644\u0649 \u0641\u064f\u0631\u064f\u0634\u0643\u0645\u060c \u0623\u0648 \u0642\u062a\u0644\u062a\u0645 \u0641\u064a \u0633\u0627\u062d\u0629 \u0627\u0644\u0642\u062a\u0627\u0644\u060c \u0644\u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u062a\u064f\u062d\u0634\u0631\u0648\u0646\u060c \u0641\u064a\u062c\u0627\u0632\u064a\u0643\u0645 \u0628\u0623\u0639\u0645\u0627\u0644\u0643\u0645.","3:159":"\u0641\u0628\u0631\u062d\u0645\u0629 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0644\u0643 \u0648\u0644\u0623\u0635\u062d\u0627\u0628\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0645\u0646\u0651\u064e \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643 \u0641\u0643\u0646\u062a \u0631\u0641\u064a\u0642\u064b\u0627 \u0628\u0647\u0645\u060c \u0648\u0644\u0648 \u0643\u0646\u062a \u0633\u064a\u0651\u0650\u0626 \u0627\u0644\u062e\u064f\u0644\u0642 \u0642\u0627\u0633\u064a \u0627\u0644\u0642\u0644\u0628\u060c \u0644\u0627\u0646\u0652\u0635\u064e\u0631\u064e\u0641\u064e \u0623\u0635\u062d\u0627\u0628\u0643 \u0645\u0646 \u062d\u0648\u0644\u0643\u060c \u0641\u0644\u0627 \u062a\u0624\u0627\u062e\u0630\u0647\u0645 \u0628\u0645\u0627 \u0643\u0627\u0646 \u0645\u0646\u0647\u0645 \u0641\u064a \u063a\u0632\u0648\u0629 \xab\u0623\u064f\u062d\u062f\xbb \u060c \u0648\u0627\u0633\u0623\u0644 \u0627\u0644\u0644\u0647 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0623\u0646 \u064a\u063a\u0641\u0631 \u0644\u0647\u0645\u060c \u0648\u0634\u0627\u0648\u0631\u0647\u0645 \u0641\u064a \u0627\u0644\u0623\u0645\u0648\u0631 \u0627\u0644\u062a\u064a \u062a\u062d\u062a\u0627\u062c \u0625\u0644\u0649 \u0645\u0634\u0648\u0631\u0629\u060c \u0641\u0625\u0630\u0627 \u0639\u0632\u0645\u062a \u0639\u0644\u0649 \u0623\u0645\u0631 \u0645\u0646 \u0627\u0644\u0623\u0645\u0648\u0631 -\u0628\u0639\u062f \u0627\u0644\u0627\u0633\u062a\u0634\u0627\u0631\u0629- \u0641\u0623\u064e\u0645\u0652\u0636\u0650\u0647 \u0645\u0639\u062a\u0645\u062f\u064b\u0627 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647\u060c \u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u062d\u0628 \u0627\u0644\u0645\u062a\u0648\u0643\u0644\u064a\u0646 \u0639\u0644\u064a\u0647.","3:160":"\u0625\u0646 \u064a\u0645\u062f\u062f\u0643\u0645 \u0627\u0644\u0644\u0647 \u0628\u0646\u0635\u0631\u0647 \u0648\u0645\u0639\u0648\u0646\u062a\u0647 \u0641\u0644\u0627 \u0623\u062d\u062f \u064a\u0633\u062a\u0637\u064a\u0639 \u0623\u0646 \u064a\u063a\u0644\u0628\u0643\u0645\u060c \u0648\u0625\u0646 \u064a\u062e\u0630\u0644\u0643\u0645 \u0641\u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u0630\u064a \u064a\u0633\u062a\u0637\u064a\u0639 \u0623\u0646 \u064a\u0646\u0635\u0631\u0643\u0645 \u0645\u0646 \u0628\u0639\u062f \u062e\u0630\u0644\u0627\u0646\u0647 \u0644\u0643\u0645\u061f \u0648\u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0641\u0644\u064a\u062a\u0648\u0643\u0644 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646.","3:161":"\u0648\u0645\u0627 \u0643\u0627\u0646 \u0644\u0646\u0628\u064a\u0651\u064d \u0623\u0646 \u064a\u064e\u062e\u064f\u0648\u0646\u064e \u0623\u0635\u062d\u0627\u0628\u0647 \u0628\u0623\u0646 \u064a\u0623\u062e\u0630 \u0634\u064a\u0626\u064b\u0627 \u0645\u0646 \u0627\u0644\u063a\u0646\u064a\u0645\u0629 \u063a\u064a\u0631 \u0645\u0627 \u0627\u062e\u062a\u0635\u0647 \u0627\u0644\u0644\u0647 \u0628\u0647\u060c \u0648\u0645\u0646 \u064a\u0641\u0639\u0644 \u0630\u0644\u0643 \u0645\u0646\u0643\u0645 \u064a\u0623\u062a \u0628\u0645\u0627 \u0623\u062e\u0630\u0647 \u062d\u0627\u0645\u0644\u0627 \u0644\u0647 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629; \u0644\u064a\u064f\u0641\u0636\u064e\u062d \u0628\u0647 \u0641\u064a \u0627\u0644\u0645\u0648\u0642\u0641 \u0627\u0644\u0645\u0634\u0647\u0648\u062f\u060c \u062b\u0645 \u062a\u064f\u0639\u0637\u0649 \u0643\u0644 \u0646\u0641\u0633 \u062c\u0632\u0627\u0621\u064e \u0645\u0627 \u0643\u0633\u0628\u062a \u0648\u0627\u0641\u064a\u064b\u0627 \u063a\u064a\u0631 \u0645\u0646\u0642\u0648\u0635 \u062f\u0648\u0646 \u0638\u0644\u0645.","3:162":"\u0644\u0627 \u064a\u0633\u062a\u0648\u064a \u0645\u0646 \u0643\u0627\u0646 \u0642\u0635\u062f\u0647 \u0631\u0636\u0648\u0627\u0646 \u0627\u0644\u0644\u0647 \u0648\u0645\u0646 \u0647\u0648 \u0645\u064f\u0643\u0650\u0628\u064c \u0639\u0644\u0649 \u0627\u0644\u0645\u0639\u0627\u0635\u064a\u060c \u0645\u0633\u062e\u0637 \u0644\u0631\u0628\u0647\u060c \u0641\u0627\u0633\u062a\u062d\u0642 \u0628\u0630\u0644\u0643 \u0633\u0643\u0646 \u062c\u0647\u0646\u0645\u060c \u0648\u0628\u0626\u0633 \u0627\u0644\u0645\u0635\u064a\u0631.","3:163":"\u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u062c\u0646\u0629 \u0627\u0644\u0645\u062a\u0628\u0639\u0648\u0646 \u0644\u0645\u0627 \u064a\u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0645\u062a\u0641\u0627\u0648\u062a\u0648\u0646 \u0641\u064a \u0627\u0644\u062f\u0631\u062c\u0627\u062a\u060c \u0648\u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0646\u0627\u0631 \u0627\u0644\u0645\u062a\u0628\u0639\u0648\u0646 \u0644\u0645\u0627 \u064a\u0633\u062e\u0637 \u0627\u0644\u0644\u0647 \u0645\u062a\u0641\u0627\u0648\u062a\u0648\u0646 \u0641\u064a \u0627\u0644\u062f\u0631\u0643\u0627\u062a\u060c \u0644\u0627 \u064a\u0633\u062a\u0648\u0648\u0646. \u0648\u0627\u0644\u0644\u0647 \u0628\u0635\u064a\u0631 \u0628\u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0644\u0627 \u064a\u062e\u0641\u0649 \u0639\u0644\u064a\u0647 \u0645\u0646\u0647\u0627 \u0634\u064a\u0621.","3:164":"\u0644\u0642\u062f \u0623\u0646\u0639\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0645\u0646 \u0627\u0644\u0639\u0631\u0628; \u0625\u0630 \u0628\u0639\u062b \u0641\u064a\u0647\u0645 \u0631\u0633\u0648\u0644\u0627 \u0645\u0646 \u0623\u0646\u0641\u0633\u0647\u0645\u060c \u064a\u062a\u0644\u0648 \u0639\u0644\u064a\u0647\u0645 \u0622\u064a\u0627\u062a \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0648\u064a\u0637\u0647\u0631\u0647\u0645 \u0645\u0646 \u0627\u0644\u0634\u0631\u0643 \u0648\u0627\u0644\u0623\u062e\u0644\u0627\u0642 \u0627\u0644\u0641\u0627\u0633\u062f\u0629\u060c \u0648\u064a\u0639\u0644\u0645\u0647\u0645 \u0627\u0644\u0642\u0631\u0622\u0646 \u0648\u0627\u0644\u0633\u0646\u0629\u060c \u0648\u0625\u0646 \u0643\u0627\u0646\u0648\u0627 \u0645\u0646 \u0642\u0628\u0644 \u0647\u0630\u0627 \u0627\u0644\u0631\u0633\u0648\u0644 \u0644\u0641\u064a \u063a\u064a\u0651\u064d \u0648\u062c\u0647\u0644 \u0638\u0627\u0647\u0631.","3:165":"\u0623\u0648 \u0644\u0645\u0627 \u0623\u0635\u0627\u0628\u062a\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0645\u0635\u064a\u0628\u0629\u060c \u0648\u0647\u064a \u0645\u0627 \u0623\u064f\u0635\u064a\u0628 \u0645\u0646\u0643\u0645 \u064a\u0648\u0645 \xab\u0623\u064f\u062d\u062f\xbb \u0642\u062f \u0623\u0635\u0628\u062a\u0645 \u0645\u062b\u0644\u064a\u0647\u0627 \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0641\u064a \u064a\u0648\u0645 \xab\u0628\u062f\u0652\u0631\xbb \u060c \u0642\u0644\u062a\u0645 \u0645\u062a\u0639\u062c\u0628\u064a\u0646: \u0643\u064a\u0641 \u064a\u0643\u0648\u0646 \u0647\u0630\u0627 \u0648\u0646\u062d\u0646 \u0645\u0633\u0644\u0645\u0648\u0646 \u0648\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0641\u064a\u0646\u0627 \u0648\u0647\u0624\u0644\u0627\u0621 \u0645\u0634\u0631\u0643\u0648\u0646\u061f \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a-: \u0647\u0630\u0627 \u0627\u0644\u0630\u064a \u0623\u0635\u0627\u0628\u0643\u0645 \u0647\u0648 \u0645\u0646 \u0639\u0646\u062f \u0623\u0646\u0641\u0633\u0643\u0645 \u0628\u0633\u0628\u0628 \u0645\u062e\u0627\u0644\u0641\u062a\u0643\u0645 \u0623\u0645\u0652\u0631\u064e \u0631\u0633\u0648\u0644\u0643\u0645 \u0648\u0625\u0642\u0628\u0627\u0644\u0643\u0645 \u0639\u0644\u0649 \u062c\u0645\u0639 \u0627\u0644\u063a\u0646\u0627\u0626\u0645. \u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u0641\u0639\u0644 \u0645\u0627 \u064a\u0634\u0627\u0621 \u0648\u064a\u062d\u0643\u0645 \u0645\u0627 \u064a\u0631\u064a\u062f\u060c \u0644\u0627 \u0645\u0639\u0642\u0651\u0650\u0628 \u0644\u062d\u0643\u0645\u0647.","3:166":"\u0648\u0645\u0627 \u0648\u0642\u0639 \u0628\u0643\u0645 \u0645\u0650\u0646 \u062c\u0631\u0627\u062d \u0623\u0648 \u0642\u062a\u0644 \u0641\u064a \u063a\u0632\u0648\u0629 \xab\u0623\u064f\u062d\u062f\xbb \u064a\u0648\u0645 \u0627\u0644\u062a\u0642\u0649 \u062c\u064e\u0645\u0652\u0639\u064f \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0648\u062c\u0645\u0639 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0641\u0643\u0627\u0646 \u0627\u0644\u0646\u0635\u0631 \u0644\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0623\u0648\u0644\u0627 \u062b\u0645 \u0644\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u062b\u0627\u0646\u064a\u064b\u0627\u060c \u0641\u0630\u0644\u0643 \u0643\u0644\u0647 \u0628\u0642\u0636\u0627\u0621 \u0627\u0644\u0644\u0647 \u0648\u0642\u062f\u0631\u0647\u060c \u0648\u0644\u064a\u0638\u0647\u0631 \u0645\u0627 \u0639\u0644\u0645\u0647 \u0627\u0644\u0644\u0647 \u0641\u064a \u0627\u0644\u0623\u0632\u0644\u061b \u0644\u064a\u0645\u064a\u0632 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0627\u0644\u0635\u0627\u062f\u0642\u064a\u0646 \u0645\u0646\u0643\u0645.","3:167":"\u0648\u0644\u064a\u0639\u0644\u0645 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0643\u0634\u0641 \u0627\u0644\u0644\u0647 \u0645\u0627 \u0641\u064a \u0642\u0644\u0648\u0628\u0647\u0645 \u062d\u064a\u0646 \u0642\u0627\u0644 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0644\u0647\u0645: \u062a\u0639\u0627\u0644\u0648\u0627 \u0642\u0627\u062a\u0644\u0648\u0627 \u0645\u0639\u0646\u0627 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647\u060c \u0623\u0648 \u0643\u0648\u0646\u0648\u0627 \u0639\u0648\u0646\u064b\u0627 \u0644\u0646\u0627 \u0628\u062a\u0643\u062b\u064a\u0631\u0643\u0645 \u0633\u0648\u0627\u062f\u0646\u0627\u060c \u0641\u0642\u0627\u0644\u0648\u0627: \u0644\u0648 \u0646\u0639\u0644\u0645 \u0623\u0646\u0643\u0645 \u062a\u0642\u0627\u062a\u0644\u0648\u0646 \u0623\u062d\u062f\u064b\u0627 \u0644\u0643\u0646\u0627 \u0645\u0639\u0643\u0645 \u0639\u0644\u064a\u0647\u0645\u060c \u0647\u0645 \u0644\u0644\u0643\u0641\u0631 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u064a\u0648\u0645 \u0623\u0642\u0631\u0628 \u0645\u0646\u0647\u0645 \u0644\u0644\u0625\u064a\u0645\u0627\u0646; \u0644\u0623\u0646\u0647\u0645 \u064a\u0642\u0648\u0644\u0648\u0646 \u0628\u0623\u0641\u0648\u0627\u0647\u0647\u0645 \u0645\u0627 \u0644\u064a\u0633 \u0641\u064a \u0642\u0644\u0648\u0628\u0647\u0645. \u0648\u0627\u0644\u0644\u0647 \u0623\u0639\u0644\u0645 \u0628\u0645\u0627 \u064a\u064f\u062e\u0641\u0648\u0646 \u0641\u064a \u0635\u062f\u0648\u0631\u0647\u0645.","3:168":"\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u0642\u0639\u062f\u0648\u0627 \u0648\u0642\u0627\u0644\u0648\u0627 \u0644\u0625\u062e\u0648\u0627\u0646\u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u0623\u0635\u064a\u0628\u0648\u0627 \u0645\u0639 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0641\u064a \u062d\u0631\u0628\u0647\u0645 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u064a\u0648\u0645 \xab\u0623\u064f\u062d\u062f\xbb : \u0644\u0648 \u0623\u0637\u0627\u0639\u064e\u0646\u0627 \u0647\u0624\u0644\u0627\u0621 \u0645\u0627 \u0642\u062a\u0644\u0648\u0627. \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0641\u0627\u062f\u0641\u0639\u0648\u0627 \u0639\u0646 \u0623\u0646\u0641\u0633\u0643\u0645 \u0627\u0644\u0645\u0648\u062a \u0625\u0646 \u0643\u0646\u062a\u0645 \u0635\u0627\u062f\u0642\u064a\u0646 \u0641\u064a \u062f\u0639\u0648\u0627\u0643\u0645 \u0623\u0646\u0647\u0645 \u0644\u0648 \u0623\u0637\u0627\u0639\u0648\u0643\u0645 \u0645\u0627 \u0642\u062a\u0644\u0648\u0627\u060c \u0648\u0623\u0646\u0643\u0645 \u0642\u062f \u0646\u062c\u0648\u062a\u0645 \u0645\u0646\u0647 \u0628\u0642\u0639\u0648\u062f\u0643\u0645 \u0639\u0646 \u0627\u0644\u0642\u062a\u0627\u0644.","3:169":"\u0648\u0644\u0627 \u062a\u0638\u0646\u0651\u064e\u0646\u0651\u064e -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0623\u0646 \u0627\u0644\u0630\u064a\u0646 \u0642\u062a\u0644\u0648\u0627 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0623\u0645\u0648\u0627\u062a \u0644\u0627 \u064a\u064f\u062d\u0650\u0633\u0651\u064f\u0648\u0646 \u0634\u064a\u0626\u064b\u0627\u060c \u0628\u0644 \u0647\u0645 \u0623\u062d\u064a\u0627\u0621 \u062d\u064a\u0627\u0629 \u0628\u0631\u0632\u062e\u064a\u0629 \u0641\u064a \u062c\u0648\u0627\u0631 \u0631\u0628\u0647\u0645 \u0627\u0644\u0630\u064a \u062c\u0627\u0647\u062f\u0648\u0627 \u0645\u0646 \u0623\u062c\u0644\u0647\u060c \u0648\u0645\u0627\u062a\u0648\u0627 \u0641\u064a \u0633\u0628\u064a\u0644\u0647\u060c \u064a\u062c\u0631\u064a \u0639\u0644\u064a\u0647\u0645 \u0631\u0632\u0642\u0647\u0645 \u0641\u064a \u0627\u0644\u062c\u0646\u0629\u060c \u0648\u064a\u064f\u0646\u0639\u0651\u064e\u0645\u0648\u0646.","3:170":"\u0644\u0642\u062f \u0639\u064e\u0645\u0651\u064e\u062a\u0647\u0645 \u0627\u0644\u0633\u0639\u0627\u062f\u0629 \u062d\u064a\u0646 \u0645\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645\u060c \u0641\u0623\u0639\u0637\u0627\u0647\u0645 \u0645\u0650\u0646 \u0639\u0638\u064a\u0645 \u062c\u0648\u062f\u0647 \u0648\u0648\u0627\u0633\u0639 \u0643\u0631\u0645\u0647 \u0645\u0646 \u0627\u0644\u0646\u0639\u064a\u0645 \u0648\u0627\u0644\u0631\u0636\u0627 \u0645\u0627 \u062a\u064e\u0642\u064e\u0631\u0651\u064f \u0628\u0647 \u0623\u0639\u064a\u0646\u0647\u0645\u060c \u0648\u0647\u0645 \u064a\u0641\u0631\u062d\u0648\u0646 \u0628\u0625\u062e\u0648\u0627\u0646\u0647\u0645 \u0627\u0644\u0645\u062c\u0627\u0647\u062f\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0641\u0627\u0631\u0642\u0648\u0647\u0645 \u0648\u0647\u0645 \u0623\u062d\u064a\u0627\u0621; \u0644\u064a\u0641\u0648\u0632\u0648\u0627 \u0643\u0645\u0627 \u0641\u0627\u0632\u0648\u0627\u060c \u0644\u0650\u0639\u0650\u0644\u0652\u0645\u0650\u0647\u0645 \u0623\u0646\u0647\u0645 \u0633\u064a\u0646\u0627\u0644\u0648\u0646 \u0645\u0646 \u0627\u0644\u062e\u064a\u0631 \u0627\u0644\u0630\u064a \u0646\u0627\u0644\u0648\u0647\u060c \u0625\u0630\u0627 \u0627\u0633\u062a\u0634\u0647\u062f\u0648\u0627 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0645\u062e\u0644\u0635\u064a\u0646 \u0644\u0647\u060c \u0648\u0623\u0646 \u0644\u0627 \u062e\u0648\u0641 \u0639\u0644\u064a\u0647\u0645 \u0641\u064a\u0645\u0627 \u064a\u0633\u062a\u0642\u0628\u0644\u0648\u0646 \u0645\u0646 \u0623\u0645\u0648\u0631 \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u0644\u0627 \u0647\u0645 \u064a\u062d\u0632\u0646\u0648\u0646 \u0639\u0644\u0649 \u0645\u0627 \u0641\u0627\u062a\u0647\u0645 \u0645\u0646 \u062d\u0638\u0648\u0638 \u0627\u0644\u062f\u0646\u064a\u0627.","3:171":"\u0648\u0625\u0646\u0647\u0645 \u0641\u064a \u0641\u0631\u062d\u0629 \u063a\u0627\u0645\u0631\u0629 \u0628\u0645\u0627 \u0623\u064f\u0639\u0637\u0648\u0627 \u0645\u0646 \u0646\u0639\u0645 \u0627\u0644\u0644\u0647 \u0648\u062c\u0632\u064a\u0644 \u0639\u0637\u0627\u0626\u0647\u060c \u0648\u0623\u0646 \u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u0636\u064a\u0639 \u0623\u062c\u0631 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0628\u0647\u060c \u0628\u0644 \u064a\u0646\u0645\u0651\u0650\u064a\u0647 \u0648\u064a\u0632\u064a\u062f\u0647 \u0645\u0646 \u0641\u0636\u0644\u0647.","3:172":"\u0627\u0644\u0630\u064a\u0646 \u0644\u0628\u0651\u064f\u0648\u0627 \u0646\u062f\u0627\u0621 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u062e\u0631\u062c\u0648\u0627 \u0641\u064a \u0623\u0639\u0642\u0627\u0628 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0625\u0644\u0649 \xab\u062d\u0645\u0631\u0627\u0621 \u0627\u0644\u0623\u0633\u062f\xbb \u0628\u0639\u062f \u0647\u0632\u064a\u0645\u062a\u0647\u0645 \u0641\u064a \u063a\u0632\u0648\u0629 \xab\u0623\u064f\u062d\u062f\xbb \u0645\u0639 \u0645\u0627 \u0643\u0627\u0646 \u0628\u0647\u0645 \u0645\u0646 \u0622\u0644\u0627\u0645 \u0648\u062c\u0631\u0627\u062d\u060c \u0648\u0628\u0630\u0644\u0648\u0627 \u063a\u0627\u064a\u0629 \u062c\u0647\u062f\u0647\u0645\u060c \u0648\u0627\u0644\u062a\u0632\u0645\u0648\u0627 \u0628\u0647\u062f\u064a \u0646\u0628\u064a\u0647\u0645\u060c \u0644\u0644\u0645\u062d\u0633\u0646\u064a\u0646 \u0645\u0646\u0647\u0645 \u0648\u0627\u0644\u0645\u062a\u0642\u064a\u0646 \u062b\u0648\u0627\u0628 \u0639\u0638\u064a\u0645.","3:173":"\u0648\u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u0642\u0627\u0644 \u0644\u0647\u0645 \u0628\u0639\u0636 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0625\u0646 \u0623\u0628\u0627 \u0633\u0641\u064a\u0627\u0646 \u0648\u0645\u0646 \u0645\u0639\u0647 \u0642\u062f \u0623\u062c\u0645\u0639\u0648\u0627 \u0623\u0645\u0631\u0647\u0645 \u0639\u0644\u0649 \u0627\u0644\u0631\u062c\u0648\u0639 \u0625\u0644\u064a\u0643\u0645 \u0644\u0627\u0633\u062a\u0626\u0635\u0627\u0644\u0643\u0645\u060c \u0641\u0627\u062d\u0630\u0631\u0648\u0647\u0645 \u0648\u0627\u062a\u0642\u0648\u0627 \u0644\u0642\u0627\u0621\u0647\u0645\u060c \u0641\u0625\u0646\u0647 \u0644\u0627 \u0637\u0627\u0642\u0629 \u0644\u0643\u0645 \u0628\u0647\u0645\u060c \u0641\u0632\u0627\u062f\u0647\u0645 \u0630\u0644\u0643 \u0627\u0644\u062a\u062e\u0648\u064a\u0641 \u064a\u0642\u064a\u0646\u064b\u0627 \u0648\u062a\u0635\u062f\u064a\u0642\u064b\u0627 \u0628\u0648\u0639\u062f \u0627\u0644\u0644\u0647 \u0644\u0647\u0645\u060c \u0648\u0644\u0645 \u064a\u064e\u062b\u0652\u0646\u0650\u0647\u0645 \u0630\u0644\u0643 \u0639\u0646 \u0639\u0632\u0645\u0647\u0645\u060c \u0641\u0633\u0627\u0631\u0648\u0627 \u0625\u0644\u0649 \u062d\u064a\u062b \u0634\u0627\u0621 \u0627\u0644\u0644\u0647\u060c \u0648\u0642\u0627\u0644\u0648\u0627: \u062d\u0633\u0628\u0646\u0627 \u0627\u0644\u0644\u0647 \u0623\u064a: \u0643\u0627\u0641\u064a\u0646\u0627\u060c \u0648\u0646\u0650\u0639\u0652\u0645 \u0627\u0644\u0648\u0643\u064a\u0644 \u0627\u0644\u0645\u0641\u0648\u0651\u064e\u0636 \u0625\u0644\u064a\u0647 \u062a\u062f\u0628\u064a\u0631 \u0639\u0628\u0627\u062f\u0647.","3:174":"\u0641\u0631\u062c\u0639\u0648\u0627 \u0645\u0646 \xab\u062d\u0645\u0631\u0627\u0621 \u0627\u0644\u0623\u0633\u062f\xbb \u0625\u0644\u0649 \xab\u0627\u0644\u0645\u062f\u064a\u0646\u0629\xbb \u0628\u0646\u0639\u0645\u0629 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0628\u0627\u0644\u062b\u0648\u0627\u0628 \u0627\u0644\u062c\u0632\u064a\u0644 \u0648\u0628\u0641\u0636\u0644 \u0645\u0646\u0647 \u0628\u0627\u0644\u0645\u0646\u0632\u0644\u0629 \u0627\u0644\u0639\u0627\u0644\u064a\u0629\u060c \u0648\u0642\u062f \u0627\u0632\u062f\u0627\u062f\u0648\u0627 \u0625\u064a\u0645\u0627\u0646\u064b\u0627 \u0648\u064a\u0642\u064a\u0646\u064b\u0627\u060c \u0648\u0623\u0630\u0644\u0648\u0627 \u0623\u0639\u062f\u0627\u0621 \u0627\u0644\u0644\u0647\u060c \u0648\u0641\u0627\u0632\u0648\u0627 \u0628\u0627\u0644\u0633\u0644\u0627\u0645\u0629 \u0645\u0646 \u0627\u0644\u0642\u062a\u0644 \u0648\u0627\u0644\u0642\u062a\u0627\u0644\u060c \u0648\u0627\u062a\u0628\u0639\u0648\u0627 \u0631\u0636\u0648\u0627\u0646 \u0627\u0644\u0644\u0647 \u0628\u0637\u0627\u0639\u062a\u0647\u0645 \u0644\u0647 \u0648\u0644\u0631\u0633\u0648\u0644\u0647. \u0648\u0627\u0644\u0644\u0647 \u0630\u0648 \u0625\u062d\u0633\u0627\u0646 \u0648\u0639\u0637\u0627\u0621 \u0643\u062b\u064a\u0631 \u0648\u0627\u0633\u0639 \u0639\u0644\u064a\u0647\u0645 \u0648\u0639\u0644\u0649 \u063a\u064a\u0631\u0647\u0645.","3:175":"\u0625\u0646\u0651\u064e\u0645\u0627 \u0627\u0644\u0645\u062b\u0628\u0651\u0650\u0637 \u0644\u0643\u0645 \u0641\u064a \u0630\u0644\u0643 \u0647\u0648 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u062c\u0627\u0621\u0643\u0645 \u064a\u062e\u0648\u0651\u0650\u0641\u0643\u0645 \u0623\u0646\u0635\u0627\u0631\u0647\u060c \u0641\u0644\u0627 \u062a\u062e\u0627\u0641\u0648\u0627 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646; \u0644\u0623\u0646\u0651\u0647\u0645 \u0636\u0639\u0627\u0641 \u0644\u0627 \u0646\u0627\u0635\u0631 \u0644\u0647\u0645\u060c \u0648\u062e\u0627\u0641\u0648\u0646\u064a \u0628\u0627\u0644\u0625\u0642\u0628\u0627\u0644 \u0639\u0644\u0649 \u0637\u0627\u0639\u062a\u064a \u0625\u0646 \u0643\u0646\u062a\u0645 \u0645\u0635\u062f\u0651\u0650\u0642\u064a\u0646 \u0628\u064a\u060c \u0648\u0645\u062a\u0628\u0639\u064a\u0646 \u0631\u0633\u0648\u0644\u064a.","3:176":"\u0644\u0627 \u064a\u064f\u062f\u0652\u062e\u0650\u0644 \u0627\u0644\u062d\u0632\u0646\u064e \u0625\u0644\u0649 \u0642\u0644\u0628\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0643\u0641\u0627\u0631\u064f \u0628\u0645\u0633\u0627\u0631\u0639\u062a\u0647\u0645 \u0641\u064a \u0627\u0644\u062c\u062d\u0648\u062f \u0648\u0627\u0644\u0636\u0644\u0627\u0644\u060c \u0625\u0646\u0647\u0645 \u0628\u0630\u0644\u0643 \u0644\u0646 \u064a\u0636\u0631\u0648\u0627 \u0627\u0644\u0644\u0647\u060c \u0625\u0646\u0645\u0627 \u064a\u0636\u0631\u0648\u0646 \u0623\u0646\u0641\u0633\u0647\u0645 \u0628\u062d\u0631\u0645\u0627\u0646\u0647\u0627 \u062d\u0644\u0627\u0648\u0629 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0639\u0638\u064a\u0645 \u0627\u0644\u062b\u0648\u0627\u0628\u060c \u064a\u0631\u064a\u062f \u0627\u0644\u0644\u0647 \u0623\u0644\u0627 \u064a\u062c\u0639\u0644 \u0644\u0647\u0645 \u062b\u0648\u0627\u0628\u064b\u0627 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629; \u0644\u0623\u0646\u0647\u0645 \u0627\u0646\u0635\u0631\u0641\u0648\u0627 \u0639\u0646 \u062f\u0639\u0648\u0629 \u0627\u0644\u062d\u0642\u060c \u0648\u0644\u0647\u0645 \u0639\u0630\u0627\u0628 \u0634\u062f\u064a\u062f.","3:177":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u0627\u0633\u062a\u0628\u062f\u0644\u0648\u0627 \u0627\u0644\u0643\u0641\u0631 \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0644\u0646 \u064a\u0636\u0631\u0648\u0627 \u0627\u0644\u0644\u0647 \u0634\u064a\u0626\u064b\u0627\u060c \u0628\u0644 \u0636\u0631\u0631 \u0641\u0650\u0639\u0652\u0644\u0650\u0647\u0645 \u064a\u0639\u0648\u062f \u0639\u0644\u0649 \u0623\u0646\u0641\u0633\u0647\u0645\u060c \u0648\u0644\u0647\u0645 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u0639\u0630\u0627\u0628 \u0645\u0648\u062c\u0639.","3:178":"\u0648\u0644\u0627 \u064a\u0638\u0646\u0646\u0651\u064e \u0627\u0644\u062c\u0627\u062d\u062f\u0648\u0646 \u0623\u0646\u0646\u0627 \u0625\u0630\u0627 \u0623\u064e\u0637\u064e\u0644\u0652\u0646\u0627 \u0623\u0639\u0645\u0627\u0631\u0647\u0645\u060c \u0648\u0645\u062a\u0639\u0646\u0627\u0647\u0645 \u0628\u0645\u064f\u062a\u0639 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0644\u0645 \u062a\u0624\u0627\u062e\u0630\u0647\u0645 \u0628\u0643\u0641\u0631\u0647\u0645 \u0648\u0630\u0646\u0648\u0628\u0647\u0645\u060c \u0623\u0646\u0647\u0645 \u0642\u062f \u0646\u0627\u0644\u0648\u0627 \u0628\u0630\u0644\u0643 \u062e\u064a\u0631\u064b\u0627 \u0644\u0623\u0646\u0641\u0633\u0647\u0645\u060c \u0625\u0646\u0645\u0627 \u0646\u0624\u062e\u0631 \u0639\u0630\u0627\u0628\u0647\u0645 \u0648\u0622\u062c\u0627\u0644\u0647\u0645; \u0644\u064a\u0632\u062f\u0627\u062f\u0648\u0627 \u0638\u0644\u0645\u064b\u0627 \u0648\u0637\u063a\u064a\u0627\u0646\u064b\u0627\u060c \u0648\u0644\u0647\u0645 \u0639\u0630\u0627\u0628 \u064a\u0647\u064a\u0646\u0647\u0645 \u0648\u064a\u0630\u0644\u0651\u064f\u0647\u0645.","3:179":"\u0645\u0627 \u0643\u0627\u0646 \u0627\u0644\u0644\u0647 \u0644\u064a\u064e\u062f\u064e\u0639\u064e\u0643\u0645 \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0635\u062f\u0642\u0648\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0627\u0644\u0639\u0627\u0645\u0644\u0648\u0646 \u0628\u0634\u0631\u0639\u0647 \u0639\u0644\u0649 \u0645\u0627 \u0623\u0646\u062a\u0645 \u0639\u0644\u064a\u0647 \u0645\u0646 \u0627\u0644\u062a\u0628\u0627\u0633 \u0627\u0644\u0645\u0624\u0645\u0646 \u0645\u0646\u0643\u0645 \u0628\u0627\u0644\u0645\u0646\u0627\u0641\u0642 \u062d\u062a\u0649 \u064a\u064e\u0645\u0650\u064a\u0632\u064e \u0627\u0644\u062e\u0628\u064a\u062b \u0645\u0646 \u0627\u0644\u0637\u064a\u0628\u060c \u0641\u064a\u064f\u0639\u0631\u0641 \u0627\u0644\u0645\u0646\u0627\u0641\u0642 \u0645\u0646 \u0627\u0644\u0645\u0624\u0645\u0646 \u0627\u0644\u0635\u0627\u062f\u0642. \u0648\u0645\u0627 \u0643\u0627\u0646 \u0645\u0650\u0646 \u062d\u0643\u0645\u0629 \u0627\u0644\u0644\u0647 \u0623\u0646 \u064a\u0637\u0644\u0639\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0639\u0644\u0649 \u0627\u0644\u063a\u064a\u0628 \u0627\u0644\u0630\u064a \u064a\u0639\u0644\u0645\u0647 \u0645\u0646 \u0639\u0628\u0627\u062f\u0647\u060c \u0641\u062a\u0639\u0631\u0641\u0648\u0627 \u0627\u0644\u0645\u0624\u0645\u0646 \u0645\u0646\u0647\u0645 \u0645\u0646 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u060c \u0648\u0644\u0643\u0646\u0647 \u064a\u0645\u064a\u0632\u0647\u0645 \u0628\u0627\u0644\u0645\u062d\u0646 \u0648\u0627\u0644\u0627\u0628\u062a\u0644\u0627\u0621\u060c \u063a\u064a\u0631 \u0623\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u064a\u0635\u0637\u0641\u064a \u0645\u0646 \u0631\u0633\u0644\u0647 \u0645\u064e\u0646 \u064a\u0634\u0627\u0621\u061b \u0644\u064a\u0637\u0644\u0639\u0647 \u0639\u0644\u0649 \u0628\u0639\u0636 \u0639\u0644\u0645 \u0627\u0644\u063a\u064a\u0628 \u0628\u0648\u062d\u064a \u0645\u0646\u0647\u060c \u0641\u0622\u0645\u0646\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0625\u0646 \u062a\u0624\u0645\u0646\u0648\u0627 \u0625\u064a\u0645\u0627\u0646\u064b\u0627 \u0635\u0627\u062f\u0642\u064b\u0627 \u0648\u062a\u062a\u0642\u0648\u0627 \u0631\u0628\u0643\u0645 \u0628\u0637\u0627\u0639\u062a\u0647\u060c \u0641\u0644\u0643\u0645 \u0623\u062c\u0631 \u0639\u0638\u064a\u0645 \u0639\u0646\u062f \u0627\u0644\u0644\u0647.","3:180":"\u0648\u0644\u0627 \u064a\u0638\u0646\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u0628\u062e\u0644\u0648\u0646 \u0628\u0645\u0627 \u0623\u0646\u0639\u0645 \u0627\u0644\u0644\u0647 \u0628\u0647 \u0639\u0644\u064a\u0647\u0645 \u062a\u0641\u0636\u0644\u0627 \u0645\u0646\u0647 \u0623\u0646 \u0647\u0630\u0627 \u0627\u0644\u0628\u062e\u0644 \u062e\u064a\u0631 \u0644\u0647\u0645\u060c \u0628\u0644 \u0647\u0648 \u0634\u0631\u0651\u064c \u0644\u0647\u0645; \u0644\u0623\u0646 \u0647\u0630\u0627 \u0627\u0644\u0645\u0627\u0644 \u0627\u0644\u0630\u064a \u062c\u0645\u0639\u0648\u0647 \u0633\u064a\u0643\u0648\u0646 \u0637\u0648\u0642\u064b\u0627 \u0645\u0646 \u0646\u0627\u0631 \u064a\u0648\u0636\u0639 \u0641\u064a \u0623\u0639\u0646\u0627\u0642\u0647\u0645 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629. \u0648\u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649 \u0647\u0648 \u0645\u0627\u0644\u0643 \u0627\u0644\u0645\u0644\u0643\u060c \u0648\u0647\u0648 \u0627\u0644\u0628\u0627\u0642\u064a \u0628\u0639\u062f \u0641\u0646\u0627\u0621 \u062c\u0645\u064a\u0639 \u062e\u0644\u0642\u0647\u060c \u0648\u0647\u0648 \u062e\u0628\u064a\u0631 \u0628\u0623\u0639\u0645\u0627\u0644\u0643\u0645 \u062c\u0645\u064a\u0639\u0647\u0627\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a \u0643\u0644\u0627 \u0639\u0644\u0649 \u0642\u062f\u0631 \u0627\u0633\u062a\u062d\u0642\u0627\u0642\u0647.","3:181":"\u0644\u0642\u062f \u0633\u0645\u0639 \u0627\u0644\u0644\u0647 \u0642\u0648\u0644 \u0627\u0644\u064a\u0647\u0648\u062f \u0627\u0644\u0630\u064a\u0646 \u0642\u0627\u0644\u0648\u0627: \u0625\u0646 \u0627\u0644\u0644\u0647 \u0641\u0642\u064a\u0631 \u0625\u0644\u064a\u0646\u0627 \u064a\u0637\u0644\u0628 \u0645\u0646\u0627 \u0623\u0646 \u0646\u0642\u0631\u0636\u0647 \u0623\u0645\u0648\u0627\u0644\u0627 \u0648\u0646\u062d\u0646 \u0623\u063a\u0646\u064a\u0627\u0621. \u0633\u0646\u0643\u062a\u0628 \u0647\u0630\u0627 \u0627\u0644\u0642\u0648\u0644 \u0627\u0644\u0630\u064a \u0642\u0627\u0644\u0648\u0647\u060c \u0648\u0633\u0646\u0643\u062a\u0628 \u0623\u0646\u0647\u0645 \u0631\u0627\u0636\u0648\u0646 \u0628\u0645\u0627 \u0643\u0627\u0646 \u0645\u0650\u0646 \u0642\u064e\u062a\u0652\u0644 \u0622\u0628\u0627\u0626\u0647\u0645 \u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0627\u0644\u0644\u0647 \u0638\u0644\u0645\u064b\u0627 \u0648\u0639\u062f\u0648\u0627\u0646\u064b\u0627\u060c \u0648\u0633\u0648\u0641 \u0646\u0624\u0627\u062e\u0630\u0647\u0645 \u0628\u0630\u0644\u0643 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u0646\u0642\u0648\u0644 \u0644\u0647\u0645 \u0648\u0647\u0645 \u0641\u064a \u0627\u0644\u0646\u0627\u0631 \u064a\u0639\u0630\u0628\u0648\u0646: \u0630\u0648\u0642\u0648\u0627 \u0639\u0630\u0627\u0628 \u0627\u0644\u0646\u0627\u0631 \u0627\u0644\u0645\u062d\u0631\u0642\u0629.","3:182":"\u0630\u0644\u0643 \u0627\u0644\u0639\u0630\u0627\u0628 \u0627\u0644\u0634\u062f\u064a\u062f \u0628\u0633\u0628\u0628 \u0645\u0627 \u0642\u062f\u0651\u064e\u0645\u062a\u0645\u0648\u0647 \u0641\u064a \u062d\u064a\u0627\u062a\u0643\u0645 \u0627\u0644\u062f\u0646\u064a\u0627 \u0645\u0646 \u0627\u0644\u0645\u0639\u0627\u0635\u064a \u0627\u0644\u0642\u0648\u0644\u064a\u0629 \u0648\u0627\u0644\u0641\u0639\u0644\u064a\u0629 \u0648\u0627\u0644\u0627\u0639\u062a\u0642\u0627\u062f\u064a\u0629\u060c \u0648\u0623\u0646 \u0627\u0644\u0644\u0647 \u0644\u064a\u0633 \u0628\u0638\u0644\u0627\u0645 \u0644\u0644\u0639\u0628\u0628\u062f.","3:183":"\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u064a\u0647\u0648\u062f \u062d\u064a\u0646 \u062f\u064f\u0639\u064f\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0642\u0627\u0644\u0648\u0627: \u0625\u0646 \u0627\u0644\u0644\u0647 \u0623\u0648\u0635\u0627\u0646\u0627 \u0641\u064a \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0623\u0644\u0627 \u0646\u0635\u062f\u0651\u0650\u0642 \u0645\u064e\u0646 \u062c\u0627\u0621\u0646\u0627 \u064a\u0642\u0648\u0644: \u0625\u0646\u0647 \u0631\u0633\u0648\u0644 \u0645\u0646 \u0627\u0644\u0644\u0647\u060c \u062d\u062a\u0649 \u064a\u0623\u062a\u064a\u0646\u0627 \u0628\u0635\u062f\u0642\u0629 \u064a\u062a\u0642\u0631\u0628 \u0628\u0647\u0627 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0641\u062a\u0646\u0632\u0644 \u0646\u0627\u0631 \u0645\u0646 \u0627\u0644\u0633\u0645\u0627\u0621 \u0641\u062a\u062d\u0631\u0642\u0647\u0627. \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0623\u0646\u062a\u0645 \u0643\u0627\u0630\u0628\u0648\u0646 \u0641\u064a \u0642\u0648\u0644\u0643\u0645; \u0644\u0623\u0646\u0647 \u0642\u062f \u062c\u0627\u0621 \u0622\u0628\u0627\u0621\u0643\u0645 \u0631\u0633\u0644\u064c \u0645\u0646 \u0642\u0650\u0628\u0644\u064a \u0628\u0627\u0644\u0645\u0639\u062c\u0632\u0627\u062a \u0648\u0627\u0644\u062f\u0644\u0627\u0626\u0644 \u0639\u0644\u0649 \u0635\u062f\u0642\u0647\u0645\u060c \u0648\u0628\u0627\u0644\u0630\u064a \u0642\u0644\u062a\u0645 \u0645\u0646 \u0627\u0644\u0625\u062a\u064a\u0627\u0646 \u0628\u0627\u0644\u0642\u0631\u0628\u0627\u0646 \u0627\u0644\u0630\u064a \u062a\u0623\u0643\u0644\u0647 \u0627\u0644\u0646\u0627\u0631\u060c \u0641\u064e\u0644\u0650\u0645\u064e \u0642\u064e\u062a\u064e\u0644 \u0622\u0628\u0627\u0624\u0643\u0645 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0625\u0646 \u0643\u0646\u062a\u0645 \u0635\u0627\u062f\u0642\u064a\u0646 \u0641\u064a \u062f\u0639\u0648\u0627\u0643\u0645\u061f","3:184":"\u0641\u0625\u0646 \u0643\u0630\u0651\u064e\u0628\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u063a\u064a\u0631\u0647\u0645 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0643\u0641\u0631\u060c \u0641\u0642\u062f \u0643\u0630\u0651\u064e\u0628 \u0627\u0644\u0645\u0628\u0637\u0644\u0648\u0646 \u0643\u062b\u064a\u0631\u064b\u0627 \u0645\u0646 \u0627\u0644\u0645\u0631\u0633\u0644\u064a\u0646 \u0645\u0650\u0646 \u0642\u0628\u0644\u0643\u060c \u062c\u0627\u0621\u0648\u0627 \u0623\u0642\u0648\u0627\u0645\u0647\u0645 \u0628\u0627\u0644\u0645\u0639\u062c\u0632\u0627\u062a \u0627\u0644\u0628\u0627\u0647\u0631\u0627\u062a \u0648\u0627\u0644\u062d\u062c\u062c \u0627\u0644\u0648\u0627\u0636\u062d\u0627\u062a\u060c \u0648\u0627\u0644\u0643\u062a\u0628 \u0627\u0644\u0633\u0645\u0627\u0648\u064a\u0629 \u0627\u0644\u062a\u064a \u0647\u064a \u0646\u0648\u0631 \u064a\u0643\u0634\u0641 \u0627\u0644\u0638\u0644\u0645\u0627\u062a\u060c \u0648\u0627\u0644\u0643\u062a\u0627\u0628\u0650 \u0627\u0644\u0628\u064a\u0651\u0650\u0646 \u0627\u0644\u0648\u0627\u0636\u062d.","3:185":"\u0643\u0644 \u0646\u0641\u0633 \u0644\u0627 \u0628\u062f\u0651\u064e \u0623\u0646 \u062a\u0630\u0648\u0642 \u0627\u0644\u0645\u0648\u062a\u060c \u0648\u0628\u0647\u0630\u0627 \u064a\u0631\u062c\u0639 \u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u0644\u0642 \u0625\u0644\u0649 \u0631\u0628\u0647\u0645; \u0644\u064a\u062d\u0627\u0633\u0628\u0647\u0645. \u0648\u0625\u0646\u0645\u0627 \u062a\u064f\u0648\u0641\u0651\u064e\u0648\u0646 \u0623\u062c\u0648\u0631\u0643\u0645 \u0639\u0644\u0649 \u0623\u0639\u0645\u0627\u0644\u0643\u0645 \u0648\u0627\u0641\u064a\u0629 \u063a\u064a\u0631 \u0645\u0646\u0642\u0648\u0635\u0629 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u0641\u0645\u0646 \u0623\u0643\u0631\u0645\u0647 \u0631\u0628\u0647 \u0648\u0646\u062c\u0651\u064e\u0627\u0647 \u0645\u0646 \u0627\u0644\u0646\u0627\u0631 \u0648\u0623\u062f\u062e\u0644\u0647 \u0627\u0644\u062c\u0646\u0629 \u0641\u0642\u062f \u0646\u0627\u0644 \u063a\u0627\u064a\u0629 \u0645\u0627 \u064a\u0637\u0644\u0628. \u0648\u0645\u0627 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627 \u0625\u0644\u0627 \u0645\u062a\u0639\u0629 \u0632\u0627\u0626\u0644\u0629\u060c \u0641\u0644\u0627 \u062a\u063a\u062a\u0631\u0651\u064f\u0648\u0627 \u0628\u0647\u0627.","3:186":"\u0644\u064e\u062a\u064f\u062e\u0652\u062a\u064e\u0628\u064e\u0631\u064f\u0646\u0651\u064e -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0641\u064a \u0623\u0645\u0648\u0627\u0644\u0643\u0645 \u0628\u0625\u062e\u0631\u0627\u062c \u0627\u0644\u0646\u0641\u0642\u0627\u062a \u0627\u0644\u0648\u0627\u062c\u0628\u0629 \u0648\u0627\u0644\u0645\u0633\u062a\u062d\u0628\u0651\u064e\u0629\u060c \u0648\u0628\u0627\u0644\u062c\u0648\u0627\u0626\u062d \u0627\u0644\u062a\u064a \u062a\u0635\u064a\u0628\u0647\u0627\u060c \u0648\u0641\u064a \u0623\u0646\u0641\u0633\u0643\u0645 \u0628\u0645\u0627 \u064a\u062c\u0628 \u0639\u0644\u064a\u0643\u0645 \u0645\u0646 \u0627\u0644\u0637\u0627\u0639\u0627\u062a\u060c \u0648\u0645\u0627 \u064a\u062d\u0644\u0651\u064f \u0628\u0643\u0645 \u0645\u0646 \u062c\u0631\u0627\u062d \u0623\u0648 \u0642\u062a\u0644 \u0648\u0641\u064e\u0642\u0652\u062f \u0644\u0644\u0623\u062d\u0628\u0627\u0628\u060c \u0648\u0630\u0644\u0643 \u062d\u062a\u0649 \u064a\u062a\u0645\u064a\u0651\u064e\u0632 \u0627\u0644\u0645\u0624\u0645\u0646 \u0627\u0644\u0635\u0627\u062f\u0642 \u0645\u0646 \u063a\u064a\u0631\u0647. \u0648\u0644\u062a\u064e\u0633\u0645\u0639\u064f\u0646\u0651\u064e \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0648\u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0645\u0627 \u064a\u0624\u0630\u064a \u0623\u0633\u0645\u0627\u0639\u0643\u0645 \u0645\u0646 \u0623\u0644\u0641\u0627\u0638 \u0627\u0644\u0634\u0631\u0643 \u0648\u0627\u0644\u0637\u0639\u0646 \u0641\u064a \u062f\u064a\u0646\u0643\u0645. \u0648\u0625\u0646 \u062a\u0635\u0628\u0631\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0639\u0644\u0649 \u0630\u0644\u0643 \u0643\u0644\u0647\u060c \u0648\u062a\u062a\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0628\u0644\u0632\u0648\u0645 \u0637\u0627\u0639\u062a\u0647 \u0648\u0627\u062c\u062a\u0646\u0627\u0628 \u0645\u0639\u0635\u064a\u062a\u0647\u060c \u0641\u0625\u0646 \u0630\u0644\u0643 \u0645\u0646 \u0627\u0644\u0623\u0645\u0648\u0631 \u0627\u0644\u062a\u064a \u064a\u064f\u0639\u0632\u0645 \u0639\u0644\u064a\u0647\u0627\u060c \u0648\u064a\u0646\u0627\u0641\u0633 \u0641\u064a\u0647\u0627.","3:187":"\u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0625\u0630 \u0623\u062e\u0630 \u0627\u0644\u0644\u0647 \u0627\u0644\u0639\u0647\u062f \u0627\u0644\u0645\u0648\u062b\u0642 \u0639\u0644\u0649 \u0627\u0644\u0630\u064a\u0646 \u0622\u062a\u0627\u0647\u0645 \u0627\u0644\u0644\u0647 \u0627\u0644\u0643\u062a\u0627\u0628 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649\u060c \u0641\u0644\u0644\u064a\u0647\u0648\u062f \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u0644\u0644\u0646\u0635\u0627\u0631\u0649 \u0627\u0644\u0625\u0646\u062c\u064a\u0644; \u0644\u064a\u0639\u0645\u0644\u0648\u0627 \u0628\u0647\u0645\u0627\u060c \u0648\u064a\u0628\u064a\u0646\u0648\u0627 \u0644\u0644\u0646\u0627\u0633 \u0645\u0627 \u0641\u064a\u0647\u0645\u0627\u060c \u0648\u0644\u0627 \u064a\u0643\u062a\u0645\u0648\u0627 \u0630\u0644\u0643 \u0648\u0644\u0627 \u064a\u062e\u0641\u0648\u0647\u060c \u0641\u062a\u0631\u0643\u0648\u0627 \u0627\u0644\u0639\u0647\u062f \u0648\u0644\u0645 \u064a\u0644\u062a\u0632\u0645\u0648\u0627 \u0628\u0647\u060c \u0648\u0623\u062e\u0630\u0648\u0627 \u062b\u0645\u0646\u0627 \u0628\u062e\u0633\u064b\u0627 \u0645\u0642\u0627\u0628\u0644 \u0643\u062a\u0645\u0627\u0646\u0647\u0645 \u0627\u0644\u062d\u0642 \u0648\u062a\u062d\u0631\u064a\u0641\u0647\u0645 \u0627\u0644\u0643\u062a\u0627\u0628\u060c \u0641\u0628\u0626\u0633 \u0627\u0644\u0634\u0631\u0627\u0621 \u064a\u0634\u062a\u0631\u0648\u0646\u060c \u0641\u064a \u062a\u0636\u064a\u064a\u0639\u0647\u0645 \u0627\u0644\u0645\u064a\u062b\u0627\u0642\u060c \u0648\u062a\u0628\u062f\u064a\u0644\u0647\u0645 \u0627\u0644\u0643\u062a\u0627\u0628.","3:188":"\u0648\u0644\u0627 \u062a\u0638\u0646\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u0641\u0631\u062d\u0648\u0646 \u0628\u0645\u0627 \u0623\u064e\u062a\u064e\u0648\u0627 \u0645\u0646 \u0623\u0641\u0639\u0627\u0644 \u0642\u0628\u064a\u062d\u0629 \u0643\u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0648\u063a\u064a\u0631\u0647\u0645\u060c \u0648\u064a\u062d\u0628\u0648\u0646 \u0623\u0646 \u064a\u062b\u0646\u064a \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0646\u0627\u0633 \u0628\u0645\u0627 \u0644\u0645 \u064a\u0641\u0639\u0644\u0648\u0627\u060c \u0641\u0644\u0627 \u062a\u0638\u0646\u0647\u0645 \u0646\u0627\u062c\u064a\u0646 \u0645\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0644\u0647\u0645 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u0639\u0630\u0627\u0628 \u0645\u0648\u062c\u0639. \u0648\u0641\u064a \u0627\u0644\u0622\u064a\u0629 \u0648\u0639\u064a\u062f \u0634\u062f\u064a\u062f \u0644\u0643\u0644 \u0622\u062a \u0644\u0641\u0639\u0644 \u0627\u0644\u0633\u0648\u0621 \u0645\u0639\u062c\u0628 \u0628\u0647\u060c \u0648\u0644\u0643\u0644 \u0645\u0641\u062a\u062e\u0631 \u0628\u0645\u0627 \u0644\u0645 \u064a\u0639\u0645\u0644\u060c \u0644\u064a\u064f\u062b\u0646\u064a\u064e \u0639\u0644\u064a\u0647 \u0627\u0644\u0646\u0627\u0633 \u0648\u064a\u062d\u0645\u062f\u0648\u0647.","3:189":"\u0648\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0645\u0644\u0643 \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636 \u0648\u0645\u0627 \u0641\u064a\u0647\u0645\u0627\u060c \u0648\u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0643\u0644 \u0634\u064a\u0621 \u0642\u062f\u064a\u0631.","3:190":"\u0625\u0646 \u0641\u064a \u062e\u0644\u0642 \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636 \u0639\u0644\u0649 \u063a\u064a\u0631 \u0645\u062b\u0627\u0644 \u0633\u0627\u0628\u0642\u060c \u0648\u0641\u064a \u062a\u0639\u0627\u0642\u064f\u0628 \u0627\u0644\u0644\u064a\u0644 \u0648\u0627\u0644\u0646\u0647\u0627\u0631\u060c \u0648\u0627\u062e\u062a\u0644\u0627\u0641\u0647\u0645\u0627 \u0637\u0648\u0644\u0627 \u0648\u0642\u0650\u0635\u064e\u0631\u064b\u0627 \u0644\u062f\u0644\u0627\u0626\u0644 \u0648\u0628\u0631\u0627\u0647\u064a\u0646 \u0639\u0638\u064a\u0645\u0629 \u0639\u0644\u0649 \u0648\u062d\u062f\u0627\u0646\u064a\u0629 \u0627\u0644\u0644\u0647 \u0644\u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0639\u0642\u0648\u0644 \u0627\u0644\u0633\u0644\u064a\u0645\u0629.","3:191":"\u0627\u0644\u0630\u064a\u0646 \u064a\u0630\u0643\u0631\u0648\u0646 \u0627\u0644\u0644\u0647 \u0641\u064a \u062c\u0645\u064a\u0639 \u0623\u062d\u0648\u0627\u0644\u0647\u0645: \u0642\u064a\u0627\u0645\u064b\u0627 \u0648\u0642\u0639\u0648\u062f\u064b\u0627 \u0648\u0639\u0644\u0649 \u062c\u0646\u0648\u0628\u0647\u0645\u060c \u0648\u0647\u0645 \u064a\u062a\u062f\u0628\u0631\u0648\u0646 \u0641\u064a \u062e\u0644\u0642 \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636\u060c \u0642\u0627\u0626\u0644\u064a\u0646: \u064a\u0627 \u0631\u0628\u0646\u0627 \u0645\u0627 \u0623\u0648\u062c\u062f\u062a \u0647\u0630\u0627 \u0627\u0644\u062e\u0644\u0642 \u0639\u0628\u062b\u064b\u0627\u060c \u0641\u0623\u0646\u062a \u0645\u0646\u0632\u0651\u064e\u0647 \u0639\u0646 \u0630\u0644\u0643\u060c \u0641\u0627\u0635\u0652\u0631\u0650\u0641 \u0639\u0646\u0627 \u0639\u0630\u0627\u0628 \u0627\u0644\u0646\u0627\u0631.","3:192":"\u064a\u0627 \u0631\u0628\u0646\u0627 \u0646\u062c\u0651\u0650\u0646\u0627 \u0645\u0646 \u0627\u0644\u0646\u0627\u0631\u060c \u0641\u0625\u0646\u0643 -\u064a\u0627 \u0623\u0644\u0644\u0647- \u0645\u064e\u0646 \u062a\u064f\u062f\u062e\u0650\u0644\u0652\u0647 \u0627\u0644\u0646\u0627\u0631 \u0628\u0630\u0646\u0648\u0628\u0647 \u0641\u0642\u062f \u0641\u0636\u062d\u062a\u0647 \u0648\u0623\u0647\u0646\u062a\u0647\u060c \u0648\u0645\u0627 \u0644\u0644\u0645\u0630\u0646\u0628\u064a\u0646 \u0627\u0644\u0638\u0627\u0644\u0645\u064a\u0646 \u0644\u0623\u0646\u0641\u0633\u0647\u0645 \u0645\u0646 \u0623\u062d\u062f \u064a\u062f\u0641\u0639 \u0639\u0646\u0647\u0645 \u0639\u0642\u0627\u0628 \u0627\u0644\u0644\u0647 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629.","3:193":"\u064a\u0627 \u0631\u0628\u0646\u0627 \u0625\u0646\u0646\u0627 \u0633\u0645\u0639\u0646\u0627 \u0645\u0646\u0627\u062f\u064a\u0627 -\u0647\u0648 \u0646\u0628\u064a\u0643 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645- \u064a\u0646\u0627\u062f\u064a \u0627\u0644\u0646\u0627\u0633 \u0644\u0644\u062a\u0635\u062f\u064a\u0642 \u0628\u0643\u060c \u0648\u0627\u0644\u0625\u0642\u0631\u0627\u0631 \u0628\u0648\u062d\u062f\u0627\u0646\u064a\u062a\u0643\u060c \u0648\u0627\u0644\u0639\u0645\u0644 \u0628\u0634\u0631\u0639\u0643\u060c \u0641\u0623\u062c\u0628\u0646\u0627 \u062f\u0639\u0648\u062a\u0647 \u0648\u0635\u062f\u0651\u064e\u0642\u0646\u0627 \u0631\u0633\u0627\u0644\u062a\u0647\u060c \u0641\u0627\u063a\u0641\u0631 \u0644\u0646\u0627 \u0630\u0646\u0648\u0628\u0646\u0627\u060c \u0648\u0627\u0633\u062a\u0631 \u0639\u064a\u0648\u0628\u0646\u0627\u060c \u0648\u0623\u0644\u062d\u0642\u0646\u0627 \u0628\u0627\u0644\u0635\u0627\u0644\u062d\u064a\u0646.","3:194":"\u064a\u0627 \u0631\u0628\u0646\u0627 \u0623\u0639\u0637\u0646\u0627 \u0645\u0627 \u0648\u0639\u062f\u062a\u0646\u0627 \u0639\u0644\u0649 \u0623\u0644\u0633\u0646\u0629 \u0631\u0633\u0644\u0643 \u0645\u0646 \u0646\u0635\u0631 \u0648\u062a\u0645\u0643\u064a\u0646 \u0648\u062a\u0648\u0641\u064a\u0642 \u0648\u0647\u062f\u0627\u064a\u0629\u060c \u0648\u0644\u0627 \u062a\u0641\u0636\u062d\u0646\u0627 \u0628\u0630\u0646\u0648\u0628\u0646\u0627 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u0641\u0625\u0646\u0643 \u0643\u0631\u064a\u0645 \u0644\u0627 \u062a\u064f\u062e\u0652\u0644\u0641 \u0648\u0639\u062f\u064b\u0627 \u0648\u064e\u0639\u064e\u062f\u0652\u062a\u064e \u0628\u0647 \u0639\u0628\u0627\u062f\u0643.","3:195":"\u0641\u0623\u062c\u0627\u0628 \u0627\u0644\u0644\u0647 \u062f\u0639\u0627\u0621\u0647\u0645 \u0628\u0623\u0646\u0647 \u0644\u0627 \u064a\u0636\u064a\u0639 \u062c\u0647\u062f \u0645\u064e\u0646 \u0639\u0645\u0644 \u0645\u0646\u0647\u0645 \u0639\u0645\u0644\u0627 \u0635\u0627\u0644\u062d\u064b\u0627 \u0630\u0643\u0631\u064b\u0627 \u0643\u0627\u0646 \u0623\u0648 \u0623\u0646\u062b\u0649\u060c \u0648\u0647\u0645 \u0641\u064a \u0623\u064f\u062e\u064f\u0648\u0651\u064e\u0629 \u0627\u0644\u062f\u064a\u0646 \u0648\u0642\u064e\u0628\u0648\u0644 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0648\u0627\u0644\u062c\u0632\u0627\u0621 \u0639\u0644\u064a\u0647\u0627 \u0633\u0648\u0627\u0621\u060c \u0641\u0627\u0644\u0630\u064a\u0646 \u0647\u0627\u062c\u0631\u0648\u0627 \u0631\u063a\u0628\u0629\u064b \u0641\u064a \u0631\u0636\u0627 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0623\u064f\u062e\u0631\u062c\u0648\u0627 \u0645\u0646 \u062f\u064a\u0627\u0631\u0647\u0645\u060c \u0648\u0623\u0648\u0630\u0648\u0627 \u0641\u064a \u0637\u0627\u0639\u0629 \u0631\u0628\u0647\u0645 \u0648\u0639\u0628\u0627\u062f\u062a\u0647\u0645 \u0625\u064a\u0651\u0627\u0647\u060c \u0648\u0642\u0627\u062a\u0644\u0648\u0627 \u0648\u0642\u064f\u062a\u0650\u0644\u0648\u0627 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0644\u0625\u0639\u0644\u0627\u0621 \u0643\u0644\u0645\u062a\u0647\u060c \u0644\u064a\u0633\u062a\u0631\u0646\u0651\u064e \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645 \u0645\u0627 \u0627\u0631\u062a\u0643\u0628\u0648\u0647 \u0645\u0646 \u0627\u0644\u0645\u0639\u0627\u0635\u064a\u060c \u0643\u0645\u0627 \u0633\u062a\u0631\u0647\u0627 \u0639\u0644\u064a\u0647\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0641\u0644\u0627 \u064a\u062d\u0627\u0633\u0628\u0647\u0645 \u0639\u0644\u064a\u0647\u0627\u060c \u0648\u0644\u064a\u062f\u062e\u0644\u0646\u0651\u064e\u0647\u0645 \u062c\u0646\u0627\u062a \u062a\u062c\u0631\u064a \u0645\u0646 \u062a\u062d\u062a \u0642\u0635\u0648\u0631\u0647\u0627 \u0648\u0623\u0634\u062c\u0627\u0631\u0647\u0627 \u0627\u0644\u0623\u0646\u0647\u0627\u0631 \u062c\u0632\u0627\u0621 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u0644\u0644\u0647 \u0639\u0646\u062f\u0647 \u062d\u0633\u0646 \u0627\u0644\u062b\u0648\u0627\u0628.","3:196":"\u0644\u0627 \u062a\u063a\u062a\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0628\u0645\u0627 \u0639\u0644\u064a\u0647 \u0623\u0647\u0644 \u0627\u0644\u0643\u0641\u0631 \u0628\u0627\u0644\u0644\u0647 \u0645\u0646 \u0628\u0633\u0637\u0629 \u0641\u064a \u0627\u0644\u0639\u064a\u0634\u060c \u0648\u0633\u064e\u0639\u064e\u0629 \u0641\u064a \u0627\u0644\u0631\u0632\u0642\u060c \u0648\u0627\u0646\u062a\u0642\u0627\u0644\u0647\u0645 \u0645\u0646 \u0645\u0643\u0627\u0646 \u0625\u0644\u0649 \u0645\u0643\u0627\u0646 \u0644\u0644\u062a\u062c\u0627\u0631\u0627\u062a \u0648\u0637\u0644\u0628 \u0627\u0644\u0623\u0631\u0628\u0627\u062d \u0648\u0627\u0644\u0623\u0645\u0648\u0627\u0644\u060c \u0641\u0639\u0645\u0651\u064e\u0627 \u0642\u0644\u064a\u0644 \u064a\u0632\u0648\u0644 \u0647\u0630\u0627 \u0643\u0644\u0651\u064f\u0647 \u0639\u0646\u0647\u0645\u060c \u0648\u064a\u0635\u0628\u062d\u0648\u0646 \u0645\u0631\u062a\u0647\u0646\u064a\u0646 \u0628\u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0627\u0644\u0633\u064a\u0626\u0629.","3:197":"\u0645\u062a\u0627\u0639 \u0642\u0644\u064a\u0644 \u0632\u0627\u0626\u0644\u060c \u062b\u0645 \u064a\u0643\u0648\u0646 \u0645\u0635\u064a\u0631\u0647\u0645 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u0625\u0644\u0649 \u0627\u0644\u0646\u0627\u0631\u060c \u0648\u0628\u0626\u0633 \u0627\u0644\u0641\u0631\u0627\u0634.","3:198":"\u0644\u0643\u0646 \u0627\u0644\u0630\u064a\u0646 \u062e\u0627\u0641\u0648\u0627 \u0631\u0628\u0647\u0645\u060c \u0648\u0627\u0645\u062a\u062b\u0644\u0648\u0627 \u0623\u0648\u0627\u0645\u0631\u0647\u060c \u0648\u0627\u062c\u062a\u0646\u0628\u0648\u0627 \u0646\u0648\u0627\u0647\u064a\u0647\u060c \u0642\u062f \u0623\u0639\u062f\u0651\u064e \u0627\u0644\u0644\u0647 \u0644\u0647\u0645 \u062c\u0646\u0627\u062a \u062a\u062c\u0631\u064a \u0645\u0646 \u062a\u062d\u062a \u0623\u0634\u062c\u0627\u0631\u0647\u0627 \u0627\u0644\u0623\u0646\u0647\u0627\u0631\u060c \u0647\u064a \u0645\u0646\u0632\u0644\u0647\u0645 \u0627\u0644\u062f\u0627\u0626\u0645 \u0644\u0627 \u064a\u062e\u0631\u062c\u0648\u0646 \u0645\u0646\u0647. \u0648\u0645\u0627 \u0639\u062f \u0627\u0644\u0644\u0647 \u0623\u0639\u0638\u0645 \u0648\u0623\u0641\u0636\u0644 \u0644\u0623\u0647\u0644 \u0627\u0644\u0637\u0627\u0639\u0629 \u0645\u0645\u0627 \u064a\u062a\u0642\u0644\u0628 \u0641\u064a\u0647 \u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0645\u0646 \u0646\u0639\u064a\u0645 \u0627\u0644\u062f\u0646\u064a\u0627.","3:199":"\u0648\u0625\u0646 \u0628\u0639\u0636\u064b\u0627 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0644\u064e\u064a\u0635\u062f\u0651\u0650\u0642 \u0628\u0627\u0644\u0644\u0647 \u0631\u0628\u0651\u064b\u0627 \u0648\u0627\u062d\u062f\u064b\u0627 \u0648\u0625\u0644\u0647\u064b\u0627 \u0645\u0639\u0628\u0648\u062f\u064b\u0627\u060c \u0648\u0628\u0645\u0627 \u0623\u064f\u0646\u0632\u0650\u0644 \u0625\u0644\u064a\u0643\u0645 \u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0648\u0628\u0645\u0627 \u0623\u064f\u0646\u0632\u0650\u0644 \u0625\u0644\u064a\u0647\u0645 \u0645\u0646 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644 \u0645\u062a\u0630\u0644\u0644\u064a\u0646 \u0644\u0644\u0647\u060c \u062e\u0627\u0636\u0639\u064a\u0646 \u0644\u0647\u060c \u0644\u0627 \u064a\u0634\u062a\u0631\u0648\u0646 \u0628\u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u062b\u0645\u0646\u064b\u0627 \u0642\u0644\u064a\u0644\u0627 \u0645\u0646 \u062d\u0637\u0627\u0645 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0644\u0627 \u064a\u0643\u062a\u0645\u0648\u0646 \u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0627 \u064a\u062d\u0631\u0641\u0648\u0646\u0647 \u0643\u063a\u064a\u0631\u0647\u0645 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628. \u0623\u0648\u0644\u0626\u0643 \u0644\u0647\u0645 \u062b\u0648\u0627\u0628 \u0639\u0638\u064a\u0645 \u0639\u0646\u062f\u0647 \u064a\u0648\u0645 \u064a\u0644\u0642\u0648\u0646\u0647\u060c \u0641\u064a\u0648\u0641\u064a\u0647\u0645 \u0625\u064a\u0627\u0647 \u063a\u064a\u0631 \u0645\u0646\u0642\u0648\u0635. \u0625\u0646\u0651\u064e \u0627\u0644\u0644\u0647 \u0633\u0631\u064a\u0639 \u0627\u0644\u062d\u0633\u0627\u0628\u060c \u0644\u0627 \u064a\u0639\u062c\u0632\u0647 \u0625\u062d\u0635\u0627\u0621 \u0623\u0639\u0645\u0627\u0644\u0647\u0645\u060c \u0648\u0645\u062d\u0627\u0633\u0628\u062a\u0647\u0645 \u0639\u0644\u064a\u0647\u0627.","3:200":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647 \u0627\u0635\u0628\u0631\u0648\u0627 \u0639\u0644\u0649 \u0637\u0627\u0639\u0629 \u0631\u0628\u0643\u0645\u060c \u0648\u0639\u0644\u0649 \u0645\u0627 \u064a\u0646\u0632\u0644 \u0628\u0643\u0645 \u0645\u0646 \u0636\u0631 \u0648\u0628\u0644\u0627\u0621\u060c \u0648\u0635\u0627\u0628\u0631\u0648\u0627 \u0623\u0639\u062f\u0627\u0621\u0643\u0645 \u062d\u062a\u0649 \u0644\u0627 \u064a\u0643\u0648\u0646\u0648\u0627 \u0623\u0634\u062f \u0635\u0628\u0631\u064b\u0627 \u0645\u0646\u0643\u0645\u060c \u0648\u0623\u0642\u064a\u0645\u0648\u0627 \u0639\u0644\u0649 \u062c\u0647\u0627\u062f \u0639\u062f\u0648\u064a \u0648\u0639\u062f\u0648\u0643\u0645\u060c \u0648\u062e\u0627\u0641\u0648\u0627 \u0627\u0644\u0644\u0647 \u0641\u064a \u062c\u0645\u064a\u0639 \u0623\u062d\u0648\u0627\u0644\u0643\u0645; \u0631\u062c\u0627\u0621 \u0623\u0646 \u062a\u0641\u0648\u0632\u0648\u0627 \u0628\u0631\u0636\u0627\u0647 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629.","4:1":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633 \u062e\u0627\u0641\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u062a\u0632\u0645\u0648\u0627 \u0623\u0648\u0627\u0645\u0631\u0647\u060c \u0648\u0627\u062c\u062a\u0646\u0628\u0648\u0627 \u0646\u0648\u0627\u0647\u064a\u0647; \u0641\u0647\u0648 \u0627\u0644\u0630\u064a \u062e\u0644\u0642\u0643\u0645 \u0645\u0646 \u0646\u0641\u0633 \u0648\u0627\u062d\u062f\u0629 \u0647\u064a \u0622\u062f\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0648\u062e\u0644\u0642 \u0645\u0646\u0647\u0627 \u0632\u0648\u062c\u0647\u0627 \u0648\u0647\u064a \u062d\u0648\u0627\u0621\u060c \u0648\u0646\u0634\u0631 \u0645\u0646\u0647\u0645\u0627 \u0641\u064a \u0623\u0646\u062d\u0627\u0621 \u0627\u0644\u0623\u0631\u0636 \u0631\u062c\u0627\u0644\u0627 \u0643\u062b\u064a\u0631\u064b\u0627 \u0648\u0646\u0633\u0627\u0621 \u0643\u062b\u064a\u0631\u0627\u062a\u060c \u0648\u0631\u0627\u0642\u0628\u0648\u0627 \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a \u064a\u064e\u0633\u0652\u0623\u0644 \u0628\u0647 \u0628\u0639\u0636\u0643\u0645 \u0628\u0639\u0636\u064b\u0627\u060c \u0648\u0627\u062d\u0630\u0631\u0648\u0627 \u0623\u0646 \u062a\u0642\u0637\u0639\u0648\u0627 \u0623\u0631\u062d\u0627\u0645\u0643\u0645. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0645\u0631\u0627\u0642\u0628 \u0644\u062c\u0645\u064a\u0639 \u0623\u062d\u0648\u0627\u0644\u0643\u0645.","4:2":"\u0648\u0623\u0639\u0637\u0648\u0627 \u0645\u064e\u0646 \u0645\u0627\u062a \u0622\u0628\u0627\u0624\u0647\u0645 \u0648\u0647\u0645 \u062f\u0648\u0646 \u0627\u0644\u0628\u0644\u0648\u063a\u060c -\u0648\u0643\u0646\u062a\u0645 \u0639\u0644\u064a\u0647\u0645 \u0623\u0648\u0635\u064a\u0627\u0621- \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0625\u0630\u0627 \u0648\u0635\u0644\u0648\u0627 \u0633\u0646 \u0627\u0644\u0628\u0644\u0648\u063a\u060c \u0648\u0631\u0623\u064a\u062a\u0645 \u0645\u0646\u0647\u0645 \u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u062d\u0641\u0638 \u0623\u0645\u0648\u0627\u0644\u0647\u0645\u060c \u0648\u0644\u0627 \u062a\u0623\u062e\u0630\u0648\u0627 \u0627\u0644\u062c\u064a\u0651\u0650\u062f \u0645\u0646 \u0623\u0645\u0648\u0627\u0644\u0647\u0645\u060c \u0648\u062a\u062c\u0639\u0644\u0648\u0627 \u0645\u0643\u0627\u0646\u0647 \u0627\u0644\u0631\u062f\u064a\u0621 \u0645\u0646 \u0623\u0645\u0648\u0627\u0644\u0643\u0645\u060c \u0648\u0644\u0627 \u062a\u062e\u0644\u0637\u0648\u0627 \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0628\u0623\u0645\u0648\u0627\u0644\u0643\u0645; \u0644\u062a\u062d\u062a\u0627\u0644\u0648\u0627 \u0628\u0630\u0644\u0643 \u0639\u0644\u0649 \u0623\u0643\u0644 \u0623\u0645\u0648\u0627\u0644\u0647\u0645. \u0625\u0646 \u0645\u0646 \u062a\u062c\u0631\u0623 \u0639\u0644\u0649 \u0630\u0644\u0643 \u0641\u0642\u062f \u0627\u0631\u062a\u0643\u0628 \u0625\u062b\u0645\u064b\u0627 \u0639\u0638\u064a\u0645\u064b\u0627.","4:3":"\u0648\u0625\u0646 \u062e\u0641\u062a\u0645 \u0623\u0644\u0627 \u062a\u0639\u062f\u0644\u0648\u0627 \u0641\u064a \u064a\u062a\u0627\u0645\u0649 \u0627\u0644\u0646\u0633\u0627\u0621 \u0627\u0644\u0644\u0627\u062a\u064a \u062a\u062d\u062a \u0623\u064a\u062f\u064a\u0643\u0645 \u0628\u0623\u0646 \u0644\u0627 \u062a\u0639\u0637\u0648\u0647\u0646 \u0645\u0647\u0648\u0631\u0647\u0646 \u0643\u063a\u064a\u0631\u0647\u0646\u060c \u0641\u0627\u062a\u0631\u0643\u0648\u0647\u0646 \u0648\u0627\u0646\u0643\u062d\u0648\u0627 \u0645\u0627 \u0637\u0627\u0628 \u0644\u0643\u0645 \u0645\u0646 \u0627\u0644\u0646\u0633\u0627\u0621 \u0645\u0646 \u063a\u064a\u0631\u0647\u0646: \u0627\u062b\u0646\u062a\u064a\u0646 \u0623\u0648 \u062b\u0644\u0627\u062b\u064b\u0627 \u0623\u0648 \u0623\u0631\u0628\u0639\u064b\u0627\u060c \u0641\u0625\u0646 \u062e\u0634\u064a\u062a\u0645 \u0623\u0644\u0627 \u062a\u0639\u062f\u0644\u0648\u0627 \u0628\u064a\u0646\u0647\u0646 \u0641\u0627\u0643\u062a\u0641\u0648\u0627 \u0628\u0648\u0627\u062d\u062f\u0629\u060c \u0623\u0648 \u0628\u0645\u0627 \u0639\u0646\u062f\u0643\u0645 \u0645\u0646 \u0627\u0644\u0625\u0645\u0627\u0621. \u0630\u0644\u0643 \u0627\u0644\u0630\u064a \u0634\u0631\u0639\u062a\u0647 \u0644\u0643\u0645 \u0641\u064a \u0627\u0644\u064a\u062a\u064a\u0645\u0627\u062a \u0648\u0627\u0644\u0632\u0648\u0627\u062c \u0645\u0646 \u0648\u0627\u062d\u062f\u0629 \u0625\u0644\u0649 \u0623\u0631\u0628\u0639\u060c \u0623\u0648 \u0627\u0644\u0627\u0642\u062a\u0635\u0627\u0631 \u0639\u0644\u0649 \u0648\u0627\u062d\u062f\u0629 \u0623\u0648 \u0645\u0644\u0643 \u0627\u0644\u064a\u0645\u064a\u0646\u060c \u0623\u0642\u0631\u0628 \u0625\u0644\u0649 \u0639\u062f\u0645 \u0627\u0644\u062c\u064e\u0648\u0652\u0631\u0650 \u0648\u0627\u0644\u062a\u0639\u062f\u064a.","4:4":"\u0648\u0623\u0639\u0637\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0623\u0632\u0648\u0627\u062c- \u0627\u0644\u0646\u0633\u0627\u0621 \u0645\u0647\u0648\u0631\u0647\u0646\u060c \u0639\u0637\u064a\u0629 \u0648\u0627\u062c\u0628\u0629 \u0648\u0641\u0631\u064a\u0636\u0629 \u0644\u0627\u0632\u0645\u0629 \u0639\u0646 \u0637\u064a\u0628 \u0646\u0641\u0633 \u0645\u0646\u0643\u0645. \u0641\u0625\u0646 \u0637\u0627\u0628\u062a \u0623\u0646\u0641\u0633\u0647\u0646 \u0644\u0643\u0645 \u0639\u0646 \u0634\u064a\u0621 \u0645\u0646 \u0627\u0644\u0645\u0647\u0631 \u0641\u0648\u0647\u064e\u0628\u0652\u0646\u0647 \u0644\u0643\u0645 \u0641\u062e\u0630\u0648\u0647\u060c \u0648\u062a\u0635\u0631\u0651\u064e\u0641\u0648\u0627 \u0641\u064a\u0647\u060c \u0641\u0647\u0648 \u062d\u0644\u0627\u0644 \u0637\u064a\u0628.","4:5":"\u0648\u0644\u0627 \u062a\u0624\u062a\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0623\u0648\u0644\u064a\u0627\u0621- \u0645\u0646 \u064a\u064f\u0628\u064e\u0630\u0651\u0650\u0631 \u0645\u0646 \u0627\u0644\u0631\u062c\u0627\u0644 \u0648\u0627\u0644\u0646\u0633\u0627\u0621 \u0648\u0627\u0644\u0635\u0628\u064a\u0627\u0646 \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0627\u0644\u062a\u064a \u062a\u062d\u062a \u0623\u064a\u062f\u064a\u0643\u0645 \u0641\u064a\u0636\u0639\u0648\u0647\u0627 \u0641\u064a \u063a\u064a\u0631 \u0648\u062c\u0647\u0647\u0627\u060c \u0641\u0647\u0630\u0647 \u0627\u0644\u0623\u0645\u0648\u0627\u0644 \u0647\u064a \u0627\u0644\u062a\u064a \u0639\u0644\u064a\u0647\u0627 \u0642\u064a\u0627\u0645 \u062d\u064a\u0627\u0629 \u0627\u0644\u0646\u0627\u0633\u060c \u0648\u0623\u0646\u0641\u0642\u0648\u0627 \u0639\u0644\u064a\u0647\u0645 \u0645\u0646\u0647\u0627 \u0648\u0627\u0643\u0633\u0648\u0647\u0645\u060c \u0648\u0642\u0648\u0644\u0648\u0627 \u0644\u0647\u0645 \u0642\u0648\u0644\u0627 \u0645\u0639\u0631\u0648\u0641\u064b\u0627 \u0645\u0646 \u0627\u0644\u0643\u0644\u0627\u0645 \u0627\u0644\u0637\u064a\u0628 \u0648\u0627\u0644\u062e\u0644\u0642 \u0627\u0644\u062d\u0633\u0646.","4:6":"\u0648\u0627\u062e\u062a\u0628\u0631\u0648\u0627 \u0645\u064e\u0646 \u062a\u062d\u062a \u0623\u064a\u062f\u064a\u0643\u0645 \u0645\u0646 \u0627\u0644\u064a\u062a\u0627\u0645\u0649 \u0644\u0645\u0639\u0631\u0641\u0629 \u0642\u062f\u0631\u062a\u0647\u0645 \u0639\u0644\u0649 \u062d\u0633\u0646 \u0627\u0644\u062a\u0635\u0631\u0641 \u0641\u064a \u0623\u0645\u0648\u0627\u0644\u0647\u0645\u060c \u062d\u062a\u0649 \u0625\u0630\u0627 \u0648\u0635\u0644\u0648\u0627 \u0625\u0644\u0649 \u0633\u0646 \u0627\u0644\u0628\u0644\u0648\u063a\u060c \u0648\u0639\u064e\u0644\u0645\u062a\u0645 \u0645\u0646\u0647\u0645 \u0635\u0644\u0627\u062d\u064b\u0627 \u0641\u064a \u062f\u064a\u0646\u0647\u0645\u060c \u0648\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u062d\u0641\u0638 \u0623\u0645\u0648\u0627\u0644\u0647\u0645\u060c \u0641\u0633\u0644\u0651\u0650\u0645\u0648\u0647\u0627 \u0644\u0647\u0645\u060c \u0648\u0644\u0627 \u062a\u0639\u062a\u062f\u0648\u0627 \u0639\u0644\u064a\u0647\u0627 \u0628\u0625\u0646\u0641\u0627\u0642\u0647\u0627 \u0641\u064a \u063a\u064a\u0631 \u0645\u0648\u0636\u0639\u0647\u0627 \u0625\u0633\u0631\u0627\u0641\u064b\u0627 \u0648\u0645\u0628\u0627\u062f\u0631\u0629 \u0644\u0623\u0643\u0644\u0647\u0627 \u0642\u0628\u0644 \u0623\u0646 \u064a\u0623\u062e\u0630\u0648\u0647\u0627 \u0645\u0646\u0643\u0645. \u0648\u0645\u064e\u0646 \u0643\u0627\u0646 \u0635\u0627\u062d\u0628 \u0645\u0627\u0644 \u0645\u0646\u0643\u0645 \u0641\u0644\u064a\u0633\u062a\u0639\u0641\u0641 \u0628\u063a\u0646\u0627\u0647\u060c \u0648\u0644\u0627 \u064a\u0623\u062e\u0630 \u0645\u0646 \u0645\u0627\u0644 \u0627\u0644\u064a\u062a\u064a\u0645 \u0634\u064a\u0626\u064b\u0627\u060c \u0648\u0645\u0646 \u0643\u0627\u0646 \u0641\u0642\u064a\u0631\u064b\u0627 \u0641\u0644\u064a\u0623\u062e\u0630 \u0628\u0642\u062f\u0631 \u062d\u0627\u062c\u062a\u0647 \u0639\u0646\u062f \u0627\u0644\u0636\u0631\u0648\u0631\u0629. \u0641\u0625\u0630\u0627 \u0639\u0644\u0645\u062a\u0645 \u0623\u0646\u0647\u0645 \u0642\u0627\u062f\u0631\u0648\u0646 \u0639\u0644\u0649 \u062d\u0641\u0638 \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0628\u0639\u062f \u0628\u0644\u0648\u063a\u0647\u0645 \u0627\u0644\u062d\u064f\u0644\u064f\u0645 \u0648\u0633\u0644\u0645\u062a\u0645\u0648\u0647\u0627 \u0625\u0644\u064a\u0647\u0645\u060c \u0641\u0623\u064e\u0634\u0652\u0647\u0650\u062f\u0648\u0627 \u0639\u0644\u064a\u0647\u0645; \u0636\u0645\u0627\u0646\u064b\u0627 \u0644\u0648\u0635\u0648\u0644 \u062d\u0642\u0647\u0645 \u0643\u0627\u0645\u0644\u0627 \u0625\u0644\u064a\u0647\u0645; \u0644\u0626\u0644\u0627 \u064a\u0646\u0643\u0631\u0648\u0627 \u0630\u0644\u0643. \u0648\u064a\u0643\u0641\u064a\u0643\u0645 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0634\u0627\u0647\u062f \u0639\u0644\u064a\u0643\u0645\u060c \u0648\u0645\u062d\u0627\u0633\u0628 \u0644\u0643\u0645 \u0639\u0644\u0649 \u0645\u0627 \u0641\u0639\u0644\u062a\u0645.","4:7":"\u0644\u0644\u0630\u0643\u0648\u0631 -\u0635\u063a\u0627\u0631\u064b\u0627 \u0623\u0648 \u0643\u0628\u0627\u0631\u064b\u0627- \u0646\u0635\u064a\u0628 \u0634\u0631\u0639\u0647 \u0627\u0644\u0644\u0647 \u0641\u064a\u0645\u0627 \u062a\u0631\u0643\u0647 \u0627\u0644\u0648\u0627\u0644\u062f\u0627\u0646 \u0648\u0627\u0644\u0623\u0642\u0631\u0628\u0648\u0646 \u0645\u0646 \u0627\u0644\u0645\u0627\u0644\u060c \u0642\u0644\u064a\u0644\u0627 \u0643\u0627\u0646 \u0623\u0648 \u0643\u062b\u064a\u0631\u064b\u0627\u060c \u0641\u064a \u0623\u0646\u0635\u0628\u0629 \u0645\u062d\u062f\u062f\u0629 \u0648\u0627\u0636\u062d\u0629 \u0641\u0631\u0636\u0647\u0627 \u0627\u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644 \u0644\u0647\u0624\u0644\u0627\u0621\u060c \u0648\u0644\u0644\u0646\u0633\u0627\u0621 \u0643\u0630\u0644\u0643.","4:8":"\u0648\u0625\u0630\u0627 \u062d\u0636\u0631 \u0642\u0633\u0645\u0629\u064e \u0627\u0644\u0645\u064a\u0631\u0627\u062b \u0623\u0642\u0627\u0631\u0628\u064f \u0627\u0644\u0645\u064a\u062a \u0645\u0645\u0646 \u0644\u0627 \u062d\u0642\u0651\u064e \u0644\u0647\u0645 \u0641\u064a \u0627\u0644\u062a\u0631\u0643\u0629\u060c \u0623\u0648 \u062d\u0636\u0631\u0647\u0627 \u0645\u0646 \u0645\u0627\u062a \u0622\u0628\u0627\u0624\u0647\u0645 \u0648\u0647\u0645 \u0635\u063a\u0627\u0631 \u062f\u0648\u0646 \u0633\u0646 \u0627\u0644\u0628\u0644\u0648\u063a\u060c \u0623\u0648 \u0645\u064e\u0646 \u0644\u0627 \u064a\u0645\u0644\u0643\u0648\u0646 \u0645\u0627 \u064a\u0643\u0641\u064a\u0647\u0645 \u0648\u064a\u0633\u062f \u062d\u0627\u062c\u062a\u0647\u0645 \u0641\u0623\u0639\u0637\u0648\u0647\u0645 \u0634\u064a\u0626\u064b\u0627 \u0645\u0646 \u0627\u0644\u0645\u0627\u0644 \u0639\u0644\u0649 \u0648\u062c\u0647 \u0627\u0644\u0627\u0633\u062a\u062d\u0628\u0627\u0628 \u0642\u0628\u0644 \u062a\u0642\u0633\u064a\u0645 \u0627\u0644\u062a\u0631\u0643\u0629 \u0639\u0644\u0649 \u0623\u0635\u062d\u0627\u0628\u0647\u0627\u060c \u0648\u0642\u0648\u0644\u0648\u0627 \u0644\u0647\u0645 \u0642\u0648\u0644\u0627 \u062d\u0633\u0646\u064b\u0627 \u063a\u064a\u0631 \u0641\u0627\u062d\u0634 \u0648\u0644\u0627 \u0642\u0628\u064a\u062d.","4:9":"\u0648\u0644\u0652\u064a\u064e\u062e\u064e\u0641\u0650 \u0627\u0644\u0630\u064a\u0646 \u0644\u0648 \u0645\u0627\u062a\u0648\u0627 \u0648\u062a\u0631\u0643\u0648\u0627 \u0645\u0646 \u062e\u0644\u0641\u0647\u0645 \u0623\u0628\u0646\u0627\u0621 \u0635\u063a\u0627\u0631\u064b\u0627 \u0636\u0639\u0627\u0641\u064b\u0627 \u062e\u0627\u0641\u0648\u0627 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0638\u0644\u0645 \u0648\u0627\u0644\u0636\u064a\u0627\u0639\u060c \u0641\u0644\u064a\u0631\u0627\u0642\u0628\u0648\u0627 \u0627\u0644\u0644\u0647 \u0641\u064a\u0645\u0646 \u062a\u062d\u062a \u0623\u064a\u062f\u064a\u0647\u0645 \u0645\u0646 \u0627\u0644\u064a\u062a\u0627\u0645\u0649 \u0648\u063a\u064a\u0631\u0647\u0645\u060c \u0648\u0630\u0644\u0643 \u0628\u062d\u0641\u0638 \u0623\u0645\u0648\u0627\u0644\u0647\u0645\u060c \u0648\u062d\u0633\u0646 \u062a\u0631\u0628\u064a\u062a\u0647\u0645\u060c \u0648\u062f\u064e\u0641\u0652\u0639 \u0627\u0644\u0623\u0630\u0649 \u0639\u0646\u0647\u0645\u060c \u0648\u0644\u064a\u0642\u0648\u0644\u0648\u0627 \u0644\u0647\u0645 \u0642\u0648\u0644\u0627 \u0645\u0648\u0627\u0641\u0642\u0627 \u0644\u0644\u0639\u062f\u0644 \u0648\u0627\u0644\u0645\u0639\u0631\u0648\u0641.","4:10":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u0639\u0652\u062a\u064e\u062f\u0648\u0646 \u0639\u0644\u0649 \u0623\u0645\u0648\u0627\u0644 \u0627\u0644\u064a\u062a\u0627\u0645\u0649\u060c \u0641\u064a\u0623\u062e\u0630\u0648\u0646\u0647\u0627 \u0628\u063a\u064a\u0631 \u062d\u0642\u060c \u0625\u0646\u0645\u0627 \u064a\u0623\u0643\u0644\u0648\u0646 \u0646\u0627\u0631\u064b\u0627 \u062a\u062a\u0623\u062c\u0651\u062c \u0641\u064a \u0628\u0637\u0648\u0646\u0647\u0645 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u0648\u0633\u064a\u062f\u062e\u0644\u0648\u0646 \u0646\u0627\u0631\u0627 \u064a\u0642\u0627\u0633\u0648\u0646 \u062d\u0631\u0651\u064e\u0647\u0627.","4:11":"\u064a\u0648\u0635\u064a\u0643\u0645 \u0627\u0644\u0644\u0647 \u0648\u064a\u0623\u0645\u0631\u0643\u0645 \u0641\u064a \u0634\u0623\u0646 \u0623\u0648\u0644\u0627\u062f\u0643\u0645: \u0625\u0630\u0627 \u0645\u0627\u062a \u0623\u062d\u062f \u0645\u0646\u0643\u0645 \u0648\u062a\u0631\u0643 \u0623\u0648\u0644\u0627\u062f\u064b\u0627: \u0630\u0643\u0648\u0631\u064b\u0627 \u0648\u0625\u0646\u0627\u062b\u064b\u0627\u060c \u0641\u0645\u064a\u0631\u0627\u062b\u0647 \u0643\u0644\u0647 \u0644\u0647\u0645: \u0644\u0644\u0630\u0643\u0631 \u0645\u062b\u0644 \u0646\u0635\u064a\u0628 \u0627\u0644\u0623\u0646\u062b\u064a\u064a\u0646\u060c \u0625\u0630\u0627 \u0644\u0645 \u064a\u0643\u0646 \u0647\u0646\u0627\u0643 \u0648\u0627\u0631\u062b \u063a\u064a\u0631\u0647\u0645. \u0641\u0625\u0646 \u062a\u0631\u0643 \u0628\u0646\u0627\u062a \u0641\u0642\u0637 \u0641\u0644\u0644\u0628\u0646\u062a\u064a\u0646 \u0641\u0623\u0643\u062b\u0631 \u062b\u0644\u062b\u0627 \u0645\u0627 \u062a\u0631\u0643\u060c \u0648\u0625\u0646 \u0643\u0627\u0646\u062a \u0627\u0628\u0646\u0629 \u0648\u0627\u062d\u062f\u0629\u060c \u0641\u0644\u0647\u0627 \u0627\u0644\u0646\u0635\u0641. \u0648\u0644\u0648\u0627\u0644\u0650\u062f\u064e\u064a \u0627\u0644\u0645\u064a\u062a \u0644\u0643\u0644 \u0648\u0627\u062d\u062f \u0645\u0646\u0647\u0645\u0627 \u0627\u0644\u0633\u062f\u0633 \u0625\u0646 \u0643\u0627\u0646 \u0644\u0647 \u0648\u0644\u062f: \u0630\u0643\u0631\u064b\u0627 \u0643\u0627\u0646 \u0623\u0648 \u0623\u0646\u062b\u0649\u060c \u0648\u0627\u062d\u062f\u064b\u0627 \u0623\u0648 \u0623\u0643\u062b\u0631. \u0641\u0625\u0646 \u0644\u0645 \u064a\u0643\u0646 \u0644\u0647 \u0648\u0644\u062f \u0648\u0648\u0631\u062b\u0647 \u0648\u0627\u0644\u062f\u0627\u0647 \u0641\u0644\u0623\u0645\u0647 \u0627\u0644\u062b\u0644\u062b \u0648\u0644\u0623\u0628\u064a\u0647 \u0627\u0644\u0628\u0627\u0642\u064a. \u0641\u0625\u0646 \u0643\u0627\u0646 \u0644\u0644\u0645\u064a\u062a \u0625\u062e\u0648\u0629 \u0627\u062b\u0646\u0627\u0646 \u0641\u0623\u0643\u062b\u0631\u060c \u0630\u0643\u0648\u0631\u064b\u0627 \u0643\u0627\u0646\u0648\u0627 \u0623\u0648 \u0625\u0646\u0627\u062b\u064b\u0627\u060c \u0641\u0644\u0623\u0645\u0647 \u0627\u0644\u0633\u062f\u0633\u060c \u0648\u0644\u0644\u0623\u0628 \u0627\u0644\u0628\u0627\u0642\u064a \u0648\u0644\u0627 \u0634\u064a\u0621 \u0644\u0644\u0625\u062e\u0648\u0629. \u0648\u0647\u0630\u0627 \u0627\u0644\u062a\u0642\u0633\u064a\u0645 \u0644\u0644\u062a\u0631\u0643\u0629 \u0625\u0646\u0645\u0627 \u064a\u0643\u0648\u0646 \u0628\u0639\u062f \u0625\u062e\u0631\u0627\u062c \u0648\u0635\u064a\u0629 \u0627\u0644\u0645\u064a\u062a \u0641\u064a \u062d\u062f\u0648\u062f \u0627\u0644\u062b\u0644\u062b \u0623\u0648 \u0625\u062e\u0631\u0627\u062c \u0645\u0627 \u0639\u0644\u064a\u0647 \u0645\u0646 \u062f\u064e\u064a\u0652\u0646. \u0622\u0628\u0627\u0624\u0643\u0645 \u0648\u0623\u0628\u0652\u0646\u0627\u0624\u0643\u0645 \u0627\u0644\u0630\u064a\u0646 \u0641\u064f\u0631\u0650\u0636 \u0644\u0647\u0645 \u0627\u0644\u0625\u0631\u062b \u0644\u0627 \u062a\u0639\u0631\u0641\u0648\u0646 \u0623\u064a\u0647\u0645 \u0623\u0642\u0631\u0628 \u0644\u0643\u0645 \u0646\u0641\u0639\u064b\u0627 \u0641\u064a \u062f\u0646\u064a\u0627\u0643\u0645 \u0648\u0623\u062e\u0631\u0627\u0643\u0645\u060c \u0641\u0644\u0627 \u062a\u0641\u0636\u0644\u0648\u0627 \u0648\u0627\u062d\u062f\u064b\u0627 \u0645\u0646\u0647\u0645 \u0639\u0644\u0649 \u0627\u0644\u0622\u062e\u0631. \u0647\u0630\u0627 \u0627\u0644\u0630\u064a \u0623\u0648\u0635\u064a\u062a\u0643\u0645 \u0628\u0647 \u0645\u0641\u0631\u0648\u0636 \u0639\u0644\u064a\u0643\u0645 \u0645\u0646 \u0627\u0644\u0644\u0647. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0643\u0627\u0646 \u0639\u0644\u064a\u0645\u064b\u0627 \u0628\u062e\u0644\u0642\u0647\u060c \u062d\u0643\u064a\u0645\u064b\u0627 \u0641\u064a\u0645\u0627 \u0634\u0631\u0639\u0647 \u0644\u0647\u0645.","4:12":"\u0648\u0644\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u062c\u0627\u0644- \u0646\u0635\u0641 \u0645\u0627 \u062a\u0631\u0643 \u0623\u0632\u0648\u0627\u062c\u0643\u0645 \u0628\u0639\u062f \u0648\u0641\u0627\u062a\u0647\u0646 \u0625\u0646 \u0644\u0645 \u064a\u0643\u0646 \u0644\u0647\u0646 \u0648\u0644\u062f \u0630\u0643\u0631\u064b\u0627 \u0643\u0627\u0646 \u0623\u0648 \u0623\u0646\u062b\u0649\u060c \u0641\u0625\u0646 \u0643\u0627\u0646 \u0644\u0647\u0646 \u0648\u0644\u062f \u0641\u0644\u0643\u0645 \u0627\u0644\u0631\u0628\u0639 \u0645\u0645\u0627 \u062a\u0631\u0643\u0646\u060c \u062a\u0631\u062b\u0648\u0646\u0647 \u0645\u0646 \u0628\u0639\u062f \u0625\u0646\u0641\u0627\u0630 \u0648\u0635\u064a\u062a\u0647\u0646 \u0627\u0644\u062c\u0627\u0626\u0632\u0629\u060c \u0623\u0648 \u0645\u0627 \u064a\u0643\u0648\u0646 \u0639\u0644\u064a\u0647\u0646 \u0645\u0646 \u062f\u064e\u064a\u0652\u0646 \u0644\u0645\u0633\u062a\u062d\u0642\u064a\u0647. \u0648\u0644\u0623\u0632\u0648\u0627\u062c\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u062c\u0627\u0644- \u0627\u0644\u0631\u0628\u0639 \u0645\u0645\u0627 \u062a\u0631\u0643\u062a\u0645\u060c \u0625\u0646 \u0644\u0645 \u064a\u0643\u0646 \u0644\u0643\u0645 \u0627\u0628\u0646 \u0623\u0648 \u0627\u0628\u0646\u0629 \u0645\u0646\u0647\u0646 \u0623\u0648 \u0645\u0646 \u063a\u064a\u0631\u0647\u0646\u060c \u0641\u0625\u0646 \u0643\u0627\u0646 \u0644\u0643\u0645 \u0627\u0628\u0646 \u0623\u0648 \u0627\u0628\u0646\u0629 \u0641\u0644\u0647\u0646 \u0627\u0644\u062b\u0645\u0646 \u0645\u0645\u0627 \u062a\u0631\u0643\u062a\u0645\u060c \u064a\u0642\u0633\u0645 \u0627\u0644\u0631\u0628\u0639 \u0623\u0648 \u0627\u0644\u062b\u0645\u0646 \u0628\u064a\u0646\u0647\u0646\u060c \u0641\u0625\u0646 \u0643\u0627\u0646\u062a \u0632\u0648\u062c\u0629 \u0648\u0627\u062d\u062f\u0629 \u0643\u0627\u0646 \u0647\u0630\u0627 \u0645\u064a\u0631\u0627\u062b\u064b\u0627 \u0644\u0647\u0627\u060c \u0645\u0646 \u0628\u0639\u062f \u0625\u0646\u0641\u0627\u0630 \u0645\u0627 \u0643\u0646\u062a\u0645 \u0623\u0648\u0635\u064a\u062a\u0645 \u0628\u0647 \u0645\u0646 \u0627\u0644\u0648\u0635\u0627\u064a\u0627 \u0627\u0644\u062c\u0627\u0626\u0632\u0629\u060c \u0623\u0648 \u0642\u0636\u0627\u0621 \u0645\u0627 \u064a\u0643\u0648\u0646 \u0639\u0644\u064a\u0643\u0645 \u0645\u0646 \u062f\u064e\u064a\u0652\u0646. \u0648\u0625\u0646 \u0645\u0627\u062a \u0631\u062c\u0644 \u0623\u0648 \u0627\u0645\u0631\u0627\u0629 \u0648\u0644\u064a\u0633 \u0644\u0647 \u0623\u0648 \u0644\u0647\u0627 \u0648\u0644\u062f \u0648\u0644\u0627 \u0648\u0627\u0644\u062f\u060c \u0648\u0644\u0647 \u0623\u0648 \u0644\u0647\u0627 \u0623\u062e \u0623\u0648 \u0623\u062e\u062a \u0645\u0646 \u0623\u0645 \u0641\u0644\u0643\u0644 \u0648\u0627\u062d\u062f \u0645\u0646\u0647\u0645\u0627 \u0627\u0644\u0633\u062f\u0633. \u0641\u0625\u0646 \u0643\u0627\u0646 \u0627\u0644\u0625\u062e\u0648\u0629 \u0623\u0648 \u0627\u0644\u0623\u062e\u0648\u0627\u062a \u0644\u0623\u0645 \u0623\u0643\u062b\u0631 \u0645\u0646 \u0630\u0644\u0643 \u0641\u0647\u0645 \u0634\u0631\u0643\u0627\u0621 \u0641\u064a \u0627\u0644\u062b\u0644\u062b \u064a\u0642\u0633\u0645 \u0628\u064a\u0646\u0647\u0645 \u0628\u0627\u0644\u0633\u0648\u064a\u0629 \u0644\u0627 \u0641\u0631\u0642 \u0628\u064a\u0646 \u0627\u0644\u0630\u0643\u0631 \u0648\u0627\u0644\u0623\u0646\u062b\u0649\u060c \u0648\u0647\u0630\u0627 \u0627\u0644\u0630\u064a \u0641\u0631\u0636\u0647 \u0627\u0644\u0644\u0647 \u0644\u0644\u0625\u062e\u0648\u0629 \u0648\u0627\u0644\u0623\u062e\u0648\u0627\u062a \u0644\u0623\u0645 \u064a\u0623\u062e\u0630\u0648\u0646\u0647 \u0645\u064a\u0631\u0627\u062b\u064b\u0627 \u0644\u0647\u0645 \u0645\u0646 \u0628\u0639\u062f \u0625\u0646\u0641\u0627\u0630 \u0648\u0635\u064a\u062a\u0647 \u0625\u0646 \u0643\u0627\u0646 \u0642\u062f \u0623\u0648\u0635\u0649 \u0628\u0634\u064a\u0621\u060c \u0623\u0648 \u0642\u0636\u0627\u0621 \u062f\u064a\u0648\u0646 \u0627\u0644\u0645\u064a\u062a\u060c \u0644\u0627 \u0636\u0631\u0631 \u0641\u064a\u0647 \u0639\u0644\u0649 \u0627\u0644\u0648\u0631\u062b\u0629. \u0628\u0647\u0630\u0627 \u0623\u0648\u0635\u0627\u0643\u0645 \u0631\u0628\u0643\u0645 \u0648\u0635\u064a\u0629 \u0646\u0627\u0641\u0639\u0629 \u0644\u0643\u0645. \u0648\u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0645 \u0628\u0645\u0627 \u064a\u0635\u0644\u062d \u062e\u0644\u0642\u0647\u060c \u062d\u0644\u064a\u0645 \u0644\u0627 \u064a\u0639\u0627\u062c\u0644\u0647\u0645 \u0628\u0627\u0644\u0639\u0642\u0648\u0628\u0629.","4:13":"\u062a\u0644\u0643 \u0627\u0644\u0623\u062d\u0643\u0627\u0645 \u0627\u0644\u0625\u0644\u0647\u064a\u0629 \u0627\u0644\u062a\u064a \u0634\u0631\u0639\u0647\u0627 \u0627\u0644\u0644\u0647 \u0641\u064a \u0627\u0644\u064a\u062a\u0627\u0645\u0649 \u0648\u0627\u0644\u0646\u0633\u0627\u0621 \u0648\u0627\u0644\u0645\u0648\u0627\u0631\u064a\u062b\u060c \u0634\u0631\u0627\u0626\u0639\u0647 \u0627\u0644\u062f\u0627\u0644\u0629 \u0639\u0644\u0649 \u0623\u0646\u0647\u0627 \u0645\u0650\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0627\u0644\u0639\u0644\u064a\u0645 \u0627\u0644\u062d\u0643\u064a\u0645. \u0648\u0645\u064e\u0646 \u064a\u0637\u0639 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0641\u064a\u0645\u0627 \u0634\u0631\u0639 \u0644\u0639\u0628\u0627\u062f\u0647 \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0623\u062d\u0643\u0627\u0645 \u0648\u063a\u064a\u0631\u0647\u0627\u060c \u064a\u062f\u062e\u0644\u0647 \u062c\u0646\u0627\u062a \u0643\u062b\u064a\u0631\u0629 \u0627\u0644\u0623\u0634\u062c\u0627\u0631 \u0648\u0627\u0644\u0642\u0635\u0648\u0631\u060c \u062a\u062c\u0631\u064a \u0645\u0646 \u062a\u062d\u062a\u0647\u0627 \u0627\u0644\u0623\u0646\u0647\u0627\u0631 \u0628\u0645\u064a\u0627\u0647\u0647\u0627 \u0627\u0644\u0639\u0630\u0628\u0629\u060c \u0648\u0647\u0645 \u0628\u0627\u0642\u0648\u0646 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0646\u0639\u064a\u0645\u060c \u0644\u0627 \u064a\u062e\u0631\u062c\u0648\u0646 \u0645\u0646\u0647\u060c \u0648\u0630\u0644\u0643 \u0627\u0644\u062b\u0648\u0627\u0628 \u0647\u0648 \u0627\u0644\u0641\u0644\u0627\u062d \u0627\u0644\u0639\u0638\u064a\u0645.","4:14":"\u0648\u0645\u064e\u0646 \u064a\u064e\u0639\u0652\u0635\u0650 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0628\u0625\u0646\u0643\u0627\u0631\u0647 \u0644\u0623\u062d\u0643\u0627\u0645 \u0627\u0644\u0644\u0647\u060c \u0648\u062a\u062c\u0627\u0648\u0632\u0647 \u0645\u0627 \u0634\u0631\u0639\u0647 \u0627\u0644\u0644\u0647 \u0644\u0639\u0628\u0627\u062f\u0647 \u0628\u062a\u063a\u064a\u064a\u0631\u0647\u0627\u060c \u0623\u0648 \u062a\u0639\u0637\u064a\u0644 \u0627\u0644\u0639\u0645\u0644 \u0628\u0647\u0627\u060c \u064a\u062f\u062e\u0644\u0647 \u0646\u0627\u0631\u064b\u0627 \u0645\u0627\u0643\u062b\u064b\u0627 \u0641\u064a\u0647\u0627\u060c \u0648\u0644\u0647 \u0639\u0630\u0627\u0628 \u064a\u062e\u0632\u064a\u0647 \u0648\u064a\u0647\u064a\u0646\u0647.","4:15":"\u0648\u0627\u0644\u0644\u0627\u062a\u064a \u064a\u0632\u0646\u064a\u0646 \u0645\u0646 \u0646\u0633\u0627\u0626\u0643\u0645\u060c \u0641\u0627\u0633\u062a\u0634\u0647\u062f\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0648\u0644\u0627\u0629 \u0648\u0627\u0644\u0642\u0636\u0627\u0629- \u0639\u0644\u064a\u0647\u0646 \u0623\u0631\u0628\u0639\u0629 \u0631\u062c\u0627\u0644 \u0639\u062f\u0648\u0644 \u0645\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646\u060c \u0641\u0625\u0646 \u0634\u0647\u062f\u0648\u0627 \u0639\u0644\u064a\u0647\u0646 \u0628\u0630\u0644\u0643 \u0641\u0627\u062d\u0628\u0633\u0648\u0647\u0646 \u0641\u064a \u0627\u0644\u0628\u064a\u0648\u062a \u062d\u062a\u0649 \u062a\u0646\u062a\u0647\u064a \u062d\u064a\u0627\u062a\u0647\u0646 \u0628\u0627\u0644\u0645\u0648\u062a\u060c \u0623\u0648 \u064a\u062c\u0639\u0644 \u0627\u0644\u0644\u0647 \u0644\u0647\u0646 \u0637\u0631\u064a\u0642\u064b\u0627 \u0644\u0644\u062e\u0644\u0627\u0635 \u0645\u0646 \u0630\u0644\u0643.","4:16":"\u0648\u0627\u0644\u0644\u0630\u0627\u0646 \u064a\u0642\u0639\u0627\u0646 \u0641\u064a \u0641\u0627\u062d\u0634\u0629 \u0627\u0644\u0632\u0646\u0649\u060c \u0641\u0622\u0630\u064f\u0648\u0647\u0645\u0627 \u0628\u0627\u0644\u0636\u0631\u0628 \u0648\u0627\u0644\u0647\u062c\u0631 \u0648\u0627\u0644\u062a\u0648\u0628\u064a\u062e\u060c \u0641\u0625\u0646 \u062a\u0627\u0628\u0627 \u0639\u0645\u0651\u064e\u0627 \u0648\u0642\u0639 \u0645\u0646\u0647\u0645\u0627 \u0648\u0623\u0635\u0644\u062d\u0627 \u0628\u0645\u0627 \u064a\u0642\u062f\u0651\u0650\u0645\u0627\u0646 \u0645\u0646 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0635\u0627\u0644\u062d\u0629 \u0641\u0627\u0635\u0641\u062d\u0648\u0627 \u0639\u0646 \u0623\u0630\u0627\u0647\u0645\u0627. \u0648\u064a\u0633\u062a\u0641\u0627\u062f \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0629 \u0648\u0627\u0644\u062a\u064a \u0642\u0628\u0644\u0647\u0627 \u0623\u0646 \u0627\u0644\u0631\u062c\u0627\u0644 \u0625\u0630\u0627 \u0641\u0639\u0644\u0648\u0627 \u0627\u0644\u0641\u0627\u062d\u0634\u0629 \u064a\u064f\u0624\u0652\u0630\u064e\u0648\u0652\u0646\u060c \u0648\u0627\u0644\u0646\u0633\u0627\u0621 \u064a\u064f\u062d\u0652\u0628\u064e\u0633\u0652\u0646\u064e \u0648\u064a\u064f\u0624\u0630\u064e\u064a\u0652\u0646\u064e\u060c \u0641\u0627\u0644\u062d\u0628\u0633 \u063a\u0627\u064a\u062a\u0629 \u0627\u0644\u0645\u0648\u062a\u060c \u0648\u0627\u0644\u0623\u0630\u064a\u0629 \u0646\u0647\u0627\u064a\u062a\u0647\u0627 \u0625\u0644\u0649 \u0627\u0644\u062a\u0648\u0628\u0629 \u0648\u0627\u0644\u0635\u0644\u0627\u062d. \u0648\u0643\u0627\u0646 \u0647\u0630\u0627 \u0641\u064a \u0635\u062f\u0631 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u062b\u0645 \u0646\u064f\u0633\u062e \u0628\u0645\u0627 \u0634\u0631\u0639 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0647\u0648 \u0627\u0644\u0631\u062c\u0645 \u0644\u0644\u0645\u062d\u0635\u0646 \u0648\u0627\u0644\u0645\u062d\u0635\u0646\u0629\u060c \u0648\u0647\u0645\u0627 \u0627\u0644\u062d\u0631\u0627\u0646 \u0627\u0644\u0628\u0627\u0644\u063a\u0627\u0646 \u0627\u0644\u0639\u0627\u0642\u0644\u0627\u0646\u060c \u0627\u0644\u0644\u0630\u0627\u0646 \u062c\u0627\u0645\u0639\u0627 \u0641\u064a \u0646\u0643\u0627\u062d \u0635\u062d\u064a\u062d\u060c \u0648\u0627\u0644\u062c\u0644\u062f\u064f \u0645\u0627\u0626\u0629 \u062c\u0644\u062f\u0629\u060c \u0648\u062a\u063a\u0631\u064a\u0628 \u0639\u0627\u0645 \u0644\u063a\u064a\u0631\u0647\u0645\u0627. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0643\u0627\u0646 \u062a\u0648\u0627\u0628\u0627 \u0639\u0644\u0649 \u0639\u0628\u0627\u062f\u0647 \u0627\u0644\u062a\u0627\u0626\u0628\u064a\u0646\u060c \u0631\u062d\u064a\u0645\u064b\u0627 \u0628\u0647\u0645.","4:17":"\u0625\u0646\u0651\u064e\u0645\u0627 \u064a\u0642\u0628\u0644 \u0627\u0644\u0644\u0647 \u0627\u0644\u062a\u0648\u0628\u0629 \u0645\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u0631\u062a\u0643\u0628\u0648\u0646 \u0627\u0644\u0645\u0639\u0627\u0635\u064a \u0648\u0627\u0644\u0630\u0646\u0648\u0628 \u0628\u062c\u0647\u0644 \u0645\u0646\u0647\u0645 \u0644\u0639\u0627\u0642\u0628\u062a\u0647\u0627\u060c \u0648\u0625\u064a\u062c\u0627\u0628\u0647\u0627 \u0644\u0633\u062e\u0637 \u0627\u0644\u0644\u0647 -\u0641\u0643\u0644 \u0639\u0627\u0635 \u0644\u0644\u0647 \u0645\u062e\u0637\u0626\u064b\u0627 \u0623\u0648 \u0645\u062a\u0639\u0645\u0651\u0650\u062f\u064b\u0627 \u0641\u0647\u0648 \u062c\u0627\u0647\u0644 \u0628\u0647\u0630\u0627 \u0627\u0644\u0627\u0639\u062a\u0628\u0627\u0631\u060c \u0648\u0625\u0646 \u0643\u0627\u0646 \u0639\u0627\u0644\u0645\u064b\u0627 \u0628\u0627\u0644\u062a\u062d\u0631\u064a\u0645- \u062b\u0645 \u064a\u0631\u062c\u0639\u0648\u0646 \u0625\u0644\u0649 \u0631\u0628\u0647\u0645 \u0628\u0627\u0644\u0625\u0646\u0627\u0628\u0629 \u0648\u0627\u0644\u0637\u0627\u0639\u0629 \u0642\u0628\u0644 \u0645\u0639\u0627\u064a\u0646\u0629 \u0627\u0644\u0645\u0648\u062a\u060c \u0641\u0623\u0648\u0644\u0626\u0643 \u064a\u0642\u0628\u0644 \u0627\u0644\u0644\u0647 \u062a\u0648\u0628\u062a\u0647\u0645. \u0648\u0643\u0627\u0646 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0645\u064b\u0627 \u0628\u062e\u0644\u0642\u0647\u060c \u062d\u0643\u064a\u0645\u064b\u0627 \u0641\u064a \u062a\u062f\u0628\u064a\u0631\u0647 \u0648\u062a\u0642\u062f\u064a\u0631\u0647.","4:18":"\u0648\u0644\u064a\u0633 \u0642\u064e\u0628\u0648\u0644 \u0627\u0644\u062a\u0648\u0628\u0629 \u0644\u0644\u0630\u064a\u0646 \u064a\u064f\u0635\u0650\u0631\u0651\u064f\u0648\u0646 \u0639\u0644\u0649 \u0627\u0631\u062a\u0643\u0627\u0628 \u0627\u0644\u0645\u0639\u0627\u0635\u064a\u060c \u0648\u0644\u0627 \u064a\u0631\u062c\u0639\u0648\u0646 \u0625\u0644\u0649 \u0631\u0628\u0647\u0645 \u0625\u0644\u0649 \u0623\u0646 \u062a\u0623\u062a\u064a\u0647\u0645 \u0633\u0643\u0631\u0627\u062a \u0627\u0644\u0645\u0648\u062a\u060c \u0641\u064a\u0642\u0648\u0644 \u0623\u062d\u062f\u0647\u0645: \u0625\u0646\u064a \u062a\u0628\u062a \u0627\u0644\u0622\u0646\u060c \u0643\u0645\u0627 \u0644\u0627 \u062a\u064f\u0642\u0628\u0644 \u062a\u0648\u0628\u0629 \u0627\u0644\u0630\u064a\u0646 \u064a\u0645\u0648\u062a\u0648\u0646 \u0648\u0647\u0645 \u062c\u0627\u062d\u062f\u0648\u0646\u060c \u0645\u0646\u0643\u0631\u0648\u0646 \u0644\u0648\u062d\u062f\u0627\u0646\u064a\u0629 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0627\u0644\u0629 \u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645. \u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0645\u0635\u0631\u0651\u064f\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u0645\u0639\u0627\u0635\u064a \u0625\u0644\u0649 \u0623\u0646 \u0645\u0627\u062a\u0648\u0627\u060c \u0648\u0627\u0644\u062c\u0627\u062d\u062f\u0648\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u0645\u0648\u062a\u0648\u0646 \u0648\u0647\u0645 \u0643\u0641\u0627\u0631\u060c \u0623\u0639\u062a\u062f\u0646\u0627 \u0644\u0647\u0645 \u0639\u0630\u0627\u0628\u064b\u0627 \u0645\u0648\u062c\u0639\u064b\u0627.","4:19":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0644\u0627 \u064a\u062c\u0648\u0632 \u0644\u0643\u0645 \u0623\u0646 \u062a\u062c\u0639\u0644\u0648\u0627 \u0646\u0633\u0627\u0621 \u0622\u0628\u0627\u0626\u0643\u0645 \u0645\u0646 \u062c\u0645\u0644\u0629 \u062a\u064e\u0631\u0650\u0643\u062a\u0647\u0645\u060c \u062a\u062a\u0635\u0631\u0641\u0648\u0646 \u0641\u064a\u0647\u0646 \u0628\u0627\u0644\u0632\u0648\u0627\u062c \u0645\u0646\u0647\u0646\u060c \u0623\u0648 \u0627\u0644\u0645\u0646\u0639 \u0644\u0647\u0646\u060c \u0623\u0648 \u062a\u0632\u0648\u064a\u062c\u0647\u0646 \u0644\u0644\u0622\u062e\u0631\u064a\u0646\u060c \u0648\u0647\u0646 \u0643\u0627\u0631\u0647\u0627\u062a \u0644\u0630\u0644\u0643 \u0643\u0644\u0647\u060c \u0648\u0644\u0627 \u064a\u062c\u0648\u0632 \u0644\u0643\u0645 \u0623\u0646 \u062a\u0636\u0627\u0631\u0651\u064f\u0648\u0627 \u0623\u0632\u0648\u0627\u062c\u0643\u0645 \u0648\u0623\u0646\u062a\u0645 \u0643\u0627\u0631\u0647\u0648\u0646 \u0644\u0647\u0646; \u0644\u064a\u062a\u0646\u0627\u0632\u0644\u0646 \u0639\u0646 \u0628\u0639\u0636 \u0645\u0627 \u0622\u062a\u064a\u062a\u0645\u0648\u0647\u0646 \u0645\u0646 \u0645\u0647\u0631 \u0648\u0646\u062d\u0648\u0647\u060c \u0625\u0644\u0627 \u0623\u0646 \u064a\u0631\u062a\u0643\u0628\u0646 \u0623\u0645\u0631\u0627 \u0641\u0627\u062d\u0634\u0627 \u0643\u0627\u0644\u0632\u0646\u0649\u060c \u0641\u0644\u0643\u0645 \u062d\u064a\u0646\u0646\u0630 \u0625\u0645\u0633\u0627\u0643\u0647\u0646 \u062d\u062a\u0649 \u062a\u0623\u062e\u0630\u0648\u0627 \u0645\u0627 \u0623\u0639\u0637\u064a\u062a\u0645\u0648\u0647\u0646. \u0648\u0644\u062a\u0643\u0646 \u0645\u0635\u0627\u062d\u0628\u062a\u0643\u0645 \u0644\u0646\u0633\u0627\u0626\u0643\u0645 \u0645\u0628\u0646\u064a\u0629 \u0639\u0644\u0649 \u0627\u0644\u062a\u0643\u0631\u064a\u0645 \u0648\u0627\u0644\u0645\u062d\u0628\u0629\u060c \u0648\u0623\u062f\u0627\u0621 \u0645\u0627 \u0644\u0647\u0646 \u0645\u0646 \u062d\u0642\u0648\u0642. \u0641\u0625\u0646 \u0643\u0631\u0647\u062a\u0645\u0648\u0647\u0646 \u0644\u0633\u0628\u0628 \u0645\u0646 \u0627\u0644\u0623\u0633\u0628\u0627\u0628 \u0627\u0644\u062f\u0646\u064a\u0648\u064a\u0629 \u0641\u0627\u0635\u0628\u0631\u0648\u0627; \u0641\u0639\u0633\u0649 \u0623\u0646 \u062a\u0643\u0631\u0647\u0648\u0627 \u0623\u0645\u0631\u064b\u0627 \u0645\u0646 \u0627\u0644\u0623\u0645\u0648\u0631 \u0648\u064a\u0643\u0648\u0646 \u0641\u064a\u0647 \u062e\u064a\u0631 \u0643\u062b\u064a\u0631.","4:20":"\u0648\u0625\u0646 \u0623\u0631\u062f\u062a\u0645 \u0627\u0633\u062a\u0628\u062f\u0627\u0644 \u0632\u0648\u062c\u0629 \u0645\u0643\u0627\u0646 \u0623\u062e\u0631\u0649\u060c \u0648\u0643\u0646\u062a\u0645 \u0642\u062f \u0623\u0639\u0637\u064a\u062a\u0645 \u0645\u064e\u0646 \u062a\u0631\u064a\u062f\u0648\u0646 \u0637\u0644\u0627\u0642\u0647\u0627 \u0645\u0627\u0644\u0627 \u0643\u062b\u064a\u0631\u064b\u0627 \u0645\u0647\u0631\u064b\u0627 \u0644\u0647\u0627\u060c \u0641\u0644\u0627 \u064a\u062d\u0644 \u0644\u0643\u0645 \u0623\u0646 \u062a\u0623\u062e\u0630\u0648\u0627 \u0645\u0646\u0647 \u0634\u064a\u0626\u064b\u0627\u060c \u0623\u062a\u0623\u062e\u0630\u0648\u0646\u0647 \u0643\u0630\u0628\u064b\u0627 \u0648\u0627\u0641\u062a\u0631\u0627\u0621\u064b \u0648\u0627\u0636\u062d\u064b\u0627\u061f","4:21":"\u0648\u0643\u064a\u0641 \u064a\u062d\u0644\u0651\u064f \u0644\u0643\u0645 \u0623\u0646 \u062a\u0623\u062e\u0630\u0648\u0627 \u0645\u0627 \u0623\u0639\u0637\u064a\u062a\u0645\u0648\u0647\u0646 \u0645\u0646 \u0645\u0647\u0631\u060c \u0648\u0642\u062f \u0627\u0633\u062a\u0645\u062a\u0639 \u0643\u0644 \u0645\u0646\u0643\u0645\u0627 \u0628\u0627\u0644\u0622\u062e\u0631 \u0628\u0627\u0644\u062c\u0645\u0627\u0639\u060c \u0648\u0623\u062e\u064e\u0630\u0652\u0646\u064e \u0645\u0646\u0643\u0645 \u0645\u064a\u062b\u0627\u0642\u064b\u0627 \u063a\u0644\u064a\u0638\u064b\u0627 \u0645\u0646 \u0625\u0645\u0633\u0627\u0643\u0647\u0646 \u0628\u0645\u0639\u0631\u0648\u0641 \u0623\u0648 \u062a\u0633\u0631\u064a\u062d\u0647\u0646 \u0628\u0625\u062d\u0633\u0627\u0646\u061f","4:22":"\u0648\u0644\u0627 \u062a\u062a\u0632\u0648\u062c\u0648\u0627 \u0645\u064e\u0646 \u062a\u0632\u0648\u062c\u0647 \u0622\u0628\u0627\u0624\u0643\u0645 \u0645\u0646 \u0627\u0644\u0646\u0633\u0627\u0621 \u0625\u0644\u0627 \u0645\u0627 \u0642\u062f \u0633\u0644\u0641 \u0645\u0646\u0643\u0645 \u0648\u0645\u0636\u0649 \u0641\u064a \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629 \u0641\u0644\u0627 \u0645\u0624\u0627\u062e\u0630\u0629 \u0641\u064a\u0647. \u0625\u0646 \u0632\u0648\u0627\u062c \u0627\u0644\u0623\u0628\u0646\u0627\u0621 \u0645\u0646 \u0632\u0648\u062c\u0627\u062a \u0622\u0628\u0627\u0626\u0647\u0645 \u0623\u0645\u0631 \u0642\u0628\u064a\u062d \u064a\u0641\u062d\u0634 \u0648\u064a\u0639\u0638\u0645 \u0642\u0628\u062d\u0647\u060c \u0648\u0628\u063a\u064a\u0636 \u064a\u0645\u0642\u062a \u0627\u0644\u0644\u0647 \u0641\u0627\u0639\u0644\u0647\u060c \u0648\u0628\u0626\u0633 \u0637\u0631\u064a\u0642\u064b\u0627 \u0648\u0645\u0646\u0647\u062c\u064b\u0627 \u0645\u0627 \u0643\u0646\u062a\u0645 \u062a\u0641\u0639\u0644\u0648\u0646\u0647 \u0641\u064a \u062c\u0627\u0647\u0644\u064a\u062a\u0643\u0645.","4:23":"\u062d\u0631\u0651\u064e\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0646\u0643\u0627\u062d \u0623\u0645\u0647\u0627\u062a\u0643\u0645\u060c \u0648\u064a\u062f\u062e\u0644 \u0641\u064a \u0630\u0644\u0643 \u0627\u0644\u062c\u062f\u0651\u064e\u0627\u062a \u0645\u0650\u0646 \u062c\u0647\u0629 \u0627\u0644\u0623\u0628 \u0623\u0648 \u0627\u0644\u0623\u0645\u060c \u0648\u0628\u0646\u0627\u062a\u0643\u0645: \u0648\u064a\u0634\u0645\u0644 \u0628\u0646\u0627\u062a \u0627\u0644\u0623\u0648\u0644\u0627\u062f \u0648\u0625\u0646 \u0646\u0632\u0644\u0646\u060c \u0648\u0623\u062e\u0648\u0627\u062a\u0643\u0645 \u0627\u0644\u0634\u0642\u064a\u0642\u0627\u062a \u0623\u0648 \u0644\u0623\u0628 \u0623\u0648 \u0644\u0623\u0645\u060c \u0648\u0639\u0645\u0627\u062a\u0643\u0645: \u0623\u062e\u0648\u0627\u062a \u0622\u0628\u0627\u0626\u0643\u0645 \u0648\u0623\u062c\u062f\u0627\u062f\u0643\u0645\u060c \u0648\u062e\u0627\u0644\u0627\u062a\u0643\u0645: \u0623\u062e\u0648\u0627\u062a \u0623\u0645\u0647\u0627\u062a\u0643\u0645 \u0648\u062c\u062f\u0627\u062a\u0643\u0645\u060c \u0648\u0628\u0646\u0627\u062a \u0627\u0644\u0623\u062e\u060c \u0648\u0628\u0646\u0627\u062a \u0627\u0644\u0623\u062e\u062a: \u0648\u064a\u062f\u062e\u0644 \u0641\u064a \u0630\u0644\u0643 \u0623\u0648\u0644\u0627\u062f\u0647\u0646\u060c \u0648\u0623\u0645\u0647\u0627\u062a\u0643\u0645 \u0627\u0644\u0644\u0627\u062a\u064a \u0623\u0631\u0636\u0639\u0646\u0643\u0645\u060c \u0648\u0623\u062e\u0648\u0627\u062a\u0643\u0645 \u0645\u0646 \u0627\u0644\u0631\u0636\u0627\u0639\u0629 -\u0648\u0642\u062f \u062d\u0631\u0651\u064e\u0645 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0645\u0646 \u0627\u0644\u0631\u0636\u0627\u0639 \u0645\u0627 \u064a\u062d\u0631\u0645 \u0645\u0646 \u0627\u0644\u0646\u0633\u0628- \u0648\u0623\u0645\u0647\u0627\u062a \u0646\u0633\u0627\u0626\u0643\u0645\u060c \u0633\u0648\u0627\u0621 \u062f\u062e\u0644\u062a\u0645 \u0628\u0646\u0633\u0627\u0626\u0643\u0645\u060c \u0623\u0645 \u0644\u0645 \u062a\u062f\u062e\u0644\u0648\u0627 \u0628\u0647\u0646\u060c \u0648\u0628\u0646\u0627\u062a \u0646\u0633\u0627\u0626\u0643\u0645 \u0645\u0646 \u063a\u064a\u0631\u0643\u0645 \u0627\u0644\u0644\u0627\u062a\u064a \u064a\u062a\u0631\u0628\u0651\u064e\u064a\u0652\u0646\u064e \u063a\u0627\u0644\u0628\u064b\u0627 \u0641\u064a \u0628\u064a\u0648\u062a\u0643\u0645 \u0648\u062a\u062d\u062a \u0631\u0639\u0627\u064a\u062a\u0643\u0645\u060c \u0648\u0647\u0646 \u0645\u064f\u062d\u0631\u0651\u064e\u0645\u064e\u0627\u062a \u0648\u0625\u0646 \u0644\u0645 \u064a\u0643\u0646\u0651\u064e \u0641\u064a \u062d\u062c\u0648\u0631\u0643\u0645\u060c \u0648\u0644\u0643\u0646 \u0628\u0634\u0631\u0637 \u0627\u0644\u062f\u062e\u0648\u0644 \u0628\u0623\u0645\u0647\u0627\u062a\u0647\u0646\u060c \u0641\u0625\u0646 \u0644\u0645 \u062a\u0643\u0648\u0646\u0648\u0627 \u062f\u062e\u0644\u062a\u0645 \u0628\u0623\u0645\u0647\u0627\u062a\u0647\u0646 \u0648\u0637\u0644\u0642\u062a\u0645\u0648\u0647\u0646 \u0623\u0648 \u0645\u062a\u0652\u0646\u064e \u0642\u0628\u0644 \u0627\u0644\u062f\u062e\u0648\u0644 \u0641\u0644\u0627 \u062c\u0646\u0627\u062d \u0639\u0644\u064a\u0643\u0645 \u0623\u0646 \u062a\u0646\u0643\u062d\u0648\u0647\u0646\u060c \u0643\u0645\u0627 \u062d\u0631\u0651\u064e\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0623\u0646 \u062a\u0646\u0643\u062d\u0648\u0627 \u0632\u0648\u062c\u0627\u062a \u0623\u0628\u0646\u0627\u0626\u0643\u0645 \u0627\u0644\u0630\u064a\u0646 \u0645\u0646 \u0623\u0635\u0644\u0627\u0628\u0643\u0645\u060c \u0648\u0645\u0646 \u0623\u064f\u0644\u062d\u0642 \u0628\u0647\u0645 \u0645\u0650\u0646 \u0623\u0628\u0646\u0627\u0626\u0643\u0645 \u0645\u0646 \u0627\u0644\u0631\u0636\u0627\u0639\u060c \u0648\u0647\u0630\u0627 \u0627\u0644\u062a\u062d\u0631\u064a\u0645 \u064a\u0643\u0648\u0646 \u0628\u0627\u0644\u0639\u0642\u062f \u0639\u0644\u064a\u0647\u0627\u060c \u062f\u062e\u0644 \u0627\u0644\u0627\u0628\u0646 \u0628\u0647\u0627 \u0623\u0645 \u0644\u0645 \u064a\u062f\u062e\u0644\u060c \u0648\u062d\u0631\u0651\u064e\u0645 \u0639\u0644\u064a\u0643\u0645 \u0643\u0630\u0644\u0643 \u0627\u0644\u062c\u0645\u0639 \u0641\u064a \u0648\u0642\u062a \u0648\u0627\u062d\u062f \u0628\u064a\u0646 \u0627\u0644\u0623\u062e\u062a\u064a\u0646 \u0628\u0646\u0633\u0628 \u0623\u0648 \u0631\u0636\u0627\u0639 \u0625\u0644\u0627 \u0645\u0627 \u0642\u062f \u0633\u0644\u0641 \u0648\u0645\u0636\u0649 \u0645\u0646\u0643\u0645 \u0641\u064a \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629. \u0648\u0644\u0627 \u064a\u062c\u0648\u0632 \u0643\u0630\u0644\u0643 \u0627\u0644\u062c\u0645\u0639 \u0628\u064a\u0646 \u0627\u0644\u0645\u0631\u0623\u0629 \u0648\u0639\u0645\u062a\u0647\u0627 \u0623\u0648 \u062e\u0627\u0644\u062a\u0647\u0627 \u0643\u0645\u0627 \u062c\u0627\u0621 \u0641\u064a \u0627\u0644\u0633\u0646\u0629. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0643\u0627\u0646 \u063a\u0641\u0648\u0631\u064b\u0627 \u0644\u0644\u0645\u0630\u0646\u0628\u064a\u0646 \u0625\u0630\u0627 \u062a\u0627\u0628\u0648\u0627\u060c \u0631\u062d\u064a\u0645\u064b\u0627 \u0628\u0647\u0645\u060c \u0641\u0644\u0627 \u064a\u0643\u0644\u0641\u0647\u0645 \u0645\u0627 \u0644\u0627 \u064a\u0637\u064a\u0642\u0648\u0646.","4:24":"\u0648\u064a\u062d\u0631\u0645 \u0639\u0644\u064a\u0643\u0645 \u0646\u0643\u0627\u062d \u0627\u0644\u0645\u062a\u0632\u0648\u062c\u0627\u062a \u0645\u0646 \u0627\u0644\u0646\u0633\u0627\u0621\u060c \u0625\u0644\u0627 \u0645\u064e\u0646\u0652 \u0633\u064e\u0628\u064e\u064a\u0652\u062a\u064f\u0645 \u0645\u0646\u0647\u0646 \u0641\u064a \u0627\u0644\u062c\u0647\u0627\u062f\u060c \u0641\u0625\u0646\u0647 \u064a\u062d\u0644 \u0644\u0643\u0645 \u0646\u0643\u0627\u062d\u0647\u0646\u060c \u0628\u0639\u062f \u0627\u0633\u062a\u0628\u0631\u0627\u0621 \u0623\u0631\u062d\u0627\u0645\u0647\u0646 \u0628\u062d\u064a\u0636\u0629\u060c \u0643\u062a\u0628 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u062a\u062d\u0631\u064a\u0645 \u0646\u0643\u0627\u062d \u0647\u0624\u0644\u0627\u0621\u060c \u0648\u0623\u062c\u0627\u0632 \u0644\u0643\u0645 \u0646\u0643\u0627\u062d \u0645\u064e\u0646 \u0633\u0648\u0627\u0647\u0646\u060c \u0645\u0645\u0651\u064e\u0627 \u0623\u062d\u0644\u0647 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0623\u0646 \u062a\u0637\u0644\u0628\u0648\u0627 \u0628\u0623\u0645\u0648\u0627\u0644\u0643\u0645 \u0627\u0644\u0639\u0641\u0629 \u0639\u0646 \u0627\u0642\u062a\u0631\u0627\u0641 \u0627\u0644\u062d\u0631\u0627\u0645. \u0641\u0645\u0627 \u0627\u0633\u062a\u0645\u062a\u0639\u062a\u0645 \u0628\u0647 \u0645\u0646\u0647\u0646 \u0628\u0627\u0644\u0646\u0643\u0627\u062d \u0627\u0644\u0635\u062d\u064a\u062d\u060c \u0641\u0623\u0639\u0637\u0648\u0647\u0646 \u0645\u0647\u0648\u0631\u0647\u0646\u060c \u0627\u0644\u062a\u064a \u0641\u0631\u0636 \u0627\u0644\u0644\u0647 \u0644\u0647\u0646 \u0639\u0644\u064a\u0643\u0645\u060c \u0648\u0644\u0627 \u0625\u062b\u0645 \u0639\u0644\u064a\u0643\u0645 \u0641\u064a\u0645\u0627 \u062a\u0645\u0651\u064e \u0627\u0644\u062a\u0631\u0627\u0636\u064a \u0628\u0647 \u0628\u064a\u0646\u0643\u0645\u060c \u0645\u0646 \u0627\u0644\u0632\u064a\u0627\u062f\u0629 \u0623\u0648 \u0627\u0644\u0646\u0642\u0635\u0627\u0646 \u0641\u064a \u0627\u0644\u0645\u0647\u0631\u060c \u0628\u0639\u062f \u062b\u0628\u0648\u062a \u0627\u0644\u0641\u0631\u064a\u0636\u0629. \u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0643\u0627\u0646 \u0639\u0644\u064a\u0645\u064b\u0627 \u0628\u0623\u0645\u0648\u0631 \u0639\u0628\u0627\u062f\u0647\u060c \u062d\u0643\u064a\u0645\u0627 \u0641\u064a \u0623\u062d\u0643\u0627\u0645\u0647 \u0648\u062a\u062f\u0628\u064a\u0631\u0647.","4:25":"\u0648\u0645\u0646 \u0644\u0627 \u0642\u062f\u0631\u0629 \u0644\u0647 \u0639\u0644\u0649 \u0645\u0647\u0648\u0631 \u0627\u0644\u062d\u0631\u0627\u0626\u0631 \u0627\u0644\u0645\u0624\u0645\u0646\u0627\u062a\u060c \u0641\u0644\u0647 \u0623\u0646 \u064a\u0646\u0643\u062d \u063a\u064a\u0631\u0647\u0646\u060c \u0645\u0646 \u0641\u062a\u064a\u0627\u062a\u0643\u0645 \u0627\u0644\u0645\u0624\u0645\u0646\u0627\u062a \u0627\u0644\u0645\u0645\u0644\u0648\u0643\u0627\u062a. \u0648\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0647\u0648 \u0627\u0644\u0639\u0644\u064a\u0645 \u0628\u062d\u0642\u064a\u0642\u0629 \u0625\u064a\u0645\u0627\u0646\u0643\u0645\u060c \u0628\u0639\u0636\u0643\u0645 \u0645\u0646 \u0628\u0639\u0636\u060c \u0641\u062a\u0632\u0648\u062c\u0648\u0647\u0646 \u0628\u0645\u0648\u0627\u0641\u0642\u0629 \u0623\u0647\u0644\u0647\u0646\u060c \u0648\u0623\u0639\u0637\u0648\u0647\u0646 \u0645\u0647\u0648\u0631\u0647\u0646 \u0639\u0644\u0649 \u0645\u0627 \u062a\u0631\u0627\u0636\u064a\u062a\u0645 \u0628\u0647 \u0639\u0646 \u0637\u064a\u0628 \u0646\u0641\u0633 \u0645\u0646\u0643\u0645\u060c \u0645\u062a\u0639\u0641\u0641\u0627\u062a \u0639\u0646 \u0627\u0644\u062d\u0631\u0627\u0645\u060c \u063a\u064a\u0631 \u0645\u062c\u0627\u0647\u0631\u0627\u062a \u0628\u0627\u0644\u0632\u0646\u0649\u060c \u0648\u0644\u0627 \u0645\u0633\u0631\u0627\u062a \u0628\u0647 \u0628\u0627\u062a\u062e\u0627\u0630 \u0623\u062e\u0644\u0627\u0621\u060c \u0641\u0625\u0630\u0627 \u062a\u0632\u0648\u062c\u0646 \u0648\u0623\u062a\u064a\u0646 \u0628\u0641\u0627\u062d\u0634\u0629 \u0627\u0644\u0632\u0646\u0649 \u0641\u0639\u0644\u064a\u0647\u0646 \u0645\u0646 \u0627\u0644\u062d\u062f\u0651\u0650 -\u0648\u0647\u0648 \u0627\u0644\u062c\u064e\u0644\u0652\u062f\u064f \u0644\u0627 \u0627\u0644\u0631\u0651\u064e\u062c\u0652\u0645\u064f- \u0646\u0635\u0641 \u0645\u0627 \u0639\u0644\u0649 \u0627\u0644\u062d\u0631\u0627\u0626\u0631. \u0630\u0644\u0643 \u0627\u0644\u0630\u064a \u0623\u0628\u064a\u062d \u0645\u0650\u0646 \u0646\u0643\u0627\u062d \u0627\u0644\u0625\u0645\u0627\u0621 \u0628\u0627\u0644\u0635\u0641\u0629 \u0627\u0644\u0645\u062a\u0642\u062f\u0645\u0629 \u0625\u0646\u0645\u0627 \u0623\u0628\u064a\u062d \u0644\u0645\u0646 \u062e\u0627\u0641 \u0639\u0644\u0649 \u0646\u0641\u0633\u0647 \u0627\u0644\u0648\u0642\u0648\u0639 \u0641\u064a \u0627\u0644\u0632\u0646\u0649\u060c \u0648\u0634\u0642 \u0639\u0644\u064a\u0647 \u0627\u0644\u0635\u0628\u0631 \u0639\u0646 \u0627\u0644\u062c\u0645\u0627\u0639\u060c \u0648\u0627\u0644\u0635\u0628\u0631 \u0639\u0646 \u0646\u0643\u0627\u062d \u0627\u0644\u0625\u0645\u0627\u0621 \u0645\u0639 \u0627\u0644\u0639\u0641\u0629 \u0623\u0648\u0644\u0649 \u0648\u0623\u0641\u0636\u0644. \u0648\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u063a\u0641\u0648\u0631 \u0644\u0643\u0645\u060c \u0631\u062d\u064a\u0645 \u0628\u0643\u0645 \u0625\u0630 \u0623\u0630\u0646 \u0644\u0643\u0645 \u0641\u064a \u0646\u0643\u0627\u062d\u0647\u0646 \u0639\u0646\u062f \u0627\u0644\u0639\u062c\u0632 \u0639\u0646 \u0646\u0643\u0627\u062d \u0627\u0644\u062d\u0631\u0627\u0626\u0631.","4:26":"\u064a\u0631\u064a\u062f \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0628\u0647\u0630\u0647 \u0627\u0644\u062a\u0634\u0631\u064a\u0639\u0627\u062a\u060c \u0623\u0646 \u064a\u0648\u0636\u062d \u0644\u0643\u0645 \u0645\u0639\u0627\u0644\u0645 \u062f\u064a\u0646\u0647 \u0627\u0644\u0642\u0648\u064a\u0645\u060c \u0648\u0634\u0631\u0639\u0647 \u0627\u0644\u062d\u0643\u064a\u0645\u060c \u0648\u064a\u062f\u0644\u0643\u0645 \u0639\u0644\u0649 \u0637\u0631\u0642 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0648\u0627\u0644\u0635\u0627\u0644\u062d\u064a\u0646 \u0645\u0646 \u0642\u0628\u0644\u0643\u0645 \u0641\u064a \u0627\u0644\u062d\u0644\u0627\u0644 \u0648\u0627\u0644\u062d\u0631\u0627\u0645\u060c \u0648\u064a\u062a\u0648\u0628 \u0639\u0644\u064a\u0643\u0645 \u0628\u0627\u0644\u0631\u062c\u0648\u0639 \u0628\u0643\u0645 \u0625\u0644\u0649 \u0627\u0644\u0637\u0627\u0639\u0627\u062a\u060c \u0648\u0647\u0648 \u0633\u0628\u062d\u0627\u0646\u0647 \u0639\u0644\u064a\u0645 \u0628\u0645\u0627 \u064a\u0635\u0644\u062d \u0634\u0623\u0646 \u0639\u0628\u0627\u062f\u0647\u060c \u062d\u0643\u064a\u0645 \u0641\u064a\u0645\u0627 \u0634\u0631\u0639\u0647 \u0644\u0643\u0645.","4:27":"\u0648\u0627\u0644\u0644\u0647 \u064a\u0631\u064a\u062f \u0623\u0646 \u064a\u062a\u0648\u0628 \u0639\u0644\u064a\u0643\u0645\u060c \u0648\u064a\u062a\u062c\u0627\u0648\u0632 \u0639\u0646 \u062e\u0637\u0627\u064a\u0627\u0643\u0645\u060c \u0648\u064a\u0631\u064a\u062f \u0627\u0644\u0630\u064a\u0646 \u064a\u0646\u0642\u0627\u062f\u0648\u0646 \u0644\u0634\u0647\u0648\u0627\u062a\u0647\u0645 \u0648\u0645\u0644\u0630\u0627\u062a\u0647\u0645 \u0623\u0646 \u062a\u0646\u062d\u0631\u0641\u0648\u0627 \u0639\u0646 \u0627\u0644\u062f\u064a\u0646 \u0627\u0646\u062d\u0631\u0627\u0641\u064b\u0627 \u0643\u0628\u064a\u0631\u064b\u0627.","4:28":"\u064a\u0631\u064a\u062f \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0628\u0645\u0627 \u0634\u0631\u0639\u0647 \u0644\u0643\u0645 \u0627\u0644\u062a\u064a\u0633\u064a\u0631\u060c \u0648\u0639\u062f\u0645 \u0627\u0644\u062a\u0634\u062f\u064a\u062f \u0639\u0644\u064a\u0643\u0645; \u0644\u0623\u0646\u0643\u0645 \u062e\u0644\u0642\u062a\u0645 \u0636\u0639\u0641\u0627\u0621.","4:29":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647\u060c \u0644\u0627 \u064a\u062d\u0644 \u0644\u0643\u0645 \u0623\u0646 \u064a\u0623\u0643\u0644 \u0628\u0639\u0636\u0643\u0645 \u0645\u0627\u0644 \u0628\u0639\u0636 \u0628\u063a\u064a\u0631 \u062d\u0642\u060c \u0625\u0644\u0627 \u0623\u0646 \u064a\u0643\u0648\u0646 \u0648\u064e\u0641\u0652\u0642\u064e \u0627\u0644\u0634\u0631\u0639 \u0648\u0627\u0644\u0643\u0633\u0628 \u0627\u0644\u062d\u0644\u0627\u0644 \u0639\u0646 \u062a\u0631\u0627\u0636 \u0645\u0646\u0643\u0645\u060c \u0648\u0644\u0627 \u064a\u0642\u062a\u0644 \u0628\u0639\u0636\u0643\u0645 \u0628\u0639\u0636\u064b\u0627 \u0641\u062a\u0647\u0644\u0643\u0648\u0627 \u0623\u0646\u0641\u0633\u0643\u0645 \u0628\u0627\u0631\u062a\u0643\u0627\u0628 \u0645\u062d\u0627\u0631\u0645 \u0627\u0644\u0644\u0647 \u0648\u0645\u0639\u0627\u0635\u064a\u0647. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0643\u0627\u0646 \u0628\u0643\u0645 \u0631\u062d\u064a\u0645\u064b\u0627 \u0641\u064a \u0643\u0644 \u0645\u0627 \u0623\u0645\u0631\u0643\u0645 \u0628\u0647\u060c \u0648\u0646\u0647\u0627\u0643\u0645 \u0639\u0646\u0647.","4:30":"\u0648\u0645\u0646 \u064a\u0631\u062a\u0643\u0628 \u0645\u0627 \u0646\u0647\u0649 \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0645\u0646 \u0623\u062e\u0630 \u0627\u0644\u0645\u0627\u0644 \u0627\u0644\u062d\u0631\u0627\u0645 \u0643\u0627\u0644\u0633\u0631\u0642\u0629 \u0648\u0627\u0644\u063a\u0635\u0628 \u0648\u0627\u0644\u063a\u0634 \u0645\u0639\u062a\u062f\u064a\u064b\u0627 \u0645\u062a\u062c\u0627\u0648\u0632\u064b\u0627 \u062d\u062f \u0627\u0644\u0634\u0631\u0639\u060c \u0641\u0633\u0648\u0641 \u064a\u062f\u062e\u0644\u0647 \u0627\u0644\u0644\u0647 \u0646\u0627\u0631\u064b\u0627 \u064a\u0642\u0627\u0633\u064a \u062d\u0631\u0651\u064e\u0647\u0627\u060c \u0648\u0643\u0627\u0646 \u0630\u0644\u0643 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u064a\u0633\u064a\u0631\u064b\u0627.","4:31":"\u0625\u0646 \u062a\u0628\u062a\u0639\u062f\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0639\u0646 \u0643\u0628\u0627\u0626\u0631 \u0627\u0644\u0630\u0646\u0648\u0628 \u0643\u0627\u0644\u0625\u0634\u0631\u0627\u0643 \u0628\u0627\u0644\u0644\u0647 \u0648\u0639\u0642\u0648\u0642 \u0627\u0644\u0648\u0627\u0644\u062f\u064a\u0646 \u0648\u0642\u064e\u062a\u0652\u0644\u0650 \u0627\u0644\u0646\u0641\u0633 \u0628\u063a\u064a\u0631 \u0627\u0644\u062d\u0642 \u0648\u063a\u064a\u0631 \u0630\u0644\u0643\u060c \u0646\u0643\u0641\u0651\u0650\u0631 \u0639\u0646\u0643\u0645 \u0645\u0627 \u062f\u0648\u0646\u0647\u0627 \u0645\u0646 \u0627\u0644\u0635\u063a\u0627\u0626\u0631\u060c \u0648\u0646\u062f\u062e\u0644\u0643\u0645 \u0645\u062f\u062e\u0644\u0627 \u0643\u0631\u064a\u0645\u064b\u0627\u060c \u0648\u0647\u0648 \u0627\u0644\u062c\u0646\u0651\u064e\u0629.","4:32":"\u0648\u0644\u0627 \u062a\u062a\u0645\u0646\u0648\u0627 \u0645\u0627 \u0641\u0636\u0651\u064e\u0644 \u0627\u0644\u0644\u0647 \u0628\u0647 \u0628\u0639\u0636\u0643\u0645 \u0639\u0644\u0649 \u0628\u0639\u0636\u060c \u0641\u064a \u0627\u0644\u0645\u0648\u0627\u0647\u0628 \u0648\u0627\u0644\u0623\u0631\u0632\u0627\u0642 \u0648\u063a\u064a\u0631 \u0630\u0644\u0643\u060c \u0641\u0642\u062f \u062c\u0639\u0644 \u0627\u0644\u0644\u0647 \u0644\u0644\u0631\u062c\u0627\u0644 \u0646\u0635\u064a\u0628\u064b\u0627 \u0645\u0642\u062f\u0651\u064e\u0631\u064b\u0627 \u0645\u0646 \u0627\u0644\u062c\u0632\u0627\u0621 \u0628\u062d\u0633\u0628 \u0639\u0645\u0644\u0647\u0645\u060c \u0648\u062c\u0639\u0644 \u0644\u0644\u0646\u0633\u0627\u0621 \u0646\u0635\u064a\u0628\u064b\u0627 \u0645\u0645\u0627 \u0639\u0645\u0644\u0646\u060c \u0648\u0627\u0633\u0623\u0644\u0648\u0627 \u0627\u0644\u0644\u0647 \u0627\u0644\u0643\u0631\u064a\u0645 \u0627\u0644\u0648\u0647\u0627\u0628 \u064a\u064f\u0639\u0652\u0637\u0650\u0643\u0645 \u0645\u0646 \u0641\u0636\u0644\u0647 \u0628\u062f\u0644\u0627 \u0645\u0646 \u0627\u0644\u062a\u0645\u0646\u064a. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0643\u0627\u0646 \u0628\u0643\u0644 \u0634\u064a\u0621 \u0639\u0644\u064a\u0645\u064b\u0627\u060c \u0648\u0647\u0648 \u0623\u0639\u0644\u0645 \u0628\u0645\u0627 \u064a\u0635\u0644\u062d \u0639\u0628\u0627\u062f\u0647 \u0641\u064a\u0645\u0627 \u0642\u0633\u0645\u0647 \u0644\u0647\u0645 \u0645\u0646 \u062e\u064a\u0631.","4:33":"\u0648\u0644\u0643\u0644 \u0648\u0627\u062d\u062f \u0645\u0646\u0643\u0645 \u062c\u0639\u0644\u0646\u0627 \u0648\u0631\u062b\u0629 \u064a\u0631\u062b\u0648\u0646 \u0645\u0645\u0627 \u062a\u0631\u0643 \u0627\u0644\u0648\u0627\u0644\u062f\u0627\u0646 \u0648\u0627\u0644\u0623\u0642\u0631\u0628\u0648\u0646\u060c \u0648\u0627\u0644\u0630\u064a\u0646 \u062a\u062d\u0627\u0644\u0641\u062a\u0645 \u0645\u0639\u0647\u0645 \u0628\u0627\u0644\u0623\u064a\u0645\u0627\u0646 \u0627\u0644\u0645\u0624\u0643\u062f\u0629 \u0639\u0644\u0649 \u0627\u0644\u0646\u0635\u0631\u0629 \u0648\u0625\u0639\u0637\u0627\u0626\u0647\u0645 \u0634\u064a\u0626\u064b\u0627 \u0645\u0646 \u0627\u0644\u0645\u064a\u0631\u0627\u062b \u0641\u0623\u0639\u0637\u0648\u0647\u0645 \u0645\u0627 \u0642\u064f\u062f\u0651\u0650\u0631 \u0644\u0647\u0645. \u0648\u0627\u0644\u0645\u064a\u0631\u0627\u062b \u0628\u0627\u0644\u062a\u062d\u0627\u0644\u0641 \u0643\u0627\u0646 \u0641\u064a \u0623\u0648\u0644 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u062b\u0645 \u0631\u064f\u0641\u0639 \u062d\u0643\u0645\u0647 \u0628\u0646\u0632\u0648\u0644 \u0622\u064a\u0627\u062a \u0627\u0644\u0645\u0648\u0627\u0631\u064a\u062b. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0643\u0627\u0646 \u0645\u064f\u0637\u0651\u064e\u0644\u0650\u0639\u064b\u0627 \u0639\u0644\u0649 \u0643\u0644 \u0634\u064a\u0621 \u0645\u0646 \u0623\u0639\u0645\u0627\u0644\u0643\u0645\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a\u0643\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643.","4:34":"\u0627\u0644\u0631\u062c\u0627\u0644 \u0642\u0648\u0651\u064e\u0627\u0645\u0648\u0646 \u0639\u0644\u0649 \u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0646\u0633\u0627\u0621 \u0648\u0631\u0639\u0627\u064a\u062a\u0647\u0646\u060c \u0628\u0645\u0627 \u062e\u0635\u0647\u0645 \u0627\u0644\u0644\u0647 \u0628\u0647 \u0645\u0646 \u062e\u0635\u0627\u0626\u0635 \u0627\u0644\u0642\u0650\u0648\u0627\u0645\u064e\u0629 \u0648\u0627\u0644\u062a\u0641\u0636\u064a\u0644\u060c \u0648\u0628\u0645\u0627 \u0623\u0639\u0637\u0648\u0647\u0646 \u0645\u0646 \u0627\u0644\u0645\u0647\u0648\u0631 \u0648\u0627\u0644\u0646\u0641\u0642\u0627\u062a. \u0641\u0627\u0644\u0635\u0627\u0644\u062d\u0627\u062a \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645\u0627\u062a \u0639\u0644\u0649 \u0634\u0631\u0639 \u0627\u0644\u0644\u0647 \u0645\u0646\u0647\u0646\u060c \u0645\u0637\u064a\u0639\u0627\u062a \u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0644\u0623\u0632\u0648\u0627\u062c\u0647\u0646\u060c \u062d\u0627\u0641\u0638\u0627\u062a \u0644\u0643\u0644 \u0645\u0627 \u063a\u0627\u0628 \u0639\u0646 \u0639\u0644\u0645 \u0623\u0632\u0648\u0627\u062c\u0647\u0646 \u0628\u0645\u0627 \u0627\u0624\u062a\u0645\u0646\u0651\u064e \u0639\u0644\u064a\u0647 \u0628\u062d\u0641\u0638 \u0627\u0644\u0644\u0647 \u0648\u062a\u0648\u0641\u064a\u0642\u0647\u060c \u0648\u0627\u0644\u0644\u0627\u062a\u064a \u062a\u062e\u0634\u0648\u0646 \u0645\u0646\u0647\u0646 \u062a\u0631\u0641\u0651\u064f\u0639\u0647\u0646 \u0639\u0646 \u0637\u0627\u0639\u062a\u0643\u0645\u060c \u0641\u0627\u0646\u0635\u062d\u0648\u0647\u0646 \u0628\u0627\u0644\u0643\u0644\u0645\u0629 \u0627\u0644\u0637\u064a\u0628\u0629\u060c \u0641\u0625\u0646 \u0644\u0645 \u062a\u062b\u0645\u0631 \u0645\u0639\u0647\u0646 \u0627\u0644\u0643\u0644\u0645\u0629 \u0627\u0644\u0637\u064a\u0628\u0629\u060c \u0641\u0627\u0647\u062c\u0631\u0648\u0647\u0646 \u0641\u064a \u0627\u0644\u0641\u0631\u0627\u0634\u060c \u0648\u0644\u0627 \u062a\u0642\u0631\u0628\u0648\u0647\u0646\u060c \u0641\u0625\u0646 \u0644\u0645 \u064a\u0624\u062b\u0631 \u0641\u0639\u0644 \u0627\u0644\u0647\u0650\u062c\u0652\u0631\u0627\u0646 \u0641\u064a\u0647\u0646\u060c \u0641\u0627\u0636\u0631\u0628\u0648\u0647\u0646 \u0636\u0631\u0628\u064b\u0627 \u0644\u0627 \u0636\u0631\u0631 \u0641\u064a\u0647\u060c \u0641\u0625\u0646 \u0623\u0637\u0639\u0646\u0643\u0645 \u0641\u0627\u062d\u0630\u0631\u0648\u0627 \u0638\u0644\u0645\u0647\u0646\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0627\u0644\u0639\u0644\u064a\u0651\u064e \u0627\u0644\u0643\u0628\u064a\u0631 \u0648\u0644\u064a\u0651\u064f\u0647\u0646\u060c \u0648\u0647\u0648 \u0645\u0646\u062a\u0642\u0645 \u0645\u0645\u0651\u064e\u0646 \u0638\u0644\u0645\u0647\u0646\u0651\u064e \u0648\u0628\u063a\u0649 \u0639\u0644\u064a\u0647\u0646.","4:35":"\u0648\u0625\u0646 \u0639\u0644\u0645\u062a\u0645 -\u064a\u0627 \u0623\u0648\u0644\u064a\u0627\u0621 \u0627\u0644\u0632\u0648\u062c\u064a\u0646- \u0634\u0642\u0627\u0642\u064b\u0627 \u0628\u064a\u0646\u0647\u0645\u0627 \u064a\u0624\u062f\u064a \u0625\u0644\u0649 \u0627\u0644\u0641\u0631\u0627\u0642\u060c \u0641\u0623\u0631\u0633\u0644\u0648\u0627 \u0625\u0644\u064a\u0647\u0645\u0627 \u062d\u0643\u0645\u064b\u0627 \u0639\u062f\u0644\u0627 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0632\u0648\u062c\u060c \u0648\u062d\u0643\u0645\u064b\u0627 \u0639\u062f\u0644\u0627 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0632\u0648\u062c\u0629; \u0644\u064a\u0646\u0638\u0631\u0627 \u0648\u064a\u062d\u0643\u0645\u0627 \u0628\u0645\u0627 \u0641\u064a\u0647 \u0627\u0644\u0645\u0635\u0644\u062d\u0629 \u0644\u0647\u0645\u0627\u060c \u0648\u0628\u0633\u0628\u0628 \u0631\u063a\u0628\u0629 \u0627\u0644\u062d\u0643\u0645\u064a\u0646 \u0641\u064a \u0627\u0644\u0625\u0635\u0644\u0627\u062d\u060c \u0648\u0627\u0633\u062a\u0639\u0645\u0627\u0644\u0647\u0645\u0627 \u0627\u0644\u0623\u0633\u0644\u0648\u0628 \u0627\u0644\u0637\u064a\u0628 \u064a\u0648\u0641\u0642 \u0627\u0644\u0644\u0647 \u0628\u064a\u0646 \u0627\u0644\u0632\u0648\u062c\u064a\u0646. \u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0644\u064a\u0645\u060c \u0644\u0627 \u064a\u062e\u0641\u0649 \u0639\u0644\u064a\u0647 \u0634\u064a\u0621 \u0645\u0646 \u0623\u0645\u0631 \u0639\u0628\u0627\u062f\u0647\u060c \u062e\u0628\u064a\u0631 \u0628\u0645\u0627 \u062a\u0646\u0637\u0648\u064a \u0639\u0644\u064a\u0647 \u0646\u0641\u0648\u0633\u0647\u0645.","4:36":"\u0648\u0627\u0639\u0628\u062f\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0627\u0646\u0642\u0627\u062f\u0648\u0627 \u0644\u0647 \u0648\u062d\u062f\u0647\u060c \u0648\u0644\u0627 \u062a\u062c\u0639\u0644\u0648\u0627 \u0644\u0647 \u0634\u0631\u064a\u0643\u064b\u0627 \u0641\u064a \u0627\u0644\u0631\u0628\u0648\u0628\u064a\u0629 \u0648\u0627\u0644\u0639\u0628\u0627\u062f\u0629\u060c \u0648\u0623\u062d\u0633\u0646\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u0648\u0627\u0644\u062f\u064a\u0646\u060c \u0648\u0623\u062f\u0651\u064f\u0648\u0627 \u062d\u0642\u0648\u0642\u0647\u0645\u0627\u060c \u0648\u062d\u0642\u0648\u0642 \u0627\u0644\u0623\u0642\u0631\u0628\u064a\u0646\u060c \u0648\u0627\u0644\u0623\u0648\u0644\u0627\u062f \u0627\u0644\u0630\u064a\u0646 \u0645\u0627\u062a \u0622\u0628\u0627\u0624\u0647\u0645 \u0648\u0647\u0645 \u062f\u0648\u0646 \u0633\u0646 \u0627\u0644\u0628\u0644\u0648\u063a\u060c \u0648\u0627\u0644\u0645\u062d\u062a\u0627\u062c\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0644\u0627 \u064a\u0645\u0644\u0643\u0648\u0646 \u0645\u0627 \u064a\u0643\u0641\u064a\u0647\u0645 \u0648\u064a\u0633\u062f \u062d\u0627\u062c\u062a\u0647\u0645\u060c \u0648\u0627\u0644\u062c\u0627\u0631 \u0627\u0644\u0642\u0631\u064a\u0628 \u0645\u0646\u0643\u0645 \u0648\u0627\u0644\u0628\u0639\u064a\u062f\u060c \u0648\u0627\u0644\u0631\u0641\u064a\u0642 \u0641\u064a \u0627\u0644\u0633\u0641\u0631 \u0648\u0641\u064a \u0627\u0644\u062d\u0636\u0631\u060c \u0648\u0627\u0644\u0645\u0633\u0627\u0641\u0631 \u0627\u0644\u0645\u062d\u062a\u0627\u062c\u060c \u0648\u0627\u0644\u0645\u0645\u0627\u0644\u064a\u0643 \u0645\u0646 \u0641\u062a\u064a\u0627\u0646\u0643\u0645 \u0648\u0641\u062a\u064a\u0627\u062a\u0643\u0645. \u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0627 \u064a\u062d\u0628 \u0627\u0644\u0645\u062a\u0643\u0628\u0631\u064a\u0646 \u0645\u0646 \u0639\u0628\u0627\u062f\u0647\u060c \u0627\u0644\u0645\u0641\u062a\u062e\u0631\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0646\u0627\u0633.","4:37":"\u0627\u0644\u0630\u064a\u0646 \u064a\u0645\u062a\u0646\u0639\u0648\u0646 \u0639\u0646 \u0627\u0644\u0625\u0646\u0641\u0627\u0642 \u0648\u0627\u0644\u0639\u0637\u0627\u0621 \u0645\u0645\u0627 \u0631\u0632\u0642\u0647\u0645 \u0627\u0644\u0644\u0647\u060c \u0648\u064a\u0623\u0645\u0631\u0648\u0646 \u063a\u064a\u0631\u0647\u0645 \u0628\u0627\u0644\u0628\u062e\u0644\u060c \u0648\u064a\u062c\u062d\u062f\u0648\u0646 \u0646\u0650\u0639\u064e\u0645\u064e \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645\u060c \u0648\u064a\u062e\u0641\u0648\u0646 \u0641\u0636\u0644\u0647 \u0648\u0639\u0637\u0627\u0621\u0647. \u0648\u0623\u0639\u062f\u062f\u0646\u0627 \u0644\u0644\u062c\u0627\u062d\u062f\u064a\u0646 \u0639\u0630\u0627\u0628\u064b\u0627 \u0645\u062e\u0632\u064a\u064b\u0627.","4:38":"\u0648\u0623\u0639\u062a\u062f\u0646\u0627 \u0647\u0630\u0627 \u0627\u0644\u0639\u0630\u0627\u0628 \u0643\u0630\u0644\u0643 \u0644\u0644\u0630\u064a\u0646 \u064a\u0646\u0641\u0642\u0648\u0646 \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0631\u064a\u0627\u0621\u064b \u0648\u0633\u0645\u0639\u0629\u064b\u060c \u0648\u0644\u0627 \u064a\u0635\u062f\u0642\u0648\u0646 \u0628\u0627\u0644\u0644\u0647 \u0627\u0639\u062a\u0642\u0627\u062f\u064b\u0627 \u0648\u0639\u0645\u0644\u0627 \u0648\u0644\u0627 \u0628\u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629. \u0648\u0647\u0630\u0647 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0633\u064a\u0626\u0629 \u0645\u0645\u0627 \u064a\u062f\u0639\u0648 \u0625\u0644\u064a\u0647\u0627 \u0627\u0644\u0634\u064a\u0637\u0627\u0646. \u0648\u0645\u0646 \u064a\u0643\u0646 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0644\u0647 \u0645\u0644\u0627\u0632\u0645\u064b\u0627 \u0641\u0628\u0626\u0633 \u0627\u0644\u0645\u0644\u0627\u0632\u0645 \u0648\u0627\u0644\u0642\u0631\u064a\u0646.","4:39":"\u0648\u0623\u064a\u0651\u064f \u0636\u0631\u0631 \u064a\u0644\u062d\u0642\u0647\u0645 \u0644\u0648 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0622\u062e\u0631 \u0627\u0639\u062a\u0642\u0627\u062f\u064b\u0627 \u0648\u0639\u0645\u0644\u0627 \u0648\u0623\u0646\u0641\u0642\u0648\u0627 \u0645\u0645\u0627 \u0623\u0639\u0637\u0627\u0647\u0645 \u0627\u0644\u0644\u0647 \u0628\u0627\u062d\u062a\u0633\u0627\u0628 \u0648\u0625\u062e\u0644\u0627\u0635\u060c \u0648\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0644\u064a\u0645 \u0628\u0647\u0645 \u0648\u0628\u0645\u0627 \u064a\u0639\u0645\u0644\u0648\u0646\u060c \u0648\u0633\u064a\u062d\u0627\u0633\u0628\u0647\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643.","4:40":"\u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0627 \u064a\u0646\u0642\u0635 \u0623\u062d\u062f\u064b\u0627 \u0645\u0646 \u062c\u0632\u0627\u0621 \u0639\u0645\u0644\u0647 \u0645\u0642\u062f\u0627\u0631 \u0630\u0631\u0629\u060c \u0648\u0625\u0646 \u062a\u0643\u0646 \u0632\u0646\u0629 \u0627\u0644\u0630\u0631\u0629 \u062d\u0633\u0646\u0629 \u0641\u0625\u0646\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u064a\u0632\u064a\u062f\u0647\u0627 \u0648\u064a\u0643\u062b\u0631\u0647\u0627 \u0644\u0635\u0627\u062d\u0628\u0647\u0627\u060c \u0648\u064a\u062a\u0641\u0636\u0644 \u0639\u0644\u064a\u0647 \u0628\u0627\u0644\u0645\u0632\u064a\u062f\u060c \u0641\u064a\u0639\u0637\u064a\u0647 \u0645\u0646 \u0639\u0646\u062f\u0647 \u062b\u0648\u0627\u0628\u064b\u0627 \u0643\u0628\u064a\u0631\u064b\u0627 \u0647\u0648 \u0627\u0644\u062c\u0646\u0629.","4:41":"\u0641\u0643\u064a\u0641 \u064a\u0643\u0648\u0646 \u062d\u0627\u0644 \u0627\u0644\u0646\u0627\u0633 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u0625\u0630\u0627 \u062c\u0627\u0621 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0643\u0644 \u0623\u0645\u0629 \u0628\u0631\u0633\u0648\u0644\u0647\u0627 \u0644\u064a\u0634\u0647\u062f \u0639\u0644\u064a\u0647\u0627 \u0628\u0645\u0627 \u0639\u0645\u0644\u062a\u060c \u0648\u062c\u0627\u0621 \u0628\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u062a\u0643\u0648\u0646 \u0634\u0647\u064a\u062f\u064b\u0627 \u0639\u0644\u0649 \u0623\u0645\u062a\u0643 \u0623\u0646\u0643 \u0628\u0644\u063a\u062a\u0647\u0645 \u0631\u0633\u0627\u0644\u0629 \u0631\u0628\u0651\u0650\u0643\u061f","4:42":"\u064a\u0648\u0645 \u064a\u0643\u0648\u0646 \u0630\u0644\u0643\u060c \u064a\u062a\u0645\u0646\u0649 \u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u062e\u0627\u0644\u0641\u0648\u0627 \u0627\u0644\u0631\u0633\u0648\u0644 \u0648\u0644\u0645 \u064a\u0637\u064a\u0639\u0648\u0647\u060c \u0644\u0648 \u064a\u062c\u0639\u0644\u0647\u0645 \u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u0623\u0631\u0636 \u0633\u0648\u0627\u0621\u060c \u0641\u064a\u0635\u064a\u0631\u0648\u0646 \u062a\u0631\u0627\u0628\u064b\u0627\u060c \u062d\u062a\u0649 \u0644\u0627 \u064a\u0628\u0639\u062b\u0648\u0627 \u0648\u0647\u0645 \u0644\u0627 \u064a\u0633\u062a\u0637\u064a\u0639\u0648\u0646 \u0623\u0646 \u064a\u064f\u062e\u0641\u0648\u0627 \u0639\u0646 \u0627\u0644\u0644\u0647 \u0634\u064a\u0626\u064b\u0627 \u0645\u0645\u0627 \u0641\u064a \u0623\u0646\u0641\u0633\u0647\u0645\u060c \u0625\u0630 \u062e\u062a\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0623\u0641\u0648\u0627\u0647\u0647\u0645\u060c \u0648\u0634\u064e\u0647\u0650\u062f\u064e\u062a\u0652 \u0639\u0644\u064a\u0647\u0645 \u062c\u0648\u0627\u0631\u062d\u0647\u0645 \u0628\u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u064a\u0639\u0645\u0644\u0648\u0646.","4:43":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647\u060c \u0644\u0627 \u062a\u0642\u0631\u0628\u0648\u0627 \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0644\u0627 \u062a\u0642\u0648\u0645\u0648\u0627 \u0625\u0644\u064a\u0647\u0627 \u062d\u0627\u0644 \u0627\u0644\u0633\u0643\u0631 \u062d\u062a\u0649 \u062a\u0645\u064a\u0632\u0648\u0627 \u0648\u062a\u0639\u0644\u0645\u0648\u0627 \u0645\u0627 \u062a\u0642\u0648\u0644\u0648\u0646 (\u0648\u0642\u062f \u0643\u0627\u0646 \u0647\u0630\u0627 \u0642\u0628\u0644 \u0627\u0644\u062a\u062d\u0631\u064a\u0645 \u0627\u0644\u0642\u0627\u0637\u0639 \u0644\u0644\u062e\u0645\u0631 \u0641\u064a \u0643\u0644 \u062d\u0627\u0644) \u060c \u0648\u0644\u0627 \u062a\u0642\u0631\u0628\u0648\u0627 \u0627\u0644\u0635\u0644\u0627\u0629 \u0625\u0646 \u0623\u0635\u0627\u0628\u0643\u0645 \u0627\u0644\u062d\u062f\u062b \u0627\u0644\u0623\u0643\u0628\u0631\u060c \u0648\u0644\u0627 \u062a\u0642\u0631\u0628\u0648\u0627 \u0643\u0630\u0644\u0643 \u0645\u0648\u0627\u0636\u0639\u0647\u0627 \u0648\u0647\u064a \u0627\u0644\u0645\u0633\u0627\u062c\u062f\u060c \u0625\u0644\u0627 \u0645\u0646 \u0643\u0627\u0646 \u0645\u0646\u0643\u0645 \u0645\u062c\u062a\u0627\u0632\u064b\u0627 \u0645\u0646 \u0628\u0627\u0628 \u0625\u0644\u0649 \u0628\u0627\u0628\u060c \u062d\u062a\u0649 \u062a\u062a\u0637\u0647\u0631\u0648\u0627 \u0628\u0627\u0644\u0627\u063a\u062a\u0633\u0627\u0644. \u0648\u0625\u0646 \u0643\u0646\u062a\u0645 \u0641\u064a \u062d\u0627\u0644 \u0645\u0631\u0636 \u0644\u0627 \u062a\u0642\u062f\u0631\u0648\u0646 \u0645\u0639\u0647 \u0639\u0644\u0649 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u0627\u0644\u0645\u0627\u0621\u060c \u0623\u0648 \u062d\u0627\u0644 \u0633\u0641\u0631\u060c \u0623\u0648 \u062c\u0627\u0621 \u0623\u062d\u062f \u0645\u0646\u0643\u0645 \u0645\u0646 \u0627\u0644\u063a\u0627\u0626\u0637\u060c \u0623\u0648 \u062c\u0627\u0645\u0639\u062a\u0645 \u0627\u0644\u0646\u0633\u0627\u0621\u060c \u0641\u0644\u0645 \u062a\u062c\u062f\u0648\u0627 \u0645\u0627\u0621 \u0644\u0644\u0637\u0647\u0627\u0631\u0629 \u0641\u0627\u0642\u0635\u062f\u0648\u0627 \u062a\u0631\u0627\u0628\u064b\u0627 \u0637\u0627\u0647\u0631\u064b\u0627\u060c \u0641\u0627\u0645\u0633\u062d\u0648\u0627 \u0628\u0648\u062c\u0648\u0647\u0643\u0645 \u0648\u0623\u064a\u062f\u064a\u0643\u0645 \u0645\u0646\u0647. \u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0643\u0627\u0646 \u0643\u062b\u064a\u0631 \u0627\u0644\u0639\u0641\u0648 \u064a\u062a\u062c\u0627\u0648\u0632 \u0639\u0646 \u0633\u064a\u0626\u0627\u062a\u0643\u0645\u060c \u0648\u064a\u0633\u062a\u0631\u0647\u0627 \u0639\u0644\u064a\u0643\u0645.","4:44":"\u0623\u0644\u0645 \u062a\u0639\u0644\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0623\u0645\u0631 \u0627\u0644\u064a\u0647\u0648\u062f \u0627\u0644\u0630\u064a\u0646 \u0623\u064f\u0639\u0637\u0648\u0627 \u062d\u0638\u0651\u064b\u0627 \u0645\u0646 \u0627\u0644\u0639\u0644\u0645 \u0645\u0645\u0627 \u062c\u0627\u0621\u0647\u0645 \u0645\u0646 \u0627\u0644\u062a\u0648\u0631\u0627\u0629\u060c \u064a\u0633\u062a\u0628\u062f\u0644\u0648\u0646 \u0627\u0644\u0636\u0644\u0627\u0644\u0629 \u0628\u0627\u0644\u0647\u062f\u0649\u060c \u0648\u064a\u062a\u0631\u0643\u0648\u0646 \u0645\u0627 \u0644\u062f\u064a\u0647\u0645 \u0645\u0646 \u0627\u0644\u062d\u062c\u062c \u0648\u0627\u0644\u0628\u0631\u0627\u0647\u064a\u0646\u060c \u0627\u0644\u062f\u0627\u0644\u0629 \u0639\u0644\u0649 \u0635\u062f\u0642 \u0631\u0633\u0627\u0644\u0629 \u0627\u0644\u0631\u0633\u0648\u0644 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u064a\u062a\u0645\u0646\u0648\u0646 \u0644\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0627\u0644\u0645\u0647\u062a\u062f\u0648\u0646- \u0623\u0646 \u062a\u0646\u062d\u0631\u0641\u0648\u0627 \u0639\u0646 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645; \u0644\u062a\u0643\u0648\u0646\u0648\u0627 \u0636\u0627\u0644\u064a\u0646 \u0645\u062b\u0644\u0647\u0645.","4:45":"\u0648\u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649 \u0623\u0639\u0644\u0645 \u0645\u0646\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0628\u0639\u062f\u0627\u0648\u0629 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u064a\u0647\u0648\u062f \u0644\u0643\u0645\u060c \u0648\u0643\u0641\u0649 \u0628\u0627\u0644\u0644\u0647 \u0648\u0644\u064a\u0651\u064b\u0627 \u064a\u062a\u0648\u0644\u0627\u0643\u0645\u060c \u0648\u0643\u0641\u0649 \u0628\u0647 \u0646\u0635\u064a\u0631\u064b\u0627 \u064a\u0646\u0635\u0631\u0643\u0645 \u0639\u0644\u0649 \u0623\u0639\u062f\u0627\u0626\u0643\u0645.","4:46":"\u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0641\u0631\u064a\u0642 \u062f\u0623\u0628\u0648\u0627 \u0639\u0644\u0649 \u062a\u0628\u062f\u064a\u0644 \u0643\u0644\u0627\u0645 \u0627\u0644\u0644\u0647 \u0648\u062a\u063a\u064a\u064a\u0631\u0647 \u0639\u0645\u0651\u064e\u0627 \u0647\u0648 \u0639\u0644\u064a\u0647 \u0627\u0641\u062a\u0631\u0627\u0621\u064b \u0639\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0648\u064a\u0642\u0648\u0644\u0648\u0646 \u0644\u0644\u0631\u0633\u0648\u0644 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645: \u0633\u0645\u0639\u0646\u0627 \u0642\u0648\u0644\u0643 \u0648\u0639\u0635\u064a\u0646\u0627 \u0623\u0645\u0631\u0643 \u0648\u0627\u0633\u0645\u0639 \u0645\u0646\u0651\u064e\u0627 \u0644\u0627 \u0633\u0645\u0639\u062a\u060c \u0648\u064a\u0642\u0648\u0644\u0648\u0646: \u0631\u0627\u0639\u0646\u0627 \u0633\u0645\u0639\u0643 \u0623\u064a: \u0627\u0641\u0647\u0645 \u0639\u0646\u0627 \u0648\u0623\u0641\u0647\u0645\u0646\u0627\u060c \u064a\u0644\u0648\u0648\u0646 \u0623\u0644\u0633\u0646\u062a\u0647\u0645 \u0628\u0630\u0644\u0643\u060c \u0648\u0647\u0645 \u064a\u0631\u064a\u062f\u0648\u0646 \u0627\u0644\u062f\u0639\u0627\u0621 \u0639\u0644\u064a\u0647 \u0628\u0627\u0644\u0631\u0639\u0648\u0646\u0629 \u062d\u0633\u0628 \u0644\u063a\u062a\u0647\u0645\u060c \u0648\u0627\u0644\u0637\u0639\u0646 \u0641\u064a \u062f\u064a\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645. \u0648\u0644\u0648 \u0623\u0646\u0647\u0645 \u0642\u0627\u0644\u0648\u0627: \u0633\u0645\u0639\u0646\u0627 \u0648\u0623\u0637\u0639\u0646\u0627\u060c \u0628\u062f\u0644 \u0648 \xab\u0639\u0635\u064a\u0646\u0627\xbb \u060c \u0648\u0627\u0633\u0645\u0639 \u062f\u0648\u0646 \xab\u063a\u064a\u0631 \u0645\u0633\u0645\u0639\xbb \u060c \u0648\u0627\u0646\u0638\u0631\u0646\u0627 \u0628\u062f\u0644 \xab\u0631\u0627\u0639\u0646\u0627\xbb \u0644\u0643\u0627\u0646 \u0630\u0644\u0643 \u062e\u064a\u0631\u064b\u0627 \u0644\u0647\u0645 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0648\u0623\u0639\u062f\u0644 \u0642\u0648\u0644\u0627 \u0648\u0644\u0643\u0646 \u0627\u0644\u0644\u0647 \u0637\u0631\u062f\u0647\u0645 \u0645\u0646 \u0631\u062d\u0645\u062a\u0647; \u0628\u0633\u0628\u0628 \u0643\u0641\u0631\u0647\u0645 \u0648\u062c\u062d\u0648\u062f\u0647\u0645 \u0646\u0628\u0648\u0629 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0641\u0644\u0627 \u064a\u0635\u062f\u0642\u0648\u0646 \u0628\u0627\u0644\u062d\u0642 \u0625\u0644\u0627 \u062a\u0635\u062f\u064a\u0642\u064b\u0627 \u0642\u0644\u064a\u0644\u0627 \u0644\u0627 \u064a\u0646\u0641\u0639\u0647\u0645.","4:47":"\u064a\u0627 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628\u060c \u0635\u062f\u0651\u0650\u0642\u0648\u0627 \u0648\u0627\u0639\u0645\u0644\u0648\u0627 \u0628\u0645\u0627 \u0646\u0632\u0651\u064e\u0644\u0646\u0627 \u0645\u0646 \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0645\u0635\u062f\u0642\u064b\u0627 \u0644\u0645\u0627 \u0645\u0639\u0643\u0645 \u0645\u0646 \u0627\u0644\u0643\u062a\u0628 \u0645\u0646 \u0642\u0628\u0644 \u0623\u0646 \u0646\u0623\u062e\u0630\u0643\u0645 \u0628\u0633\u0648\u0621 \u0635\u0646\u064a\u0639\u0643\u0645\u060c \u0641\u0646\u0645\u062d\u0648 \u0627\u0644\u0648\u062c\u0648\u0647 \u0648\u0646\u062d\u0648\u0644\u0647\u0627 \u0642\u0650\u0628\u064e\u0644\u064e \u0627\u0644\u0638\u0647\u0648\u0631\u060c \u0623\u0648 \u0646\u0644\u0639\u0646 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0641\u0633\u062f\u064a\u0646 \u0628\u0645\u0633\u062e\u0647\u0645 \u0642\u0631\u062f\u0629 \u0648\u062e\u0646\u0627\u0632\u064a\u0631\u060c \u0643\u0645\u0627 \u0644\u0639\u0646\u0651\u064e\u0627 \u0627\u0644\u064a\u0647\u0648\u062f \u0645\u0650\u0646 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0633\u0628\u062a\u060c \u0627\u0644\u0630\u064a\u0646 \u0646\u064f\u0647\u0648\u0627 \u0639\u0646 \u0627\u0644\u0635\u064a\u062f \u0641\u064a\u0647 \u0641\u0644\u0645 \u064a\u0646\u062a\u0647\u0648\u0627\u060c \u0641\u063a\u0636\u0628 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645\u060c \u0648\u0637\u0631\u062f\u0647\u0645 \u0645\u0646 \u0631\u062d\u0645\u062a\u0647\u060c \u0648\u0643\u0627\u0646 \u0623\u0645\u0631 \u0627\u0644\u0644\u0647 \u0646\u0627\u0641\u0630\u064b\u0627 \u0641\u064a \u0643\u0644 \u062d\u0627\u0644.","4:48":"\u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0627 \u064a\u063a\u0641\u0631 \u0648\u0644\u0627 \u064a\u062a\u062c\u0627\u0648\u0632 \u0639\u0645\u0651\u064e\u0646 \u0623\u0634\u0631\u0643 \u0628\u0647 \u0623\u062d\u062f\u064b\u0627 \u0645\u0646 \u0645\u062e\u0644\u0648\u0642\u0627\u062a\u0647\u060c \u0623\u0648 \u0643\u0641\u0631 \u0628\u0623\u064a \u0646\u0648\u0639 \u0645\u0646 \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0643\u0641\u0631 \u0627\u0644\u0623\u0643\u0628\u0631\u060c \u0648\u064a\u062a\u062c\u0627\u0648\u0632 \u0648\u064a\u0639\u0641\u0648 \u0639\u0645\u0651\u064e\u0627 \u062f\u0648\u0646 \u0627\u0644\u0634\u0631\u0643 \u0645\u0646 \u0627\u0644\u0630\u0646\u0648\u0628\u060c \u0644\u0645\u0646 \u064a\u0634\u0627\u0621 \u0645\u0646 \u0639\u0628\u0627\u062f\u0647\u060c \u0648\u0645\u0646 \u064a\u0634\u0631\u0643 \u0628\u0627\u0644\u0644\u0647 \u063a\u064a\u0631\u0647 \u0641\u0642\u062f \u0627\u062e\u062a\u0644\u0642 \u0630\u0646\u0628\u064b\u0627 \u0639\u0638\u064a\u0645\u064b\u0627.","4:49":"\u0623\u0644\u0645 \u062a\u0639\u0644\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0623\u0645\u0631 \u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0630\u064a\u0646 \u064a\u064f\u062b\u0646\u0648\u0646 \u0639\u0644\u0649 \u0623\u0646\u0641\u0633\u0647\u0645 \u0648\u0623\u0639\u0645\u0627\u0644\u0647\u0645\u060c \u0648\u064a\u0635\u0641\u0648\u0646\u0647\u0627 \u0628\u0627\u0644\u0637\u0647\u0631 \u0648\u0627\u0644\u0628\u0639\u062f \u0639\u0646 \u0627\u0644\u0633\u0648\u0621\u061f \u0628\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u062d\u062f\u0647 \u0647\u0648 \u0627\u0644\u0630\u064a \u064a\u062b\u0646\u064a \u0639\u0644\u0649 \u0645\u064e\u0646 \u064a\u0634\u0627\u0621 \u0645\u0650\u0646 \u0639\u0628\u0627\u062f\u0647\u060c \u0644\u0639\u0644\u0645\u0647 \u0628\u062d\u0642\u064a\u0642\u0629 \u0623\u0639\u0645\u0627\u0644\u0647\u0645\u060c \u0648\u0644\u0627 \u064a\u064f\u0646\u0642\u064e\u0635\u0648\u0646 \u0645\u0646 \u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0634\u064a\u0626\u064b\u0627 \u0645\u0642\u062f\u0627\u0631 \u0627\u0644\u062e\u064a\u0637 \u0627\u0644\u0630\u064a \u064a\u0643\u0648\u0646 \u0641\u064a \u0634\u0642 \u0646\u064e\u0648\u0627\u0629 \u0627\u0644\u062a\u0645\u0631\u0629.","4:50":"\u0627\u0646\u0638\u0631 \u0625\u0644\u064a\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0645\u062a\u0639\u062c\u0628\u064b\u0627 \u0645\u0646 \u0623\u0645\u0631\u0647\u0645\u060c \u0643\u064a\u0641 \u064a\u062e\u062a\u0644\u0642\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0627\u0644\u0643\u0630\u0628\u060c \u0648\u0647\u0648 \u0627\u0644\u0645\u0646\u0632\u0651\u064e\u0647 \u0639\u0646 \u0643\u0644 \u0645\u0627 \u0644\u0627 \u064a\u0644\u064a\u0642 \u0628\u0647\u061f \u0648\u0643\u0641\u0649 \u0628\u0647\u0630\u0627 \u0627\u0644\u0627\u062e\u062a\u0644\u0627\u0642 \u0630\u0646\u0628\u064b\u0627 \u0643\u0628\u064a\u0631\u064b\u0627 \u0643\u0627\u0634\u0641\u064b\u0627 \u0639\u0646 \u0641\u0633\u0627\u062f \u0645\u0639\u062a\u0642\u062f\u0647\u0645.","4:51":"\u0623\u0644\u0645 \u062a\u0639\u0644\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0623\u0645\u0631 \u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u064a\u0647\u0648\u062f \u0627\u0644\u0630\u064a\u0646 \u0623\u064f\u0639\u0637\u0648\u0627 \u062d\u0638\u0651\u064b\u0627 \u0645\u0646 \u0627\u0644\u0639\u0644\u0645 \u064a\u0635\u062f\u0642\u0648\u0646 \u0628\u0643\u0644 \u0645\u0627 \u064a\u064f\u0639\u0628\u062f \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u0623\u0635\u0646\u0627\u0645 \u0648\u0634\u064a\u0627\u0637\u064a\u0646 \u0627\u0644\u0625\u0646\u0633 \u0648\u0627\u0644\u062c\u0646 \u062a\u0635\u062f\u064a\u0642\u0627 \u064a\u062d\u0645\u0644\u0647\u0645 \u0639\u0644\u0649 \u0627\u0644\u062a\u062d\u0627\u0643\u0645 \u0625\u0644\u0649 \u063a\u064a\u0631 \u0634\u0631\u0639 \u0627\u0644\u0644\u0647\u060c \u0648\u064a\u0642\u0648\u0644\u0648\u0646 \u0644\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0628\u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645: \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0643\u0627\u0641\u0631\u0648\u0646 \u0623\u0642\u0652\u0648\u0645\u064f\u060c \u0648\u0623\u0639\u062f\u0644\u064f \u0637\u0631\u064a\u0642\u064b\u0627 \u0645\u0646 \u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627\u061f","4:52":"\u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0630\u064a\u0646 \u0643\u064e\u062b\u064f\u0631\u064e \u0641\u0633\u0627\u062f\u0647\u0645 \u0648\u0639\u0645\u0651\u064e \u0636\u0644\u0627\u0644\u0647\u0645\u060c \u0637\u0631\u062f\u0647\u0645 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0645\u0646 \u0631\u062d\u0645\u062a\u0647\u060c \u0648\u0645\u064e\u0646 \u064a\u0637\u0631\u062f\u0647 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0631\u062d\u0645\u062a\u0647 \u0641\u0644\u0646 \u062a\u062c\u062f \u0644\u0647 \u0645\u0646 \u064a\u0646\u0635\u0631\u0647\u060c \u0648\u064a\u062f\u0641\u0639 \u0639\u0646\u0647 \u0633\u0648\u0621 \u0627\u0644\u0639\u0630\u0627\u0628.","4:53":"\u0628\u0644 \u0623\u0644\u0647\u0645 \u062d\u0638 \u0645\u0646 \u0627\u0644\u0645\u0644\u0643\u060c \u0648\u0644\u0648 \u0623\u0648\u062a\u0648\u0647 \u0644\u0645\u0627 \u0623\u0639\u0637\u0648\u0627 \u0623\u062d\u062f\u064b\u0627 \u0645\u0646\u0647 \u0634\u064a\u0626\u064b\u0627\u060c \u0648\u0644\u0648 \u0643\u0627\u0646 \u0645\u0642\u062f\u0627\u0631 \u0627\u0644\u0646\u0642\u0631\u0629 \u0627\u0644\u062a\u064a \u062a\u0643\u0648\u0646 \u0641\u064a \u0638\u0647\u0631 \u0627\u0644\u0646\u0651\u064e\u0648\u0627\u0629\u061f","4:54":"\u0628\u0644 \u0623\u064a\u062d\u0633\u062f\u0648\u0646 \u0645\u062d\u0645\u062f\u064b\u0627 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0639\u0644\u0649 \u0645\u0627 \u0623\u0639\u0637\u0627\u0647 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0646\u0639\u0645\u0629 \u0627\u0644\u0646\u0628\u0648\u0629 \u0648\u0627\u0644\u0631\u0633\u0627\u0644\u0629\u060c \u0648\u064a\u062d\u0633\u062f\u0648\u0646 \u0623\u0635\u062d\u0627\u0628\u0647 \u0639\u0644\u0649 \u0646\u0639\u0645\u0629 \u0627\u0644\u062a\u0648\u0641\u064a\u0642 \u0625\u0644\u0649 \u0627\u0644\u0625\u064a\u0645\u0627\u0646\u060c \u0648\u0627\u0644\u062a\u0635\u062f\u064a\u0642 \u0628\u0627\u0644\u0631\u0633\u0627\u0644\u0629\u060c \u0648\u0627\u062a\u0628\u0627\u0639 \u0627\u0644\u0631\u0633\u0648\u0644\u060c \u0648\u0627\u0644\u062a\u0645\u0643\u064a\u0646 \u0641\u064a \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u064a\u062a\u0645\u0646\u0648\u0646 \u0632\u0648\u0627\u0644 \u0647\u0630\u0627 \u0627\u0644\u0641\u0636\u0644 \u0639\u0646\u0647\u0645\u061f \u0641\u0642\u062f \u0623\u0639\u0637\u064a\u0646\u0627 \u0630\u0631\u064a\u0629 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 -\u0645\u0646 \u0642\u064e\u0628\u0652\u0644\u064f- \u0627\u0644\u0643\u062a\u0628\u060c \u0627\u0644\u062a\u064a \u0623\u0646\u0632\u0644\u0647\u0627 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645 \u0648\u0645\u0627 \u0623\u0648\u062d\u064a \u0625\u0644\u064a\u0647\u0645 \u0645\u0645\u0627 \u0644\u0645 \u064a\u0643\u0646 \u0643\u062a\u0627\u0628\u0627 \u0645\u0642\u0631\u0648\u0621\u0627\u060c \u0648\u0623\u0639\u0637\u064a\u0646\u0627\u0647\u0645 \u0645\u0639 \u0630\u0644\u0643 \u0645\u0644\u0643\u0627 \u0648\u0627\u0633\u0639\u0627.","4:55":"\u0641\u0645\u0646 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u0623\u0648\u062a\u0648\u0627 \u062d\u0638\u0651\u064b\u0627 \u0645\u0646 \u0627\u0644\u0639\u0644\u0645\u060c \u0645\u064e\u0646 \u0635\u062f\u0651\u064e\u0642 \u0628\u0631\u0633\u0627\u0644\u0629 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0639\u0645\u0644 \u0628\u0634\u0631\u0639\u0647\u060c \u0648\u0645\u0646\u0647\u0645 \u0645\u064e\u0646 \u0623\u0639\u0631\u0636 \u0648\u0644\u0645 \u064a\u0633\u062a\u062c\u0628 \u0644\u062f\u0639\u0648\u062a\u0647\u060c \u0648\u0645\u0646\u0639 \u0627\u0644\u0646\u0627\u0633 \u0645\u0646 \u0627\u062a\u0628\u0627\u0639\u0647. \u0648\u062d\u0633\u0628\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0643\u0630\u0628\u0648\u0646- \u0646\u0627\u0631 \u062c\u0647\u0646\u0645 \u062a\u0633\u0639\u0651\u064e\u0631 \u0628\u0643\u0645.","4:56":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u062c\u062d\u062f\u0648\u0627 \u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0622\u064a\u0627\u062a\u0647 \u0648\u0648\u062d\u064a \u0643\u062a\u0627\u0628\u0647 \u0648\u062f\u0644\u0627\u0626\u0644\u0647 \u0648\u062d\u062c\u062c\u0647\u060c \u0633\u0648\u0641 \u0646\u062f\u062e\u0644\u0647\u0645 \u0646\u0627\u0631\u064b\u0627 \u064a\u0642\u0627\u0633\u0648\u0646 \u062d\u0631\u0651\u064e\u0647\u0627\u060c \u0643\u0644\u0645\u0627 \u0627\u062d\u062a\u0631\u0642\u062a \u062c\u0644\u0648\u062f\u0647\u0645 \u0628\u062f\u0651\u064e\u0644\u0652\u0646\u0627\u0647\u0645 \u062c\u0644\u0648\u062f\u064b\u0627 \u0623\u062e\u0631\u0649; \u0644\u064a\u0633\u062a\u0645\u0631 \u0639\u0630\u0627\u0628\u0647\u0645 \u0648\u0623\u0644\u0645\u0647\u0645. \u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0643\u0627\u0646 \u0639\u0632\u064a\u0632\u064b\u0627 \u0644\u0627 \u064a\u0645\u062a\u0646\u0639 \u0639\u0644\u064a\u0647 \u0634\u064a\u0621\u060c \u062d\u0643\u064a\u0645\u064b\u0627 \u0641\u064a \u062a\u062f\u0628\u064a\u0631\u0647 \u0648\u0642\u0636\u0627\u0626\u0647.","4:57":"\u0648\u0627\u0644\u0630\u064a\u0646 \u0627\u0637\u0645\u0623\u0646\u062a \u0642\u0644\u0648\u0628\u0647\u0645 \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0627\u0644\u062a\u0635\u062f\u064a\u0642 \u0628\u0631\u0633\u0627\u0644\u0629 \u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0627\u0633\u062a\u0642\u0627\u0645\u0648\u0627 \u0639\u0644\u0649 \u0627\u0644\u0637\u0627\u0639\u0629\u060c \u0633\u0646\u062f\u062e\u0644\u0647\u0645 \u062c\u0646\u0627\u062a \u062a\u062c\u0631\u064a \u0645\u0646 \u062a\u062d\u062a\u0647\u0627 \u0627\u0644\u0623\u0646\u0647\u0627\u0631\u060c \u064a\u0646\u0639\u0645\u0648\u0646 \u0641\u064a\u0647\u0627 \u0623\u0628\u062f\u064b\u0627 \u0648\u0644\u0627 \u064a\u062e\u0631\u062c\u0648\u0646 \u0645\u0646\u0647\u0627\u060c \u0648\u0644\u0647\u0645 \u0641\u064a\u0647\u0627 \u0623\u0632\u0648\u0627\u062c \u0637\u0647\u0631\u0647\u0627 \u0627\u0644\u0644\u0647 \u0645\u0650\u0646 \u0643\u0644 \u0623\u0630\u0649\u060c \u0648\u0646\u062f\u062e\u0644\u0647\u0645 \u0638\u0644\u0627 \u0643\u062b\u064a\u0641\u064b\u0627 \u0645\u0645\u062a\u062f\u064b\u0627 \u0641\u064a \u0627\u0644\u062c\u0646\u0629.","4:58":"\u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u064a\u0623\u0645\u0631\u0643\u0645 \u0628\u0623\u062f\u0627\u0621 \u0645\u062e\u062a\u0644\u0641 \u0627\u0644\u0623\u0645\u0627\u0646\u0627\u062a\u060c \u0627\u0644\u062a\u064a \u0627\u0624\u062a\u0645\u0646\u062a\u0645 \u0639\u0644\u064a\u0647\u0627 \u0625\u0644\u0649 \u0623\u0635\u062d\u0627\u0628\u0647\u0627\u060c \u0641\u0644\u0627 \u062a\u0641\u0631\u0637\u0648\u0627 \u0641\u064a\u0647\u0627\u060c \u0648\u064a\u0623\u0645\u0631\u0643\u0645 \u0628\u0627\u0644\u0642\u0636\u0627\u0621 \u0628\u064a\u0646 \u0627\u0644\u0646\u0627\u0633 \u0628\u0627\u0644\u0639\u062f\u0644 \u0648\u0627\u0644\u0642\u0633\u0637\u060c \u0625\u0630\u0627 \u0642\u0636\u064a\u062a\u0645 \u0628\u064a\u0646\u0647\u0645\u060c \u0648\u0646\u0650\u0639\u0652\u0645\u064e \u0645\u0627 \u064a\u0639\u0638\u0643\u0645 \u0627\u0644\u0644\u0647 \u0628\u0647 \u0648\u064a\u0647\u062f\u064a\u0643\u0645 \u0625\u0644\u064a\u0647. \u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0643\u0627\u0646 \u0633\u0645\u064a\u0639\u064b\u0627 \u0644\u0623\u0642\u0648\u0627\u0644\u0643\u0645\u060c \u0645\u064f\u0637\u0651\u064e\u0644\u0639\u064b\u0627 \u0639\u0644\u0649 \u0633\u0627\u0626\u0631 \u0623\u0639\u0645\u0627\u0644\u0643\u0645\u060c \u0628\u0635\u064a\u0631\u064b\u0627 \u0628\u0647\u0627.","4:59":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647\u060c \u0627\u0633\u062a\u062c\u064a\u0628\u0648\u0627 \u0644\u0623\u0648\u0627\u0645\u0631 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0644\u0627 \u062a\u0639\u0635\u0648\u0647\u060c \u0648\u0627\u0633\u062a\u062c\u064a\u0628\u0648\u0627 \u0644\u0644\u0631\u0633\u0648\u0644 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0641\u064a\u0645\u0627 \u062c\u0627\u0621 \u0628\u0647 \u0645\u0646 \u0627\u0644\u062d\u0642\u060c \u0648\u0623\u0637\u064a\u0639\u0648\u0627 \u0648\u0644\u0627\u0629 \u0623\u0645\u0631\u0643\u0645 \u0641\u064a \u063a\u064a\u0631 \u0645\u0639\u0635\u064a\u0629 \u0627\u0644\u0644\u0647\u060c \u0641\u0625\u0646 \u0627\u062e\u062a\u0644\u0641\u062a\u0645 \u0641\u064a \u0634\u064a\u0621 \u0628\u064a\u0646\u0643\u0645\u060c \u0641\u0623\u0631\u062c\u0639\u0648\u0627 \u0627\u0644\u062d\u0643\u0645 \u0641\u064a\u0647 \u0625\u0644\u0649 \u0643\u062a\u0627\u0628 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0633\u0646\u0629 \u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0625\u0646 \u0643\u0646\u062a\u0645 \u062a\u0624\u0645\u0646\u0648\u0646 \u062d\u0642 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0628\u064a\u0648\u0645 \u0627\u0644\u062d\u0633\u0627\u0628. \u0630\u0644\u0643 \u0627\u0644\u0631\u062f\u0651\u064f \u0625\u0644\u0649 \u0627\u0644\u0643\u062a\u0627\u0628 \u0648\u0627\u0644\u0633\u0646\u0629 \u062e\u064a\u0631 \u0644\u0643\u0645 \u0645\u0646 \u0627\u0644\u062a\u0646\u0627\u0632\u0639 \u0648\u0627\u0644\u0642\u0648\u0644 \u0628\u0627\u0644\u0631\u0623\u064a\u060c \u0648\u0623\u062d\u0633\u0646 \u0639\u0627\u0642\u0628\u0629 \u0648\u0645\u0622\u0644\u0627.","4:60":"\u0623\u0644\u0645 \u062a\u0639\u0644\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0623\u0645\u0631 \u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u062f\u0651\u064e\u0639\u0648\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0645\u0627 \u0623\u064f\u0646\u0632\u0644 \u0625\u0644\u064a\u0643 -\u0648\u0647\u0648 \u0627\u0644\u0642\u0631\u0622\u0646- \u0648\u0628\u0645\u0627 \u0623\u064f\u0646\u0632\u0644 \u0625\u0644\u0649 \u0627\u0644\u0631\u0633\u0644 \u0645\u0646 \u0642\u0628\u0644\u0643\u060c \u0648\u0647\u0645 \u064a\u0631\u064a\u062f\u0648\u0646 \u0623\u0646 \u064a\u062a\u062d\u0627\u0643\u0645\u0648\u0627 \u0641\u064a \u0641\u064e\u0635\u0652\u0644 \u0627\u0644\u062e\u0635\u0648\u0645\u0627\u062a \u0628\u064a\u0646\u0647\u0645 \u0625\u0644\u0649 \u063a\u064a\u0631 \u0645\u0627 \u0634\u0631\u0639 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u0628\u0627\u0637\u0644\u060c \u0648\u0642\u062f \u0623\u064f\u0645\u0631\u0648\u0627 \u0623\u0646 \u064a\u0643\u0641\u0631\u0648\u0627 \u0628\u0627\u0644\u0628\u0627\u0637\u0644\u061f \u0648\u064a\u0631\u064a\u062f \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0623\u0646 \u064a\u0628\u0639\u062f\u0647\u0645 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u062d\u0642\u060c \u0628\u0639\u062f\u064b\u0627 \u0634\u062f\u064a\u062f\u064b\u0627. \u0648\u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0629 \u062f\u0644\u064a\u0644 \u0639\u0644\u0649 \u0623\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0627\u0644\u0635\u0627\u062f\u0642\u060c \u064a\u0642\u062a\u0636\u064a \u0627\u0644\u0627\u0646\u0642\u064a\u0627\u062f \u0644\u0634\u0631\u0639 \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u0644\u062d\u0643\u0645 \u0628\u0647 \u0641\u064a \u0643\u0644 \u0623\u0645\u0631 \u0645\u0646 \u0627\u0644\u0623\u0645\u0648\u0631\u060c \u0641\u0645\u0646 \u0632\u0639\u0645 \u0623\u0646\u0647 \u0645\u0624\u0645\u0646 \u0648\u0627\u062e\u062a\u0627\u0631 \u062d\u0643\u0645 \u0627\u0644\u0637\u0627\u063a\u0648\u062a \u0639\u0644\u0649 \u062d\u0643\u0645 \u0627\u0644\u0644\u0647\u060c \u0641\u0647\u0648 \u0643\u0627\u0630\u0628 \u0641\u064a \u0632\u0639\u0645\u0647.","4:61":"\u0648\u0625\u0630\u0627 \u0646\u064f\u0635\u062d \u0647\u0624\u0644\u0627\u0621\u060c \u0648\u0642\u064a\u0644 \u0644\u0647\u0645: \u062a\u0639\u0627\u0644\u0648\u0627 \u0625\u0644\u0649 \u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647\u060c \u0648\u0625\u0644\u0649 \u0627\u0644\u0631\u0633\u0648\u0644 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0647\u062f\u064a\u0647\u060c \u0623\u0628\u0635\u064e\u0631\u0652\u062a\u064e \u0627\u0644\u0630\u064a\u0646 \u064a\u0638\u0647\u0631\u0648\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u064a\u0628\u0637\u0646\u0648\u0646 \u0627\u0644\u0643\u0641\u0631\u060c \u064a\u0639\u0631\u0636\u0648\u0646 \u0639\u0646\u0643 \u0625\u0639\u0631\u0627\u0636\u064b\u0627.","4:62":"\u0641\u0643\u064a\u0641 \u064a\u0643\u0648\u0646 \u062d\u0627\u0644 \u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0645\u0646\u0627\u0641\u0641\u064a\u0646\u060c \u0625\u0630\u0627 \u062d\u0644\u0651\u064e\u062a \u0628\u0647\u0645 \u0645\u0635\u064a\u0628\u0629 \u0628\u0633\u0628\u0628 \u0645\u0627 \u0627\u0642\u062a\u0631\u0641\u0648\u0647 \u0628\u0623\u064a\u062f\u064a\u0647\u0645\u060c \u062b\u0645 \u062c\u0627\u0624\u0648\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u064a\u0639\u062a\u0630\u0631\u0648\u0646\u060c \u0648\u064a\u0624\u0643\u062f\u0648\u0646 \u0644\u0643 \u0623\u0646\u0647\u0645 \u0645\u0627 \u0642\u0635\u062f\u0648\u0627 \u0628\u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u062a\u0644\u0643 \u0625\u0644\u0627 \u0627\u0644\u0625\u062d\u0633\u0627\u0646 \u0648\u0627\u0644\u062a\u0648\u0641\u064a\u0642 \u0628\u064a\u0646 \u0627\u0644\u062e\u0635\u0648\u0645\u061f","4:63":"\u0623\u0648\u0644\u0626\u0643 \u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u064a\u0639\u0644\u0645 \u0627\u0644\u0644\u0647 \u062d\u0642\u064a\u0642\u0629 \u0645\u0627 \u0641\u064a \u0642\u0644\u0648\u0628\u0647\u0645 \u0645\u0646 \u0627\u0644\u0646\u0641\u0627\u0642\u060c \u0641\u062a\u0648\u0644\u0651\u064e \u0639\u0646\u0647\u0645\u060c \u0648\u062d\u0630\u0651\u0650\u0631\u0647\u0645 \u0645\u0646 \u0633\u0648\u0621 \u0645\u0627 \u0647\u0645 \u0639\u0644\u064a\u0647\u060c \u0648\u0642\u0644 \u0644\u0647\u0645 \u0642\u0648\u0644\u0627 \u0645\u0624\u062b\u0631\u064b\u0627 \u0641\u064a\u0647\u0645 \u0632\u0627\u062c\u0631\u064b\u0627 \u0644\u0647\u0645.","4:64":"\u0648\u0645\u0627 \u0628\u0639\u064e\u062b\u0652\u0646\u064e\u0627 \u0645\u0646 \u0631\u0633\u0648\u0644 \u0645\u0646 \u0631\u0633\u0644\u0646\u0627\u060c \u0625\u0644\u0627 \u0644\u064a\u0633\u062a\u062c\u0627\u0628 \u0644\u0647\u060c \u0628\u0623\u0645\u0631 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0642\u0636\u0627\u0626\u0647. \u0648\u0644\u0648 \u0623\u0646 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u0638\u0644\u0645\u0648\u0627 \u0623\u0646\u0641\u0633\u0647\u0645 \u0628\u0627\u0642\u062a\u0631\u0627\u0641 \u0627\u0644\u0633\u064a\u0626\u0627\u062a\u060c \u062c\u0627\u0624\u0648\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0641\u064a \u062d\u064a\u0627\u062a\u0643 \u062a\u0627\u0626\u0628\u064a\u0646 \u0633\u0627\u0626\u0644\u064a\u0646 \u0627\u0644\u0644\u0647 \u0623\u0646 \u064a\u063a\u0641\u0631 \u0644\u0647\u0645 \u0630\u0646\u0648\u0628\u0647\u0645\u060c \u0648\u0627\u0633\u062a\u063a\u0641\u0631\u062a \u0644\u0647\u0645\u060c \u0644\u0648\u062c\u062f\u0648\u0627 \u0627\u0644\u0644\u0647 \u062a\u0648\u0627\u0628\u064b\u0627 \u0631\u062d\u064a\u0645\u064b\u0627.","4:65":"\u0623\u0642\u0633\u0645 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0628\u0646\u0641\u0633\u0647 \u0627\u0644\u0643\u0631\u064a\u0645\u0629 \u0623\u0646 \u0647\u0624\u0644\u0627\u0621 \u0644\u0627 \u064a\u0624\u0645\u0646\u0648\u0646 \u062d\u0642\u064a\u0642\u0629 \u062d\u062a\u0649 \u064a\u062c\u0639\u0644\u0648\u0643 \u062d\u0643\u0645\u064b\u0627 \u0641\u064a\u0645\u0627 \u0648\u0642\u0639 \u0628\u064a\u0646\u0647\u0645 \u0645\u0646 \u0646\u0632\u0627\u0639 \u0641\u064a \u062d\u064a\u0627\u062a\u0643\u060c \u0648\u064a\u062a\u062d\u0627\u0643\u0645\u0648\u0627 \u0625\u0644\u0649 \u0633\u0646\u062a\u0643 \u0628\u0639\u062f \u0645\u0645\u0627\u062a\u0643\u060c \u062b\u0645 \u0644\u0627 \u064a\u062c\u062f\u0648\u0627 \u0641\u064a \u0623\u0646\u0641\u0633\u0647\u0645 \u0636\u064a\u0642\u064b\u0627 \u0645\u0645\u0627 \u0627\u0646\u062a\u0647\u0649 \u0625\u0644\u064a\u0647 \u062d\u0643\u0645\u0643\u060c \u0648\u064a\u0646\u0642\u0627\u062f\u0648\u0627 \u0645\u0639 \u0630\u0644\u0643 \u0627\u0646\u0642\u064a\u0627\u062f\u064b\u0627 \u062a\u0627\u0645\u0627\u064b\u060c \u0641\u0627\u0644\u062d\u0643\u0645 \u0628\u0645\u0627 \u062c\u0627\u0621 \u0628\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0645\u0646 \u0627\u0644\u0643\u062a\u0627\u0628 \u0648\u0627\u0644\u0633\u0646\u0629 \u0641\u064a \u0643\u0644 \u0634\u0623\u0646 \u0645\u0646 \u0634\u0624\u0648\u0646 \u0627\u0644\u062d\u064a\u0627\u0629 \u0645\u0646 \u0635\u0645\u064a\u0645 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0645\u0639 \u0627\u0644\u0631\u0636\u0627 \u0648\u0627\u0644\u062a\u0633\u0644\u064a\u0645.","4:66":"\u0648\u0644\u0648 \u0623\u0648\u062c\u0628\u0646\u0627 \u0639\u0644\u0649 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0627\u0644\u0645\u062a\u062d\u0627\u0643\u0645\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u0637\u0627\u063a\u0648\u062a \u0623\u0646 \u064a\u0642\u062a\u0644 \u0628\u0639\u0636\u0647\u0645 \u0628\u0639\u0636\u064b\u0627\u060c \u0623\u0648 \u0623\u0646 \u064a\u062e\u0631\u062c\u0648\u0627 \u0645\u0646 \u062f\u064a\u0627\u0631\u0647\u0645\u060c \u0645\u0627 \u0627\u0633\u062a\u062c\u0627\u0628 \u0644\u0630\u0644\u0643 \u0625\u0644\u0627 \u0639\u062f\u062f \u0642\u0644\u064a\u0644 \u0645\u0646\u0647\u0645\u060c \u0648\u0644\u0648 \u0623\u0646\u0647\u0645 \u0627\u0633\u062a\u062c\u0627\u0628\u0648\u0627 \u0644\u0645\u0627 \u064a\u064f\u0646\u0635\u062d\u0648\u0646 \u0628\u0647 \u0644\u0643\u0627\u0646 \u0630\u0644\u0643 \u0646\u0627\u0641\u0639\u064b\u0627 \u0644\u0647\u0645\u060c \u0648\u0623\u0642\u0648\u0649 \u0644\u0625\u064a\u0645\u0627\u0646\u0647\u0645\u060c \u0648\u0644\u0623\u0639\u0637\u064a\u0646\u0627\u0647\u0645 \u0645\u0646 \u0639\u0646\u062f\u0646\u0627 \u062b\u0648\u0627\u0628\u064b\u0627 \u0639\u0638\u064a\u0645\u064b\u0627 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u0644\u0623\u0631\u0634\u062f\u0646\u0627\u0647\u0645 \u0648\u0648\u0641\u0642\u0646\u0627\u0647\u0645 \u0625\u0644\u0649 \u0637\u0631\u064a\u0642 \u0627\u0644\u0644\u0647 \u0627\u0644\u0642\u0648\u064a\u0645.","4:67":"@4:66","4:68":"@4:66","4:69":"\u0648\u0645\u0646 \u064a\u0633\u062a\u062c\u0628 \u0644\u0623\u0648\u0627\u0645\u0631 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0647\u062f\u064a \u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0641\u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0630\u064a\u0646 \u0639\u064e\u0638\u064f\u0645\u064e \u0634\u0623\u0646\u0647\u0645 \u0648\u0642\u062f\u0631\u0647\u0645\u060c \u0641\u0643\u0627\u0646\u0648\u0627 \u0641\u064a \u0635\u062d\u0628\u0629 \u0645\u064e\u0646 \u0623\u0646\u0639\u0645 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0644\u064a\u0647\u0645 \u0628\u0627\u0644\u062c\u0646\u0629 \u0645\u0646 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0648\u0627\u0644\u0635\u062f\u064a\u0642\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0643\u0645\u064f\u0644 \u062a\u0635\u062f\u064a\u0642\u0647\u0645 \u0628\u0645\u0627 \u062c\u0627\u0621\u062a \u0628\u0647 \u0627\u0644\u0631\u0633\u0644\u060c \u0627\u0639\u062a\u0642\u0627\u062f\u064b\u0627 \u0648\u0642\u0648\u0644\u0627 \u0648\u0639\u0645\u0644\u0627 \u0648\u0627\u0644\u0634\u0647\u062f\u0627\u0621 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0648\u0635\u0627\u0644\u062d \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0648\u062d\u064e\u0633\u064f\u0646\u064e \u0647\u0624\u0644\u0627\u0621 \u0631\u0641\u0642\u0627\u0621 \u0641\u064a \u0627\u0644\u062c\u0646\u0629.","4:70":"\u0630\u0644\u0643 \u0627\u0644\u0639\u0637\u0627\u0621 \u0627\u0644\u062c\u0632\u064a\u0644 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647. \u0648\u0643\u0641\u0649 \u0628\u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0645\u0627 \u064a\u0639\u0644\u0645 \u0623\u062d\u0648\u0627\u0644 \u0639\u0628\u0627\u062f\u0647\u060c \u0648\u0645\u064e\u0646 \u064a\u064e\u0633\u062a\u062d\u0642\u0651\u064f \u0645\u0646\u0647\u0645 \u0627\u0644\u062b\u0648\u0627\u0628 \u0627\u0644\u062c\u0632\u064a\u0644 \u0628\u0645\u0627 \u0642\u0627\u0645 \u0628\u0647 \u0645\u0646 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0635\u0627\u0644\u062d\u0629.","4:71":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u062e\u0630\u0648\u0627 \u062d\u0630\u0631\u0643\u0645 \u0628\u0627\u0644\u0627\u0633\u062a\u0639\u062f\u0627\u062f \u0644\u0639\u062f\u0648\u0643\u0645\u060c \u0641\u0627\u062e\u0631\u062c\u0648\u0627 \u0644\u0645\u0644\u0627\u0642\u0627\u062a\u0647 \u062c\u0645\u0627\u0639\u0629 \u0628\u0639\u062f \u062c\u0645\u0627\u0639\u0629 \u0623\u0648 \u0645\u062c\u062a\u0645\u0639\u064a\u0646.","4:72":"\u0648\u0625\u0646\u0651\u064e \u0645\u0646\u0643\u0645 \u0644\u0646\u0641\u0631\u064b\u0627 \u064a\u062a\u0623\u062e\u0631 \u0639\u0646 \u0627\u0644\u062e\u0631\u0648\u062c \u0644\u0645\u0644\u0627\u0642\u0627\u0629 \u0627\u0644\u0623\u0639\u062f\u0627\u0621 \u0645\u062a\u062b\u0627\u0642\u0644\u0627 \u0648\u064a\u062b\u0628\u0637 \u063a\u064a\u0631\u0647 \u0639\u0646 \u0639\u0645\u062f \u0648\u0625\u0635\u0631\u0627\u0631\u060c \u0641\u0625\u0646 \u0642\u064f\u062f\u0651\u0650\u0631 \u0639\u0644\u064a\u0643\u0645 \u0648\u0623\u064f\u0635\u0650\u0628\u062a\u0645 \u0628\u0642\u062a\u0644 \u0648\u0647\u0632\u064a\u0645\u0629\u060c \u0642\u0627\u0644 \u0645\u0633\u062a\u0628\u0634\u0631\u064b\u0627: \u0642\u062f \u062d\u0641\u0638\u0646\u064a \u0627\u0644\u0644\u0647\u060c \u062d\u064a\u0646 \u0644\u0645 \u0623\u0643\u0646 \u062d\u0627\u0636\u0631\u064b\u0627 \u0645\u0639 \u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0630\u064a\u0646 \u0648\u0642\u0639 \u0644\u0647\u0645 \u0645\u0627 \u0623\u0643\u0631\u0647\u0647 \u0644\u0646\u0641\u0633\u064a\u060c \u0648\u0633\u0631\u0651\u064e\u0647 \u062a\u062e\u0644\u0641\u0647 \u0639\u0646\u0643\u0645.","4:73":"\u0648\u0644\u0626\u0646 \u0646\u0627\u0644\u0643\u0645 \u0641\u0636\u0644 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0648\u063a\u0646\u064a\u0645\u0629\u060c \u0644\u064a\u0642\u0648\u0644\u0646 -\u062d\u0627\u0633\u062f\u064b\u0627 \u0645\u062a\u062d\u0633\u0631\u064b\u0627\u060c \u0643\u0623\u0646 \u0644\u0645 \u062a\u0643\u0646 \u0628\u064a\u0646\u0643\u0645 \u0648\u0628\u064a\u0646\u0647 \u0645\u0648\u062f\u0629 \u0641\u064a \u0627\u0644\u0638\u0627\u0647\u0631-: \u064a\u0627 \u0644\u064a\u062a\u0646\u064a \u0643\u0646\u062a \u0645\u0639\u0647\u0645 \u0641\u0623\u0638\u0641\u0631 \u0628\u0645\u0627 \u0638\u064e\u0641\u0650\u0631\u0648\u0627 \u0628\u0647 \u0645\u0646 \u0627\u0644\u0646\u062c\u0627\u0629 \u0648\u0627\u0644\u0646\u0635\u0631\u0629 \u0648\u0627\u0644\u063a\u0646\u064a\u0645\u0629.","4:74":"\u0641\u0644\u064a\u062c\u0627\u0647\u062f \u0641\u064a \u0633\u0628\u064a\u0644 \u0646\u0635\u0631\u0629 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u0625\u0639\u0644\u0627\u0621 \u0643\u0644\u0645\u062a\u0647\u060c \u0627\u0644\u0630\u064a\u0646 \u064a\u0628\u064a\u0639\u0648\u0646 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627 \u0628\u0627\u0644\u062f\u0627\u0631 \u0627\u0644\u0622\u062e\u0631\u0629 \u0648\u062b\u0648\u0627\u0628\u0647\u0627. \u0648\u0645\u0646 \u064a\u062c\u0627\u0647\u062f \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0645\u062e\u0644\u0635\u064b\u0627\u060c \u0641\u064a\u064f\u0642\u0652\u062a\u064e\u0644\u0652 \u0623\u0648 \u064a\u064e\u063a\u0652\u0644\u0650\u0628\u0652\u060c \u0641\u0633\u0648\u0641 \u0646\u0624\u062a\u064a\u0647 \u0623\u062c\u0631\u064b\u0627 \u0639\u0638\u064a\u0645\u064b\u0627.","4:75":"\u0648\u0645\u0627 \u0627\u0644\u0630\u064a \u064a\u0645\u0646\u0639\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0639\u0646 \u0627\u0644\u062c\u0647\u0627\u062f \u0641\u064a \u0633\u0628\u064a\u0644 \u0646\u0635\u0631\u0629 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u0646\u0635\u0631\u0629 \u0639\u0628\u0627\u062f\u0647 \u0627\u0644\u0645\u0633\u062a\u0636\u0639\u0641\u064a\u0646 \u0645\u0646 \u0627\u0644\u0631\u062c\u0627\u0644 \u0648\u0627\u0644\u0646\u0633\u0627\u0621 \u0648\u0627\u0644\u0635\u063a\u0627\u0631 \u0627\u0644\u0630\u064a\u0646 \u0627\u0639\u062a\u064f\u062f\u064a \u0639\u0644\u064a\u0647\u0645\u060c \u0648\u0644\u0627 \u062d\u064a\u0644\u0629 \u0644\u0647\u0645 \u0648\u0644\u0627 \u0648\u0633\u064a\u0644\u0629 \u0644\u062f\u064a\u0647\u0645 \u0625\u0644\u0627 \u0627\u0644\u0627\u0633\u062a\u063a\u0627\u062b\u0629 \u0628\u0631\u0628\u0647\u0645\u060c \u064a\u062f\u0639\u0648\u0646\u0647 \u0642\u0627\u0626\u0644\u064a\u0646: \u0631\u0628\u0646\u0627 \u0623\u062e\u0631\u062c\u0646\u0627 \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0642\u0631\u064a\u0629 -\u064a\u0639\u0646\u064a \xab\u0645\u0643\u0629\xbb - \u0627\u0644\u062a\u064a \u0638\u064e\u0644\u064e\u0645 \u0623\u0647\u0644\u0647\u0627 \u0623\u0646\u0641\u0633\u0647\u0645 \u0628\u0627\u0644\u0643\u0641\u0631 \u0648\u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0628\u0627\u0644\u0623\u0630\u0649\u060c \u0648\u0627\u062c\u0639\u0644 \u0644\u0646\u0627 \u0645\u0646 \u0639\u0646\u062f\u0643 \u0648\u0644\u064a\u0651\u0627\u064b \u064a\u062a\u0648\u0644\u0649 \u0623\u0645\u0648\u0631\u0646\u0627\u060c \u0648\u0646\u0635\u064a\u0631\u064b\u0627 \u064a\u0646\u0635\u0631\u0646\u0627 \u0639\u0644\u0649 \u0627\u0644\u0638\u0627\u0644\u0645\u064a\u0646\u061f","4:76":"\u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u064e\u0642\u064f\u0648\u0627 \u0641\u064a \u0625\u064a\u0645\u0627\u0646\u0647\u0645 \u0627\u0639\u062a\u0642\u0627\u062f\u064b\u0627 \u0648\u0639\u0645\u0644\u0627 \u064a\u062c\u0627\u0647\u062f\u0648\u0646 \u0641\u064a \u0633\u0628\u064a\u0644 \u0646\u0635\u0631\u0629 \u0627\u0644\u062d\u0642 \u0648\u0623\u0647\u0644\u0647\u060c \u0648\u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u064a\u0642\u0627\u062a\u0644\u0648\u0646 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0628\u063a\u064a \u0648\u0627\u0644\u0641\u0633\u0627\u062f \u0641\u064a \u0627\u0644\u0623\u0631\u0636\u060c \u0641\u0642\u0627\u062a\u0644\u0648\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0623\u0647\u0644 \u0627\u0644\u0643\u0641\u0631 \u0648\u0627\u0644\u0634\u0631\u0643 \u0627\u0644\u0630\u064a\u0646 \u064a\u062a\u0648\u0644\u0651\u064e\u0648\u0646 \u0627\u0644\u0634\u064a\u0637\u0627\u0646\u060c \u0648\u064a\u0637\u064a\u0639\u0648\u0646 \u0623\u0645\u0631\u0647\u060c \u0625\u0646 \u062a\u062f\u0628\u064a\u0631 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0644\u0623\u0648\u0644\u064a\u0627\u0626\u0647 \u0643\u0627\u0646 \u0636\u0639\u064a\u0641\u064b\u0627.","4:77":"\u0623\u0644\u0645 \u062a\u0639\u0644\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0623\u0645\u0631 \u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0630\u064a\u0646 \u0642\u064a\u0644 \u0644\u0647\u0645 \u0642\u0628\u0644 \u0627\u0644\u0625\u0630\u0646 \u0628\u0627\u0644\u062c\u0647\u0627\u062f: \u0627\u0645\u0646\u0639\u0648\u0627 \u0623\u064a\u062f\u064a\u0643\u0645 \u0639\u0646 \u0642\u062a\u0627\u0644 \u0623\u0639\u062f\u0627\u0626\u0643\u0645 \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646\u060c \u0648\u0639\u0644\u064a\u0643\u0645 \u0623\u062f\u0627\u0621 \u0645\u0627 \u0641\u0631\u0636\u0647 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0645\u0646 \u0627\u0644\u0635\u0644\u0627\u0629\u060c \u0648\u0627\u0644\u0632\u0643\u0627\u0629\u060c \u0641\u0644\u0645\u0627 \u0641\u0631\u0636 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0642\u062a\u0627\u0644 \u0625\u0630\u0627 \u062c\u0645\u0627\u0639\u0629 \u0645\u0646\u0647\u0645 \u0642\u062f \u062a\u063a\u064a\u0631 \u062d\u0627\u0644\u0647\u0645\u060c \u0641\u0623\u0635\u0628\u062d\u0648\u0627 \u064a\u062e\u0627\u0641\u0648\u0646 \u0627\u0644\u0646\u0627\u0633 \u0648\u064a\u0631\u0647\u0628\u0648\u0646\u0647\u0645\u060c \u0643\u062e\u0648\u0641\u0647\u0645 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0623\u0648 \u0623\u0634\u062f\u060c \u0648\u064a\u0639\u0644\u0646\u0648\u0646 \u0639\u0645\u0627 \u0627\u0639\u062a\u0631\u0627\u0647\u0645 \u0645\u0646 \u0634\u062f\u0629 \u0627\u0644\u062e\u0648\u0641\u060c \u0641\u064a\u0642\u0648\u0644\u0648\u0646: \u0631\u0628\u0646\u0627 \u0644\u0650\u0645\u064e \u0623\u064e\u0648\u0652\u062c\u064e\u0628\u0652\u062a\u064e \u0639\u0644\u064a\u0646\u0627 \u0627\u0644\u0642\u062a\u0627\u0644\u061f \u0647\u0644\u0627 \u0623\u0645\u0647\u0644\u062a\u0646\u0627 \u0625\u0644\u0649 \u0648\u0642\u062a \u0642\u0631\u064a\u0628\u060c \u0631\u063a\u0628\u0629 \u0645\u0646\u0647\u0645 \u0641\u064a \u0645\u062a\u0627\u0639 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0645\u062a\u0627\u0639 \u0627\u0644\u062f\u0646\u064a\u0627 \u0642\u0644\u064a\u0644\u060c \u0648\u0627\u0644\u0622\u062e\u0631\u0629 \u0648\u0645\u0627 \u0641\u064a\u0647\u0627 \u0623\u0639\u0638\u0645 \u0648\u0623\u0628\u0642\u0649 \u0644\u0645\u0646 \u0627\u062a\u0642\u0649\u060c \u0641\u0639\u0645\u0644 \u0628\u0645\u0627 \u0623\u064f\u0645\u0631 \u0628\u0647\u060c \u0648\u0627\u062c\u062a\u0646\u0628 \u0645\u0627 \u0646\u064f\u0647\u064a \u0639\u0646\u0647. \u0644\u0627 \u064a\u0638\u0644\u0645 \u0631\u0628\u0643 \u0623\u062d\u062f\u064b\u0627 \u0634\u064a\u0626\u064b\u0627\u060c \u0648\u0644\u0648 \u0643\u0627\u0646 \u0645\u0642\u062f\u0627\u0631 \u0627\u0644\u062e\u064a\u0637 \u0627\u0644\u0630\u064a \u064a\u0643\u0648\u0646 \u0641\u064a \u0634\u0642 \u0646\u064e\u0648\u0627\u0629 \u0627\u0644\u062a\u0645\u0631\u0629.","4:78":"\u0623\u064a\u0646\u0645\u0627 \u062a\u0643\u0648\u0646\u0648\u0627 \u064a\u0644\u062d\u0642\u0643\u0645 \u0627\u0644\u0645\u0648\u062a \u0641\u064a \u0623\u064a \u0645\u0643\u0627\u0646 \u0643\u0646\u062a\u0645 \u0641\u064a\u0647 \u0639\u0646\u062f \u062d\u0644\u0648\u0644 \u0622\u062c\u0627\u0644\u0643\u0645\u060c \u0648\u0644\u0648 \u0643\u0646\u062a\u0645 \u0641\u064a \u062d\u0635\u0648\u0646 \u0645\u0646\u064a\u0639\u0629 \u0628\u0639\u064a\u062f\u0629 \u0639\u0646 \u0633\u0627\u062d\u0629 \u0627\u0644\u0645\u0639\u0627\u0631\u0643 \u0648\u0627\u0644\u0642\u062a\u0627\u0644. \u0648\u0625\u0646 \u064a\u062d\u0635\u0644 \u0644\u0647\u0645 \u0645\u0627 \u064a\u0633\u0631\u0651\u064f\u0647\u0645 \u0645\u0646 \u0645\u062a\u0627\u0639 \u0647\u0630\u0647 \u0627\u0644\u062d\u064a\u0627\u0629\u060c \u064a\u0646\u0633\u0628\u0648\u0627 \u062d\u0635\u0648\u0644\u0647 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0625\u0646 \u064a\u0642\u0639 \u0639\u0644\u064a\u0647\u0645 \u0645\u0627 \u064a\u0643\u0631\u0647\u0648\u0646\u0647 \u064a\u0646\u0633\u0628\u0648\u0647 \u0625\u0644\u0649 \u0627\u0644\u0631\u0633\u0648\u0644 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u062c\u0647\u0627\u0644\u0629 \u0648\u062a\u0634\u0627\u0624\u0645\u064b\u0627\u060c \u0648\u0645\u0627 \u0639\u0644\u0645\u0648\u0627 \u0623\u0646 \u0630\u0644\u0643 \u0643\u0644\u0647 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647\u060c \u0628\u0642\u0636\u0627\u0626\u0647 \u0648\u0642\u062f\u0631\u0647\u060c \u0641\u0645\u0627 \u0628\u0627\u0644\u0647\u0645 \u0644\u0627 \u064a\u0642\u0627\u0631\u0628\u0648\u0646 \u0641\u064e\u0647\u0652\u0645\u064e \u0623\u064a\u0651\u0650 \u062d\u062f\u064a\u062b \u062a\u062d\u062f\u062b\u0647\u0645 \u0628\u0647\u061f","4:79":"\u0645\u0627 \u0623\u0635\u0627\u0628\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0625\u0646\u0633\u0627\u0646- \u0645\u0650\u0646 \u062e\u064a\u0631 \u0648\u0646\u0639\u0645\u0629 \u0641\u0647\u0648 \u0645\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u062d\u062f\u0647\u060c \u0641\u0636\u0644\u0627 \u0648\u0625\u062d\u0633\u0627\u0646\u064b\u0627\u060c \u0648\u0645\u0627 \u0623\u0635\u0627\u0628\u0643 \u0645\u0646 \u062c\u0647\u062f \u0648\u0634\u062f\u0629 \u0641\u0628\u0633\u0628\u0628 \u0639\u0645\u0644\u0643 \u0627\u0644\u0633\u064a\u0626\u060c \u0648\u0645\u0627 \u0627\u0642\u062a\u0631\u0641\u062a\u0647 \u064a\u062f\u0627\u0643 \u0645\u0646 \u0627\u0644\u062e\u0637\u0627\u064a\u0627 \u0648\u0627\u0644\u0633\u064a\u0626\u0627\u062a. \u0648\u0628\u0639\u062b\u0646\u0627\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0639\u0645\u0648\u0645 \u0627\u0644\u0646\u0627\u0633 \u0631\u0633\u0648\u0644\u0627 \u062a\u0628\u0644\u063a\u0647\u0645 \u0631\u0633\u0627\u0644\u0629 \u0631\u0628\u0643\u060c \u0648\u0643\u0641\u0649 \u0628\u0627\u0644\u0644\u0647 \u0634\u0647\u064a\u062f\u064b\u0627 \u0639\u0644\u0649 \u0635\u062f\u0642 \u0631\u0633\u0627\u0644\u062a\u0643.","4:80":"\u0645\u0646 \u064a\u0633\u062a\u062c\u0628 \u0644\u0644\u0631\u0633\u0648\u0644 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u064a\u0639\u0645\u0644 \u0628\u0647\u062f\u064a\u0647\u060c \u0641\u0642\u062f \u0627\u0633\u062a\u062c\u0627\u0628 \u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0627\u0645\u062a\u062b\u0644 \u0623\u0645\u0631\u0647\u060c \u0648\u0645\u0646 \u0623\u0639\u0631\u0636 \u0639\u0646 \u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0641\u0645\u0627 \u0628\u0639\u062b\u0646\u0627\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0639\u0644\u0649 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0639\u062a\u0631\u0636\u064a\u0646 \u0631\u0642\u064a\u0628\u064b\u0627 \u062a\u062d\u0641\u0638 \u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0648\u062a\u062d\u0627\u0633\u0628\u0647\u0645 \u0639\u0644\u064a\u0647\u0627\u060c \u0641\u062d\u0633\u0627\u0628\u0647\u0645 \u0639\u0644\u064a\u0646\u0627.","4:81":"\u0648\u064a\u064f\u0638\u0652\u0647\u0631 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0639\u0631\u0636\u0648\u0646 -\u0648\u0647\u0645 \u0641\u064a \u0645\u062c\u0644\u0633 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645- \u0637\u0627\u0639\u062a\u0647\u0645 \u0644\u0644\u0631\u0633\u0648\u0644 \u0648\u0645\u0627 \u062c\u0627\u0621 \u0628\u0647\u060c \u0641\u0625\u0630\u0627 \u0627\u0628\u062a\u0639\u062f\u0648\u0627 \u0639\u0646\u0647 \u0648\u0627\u0646\u0635\u0631\u0641\u0648\u0627 \u0639\u0646 \u0645\u062c\u0644\u0633\u0647\u060c \u062f\u0628\u0651\u064e\u0631 \u062c\u0645\u0627\u0639\u0629 \u0645\u0646\u0647\u0645 \u0644\u064a\u0644\u0627 \u063a\u064a\u0631 \u0645\u0627 \u0623\u0639\u0644\u0646\u0648\u0647 \u0645\u0646 \u0627\u0644\u0637\u0627\u0639\u0629\u060c \u0648\u0645\u0627 \u0639\u0644\u0645\u0648\u0627 \u0623\u0646 \u0627\u0644\u0644\u0647 \u064a\u062d\u0635\u064a \u0639\u0644\u064a\u0647\u0645 \u0645\u0627 \u064a\u062f\u0628\u0631\u0648\u0646\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a\u0647\u0645 \u0639\u0644\u064a\u0647 \u0623\u062a\u0645 \u0627\u0644\u062c\u0632\u0627\u0621\u060c \u0641\u062a\u0648\u0644 \u0639\u0646\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0648\u0644\u0627 \u062a\u0628\u0627\u0644 \u0628\u0647\u0645\u060c \u0641\u0625\u0646\u0647\u0645 \u0644\u0646 \u064a\u0636\u0631\u0648\u0643\u060c \u0648\u062a\u0648\u0643\u0644 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0648\u062d\u0633\u0628\u0643 \u0628\u0647 \u0648\u0644\u064a\u0651\u0627\u064b \u0648\u0646\u0627\u0635\u0631\u064b\u0627.","4:82":"\u0623\u0641\u0644\u0627 \u064a\u0646\u0638\u0631 \u0647\u0624\u0644\u0627\u0621 \u0641\u064a \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0648\u0645\u0627 \u062c\u0627\u0621 \u0628\u0647 \u0645\u0646 \u0627\u0644\u062d\u0642\u060c \u0646\u0638\u0631 \u062a\u0623\u0645\u0644 \u0648\u062a\u062f\u0628\u0631\u060c \u062d\u064a\u062b \u062c\u0627\u0621 \u0639\u0644\u0649 \u0646\u0633\u0642 \u0645\u062d\u0643\u0645 \u064a\u0642\u0637\u0639 \u0628\u0623\u0646\u0647 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647\u061f \u0648\u0644\u0648 \u0643\u0627\u0646 \u0645\u0650\u0646 \u0639\u0646\u062f \u063a\u064a\u0631\u0647 \u0644\u0648\u062c\u062f\u0648\u0627 \u0641\u064a\u0647 \u0627\u062e\u062a\u0644\u0627\u0641\u064b\u0627 \u0643\u062b\u064a\u0631\u064b\u0627.","4:83":"\u0648\u0625\u0630\u0627 \u062c\u0627\u0621 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u0644\u0645 \u064a\u0633\u062a\u0642\u0631 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0641\u064a \u0642\u0644\u0648\u0628\u0647\u0645 \u0623\u0645\u0652\u0631\u064c \u064a\u062c\u0628 \u0643\u062a\u0645\u0627\u0646\u0647 \u0645\u062a\u0639\u0644\u0642\u064b\u0627 \u0628\u0627\u0644\u0623\u0645\u0646 \u0627\u0644\u0630\u064a \u064a\u0639\u0648\u062f \u062e\u064a\u0631\u0647 \u0639\u0644\u0649 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646\u060c \u0623\u0648 \u0628\u0627\u0644\u062e\u0648\u0641 \u0627\u0644\u0630\u064a \u064a\u0644\u0642\u064a \u0641\u064a \u0642\u0644\u0648\u0628\u0647\u0645 \u0639\u062f\u0645 \u0627\u0644\u0627\u0637\u0645\u0626\u0646\u0627\u0646\u060c \u0623\u0641\u0634\u0648\u0647 \u0648\u0623\u0630\u0627\u0639\u0648\u0627 \u0628\u0647 \u0641\u064a \u0627\u0644\u0646\u0627\u0633\u060c \u0648\u0644\u0648 \u0631\u062f\u0651\u064e \u0647\u0624\u0644\u0627\u0621 \u0645\u0627 \u062c\u0627\u0621\u0647\u0645 \u0625\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u0625\u0644\u0649 \u0623\u0647\u0644 \u0627\u0644\u0639\u0644\u0645 \u0648\u0627\u0644\u0641\u0642\u0647 \u0644\u064e\u0639\u064e\u0644\u0650\u0645\u064e \u062d\u0642\u064a\u0642\u0629 \u0645\u0639\u0646\u0627\u0647 \u0623\u0647\u0644 \u0627\u0644\u0627\u0633\u062a\u0646\u0628\u0627\u0637 \u0645\u0646\u0647\u0645. \u0648\u0644\u0648\u0644\u0627 \u0623\u0646\u0652 \u062a\u064e\u0641\u064e\u0636\u0651\u064e\u0644\u064e \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0648\u0631\u062d\u0645\u0643\u0645 \u0644\u0627\u062a\u0628\u0639\u062a\u0645 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0648\u0648\u0633\u0627\u0648\u0633\u0647 \u0625\u0644\u0627 \u0642\u0644\u064a\u0644\u0627 \u0645\u0646\u0643\u0645.","4:84":"\u0641\u062c\u0627\u0647\u062f -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0644\u0625\u0639\u0644\u0627\u0621 \u0643\u0644\u0645\u062a\u0647\u060c \u0644\u0627 \u062a\u0644\u0632\u0645 \u0641\u0639\u0644 \u063a\u064a\u0631\u0643 \u0648\u0644\u0627 \u062a\u0624\u0627\u062e\u0630 \u0628\u0647\u060c \u0648\u062d\u064f\u0636\u0651\u064e \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0642\u062a\u0627\u0644 \u0648\u0627\u0644\u062c\u0647\u0627\u062f\u060c \u0648\u0631\u063a\u0651\u0650\u0628\u0647\u0645 \u0641\u064a\u0647\u060c \u0644\u0639\u0644 \u0627\u0644\u0644\u0647 \u064a\u0645\u0646\u0639 \u0628\u0643 \u0648\u0628\u0647\u0645 \u0628\u0623\u0633 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0648\u0634\u062f\u062a\u0647\u0645. \u0648\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0623\u0634\u062f \u0642\u0648\u0629 \u0648\u0623\u0639\u0638\u0645 \u0639\u0642\u0648\u0628\u0629 \u0644\u0644\u0643\u0627\u0641\u0631\u064a\u0646.","4:85":"\u0645\u0646 \u064a\u064e\u0633\u0652\u0639\u064e \u0644\u062d\u0635\u0648\u0644 \u063a\u064a\u0631\u0647 \u0639\u0644\u0649 \u0627\u0644\u062e\u064a\u0631 \u064a\u0643\u0646 \u0644\u0647 \u0628\u0634\u0641\u0627\u0639\u062a\u0647 \u0646\u0635\u064a\u0628 \u0645\u0646 \u0627\u0644\u062b\u0648\u0627\u0628\u060c \u0648\u0645\u0646 \u064a\u064e\u0633\u0652\u0639\u064e \u0644\u0625\u064a\u0635\u0627\u0644 \u0627\u0644\u0634\u0631 \u0625\u0644\u0649 \u063a\u064a\u0631\u0647 \u064a\u0643\u0646 \u0644\u0647 \u0646\u0635\u064a\u0628 \u0645\u0646 \u0627\u0644\u0648\u0632\u0631 \u0648\u0627\u0644\u0625\u062b\u0645. \u0648\u0643\u0627\u0646 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0643\u0644 \u0634\u064a\u0621 \u0634\u0627\u0647\u062f\u064b\u0627 \u0648\u062d\u0641\u064a\u0638\u064b\u0627.","4:86":"\u0648\u0625\u0630\u0627 \u0633\u0644\u0651\u064e\u0645 \u0639\u0644\u064a\u0643\u0645 \u0627\u0644\u0645\u0633\u0644\u0645 \u0641\u0631\u062f\u0651\u064f\u0648\u0627 \u0639\u0644\u064a\u0647 \u0628\u0623\u0641\u0636\u0644 \u0645\u0645\u0627 \u0633\u0644\u0651\u064e\u0645 \u0644\u0641\u0638\u064b\u0627 \u0648\u0628\u0634\u0627\u0634\u0629\u064b\u060c \u0623\u0648 \u0631\u062f\u0648\u0627 \u0639\u0644\u064a\u0647 \u0628\u0645\u062b\u0644 \u0645\u0627 \u0633\u0644\u0651\u064e\u0645\u060c \u0648\u0644\u0643\u0644 \u062b\u0648\u0627\u0628\u0647 \u0648\u062c\u0632\u0627\u0624\u0647. \u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0643\u0627\u0646 \u0639\u0644\u0649 \u0643\u0644 \u0634\u064a\u0621 \u0645\u062c\u0627\u0632\u064a\u064b\u0627.","4:87":"\u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0627\u0644\u0645\u062a\u0641\u0631\u062f \u0628\u0627\u0644\u0623\u0644\u0648\u0647\u064a\u0629 \u0644\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u0644\u0642\u060c \u0644\u064a\u062c\u0645\u0639\u0646\u0643\u0645 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u0627\u0644\u0630\u064a \u0644\u0627 \u0634\u0643 \u0641\u064a\u0647\u060c \u0644\u0644\u062d\u0633\u0627\u0628 \u0648\u0627\u0644\u062c\u0632\u0627\u0621. \u0648\u0644\u0627 \u0623\u062d\u062f \u0623\u0635\u062f\u0642 \u0645\u0646 \u0627\u0644\u0644\u0647 \u062d\u062f\u064a\u062b\u064b\u0627 \u0641\u064a\u0645\u0627 \u0623\u062e\u0628\u0631 \u0628\u0647.","4:88":"\u0641\u0645\u0627 \u0644\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0641\u064a \u0634\u0623\u0646 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0625\u0630 \u0627\u062e\u062a\u0644\u0641\u062a\u0645 \u0641\u0631\u0642\u062a\u064a\u0646: \u0641\u0631\u0642\u0629 \u062a\u0642\u0648\u0644 \u0628\u0642\u062a\u0627\u0644\u0647\u0645 \u0648\u0623\u062e\u0631\u0649 \u0644\u0627 \u062a\u0642\u0648\u0644 \u0628\u0630\u0644\u0643\u061f \u0648\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0642\u062f \u0623\u0648\u0642\u0639\u0647\u0645 \u0641\u064a \u0627\u0644\u0643\u0641\u0631 \u0648\u0627\u0644\u0636\u0644\u0627\u0644 \u0628\u0633\u0628\u0628 \u0633\u0648\u0621 \u0623\u0639\u0645\u0627\u0644\u0647\u0645. \u0623\u062a\u0648\u062f\u0648\u0646 \u0647\u062f\u0627\u064a\u0629 \u0645\u0646 \u0635\u0631\u0641 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0642\u0644\u0628\u0647 \u0639\u0646 \u062f\u064a\u0646\u0647\u061f \u0648\u0645\u0646 \u062e\u0630\u0644\u0647 \u0627\u0644\u0644\u0647 \u0639\u0646 \u062f\u064a\u0646\u0647\u060c \u0648\u0627\u062a\u0628\u0627\u0639 \u0645\u0627 \u0623\u0645\u0631\u0647 \u0628\u0647\u060c \u0641\u0644\u0627 \u0637\u0631\u064a\u0642 \u0644\u0647 \u0625\u0644\u0649 \u0627\u0644\u0647\u062f\u0649.","4:89":"\u062a\u0645\u0646\u0651\u064e\u0649 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0644\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646-\u060c \u0644\u0648 \u062a\u0646\u0643\u0631\u0648\u0646 \u062d\u0642\u064a\u0642\u0629 \u0645\u0627 \u0622\u0645\u0646\u062a \u0628\u0647 \u0642\u0644\u0648\u0628\u0643\u0645\u060c \u0645\u062b\u0644\u0645\u0627 \u0623\u0646\u0643\u0631\u0648\u0647 \u0628\u0642\u0644\u0648\u0628\u0647\u0645\u060c \u0641\u062a\u0643\u0648\u0646\u0648\u0646 \u0645\u0639\u0647\u0645 \u0641\u064a \u0627\u0644\u0625\u0646\u0643\u0627\u0631 \u0633\u0648\u0627\u0621\u060c \u0641\u0644\u0627 \u062a\u062a\u062e\u0630\u0648\u0627 \u0645\u0646\u0647\u0645 \u0623\u0635\u0641\u064a\u0627\u0621 \u0644\u0643\u0645\u060c \u062d\u062a\u0649 \u064a\u0647\u0627\u062c\u0631\u0648\u0627 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647\u060c \u0628\u0631\u0647\u0627\u0646\u064b\u0627 \u0639\u0644\u0649 \u0635\u062f\u0642 \u0625\u064a\u0645\u0627\u0646\u0647\u0645\u060c \u0641\u0625\u0646 \u0623\u0639\u0631\u0636\u0648\u0627 \u0639\u0645\u0627 \u062f\u0639\u0648\u0627 \u0625\u0644\u064a\u0647\u060c \u0641\u062e\u0630\u0648\u0647\u0645 \u0623\u064a\u0646\u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u0648\u0627\u0642\u062a\u0644\u0648\u0647\u0645\u060c \u0648\u0644\u0627 \u062a\u062a\u062e\u0630\u0648\u0627 \u0645\u0646\u0647\u0645 \u0648\u0644\u064a\u0651\u0627\u064b \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647 \u0648\u0644\u0627 \u0646\u0635\u064a\u0631\u064b\u0627 \u062a\u0633\u062a\u0646\u0635\u0631\u0648\u0646\u0647 \u0628\u0647.","4:90":"\u0644\u0643\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u062a\u0635\u0644\u0648\u0646 \u0628\u0642\u0648\u0645 \u0628\u064a\u0646\u0643\u0645 \u0648\u0628\u064a\u0646\u0647\u0645 \u0639\u0647\u062f \u0648\u0645\u064a\u062b\u0627\u0642 \u0641\u0644\u0627 \u062a\u0642\u0627\u062a\u0644\u0648\u0647\u0645\u060c \u0648\u0643\u0630\u0644\u0643 \u0627\u0644\u0630\u064a\u0646 \u0623\u062a\u064e\u0648\u0627 \u0625\u0644\u064a\u0643\u0645 \u0648\u0642\u062f \u0636\u0627\u0642\u062a \u0635\u062f\u0648\u0631\u0647\u0645 \u0648\u0643\u0631\u0647\u0648\u0627 \u0623\u0646 \u064a\u0642\u0627\u062a\u0644\u0648\u0643\u0645\u060c \u0643\u0645\u0627 \u0643\u0631\u0647\u0648\u0627 \u0623\u0646 \u064a\u0642\u0627\u062a\u0644\u0648\u0627 \u0642\u0648\u0645\u0647\u0645\u060c \u0641\u0644\u0645 \u064a\u0643\u0648\u0646\u0648\u0627 \u0645\u0639\u0643\u0645 \u0648\u0644\u0627 \u0645\u0639 \u0642\u0648\u0645\u0647\u0645\u060c \u0641\u0644\u0627 \u062a\u0642\u0627\u062a\u0644\u0648\u0647\u0645\u060c \u0648\u0644\u0648 \u0634\u0627\u0621 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0633\u0644\u0651\u064e\u0637\u0647\u0645 \u0639\u0644\u064a\u0643\u0645\u060c \u0641\u0644\u0642\u0627\u062a\u0644\u0648\u0643\u0645 \u0645\u0639 \u0623\u0639\u062f\u0627\u0626\u0643\u0645 \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646\u060c \u0648\u0644\u0643\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0635\u0631\u0641\u0647\u0645 \u0639\u0646\u0643\u0645 \u0628\u0641\u0636\u0644\u0647 \u0648\u0642\u062f\u0631\u062a\u0647\u060c \u0641\u0625\u0646 \u062a\u0631\u0643\u0648\u0643\u0645 \u0641\u0644\u0645 \u064a\u0642\u0627\u062a\u0644\u0648\u0643\u0645\u060c \u0648\u0627\u0646\u0642\u0627\u062f\u0648\u0627 \u0627\u0644\u064a\u0643\u0645 \u0645\u0633\u062a\u0633\u0644\u0645\u064a\u0646\u060c \u0641\u0644\u064a\u0633 \u0644\u0643\u0645 \u0639\u0644\u064a\u0647\u0645 \u0645\u0646 \u0637\u0631\u064a\u0642 \u0644\u0642\u062a\u0627\u0644\u0647\u0645.","4:91":"\u0633\u062a\u062c\u062f\u0648\u0646 \u0642\u0648\u0645\u064b\u0627 \u0622\u062e\u0631\u064a\u0646 \u0645\u0646 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u064a\u0648\u062f\u0648\u0646 \u0627\u0644\u0627\u0637\u0645\u0626\u0646\u0627\u0646 \u0639\u0644\u0649 \u0623\u0646\u0641\u0633\u0647\u0645 \u0645\u0646 \u062c\u0627\u0646\u0628\u0643\u0645\u060c \u0641\u064a\u0638\u0647\u0631\u0648\u0646 \u0644\u0643\u0645 \u0627\u0644\u0625\u064a\u0645\u0627\u0646\u060c \u0648\u064a\u0648\u062f\u0648\u0646 \u0627\u0644\u0627\u0637\u0645\u0626\u0646\u0627\u0646 \u0639\u0644\u0649 \u0623\u0646\u0641\u0633\u0647\u0645 \u0645\u0646 \u062c\u0627\u0646\u0628 \u0642\u0648\u0645\u0647\u0645 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646\u060c \u0641\u064a\u0638\u0647\u0631\u0648\u0646 \u0644\u0647\u0645 \u0627\u0644\u0643\u0641\u0631\u060c \u0643\u0644\u0645\u0627 \u0623\u0639\u064a\u062f\u0648\u0627 \u0625\u0644\u0649 \u0645\u0648\u0637\u0646 \u0627\u0644\u0643\u0641\u0631 \u0648\u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646\u060c \u0648\u0642\u0639\u0648\u0627 \u0641\u064a \u0623\u0633\u0648\u0623 \u062d\u0627\u0644. \u0641\u0647\u0624\u0644\u0627\u0621 \u0625\u0646 \u0644\u0645 \u064a\u0646\u0635\u0631\u0641\u0648\u0627 \u0639\u0646\u0643\u0645\u060c \u0648\u064a\u0642\u062f\u0645\u0648\u0627 \u0625\u0644\u064a\u0643\u0645 \u0627\u0644\u0627\u0633\u062a\u0633\u0644\u0627\u0645 \u0627\u0644\u062a\u0627\u0645\u060c \u0648\u064a\u0645\u0646\u0639\u0648\u0627 \u0623\u0646\u0641\u0633\u0647\u0645 \u0639\u0646 \u0642\u062a\u0627\u0644\u0643\u0645 \u0641\u062e\u0630\u0648\u0647\u0645 \u0628\u0642\u0648\u0629 \u0648\u0627\u0642\u062a\u0644\u0648\u0647\u0645 \u0623\u064a\u0646\u0645\u0627 \u0643\u0627\u0646\u0648\u0627\u060c \u0648\u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0630\u064a\u0646 \u0628\u0644\u063a\u0648\u0627 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0645\u0633\u0644\u0643 \u0627\u0644\u0633\u064a\u0651\u0650\u0626 \u062d\u062f\u0651\u0627\u064b \u064a\u0645\u064a\u0632\u0647\u0645 \u0639\u0645\u0651\u064e\u0646 \u0639\u062f\u0627\u0647\u0645\u060c \u0641\u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u062c\u0639\u0644\u0646\u0627 \u0644\u0643\u0645 \u0627\u0644\u062d\u062c\u0629 \u0627\u0644\u0628\u064a\u0646\u0629 \u0639\u0644\u0649 \u0642\u062a\u0644\u0647\u0645 \u0648\u0623\u0633\u0631\u0647\u0645.","4:92":"\u0648\u0644\u0627 \u064a\u062d\u0642 \u0644\u0645\u0624\u0645\u0646 \u0627\u0644\u0627\u0639\u062a\u062f\u0627\u0621 \u0639\u0644\u0649 \u0623\u062e\u064a\u0647 \u0627\u0644\u0645\u0624\u0645\u0646 \u0648\u0642\u062a\u0644\u0647 \u0628\u063a\u064a\u0631 \u062d\u0642\u060c \u0625\u0644\u0627 \u0623\u0646 \u064a\u0642\u0639 \u0645\u0646\u0647 \u0630\u0644\u0643 \u0639\u0644\u0649 \u0648\u062c\u0647 \u0627\u0644\u062e\u0637\u0623 \u0627\u0644\u0630\u064a \u0644\u0627 \u0639\u0645\u062f \u0641\u064a\u0647\u060c \u0648\u0645\u0646 \u0648\u0642\u0639 \u0645\u0646\u0647 \u0630\u0644\u0643 \u0627\u0644\u062e\u0637\u0623 \u0641\u0639\u0644\u064a\u0647 \u0639\u062a\u0642 \u0631\u0642\u0628\u0629 \u0645\u0624\u0645\u0646\u0629\u060c \u0648\u062a\u0633\u0644\u064a\u0645 \u062f\u064a\u0629 \u0645\u0642\u062f\u0631\u0629 \u0625\u0644\u0649 \u0623\u0648\u0644\u064a\u0627\u0626\u0647\u060c \u0625\u0644\u0627 \u0623\u0646 \u064a\u062a\u0635\u062f\u0642\u0648\u0627 \u0628\u0647\u0627 \u0639\u0644\u064a\u0647 \u0648\u064a\u0639\u0641\u0648\u0627 \u0639\u0646\u0647. \u0641\u0625\u0646 \u0643\u0627\u0646 \u0627\u0644\u0645\u0642\u062a\u0648\u0644 \u0645\u0646 \u0642\u0648\u0645 \u0643\u0641\u0627\u0631 \u0623\u0639\u062f\u0627\u0621 \u0644\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0648\u0647\u0648 \u0645\u0624\u0645\u0646 \u0628\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0628\u0645\u0627 \u0623\u0646\u0632\u0644 \u0645\u0646 \u0627\u0644\u062d\u0642 \u0639\u0644\u0649 \u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0641\u0639\u0644\u0649 \u0642\u0627\u062a\u0644\u0647 \u0639\u062a\u0642 \u0631\u0642\u0628\u0629 \u0645\u0624\u0645\u0646\u0629\u060c \u0648\u0625\u0646 \u0643\u0627\u0646 \u0645\u0646 \u0642\u0648\u0645 \u0628\u064a\u0646\u0643\u0645 \u0648\u0628\u064a\u0646\u0647\u0645 \u0639\u0647\u062f \u0648\u0645\u064a\u062b\u0627\u0642\u060c \u0641\u0639\u0644\u0649 \u0642\u0627\u062a\u0644\u0647 \u062f\u064a\u0629 \u062a\u0633\u0644\u0645 \u0625\u0644\u0649 \u0623\u0648\u0644\u064a\u0627\u0626\u0647 \u0648\u0639\u062a\u0642 \u0631\u0642\u0628\u0629 \u0645\u0624\u0645\u0646\u0629\u060c \u0641\u0645\u0646 \u0644\u0645 \u064a\u062c\u062f \u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u0639\u062a\u0642 \u0631\u0642\u0628\u0629 \u0645\u0624\u0645\u0646\u0629\u060c \u0641\u0639\u0644\u064a\u0647 \u0635\u064a\u0627\u0645 \u0634\u0647\u0631\u064a\u0646 \u0645\u062a\u062a\u0627\u0628\u0639\u064a\u0646; \u0644\u064a\u062a\u0648\u0628 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0644\u064a\u0647. \u0648\u0643\u0627\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0644\u064a\u0645\u0627 \u0628\u062d\u0642\u064a\u0642\u0629 \u0634\u0623\u0646 \u0639\u0628\u0627\u062f\u0647\u060c \u062d\u0643\u064a\u0645\u064b\u0627 \u0641\u064a\u0645\u0627 \u0634\u0631\u0639\u0647 \u0644\u0647\u0645.","4:93":"\u0648\u0645\u0646 \u064a\u064e\u0639\u0652\u062a\u064e\u062f\u0650 \u0639\u0644\u0649 \u0645\u0624\u0645\u0646 \u0641\u064a\u0642\u062a\u0644\u0647 \u0639\u0646 \u0639\u0645\u062f \u0628\u063a\u064a\u0631 \u062d\u0642 \u0641\u0639\u0627\u0642\u0628\u062a\u0647 \u062c\u0647\u0646\u0645\u060c \u062e\u0627\u0644\u062f\u064b\u0627 \u0641\u064a\u0647\u0627 \u0645\u0639 \u0633\u062e\u0637 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0644\u064a\u0647 \u0648\u0637\u064e\u0631\u0652\u062f\u0650\u0647\u0650 \u0645\u0646 \u0631\u062d\u0645\u062a\u0647\u060c \u0625\u0646 \u062c\u0627\u0632\u0627\u0647 \u0639\u0644\u0649 \u0630\u0646\u0628\u0647 \u0648\u0623\u0639\u062f\u0651\u064e \u0627\u0644\u0644\u0647 \u0644\u0647 \u0623\u0634\u062f \u0627\u0644\u0639\u0630\u0627\u0628 \u0628\u0633\u0628\u0628 \u0645\u0627 \u0627\u0631\u062a\u0643\u0628\u0647 \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u062c\u0646\u0627\u064a\u0629 \u0627\u0644\u0639\u0638\u064a\u0645\u0629. \u0648\u0644\u0643\u0646\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u064a\u0639\u0641\u0648 \u0648\u064a\u062a\u0641\u0636\u0644 \u0639\u0644\u0649 \u0623\u0647\u0644 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0641\u0644\u0627 \u064a\u062c\u0627\u0632\u064a\u0647\u0645 \u0628\u0627\u0644\u062e\u0644\u0648\u062f \u0641\u064a \u062c\u0647\u0646\u0645.","4:94":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647 \u0625\u0630\u0627 \u062e\u0631\u062c\u062a\u0645 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0645\u062c\u0627\u0647\u062f\u064a\u0646 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0641\u0643\u0648\u0646\u0648\u0627 \u0639\u0644\u0649 \u0628\u064a\u0646\u0629 \u0645\u0645\u0627 \u062a\u0623\u062a\u0648\u0646 \u0648\u062a\u062a\u0631\u0643\u0648\u0646\u060c \u0648\u0644\u0627 \u062a\u0646\u0641\u0648\u0627 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0639\u0645\u0646 \u0628\u062f\u0627 \u0645\u0646\u0647 \u0634\u064a\u0621 \u0645\u0646 \u0639\u0644\u0627\u0645\u0627\u062a \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u0644\u0645 \u064a\u0642\u0627\u062a\u0644\u0643\u0645; \u0644\u0627\u062d\u062a\u0645\u0627\u0644 \u0623\u0646 \u064a\u0643\u0648\u0646 \u0645\u0624\u0645\u0646\u064b\u0627 \u064a\u062e\u0641\u064a \u0625\u064a\u0645\u0627\u0646\u0647\u060c \u0637\u0627\u0644\u0628\u064a\u0646 \u0628\u0630\u0644\u0643 \u0645\u062a\u0627\u0639 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0646\u062f\u0647 \u0645\u0646 \u0627\u0644\u0641\u0636\u0644 \u0648\u0627\u0644\u0639\u0637\u0627\u0621 \u0645\u0627 \u064a\u063a\u0646\u064a\u0643\u0645 \u0628\u0647\u060c \u0643\u0630\u0644\u0643 \u0643\u0646\u062a\u0645 \u0641\u064a \u0628\u062f\u0621 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u062a\u062e\u0641\u0648\u0646 \u0625\u064a\u0645\u0627\u0646\u0643\u0645 \u0639\u0646 \u0642\u0648\u0645\u0643\u0645 \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0641\u0645\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645\u060c \u0648\u0623\u0639\u0632\u0651\u064e\u0643\u0645 \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0627\u0644\u0642\u0648\u0629\u060c \u0641\u0643\u0648\u0646\u0648\u0627 \u0639\u0644\u0649 \u0628\u064a\u0651\u0650\u0646\u0629 \u0648\u0645\u0639\u0631\u0641\u0629 \u0641\u064a \u0623\u0645\u0648\u0631\u0643\u0645. \u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0644\u064a\u0645 \u0628\u0643\u0644 \u0623\u0639\u0645\u0627\u0644\u0643\u0645\u060c \u0645\u0637\u0651\u064e\u0644\u0639 \u0639\u0644\u0649 \u062f\u0642\u0627\u0626\u0642 \u0623\u0645\u0648\u0631\u0643\u0645\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a\u0643\u0645 \u0639\u0644\u064a\u0647\u0627.","4:95":"\u0644\u0627 \u064a\u062a\u0633\u0627\u0648\u0649 \u0627\u0644\u0645\u062a\u062e\u0644\u0641\u0648\u0646 \u0639\u0646 \u0627\u0644\u062c\u0647\u0627\u062f \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 -\u063a\u064a\u0631 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0623\u0639\u0630\u0627\u0631 \u0645\u0646\u0647\u0645- \u0648\u0627\u0644\u0645\u062c\u0627\u0647\u062f\u0648\u0646 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647\u060c \u0628\u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0648\u0623\u0646\u0641\u0633\u0647\u0645\u060c \u0641\u0636\u0651\u064e\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0627\u0644\u0645\u062c\u0627\u0647\u062f\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0642\u0627\u0639\u062f\u064a\u0646\u060c \u0648\u0631\u0641\u0639 \u0645\u0646\u0632\u0644\u062a\u0647\u0645 \u062f\u0631\u062c\u0629 \u0639\u0627\u0644\u064a\u0629 \u0641\u064a \u0627\u0644\u062c\u0646\u0629\u060c \u0648\u0642\u062f \u0648\u0639\u062f \u0627\u0644\u0644\u0647 \u0643\u0644\u0627 \u0645\u0646 \u0627\u0644\u0645\u062c\u0627\u0647\u062f\u064a\u0646 \u0628\u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0648\u0623\u0646\u0641\u0633\u0647\u0645 \u0648\u0627\u0644\u0642\u0627\u0639\u062f\u064a\u0646 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0623\u0639\u0630\u0627\u0631 \u0627\u0644\u062c\u0646\u0629 \u0644\u0650\u0645\u0627 \u0628\u0630\u0644\u0648\u0627 \u0648\u0636\u062d\u0651\u064e\u0648\u0627 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u062d\u0642\u060c \u0648\u0641\u0636\u0651\u064e\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0627\u0644\u0645\u062c\u0627\u0647\u062f\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0642\u0627\u0639\u062f\u064a\u0646 \u062b\u0648\u0627\u0628\u064b\u0627 \u062c\u0632\u064a\u0644\u0627.","4:96":"\u0647\u0630\u0627 \u0627\u0644\u062b\u0648\u0627\u0628 \u0627\u0644\u062c\u0632\u064a\u0644 \u0645\u0646\u0627\u0632\u0644 \u0639\u0627\u0644\u064a\u0629 \u0641\u064a \u0627\u0644\u062c\u0646\u0627\u062a \u0645\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u062e\u0627\u0635\u0629 \u0639\u0628\u0627\u062f\u0647 \u0627\u0644\u0645\u062c\u0627\u0647\u062f\u064a\u0646 \u0641\u064a \u0633\u0628\u064a\u0644\u0647\u060c \u0648\u0645\u063a\u0641\u0631\u0629 \u0644\u0630\u0646\u0648\u0628\u0647\u0645 \u0648\u0631\u062d\u0645\u0629 \u0648\u0627\u0633\u0639\u0629 \u064a\u0646\u0639\u0645\u0648\u0646 \u0641\u064a\u0647\u0627. \u0648\u0643\u0627\u0646 \u0627\u0644\u0644\u0647 \u063a\u0641\u0648\u0631\u064b\u0627 \u0644\u0645\u0646 \u062a\u0627\u0628 \u0625\u0644\u064a\u0647 \u0648\u0623\u0646\u0627\u0628\u060c \u0631\u062d\u064a\u0645\u064b\u0627 \u0628\u0623\u0647\u0644 \u0637\u0627\u0639\u062a\u0647\u060c \u0627\u0644\u0645\u062c\u0627\u0647\u062f\u064a\u0646 \u0641\u064a \u0633\u0628\u064a\u0644\u0647.","4:97":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u062a\u0648\u0641\u0651\u064e\u0627\u0647\u0645 \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u0648\u0642\u062f \u0638\u0644\u0645\u0648\u0627 \u0623\u0646\u0641\u0633\u0647\u0645 \u0628\u0642\u0639\u0648\u062f\u0647\u0645 \u0641\u064a \u062f\u0627\u0631 \u0627\u0644\u0643\u0641\u0631 \u0648\u062a\u0631\u0643 \u0627\u0644\u0647\u062c\u0631\u0629\u060c \u062a\u0642\u0648\u0644 \u0644\u0647\u0645 \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u062a\u0648\u0628\u064a\u062e\u064b\u0627 \u0644\u0647\u0645: \u0641\u064a \u0623\u064a \u0634\u064a\u0621 \u0643\u0646\u062a\u0645 \u0645\u0646 \u0623\u0645\u0631 \u062f\u064a\u0646\u0643\u0645\u061f \u0641\u064a\u0642\u0648\u0644\u0648\u0646: \u0643\u0646\u0627 \u0636\u0639\u0641\u0627\u0621 \u0641\u064a \u0623\u0631\u0636\u0646\u0627\u060c \u0639\u0627\u062c\u0632\u064a\u0646 \u0639\u0646 \u062f\u0641\u0639 \u0627\u0644\u0638\u0644\u0645 \u0648\u0627\u0644\u0642\u0647\u0631 \u0639\u0646\u0627\u060c \u0641\u064a\u0642\u0648\u0644\u0648\u0646 \u0644\u0647\u0645 \u062a\u0648\u0628\u064a\u062e\u0627: \u0623\u0644\u0645 \u062a\u0643\u0646 \u0623\u0631\u0636 \u0627\u0644\u0644\u0647 \u0648\u0627\u0633\u0639\u0629 \u0641\u062a\u062e\u0631\u062c\u0648\u0627 \u0645\u0646 \u0623\u0631\u0636\u0643\u0645 \u0625\u0644\u0649 \u0623\u0631\u0636 \u0623\u062e\u0631\u0649 \u0628\u062d\u064a\u062b \u062a\u0623\u0645\u0646\u0648\u0646 \u0639\u0644\u0649 \u062f\u064a\u0646\u0643\u0645\u061f \u0641\u0623\u0648\u0644\u0626\u0643 \u0645\u062b\u0648\u0627\u0647\u0645 \u0627\u0644\u0646\u0627\u0631\u060c \u0648\u0642\u0628\u062d \u0647\u0630\u0627 \u0627\u0644\u0645\u0631\u062c\u0639 \u0648\u0627\u0644\u0645\u0622\u0628.","4:98":"\u0648\u064a\u0639\u0630\u0631 \u0645\u0646 \u0630\u0627\u0643 \u0627\u0644\u0645\u0635\u064a\u0631 \u0627\u0644\u0639\u062c\u0632\u0629 \u0645\u0646 \u0627\u0644\u0631\u062c\u0627\u0644 \u0648\u0627\u0644\u0646\u0633\u0627\u0621 \u0648\u0627\u0644\u0635\u063a\u0627\u0631 \u0627\u0644\u0630\u064a\u0646 \u0644\u0627 \u064a\u0642\u062f\u0631\u0648\u0646 \u0639\u0644\u0649 \u062f\u0641\u0639 \u0627\u0644\u0642\u0647\u0631 \u0648\u0627\u0644\u0638\u0644\u0645 \u0639\u0646\u0647\u0645\u060c \u0648\u0644\u0627 \u064a\u0639\u0631\u0641\u0648\u0646 \u0637\u0631\u064a\u0642\u064b\u0627 \u064a\u062e\u0644\u0635\u0647\u0645 \u0645\u0645\u0627 \u0647\u0645 \u0641\u064a\u0647 \u0645\u0646 \u0627\u0644\u0645\u0639\u0627\u0646\u0627\u0629.","4:99":"\u0641\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0636\u0639\u0641\u0627\u0621 \u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u064a\u064f\u0631\u062c\u0649 \u0644\u0647\u0645 \u0645\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0627\u0644\u0639\u0641\u0648; \u0644\u0639\u0644\u0645\u0647 \u062a\u0639\u0627\u0644\u0649 \u0628\u062d\u0642\u064a\u0642\u0629 \u0623\u0645\u0631\u0647\u0645. \u0648\u0643\u0627\u0646 \u0627\u0644\u0644\u0647 \u0643\u062b\u064a\u0631 \u0627\u0644\u0639\u0641\u0648 \u064a\u062a\u062c\u0627\u0648\u0632 \u0639\u0646 \u0633\u064a\u0626\u0627\u062a\u0647\u0645\u060c \u0648\u064a\u0633\u062a\u0631\u0647\u0627 \u0639\u0644\u064a\u0647\u0645.","4:100":"\u0648\u0645\u064e\u0646 \u064a\u062e\u0631\u062c \u0645\u0646 \u0623\u0631\u0636 \u0627\u0644\u0634\u0631\u0643 \u0625\u0644\u0649 \u0623\u0631\u0636 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0641\u0631\u0627\u0631\u064b\u0627 \u0628\u062f\u064a\u0646\u0647\u060c \u0631\u0627\u062c\u064a\u064b\u0627 \u0641\u0636\u0644 \u0631\u0628\u0647\u060c \u0642\u0627\u0635\u062f\u064b\u0627 \u0646\u0635\u0631\u0629 \u062f\u064a\u0646\u0647\u060c \u064a\u062c\u062f \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0645\u0643\u0627\u0646\u064b\u0627 \u0648\u0645\u062a\u062d\u0648\u0644\u0627 \u064a\u0646\u0639\u0645 \u0641\u064a\u0647 \u0628\u0645\u0627 \u064a\u0643\u0648\u0646 \u0633\u0628\u0628\u064b\u0627 \u0641\u064a \u0642\u0648\u062a\u0647 \u0648\u0630\u0644\u0629 \u0623\u0639\u062f\u0627\u0626\u0647\u060c \u0645\u0639 \u0627\u0644\u0633\u0639\u0629 \u0641\u064a \u0631\u0632\u0642\u0647 \u0648\u0639\u064a\u0634\u0647\u060c \u0648\u0645\u0646 \u064a\u062e\u0631\u062c \u0645\u0646 \u0628\u064a\u062a\u0647 \u0642\u0627\u0635\u062f\u064b\u0627 \u0646\u0635\u0631\u0629 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0625\u0639\u0644\u0627\u0621 \u0643\u0644\u0645\u0629 \u0627\u0644\u0644\u0647\u060c \u062b\u0645 \u064a\u062f\u0631\u0643\u0647 \u0627\u0644\u0645\u0648\u062a \u0642\u0628\u0644 \u0628\u0644\u0648\u063a\u0647 \u0645\u0642\u0635\u062f\u0647\u060c \u0641\u0642\u062f \u062b\u0628\u062a \u0644\u0647 \u062c\u0632\u0627\u0621 \u0639\u0645\u0644\u0647 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0641\u0636\u0644\u0627 \u0645\u0646\u0647 \u0648\u0625\u062d\u0633\u0627\u0646\u064b\u0627. \u0648\u0643\u0627\u0646 \u0627\u0644\u0644\u0647 \u063a\u0641\u0648\u0631\u064b\u0627 \u0631\u062d\u064a\u0645\u064b\u0627 \u0628\u0639\u0628\u0627\u062f\u0647.","4:101":"\u0648\u0625\u0630\u0627 \u0633\u0627\u0641\u0631\u062a\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0641\u064a \u0623\u0631\u0636 \u0627\u0644\u0644\u0647\u060c \u0641\u0644\u0627 \u062d\u0631\u062c \u0648\u0644\u0627 \u0625\u062b\u0645 \u0639\u0644\u064a\u0643\u0645 \u0641\u064a \u0642\u0635\u0631 \u0627\u0644\u0635\u0644\u0627\u0629 \u0625\u0646 \u062e\u0641\u062a\u0645 \u0645\u0646 \u0639\u062f\u0648\u0627\u0646 \u0627\u0644\u0643\u0641\u0627\u0631 \u0639\u0644\u064a\u0643\u0645 \u0641\u064a \u062d\u0627\u0644 \u0635\u0644\u0627\u062a\u0643\u0645\u060c \u0648\u0643\u0627\u0646\u062a \u063a\u0627\u0644\u0628 \u0623\u0633\u0641\u0627\u0631 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0641\u064a \u0628\u062f\u0621 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0645\u062e\u0648\u0641\u0629\u060c \u0648\u0627\u0644\u0642\u0635\u0631 \u0631\u062e\u0635\u0629 \u0641\u064a \u0627\u0644\u0633\u0641\u0631 \u062d\u0627\u0644 \u0627\u0644\u0623\u0645\u0646 \u0623\u0648 \u0627\u0644\u062e\u0648\u0641. \u0625\u0646 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0645\u062c\u0627\u0647\u0631\u0648\u0646 \u0644\u0643\u0645 \u0628\u0639\u062f\u0627\u0648\u062a\u0647\u0645\u060c \u0641\u0627\u062d\u0630\u0631\u0648\u0647\u0645.","4:102":"\u0648\u0625\u0630\u0627 \u0643\u0646\u062a -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0641\u064a \u0633\u0627\u062d\u0629 \u0627\u0644\u0642\u062a\u0627\u0644\u060c \u0641\u0623\u0631\u062f\u062a \u0623\u0646 \u062a\u0635\u0644\u064a \u0628\u0647\u0645\u060c \u0641\u0644\u062a\u0642\u0645 \u062c\u0645\u0627\u0639\u0629 \u0645\u0646\u0647\u0645 \u0645\u0639\u0643 \u0644\u0644\u0635\u0644\u0627\u0629\u060c \u0648\u0644\u064a\u0623\u062e\u0630\u0648\u0627 \u0633\u0644\u0627\u062d\u0647\u0645\u060c \u0641\u0625\u0630\u0627 \u0633\u062c\u062f \u0647\u0624\u0644\u0627\u0621 \u0641\u0644\u062a\u0643\u0646 \u0627\u0644\u062c\u0645\u0627\u0639\u0629 \u0627\u0644\u0623\u062e\u0631\u0649 \u0645\u0646 \u062e\u0644\u0641\u0643\u0645 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0639\u062f\u0648\u0643\u0645\u060c \u0648\u062a\u062a\u0645 \u0627\u0644\u062c\u0645\u0627\u0639\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0631\u0643\u0639\u062a\u0647\u0645 \u0627\u0644\u062b\u0627\u0646\u064a\u0629 \u0648\u064a\u064f\u0633\u0644\u0651\u0650\u0645\u0648\u0646\u060c \u062b\u0645 \u062a\u0623\u062a\u064a \u0627\u0644\u062c\u0645\u0627\u0639\u0629 \u0627\u0644\u0623\u062e\u0631\u0649 \u0627\u0644\u062a\u064a \u0644\u0645 \u062a\u0628\u062f\u0623 \u0627\u0644\u0635\u0644\u0627\u0629 \u0641\u0644\u064a\u0623\u062a\u0645\u0648\u0627 \u0628\u0643 \u0641\u064a \u0631\u0643\u0639\u062a\u0647\u0645 \u0627\u0644\u0623\u0648\u0644\u0649\u060c \u062b\u0645 \u064a\u0643\u0645\u0644\u0648\u0627 \u0628\u0623\u0646\u0641\u0633\u0647\u0645 \u0631\u0643\u0639\u062a\u0647\u0645 \u0627\u0644\u062b\u0627\u0646\u064a\u0629\u060c \u0648\u0644\u064a\u062d\u0630\u0631\u0648\u0627 \u0645\u0650\u0646 \u0639\u062f\u0648\u0647\u0645 \u0648\u0644\u064a\u0623\u062e\u0630\u0648\u0627 \u0623\u0633\u0644\u062d\u062a\u0647\u0645. \u0648\u062f\u0651\u064e \u0627\u0644\u062c\u0627\u062d\u062f\u0648\u0646 \u0644\u062f\u064a\u0646 \u0627\u0644\u0644\u0647 \u0623\u0646 \u062a\u063a\u0641\u064f\u0644\u0648\u0627 \u0639\u0646 \u0633\u0644\u0627\u062d\u0643\u0645 \u0648\u0632\u0627\u062f\u0643\u0645; \u0644\u064a\u062d\u0645\u0644\u0648\u0627 \u0639\u0644\u064a\u0643\u0645 \u062d\u0645\u0644\u0629 \u0648\u0627\u062d\u0644\u0629 \u0641\u064a\u0642\u0636\u0648\u0627 \u0639\u0644\u064a\u0643\u0645\u060c \u0648\u0644\u0627 \u0625\u062b\u0645 \u0639\u0644\u064a\u0643\u0645 \u062d\u064a\u0646\u0626\u0630 \u0625\u0646 \u0643\u0627\u0646 \u0628\u0643\u0645 \u0623\u0630\u0649 \u0645\u0646 \u0645\u0637\u0631\u060c \u0623\u0648 \u0643\u0646\u062a\u0645 \u0641\u064a \u062d\u0627\u0644 \u0645\u0631\u0636\u060c \u0623\u0646 \u062a\u062a\u0631\u0643\u0648\u0627 \u0623\u0633\u0644\u062d\u062a\u0643\u0645\u060c \u0645\u0639 \u0623\u062e\u0630 \u0627\u0644\u062d\u0630\u0631. \u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0623\u0639\u062f\u0651\u064e \u0644\u0644\u062c\u0627\u062d\u062f\u064a\u0646 \u0644\u062f\u064a\u0646\u0647 \u0639\u0630\u0627\u0628\u064b\u0627 \u064a\u0647\u064a\u0646\u0647\u0645\u060c \u0648\u064a\u062e\u0632\u064a\u0647\u0645.","4:103":"\u0641\u0625\u0630\u0627 \u0623\u062f\u0651\u064e\u064a\u062a\u0645 \u0627\u0644\u0635\u0644\u0627\u0629\u060c \u0641\u0623\u062f\u064a\u0645\u0648\u0627 \u0630\u0643\u0631 \u0627\u0644\u0644\u0647 \u0641\u064a \u062c\u0645\u064a\u0639 \u0623\u062d\u0648\u0627\u0644\u0643\u0645\u060c \u0641\u0625\u0630\u0627 \u0632\u0627\u0644 \u0627\u0644\u062e\u0648\u0641 \u0641\u0623\u062f\u0651\u064f\u0648\u0627 \u0627\u0644\u0635\u0644\u0627\u0629 \u0643\u0627\u0645\u0644\u0629\u060c \u0648\u0644\u0627 \u062a\u0641\u0631\u0651\u0650\u0637\u0648\u0627 \u0641\u064a\u0647\u0627 \u0641\u0625\u0646\u0647\u0627 \u0648\u0627\u062c\u0628\u0629 \u0641\u064a \u0623\u0648\u0642\u0627\u062a \u0645\u0639\u0644\u0648\u0645\u0629 \u0641\u064a \u0627\u0644\u0634\u0631\u0639.","4:104":"\u0648\u0644\u0627 \u062a\u0636\u0639\u0641\u0648\u0627 \u0641\u064a \u0637\u0644\u0628 \u0639\u062f\u0648\u0643\u0645 \u0648\u0642\u062a\u0627\u0644\u0647\u060c \u0625\u0646 \u062a\u0643\u0648\u0646\u0648\u0627 \u062a\u062a\u0623\u0644\u0645\u0648\u0646 \u0645\u0646 \u0627\u0644\u0642\u062a\u0627\u0644 \u0648\u0622\u062b\u0627\u0631\u0647\u060c \u0641\u0623\u0639\u062f\u0627\u0624\u0643\u0645 \u0643\u0630\u0644\u0643 \u064a\u062a\u0623\u0644\u0645\u0648\u0646 \u0645\u0646\u0647 \u0623\u0634\u062f \u0627\u0644\u0623\u0644\u0645\u060c \u0648\u0645\u0639 \u0630\u0644\u0643 \u0644\u0627 \u064a\u0643\u0641\u0648\u0646 \u0639\u0646 \u0642\u062a\u0627\u0644\u0643\u0645\u060c \u0641\u0623\u0646\u062a\u0645 \u0623\u0648\u0644\u0649 \u0628\u0630\u0644\u0643 \u0645\u0646\u0647\u0645\u060c \u0644\u0645\u0627 \u062a\u0631\u062c\u0648\u0646\u0647 \u0645\u0646 \u0627\u0644\u062b\u0648\u0627\u0628 \u0648\u0627\u0644\u0646\u0635\u0631 \u0648\u0627\u0644\u062a\u0623\u064a\u064a\u062f\u060c \u0648\u0647\u0645 \u0644\u0627 \u064a\u0631\u062c\u0648\u0646 \u0630\u0644\u0643. \u0648\u0643\u0627\u0646 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0645\u064b\u0627 \u0628\u0643\u0644 \u0623\u062d\u0648\u0627\u0644\u0643\u0645\u060c \u062d\u0643\u064a\u0645\u064b\u0627 \u0641\u064a \u0623\u0645\u0631\u0647 \u0648\u062a\u062f\u0628\u064a\u0631\u0647.","4:105":"\u0625\u0646\u0627 \u0623\u0646\u0632\u0644\u0646\u0627 \u0625\u0644\u064a\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0627\u0644\u0642\u0631\u0622\u0646 \u0645\u0634\u062a\u0645\u0644\u0627 \u0639\u0644\u0649 \u0627\u0644\u062d\u0642; \u0644\u062a\u0641\u0635\u0644 \u0628\u064a\u0646 \u0627\u0644\u0646\u0627\u0633 \u062c\u0645\u064a\u0639\u064b\u0627 \u0628\u0645\u0627 \u0623\u0648\u062d\u0649 \u0627\u0644\u0644\u0647 \u0625\u0644\u064a\u0643\u060c \u0648\u0628\u064e\u0635\u0651\u064e\u0631\u0643 \u0628\u0647\u060c \u0641\u0644\u0627 \u062a\u0643\u0646 \u0644\u0644\u0630\u064a\u0646 \u064a\u062e\u0648\u0646\u0648\u0646 \u0623\u0646\u0641\u0633\u0647\u0645 -\u0628\u0643\u062a\u0645\u0627\u0646 \u0627\u0644\u062d\u0642- \u0645\u062f\u0627\u0641\u0639\u064b\u0627 \u0639\u0646\u0647\u0645 \u0628\u0645\u0627 \u0623\u064a\u062f\u0648\u0647 \u0644\u0643 \u0645\u0646 \u0627\u0644\u0642\u0648\u0644 \u0627\u0644\u0645\u062e\u0627\u0644\u0641 \u0644\u0644\u062d\u0642\u064a\u0642\u0629.","4:106":"\u0648\u0627\u0637\u0644\u0628 \u0645\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0627\u0644\u0645\u063a\u0641\u0631\u0629 \u0641\u064a \u062c\u0645\u064a\u0639 \u0623\u062d\u0648\u0627\u0644\u0643\u060c \u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0643\u0627\u0646 \u063a\u0641\u0648\u0631\u064b\u0627 \u0644\u0645\u0646 \u064a\u0631\u062c\u0648 \u0641\u0636\u0644\u0647 \u0648\u0646\u0648\u0627\u0644 \u0645\u063a\u0641\u0631\u062a\u0647\u060c \u0631\u062d\u064a\u0645\u064b\u0627 \u0628\u0647.","4:107":"\u0648\u0644\u0627 \u062a\u062f\u0627\u0641\u0639 \u0639\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u062e\u0648\u0646\u0648\u0646 \u0623\u0646\u0641\u0633\u0647\u0645 \u0628\u0645\u0639\u0635\u064a\u0629 \u0627\u0644\u0644\u0647. \u0625\u0646 \u0627\u0644\u0644\u0647 -\u0633\u0628\u062d\u0627\u0646\u0647- \u0644\u0627 \u064a\u062d\u0628 \u0645\u064e\u0646 \u0639\u064e\u0638\u064f\u0645\u064e\u062a\u0652 \u062e\u064a\u0627\u0646\u062a\u0647\u060c \u0648\u0643\u062b\u0631 \u0630\u0646\u0628\u0647.","4:108":"\u064a\u0633\u062a\u062a\u0631\u0648\u0646 \u0645\u0646 \u0627\u0644\u0646\u0627\u0633 \u062e\u0648\u0641\u064b\u0627 \u0645\u0646 \u0627\u0637\u0644\u0627\u0639\u0647\u0645 \u0639\u0644\u0649 \u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0627\u0644\u0633\u064a\u0626\u0629\u060c \u0648\u0644\u0627 \u064a\u0633\u062a\u062a\u0631\u0648\u0646 \u0645\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0644\u0627 \u064a\u0633\u062a\u062d\u064a\u0648\u0646 \u0645\u0646\u0647\u060c \u0648\u0647\u0648 \u0639\u0632\u0651\u064e \u0634\u0623\u0646\u0647 \u0645\u0639\u0647\u0645 \u0628\u0639\u0644\u0645\u0647\u060c \u0645\u0637\u0644\u0639 \u0639\u0644\u064a\u0647\u0645 \u062d\u064a\u0646 \u064a\u062f\u0628\u0651\u0650\u0631\u0648\u0646 -\u0644\u064a\u0644\u0627- \u0645\u0627 \u0644\u0627 \u064a\u0631\u0636\u0649 \u0645\u0646 \u0627\u0644\u0642\u0648\u0644\u060c \u0648\u0643\u0627\u0646 \u0627\u0644\u0644\u0647 -\u062a\u0639\u0627\u0644\u0649- \u0645\u062d\u064a\u0637\u064b\u0627 \u0628\u062c\u0645\u064a\u0639 \u0623\u0642\u0648\u0627\u0644\u0647\u0645 \u0648\u0623\u0641\u0639\u0627\u0644\u0647\u0645\u060c \u0644\u0627 \u064a\u062e\u0641\u0649 \u0639\u0644\u064a\u0647 \u0645\u0646\u0647\u0627 \u0634\u064a\u0621.","4:109":"\u0647\u0627 \u0623\u0646\u062a\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0642\u062f \u062d\u0627\u062c\u062c\u062a\u0645 \u0639\u0646 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u062e\u0627\u0626\u0646\u064a\u0646 \u0644\u0623\u0646\u0641\u0633\u0647\u0645 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0641\u0645\u0646 \u064a\u062d\u0627\u062c\u062c \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0646\u0647\u0645 \u064a\u0648\u0645 \u0627\u0644\u0628\u0639\u062b \u0648\u0627\u0644\u062d\u0633\u0627\u0628\u061f \u0648\u0645\u0646 \u0630\u0627 \u0627\u0644\u0630\u064a \u064a\u0643\u0648\u0646 \u0639\u0644\u0649 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u062e\u0627\u0626\u0646\u064a\u0646 \u0648\u0643\u064a\u0644\u0627 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u061f","4:110":"\u0648\u0645\u0646 \u064a\u064f\u0642\u0652\u062f\u0650\u0645\u0652 \u0639\u0644\u0649 \u0639\u0645\u0644 \u0633\u064a\u0651\u0650\u0626 \u0642\u0628\u064a\u062d\u060c \u0623\u0648 \u064a\u0638\u0644\u0645 \u0646\u0641\u0633\u0647 \u0628\u0627\u0631\u062a\u0643\u0627\u0628 \u0645\u0627 \u064a\u062e\u0627\u0644\u0641 \u062d\u0643\u0645 \u0627\u0644\u0644\u0647 \u0648\u0634\u0631\u0639\u0647\u060c \u062b\u0645 \u064a\u0631\u062c\u0639 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0646\u0627\u062f\u0645\u064b\u0627 \u0639\u0644\u0649 \u0645\u0627 \u0639\u0645\u0644\u060c \u0631\u0627\u062c\u064a\u064b\u0627 \u0645\u063a\u0641\u0631\u062a\u0647 \u0648\u0633\u062a\u0631 \u0630\u0646\u0628\u0647\u060c \u064a\u062c\u062f \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u063a\u0641\u0648\u0631\u064b\u0627 \u0644\u0647\u060c \u0631\u062d\u064a\u0645\u064b\u0627 \u0628\u0647.","4:111":"\u0648\u0645\u0646 \u064a\u0639\u0645\u062f \u0625\u0644\u0649 \u0627\u0631\u062a\u0643\u0627\u0628 \u0630\u0646\u0628 \u0641\u0625\u0646\u0645\u0627 \u064a\u0636\u0631 \u0628\u0630\u0644\u0643 \u0646\u0641\u0633\u0647 \u0648\u062d\u062f\u0647\u0627\u060c \u0648\u0643\u0627\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0644\u064a\u0645\u064b\u0627 \u0628\u062d\u0642\u064a\u0642\u0629 \u0623\u0645\u0631 \u0639\u0628\u0627\u062f\u0647\u060c \u062d\u0643\u064a\u0645\u064b\u0627 \u0641\u064a\u0645\u0627 \u064a\u0642\u0636\u064a \u0628\u0647 \u0628\u064a\u0646 \u062e\u0644\u0642\u0647.","4:112":"\u0648\u0645\u0646 \u064a\u0639\u0645\u0644 \u062e\u0637\u064a\u0626\u0629 \u0628\u063a\u064a\u0631 \u0639\u0645\u062f\u060c \u0623\u0648 \u064a\u0631\u062a\u0643\u0628 \u0630\u0646\u0628\u064b\u0627 \u0645\u062a\u0639\u0645\u062f\u064b\u0627 \u062b\u0645 \u064a\u0642\u0630\u0641 \u0628\u0645\u0627 \u0627\u0631\u062a\u0643\u0628\u0647 \u0646\u0641\u0633\u064b\u0627 \u0628\u0631\u064a\u0626\u0629 \u0644\u0627 \u062c\u0646\u0627\u064a\u0629 \u0644\u0647\u0627\u060c \u0641\u0642\u062f \u062a\u062d\u0645\u0651\u064e\u0644 \u0643\u0630\u0628\u064b\u0627 \u0648\u0630\u0646\u0628\u064b\u0627 \u0628\u064a\u0651\u0646\u0627.","4:113":"\u0648\u0644\u0648\u0644\u0627 \u0623\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0642\u062f \u0645\u064e\u0646\u0651\u064e \u0639\u0644\u064a\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0648\u0631\u062d\u0645\u0643 \u0628\u0646\u0639\u0645\u0629 \u0627\u0644\u0646\u0628\u0648\u0629\u060c \u0641\u0639\u0635\u0645\u0643 \u0628\u062a\u0648\u0641\u064a\u0642\u0647 \u0628\u0645\u0627 \u0623\u0648\u062d\u0649 \u0625\u0644\u064a\u0643\u060c \u0644\u0639\u0632\u0645\u062a \u062c\u0645\u0627\u0639\u0629 \u0645\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u062e\u0648\u0646\u0648\u0646 \u0623\u0646\u0641\u0633\u0647\u0645 \u0623\u0646 \u064a\u064f\u0632\u0650\u0644\u0651\u064f\u0648\u0643\u064e \u0639\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u062d\u0642\u060c \u0648\u0645\u0627 \u064a\u064f\u0632\u0650\u0644\u0651\u064f\u0648\u0646\u064e \u0628\u0630\u0644\u0643 \u0625\u0644\u0627 \u0623\u0646\u0641\u0633\u0647\u0645\u060c \u0648\u0645\u0627 \u064a\u0642\u062f\u0631\u0648\u0646 \u0639\u0644\u0649 \u0625\u064a\u0630\u0627\u0626\u0643 \u0644\u0639\u0635\u0645\u0629 \u0627\u0644\u0644\u0647 \u0644\u0643\u060c \u0648\u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643 \u0627\u0644\u0642\u0631\u0622\u0646 \u0648\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0645\u0628\u064a\u0646\u0629 \u0644\u0647\u060c \u0648\u0647\u062f\u0627\u0643 \u0625\u0644\u0649 \u0639\u0644\u0645 \u0645\u0627 \u0644\u0645 \u062a\u0643\u0646 \u062a\u0639\u0644\u0645\u0647 \u0645\u0650\u0646 \u0642\u0628\u0644\u060c \u0648\u0643\u0627\u0646 \u0645\u0627 \u062e\u0635\u0651\u064e\u0643 \u0627\u0644\u0644\u0647 \u0628\u0647 \u0645\u0646 \u0641\u0636\u0644\u064d \u0623\u0645\u0631\u064b\u0627 \u0639\u0638\u064a\u0645\u064b\u0627.","4:114":"\u0644\u0627 \u0646\u0641\u0639 \u0641\u064a \u0643\u062b\u064a\u0631 \u0645\u0646 \u0643\u0644\u0627\u0645 \u0627\u0644\u0646\u0627\u0633 \u0633\u0631\u0651\u0627\u064b \u0641\u064a\u0645\u0627 \u0628\u064a\u0646\u0647\u0645\u060c \u0625\u0644\u0627 \u0625\u0630\u0627 \u0643\u0627\u0646 \u062d\u062f\u064a\u062b\u064b\u0627 \u062f\u0627\u0639\u064a\u064b\u0627 \u0625\u0644\u0649 \u0628\u0630\u0644 \u0627\u0644\u0645\u0639\u0631\u0648\u0641 \u0645\u0646 \u0627\u0644\u0635\u062f\u0642\u0629\u060c \u0623\u0648 \u0627\u0644\u0643\u0644\u0645\u0629 \u0627\u0644\u0637\u064a\u0628\u0629\u060c \u0623\u0648 \u0627\u0644\u062a\u0648\u0641\u064a\u0642 \u0628\u064a\u0646 \u0627\u0644\u0646\u0627\u0633\u060c \u0648\u0645\u0646 \u064a\u0641\u0639\u0644 \u062a\u0644\u0643 \u0627\u0644\u0623\u0645\u0648\u0631 \u0637\u0644\u0628\u064b\u0627 \u0644\u0631\u0636\u0627 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0631\u0627\u062c\u064a\u064b\u0627 \u062b\u0648\u0627\u0628\u0647\u060c \u0641\u0633\u0648\u0641 \u0646\u0624\u062a\u064a\u0647 \u062b\u0648\u0627\u0628\u064b\u0627 \u062c\u0632\u064a\u0644\u0627 \u0648\u0627\u0633\u0639\u064b\u0627.","4:115":"\u0648\u0645\u0646 \u064a\u062e\u0627\u0644\u0641 \u0627\u0644\u0631\u0633\u0648\u0644 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0645\u0646 \u0628\u0639\u062f \u0645\u0627 \u0638\u0647\u0631 \u0644\u0647 \u0627\u0644\u062d\u0642\u060c \u0648\u064a\u0633\u0644\u0643 \u0637\u0631\u064a\u0642\u064b\u0627 \u063a\u064a\u0631 \u0637\u0631\u064a\u0642 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0648\u0645\u0627 \u0647\u0645 \u0639\u0644\u064a\u0647 \u0645\u0646 \u0627\u0644\u062d\u0642\u060c \u0646\u062a\u0631\u0643\u0647 \u0648\u0645\u0627 \u062a\u0648\u062c\u0651\u064e\u0647 \u0625\u0644\u064a\u0647\u060c \u0641\u0644\u0627 \u0646\u0648\u0641\u0642\u0647 \u0644\u0644\u062e\u064a\u0631\u060c \u0648\u0646\u062f\u062e\u0644\u0647 \u0646\u0627\u0631 \u062c\u0647\u0646\u0645 \u064a\u0642\u0627\u0633\u064a \u062d\u0631\u0651\u064e\u0647\u0627\u060c \u0648\u0628\u0626\u0633 \u0647\u0630\u0627 \u0627\u0644\u0645\u0631\u062c\u0639 \u0648\u0627\u0644\u0645\u0622\u0644.","4:116":"\u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0627 \u064a\u063a\u0641\u0631 \u0623\u0646 \u064a\u0634\u0631\u0643 \u0628\u0647\u060c \u0648\u064a\u063a\u0641\u0631 \u0645\u0627 \u062f\u0648\u0646 \u0627\u0644\u0634\u0631\u0643 \u0645\u0646 \u0627\u0644\u0630\u0646\u0648\u0628 \u0644\u0645\u0646 \u064a\u0634\u0627\u0621 \u0645\u0646 \u0639\u0628\u0627\u062f\u0647. \u0648\u0645\u0646 \u064a\u062c\u0639\u0644 \u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0627\u0644\u0648\u0627\u062d\u062f \u0627\u0644\u0623\u062d\u062f \u0634\u0631\u064a\u0643\u064b\u0627 \u0645\u0646 \u062e\u0644\u0642\u0647\u060c \u0641\u0642\u062f \u0628\u064e\u0639\u064f\u062f\u064e \u0639\u0646 \u0627\u0644\u062d\u0642 \u0628\u0639\u062f\u064b\u0627 \u0643\u0628\u064a\u0631\u064b\u0627.","4:117":"\u0645\u0627 \u064a\u0639\u0628\u062f \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0625\u0644\u0627 \u0623\u0648\u062b\u0627\u0646\u064b\u0627 \u0644\u0627 \u062a\u0646\u0641\u0639 \u0648\u0644\u0627 \u062a\u0636\u0631\u060c \u0648\u0645\u0627 \u064a\u0639\u0628\u062f\u0648\u0646 \u0625\u0644\u0627 \u0634\u064a\u0637\u0627\u0646\u064b\u0627 \u0645\u062a\u0645\u0631\u062f\u064b\u0627 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0628\u0644\u063a \u0641\u064a \u0627\u0644\u0641\u0633\u0627\u062f \u0648\u0627\u0644\u0625\u0641\u0633\u0627\u062f \u062d\u062f\u0651\u0627\u064b \u0643\u0628\u064a\u0631\u064b\u0627.","4:118":"\u0637\u0631\u062f\u0647 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0645\u0646 \u0631\u062d\u0645\u062a\u0647. \u0648\u0642\u0627\u0644 \u0627\u0644\u0634\u064a\u0637\u0627\u0646: \u0644\u0623\u062a\u062e\u0630\u0646 \u0645\u0650\u0646 \u0639\u0628\u0627\u062f\u0643 \u062c\u0632\u0621\u064b\u0627 \u0645\u0639\u0644\u0648\u0645\u064b\u0627 \u0641\u064a \u0625\u063a\u0648\u0627\u0626\u0647\u0645 \u0642\u0648\u0644\u0627 \u0648\u0639\u0645\u0644\u0627.","4:119":"\u0648\u0644\u0623\u0635\u0631\u0641\u064e\u0646\u0651\u064e \u0645\u064e\u0646 \u062a\u0628\u0639\u0646\u064a \u0645\u0646\u0647\u0645 \u0639\u0646 \u0627\u0644\u062d\u0642\u060c \u0648\u0644\u0623\u0639\u0650\u062f\u064e\u0646\u0651\u064e\u0647\u0645 \u0628\u0627\u0644\u0623\u0645\u0627\u0646\u064a \u0627\u0644\u0643\u0627\u0630\u0628\u0629\u060c \u0648\u0644\u0623\u062f\u0639\u0648\u0646\u0651\u064e\u0647\u0645 \u0625\u0644\u0649 \u062a\u0642\u0637\u064a\u0639 \u0622\u0630\u0627\u0646 \u0627\u0644\u0623\u0646\u0639\u0627\u0645 \u0648\u062a\u0634\u0642\u064a\u0642\u0647\u0627 \u0644\u0645\u0627 \u0623\u0632\u064a\u0646\u0647 \u0644\u0647\u0645 \u0645\u0646 \u0627\u0644\u0628\u0627\u0637\u0644\u060c \u0648\u0644\u0623\u062f\u0639\u0648\u0646\u0651\u064e\u0647\u0645 \u0625\u0644\u0649 \u062a\u063a\u064a\u064a\u0631 \u062e\u0644\u0642 \u0627\u0644\u0644\u0647 \u0641\u064a \u0627\u0644\u0641\u0637\u0631\u0629\u060c \u0648\u0647\u064a\u0626\u0629 \u0645\u0627 \u0639\u0644\u064a\u0647 \u0627\u0644\u062e\u0644\u0642. \u0648\u0645\u0646 \u064a\u0633\u062a\u062c\u0628 \u0644\u0644\u0634\u064a\u0637\u0627\u0646 \u0648\u064a\u062a\u062e\u0630\u0647 \u0646\u0627\u0635\u0631\u064b\u0627 \u0644\u0647 \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647 \u0627\u0644\u0642\u0648\u064a \u0627\u0644\u0639\u0632\u064a\u0632\u060c \u0641\u0642\u062f \u0647\u0644\u0643 \u0647\u0644\u0627\u0643\u064b\u0627 \u0628\u064a\u0651\u0650\u0646\u064b\u0627.","4:120":"\u064a\u0639\u062f \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0623\u062a\u0628\u0627\u0639\u0647 \u0628\u0627\u0644\u0648\u0639\u0648\u062f \u0627\u0644\u0643\u0627\u0630\u0628\u0629\u060c \u0648\u064a\u063a\u0631\u064a\u0647\u0645 \u0628\u0627\u0644\u0623\u0645\u0627\u0646\u064a \u0627\u0644\u0628\u0627\u0637\u0644\u0629 \u0627\u0644\u062e\u0627\u062f\u0639\u0629\u060c \u0648\u0645\u0627 \u064a\u064e\u0639\u0650\u062f\u0647\u0645 \u0625\u0644\u0627 \u062e\u062f\u064a\u0639\u0629 \u0644\u0627 \u0635\u062d\u0629 \u0644\u0647\u0627\u060c \u0648\u0644\u0627 \u062f\u0644\u064a\u0644 \u0639\u0644\u064a\u0647\u0627.","4:121":"\u0623\u0648\u0644\u0626\u0643 \u0645\u0622\u0644\u0647\u0645 \u062c\u0647\u0646\u0645\u060c \u0648\u0644\u0627 \u064a\u062c\u062f\u0648\u0646 \u0639\u0646\u0647\u0627 \u0645\u0639\u062f\u0644\u0627 \u0648\u0644\u0627 \u0645\u0644\u062c\u0623\u064b.","4:122":"\u0648\u0627\u0644\u0630\u064a\u0646 \u0635\u064e\u062f\u064e\u0642\u0648\u0627 \u0641\u064a \u0625\u064a\u0645\u0627\u0646\u0647\u0645 \u0628\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0623\u062a\u0628\u0639\u0648\u0627 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0635\u0627\u0644\u062d\u0629 \u0633\u064a\u062f\u062e\u0644\u0647\u0645 \u0627\u0644\u0644\u0647 -\u0628\u0641\u0636\u0644\u0647- \u062c\u0646\u0627\u062a \u062a\u062c\u0631\u064a \u0645\u0646 \u0646\u062d\u062a \u0623\u0634\u062c\u0627\u0631\u0647\u0627 \u0627\u0644\u0623\u0646\u0647\u0627\u0631 \u0645\u0627\u0643\u062b\u064a\u0646 \u0641\u064a\u0647\u0627 \u0623\u0628\u062f\u064b\u0627\u060c \u0648\u0639\u062f\u0627 \u0645\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u062e\u0644\u0641 \u0648\u0639\u062f\u0647. \u0648\u0644\u0627 \u0623\u062d\u062f \u0623\u0635\u062f\u0642 \u0645\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0641\u064a \u0642\u0648\u0644\u0647 \u0648\u0648\u0639\u062f\u0647.","4:123":"\u0644\u0627 \u064a\u064f\u0646\u0627\u0644 \u0647\u0630\u0627 \u0627\u0644\u0641\u0636\u0644 \u0627\u0644\u0639\u0638\u064a\u0645 \u0628\u0627\u0644\u0623\u0645\u0627\u0646\u064a \u0627\u0644\u062a\u064a \u062a\u062a\u0645\u0646\u0648\u0646\u0647\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646\u060c \u0648\u0644\u0627 \u0628\u0623\u0645\u0627\u0646\u064a \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649\u060c \u0648\u0625\u0646\u0645\u0627 \u064a\u064f\u0646\u0627\u0644 \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0627\u0644\u0635\u0627\u062f\u0642 \u0628\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0625\u062d\u0633\u0627\u0646 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0630\u064a \u064a\u0631\u0636\u064a\u0647. \u0648\u0645\u0646 \u064a\u0639\u0645\u0644 \u0639\u0645\u0644\u0627 \u0633\u064a\u0626\u064b\u0627 \u064a\u062c\u0632 \u0628\u0647\u060c \u0648\u0644\u0627 \u064a\u062c\u062f \u0644\u0647 \u0633\u0648\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0644\u064a\u0651\u0627\u064b \u064a\u062a\u0648\u0644\u0649 \u0623\u0645\u0631\u0647 \u0648\u0634\u0623\u0646\u0647\u060c \u0648\u0644\u0627 \u0646\u0635\u064a\u0631\u064b\u0627 \u064a\u0646\u0635\u0631\u0647\u060c \u0648\u064a\u062f\u0641\u0639 \u0639\u0646\u0647 \u0633\u0648\u0621 \u0627\u0644\u0639\u0630\u0627\u0628.","4:124":"\u0648\u0645\u0646 \u064a\u0639\u0645\u0644 \u0645\u0646 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0635\u0627\u0644\u062d\u0629 \u0645\u0646 \u0630\u0643\u0631 \u0623\u0648 \u0623\u0646\u062b\u0649\u060c \u0648\u0647\u0648 \u0645\u0624\u0645\u0646 \u0628\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0628\u0645\u0627 \u0623\u0646\u0632\u0644 \u0645\u0646 \u0627\u0644\u062d\u0642\u060c \u0641\u0623\u0648\u0644\u0626\u0643 \u064a\u062f\u062e\u0644\u0647\u0645 \u0627\u0644\u0644\u0647 \u0627\u0644\u062c\u0646\u0629 \u062f\u0627\u0631 \u0627\u0644\u0646\u0639\u064a\u0645 \u0627\u0644\u0645\u0642\u064a\u0645\u060c \u0648\u0644\u0627 \u064a\u064f\u0646\u0652\u0642\u064e\u0635\u0648\u0646 \u0645\u0646 \u062b\u0648\u0627\u0628 \u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0634\u064a\u0626\u064b\u0627\u060c \u0648\u0644\u0648 \u0643\u0627\u0646 \u0645\u0642\u062f\u0627\u0631 \u0627\u0644\u0646\u0642\u0631\u0629 \u0641\u064a \u0638\u0647\u0631 \u0627\u0644\u0646\u0648\u0627\u0629.","4:125":"\u0644\u0627 \u0623\u062d\u062f \u0623\u062d\u0633\u0646 \u062f\u064a\u0646\u064b\u0627 \u0645\u0645\u0646 \u0627\u0646\u0642\u0627\u062f \u0628\u0642\u0644\u0628\u0647 \u0648\u0633\u0627\u0626\u0631 \u062c\u0648\u0627\u0631\u062d\u0647 \u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u062d\u062f\u0647\u060c \u0648\u0647\u0648 \u0645\u062d\u0633\u0646\u060c \u0648\u0627\u062a\u0628\u0639 \u062f\u064a\u0646 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0648\u0634\u0631\u0639\u0647\u060c \u0645\u0627\u0626\u0644\u0627 \u0639\u0646 \u0627\u0644\u0639\u0642\u0627\u0626\u062f \u0627\u0644\u0641\u0627\u0633\u062f\u0629 \u0648\u0627\u0644\u0634\u0631\u0627\u0626\u0639 \u0627\u0644\u0628\u0627\u0637\u0644\u0629. \u0648\u0642\u062f \u0627\u0635\u0637\u0641\u0649 \u0627\u0644\u0644\u0647 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 -\u0639\u0644\u064a\u0647 \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0627\u0644\u0633\u0644\u0627\u0645- \u0648\u0627\u062a\u062e\u0630\u0647 \u0635\u0641\u064a\u0651\u0627\u064b \u0645\u0646 \u0628\u064a\u0646 \u0633\u0627\u0626\u0631 \u062e\u0644\u0642\u0647. \u0648\u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0629\u060c \u0625\u062b\u0628\u0627\u062a \u0635\u0641\u0629 \u0627\u0644\u062e\u064f\u0644\u0651\u0629 \u0644\u0644\u0647 -\u062a\u0639\u0627\u0644\u0649- \u0648\u0647\u064a \u0623\u0639\u0644\u0649 \u0645\u0642\u0627\u0645\u0627\u062a \u0627\u0644\u0645\u062d\u0628\u0629\u060c \u0648\u0627\u0644\u0627\u0635\u0637\u0641\u0627\u0621.","4:126":"\u0648\u0644\u0644\u0647 \u062c\u0645\u064a\u0639 \u0645\u0627 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0643\u0648\u0646 \u0645\u0646 \u0627\u0644\u0645\u062e\u0644\u0648\u0642\u0627\u062a\u060c \u0641\u0647\u064a \u0645\u0644\u0643 \u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u062d\u062f\u0647. \u0648\u0643\u0627\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0628\u0643\u0644 \u0634\u064a\u0621 \u0645\u062d\u064a\u0637\u064b\u0627\u060c \u0644\u0627 \u064a\u062e\u0641\u0649 \u0639\u0644\u064a\u0647 \u0634\u064a\u0621 \u0645\u0646 \u0623\u0645\u0648\u0631 \u062e\u0644\u0642\u0647.","4:127":"\u064a\u0637\u0644\u0628 \u0627\u0644\u0646\u0627\u0633 \u0645\u0646\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0623\u0646 \u062a\u0628\u064a\u0646 \u0644\u0647\u0645 \u0645\u0627 \u0623\u0634\u0643\u0644 \u0639\u0644\u064a\u0647\u0645 \u0641\u064e\u0647\u0652\u0645\u064f\u0647 \u0645\u0646 \u0642\u0636\u0627\u064a\u0627 \u0627\u0644\u0646\u0633\u0627\u0621 \u0648\u0623\u062d\u0643\u0627\u0645\u0647\u0646\u060c \u0642\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u064a\u0628\u064a\u0651\u0650\u0646 \u0644\u0643\u0645 \u0623\u0645\u0648\u0631\u0647\u0646\u060c \u0648\u0645\u0627 \u064a\u062a\u0644\u0649 \u0639\u0644\u064a\u0643\u0645 \u0641\u064a \u0627\u0644\u0643\u062a\u0627\u0628 \u0641\u064a \u064a\u062a\u0627\u0645\u0649 \u0627\u0644\u0646\u0633\u0627\u0621 \u0627\u0644\u0644\u0627\u062a\u064a \u0644\u0627 \u062a\u0639\u0637\u0648\u0646\u0647\u0646 \u0645\u0627 \u0641\u0631\u0636 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0647\u0646 \u0645\u0646 \u0627\u0644\u0645\u0647\u0631 \u0648\u0627\u0644\u0645\u064a\u0631\u0627\u062b \u0648\u063a\u064a\u0631 \u0630\u0644\u0643 \u0645\u0646 \u0627\u0644\u062d\u0642\u0648\u0642\u060c \u0648\u062a\u062d\u0628\u0648\u0646 \u0646\u0643\u0627\u062d\u0647\u0646 \u0623\u0648 \u062a\u0631\u063a\u0628\u0648\u0646 \u0639\u0646 \u0646\u0643\u0627\u062d\u0647\u0646\u060c \u0648\u064a\u0628\u064a\u0651\u0650\u0646 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0623\u0645\u0631 \u0627\u0644\u0636\u0639\u0641\u0627\u0621 \u0645\u0646 \u0627\u0644\u0635\u063a\u0627\u0631\u060c \u0648\u0648\u062c\u0648\u0628 \u0627\u0644\u0642\u064a\u0627\u0645 \u0644\u0644\u064a\u062a\u0627\u0645\u0649 -\u0648\u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u0645\u0627\u062a \u0622\u0628\u0627\u0624\u0647\u0645 \u0648\u0647\u0645 \u062f\u0648\u0646 \u0633\u0646 \u0627\u0644\u0628\u0644\u0648\u063a- \u0628\u0627\u0644\u0639\u062f\u0644 \u0648\u062a\u0631\u0643 \u0627\u0644\u062c\u0648\u0631 \u0639\u0644\u064a\u0647\u0645 \u0641\u064a \u062d\u0642\u0648\u0642\u0647\u0645. \u0648\u0645\u0627 \u062a\u0641\u0639\u0644\u0648\u0627 \u0645\u0646 \u062e\u064a\u0631 \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0643\u0627\u0646 \u0628\u0647 \u0639\u0644\u064a\u0645\u064b\u0627\u060c \u0644\u0627 \u064a\u062e\u0641\u0649 \u0639\u0644\u064a\u0647 \u0634\u064a\u0621 \u0645\u0646\u0647 \u0648\u0644\u0627 \u0645\u0646 \u063a\u064a\u0631\u0647.","4:128":"\u0648\u0625\u0646 \u0639\u0644\u0645\u062a \u0627\u0645\u0631\u0623\u0629 \u0645\u0646 \u0632\u0648\u062c\u0647\u0627 \u062a\u0631\u0641\u0639\u064b\u0627 \u0639\u0646\u0647\u0627\u060c \u0648\u062a\u0639\u0627\u0644\u064a\u064b\u0627 \u0639\u0644\u064a\u0647\u0627 \u0623\u0648 \u0627\u0646\u0635\u0631\u0627\u0641\u064b\u0627 \u0639\u0646\u0647\u0627 \u0641\u0644\u0627 \u0625\u062b\u0645 \u0639\u0644\u064a\u0647\u0645\u0627 \u0623\u0646 \u064a\u062a\u0635\u0627\u0644\u062d\u0627 \u0639\u0644\u0649 \u0645\u0627 \u062a\u0637\u064a\u0628 \u0628\u0647 \u0646\u0641\u0648\u0633\u0647\u0645\u0627 \u0645\u0646 \u0627\u0644\u0642\u0633\u0645\u0629 \u0623\u0648 \u0627\u0644\u0646\u0641\u0642\u0629\u060c \u0648\u0627\u0644\u0635\u0644\u062d \u0623\u0648\u0644\u0649 \u0648\u0623\u0641\u0636\u0644. \u0648\u062c\u0628\u0644\u062a \u0627\u0644\u0646\u0641\u0648\u0633 \u0639\u0644\u0649 \u0627\u0644\u0634\u062d \u0648\u0627\u0644\u0628\u062e\u0644. \u0648\u0625\u0646 \u062a\u062d\u0633\u0646\u0648\u0627 \u0645\u0639\u0627\u0645\u0644\u0629 \u0632\u0648\u062c\u0627\u062a\u0643\u0645 \u0648\u062a\u062e\u0627\u0641\u0648\u0627 \u0627\u0644\u0644\u0647 \u0641\u064a\u0647\u0646\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0643\u0627\u0646 \u0628\u0645\u0627 \u062a\u0639\u0645\u0644\u0648\u0646 \u0645\u0646 \u0630\u0644\u0643 \u0648\u063a\u064a\u0631\u0647 \u0639\u0627\u0644\u0645\u064b\u0627 \u0644\u0627 \u064a\u062e\u0641\u0649 \u0639\u0644\u064a\u0647 \u0634\u064a\u0621\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a\u0643\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643.","4:129":"\u0648\u0644\u0646 \u062a\u0642\u062f\u0631\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u062c\u0627\u0644- \u0639\u0644\u0649 \u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u0639\u062f\u0644 \u0627\u0644\u062a\u0627\u0645 \u0628\u064a\u0646 \u0627\u0644\u0646\u0633\u0627\u0621 \u0641\u064a \u0627\u0644\u0645\u062d\u0628\u0629 \u0648\u0645\u064a\u0644 \u0627\u0644\u0642\u0644\u0628\u060c \u0645\u0647\u0645\u0627 \u0628\u0630\u0644\u062a\u0645 \u0641\u064a \u0630\u0644\u0643 \u0645\u0646 \u0627\u0644\u062c\u0647\u062f\u060c \u0641\u0644\u0627 \u062a\u0639\u0631\u0636\u0648\u0627 \u0639\u0646 \u0627\u0644\u0645\u0631\u063a\u0648\u0628 \u0639\u0646\u0647\u0627 \u0643\u0644 \u0627\u0644\u0625\u0639\u0631\u0627\u0636\u060c \u0641\u062a\u062a\u0631\u0643\u0648\u0647\u0627 \u0643\u0627\u0644\u0645\u0631\u0623\u0629 \u0627\u0644\u062a\u064a \u0644\u064a\u0633\u062a \u0628\u0630\u0627\u062a \u0632\u0648\u062c \u0648\u0644\u0627 \u0647\u064a \u0645\u0637\u0644\u0642\u0629 \u0641\u062a\u0623\u062b\u0645\u0648\u0627. \u0648\u0625\u0646 \u062a\u0635\u0644\u062d\u0648\u0627 \u0623\u0639\u0645\u0627\u0644\u0643\u0645 \u0641\u062a\u0639\u062f\u0644\u0648\u0627 \u0641\u064a \u0642\u064e\u0633\u0652\u0645\u0643\u0645 \u0628\u064a\u0646 \u0632\u0648\u062c\u0627\u062a\u0643\u0645\u060c \u0648\u062a\u0631\u0627\u0642\u0628\u0648\u0627 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u062a\u062e\u0634\u0648\u0647 \u0641\u064a\u0647\u0646\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0643\u0627\u0646 \u063a\u0641\u0648\u0631\u064b\u0627 \u0644\u0639\u0628\u0627\u062f\u0647\u060c \u0631\u062d\u064a\u0645\u064b\u0627 \u0628\u0647\u0645.","4:130":"\u0648\u0625\u0646 \u0648\u0642\u0639\u062a \u0627\u0644\u0641\u0631\u0642\u0629 \u0628\u064a\u0646 \u0627\u0644\u0631\u062c\u0644 \u0648\u0627\u0645\u0631\u0623\u062a\u0647\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u064a\u063a\u0646\u064a \u0643\u0644\u0627 \u0645\u0646\u0647\u0645\u0627 \u0645\u0646 \u0641\u0636\u0644\u0647 \u0648\u0633\u0639\u062a\u0647; \u0641\u0625\u0646\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649 \u0648\u0627\u0633\u0639 \u0627\u0644\u0641\u0636\u0644 \u0648\u0627\u0644\u0645\u0646\u0629\u060c \u062d\u0643\u064a\u0645 \u0641\u064a\u0645\u0627 \u064a\u0642\u0636\u064a \u0628\u0647 \u0628\u064a\u0646 \u0639\u0628\u0627\u062f\u0647.","4:131":"\u0648\u0644\u0644\u0647 \u0645\u0644\u0643 \u0645\u0627 \u0641\u064a \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0645\u0627 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0648\u0645\u0627 \u0628\u064a\u0646\u0647\u0645\u0627. \u0648\u0644\u0642\u062f \u0639\u0647\u062f\u0646\u0627 \u0625\u0644\u0649 \u0627\u0644\u0630\u064a\u0646 \u0623\u064f\u0639\u0637\u0648\u0627 \u0627\u0644\u0643\u062a\u0627\u0628 \u0645\u0646 \u0642\u0628\u0644\u0643\u0645 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649\u060c \u0648\u0639\u0647\u062f\u0646\u0627 \u0625\u0644\u064a\u0643\u0645 \u0643\u0630\u0644\u0643 -\u064a\u0627 \u0623\u0645\u0629 \u0645\u062d\u0645\u062f- \u0628\u062a\u0642\u0648\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0627\u0644\u0642\u064a\u0627\u0645 \u0628\u0623\u0645\u0631\u0647 \u0648\u0627\u062c\u062a\u0646\u0627\u0628 \u0646\u0647\u064a\u0647\u060c \u0648\u0628\u064a\u0651\u064e\u0646\u0651\u064e\u0627 \u0644\u0643\u0645 \u0623\u0646\u0643\u0645 \u0625\u0646 \u062a\u062c\u062d\u062f\u0648\u0627 \u0648\u062d\u062f\u0627\u0646\u064a\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0634\u0631\u0639\u0647 \u0641\u0625\u0646\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u063a\u0646\u064a \u0639\u0646\u0643\u0645; \u0644\u0623\u0646 \u0644\u0647 \u062c\u0645\u064a\u0639 \u0645\u0627 \u0641\u064a \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636. \u0648\u0643\u0627\u0646 \u0627\u0644\u0644\u0647 \u063a\u0646\u064a\u0651\u0627\u064b \u0639\u0646 \u062e\u0644\u0642\u0647\u060c \u062d\u0645\u064a\u062f\u064b\u0627 \u0641\u064a \u0635\u0641\u0627\u062a\u0647 \u0648\u0623\u0641\u0639\u0627\u0644\u0647.","4:132":"\u0648\u0644\u0644\u0647 \u0645\u0644\u0643 \u0645\u0627 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0643\u0648\u0646 \u0645\u0646 \u0627\u0644\u0643\u0627\u0626\u0646\u0627\u062a\u060c \u0648\u0643\u0641\u0649 \u0628\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0642\u0627\u0626\u0645\u064b\u0627 \u0628\u0634\u0624\u0648\u0646 \u062e\u0644\u0642\u0647 \u062d\u0627\u0641\u0638\u064b\u0627 \u0644\u0647\u0627.","4:133":"\u0625\u0646 \u064a\u0634\u0623 \u0627\u0644\u0644\u0647 \u064a\u064f\u0647\u0644\u0643\u0651\u064f\u0645 \u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633\u060c \u0648\u064a\u0623\u062a \u0628\u0642\u0648\u0645 \u0622\u062e\u0631\u064a\u0646 \u063a\u064a\u0631\u0643\u0645. \u0648\u0643\u0627\u0646 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0630\u0644\u0643 \u0642\u062f\u064a\u0631\u064b\u0627.","4:134":"\u0645\u0646 \u064a\u0631\u063a\u0628 \u0645\u0646\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633- \u0641\u064a \u062b\u0648\u0627\u0628 \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u064a\u0639\u0631\u0636 \u0639\u0646 \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0641\u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u062b\u0648\u0627\u0628 \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0641\u0644\u064a\u0637\u0644\u0628 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u062e\u064a\u0631\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0641\u0647\u0648 \u0627\u0644\u0630\u064a \u064a\u0645\u0644\u0643\u0647\u0645\u0627. \u0648\u0643\u0627\u0646 \u0627\u0644\u0644\u0647 \u0633\u0645\u064a\u0639\u064b\u0627 \u0644\u0623\u0642\u0648\u0627\u0644 \u0639\u0628\u0627\u062f\u0647\u060c \u0628\u0635\u064a\u0631\u064b\u0627 \u0628\u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0648\u0646\u064a\u0627\u062a\u0647\u0645\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a\u0647\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643.","4:135":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647\u060c \u0643\u0648\u0646\u0648\u0627 \u0642\u0627\u0626\u0645\u064a\u0646 \u0628\u0627\u0644\u0639\u062f\u0644\u060c \u0645\u0624\u062f\u064a\u0646 \u0644\u0644\u0634\u0647\u0627\u062f\u0629 \u0644\u0648\u062c\u0647 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0644\u0648 \u0643\u0627\u0646\u062a \u0639\u0644\u0649 \u0623\u0646\u0641\u0633\u0643\u0645\u060c \u0623\u0648 \u0639\u0644\u0649 \u0622\u0628\u0627\u0626\u0643\u0645 \u0648\u0623\u0645\u0647\u0627\u062a\u0643\u0645\u060c \u0623\u0648 \u0639\u0644\u0649 \u0623\u0642\u0627\u0631\u0628\u0643\u0645\u060c \u0645\u0647\u0645\u0627 \u0643\u0627\u0646 \u0634\u0623\u0646 \u0627\u0644\u0645\u0634\u0647\u0648\u062f \u0639\u0644\u064a\u0647 \u063a\u0646\u064a\u0651\u064b\u0627 \u0623\u0648 \u0641\u0642\u064a\u0631\u064b\u0627; \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0623\u0648\u0644\u0649 \u0628\u0647\u0645\u0627 \u0645\u0646\u0643\u0645\u060c \u0648\u0623\u0639\u0644\u0645 \u0628\u0645\u0627 \u0641\u064a\u0647 \u0635\u0644\u0627\u062d\u0647\u0645\u0627\u060c \u0641\u0644\u0627 \u064a\u062d\u0645\u0644\u0646\u0651\u064e\u0643\u0645 \u0627\u0644\u0647\u0648\u0649 \u0648\u0627\u0644\u062a\u0639\u0635\u0628 \u0639\u0644\u0649 \u062a\u0631\u0643 \u0627\u0644\u0639\u062f\u0644\u060c \u0648\u0625\u0646 \u062a\u062d\u0631\u0641\u0648\u0627 \u0627\u0644\u0634\u0647\u0627\u062f\u0629 \u0628\u0623\u0644\u0633\u0646\u062a\u0643\u0645 \u0641\u062a\u0623\u062a\u0648\u0627 \u0628\u0647\u0627 \u0639\u0644\u0649 \u063a\u064a\u0631 \u062d\u0642\u064a\u0642\u062a\u0647\u0627\u060c \u0623\u0648 \u062a\u0639\u0631\u0636\u0648\u0627 \u0639\u0646\u0647\u0627 \u0628\u062a\u0631\u0643 \u0623\u062f\u0627\u0626\u0647\u0627 \u0623\u0648 \u0628\u0643\u062a\u0645\u0627\u0646\u0647\u0627\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0643\u0627\u0646 \u0639\u0644\u064a\u0645\u064b\u0627 \u0628\u062f\u0642\u0627\u0626\u0642 \u0623\u0639\u0645\u0627\u0644\u0643\u0645\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a\u0643\u0645 \u0628\u0647\u0627.","4:136":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647 \u062f\u0627\u0648\u0645\u0648\u0627 \u0639\u0644\u0649 \u0645\u0627 \u0623\u0646\u062a\u0645 \u0639\u0644\u064a\u0647 \u0645\u0646 \u0627\u0644\u062a\u0635\u062f\u064a\u0642 \u0627\u0644\u062c\u0627\u0632\u0645 \u0628\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0628\u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0645\u0646 \u0637\u0627\u0639\u062a\u0647\u0645\u0627\u060c \u0648\u0628\u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0630\u064a \u0646\u0632\u0644\u0647 \u0639\u0644\u064a\u0647\u060c \u0648\u0628\u062c\u0645\u064a\u0639 \u0627\u0644\u0643\u062a\u0628 \u0627\u0644\u062a\u064a \u0623\u0646\u0632\u0644\u0647\u0627 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0627\u0644\u0631\u0633\u0644. \u0648\u0645\u0646 \u064a\u0643\u0641\u0631 \u0628\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0645\u0644\u0627\u0626\u0643\u062a\u0647 \u0627\u0644\u0645\u0643\u0631\u0645\u064a\u0646\u060c \u0648\u0643\u062a\u0628\u0647 \u0627\u0644\u062a\u064a \u0623\u0646\u0632\u0644\u0647\u0627 \u0644\u0647\u062f\u0627\u064a\u0629 \u062e\u0644\u0642\u0647\u060c \u0648\u0631\u0633\u0644\u0647 \u0627\u0644\u0630\u064a\u0646 \u0627\u0635\u0637\u0641\u0627\u0647\u0645 \u0644\u062a\u0628\u0644\u064a\u063a \u0631\u0633\u0627\u0644\u062a\u0647\u060c \u0648\u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0622\u062e\u0631 \u0627\u0644\u0630\u064a \u064a\u0642\u0648\u0645 \u0627\u0644\u0646\u0627\u0633 \u0641\u064a\u0647 \u0628\u0639\u062f \u0645\u0648\u062a\u0647\u0645 \u0644\u0644\u0639\u0631\u0636 \u0648\u0627\u0644\u062d\u0633\u0627\u0628\u060c \u0641\u0642\u062f \u062e\u0631\u062c \u0645\u0646 \u0627\u0644\u062f\u064a\u0646\u060c \u0648\u0628\u064e\u0639\u064f\u062f\u064e \u0628\u0639\u062f\u064b\u0627 \u0643\u0628\u064a\u0631\u064b\u0627 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u062d\u0642.","4:137":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u062f\u062e\u0644\u0648\u0627 \u0641\u064a \u0627\u0644\u0625\u064a\u0645\u0627\u0646\u060c \u062b\u0645 \u0631\u062c\u0639\u0648\u0627 \u0639\u0646\u0647 \u0625\u0644\u0649 \u0627\u0644\u0643\u0641\u0631\u060c \u062b\u0645 \u0639\u0627\u062f\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u0625\u064a\u0645\u0627\u0646\u060c \u062b\u0645 \u0631\u062c\u0639\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u0643\u0641\u0631 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649\u060c \u062b\u0645 \u0623\u0635\u0631\u0651\u064f\u0648\u0627 \u0639\u0644\u0649 \u0643\u0641\u0631\u0647\u0645 \u0648\u0627\u0633\u062a\u0645\u0631\u0648\u0627 \u0639\u0644\u064a\u0647\u060c \u0644\u0645 \u064a\u0643\u0646 \u0627\u0644\u0644\u0647 \u0644\u064a\u063a\u0641\u0631 \u0644\u0647\u0645\u060c \u0648\u0644\u0627 \u0644\u064a\u062f\u0644\u0647\u0645 \u0639\u0644\u0649 \u0637\u0631\u064a\u0642 \u0645\u0646 \u0637\u0631\u0642 \u0627\u0644\u0647\u062f\u0627\u064a\u0629\u060c \u0627\u0644\u062a\u064a \u064a\u0646\u062c\u0648\u0646 \u0628\u0647\u0627 \u0645\u0646 \u0633\u0648\u0621 \u0627\u0644\u0639\u0627\u0642\u0628\u0629.","4:138":"\u0628\u0634\u0651\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 -\u0648\u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u064a\u0638\u0647\u0631\u0648\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u064a\u0628\u0637\u0646\u0648\u0646 \u0627\u0644\u0643\u0641\u0631- \u0628\u0623\u0646 \u0644\u0647\u0645 \u0639\u0630\u0627\u0628\u064b\u0627 \u0645\u0648\u062c\u0639\u064b\u0627.","4:139":"\u0627\u0644\u0630\u064a\u0646 \u064a\u0648\u0627\u0644\u0648\u0646 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646\u060c \u0648\u064a\u062a\u062e\u0630\u0648\u0646\u0647\u0645 \u0623\u0639\u0648\u0627\u0646\u064b\u0627 \u0644\u0647\u0645\u060c \u0648\u064a\u062a\u0631\u0643\u0648\u0646 \u0648\u0644\u0627\u064a\u0629 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0648\u0644\u0627 \u064a\u0631\u063a\u0628\u0648\u0646 \u0641\u064a \u0645\u0648\u062f\u062a\u0647\u0645. \u0623\u064a\u0637\u0644\u0628\u0648\u0646 \u0628\u0630\u0644\u0643 \u0627\u0644\u0646\u0635\u0631\u0629 \u0648\u0627\u0644\u0645\u0646\u0639\u0629 \u0639\u0646\u062f \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646\u061f \u0625\u0646\u0647\u0645 \u0644\u0627 \u064a\u0645\u0644\u0643\u0648\u0646 \u0630\u0644\u0643\u060c \u0641\u0627\u0644\u0646\u0635\u0631\u0629 \u0648\u0627\u0644\u0639\u0632\u0629 \u0648\u0627\u0644\u0642\u0648\u0629 \u062c\u0645\u064a\u0639\u0647\u0627 \u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u062d\u062f\u0647.","4:140":"\u0648\u0642\u062f \u0646\u0632\u0644 \u0639\u0644\u064a\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0641\u064a \u0643\u062a\u0627\u0628 \u0631\u0628\u0643\u0645 \u0623\u0646\u0647 \u0625\u0630\u0627 \u0633\u0645\u0639\u062a\u0645 \u0627\u0644\u0643\u0641\u0631 \u0628\u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u0627\u0633\u062a\u0647\u0632\u0627\u0621 \u0628\u0647\u0627 \u0641\u0644\u0627 \u062a\u062c\u0644\u0633\u0648\u0627 \u0645\u0639 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0648\u0627\u0644\u0645\u0633\u062a\u0647\u0632\u0626\u064a\u0646\u060c \u0625\u0644\u0627 \u0625\u0630\u0627 \u0623\u062e\u0630\u0648\u0627 \u0641\u064a \u062d\u062f\u064a\u062b \u063a\u064a\u0631 \u062d\u062f\u064a\u062b \u0627\u0644\u0643\u0641\u0631 \u0648\u0627\u0644\u0627\u0633\u062a\u0647\u0632\u0627\u0621 \u0628\u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647. \u0625\u0646\u0643\u0645 \u0625\u0630\u0627 \u062c\u0627\u0644\u0633\u062a\u0645\u0648\u0647\u0645\u060c \u0648\u0647\u0645 \u0639\u0644\u0649 \u0645\u0627 \u0647\u0645 \u0639\u0644\u064a\u0647\u060c \u0641\u0623\u0646\u062a\u0645 \u0645\u062b\u0644\u0647\u0645; \u0644\u0623\u0646\u0643\u0645 \u0631\u0636\u064a\u062a\u0645 \u0628\u0643\u0641\u0631\u0647\u0645 \u0648\u0627\u0633\u062a\u0647\u0632\u0627\u0626\u0647\u0645\u060c \u0648\u0627\u0644\u0631\u0627\u0636\u064a \u0628\u0627\u0644\u0645\u0639\u0635\u064a\u0629 \u0643\u0627\u0644\u0641\u0627\u0639\u0644 \u0644\u0647\u0627. \u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u062c\u0627\u0645\u0639 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0648\u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0641\u064a \u0646\u0627\u0631 \u062c\u0647\u0646\u0645 \u062c\u0645\u064a\u0639\u064b\u0627\u060c \u064a\u0644\u0652\u0642\u064e\u0648\u0646 \u0641\u064a\u0647\u0627 \u0633\u0648\u0621 \u0627\u0644\u0639\u0630\u0627\u0628.","4:141":"\u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u064a\u0646\u062a\u0638\u0631\u0648\u0646 \u0645\u0627 \u064a\u062d\u0644\u0651\u064f \u0628\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0645\u0646 \u0627\u0644\u0641\u062a\u0646 \u0648\u0627\u0644\u062d\u0631\u0628\u060c \u0641\u0625\u0646 \u0645\u0646\u0651\u064e \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0628\u0641\u0636\u0644\u0647\u060c \u0648\u0646\u0635\u0631\u0643\u0645 \u0639\u0644\u0649 \u0639\u062f\u0648\u0643\u0645 \u0648\u063a\u0646\u0645\u062a\u0645\u060c \u0642\u0627\u0644\u0648\u0627 \u0644\u0643\u0645: \u0623\u0644\u0645 \u0646\u0643\u0646 \u0645\u0639\u0643\u0645 \u0646\u0624\u0627\u0632\u0631\u0643\u0645\u061f \u0648\u0625\u0646 \u0643\u0627\u0646 \u0644\u0644\u062c\u0627\u062d\u062f\u064a\u0646 \u0644\u0647\u0630\u0627 \u0627\u0644\u062f\u064a\u0646 \u0642\u064e\u062f\u0652\u0631\u064c \u0645\u0646 \u0627\u0644\u0646\u0635\u0631 \u0648\u0627\u0644\u063a\u0646\u064a\u0645\u0629\u060c \u0642\u0627\u0644\u0648\u0627 \u0644\u0647\u0645: \u0623\u0644\u0645 \u0646\u0633\u0627\u0639\u062f\u0643\u0645 \u0628\u0645\u0627 \u0642\u062f\u0651\u064e\u0645\u0646\u0627\u0647 \u0644\u0643\u0645 \u0648\u0646\u064e\u062d\u0652\u0645\u0650\u0643\u064f\u0645 \u0645\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u061f \u0641\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u064a\u0642\u0636\u064a \u0628\u064a\u0646\u0643\u0645 \u0648\u0628\u064a\u0646\u0647\u0645 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u0648\u0644\u0646 \u064a\u062c\u0639\u0644 \u0627\u0644\u0644\u0647 \u0644\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0637\u0631\u064a\u0642\u064b\u0627 \u0644\u0644\u063a\u0644\u0628\u0629 \u0639\u0644\u0649 \u0639\u0628\u0627\u062f\u0647 \u0627\u0644\u0635\u0627\u0644\u062d\u064a\u0646\u060c \u0641\u0627\u0644\u0639\u0627\u0642\u0628\u0629 \u0644\u0644\u0645\u062a\u0642\u064a\u0646 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629.","4:142":"\u0625\u0646\u0651\u064e \u0637\u0631\u064a\u0642\u0629 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0645\u062e\u0627\u062f\u0639\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0628\u0645\u0627 \u064a\u0638\u0647\u0631\u0648\u0646\u0647 \u0645\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0645\u0627 \u064a\u0628\u0637\u0646\u0648\u0646\u0647 \u0645\u0646 \u0627\u0644\u0643\u0641\u0631\u060c \u0638\u0646\u0651\u064b\u0627 \u0623\u0646\u0647 \u064a\u062e\u0641\u0649 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u0644\u062d\u0627\u0644 \u0623\u0646 \u0627\u0644\u0644\u0647 \u062e\u0627\u062f\u0639\u0647\u0645 \u0648\u0645\u062c\u0627\u0632\u064a\u0647\u0645 \u0628\u0645\u062b\u0644 \u0639\u0645\u0644\u0647\u0645\u060c \u0648\u0625\u0630\u0627 \u0642\u0627\u0645 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0644\u0623\u062f\u0627\u0621 \u0627\u0644\u0635\u0644\u0627\u0629\u060c \u0642\u0627\u0645\u0648\u0627 \u0625\u0644\u064a\u0647\u0627 \u0641\u064a \u0641\u062a\u0648\u0631\u060c \u064a\u0642\u0635\u062f\u0648\u0646 \u0628\u0635\u0644\u0627\u062a\u0647\u0645 \u0627\u0644\u0631\u064a\u0627\u0621 \u0648\u0627\u0644\u0633\u0645\u0639\u0629\u060c \u0648\u0644\u0627 \u064a\u0630\u0643\u0631\u0648\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0625\u0644\u0627 \u0630\u0643\u0631\u064b\u0627 \u0642\u0644\u064a\u0644\u0627.","4:143":"\u0625\u0646\u0651\u064e \u0645\u0650\u0646 \u0634\u0623\u0646 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0627\u0644\u062a\u0631\u062f\u062f \u0648\u0627\u0644\u062d\u064e\u064a\u0652\u0631\u0629 \u0648\u0627\u0644\u0627\u0636\u0637\u0631\u0627\u0628\u060c \u0644\u0627 \u064a\u0633\u062a\u0642\u0631\u0648\u0646 \u0639\u0644\u0649 \u062d\u0627\u0644\u060c \u0641\u0644\u0627 \u0647\u0645 \u0645\u0639 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0648\u0644\u0627 \u0647\u0645 \u0645\u0639 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646. \u0648\u0645\u0646 \u064a\u0635\u0631\u0641 \u0627\u0644\u0644\u0647 \u0642\u0644\u0628\u0647 \u0639\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0647 \u0648\u0627\u0644\u0627\u0633\u062a\u0645\u0633\u0627\u0643 \u0628\u0647\u062f\u064a\u0647\u060c \u0641\u0644\u0646 \u062a\u062c\u062f \u0644\u0647 \u0637\u0631\u064a\u0642\u064b\u0627 \u0625\u0644\u0649 \u0627\u0644\u0647\u062f\u0627\u064a\u0629 \u0648\u0627\u0644\u064a\u0642\u064a\u0646.","4:144":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647\u060c \u0644\u0627 \u062a\u0648\u0627\u0644\u0648\u0627 \u0627\u0644\u062c\u0627\u062d\u062f\u064a\u0646 \u0644\u062f\u064a\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u062a\u062a\u0631\u0643\u0648\u0627 \u0645\u0648\u0627\u0644\u0627\u0629 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0648\u0645\u0648\u062f\u062a\u0647\u0645. \u0623\u062a\u0631\u064a\u062f\u0648\u0646 \u0628\u0645\u0648\u062f\u0651\u064e\u0629 \u0623\u0639\u062f\u0627\u0626\u0643\u0645 \u0623\u0646 \u062a\u062c\u0639\u0644\u0648\u0627 \u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0644\u064a\u0643\u0645 \u062d\u062c\u0629 \u0638\u0627\u0647\u0631\u0629 \u0639\u0644\u0649 \u0639\u062f\u0645 \u0635\u062f\u0642\u0643\u0645 \u0641\u064a \u0625\u064a\u0645\u0627\u0646\u0643\u0645\u061f","4:145":"\u0625\u0646 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0641\u064a \u0623\u0633\u0641\u0644 \u0645\u0646\u0627\u0632\u0644 \u0627\u0644\u0646\u0627\u0631 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u0648\u0644\u0646 \u062a\u062c\u062f \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0646\u0627\u0635\u0631\u064b\u0627 \u064a\u062f\u0641\u0639 \u0639\u0646\u0647\u0645 \u0633\u0648\u0621 \u0647\u0630\u0627 \u0627\u0644\u0645\u0635\u064a\u0631.","4:146":"\u0625\u0644\u0627 \u0627\u0644\u0630\u064a\u0646 \u0631\u062c\u0639\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u062a\u0627\u0628\u0648\u0627 \u0625\u0644\u064a\u0647\u060c \u0648\u0623\u0635\u0644\u062d\u0648\u0627 \u0645\u0627 \u0623\u0641\u0633\u062f\u0648\u0627 \u0645\u0646 \u0623\u062d\u0648\u0627\u0644\u0647\u0645 \u0628\u0627\u0637\u0646\u064b\u0627 \u0648\u0638\u0627\u0647\u0631\u064b\u0627\u060c \u0648\u0648\u0627\u0644\u0648\u0627 \u0639\u0628\u0627\u062f\u0647 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0648\u0627\u0633\u062a\u0645\u0633\u0643\u0648\u0627 \u0628\u062f\u064a\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u0623\u062e\u0644\u0635\u0648\u0627 \u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647\u060c \u0641\u0623\u0648\u0644\u0626\u0643 \u0645\u0639 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u0633\u0648\u0641 \u064a\u0639\u0637\u064a \u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u062b\u0648\u0627\u0628\u064b\u0627 \u0639\u0638\u064a\u0645\u064b\u0627.","4:147":"\u0645\u0627 \u064a\u0641\u0639\u0644 \u0627\u0644\u0644\u0647 \u0628\u0639\u0630\u0627\u0628\u0643\u0645 \u0625\u0646 \u0623\u0635\u0644\u062d\u062a\u0645 \u0627\u0644\u0639\u0645\u0644 \u0648\u0622\u0645\u0646\u062a\u0645 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u063a\u0646\u064a \u0639\u0645\u0651\u064e\u0646 \u0633\u0648\u0627\u0647\u060c \u0648\u0625\u0646\u0645\u0627 \u064a\u0639\u0630\u0628 \u0627\u0644\u0639\u0628\u0627\u062f \u0628\u0630\u0646\u0648\u0628\u0647\u0645. \u0648\u0643\u0627\u0646 \u0627\u0644\u0644\u0647 \u0634\u0627\u0643\u0631\u064b\u0627 \u0644\u0639\u0628\u0627\u062f\u0647 \u0639\u0644\u0649 \u0637\u0627\u0639\u062a\u0647\u0645 \u0644\u0647\u060c \u0639\u0644\u064a\u0645\u064b\u0627 \u0628\u0643\u0644 \u0634\u064a\u0621.","4:148":"\u0644\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0644\u0647 \u0623\u0646 \u064a\u064e\u062c\u0647\u0631 \u0623\u062d\u062f\u064c \u0628\u0642\u0648\u0644 \u0627\u0644\u0633\u0648\u0621\u060c \u0644\u0643\u0646 \u064a\u064f\u0628\u0627\u062d \u0644\u0644\u0645\u0638\u0644\u0648\u0645 \u0623\u0646 \u064a\u064e\u0630\u0643\u064f\u0631 \u0638\u0627\u0644\u0645\u0647 \u0628\u0645\u0627 \u0641\u064a\u0647 \u0645\u0646 \u0627\u0644\u0633\u0648\u0621; \u0644\u064a\u0628\u064a\u0651\u0650\u0646 \u0645\u064e\u0638\u0652\u0644\u0645\u062a\u0647. \u0648\u0643\u0627\u0646 \u0627\u0644\u0644\u0647 \u0633\u0645\u064a\u0639\u064b\u0627 \u0644\u0645\u0627 \u062a\u062c\u0647\u0631\u0648\u0646 \u0628\u0647\u060c \u0639\u0644\u064a\u0645\u064b\u0627 \u0628\u0645\u0627 \u062a\u062e\u0641\u0648\u0646 \u0645\u0646 \u0630\u0644\u0643.","4:149":"\u0646\u064e\u062f\u064e\u0628 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0625\u0644\u0649 \u0627\u0644\u0639\u0641\u0648\u060c \u0648\u0645\u0647\u0651\u064e\u062f \u0644\u0647 \u0628\u0623\u0646\u0651\u064e \u0627\u0644\u0645\u0624\u0645\u0646: \u0625\u0645\u0651\u064e\u0627 \u0623\u0646 \u064a\u064f\u0638\u0647\u0631 \u0627\u0644\u062e\u064a\u0631\u060c \u0648\u0625\u0645\u0651\u064e\u0627 \u0623\u0646 \u064a\u064f\u062e\u0641\u064a\u0647\u060c \u0648\u0643\u0630\u0644\u0643 \u0645\u0639 \u0627\u0644\u0625\u0633\u0627\u0621\u0629: \u0625\u0645\u0627 \u0623\u0646 \u064a\u0638\u0647\u0631\u0647\u0627 \u0641\u064a \u062d\u0627\u0644 \u0627\u0644\u0627\u0646\u062a\u0635\u0627\u0641 \u0645\u0646 \u0627\u0644\u0645\u0633\u064a\u0621\u060c \u0648\u0625\u0645\u0627 \u0623\u0646 \u064a\u0639\u0641\u0648 \u0648\u064a\u0635\u0641\u062d\u060c \u0648\u0627\u0644\u0639\u0641\u0648\u064f \u0623\u0641\u0636\u0644\u064f; \u0641\u0625\u0646 \u0645\u0646 \u0635\u0641\u0627\u062a\u0647 \u062a\u0639\u0627\u0644\u0649 \u0627\u0644\u0639\u0641\u0648 \u0639\u0646 \u0639\u0628\u0627\u062f\u0647 \u0645\u0639 \u0642\u062f\u0631\u062a\u0647 \u0639\u0644\u064a\u0647\u0645.","4:150":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u0643\u0641\u0631\u0648\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0644\u0647 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649\u060c \u0648\u064a\u0631\u064a\u062f\u0648\u0646 \u0623\u0646 \u064a\u0641\u0631\u0642\u0648\u0627 \u0628\u064a\u0646 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0644\u0647 \u0628\u0623\u0646 \u064a\u0624\u0645\u0646\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u064a\u0643\u0630\u0628\u0648\u0627 \u0631\u0633\u0644\u0647 \u0627\u0644\u0630\u064a\u0646 \u0623\u0631\u0633\u0644\u0647\u0645 \u0625\u0644\u0649 \u062e\u0644\u0642\u0647\u060c \u0623\u0648 \u064a\u0639\u062a\u0631\u0641\u0648\u0627 \u0628\u0635\u062f\u0642 \u0628\u0639\u0636 \u0627\u0644\u0631\u0633\u0644 \u062f\u0648\u0646 \u0628\u0639\u0636\u060c \u0648\u064a\u0632\u0639\u0645\u0648\u0627 \u0623\u0646\u0651\u064e \u0628\u0639\u0636\u0647\u0645 \u0627\u0641\u062a\u0631\u0648\u0627 \u0639\u0644\u0649 \u0631\u0628\u0651\u0650\u0647\u0645\u060c \u0648\u064a\u0631\u064a\u062f\u0648\u0646 \u0623\u0646 \u064a\u062a\u062e\u0630\u0648\u0627 \u0637\u0631\u064a\u0642\u064b\u0627 \u0625\u0644\u0649 \u0627\u0644\u0636\u0644\u0627\u0644\u0629 \u0627\u0644\u062a\u064a \u0623\u062d\u062f\u062b\u0648\u0647\u0627 \u0648\u0627\u0644\u0628\u062f\u0639\u0629 \u0627\u0644\u062a\u064a \u0627\u0628\u062a\u062f\u0639\u0648\u0647\u0627.","4:151":"\u0623\u0648\u0644\u0626\u0643 \u0647\u0645 \u0623\u0647\u0644 \u0627\u0644\u0643\u0641\u0631 \u0627\u0644\u0645\u062d\u0642\u0651\u064e\u0642 \u0627\u0644\u0630\u064a \u0644\u0627 \u0634\u0643 \u0641\u064a\u0647\u060c \u0648\u0623\u0639\u062a\u062f\u0646\u0627 \u0644\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0639\u0630\u0627\u0628\u064b\u0627 \u064a\u062e\u0632\u064a\u0647\u0645 \u0648\u064a\u0647\u064a\u0646\u0647\u0645.","4:152":"\u0648\u0627\u0644\u0630\u064a\u0646 \u0635\u064e\u062f\u0651\u064e\u0642\u0648\u0627 \u0628\u0648\u062d\u062f\u0627\u0646\u064a\u0629 \u0627\u0644\u0644\u0647\u060c \u0648\u0623\u0642\u0631\u0651\u064f\u0648\u0627 \u0628\u0646\u0628\u0648\u0651\u064e\u0629 \u0631\u0633\u0644\u0647 \u0623\u062c\u0645\u0639\u064a\u0646\u060c \u0648\u0644\u0645 \u064a\u0641\u0631\u0642\u0648\u0627 \u0628\u064a\u0646 \u0623\u062d\u062f \u0645\u0646\u0647\u0645\u060c \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u064a\u0639\u0629 \u0627\u0644\u0644\u0647\u060c \u0623\u0648\u0644\u0626\u0643 \u0633\u0648\u0641 \u064a\u0639\u0637\u064a\u0647\u0645 \u062c\u0632\u0627\u0621\u0647\u0645 \u0648\u062b\u0648\u0627\u0628\u0647\u0645 \u0639\u0644\u0649 \u0625\u064a\u0645\u0627\u0646\u0647\u0645 \u0628\u0647 \u0648\u0628\u0631\u0633\u0644\u0647. \u0648\u0643\u0627\u0646 \u0627\u0644\u0644\u0647 \u063a\u0641\u0648\u0631\u064b\u0627 \u0631\u062d\u064a\u0645\u064b\u0627.","4:153":"\u064a\u0633\u0623\u0644\u0643 \u0627\u0644\u064a\u0647\u0648\u062f -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0645\u0639\u062c\u0632\u0629 \u0645\u062b\u0644 \u0645\u0639\u062c\u0632\u0629 \u0645\u0648\u0633\u0649 \u062a\u0634\u0647\u062f \u0644\u0643 \u0628\u0627\u0644\u0635\u062f\u0642: \u0628\u0623\u0646 \u062a\u0646\u0632\u0644 \u0639\u0644\u064a\u0647\u0645 \u0635\u064f\u062d\u064f\u0641\u064b\u0627 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0645\u0643\u062a\u0648\u0628\u0629\u064b\u060c \u0645\u062b\u0644 \u0645\u062c\u064a\u0621 \u0645\u0648\u0633\u0649 \u0628\u0627\u0644\u0623\u0644\u0648\u0627\u062d \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647\u060c \u0641\u0644\u0627 \u062a\u0639\u062c\u0628 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0641\u0642\u062f \u0633\u0623\u0644 \u0623\u0633\u0644\u0627\u0641\u0647\u0645 \u0645\u0648\u0633\u0649 -\u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645- \u0645\u0627 \u0647\u0648 \u0623\u0639\u0638\u0645: \u0633\u0623\u0644\u0648\u0647 \u0623\u0646 \u064a\u0631\u064a\u0647\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u0627\u0646\u064a\u0629\u064b\u060c \u0641\u064e\u0635\u064f\u0639\u0650\u0642\u0648\u0627 \u0628\u0633\u0628\u0628 \u0638\u0644\u0645\u0647\u0645 \u0623\u0646\u0641\u0633\u0647\u0645 \u062d\u064a\u0646 \u0633\u0623\u0644\u0648\u0627 \u0623\u0645\u0631\u064b\u0627 \u0644\u064a\u0633 \u0645\u0646 \u062d\u0642\u0651\u0650\u0647\u0645. \u0648\u0628\u0639\u062f \u0623\u0646 \u0623\u062d\u064a\u0627\u0647\u0645 \u0627\u0644\u0644\u0647 \u0628\u0639\u062f \u0627\u0644\u0635\u0639\u0642\u060c \u0648\u0634\u0627\u0647\u062f\u0648\u0627 \u0627\u0644\u0622\u064a\u0627\u062a \u0627\u0644\u0628\u064a\u0646\u0627\u062a \u0639\u0644\u0649 \u064a\u062f \u0645\u0648\u0633\u0649 \u0627\u0644\u0642\u0627\u0637\u0639\u0629 \u0628\u0646\u0641\u064a \u0627\u0644\u0634\u0631\u0643\u060c \u0639\u0628\u062f\u0648\u0627 \u0627\u0644\u0639\u062c\u0644 \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647\u060c \u0641\u0639\u064e\u0641\u0648\u0646\u0627 \u0639\u0646 \u0639\u0628\u0627\u062f\u062a\u0647\u0645 \u0627\u0644\u0639\u062c\u0644 \u0628\u0633\u0628\u0628 \u062a\u0648\u0628\u062a\u0647\u0645\u060c \u0648\u0622\u062a\u064a\u0646\u0627 \u0645\u0648\u0633\u0649 \u062d\u062c\u0629 \u0639\u0638\u064a\u0645\u0629 \u062a\u0624\u064a\u0651\u0650\u062f \u0635\u0650\u062f\u0642 \u0646\u064f\u0628\u064f\u0648\u0651\u064e\u062a\u0650\u0647.","4:154":"\u0648\u0631\u0641\u0639\u0646\u0627 \u0641\u0648\u0642 \u0631\u0624\u0648\u0633\u0647\u0645 \u062c\u0628\u0644 \u0627\u0644\u0637\u0648\u0631 \u062d\u064a\u0646 \u0627\u0645\u062a\u0646\u0639\u0648\u0627 \u0639\u0646 \u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0628\u0627\u0644\u0639\u0647\u062f \u0627\u0644\u0645\u0624\u0643\u062f \u0627\u0644\u0630\u064a \u0623\u0639\u0637\u0648\u0647 \u0628\u0627\u0644\u0639\u0645\u0644 \u0628\u0623\u062d\u0643\u0627\u0645 \u0627\u0644\u062a\u0648\u0631\u0627\u0629\u060c \u0648\u0623\u0645\u0631\u0646\u0627\u0647\u0645 \u0623\u0646 \u064a\u062f\u062e\u0644\u0648\u0627 \u0628\u0627\u0628 \xab\u0628\u064a\u062a \u0627\u0644\u0645\u0642\u062f\u0633\xbb \u0633\u064f\u062c\u0651\u064e\u062f\u064b\u0627\u060c \u0641\u062f\u062e\u0644\u0648\u0627 \u064a\u0632\u062d\u0641\u0648\u0646 \u0639\u0644\u0649 \u0623\u0633\u062a\u0627\u0647\u0647\u0645\u060c \u0648\u0623\u0645\u0631\u0646\u0627\u0647\u0645 \u0623\u0644\u0627 \u064a\u064e\u0639\u0652\u062a\u064e\u062f\u064f\u0648\u0627 \u0628\u0627\u0644\u0635\u064a\u062f \u0641\u064a \u064a\u0648\u0645 \u0627\u0644\u0633\u0628\u062a \u0641\u0627\u0639\u062a\u062f\u064e\u0648\u0627\u060c \u0648\u0635\u0627\u062f\u0648\u0627\u060c \u0648\u0623\u062e\u0630\u0646\u0627 \u0639\u0644\u064a\u0647\u0645 \u0639\u0647\u062f\u064b\u0627 \u0645\u0624\u0643\u062f\u064b\u0627\u060c \u0641\u0646\u0642\u0636\u0648\u0647.","4:155":"\u0641\u0644\u0639\u0646\u0651\u064e\u0627\u0647\u0645 \u0628\u0633\u0628\u0628 \u0646\u0642\u0636\u0647\u0645 \u0644\u0644\u0639\u0647\u0648\u062f\u060c \u0648\u0643\u0641\u0631\u0647\u0645 \u0628\u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0627\u0644\u062f\u0627\u0644\u0629 \u0639\u0644\u0649 \u0635\u062f\u0642 \u0631\u0633\u0644\u0647\u060c \u0648\u0642\u062a\u0644\u0647\u0645 \u0644\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0638\u0644\u0645\u064b\u0627 \u0648\u0627\u0639\u062a\u062f\u0627\u0621\u064b\u060c \u0648\u0642\u0648\u0644\u0647\u0645: \u0642\u0644\u0648\u0628\u0646\u0627 \u0639\u0644\u064a\u0647\u0627 \u0623\u063a\u0637\u064a\u0629 \u0641\u0644\u0627 \u062a\u0641\u0642\u0647 \u0645\u0627 \u062a\u0642\u0648\u0644\u060c \u0628\u0644 \u0637\u0645\u0633 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0627 \u0628\u0633\u0628\u0628 \u0643\u0641\u0631\u0647\u0645\u060c \u0641\u0644\u0627 \u064a\u0624\u0645\u0646\u0648\u0646 \u0625\u0644\u0627 \u0625\u064a\u0645\u0627\u0646\u064b\u0627 \u0642\u0644\u064a\u0644\u0627 \u0644\u0627 \u064a\u0646\u0641\u0639\u0647\u0645.","4:156":"\u0648\u0643\u0630\u0644\u0643 \u0644\u0639\u0646\u0651\u064e\u0627\u0647\u0645 \u0628\u0633\u0628\u0628 \u0643\u0641\u0631\u0647\u0645 \u0648\u0627\u0641\u062a\u0631\u0627\u0626\u0647\u0645 \u0639\u0644\u0649 \u0645\u0631\u064a\u0645 \u0628\u0645\u0627 \u0646\u0633\u0628\u0648\u0647 \u0625\u0644\u064a\u0647\u0627 \u0645\u0646 \u0627\u0644\u0632\u0646\u0649\u060c \u0648\u0647\u064a \u0628\u0631\u064a\u0626\u0629 \u0645\u0646\u0647.","4:157":"\u0648\u0628\u0633\u0628\u0628 \u0642\u0648\u0644\u0647\u0645 -\u0639\u0644\u0649 \u0633\u0628\u064a\u0644 \u0627\u0644\u062a\u0647\u0643\u0645 \u0648\u0627\u0644\u0627\u0633\u062a\u0647\u0632\u0627\u0621-: \u0625\u0646\u0627 \u0642\u062a\u0644\u0646\u0627 \u0627\u0644\u0645\u0633\u064a\u062d \u0639\u064a\u0633\u0649 \u0628\u0646 \u0645\u0631\u064a\u0645 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647\u060c \u0648\u0645\u0627 \u0642\u062a\u0644\u0648\u0627 \u0639\u064a\u0633\u0649 \u0648\u0645\u0627 \u0635\u0644\u0628\u0648\u0647\u060c \u0628\u0644 \u0635\u0644\u0628\u0648\u0627 \u0631\u062c\u0644\u0627 \u0634\u0628\u064a\u0647\u064b\u0627 \u0628\u0647 \u0638\u0646\u0651\u064b\u0627 \u0645\u0646\u0647\u0645 \u0623\u0646\u0647 \u0639\u064a\u0633\u0649. \u0648\u0645\u0646 \u0627\u062f\u0651\u064e\u0639\u0649 \u0642\u064e\u062a\u0652\u0644\u064e\u0647\u064f \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f\u060c \u0648\u0645\u0646 \u0623\u0633\u0644\u0645\u0647 \u0625\u0644\u064a\u0647\u0645 \u0645\u0646 \u0627\u0644\u0646\u0635\u0627\u0631\u0649\u060c \u0643\u0644\u0647\u0645 \u0648\u0627\u0642\u0639\u0648\u0646 \u0641\u064a \u0634\u0643 \u0648\u062d\u064e\u064a\u0652\u0631\u064e\u0629\u060c \u0644\u0627 \u0639\u0650\u0644\u0652\u0645\u064e \u0644\u062f\u064a\u0647\u0645 \u0625\u0644\u0627 \u0627\u062a\u0628\u0627\u0639 \u0627\u0644\u0638\u0646\u060c \u0648\u0645\u0627 \u0642\u062a\u0644\u0648\u0647 \u0645\u062a\u064a\u0642\u0646\u064a\u0646 \u0628\u0644 \u0634\u0627\u0643\u064a\u0646 \u0645\u062a\u0648\u0647\u0645\u064a\u0646.","4:158":"\u0628\u0644 \u0631\u0641\u0639 \u0627\u0644\u0644\u0647 \u0639\u064a\u0633\u0649 \u0625\u0644\u064a\u0647 \u0628\u0628\u062f\u0646\u0647 \u0648\u0631\u0648\u062d\u0647 \u062d\u064a\u0651\u064b\u0627\u060c \u0648\u0637\u0647\u0651\u064e\u0631\u0647 \u0645\u0646 \u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627. \u0648\u0643\u0627\u0646 \u0627\u0644\u0644\u0647 \u0639\u0632\u064a\u0632\u064b\u0627 \u0641\u064a \u0645\u0644\u0643\u0647\u060c \u062d\u0643\u064a\u0645\u064b\u0627 \u0641\u064a \u062a\u062f\u0628\u064a\u0631\u0647 \u0648\u0642\u0636\u0627\u0626\u0647.","4:159":"\u0648\u0625\u0646\u0647 \u0644\u0627 \u064a\u0628\u0642\u0649 \u0623\u062d\u062f\u064c \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0628\u0639\u062f \u0646\u0632\u0648\u0644 \u0639\u064a\u0633\u0649 \u0622\u062e\u0631 \u0627\u0644\u0632\u0645\u0627\u0646 \u0625\u0644\u0627 \u0622\u0645\u0646 \u0628\u0647 \u0642\u0628\u0644 \u0645\u0648\u062a\u0647 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0648\u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u064a\u0643\u0648\u0646 \u0639\u064a\u0633\u0649 -\u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645- \u0634\u0647\u064a\u062f\u064b\u0627 \u0628\u062a\u0643\u0630\u064a\u0628 \u0645\u064e\u0646 \u0643\u0630\u0651\u064e\u0628\u0647\u060c \u0648\u062a\u0635\u062f\u064a\u0642 \u0645\u064e\u0646 \u0635\u062f\u0651\u064e\u0642\u0647.","4:160":"\u0641\u0628\u0633\u0628\u0628 \u0638\u0644\u0645 \u0627\u0644\u064a\u0647\u0648\u062f \u0628\u0645\u0627 \u0627\u0631\u062a\u0643\u0628\u0648\u0647 \u0645\u0646 \u0627\u0644\u0630\u0646\u0648\u0628 \u0627\u0644\u0639\u0638\u064a\u0645\u0629 \u062d\u064e\u0631\u0651\u064e\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645 \u0637\u064a\u0628\u0627\u062a \u0645\u0646 \u0627\u0644\u0645\u0623\u0643\u0644 \u0643\u0627\u0646\u062a \u062d\u0644\u0627\u0644\u0627 \u0644\u0647\u0645\u060c \u0648\u0628\u0633\u0628\u0628 \u0635\u062f\u0651\u0650\u0647\u0645 \u0623\u0646\u0641\u0633\u0647\u0645 \u0648\u063a\u064a\u0631\u0647\u0645 \u0639\u0646 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647 \u0627\u0644\u0642\u0648\u064a\u0645.","4:161":"\u0648\u0628\u0633\u0628\u0628 \u062a\u0646\u0627\u0648\u0644\u0647\u0645 \u0627\u0644\u0631\u0628\u0627 \u0627\u0644\u0630\u064a \u0646\u0647\u0648\u0627 \u0639\u0646\u0647\u060c \u0648\u0627\u0633\u062a\u062d\u0644\u0627\u0644\u0647\u0645 \u0623\u0645\u0648\u0627\u0644 \u0627\u0644\u0646\u0627\u0633 \u0628\u063a\u064a\u0631 \u0627\u0633\u062a\u062d\u0642\u0627\u0642\u060c \u0648\u0623\u0639\u062a\u062f\u0646\u0627 \u0644\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0645\u0650\u0646 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u064a\u0647\u0648\u062f \u0639\u0630\u0627\u0628\u064b\u0627 \u0645\u0648\u062c\u0639\u064b\u0627 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629.","4:162":"\u0644\u0643\u0646\u0650 \u0627\u0644\u0645\u062a\u0645\u0643\u0646\u0648\u0646 \u0641\u064a \u0627\u0644\u0639\u0644\u0645 \u0628\u0623\u062d\u0643\u0627\u0645 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f\u060c \u0648\u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u064a\u0624\u0645\u0646\u0648\u0646 \u0628\u0627\u0644\u0630\u064a \u0623\u0646\u0632\u0644\u0647 \u0627\u0644\u0644\u0647 \u0625\u0644\u064a\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0648\u0647\u0648 \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0648\u0628\u0627\u0644\u0630\u064a \u0623\u0646\u0632\u0644 \u0625\u0644\u0649 \u0627\u0644\u0631\u0633\u0644 \u0645\u0646 \u0642\u0628\u0644\u0643 \u0643\u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644\u060c \u0648\u064a\u0624\u062f\u0651\u064f\u0648\u0646 \u0627\u0644\u0635\u0644\u0627\u0629 \u0641\u064a \u0623\u0648\u0642\u0627\u062a\u0647\u0627\u060c \u0648\u064a\u062e\u0631\u062c\u0648\u0646 \u0632\u0643\u0627\u0629 \u0623\u0645\u0648\u0627\u0644\u0647\u0645\u060c \u0648\u064a\u0624\u0645\u0646\u0648\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0628\u0627\u0644\u0628\u0639\u062b \u0648\u0627\u0644\u062c\u0632\u0627\u0621\u060c \u0623\u0648\u0644\u0626\u0643 \u0633\u064a\u0639\u0637\u064a\u0647\u0645 \u0627\u0644\u0644\u0647 \u062b\u0648\u0627\u0628\u064b\u0627 \u0639\u0638\u064a\u0645\u064b\u0627\u060c \u0648\u0647\u0648 \u0627\u0644\u062c\u0646\u0629.","4:163":"\u0625\u0646\u0627 \u0623\u0648\u062d\u064a\u0646\u0627 \u0627\u0644\u064a\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0628\u062a\u0628\u0644\u064a\u063a \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0643\u0645\u0627 \u0623\u0648\u062d\u064a\u0646\u0627 \u0625\u0644\u0649 \u0646\u0648\u062d \u0648\u0627\u0644\u0646\u0628\u064a\u064a\u0646 \u0645\u0646 \u0628\u0639\u062f\u0647\u060c \u0648\u0623\u0648\u062d\u064a\u0646\u0627 \u0625\u0644\u0649 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0648\u0625\u0633\u0645\u0627\u0639\u064a\u0644 \u0648\u0625\u0633\u062d\u0627\u0642 \u0648\u064a\u0639\u0642\u0648\u0628 \u0648\u0627\u0644\u0623\u0633\u0628\u0627\u0637 -\u0648\u0647\u0645 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u0643\u0627\u0646\u0648\u0627 \u0641\u064a \u0642\u0628\u0627\u0626\u0644 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0627\u0644\u0627\u062b\u0646\u062a\u064a \u0639\u0634\u0631\u0629 \u0645\u0646 \u0648\u0644\u062f \u064a\u0639\u0642\u0648\u0628- \u0648\u0639\u064a\u0633\u0649 \u0648\u0623\u064a\u0648\u0628 \u0648\u064a\u0648\u0646\u0633 \u0648\u0647\u0627\u0631\u0648\u0646 \u0648\u0633\u0644\u064a\u0645\u0627\u0646. \u0648\u0622\u062a\u064a\u0646\u0627 \u062f\u0627\u0648\u062f \u0632\u0628\u0648\u0631\u064b\u0627\u060c \u0648\u0647\u0648 \u0643\u062a\u0627\u0628 \u0648\u0635\u062d\u0641 \u0645\u0643\u062a\u0648\u0628\u0629.","4:164":"\u0648\u0623\u0631\u0633\u0644\u0646\u0627 \u0631\u0633\u0644\u0627 \u0642\u062f \u0642\u0635\u0635\u0646\u0627\u0647\u0645 \u0639\u0644\u064a\u0643 \u0641\u064a \u0627\u0644\u0642\u0631\u0622\u0646 \u0645\u0646 \u0642\u0628\u0644 \u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0629\u060c \u0648\u0631\u0633\u0644\u0627 \u0644\u0645 \u0646\u0642\u0635\u0635\u0647\u0645 \u0639\u0644\u064a\u0643 \u0644\u062d\u0643\u0645\u0629 \u0623\u0631\u062f\u0646\u0627\u0647\u0627. \u0648\u0643\u0644\u0645 \u0627\u0644\u0644\u0647 \u0645\u0648\u0633\u0649 \u062a\u0643\u0644\u064a\u0645\u064b\u0627\u061b \u062a\u0634\u0631\u064a\u0641\u064b\u0627 \u0644\u0647 \u0628\u0647\u0630\u0647 \u0627\u0644\u0635\u0641\u0629. \u0648\u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0629 \u0627\u0644\u0643\u0631\u064a\u0645\u0629\u060c \u0625\u062b\u0628\u0627\u062a \u0635\u0641\u0629 \u0627\u0644\u0643\u0644\u0627\u0645 \u0644\u0644\u0647 -\u062a\u0639\u0627\u0644\u0649- \u0643\u0645\u0627 \u064a\u0644\u064a\u0642 \u0628\u062c\u0644\u0627\u0644\u0647\u060c \u0648\u0623\u0646\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0643\u0644\u0645 \u0646\u0628\u064a\u0647 \u0645\u0648\u0633\u0649 -\u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645- \u062d\u0642\u064a\u0642\u0629 \u0628\u0644\u0627 \u0648\u0633\u0627\u0637\u0629.","4:165":"\u0623\u0631\u0633\u064e\u0644\u0652\u062a\u064f \u0631\u0633\u0644\u0627 \u0625\u0644\u0649 \u062e\u064e\u0644\u0652\u0642\u064a \u0645\u064f\u0628\u0634\u0651\u0650\u0631\u064a\u0646 \u0628\u062b\u0648\u0627\u0628\u064a\u060c \u0648\u0645\u0646\u0630\u0631\u064a\u0646 \u0628\u0639\u0642\u0627\u0628\u064a; \u0644\u0626\u0644\u0627 \u064a\u0643\u0648\u0646 \u0644\u0644\u0628\u0634\u0631 \u062d\u062c\u0629 \u064a\u0639\u062a\u0630\u0631\u0648\u0646 \u0628\u0647\u0627 \u0628\u0639\u062f \u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u0631\u0633\u0644. \u0648\u0643\u0627\u0646 \u0627\u0644\u0644\u0647 \u0639\u0632\u064a\u0632\u064b\u0627 \u0641\u064a \u0645\u0644\u0643\u0647\u060c \u062d\u0643\u064a\u0645\u064b\u0627 \u0641\u064a \u062a\u062f\u0628\u064a\u0631\u0647.","4:166":"\u0625\u0646 \u064a\u0643\u0641\u0631 \u0628\u0643 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u063a\u064a\u0631\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0641\u0627\u0644\u0644\u0647 \u064a\u0634\u0647\u062f \u0644\u0643 \u0628\u0623\u0646\u0643 \u0631\u0633\u0648\u0644\u0647 \u0627\u0644\u0630\u064a \u0623\u064e\u0646\u0652\u0632\u064e\u0644\u064e \u0639\u0644\u064a\u0647 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0639\u0638\u064a\u0645\u060c \u0623\u0646\u0632\u0644\u0647 \u0628\u0639\u0644\u0645\u0647\u060c \u0648\u0643\u0630\u0644\u0643 \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u064a\u0634\u0647\u062f\u0648\u0646 \u0628\u0635\u062f\u0642 \u0645\u0627 \u0623\u0648\u062d\u064a \u0625\u0644\u064a\u0643\u060c \u0648\u0634\u0647\u0627\u062f\u0629 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647\u0627 \u0643\u0627\u0641\u064a\u0629.","4:167":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u062c\u062d\u062f\u0648\u0627 \u0646\u064f\u0628\u064f\u0648\u0651\u064e\u062a\u0643\u060c \u0648\u0635\u062f\u0648\u0627 \u0627\u0644\u0646\u0627\u0633 \u0639\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0642\u062f \u0628\u064e\u0639\u064f\u062f\u0648\u0627 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u062d\u0642 \u0628\u064f\u0639\u0652\u062f\u064b\u0627 \u0634\u062f\u064a\u062f\u064b\u0627.","4:168":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0628\u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0638\u0644\u0645\u0648\u0627 \u0628\u0627\u0633\u062a\u0645\u0631\u0627\u0631\u0647\u0645 \u0639\u0644\u0649 \u0627\u0644\u0643\u0641\u0631\u060c \u0644\u0645 \u064a\u0643\u0646 \u0627\u0644\u0644\u0647 \u0644\u064a\u063a\u0641\u0631 \u0630\u0646\u0648\u0628\u0647\u0645\u060c \u0648\u0644\u0627 \u0644\u064a\u062f\u0644\u0647\u0645 \u0639\u0644\u0649 \u0637\u0631\u064a\u0642 \u064a\u0646\u062c\u064a\u0647\u0645.","4:169":"\u0625\u0644\u0627 \u0637\u0631\u064a\u0642 \u062c\u0647\u0646\u0645 \u0645\u0627\u0643\u062b\u064a\u0646 \u0641\u064a\u0647\u0627 \u0623\u0628\u062f\u064b\u0627\u060c \u0648\u0643\u0627\u0646 \u0630\u0644\u0643 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u064a\u0633\u064a\u0631\u064b\u0627\u060c \u0641\u0644\u0627 \u064a\u0639\u062c\u0632\u0647 \u0634\u064a\u0621.","4:170":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633 \u0642\u062f \u062c\u0627\u0621\u0643\u0645 \u0631\u0633\u0648\u0644\u0646\u0627 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0628\u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u062f\u064a\u0646 \u0627\u0644\u062d\u0642 \u0645\u0646 \u0631\u0628\u0643\u0645\u060c \u0641\u064e\u0635\u064e\u062f\u0651\u0650\u0642\u0648\u0647 \u0648\u0627\u062a\u0628\u0639\u0648\u0647\u060c \u0641\u0625\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0647 \u062e\u064a\u0631 \u0644\u0643\u0645\u060c \u0648\u0625\u0646 \u062a\u064f\u0635\u0631\u0651\u064f\u0648\u0627 \u0639\u0644\u0649 \u0643\u0641\u0631\u0643\u0645 \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u063a\u0646\u064a \u0639\u0646\u0643\u0645 \u0648\u0639\u0646 \u0625\u064a\u0645\u0627\u0646\u0643\u0645; \u0644\u0623\u0646\u0647 \u0645\u0627\u0644\u0643 \u0645\u0627 \u0641\u064a \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636. \u0648\u0643\u0627\u0646 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0645\u064b\u0627 \u0628\u0623\u0642\u0648\u0627\u0644\u0643\u0645 \u0648\u0623\u0641\u0639\u0627\u0644\u0643\u0645\u060c \u062d\u0643\u064a\u0645\u064b\u0627 \u0641\u064a \u062a\u0634\u0631\u064a\u0639\u0647 \u0648\u0623\u0645\u0631\u0647. \u0641\u0625\u0630\u0627 \u0643\u0627\u0646\u062a \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636 \u0642\u062f \u062e\u0636\u0639\u062a\u0627 \u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0643\u0648\u0646\u064b\u0627 \u0648\u0642\u062f\u0631\u064b\u0627 \u062e\u0636\u0648\u0639 \u0633\u0627\u0626\u0631 \u0645\u0644\u0643\u0647\u060c \u0641\u0623\u0648\u0644\u0649 \u0628\u0643\u0645 \u0623\u0646 \u062a\u0624\u0645\u0646\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0628\u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0628\u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0630\u064a \u0623\u0646\u0632\u0644\u0647 \u0639\u0644\u064a\u0647\u060c \u0648\u0623\u0646 \u062a\u0646\u0642\u0627\u062f\u0648\u0627 \u0644\u0630\u0644\u0643 \u0634\u0631\u0639\u064b\u0627 \u062d\u062a\u0649 \u064a\u0643\u0648\u0646 \u0627\u0644\u0643\u0648\u0646 \u0643\u0644\u0651\u064f\u0647 \u062e\u0627\u0636\u0639\u064b\u0627 \u0644\u0644\u0647 \u0642\u062f\u0631\u064b\u0627 \u0648\u0634\u0631\u0639\u064b\u0627. \u0648\u0641\u064a \u0627\u0644\u0622\u064a\u0629 \u062f\u0644\u064a\u0644 \u0639\u0644\u0649 \u0639\u0645\u0648\u0645 \u0631\u0633\u0627\u0644\u0629 \u0646\u0628\u064a \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645.","4:171":"\u064a\u0627 \u0623\u0647\u0644 \u0627\u0644\u0625\u0646\u062c\u064a\u0644 \u0644\u0627 \u062a\u062a\u062c\u0627\u0648\u0632\u0648\u0627 \u0627\u0644\u0627\u0639\u062a\u0642\u0627\u062f \u0627\u0644\u062d\u0642 \u0641\u064a \u062f\u064a\u0646\u0643\u0645\u060c \u0648\u0644\u0627 \u062a\u0642\u0648\u0644\u0648\u0627 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u062d\u0642\u060c \u0641\u0644\u0627 \u062a\u062c\u0639\u0644\u0648\u0627 \u0644\u0647 \u0635\u0627\u062d\u0628\u0629\u064b \u0648\u0644\u0627 \u0648\u0644\u062f\u064b\u0627. \u0625\u0646\u0645\u0627 \u0627\u0644\u0645\u0633\u064a\u062d \u0639\u064a\u0633\u0649 \u0627\u0628\u0646 \u0645\u0631\u064a\u0645 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0623\u0631\u0633\u0644\u0647 \u0627\u0644\u0644\u0647 \u0628\u0627\u0644\u062d\u0642\u060c \u0648\u062e\u064e\u0644\u064e\u0642\u064e\u0647 \u0628\u0627\u0644\u0643\u0644\u0645\u0629 \u0627\u0644\u062a\u064a \u0623\u0631\u0633\u0644 \u0628\u0647\u0627 \u062c\u0628\u0631\u064a\u0644 \u0625\u0644\u0649 \u0645\u0631\u064a\u0645\u060c \u0648\u0647\u064a \u0642\u0648\u0644\u0647: \xab\u0643\u0646\xbb \u060c \u0641\u0643\u0627\u0646\u060c \u0648\u0647\u064a \u0646\u0641\u062e\u0629 \u0645\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0646\u0641\u062e\u0647\u0627 \u062c\u0628\u0631\u064a\u0644 \u0628\u0623\u0645\u0631 \u0631\u0628\u0647\u060c \u0641\u064e\u0635\u062f\u0651\u0650\u0642\u0648\u0627 \u0628\u0623\u0646 \u0627\u0644\u0644\u0647 \u0648\u0627\u062d\u062f \u0648\u0623\u0633\u0644\u0645\u0648\u0627 \u0644\u0647\u060c \u0648\u0635\u062f\u0651\u0650\u0642\u0648\u0627 \u0631\u0633\u0644\u0647 \u0641\u064a\u0645\u0627 \u062c\u0627\u0624\u0648\u0643\u0645 \u0628\u0647 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0648\u0627\u0639\u0645\u0644\u0648\u0627 \u0628\u0647\u060c \u0648\u0644\u0627 \u062a\u062c\u0639\u0644\u0648\u0627 \u0639\u064a\u0633\u0649 \u0648\u0623\u0645\u0647 \u0645\u0639 \u0627\u0644\u0644\u0647 \u0634\u0631\u064a\u0643\u064a\u0646. \u0627\u0646\u062a\u0647\u0648\u0627 \u0639\u0646 \u0647\u0630\u0647 \u0627\u0644\u0645\u0642\u0627\u0644\u0629 \u062e\u064a\u0631\u064b\u0627 \u0644\u0643\u0645 \u0645\u0645\u0627 \u0623\u0646\u062a\u0645 \u0639\u0644\u064a\u0647\u060c \u0625\u0646\u0645\u0627 \u0627\u0644\u0644\u0647 \u0625\u0644\u0647 \u0648\u0627\u062d\u062f \u0633\u0628\u062d\u0627\u0646\u0647. \u0645\u0627 \u0641\u064a \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636 \u0645\u064f\u0644\u0652\u0643\u064f\u0647\u060c \u0641\u0643\u064a\u0641 \u064a\u0643\u0648\u0646 \u0644\u0647 \u0645\u0646\u0647\u0645 \u0635\u0627\u062d\u0628\u0629 \u0623\u0648 \u0648\u0644\u062f\u061f \u0648\u0643\u0641\u0649 \u0628\u0627\u0644\u0644\u0647 \u0648\u0643\u064a\u0644\u0627 \u0639\u0644\u0649 \u062a\u062f\u0628\u064a\u0631 \u062e\u0644\u0642\u0647 \u0648\u062a\u0635\u0631\u064a\u0641 \u0645\u0639\u0627\u0634\u0647\u0645\u060c \u0641\u062a\u0648\u0643\u0651\u064e\u0644\u0648\u0627 \u0639\u0644\u064a\u0647 \u0648\u062d\u062f\u0647 \u0641\u0647\u0648 \u0643\u0627\u0641\u064a\u0643\u0645.","4:172":"\u0644\u0646 \u064a\u064e\u0623\u0652\u0646\u0641 \u0648\u0644\u0646 \u064a\u0645\u062a\u0646\u0639 \u0627\u0644\u0645\u0633\u064a\u062d \u0623\u0646 \u064a\u0643\u0648\u0646 \u0639\u0628\u062f\u064b\u0627 \u0644\u0644\u0647\u060c \u0648\u0643\u0630\u0644\u0643 \u0644\u0646 \u064a\u0623\u0646\u064e\u0641\u064e \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u0627\u0644\u0645\u064f\u0642\u064e\u0631\u0651\u064e\u0628\u0648\u0646 \u0645\u0646 \u0627\u0644\u0625\u0642\u0631\u0627\u0631 \u0628\u0627\u0644\u0639\u0628\u0648\u062f\u064a\u0629 \u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649. \u0648\u0645\u0646 \u064a\u0623\u0646\u0641 \u0639\u0646 \u0627\u0644\u0627\u0646\u0642\u064a\u0627\u062f \u0648\u0627\u0644\u062e\u0636\u0648\u0639 \u0648\u064a\u0633\u062a\u0643\u0628\u0631 \u0641\u0633\u064a\u062d\u0634\u0631\u0647\u0645 \u0643\u0644\u0647\u0645 \u0625\u0644\u064a\u0647 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u0648\u064a\u0641\u0635\u0644\u064f \u0628\u064a\u0646\u0647\u0645 \u0628\u062d\u0643\u0645\u0647 \u0627\u0644\u0639\u0627\u062f\u0644\u060c \u0648\u064a\u062c\u0627\u0632\u064a \u0643\u0644\u0627 \u0628\u0645\u0627 \u064a\u0633\u062a\u062d\u0642.","4:173":"\u0641\u0623\u0645\u0651\u064e\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u064e\u062f\u0651\u064e\u0642\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0627\u0639\u062a\u0642\u0627\u062f\u064b\u0627 \u0648\u0642\u0648\u0644\u0627 \u0648\u0639\u0645\u0644\u0627 \u0648\u0627\u0633\u062a\u0642\u0627\u0645\u0648\u0627 \u0639\u0644\u0649 \u0634\u0631\u064a\u0639\u062a\u0647 \u0641\u064a\u0648\u0641\u064a\u0647\u0645 \u062b\u0648\u0627\u0628 \u0623\u0639\u0645\u0627\u0644\u0647\u0645\u060c \u0648\u064a\u0632\u064a\u062f\u064f\u0647\u0645 \u0645\u0646 \u0641\u0636\u0644\u0647\u060c \u0648\u0623\u0645\u0627 \u0627\u0644\u0630\u064a\u0646 \u0627\u0645\u062a\u0646\u0639\u0648\u0627 \u0639\u0646 \u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u0633\u062a\u0643\u0628\u0631\u0648\u0627 \u0639\u0646 \u0627\u0644\u062a\u0630\u0644\u0644 \u0644\u0647 \u0641\u064a\u0639\u0630\u0628\u0647\u0645 \u0639\u0630\u0627\u0628\u064b\u0627 \u0645\u0648\u062c\u0639\u064b\u0627\u060c \u0648\u0644\u0627 \u064a\u062c\u062f\u0648\u0646 \u0644\u0647\u0645 \u0648\u0644\u064a\u0651\u064b\u0627 \u064a\u0646\u062c\u064a\u0647\u0645 \u0645\u0646 \u0639\u0630\u0627\u0628\u0647\u060c \u0648\u0644\u0627 \u0646\u0627\u0635\u0631\u064b\u0627 \u064a\u0646\u0635\u0631\u0647\u0645 \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647.","4:174":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633 \u0642\u062f \u062c\u0627\u0621\u0643\u0645 \u0628\u0631\u0647\u0627\u0646 \u0645\u0646 \u0631\u0628\u0643\u0645\u060c \u0648\u0647\u0648 \u0631\u0633\u0648\u0644\u0646\u0627 \u0645\u062d\u0645\u062f\u060c \u0648\u0645\u0627 \u062c\u0627\u0621 \u0628\u0647 \u0645\u0646 \u0627\u0644\u0628\u064a\u0646\u0627\u062a \u0648\u0627\u0644\u062d\u062c\u062c \u0627\u0644\u0642\u0627\u0637\u0639\u0629\u060c \u0648\u0623\u0639\u0638\u0645\u0647\u0627 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064a\u0645\u060c \u0645\u0645\u0627 \u064a\u0634\u0647\u062f \u0628\u0635\u062f\u0642 \u0646\u0628\u0648\u062a\u0647 \u0648\u0631\u0633\u0627\u0644\u062a\u0647 \u0627\u0644\u062e\u0627\u062a\u0645\u0629\u060c \u0648\u0623\u0646\u0632\u0644\u0646\u0627 \u0625\u0644\u064a\u0643\u0645 \u0627\u0644\u0642\u0631\u0622\u0646 \u0647\u062f\u064b\u0649 \u0648\u0646\u0648\u0631\u064b\u0627 \u0645\u0628\u064a\u0646\u064b\u0627.","4:175":"\u0641\u0623\u0645\u0651\u064e\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0627\u0639\u062a\u0642\u0627\u062f\u064b\u0627 \u0648\u0642\u0648\u0644\u0627 \u0648\u0639\u0645\u0644\u0627 \u0648\u0627\u0633\u062a\u0645\u0633\u0643\u0648\u0627 \u0628\u0627\u0644\u0646\u0648\u0631 \u0627\u0644\u0630\u064a \u0623\u064f\u0646\u0632\u0644 \u0625\u0644\u064a\u0647\u0645\u060c \u0641\u0633\u064a\u062f\u062e\u0644\u0647\u0645 \u0627\u0644\u062c\u0646\u0629 \u0631\u062d\u0645\u0629 \u0645\u0646\u0647 \u0648\u0641\u0636\u0644\u0627 \u0648\u064a\u0648\u0641\u0642\u0647\u0645 \u0625\u0644\u0649 \u0633\u0644\u0648\u0643 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645 \u0627\u0644\u0645\u0641\u0636\u064a \u0625\u0644\u0649 \u0631\u0648\u0636\u0627\u062a \u0627\u0644\u062c\u0646\u0627\u062a.","4:176":"\u064a\u0633\u0623\u0644\u0648\u0646\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0639\u0646 \u062d\u0643\u0645 \u0645\u064a\u0631\u0627\u062b \u0627\u0644\u0643\u0644\u0627\u0644\u0629\u060c \u0648\u0647\u0648 \u0645\u0646 \u0645\u0627\u062a \u0648\u0644\u064a\u0633 \u0644\u0647 \u0648\u0644\u062f\u064c \u0648\u0644\u0627 \u0648\u0627\u0644\u062f\u060c \u0642\u0644: \u0627\u0644\u0644\u0647 \u064a\u064f\u0628\u064a\u0651\u0650\u0646 \u0644\u0643\u0645 \u0627\u0644\u062d\u0643\u0645 \u0641\u064a\u0647\u0627: \u0625\u0646 \u0645\u0627\u062a \u0627\u0645\u0631\u0624 \u0644\u064a\u0633 \u0644\u0647 \u0648\u0644\u062f \u0648\u0644\u0627 \u0648\u0627\u0644\u062f\u060c \u0648\u0644\u0647 \u0623\u062e\u062a \u0644\u0623\u0628\u064a\u0647 \u0648\u0623\u0645\u0647\u060c \u0623\u0648 \u0644\u0623\u0628\u064a\u0647 \u0641\u0642\u0637\u060c \u0641\u0644\u0647\u0627 \u0646\u0635\u0641 \u062a\u0631\u0643\u062a\u0647\u060c \u0648\u064a\u0631\u062b \u0623\u062e\u0648\u0647\u0627 \u0634\u0642\u064a\u0642\u064b\u0627 \u0643\u0627\u0646 \u0623\u0648 \u0644\u0623\u0628 \u062c\u0645\u064a\u0639 \u0645\u0627\u0644\u0647\u0627 \u0625\u0630\u0627 \u0645\u0627\u062a\u062a \u0648\u0644\u064a\u0633 \u0644\u0647\u0627 \u0648\u0644\u062f \u0648\u0644\u0627 \u0648\u0627\u0644\u062f. \u0641\u0625\u0646 \u0643\u0627\u0646 \u0644\u0645\u0646 \u0645\u0627\u062a \u0643\u0644\u0627\u0644\u0629\u064b \u0623\u062e\u062a\u0627\u0646 \u0641\u0644\u0647\u0645\u0627 \u0627\u0644\u062b\u0644\u062b\u0627\u0646 \u0645\u0645\u0627 \u062a\u0631\u0643. \u0648\u0625\u0630\u0627 \u0627\u062c\u062a\u0645\u0639 \u0627\u0644\u0630\u0643\u0648\u0631 \u0645\u0646 \u0627\u0644\u0625\u062e\u0648\u0629 \u0644\u063a\u064a\u0631 \u0623\u0645 \u0645\u0639 \u0627\u0644\u0625\u0646\u0627\u062b \u0641\u0644\u0644\u0630\u0643\u0631 \u0645\u062b\u0644 \u0646\u0635\u064a\u0628 \u0627\u0644\u0623\u0646\u062b\u064a\u064a\u0646 \u0645\u0646 \u0623\u062e\u0648\u0627\u062a\u0647. \u064a\u064f\u0628\u064a\u0651\u0650\u0646 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0642\u0633\u0645\u0629 \u0627\u0644\u0645\u0648\u0627\u0631\u064a\u062b \u0648\u062d\u0643\u0645 \u0627\u0644\u0643\u0644\u0627\u0644\u0629\u060c \u0644\u0626\u0644\u0627 \u062a\u0636\u0644\u0648\u0627 \u0639\u0646 \u0627\u0644\u062d\u0642\u0651\u0650 \u0641\u064a \u0623\u0645\u0631 \u0627\u0644\u0645\u0648\u0627\u0631\u064a\u062b. \u0648\u0627\u0644\u0644\u0647 \u0639\u0627\u0644\u0645 \u0628\u0639\u0648\u0627\u0642\u0628 \u0627\u0644\u0623\u0645\u0648\u0631\u060c \u0648\u0645\u0627 \u0641\u064a\u0647\u0627 \u0645\u0646 \u0627\u0644\u062e\u064a\u0631 \u0644\u0639\u0628\u0627\u062f\u0647."}},883,[]);